INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 1, 'Unknown', 41, 25, 'And Joseph said unto Pharaoh, The dream of Pharaoh {is} one: God hath shewed Pharaoh what he {is} about to do.', 'and joseph said unto pharaoh the dream of pharaoh is one god hath shewed pharaoh what he is about to do');
