INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 1, 'Unknown', 41, 44, 'And Pharaoh said unto Joseph, I {am} Pharaoh, and without thee shall no man lift up his hand or foot in all the land of Egypt.', 'and pharaoh said unto joseph i am pharaoh and without thee shall no man lift up his hand or foot in all the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 1, 'Unknown', 41, 45, 'And Pharaoh called Joseph''s name Zaphnathpaaneah; and he gave him to wife Asenath the daughter of Potipherah priest of On. And Joseph went out over {all} the land of Egypt. {Zaphnathpaaneah: which in the Coptic signifies, A revealer of secrets, or, The man to whom secrets are revealed} {priest: or, prince}', 'and pharaoh called joseph s name zaphnathpaaneah and he gave him to wife asenath the daughter of potipherah priest of on and joseph went out over all the land of egypt zaphnathpaaneah which in the coptic signifies a revealer of secrets or the man to whom secrets are revealed priest or prince');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 1, 'Unknown', 41, 46, 'And Joseph {was} thirty years old when he stood before Pharaoh king of Egypt. And Joseph went out from the presence of Pharaoh, and went throughout all the land of Egypt.', 'and joseph was thirty years old when he stood before pharaoh king of egypt and joseph went out from the presence of pharaoh and went throughout all the land of egypt');
