INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 3, 'And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid {it} in the flags by the river''s brink.', 'and when she could not longer hide him she took for him an ark of bulrushes and daubed it with slime and with pitch and put the child therein and she laid it in the flags by the river s brink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 4, 'And his sister stood afar off, to wit what would be done to him.', 'and his sister stood afar off to wit what would be done to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 5, 'And the daughter of Pharaoh came down to wash {herself} at the river; and her maidens walked along by the river''s side; and when she saw the ark among the flags, she sent her maid to fetch it.', 'and the daughter of pharaoh came down to wash herself at the river and her maidens walked along by the river s side and when she saw the ark among the flags she sent her maid to fetch it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 6, 'And when she had opened {it}, she saw the child: and, behold, the babe wept. And she had compassion on him, and said, This {is one} of the Hebrews'' children.', 'and when she had opened it she saw the child and behold the babe wept and she had compassion on him and said this is one of the hebrews children');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 7, 'Then said his sister to Pharaoh''s daughter, Shall I go and call to thee a nurse of the Hebrew women, that she may nurse the child for thee?', 'then said his sister to pharaoh s daughter shall i go and call to thee a nurse of the hebrew women that she may nurse the child for thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 8, 'And Pharaoh''s daughter said to her, Go. And the maid went and called the child''s mother.', 'and pharaoh s daughter said to her go and the maid went and called the child s mother');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 9, 'And Pharaoh''s daughter said unto her, Take this child away, and nurse it for me, and I will give {thee} thy wages. And the woman took the child, and nursed it.', 'and pharaoh s daughter said unto her take this child away and nurse it for me and i will give thee thy wages and the woman took the child and nursed it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 10, 'And the child grew, and she brought him unto Pharaoh''s daughter, and he became her son. And she called his name Moses: and she said, Because I drew him out of the water. {Moses: that is, Drawn out}', 'and the child grew and she brought him unto pharaoh s daughter and he became her son and she called his name moses and she said because i drew him out of the water moses that is drawn out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 11, 'And it came to pass in those days, when Moses was grown, that he went out unto his brethren, and looked on their burdens: and he spied an Egyptian smiting an Hebrew, one of his brethren.', 'and it came to pass in those days when moses was grown that he went out unto his brethren and looked on their burdens and he spied an egyptian smiting an hebrew one of his brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 12, 'And he looked this way and that way, and when he saw that {there was} no man, he slew the Egyptian, and hid him in the sand.', 'and he looked this way and that way and when he saw that there was no man he slew the egyptian and hid him in the sand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 13, 'And when he went out the second day, behold, two men of the Hebrews strove together: and he said to him that did the wrong, Wherefore smitest thou thy fellow?', 'and when he went out the second day behold two men of the hebrews strove together and he said to him that did the wrong wherefore smitest thou thy fellow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 14, 'And he said, Who made thee a prince and a judge over us? intendest thou to kill me, as thou killedst the Egyptian? And Moses feared, and said, Surely this thing is known. {a prince: Heb. a man, a prince}', 'and he said who made thee a prince and a judge over us intendest thou to kill me as thou killedst the egyptian and moses feared and said surely this thing is known a prince heb a man a prince');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 15, 'Now when Pharaoh heard this thing, he sought to slay Moses. But Moses fled from the face of Pharaoh, and dwelt in the land of Midian: and he sat down by a well.', 'now when pharaoh heard this thing he sought to slay moses but moses fled from the face of pharaoh and dwelt in the land of midian and he sat down by a well');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 16, 'Now the priest of Midian had seven daughters: and they came and drew {water}, and filled the troughs to water their father''s flock. {priest: or, prince}', 'now the priest of midian had seven daughters and they came and drew water and filled the troughs to water their father s flock priest or prince');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 17, 'And the shepherds came and drove them away: but Moses stood up and helped them, and watered their flock.', 'and the shepherds came and drove them away but moses stood up and helped them and watered their flock');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 18, 'And when they came to Reuel their father, he said, How {is it that} ye are come so soon to day? {Reuel: called also Jethro, or, Jether}', 'and when they came to reuel their father he said how is it that ye are come so soon to day reuel called also jethro or jether');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 19, 'And they said, An Egyptian delivered us out of the hand of the shepherds, and also drew {water} enough for us, and watered the flock.', 'and they said an egyptian delivered us out of the hand of the shepherds and also drew water enough for us and watered the flock');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 20, 'And he said unto his daughters, And where {is} he? why {is} it {that} ye have left the man? call him, that he may eat bread.', 'and he said unto his daughters and where is he why is it that ye have left the man call him that he may eat bread');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 21, 'And Moses was content to dwell with the man: and he gave Moses Zipporah his daughter.', 'and moses was content to dwell with the man and he gave moses zipporah his daughter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 22, 'And she bare {him} a son, and he called his name Gershom: for he said, I have been a stranger in a strange land. {Gershom: that is, A stranger here}', 'and she bare him a son and he called his name gershom for he said i have been a stranger in a strange land gershom that is a stranger here');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 23, 'And it came to pass in process of time, that the king of Egypt died: and the children of Israel sighed by reason of the bondage, and they cried, and their cry came up unto God by reason of the bondage.', 'and it came to pass in process of time that the king of egypt died and the children of israel sighed by reason of the bondage and they cried and their cry came up unto god by reason of the bondage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 24, 'And God heard their groaning, and God remembered his covenant with Abraham, with Isaac, and with Jacob.', 'and god heard their groaning and god remembered his covenant with abraham with isaac and with jacob');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 2, 25, 'And God looked upon the children of Israel, and God had respect unto {them}. {had...: Heb. knew}', 'and god looked upon the children of israel and god had respect unto them had heb knew');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 1, 'Now Moses kept the flock of Jethro his father in law, the priest of Midian: and he led the flock to the backside of the desert, and came to the mountain of God, {even} to Horeb.', 'now moses kept the flock of jethro his father in law the priest of midian and he led the flock to the backside of the desert and came to the mountain of god even to horeb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 2, 'And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush {was} not consumed.', 'and the angel of the lord appeared unto him in a flame of fire out of the midst of a bush and he looked and behold the bush burned with fire and the bush was not consumed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 3, 'And Moses said, I will now turn aside, and see this great sight, why the bush is not burnt.', 'and moses said i will now turn aside and see this great sight why the bush is not burnt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 4, 'And when the LORD saw that he turned aside to see, God called unto him out of the midst of the bush, and said, Moses, Moses. And he said, Here {am} I.', 'and when the lord saw that he turned aside to see god called unto him out of the midst of the bush and said moses moses and he said here am i');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 5, 'And he said, Draw not nigh hither: put off thy shoes from off thy feet, for the place whereon thou standest {is} holy ground.', 'and he said draw not nigh hither put off thy shoes from off thy feet for the place whereon thou standest is holy ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 6, 'Moreover he said, I {am} the God of thy father, the God of Abraham, the God of Isaac, and the God of Jacob. And Moses hid his face; for he was afraid to look upon God.', 'moreover he said i am the god of thy father the god of abraham the god of isaac and the god of jacob and moses hid his face for he was afraid to look upon god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 7, 'And the LORD said, I have surely seen the affliction of my people which {are} in Egypt, and have heard their cry by reason of their taskmasters; for I know their sorrows;', 'and the lord said i have surely seen the affliction of my people which are in egypt and have heard their cry by reason of their taskmasters for i know their sorrows');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 8, 'And I am come down to deliver them out of the hand of the Egyptians, and to bring them up out of that land unto a good land and a large, unto a land flowing with milk and honey; unto the place of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites.', 'and i am come down to deliver them out of the hand of the egyptians and to bring them up out of that land unto a good land and a large unto a land flowing with milk and honey unto the place of the canaanites and the hittites and the amorites and the perizzites and the hivites and the jebusites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 9, 'Now therefore, behold, the cry of the children of Israel is come unto me: and I have also seen the oppression wherewith the Egyptians oppress them.', 'now therefore behold the cry of the children of israel is come unto me and i have also seen the oppression wherewith the egyptians oppress them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 10, 'Come now therefore, and I will send thee unto Pharaoh, that thou mayest bring forth my people the children of Israel out of Egypt.', 'come now therefore and i will send thee unto pharaoh that thou mayest bring forth my people the children of israel out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 11, 'And Moses said unto God, Who {am} I, that I should go unto Pharaoh, and that I should bring forth the children of Israel out of Egypt?', 'and moses said unto god who am i that i should go unto pharaoh and that i should bring forth the children of israel out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 12, 'And he said, Certainly I will be with thee; and this {shall be} a token unto thee, that I have sent thee: When thou hast brought forth the people out of Egypt, ye shall serve God upon this mountain.', 'and he said certainly i will be with thee and this shall be a token unto thee that i have sent thee when thou hast brought forth the people out of egypt ye shall serve god upon this mountain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 13, 'And Moses said unto God, Behold, {when} I come unto the children of Israel, and shall say unto them, The God of your fathers hath sent me unto you; and they shall say to me, What {is} his name? what shall I say unto them?', 'and moses said unto god behold when i come unto the children of israel and shall say unto them the god of your fathers hath sent me unto you and they shall say to me what is his name what shall i say unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 14, 'And God said unto Moses, I AM THAT I AM: and he said, Thus shalt thou say unto the children of Israel, I AM hath sent me unto you.', 'and god said unto moses i am that i am and he said thus shalt thou say unto the children of israel i am hath sent me unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 15, 'And God said moreover unto Moses, Thus shalt thou say unto the children of Israel, The LORD God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob, hath sent me unto you: this {is} my name for ever, and this {is} my memorial unto all generations.', 'and god said moreover unto moses thus shalt thou say unto the children of israel the lord god of your fathers the god of abraham the god of isaac and the god of jacob hath sent me unto you this is my name for ever and this is my memorial unto all generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 16, 'Go, and gather the elders of Israel together, and say unto them, The LORD God of your fathers, the God of Abraham, of Isaac, and of Jacob, appeared unto me, saying, I have surely visited you, and {seen} that which is done to you in Egypt:', 'go and gather the elders of israel together and say unto them the lord god of your fathers the god of abraham of isaac and of jacob appeared unto me saying i have surely visited you and seen that which is done to you in egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 17, 'And I have said, I will bring you up out of the affliction of Egypt unto the land of the Canaanites, and the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites, unto a land flowing with milk and honey.', 'and i have said i will bring you up out of the affliction of egypt unto the land of the canaanites and the hittites and the amorites and the perizzites and the hivites and the jebusites unto a land flowing with milk and honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 18, 'And they shall hearken to thy voice: and thou shalt come, thou and the elders of Israel, unto the king of Egypt, and ye shall say unto him, The LORD God of the Hebrews hath met with us: and now let us go, we beseech thee, three days'' journey into the wilderness, that we may sacrifice to the LORD our God.', 'and they shall hearken to thy voice and thou shalt come thou and the elders of israel unto the king of egypt and ye shall say unto him the lord god of the hebrews hath met with us and now let us go we beseech thee three days journey into the wilderness that we may sacrifice to the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 19, 'And I am sure that the king of Egypt will not let you go, no, not by a mighty hand. {no...: or, but by strong hand}', 'and i am sure that the king of egypt will not let you go no not by a mighty hand no or but by strong hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 20, 'And I will stretch out my hand, and smite Egypt with all my wonders which I will do in the midst thereof: and after that he will let you go.', 'and i will stretch out my hand and smite egypt with all my wonders which i will do in the midst thereof and after that he will let you go');
