INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 3, 22, 'But every woman shall borrow of her neighbour, and of her that sojourneth in her house, jewels of silver, and jewels of gold, and raiment: and ye shall put {them} upon your sons, and upon your daughters; and ye shall spoil the Egyptians. {the Egyptians: or, Egypt}', 'but every woman shall borrow of her neighbour and of her that sojourneth in her house jewels of silver and jewels of gold and raiment and ye shall put them upon your sons and upon your daughters and ye shall spoil the egyptians the egyptians or egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 1, 'And Moses answered and said, But, behold, they will not believe me, nor hearken unto my voice: for they will say, The LORD hath not appeared unto thee.', 'and moses answered and said but behold they will not believe me nor hearken unto my voice for they will say the lord hath not appeared unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 2, 'And the LORD said unto him, What {is} that in thine hand? And he said, A rod.', 'and the lord said unto him what is that in thine hand and he said a rod');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 3, 'And he said, Cast it on the ground. And he cast it on the ground, and it became a serpent; and Moses fled from before it.', 'and he said cast it on the ground and he cast it on the ground and it became a serpent and moses fled from before it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 4, 'And the LORD said unto Moses, Put forth thine hand, and take it by the tail. And he put forth his hand, and caught it, and it became a rod in his hand:', 'and the lord said unto moses put forth thine hand and take it by the tail and he put forth his hand and caught it and it became a rod in his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 5, 'That they may believe that the LORD God of their fathers, the God of Abraham, the God of Isaac, and the God of Jacob, hath appeared unto thee.', 'that they may believe that the lord god of their fathers the god of abraham the god of isaac and the god of jacob hath appeared unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 6, 'And the LORD said furthermore unto him, Put now thine hand into thy bosom. And he put his hand into his bosom: and when he took it out, behold, his hand {was} leprous as snow.', 'and the lord said furthermore unto him put now thine hand into thy bosom and he put his hand into his bosom and when he took it out behold his hand was leprous as snow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 7, 'And he said, Put thine hand into thy bosom again. And he put his hand into his bosom again; and plucked it out of his bosom, and, behold, it was turned again as his {other} flesh.', 'and he said put thine hand into thy bosom again and he put his hand into his bosom again and plucked it out of his bosom and behold it was turned again as his other flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 4, 8, 'And it shall come to pass, if they will not believe thee, neither hearken to the voice of the first sign, that they will believe the voice of the latter sign.', 'and it shall come to pass if they will not believe thee neither hearken to the voice of the first sign that they will believe the voice of the latter sign');
