INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 23, 'And Aaron took him Elisheba, daughter of Amminadab, sister of Naashon, to wife; and she bare him Nadab, and Abihu, Eleazar, and Ithamar.', 'and aaron took him elisheba daughter of amminadab sister of naashon to wife and she bare him nadab and abihu eleazar and ithamar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 24, 'And the sons of Korah; Assir, and Elkanah, and Abiasaph: these {are} the families of the Korhites.', 'and the sons of korah assir and elkanah and abiasaph these are the families of the korhites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 25, 'And Eleazar Aaron''s son took him {one} of the daughters of Putiel to wife; and she bare him Phinehas: these {are} the heads of the fathers of the Levites according to their families.', 'and eleazar aaron s son took him one of the daughters of putiel to wife and she bare him phinehas these are the heads of the fathers of the levites according to their families');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 26, 'These {are} that Aaron and Moses, to whom the LORD said, Bring out the children of Israel from the land of Egypt according to their armies.', 'these are that aaron and moses to whom the lord said bring out the children of israel from the land of egypt according to their armies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 27, 'These {are} they which spake to Pharaoh king of Egypt, to bring out the children of Israel from Egypt: these {are} that Moses and Aaron.', 'these are they which spake to pharaoh king of egypt to bring out the children of israel from egypt these are that moses and aaron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 28, 'And it came to pass on the day {when} the LORD spake unto Moses in the land of Egypt,', 'and it came to pass on the day when the lord spake unto moses in the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 29, 'That the LORD spake unto Moses, saying, I {am} the LORD: speak thou unto Pharaoh king of Egypt all that I say unto thee.', 'that the lord spake unto moses saying i am the lord speak thou unto pharaoh king of egypt all that i say unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 6, 30, 'And Moses said before the LORD, Behold, I {am} of uncircumcised lips, and how shall Pharaoh hearken unto me?', 'and moses said before the lord behold i am of uncircumcised lips and how shall pharaoh hearken unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 1, 'And the LORD said unto Moses, See, I have made thee a god to Pharaoh: and Aaron thy brother shall be thy prophet.', 'and the lord said unto moses see i have made thee a god to pharaoh and aaron thy brother shall be thy prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 2, 'Thou shalt speak all that I command thee: and Aaron thy brother shall speak unto Pharaoh, that he send the children of Israel out of his land.', 'thou shalt speak all that i command thee and aaron thy brother shall speak unto pharaoh that he send the children of israel out of his land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 3, 'And I will harden Pharaoh''s heart, and multiply my signs and my wonders in the land of Egypt.', 'and i will harden pharaoh s heart and multiply my signs and my wonders in the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 4, 'But Pharaoh shall not hearken unto you, that I may lay my hand upon Egypt, and bring forth mine armies, {and} my people the children of Israel, out of the land of Egypt by great judgments.', 'but pharaoh shall not hearken unto you that i may lay my hand upon egypt and bring forth mine armies and my people the children of israel out of the land of egypt by great judgments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 5, 'And the Egyptians shall know that I {am} the LORD, when I stretch forth mine hand upon Egypt, and bring out the children of Israel from among them.', 'and the egyptians shall know that i am the lord when i stretch forth mine hand upon egypt and bring out the children of israel from among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 6, 'And Moses and Aaron did as the LORD commanded them, so did they.', 'and moses and aaron did as the lord commanded them so did they');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 7, 'And Moses {was} fourscore years old, and Aaron fourscore and three years old, when they spake unto Pharaoh.', 'and moses was fourscore years old and aaron fourscore and three years old when they spake unto pharaoh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 8, 'And the LORD spake unto Moses and unto Aaron, saying,', 'and the lord spake unto moses and unto aaron saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 9, 'When Pharaoh shall speak unto you, saying, Shew a miracle for you: then thou shalt say unto Aaron, Take thy rod, and cast {it} before Pharaoh, {and} it shall become a serpent.', 'when pharaoh shall speak unto you saying shew a miracle for you then thou shalt say unto aaron take thy rod and cast it before pharaoh and it shall become a serpent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 10, 'And Moses and Aaron went in unto Pharaoh, and they did so as the LORD had commanded: and Aaron cast down his rod before Pharaoh, and before his servants, and it became a serpent.', 'and moses and aaron went in unto pharaoh and they did so as the lord had commanded and aaron cast down his rod before pharaoh and before his servants and it became a serpent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 11, 'Then Pharaoh also called the wise men and the sorcerers: now the magicians of Egypt, they also did in like manner with their enchantments.', 'then pharaoh also called the wise men and the sorcerers now the magicians of egypt they also did in like manner with their enchantments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 12, 'For they cast down every man his rod, and they became serpents: but Aaron''s rod swallowed up their rods.', 'for they cast down every man his rod and they became serpents but aaron s rod swallowed up their rods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 13, 'And he hardened Pharaoh''s heart, that he hearkened not unto them; as the LORD had said.', 'and he hardened pharaoh s heart that he hearkened not unto them as the lord had said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 14, 'And the LORD said unto Moses, Pharaoh''s heart {is} hardened, he refuseth to let the people go.', 'and the lord said unto moses pharaoh s heart is hardened he refuseth to let the people go');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 15, 'Get thee unto Pharaoh in the morning; lo, he goeth out unto the water; and thou shalt stand by the river''s brink against he come; and the rod which was turned to a serpent shalt thou take in thine hand.', 'get thee unto pharaoh in the morning lo he goeth out unto the water and thou shalt stand by the river s brink against he come and the rod which was turned to a serpent shalt thou take in thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 16, 'And thou shalt say unto him, The LORD God of the Hebrews hath sent me unto thee, saying, Let my people go, that they may serve me in the wilderness: and, behold, hitherto thou wouldest not hear.', 'and thou shalt say unto him the lord god of the hebrews hath sent me unto thee saying let my people go that they may serve me in the wilderness and behold hitherto thou wouldest not hear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 17, 'Thus saith the LORD, In this thou shalt know that I {am} the LORD: behold, I will smite with the rod that {is} in mine hand upon the waters which {are} in the river, and they shall be turned to blood.', 'thus saith the lord in this thou shalt know that i am the lord behold i will smite with the rod that is in mine hand upon the waters which are in the river and they shall be turned to blood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 18, 'And the fish that {is} in the river shall die, and the river shall stink; and the Egyptians shall lothe to drink of the water of the river.', 'and the fish that is in the river shall die and the river shall stink and the egyptians shall lothe to drink of the water of the river');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 19, 'And the LORD spake unto Moses, Say unto Aaron, Take thy rod, and stretch out thine hand upon the waters of Egypt, upon their streams, upon their rivers, and upon their ponds, and upon all their pools of water, that they may become blood; and {that} there may be blood throughout all the land of Egypt, both in {vessels of} wood, and in {vessels of} stone. {pools...: Heb. gathering of their waters}', 'and the lord spake unto moses say unto aaron take thy rod and stretch out thine hand upon the waters of egypt upon their streams upon their rivers and upon their ponds and upon all their pools of water that they may become blood and that there may be blood throughout all the land of egypt both in vessels of wood and in vessels of stone pools heb gathering of their waters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 20, 'And Moses and Aaron did so, as the LORD commanded; and he lifted up the rod, and smote the waters that {were} in the river, in the sight of Pharaoh, and in the sight of his servants; and all the waters that {were} in the river were turned to blood.', 'and moses and aaron did so as the lord commanded and he lifted up the rod and smote the waters that were in the river in the sight of pharaoh and in the sight of his servants and all the waters that were in the river were turned to blood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 21, 'And the fish that {was} in the river died; and the river stank, and the Egyptians could not drink of the water of the river; and there was blood throughout all the land of Egypt.', 'and the fish that was in the river died and the river stank and the egyptians could not drink of the water of the river and there was blood throughout all the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 22, 'And the magicians of Egypt did so with their enchantments: and Pharaoh''s heart was hardened, neither did he hearken unto them; as the LORD had said.', 'and the magicians of egypt did so with their enchantments and pharaoh s heart was hardened neither did he hearken unto them as the lord had said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 23, 'And Pharaoh turned and went into his house, neither did he set his heart to this also.', 'and pharaoh turned and went into his house neither did he set his heart to this also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 24, 'And all the Egyptians digged round about the river for water to drink; for they could not drink of the water of the river.', 'and all the egyptians digged round about the river for water to drink for they could not drink of the water of the river');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 7, 25, 'And seven days were fulfilled, after that the LORD had smitten the river.', 'and seven days were fulfilled after that the lord had smitten the river');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 1, 'And the LORD spake unto Moses, Go unto Pharaoh, and say unto him, Thus saith the LORD, Let my people go, that they may serve me.', 'and the lord spake unto moses go unto pharaoh and say unto him thus saith the lord let my people go that they may serve me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 2, 'And if thou refuse to let {them} go, behold, I will smite all thy borders with frogs:', 'and if thou refuse to let them go behold i will smite all thy borders with frogs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 3, 'And the river shall bring forth frogs abundantly, which shall go up and come into thine house, and into thy bedchamber, and upon thy bed, and into the house of thy servants, and upon thy people, and into thine ovens, and into thy kneadingtroughs: {kneadingtroughs: or, dough}', 'and the river shall bring forth frogs abundantly which shall go up and come into thine house and into thy bedchamber and upon thy bed and into the house of thy servants and upon thy people and into thine ovens and into thy kneadingtroughs kneadingtroughs or dough');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 4, 'And the frogs shall come up both on thee, and upon thy people, and upon all thy servants.', 'and the frogs shall come up both on thee and upon thy people and upon all thy servants');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 5, 'And the LORD spake unto Moses, Say unto Aaron, Stretch forth thine hand with thy rod over the streams, over the rivers, and over the ponds, and cause frogs to come up upon the land of Egypt.', 'and the lord spake unto moses say unto aaron stretch forth thine hand with thy rod over the streams over the rivers and over the ponds and cause frogs to come up upon the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 6, 'And Aaron stretched out his hand over the waters of Egypt; and the frogs came up, and covered the land of Egypt.', 'and aaron stretched out his hand over the waters of egypt and the frogs came up and covered the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 7, 'And the magicians did so with their enchantments, and brought up frogs upon the land of Egypt.', 'and the magicians did so with their enchantments and brought up frogs upon the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 8, 'Then Pharaoh called for Moses and Aaron, and said, Intreat the LORD, that he may take away the frogs from me, and from my people; and I will let the people go, that they may do sacrifice unto the LORD.', 'then pharaoh called for moses and aaron and said intreat the lord that he may take away the frogs from me and from my people and i will let the people go that they may do sacrifice unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 9, 'And Moses said unto Pharaoh, Glory over me: when shall I intreat for thee, and for thy servants, and for thy people, to destroy the frogs from thee and thy houses, {that} they may remain in the river only? {Glory...: or, Have this honour over me, etc} {when: or, against when} {to destroy: Heb. to cut off}', 'and moses said unto pharaoh glory over me when shall i intreat for thee and for thy servants and for thy people to destroy the frogs from thee and thy houses that they may remain in the river only glory or have this honour over me etc when or against when to destroy heb to cut off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 10, 'And he said, To morrow. And he said, {Be it} according to thy word: that thou mayest know that {there is} none like unto the LORD our God. {To morrow: or, Against to morrow}', 'and he said to morrow and he said be it according to thy word that thou mayest know that there is none like unto the lord our god to morrow or against to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 11, 'And the frogs shall depart from thee, and from thy houses, and from thy servants, and from thy people; they shall remain in the river only.', 'and the frogs shall depart from thee and from thy houses and from thy servants and from thy people they shall remain in the river only');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 12, 'And Moses and Aaron went out from Pharaoh: and Moses cried unto the LORD because of the frogs which he had brought against Pharaoh.', 'and moses and aaron went out from pharaoh and moses cried unto the lord because of the frogs which he had brought against pharaoh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 13, 'And the LORD did according to the word of Moses; and the frogs died out of the houses, out of the villages, and out of the fields.', 'and the lord did according to the word of moses and the frogs died out of the houses out of the villages and out of the fields');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 14, 'And they gathered them together upon heaps: and the land stank.', 'and they gathered them together upon heaps and the land stank');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 15, 'But when Pharaoh saw that there was respite, he hardened his heart, and hearkened not unto them; as the LORD had said.', 'but when pharaoh saw that there was respite he hardened his heart and hearkened not unto them as the lord had said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 16, 'And the LORD said unto Moses, Say unto Aaron, Stretch out thy rod, and smite the dust of the land, that it may become lice throughout all the land of Egypt.', 'and the lord said unto moses say unto aaron stretch out thy rod and smite the dust of the land that it may become lice throughout all the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 17, 'And they did so; for Aaron stretched out his hand with his rod, and smote the dust of the earth, and it became lice in man, and in beast; all the dust of the land became lice throughout all the land of Egypt.', 'and they did so for aaron stretched out his hand with his rod and smote the dust of the earth and it became lice in man and in beast all the dust of the land became lice throughout all the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 18, 'And the magicians did so with their enchantments to bring forth lice, but they could not: so there were lice upon man, and upon beast.', 'and the magicians did so with their enchantments to bring forth lice but they could not so there were lice upon man and upon beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 19, 'Then the magicians said unto Pharaoh, This {is} the finger of God: and Pharaoh''s heart was hardened, and he hearkened not unto them; as the LORD had said.', 'then the magicians said unto pharaoh this is the finger of god and pharaoh s heart was hardened and he hearkened not unto them as the lord had said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 20, 'And the LORD said unto Moses, Rise up early in the morning, and stand before Pharaoh; lo, he cometh forth to the water; and say unto him, Thus saith the LORD, Let my people go, that they may serve me.', 'and the lord said unto moses rise up early in the morning and stand before pharaoh lo he cometh forth to the water and say unto him thus saith the lord let my people go that they may serve me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 21, 'Else, if thou wilt not let my people go, behold, I will send swarms {of flies} upon thee, and upon thy servants, and upon thy people, and into thy houses: and the houses of the Egyptians shall be full of swarms {of flies}, and also the ground whereon they {are}. {swarms...: or, a mixture of noisome beasts, etc}', 'else if thou wilt not let my people go behold i will send swarms of flies upon thee and upon thy servants and upon thy people and into thy houses and the houses of the egyptians shall be full of swarms of flies and also the ground whereon they are swarms or a mixture of noisome beasts etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 22, 'And I will sever in that day the land of Goshen, in which my people dwell, that no swarms {of flies} shall be there; to the end thou mayest know that I {am} the LORD in the midst of the earth.', 'and i will sever in that day the land of goshen in which my people dwell that no swarms of flies shall be there to the end thou mayest know that i am the lord in the midst of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 23, 'And I will put a division between my people and thy people: to morrow shall this sign be. {a division: Heb. a redemption} {to morrow: or, by to morrow}', 'and i will put a division between my people and thy people to morrow shall this sign be a division heb a redemption to morrow or by to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 24, 'And the LORD did so; and there came a grievous swarm {of flies} into the house of Pharaoh, and {into} his servants'' houses, and into all the land of Egypt: the land was corrupted by reason of the swarm {of flies}. {corrupted: or, destroyed}', 'and the lord did so and there came a grievous swarm of flies into the house of pharaoh and into his servants houses and into all the land of egypt the land was corrupted by reason of the swarm of flies corrupted or destroyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 25, 'And Pharaoh called for Moses and for Aaron, and said, Go ye, sacrifice to your God in the land.', 'and pharaoh called for moses and for aaron and said go ye sacrifice to your god in the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 8, 26, 'And Moses said, It is not meet so to do; for we shall sacrifice the abomination of the Egyptians to the LORD our God: lo, shall we sacrifice the abomination of the Egyptians before their eyes, and will they not stone us?', 'and moses said it is not meet so to do for we shall sacrifice the abomination of the egyptians to the lord our god lo shall we sacrifice the abomination of the egyptians before their eyes and will they not stone us');
