INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 10, 'And they took ashes of the furnace, and stood before Pharaoh; and Moses sprinkled it up toward heaven; and it became a boil breaking forth {with} blains upon man, and upon beast.', 'and they took ashes of the furnace and stood before pharaoh and moses sprinkled it up toward heaven and it became a boil breaking forth with blains upon man and upon beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 11, 'And the magicians could not stand before Moses because of the boils; for the boil was upon the magicians, and upon all the Egyptians.', 'and the magicians could not stand before moses because of the boils for the boil was upon the magicians and upon all the egyptians');
