INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 13, 'And the LORD said unto Moses, Rise up early in the morning, and stand before Pharaoh, and say unto him, Thus saith the LORD God of the Hebrews, Let my people go, that they may serve me.', 'and the lord said unto moses rise up early in the morning and stand before pharaoh and say unto him thus saith the lord god of the hebrews let my people go that they may serve me');
