INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 18, 'Behold, to morrow about this time I will cause it to rain a very grievous hail, such as hath not been in Egypt since the foundation thereof even until now.', 'behold to morrow about this time i will cause it to rain a very grievous hail such as hath not been in egypt since the foundation thereof even until now');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 19, 'Send therefore now, {and} gather thy cattle, and all that thou hast in the field; {for upon} every man and beast which shall be found in the field, and shall not be brought home, the hail shall come down upon them, and they shall die.', 'send therefore now and gather thy cattle and all that thou hast in the field for upon every man and beast which shall be found in the field and shall not be brought home the hail shall come down upon them and they shall die');
