INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 22, 'And the LORD said unto Moses, Stretch forth thine hand toward heaven, that there may be hail in all the land of Egypt, upon man, and upon beast, and upon every herb of the field, throughout the land of Egypt.', 'and the lord said unto moses stretch forth thine hand toward heaven that there may be hail in all the land of egypt upon man and upon beast and upon every herb of the field throughout the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 23, 'And Moses stretched forth his rod toward heaven: and the LORD sent thunder and hail, and the fire ran along upon the ground; and the LORD rained hail upon the land of Egypt.', 'and moses stretched forth his rod toward heaven and the lord sent thunder and hail and the fire ran along upon the ground and the lord rained hail upon the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 24, 'So there was hail, and fire mingled with the hail, very grievous, such as there was none like it in all the land of Egypt since it became a nation.', 'so there was hail and fire mingled with the hail very grievous such as there was none like it in all the land of egypt since it became a nation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 25, 'And the hail smote throughout all the land of Egypt all that {was} in the field, both man and beast; and the hail smote every herb of the field, and brake every tree of the field.', 'and the hail smote throughout all the land of egypt all that was in the field both man and beast and the hail smote every herb of the field and brake every tree of the field');
