INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 27, 'And Pharaoh sent, and called for Moses and Aaron, and said unto them, I have sinned this time: the LORD {is} righteous, and I and my people {are} wicked.', 'and pharaoh sent and called for moses and aaron and said unto them i have sinned this time the lord is righteous and i and my people are wicked');
