INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 30, 'But as for thee and thy servants, I know that ye will not yet fear the LORD God.', 'but as for thee and thy servants i know that ye will not yet fear the lord god');
