INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 33, 'And Moses went out of the city from Pharaoh, and spread abroad his hands unto the LORD: and the thunders and hail ceased, and the rain was not poured upon the earth.', 'and moses went out of the city from pharaoh and spread abroad his hands unto the lord and the thunders and hail ceased and the rain was not poured upon the earth');
