INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 9, 35, 'And the heart of Pharaoh was hardened, neither would he let the children of Israel go; as the LORD had spoken by Moses. {by Moses: Heb. by the hand of Moses}', 'and the heart of pharaoh was hardened neither would he let the children of israel go as the lord had spoken by moses by moses heb by the hand of moses');
