INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 3, 'And Moses and Aaron came in unto Pharaoh, and said unto him, Thus saith the LORD God of the Hebrews, How long wilt thou refuse to humble thyself before me? let my people go, that they may serve me.', 'and moses and aaron came in unto pharaoh and said unto him thus saith the lord god of the hebrews how long wilt thou refuse to humble thyself before me let my people go that they may serve me');
