INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 7, 'And Pharaoh''s servants said unto him, How long shall this man be a snare unto us? let the men go, that they may serve the LORD their God: knowest thou not yet that Egypt is destroyed?', 'and pharaoh s servants said unto him how long shall this man be a snare unto us let the men go that they may serve the lord their god knowest thou not yet that egypt is destroyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 8, 'And Moses and Aaron were brought again unto Pharaoh: and he said unto them, Go, serve the LORD your God: {but} who {are} they that shall go? {who...: Heb. who and who, etc}', 'and moses and aaron were brought again unto pharaoh and he said unto them go serve the lord your god but who are they that shall go who heb who and who etc');
