INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 10, 'And he said unto them, Let the LORD be so with you, as I will let you go, and your little ones: look {to it}; for evil {is} before you.', 'and he said unto them let the lord be so with you as i will let you go and your little ones look to it for evil is before you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 11, 'Not so: go now ye {that are} men, and serve the LORD; for that ye did desire. And they were driven out from Pharaoh''s presence.', 'not so go now ye that are men and serve the lord for that ye did desire and they were driven out from pharaoh s presence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 12, 'And the LORD said unto Moses, Stretch out thine hand over the land of Egypt for the locusts, that they may come up upon the land of Egypt, and eat every herb of the land, {even} all that the hail hath left.', 'and the lord said unto moses stretch out thine hand over the land of egypt for the locusts that they may come up upon the land of egypt and eat every herb of the land even all that the hail hath left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 13, 'And Moses stretched forth his rod over the land of Egypt, and the LORD brought an east wind upon the land all that day, and all {that} night; {and} when it was morning, the east wind brought the locusts.', 'and moses stretched forth his rod over the land of egypt and the lord brought an east wind upon the land all that day and all that night and when it was morning the east wind brought the locusts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 10, 14, 'And the locusts went up over all the land of Egypt, and rested in all the coasts of Egypt: very grievous {were they}; before them there were no such locusts as they, neither after them shall be such.', 'and the locusts went up over all the land of egypt and rested in all the coasts of egypt very grievous were they before them there were no such locusts as they neither after them shall be such');
