INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 9, 'Eat not of it raw, nor sodden at all with water, but roast {with} fire; his head with his legs, and with the purtenance thereof.', 'eat not of it raw nor sodden at all with water but roast with fire his head with his legs and with the purtenance thereof');
