INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 17, 'And ye shall observe {the feast of} unleavened bread; for in this selfsame day have I brought your armies out of the land of Egypt: therefore shall ye observe this day in your generations by an ordinance for ever.', 'and ye shall observe the feast of unleavened bread for in this selfsame day have i brought your armies out of the land of egypt therefore shall ye observe this day in your generations by an ordinance for ever');
