INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 39, 'And they baked unleavened cakes of the dough which they brought forth out of Egypt, for it was not leavened; because they were thrust out of Egypt, and could not tarry, neither had they prepared for themselves any victual.', 'and they baked unleavened cakes of the dough which they brought forth out of egypt for it was not leavened because they were thrust out of egypt and could not tarry neither had they prepared for themselves any victual');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 40, 'Now the sojourning of the children of Israel, who dwelt in Egypt, {was} four hundred and thirty years.', 'now the sojourning of the children of israel who dwelt in egypt was four hundred and thirty years');
