INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 43, 'And the LORD said unto Moses and Aaron, This {is} the ordinance of the passover: There shall no stranger eat thereof:', 'and the lord said unto moses and aaron this is the ordinance of the passover there shall no stranger eat thereof');
