INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 46, 'In one house shall it be eaten; thou shalt not carry forth ought of the flesh abroad out of the house; neither shall ye break a bone thereof.', 'in one house shall it be eaten thou shalt not carry forth ought of the flesh abroad out of the house neither shall ye break a bone thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 47, 'All the congregation of Israel shall keep it. {keep...: Heb. do it}', 'all the congregation of israel shall keep it keep heb do it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 48, 'And when a stranger shall sojourn with thee, and will keep the passover to the LORD, let all his males be circumcised, and then let him come near and keep it; and he shall be as one that is born in the land: for no uncircumcised person shall eat thereof.', 'and when a stranger shall sojourn with thee and will keep the passover to the lord let all his males be circumcised and then let him come near and keep it and he shall be as one that is born in the land for no uncircumcised person shall eat thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 12, 49, 'One law shall be to him that is homeborn, and unto the stranger that sojourneth among you.', 'one law shall be to him that is homeborn and unto the stranger that sojourneth among you');
