INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 2, 'Sanctify unto me all the firstborn, whatsoever openeth the womb among the children of Israel, {both} of man and of beast: it {is} mine.', 'sanctify unto me all the firstborn whatsoever openeth the womb among the children of israel both of man and of beast it is mine');
