INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 4, 'This day came ye out in the month Abib.', 'this day came ye out in the month abib');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 5, 'And it shall be when the LORD shall bring thee into the land of the Canaanites, and the Hittites, and the Amorites, and the Hivites, and the Jebusites, which he sware unto thy fathers to give thee, a land flowing with milk and honey, that thou shalt keep this service in this month.', 'and it shall be when the lord shall bring thee into the land of the canaanites and the hittites and the amorites and the hivites and the jebusites which he sware unto thy fathers to give thee a land flowing with milk and honey that thou shalt keep this service in this month');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 6, 'Seven days thou shalt eat unleavened bread, and in the seventh day {shall be} a feast to the LORD.', 'seven days thou shalt eat unleavened bread and in the seventh day shall be a feast to the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 7, 'Unleavened bread shall be eaten seven days; and there shall no leavened bread be seen with thee, neither shall there be leaven seen with thee in all thy quarters.', 'unleavened bread shall be eaten seven days and there shall no leavened bread be seen with thee neither shall there be leaven seen with thee in all thy quarters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 8, 'And thou shalt shew thy son in that day, saying, {This is done} because of that {which} the LORD did unto me when I came forth out of Egypt.', 'and thou shalt shew thy son in that day saying this is done because of that which the lord did unto me when i came forth out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 9, 'And it shall be for a sign unto thee upon thine hand, and for a memorial between thine eyes, that the LORD''S law may be in thy mouth: for with a strong hand hath the LORD brought thee out of Egypt.', 'and it shall be for a sign unto thee upon thine hand and for a memorial between thine eyes that the lord s law may be in thy mouth for with a strong hand hath the lord brought thee out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 10, 'Thou shalt therefore keep this ordinance in his season from year to year.', 'thou shalt therefore keep this ordinance in his season from year to year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 11, 'And it shall be when the LORD shall bring thee into the land of the Canaanites, as he sware unto thee and to thy fathers, and shall give it thee,', 'and it shall be when the lord shall bring thee into the land of the canaanites as he sware unto thee and to thy fathers and shall give it thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 12, 'That thou shalt set apart unto the LORD all that openeth the matrix, and every firstling that cometh of a beast which thou hast; the males {shall be} the LORD''S. {set...: Heb. cause to pass over}', 'that thou shalt set apart unto the lord all that openeth the matrix and every firstling that cometh of a beast which thou hast the males shall be the lord s set heb cause to pass over');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 13, 'And every firstling of an ass thou shalt redeem with a lamb; and if thou wilt not redeem it, then thou shalt break his neck: and all the firstborn of man among thy children shalt thou redeem. {lamb: or, kid}', 'and every firstling of an ass thou shalt redeem with a lamb and if thou wilt not redeem it then thou shalt break his neck and all the firstborn of man among thy children shalt thou redeem lamb or kid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 14, 'And it shall be when thy son asketh thee in time to come, saying, What {is} this? that thou shalt say unto him, By strength of hand the LORD brought us out from Egypt, from the house of bondage: {in...: Heb. to morrow}', 'and it shall be when thy son asketh thee in time to come saying what is this that thou shalt say unto him by strength of hand the lord brought us out from egypt from the house of bondage in heb to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 15, 'And it came to pass, when Pharaoh would hardly let us go, that the LORD slew all the firstborn in the land of Egypt, both the firstborn of man, and the firstborn of beast: therefore I sacrifice to the LORD all that openeth the matrix, being males; but all the firstborn of my children I redeem.', 'and it came to pass when pharaoh would hardly let us go that the lord slew all the firstborn in the land of egypt both the firstborn of man and the firstborn of beast therefore i sacrifice to the lord all that openeth the matrix being males but all the firstborn of my children i redeem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 16, 'And it shall be for a token upon thine hand, and for frontlets between thine eyes: for by strength of hand the LORD brought us forth out of Egypt.', 'and it shall be for a token upon thine hand and for frontlets between thine eyes for by strength of hand the lord brought us forth out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 17, 'And it came to pass, when Pharaoh had let the people go, that God led them not {through} the way of the land of the Philistines, although that {was} near; for God said, Lest peradventure the people repent when they see war, and they return to Egypt:', 'and it came to pass when pharaoh had let the people go that god led them not through the way of the land of the philistines although that was near for god said lest peradventure the people repent when they see war and they return to egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 18, 'But God led the people about, {through} the way of the wilderness of the Red sea: and the children of Israel went up harnessed out of the land of Egypt. {harnessed: or, by five in a rank}', 'but god led the people about through the way of the wilderness of the red sea and the children of israel went up harnessed out of the land of egypt harnessed or by five in a rank');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 19, 'And Moses took the bones of Joseph with him: for he had straitly sworn the children of Israel, saying, God will surely visit you; and ye shall carry up my bones away hence with you.', 'and moses took the bones of joseph with him for he had straitly sworn the children of israel saying god will surely visit you and ye shall carry up my bones away hence with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 13, 20, 'And they took their journey from Succoth, and encamped in Etham, in the edge of the wilderness.', 'and they took their journey from succoth and encamped in etham in the edge of the wilderness');
