INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 5, 'And it was told the king of Egypt that the people fled: and the heart of Pharaoh and of his servants was turned against the people, and they said, Why have we done this, that we have let Israel go from serving us?', 'and it was told the king of egypt that the people fled and the heart of pharaoh and of his servants was turned against the people and they said why have we done this that we have let israel go from serving us');
