INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 8, 'And the LORD hardened the heart of Pharaoh king of Egypt, and he pursued after the children of Israel: and the children of Israel went out with an high hand.', 'and the lord hardened the heart of pharaoh king of egypt and he pursued after the children of israel and the children of israel went out with an high hand');
