INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 10, 'And when Pharaoh drew nigh, the children of Israel lifted up their eyes, and, behold, the Egyptians marched after them; and they were sore afraid: and the children of Israel cried out unto the LORD.', 'and when pharaoh drew nigh the children of israel lifted up their eyes and behold the egyptians marched after them and they were sore afraid and the children of israel cried out unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 11, 'And they said unto Moses, Because {there were} no graves in Egypt, hast thou taken us away to die in the wilderness? wherefore hast thou dealt thus with us, to carry us forth out of Egypt?', 'and they said unto moses because there were no graves in egypt hast thou taken us away to die in the wilderness wherefore hast thou dealt thus with us to carry us forth out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 12, '{Is} not this the word that we did tell thee in Egypt, saying, Let us alone, that we may serve the Egyptians? For {it had been} better for us to serve the Egyptians, than that we should die in the wilderness.', 'is not this the word that we did tell thee in egypt saying let us alone that we may serve the egyptians for it had been better for us to serve the egyptians than that we should die in the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 13, 'And Moses said unto the people, Fear ye not, stand still, and see the salvation of the LORD, which he will shew to you to day: for the Egyptians whom ye have seen to day, ye shall see them again no more for ever. {for the...: or, for whereas ye have seen the Egyptians to day}', 'and moses said unto the people fear ye not stand still and see the salvation of the lord which he will shew to you to day for the egyptians whom ye have seen to day ye shall see them again no more for ever for the or for whereas ye have seen the egyptians to day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 14, 'The LORD shall fight for you, and ye shall hold your peace.', 'the lord shall fight for you and ye shall hold your peace');
