INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 16, 'But lift thou up thy rod, and stretch out thine hand over the sea, and divide it: and the children of Israel shall go on dry {ground} through the midst of the sea.', 'but lift thou up thy rod and stretch out thine hand over the sea and divide it and the children of israel shall go on dry ground through the midst of the sea');
