INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 18, 'And the Egyptians shall know that I {am} the LORD, when I have gotten me honour upon Pharaoh, upon his chariots, and upon his horsemen.', 'and the egyptians shall know that i am the lord when i have gotten me honour upon pharaoh upon his chariots and upon his horsemen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 19, 'And the angel of God, which went before the camp of Israel, removed and went behind them; and the pillar of the cloud went from before their face, and stood behind them:', 'and the angel of god which went before the camp of israel removed and went behind them and the pillar of the cloud went from before their face and stood behind them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 20, 'And it came between the camp of the Egyptians and the camp of Israel; and it was a cloud and darkness {to them}, but it gave light by night {to these}: so that the one came not near the other all the night.', 'and it came between the camp of the egyptians and the camp of israel and it was a cloud and darkness to them but it gave light by night to these so that the one came not near the other all the night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 14, 21, 'And Moses stretched out his hand over the sea; and the LORD caused the sea to go {back} by a strong east wind all that night, and made the sea dry {land}, and the waters were divided.', 'and moses stretched out his hand over the sea and the lord caused the sea to go back by a strong east wind all that night and made the sea dry land and the waters were divided');
