INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 15, 'And when the children of Israel saw {it}, they said one to another, It {is} manna: for they wist not what it {was}. And Moses said unto them, This {is} the bread which the LORD hath given you to eat. {It is...: or, What is this? or, It is a portion}', 'and when the children of israel saw it they said one to another it is manna for they wist not what it was and moses said unto them this is the bread which the lord hath given you to eat it is or what is this or it is a portion');
