INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 25, 'And Moses said, Eat that to day; for to day {is} a sabbath unto the LORD: to day ye shall not find it in the field.', 'and moses said eat that to day for to day is a sabbath unto the lord to day ye shall not find it in the field');
