INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 27, 'And it came to pass, {that} there went out {some} of the people on the seventh day for to gather, and they found none.', 'and it came to pass that there went out some of the people on the seventh day for to gather and they found none');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 28, 'And the LORD said unto Moses, How long refuse ye to keep my commandments and my laws?', 'and the lord said unto moses how long refuse ye to keep my commandments and my laws');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 29, 'See, for that the LORD hath given you the sabbath, therefore he giveth you on the sixth day the bread of two days; abide ye every man in his place, let no man go out of his place on the seventh day.', 'see for that the lord hath given you the sabbath therefore he giveth you on the sixth day the bread of two days abide ye every man in his place let no man go out of his place on the seventh day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 30, 'So the people rested on the seventh day.', 'so the people rested on the seventh day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 31, 'And the house of Israel called the name thereof Manna: and it {was} like coriander seed, white; and the taste of it {was} like wafers {made} with honey.', 'and the house of israel called the name thereof manna and it was like coriander seed white and the taste of it was like wafers made with honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 32, 'And Moses said, This {is} the thing which the LORD commandeth, Fill an omer of it to be kept for your generations; that they may see the bread wherewith I have fed you in the wilderness, when I brought you forth from the land of Egypt.', 'and moses said this is the thing which the lord commandeth fill an omer of it to be kept for your generations that they may see the bread wherewith i have fed you in the wilderness when i brought you forth from the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 33, 'And Moses said unto Aaron, Take a pot, and put an omer full of manna therein, and lay it up before the LORD, to be kept for your generations.', 'and moses said unto aaron take a pot and put an omer full of manna therein and lay it up before the lord to be kept for your generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 34, 'As the LORD commanded Moses, so Aaron laid it up before the Testimony, to be kept.', 'as the lord commanded moses so aaron laid it up before the testimony to be kept');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 35, 'And the children of Israel did eat manna forty years, until they came to a land inhabited; they did eat manna, until they came unto the borders of the land of Canaan.', 'and the children of israel did eat manna forty years until they came to a land inhabited they did eat manna until they came unto the borders of the land of canaan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 16, 36, 'Now an omer {is} the tenth {part} of an ephah.', 'now an omer is the tenth part of an ephah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 17, 1, 'And all the congregation of the children of Israel journeyed from the wilderness of Sin, after their journeys, according to the commandment of the LORD, and pitched in Rephidim: and {there was} no water for the people to drink.', 'and all the congregation of the children of israel journeyed from the wilderness of sin after their journeys according to the commandment of the lord and pitched in rephidim and there was no water for the people to drink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 17, 2, 'Wherefore the people did chide with Moses, and said, Give us water that we may drink. And Moses said unto them, Why chide ye with me? wherefore do ye tempt the LORD?', 'wherefore the people did chide with moses and said give us water that we may drink and moses said unto them why chide ye with me wherefore do ye tempt the lord');
