INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 19, 1, 'In the third month, when the children of Israel were gone forth out of the land of Egypt, the same day came they {into} the wilderness of Sinai.', 'in the third month when the children of israel were gone forth out of the land of egypt the same day came they into the wilderness of sinai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 19, 2, 'For they were departed from Rephidim, and were come {to} the desert of Sinai, and had pitched in the wilderness; and there Israel camped before the mount.', 'for they were departed from rephidim and were come to the desert of sinai and had pitched in the wilderness and there israel camped before the mount');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 19, 3, 'And Moses went up unto God, and the LORD called unto him out of the mountain, saying, Thus shalt thou say to the house of Jacob, and tell the children of Israel;', 'and moses went up unto god and the lord called unto him out of the mountain saying thus shalt thou say to the house of jacob and tell the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 19, 4, 'Ye have seen what I did unto the Egyptians, and {how} I bare you on eagles'' wings, and brought you unto myself.', 'ye have seen what i did unto the egyptians and how i bare you on eagles wings and brought you unto myself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 19, 5, 'Now therefore, if ye will obey my voice indeed, and keep my covenant, then ye shall be a peculiar treasure unto me above all people: for all the earth {is} mine:', 'now therefore if ye will obey my voice indeed and keep my covenant then ye shall be a peculiar treasure unto me above all people for all the earth is mine');
