INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 29, 18, 'And thou shalt burn the whole ram upon the altar: it {is} a burnt offering unto the LORD: it {is} a sweet savour, an offering made by fire unto the LORD.', 'and thou shalt burn the whole ram upon the altar it is a burnt offering unto the lord it is a sweet savour an offering made by fire unto the lord');
