INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 29, 33, 'And they shall eat those things wherewith the atonement was made, to consecrate {and} to sanctify them: but a stranger shall not eat {thereof}, because they {are} holy.', 'and they shall eat those things wherewith the atonement was made to consecrate and to sanctify them but a stranger shall not eat thereof because they are holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 29, 34, 'And if ought of the flesh of the consecrations, or of the bread, remain unto the morning, then thou shalt burn the remainder with fire: it shall not be eaten, because it {is} holy.', 'and if ought of the flesh of the consecrations or of the bread remain unto the morning then thou shalt burn the remainder with fire it shall not be eaten because it is holy');
