INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 30, 18, 'Thou shalt also make a laver {of} brass, and his foot {also of} brass, to wash {withal}: and thou shalt put it between the tabernacle of the congregation and the altar, and thou shalt put water therein.', 'thou shalt also make a laver of brass and his foot also of brass to wash withal and thou shalt put it between the tabernacle of the congregation and the altar and thou shalt put water therein');
