INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 30, 20, 'When they go into the tabernacle of the congregation, they shall wash with water, that they die not; or when they come near to the altar to minister, to burn offering made by fire unto the LORD:', 'when they go into the tabernacle of the congregation they shall wash with water that they die not or when they come near to the altar to minister to burn offering made by fire unto the lord');
