INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 31, 17, 'It {is} a sign between me and the children of Israel for ever: for {in} six days the LORD made heaven and earth, and on the seventh day he rested, and was refreshed.', 'it is a sign between me and the children of israel for ever for in six days the lord made heaven and earth and on the seventh day he rested and was refreshed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 31, 18, 'And he gave unto Moses, when he had made an end of communing with him upon mount Sinai, two tables of testimony, tables of stone, written with the finger of God.', 'and he gave unto moses when he had made an end of communing with him upon mount sinai two tables of testimony tables of stone written with the finger of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 1, 'And when the people saw that Moses delayed to come down out of the mount, the people gathered themselves together unto Aaron, and said unto him, Up, make us gods, which shall go before us; for {as for} this Moses, the man that brought us up out of the land of Egypt, we wot not what is become of him.', 'and when the people saw that moses delayed to come down out of the mount the people gathered themselves together unto aaron and said unto him up make us gods which shall go before us for as for this moses the man that brought us up out of the land of egypt we wot not what is become of him');
