INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 4, 'And he received {them} at their hand, and fashioned it with a graving tool, after he had made it a molten calf: and they said, These {be} thy gods, O Israel, which brought thee up out of the land of Egypt.', 'and he received them at their hand and fashioned it with a graving tool after he had made it a molten calf and they said these be thy gods o israel which brought thee up out of the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 5, 'And when Aaron saw {it}, he built an altar before it; and Aaron made proclamation, and said, To morrow {is} a feast to the LORD.', 'and when aaron saw it he built an altar before it and aaron made proclamation and said to morrow is a feast to the lord');
