INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 9, 'And the LORD said unto Moses, I have seen this people, and, behold, it {is} a stiffnecked people:', 'and the lord said unto moses i have seen this people and behold it is a stiffnecked people');
