INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 12, 'Wherefore should the Egyptians speak, and say, For mischief did he bring them out, to slay them in the mountains, and to consume them from the face of the earth? Turn from thy fierce wrath, and repent of this evil against thy people.', 'wherefore should the egyptians speak and say for mischief did he bring them out to slay them in the mountains and to consume them from the face of the earth turn from thy fierce wrath and repent of this evil against thy people');
