INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 19, 'And it came to pass, as soon as he came nigh unto the camp, that he saw the calf, and the dancing: and Moses'' anger waxed hot, and he cast the tables out of his hands, and brake them beneath the mount.', 'and it came to pass as soon as he came nigh unto the camp that he saw the calf and the dancing and moses anger waxed hot and he cast the tables out of his hands and brake them beneath the mount');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 20, 'And he took the calf which they had made, and burnt {it} in the fire, and ground {it} to powder, and strawed {it} upon the water, and made the children of Israel drink {of it}.', 'and he took the calf which they had made and burnt it in the fire and ground it to powder and strawed it upon the water and made the children of israel drink of it');
