INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 32, 34, 'Therefore now go, lead the people unto {the place} of which I have spoken unto thee: behold, mine Angel shall go before thee: nevertheless in the day when I visit I will visit their sin upon them.', 'therefore now go lead the people unto the place of which i have spoken unto thee behold mine angel shall go before thee nevertheless in the day when i visit i will visit their sin upon them');
