INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 33, 6, 'And the children of Israel stripped themselves of their ornaments by the mount Horeb.', 'and the children of israel stripped themselves of their ornaments by the mount horeb');
