INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 33, 8, 'And it came to pass, when Moses went out unto the tabernacle, {that} all the people rose up, and stood every man {at} his tent door, and looked after Moses, until he was gone into the tabernacle.', 'and it came to pass when moses went out unto the tabernacle that all the people rose up and stood every man at his tent door and looked after moses until he was gone into the tabernacle');
