INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 34, 22, 'And thou shalt observe the feast of weeks, of the firstfruits of wheat harvest, and the feast of ingathering at the year''s end. {year''s end: Heb. revolution of the year}', 'and thou shalt observe the feast of weeks of the firstfruits of wheat harvest and the feast of ingathering at the year s end year s end heb revolution of the year');
