INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 36, 6, 'And Moses gave commandment, and they caused it to be proclaimed throughout the camp, saying, Let neither man nor woman make any more work for the offering of the sanctuary. So the people were restrained from bringing.', 'and moses gave commandment and they caused it to be proclaimed throughout the camp saying let neither man nor woman make any more work for the offering of the sanctuary so the people were restrained from bringing');
