INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 36, 9, 'The length of one curtain {was} twenty and eight cubits, and the breadth of one curtain four cubits: the curtains {were} all of one size.', 'the length of one curtain was twenty and eight cubits and the breadth of one curtain four cubits the curtains were all of one size');
