INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 13, 'And thou shalt put upon Aaron the holy garments, and anoint him, and sanctify him; that he may minister unto me in the priest''s office.', 'and thou shalt put upon aaron the holy garments and anoint him and sanctify him that he may minister unto me in the priest s office');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 14, 'And thou shalt bring his sons, and clothe them with coats:', 'and thou shalt bring his sons and clothe them with coats');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 15, 'And thou shalt anoint them, as thou didst anoint their father, that they may minister unto me in the priest''s office: for their anointing shall surely be an everlasting priesthood throughout their generations.', 'and thou shalt anoint them as thou didst anoint their father that they may minister unto me in the priest s office for their anointing shall surely be an everlasting priesthood throughout their generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 16, 'Thus did Moses: according to all that the LORD commanded him, so did he.', 'thus did moses according to all that the lord commanded him so did he');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 17, 'And it came to pass in the first month in the second year, on the first {day} of the month, {that} the tabernacle was reared up.', 'and it came to pass in the first month in the second year on the first day of the month that the tabernacle was reared up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 18, 'And Moses reared up the tabernacle, and fastened his sockets, and set up the boards thereof, and put in the bars thereof, and reared up his pillars.', 'and moses reared up the tabernacle and fastened his sockets and set up the boards thereof and put in the bars thereof and reared up his pillars');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 19, 'And he spread abroad the tent over the tabernacle, and put the covering of the tent above upon it; as the LORD commanded Moses.', 'and he spread abroad the tent over the tabernacle and put the covering of the tent above upon it as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 20, 'And he took and put the testimony into the ark, and set the staves on the ark, and put the mercy seat above upon the ark:', 'and he took and put the testimony into the ark and set the staves on the ark and put the mercy seat above upon the ark');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 21, 'And he brought the ark into the tabernacle, and set up the vail of the covering, and covered the ark of the testimony; as the LORD commanded Moses.', 'and he brought the ark into the tabernacle and set up the vail of the covering and covered the ark of the testimony as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 22, 'And he put the table in the tent of the congregation, upon the side of the tabernacle northward, without the vail.', 'and he put the table in the tent of the congregation upon the side of the tabernacle northward without the vail');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 23, 'And he set the bread in order upon it before the LORD; as the LORD had commanded Moses.', 'and he set the bread in order upon it before the lord as the lord had commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 24, 'And he put the candlestick in the tent of the congregation, over against the table, on the side of the tabernacle southward.', 'and he put the candlestick in the tent of the congregation over against the table on the side of the tabernacle southward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 25, 'And he lighted the lamps before the LORD; as the LORD commanded Moses.', 'and he lighted the lamps before the lord as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 26, 'And he put the golden altar in the tent of the congregation before the vail:', 'and he put the golden altar in the tent of the congregation before the vail');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 27, 'And he burnt sweet incense thereon; as the LORD commanded Moses.', 'and he burnt sweet incense thereon as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 28, 'And he set up the hanging {at} the door of the tabernacle.', 'and he set up the hanging at the door of the tabernacle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 29, 'And he put the altar of burnt offering {by} the door of the tabernacle of the tent of the congregation, and offered upon it the burnt offering and the meat offering; as the LORD commanded Moses.', 'and he put the altar of burnt offering by the door of the tabernacle of the tent of the congregation and offered upon it the burnt offering and the meat offering as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 30, 'And he set the laver between the tent of the congregation and the altar, and put water there, to wash {withal}.', 'and he set the laver between the tent of the congregation and the altar and put water there to wash withal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 31, 'And Moses and Aaron and his sons washed their hands and their feet thereat:', 'and moses and aaron and his sons washed their hands and their feet thereat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 32, 'When they went into the tent of the congregation, and when they came near unto the altar, they washed; as the LORD commanded Moses.', 'when they went into the tent of the congregation and when they came near unto the altar they washed as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 33, 'And he reared up the court round about the tabernacle and the altar, and set up the hanging of the court gate. So Moses finished the work.', 'and he reared up the court round about the tabernacle and the altar and set up the hanging of the court gate so moses finished the work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 34, 'Then a cloud covered the tent of the congregation, and the glory of the LORD filled the tabernacle.', 'then a cloud covered the tent of the congregation and the glory of the lord filled the tabernacle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 35, 'And Moses was not able to enter into the tent of the congregation, because the cloud abode thereon, and the glory of the LORD filled the tabernacle.', 'and moses was not able to enter into the tent of the congregation because the cloud abode thereon and the glory of the lord filled the tabernacle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 36, 'And when the cloud was taken up from over the tabernacle, the children of Israel went onward in all their journeys: {went onward: Heb. journeyed}', 'and when the cloud was taken up from over the tabernacle the children of israel went onward in all their journeys went onward heb journeyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 37, 'But if the cloud were not taken up, then they journeyed not till the day that it was taken up.', 'but if the cloud were not taken up then they journeyed not till the day that it was taken up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 2, 'Unknown', 40, 38, 'For the cloud of the LORD {was} upon the tabernacle by day, and fire was on it by night, in the sight of all the house of Israel, throughout all their journeys.', 'for the cloud of the lord was upon the tabernacle by day and fire was on it by night in the sight of all the house of israel throughout all their journeys');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 1, 'And the LORD called unto Moses, and spake unto him out of the tabernacle of the congregation, saying,', 'and the lord called unto moses and spake unto him out of the tabernacle of the congregation saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 2, 'Speak unto the children of Israel, and say unto them, If any man of you bring an offering unto the LORD, ye shall bring your offering of the cattle, {even} of the herd, and of the flock.', 'speak unto the children of israel and say unto them if any man of you bring an offering unto the lord ye shall bring your offering of the cattle even of the herd and of the flock');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 3, 'If his offering {be} a burnt sacrifice of the herd, let him offer a male without blemish: he shall offer it of his own voluntary will at the door of the tabernacle of the congregation before the LORD.', 'if his offering be a burnt sacrifice of the herd let him offer a male without blemish he shall offer it of his own voluntary will at the door of the tabernacle of the congregation before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 4, 'And he shall put his hand upon the head of the burnt offering; and it shall be accepted for him to make atonement for him.', 'and he shall put his hand upon the head of the burnt offering and it shall be accepted for him to make atonement for him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 5, 'And he shall kill the bullock before the LORD: and the priests, Aaron''s sons, shall bring the blood, and sprinkle the blood round about upon the altar that {is by} the door of the tabernacle of the congregation.', 'and he shall kill the bullock before the lord and the priests aaron s sons shall bring the blood and sprinkle the blood round about upon the altar that is by the door of the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 6, 'And he shall flay the burnt offering, and cut it into his pieces.', 'and he shall flay the burnt offering and cut it into his pieces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 7, 'And the sons of Aaron the priest shall put fire upon the altar, and lay the wood in order upon the fire:', 'and the sons of aaron the priest shall put fire upon the altar and lay the wood in order upon the fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 8, 'And the priests, Aaron''s sons, shall lay the parts, the head, and the fat, in order upon the wood that {is} on the fire which {is} upon the altar:', 'and the priests aaron s sons shall lay the parts the head and the fat in order upon the wood that is on the fire which is upon the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 9, 'But his inwards and his legs shall he wash in water: and the priest shall burn all on the altar, {to be} a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.', 'but his inwards and his legs shall he wash in water and the priest shall burn all on the altar to be a burnt sacrifice an offering made by fire of a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 10, 'And if his offering {be} of the flocks, {namely}, of the sheep, or of the goats, for a burnt sacrifice; he shall bring it a male without blemish.', 'and if his offering be of the flocks namely of the sheep or of the goats for a burnt sacrifice he shall bring it a male without blemish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 11, 'And he shall kill it on the side of the altar northward before the LORD: and the priests, Aaron''s sons, shall sprinkle his blood round about upon the altar.', 'and he shall kill it on the side of the altar northward before the lord and the priests aaron s sons shall sprinkle his blood round about upon the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 12, 'And he shall cut it into his pieces, with his head and his fat: and the priest shall lay them in order on the wood that {is} on the fire which {is} upon the altar:', 'and he shall cut it into his pieces with his head and his fat and the priest shall lay them in order on the wood that is on the fire which is upon the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 13, 'But he shall wash the inwards and the legs with water: and the priest shall bring {it} all, and burn {it} upon the altar: it {is} a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.', 'but he shall wash the inwards and the legs with water and the priest shall bring it all and burn it upon the altar it is a burnt sacrifice an offering made by fire of a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 14, 'And if the burnt sacrifice for his offering to the LORD {be} of fowls, then he shall bring his offering of turtledoves, or of young pigeons.', 'and if the burnt sacrifice for his offering to the lord be of fowls then he shall bring his offering of turtledoves or of young pigeons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 15, 'And the priest shall bring it unto the altar, and wring off his head, and burn {it} on the altar; and the blood thereof shall be wrung out at the side of the altar: {wring...: or, pinch off the head with the nail}', 'and the priest shall bring it unto the altar and wring off his head and burn it on the altar and the blood thereof shall be wrung out at the side of the altar wring or pinch off the head with the nail');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 16, 'And he shall pluck away his crop with his feathers, and cast it beside the altar on the east part, by the place of the ashes: {his feathers: or, the filth thereof}', 'and he shall pluck away his crop with his feathers and cast it beside the altar on the east part by the place of the ashes his feathers or the filth thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 1, 17, 'And he shall cleave it with the wings thereof, {but} shall not divide {it} asunder: and the priest shall burn it upon the altar, upon the wood that {is} upon the fire: it {is} a burnt sacrifice, an offering made by fire, of a sweet savour unto the LORD.', 'and he shall cleave it with the wings thereof but shall not divide it asunder and the priest shall burn it upon the altar upon the wood that is upon the fire it is a burnt sacrifice an offering made by fire of a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 1, 'And when any will offer a meat offering unto the LORD, his offering shall be {of} fine flour; and he shall pour oil upon it, and put frankincense thereon:', 'and when any will offer a meat offering unto the lord his offering shall be of fine flour and he shall pour oil upon it and put frankincense thereon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 2, 'And he shall bring it to Aaron''s sons the priests: and he shall take thereout his handful of the flour thereof, and of the oil thereof, with all the frankincense thereof; and the priest shall burn the memorial of it upon the altar, {to be} an offering made by fire, of a sweet savour unto the LORD:', 'and he shall bring it to aaron s sons the priests and he shall take thereout his handful of the flour thereof and of the oil thereof with all the frankincense thereof and the priest shall burn the memorial of it upon the altar to be an offering made by fire of a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 3, 'And the remnant of the meat offering {shall be} Aaron''s and his sons'': {it is} a thing most holy of the offerings of the LORD made by fire.', 'and the remnant of the meat offering shall be aaron s and his sons it is a thing most holy of the offerings of the lord made by fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 4, 'And if thou bring an oblation of a meat offering baken in the oven, {it shall be} unleavened cakes of fine flour mingled with oil, or unleavened wafers anointed with oil.', 'and if thou bring an oblation of a meat offering baken in the oven it shall be unleavened cakes of fine flour mingled with oil or unleavened wafers anointed with oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 5, 'And if thy oblation {be} a meat offering {baken} in a pan, it shall be {of} fine flour unleavened, mingled with oil. {in a pan: or, on a flat plate, or, slice}', 'and if thy oblation be a meat offering baken in a pan it shall be of fine flour unleavened mingled with oil in a pan or on a flat plate or slice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 6, 'Thou shalt part it in pieces, and pour oil thereon: it {is} a meat offering.', 'thou shalt part it in pieces and pour oil thereon it is a meat offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 7, 'And if thy oblation {be} a meat offering {baken} in the fryingpan, it shall be made {of} fine flour with oil.', 'and if thy oblation be a meat offering baken in the fryingpan it shall be made of fine flour with oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 8, 'And thou shalt bring the meat offering that is made of these things unto the LORD: and when it is presented unto the priest, he shall bring it unto the altar.', 'and thou shalt bring the meat offering that is made of these things unto the lord and when it is presented unto the priest he shall bring it unto the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 9, 'And the priest shall take from the meat offering a memorial thereof, and shall burn {it} upon the altar: {it is} an offering made by fire, of a sweet savour unto the LORD.', 'and the priest shall take from the meat offering a memorial thereof and shall burn it upon the altar it is an offering made by fire of a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 10, 'And that which is left of the meat offering {shall be} Aaron''s and his sons'': {it is} a thing most holy of the offerings of the LORD made by fire.', 'and that which is left of the meat offering shall be aaron s and his sons it is a thing most holy of the offerings of the lord made by fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 11, 'No meat offering, which ye shall bring unto the LORD, shall be made with leaven: for ye shall burn no leaven, nor any honey, in any offering of the LORD made by fire.', 'no meat offering which ye shall bring unto the lord shall be made with leaven for ye shall burn no leaven nor any honey in any offering of the lord made by fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 12, 'As for the oblation of the firstfruits, ye shall offer them unto the LORD: but they shall not be burnt on the altar for a sweet savour. {be burnt: Heb. ascend}', 'as for the oblation of the firstfruits ye shall offer them unto the lord but they shall not be burnt on the altar for a sweet savour be burnt heb ascend');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 13, 'And every oblation of thy meat offering shalt thou season with salt; neither shalt thou suffer the salt of the covenant of thy God to be lacking from thy meat offering: with all thine offerings thou shalt offer salt.', 'and every oblation of thy meat offering shalt thou season with salt neither shalt thou suffer the salt of the covenant of thy god to be lacking from thy meat offering with all thine offerings thou shalt offer salt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 14, 'And if thou offer a meat offering of thy firstfruits unto the LORD, thou shalt offer for the meat offering of thy firstfruits green ears of corn dried by the fire, {even} corn beaten out of full ears.', 'and if thou offer a meat offering of thy firstfruits unto the lord thou shalt offer for the meat offering of thy firstfruits green ears of corn dried by the fire even corn beaten out of full ears');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 15, 'And thou shalt put oil upon it, and lay frankincense thereon: it {is} a meat offering.', 'and thou shalt put oil upon it and lay frankincense thereon it is a meat offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 2, 16, 'And the priest shall burn the memorial of it, {part} of the beaten corn thereof, and {part} of the oil thereof, with all the frankincense thereof: {it is} an offering made by fire unto the LORD.', 'and the priest shall burn the memorial of it part of the beaten corn thereof and part of the oil thereof with all the frankincense thereof it is an offering made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 3, 1, 'And if his oblation {be} a sacrifice of peace offering, if he offer {it} of the herd; whether {it be} a male or female, he shall offer it without blemish before the LORD.', 'and if his oblation be a sacrifice of peace offering if he offer it of the herd whether it be a male or female he shall offer it without blemish before the lord');
