INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 1, 'And if a soul sin, and hear the voice of swearing, and {is} a witness, whether he hath seen or known {of it}; if he do not utter {it}, then he shall bear his iniquity.', 'and if a soul sin and hear the voice of swearing and is a witness whether he hath seen or known of it if he do not utter it then he shall bear his iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 2, 'Or if a soul touch any unclean thing, whether {it be} a carcase of an unclean beast, or a carcase of unclean cattle, or the carcase of unclean creeping things, and {if} it be hidden from him; he also shall be unclean, and guilty.', 'or if a soul touch any unclean thing whether it be a carcase of an unclean beast or a carcase of unclean cattle or the carcase of unclean creeping things and if it be hidden from him he also shall be unclean and guilty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 3, 'Or if he touch the uncleanness of man, whatsoever uncleanness {it be} that a man shall be defiled withal, and it be hid from him; when he knoweth {of it}, then he shall be guilty.', 'or if he touch the uncleanness of man whatsoever uncleanness it be that a man shall be defiled withal and it be hid from him when he knoweth of it then he shall be guilty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 4, 'Or if a soul swear, pronouncing with {his} lips to do evil, or to do good, whatsoever {it be} that a man shall pronounce with an oath, and it be hid from him; when he knoweth {of it}, then he shall be guilty in one of these.', 'or if a soul swear pronouncing with his lips to do evil or to do good whatsoever it be that a man shall pronounce with an oath and it be hid from him when he knoweth of it then he shall be guilty in one of these');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 5, 'And it shall be, when he shall be guilty in one of these {things}, that he shall confess that he hath sinned in that {thing}:', 'and it shall be when he shall be guilty in one of these things that he shall confess that he hath sinned in that thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 6, 'And he shall bring his trespass offering unto the LORD for his sin which he hath sinned, a female from the flock, a lamb or a kid of the goats, for a sin offering; and the priest shall make an atonement for him concerning his sin.', 'and he shall bring his trespass offering unto the lord for his sin which he hath sinned a female from the flock a lamb or a kid of the goats for a sin offering and the priest shall make an atonement for him concerning his sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 7, 'And if he be not able to bring a lamb, then he shall bring for his trespass, which he hath committed, two turtledoves, or two young pigeons, unto the LORD; one for a sin offering, and the other for a burnt offering. {he be...: Heb. his hand cannot reach to the sufficiency of a lamb}', 'and if he be not able to bring a lamb then he shall bring for his trespass which he hath committed two turtledoves or two young pigeons unto the lord one for a sin offering and the other for a burnt offering he be heb his hand cannot reach to the sufficiency of a lamb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 8, 'And he shall bring them unto the priest, who shall offer {that} which {is} for the sin offering first, and wring off his head from his neck, but shall not divide {it} asunder:', 'and he shall bring them unto the priest who shall offer that which is for the sin offering first and wring off his head from his neck but shall not divide it asunder');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 9, 'And he shall sprinkle of the blood of the sin offering upon the side of the altar; and the rest of the blood shall be wrung out at the bottom of the altar: it {is} a sin offering.', 'and he shall sprinkle of the blood of the sin offering upon the side of the altar and the rest of the blood shall be wrung out at the bottom of the altar it is a sin offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 10, 'And he shall offer the second {for} a burnt offering, according to the manner: and the priest shall make an atonement for him for his sin which he hath sinned, and it shall be forgiven him. {manner: or, ordinance}', 'and he shall offer the second for a burnt offering according to the manner and the priest shall make an atonement for him for his sin which he hath sinned and it shall be forgiven him manner or ordinance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 11, 'But if he be not able to bring two turtledoves, or two young pigeons, then he that sinned shall bring for his offering the tenth part of an ephah of fine flour for a sin offering; he shall put no oil upon it, neither shall he put {any} frankincense thereon: for it {is} a sin offering.', 'but if he be not able to bring two turtledoves or two young pigeons then he that sinned shall bring for his offering the tenth part of an ephah of fine flour for a sin offering he shall put no oil upon it neither shall he put any frankincense thereon for it is a sin offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 12, 'Then shall he bring it to the priest, and the priest shall take his handful of it, {even} a memorial thereof, and burn {it} on the altar, according to the offerings made by fire unto the LORD: it {is} a sin offering.', 'then shall he bring it to the priest and the priest shall take his handful of it even a memorial thereof and burn it on the altar according to the offerings made by fire unto the lord it is a sin offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 13, 'And the priest shall make an atonement for him as touching his sin that he hath sinned in one of these, and it shall be forgiven him: and {the remnant} shall be the priest''s, as a meat offering.', 'and the priest shall make an atonement for him as touching his sin that he hath sinned in one of these and it shall be forgiven him and the remnant shall be the priest s as a meat offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 14, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 15, 'If a soul commit a trespass, and sin through ignorance, in the holy things of the LORD; then he shall bring for his trespass unto the LORD a ram without blemish out of the flocks, with thy estimation by shekels of silver, after the shekel of the sanctuary, for a trespass offering:', 'if a soul commit a trespass and sin through ignorance in the holy things of the lord then he shall bring for his trespass unto the lord a ram without blemish out of the flocks with thy estimation by shekels of silver after the shekel of the sanctuary for a trespass offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 16, 'And he shall make amends for the harm that he hath done in the holy thing, and shall add the fifth part thereto, and give it unto the priest: and the priest shall make an atonement for him with the ram of the trespass offering, and it shall be forgiven him.', 'and he shall make amends for the harm that he hath done in the holy thing and shall add the fifth part thereto and give it unto the priest and the priest shall make an atonement for him with the ram of the trespass offering and it shall be forgiven him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 17, 'And if a soul sin, and commit any of these things which are forbidden to be done by the commandments of the LORD; though he wist {it} not, yet is he guilty, and shall bear his iniquity.', 'and if a soul sin and commit any of these things which are forbidden to be done by the commandments of the lord though he wist it not yet is he guilty and shall bear his iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 18, 'And he shall bring a ram without blemish out of the flock, with thy estimation, for a trespass offering, unto the priest: and the priest shall make an atonement for him concerning his ignorance wherein he erred and wist {it} not, and it shall be forgiven him.', 'and he shall bring a ram without blemish out of the flock with thy estimation for a trespass offering unto the priest and the priest shall make an atonement for him concerning his ignorance wherein he erred and wist it not and it shall be forgiven him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 5, 19, 'It {is} a trespass offering: he hath certainly trespassed against the LORD.', 'it is a trespass offering he hath certainly trespassed against the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 2, 'If a soul sin, and commit a trespass against the LORD, and lie unto his neighbour in that which was delivered him to keep, or in fellowship, or in a thing taken away by violence, or hath deceived his neighbour; {in fellowship: or, in dealing} {fellowship: Heb. putting of the hand}', 'if a soul sin and commit a trespass against the lord and lie unto his neighbour in that which was delivered him to keep or in fellowship or in a thing taken away by violence or hath deceived his neighbour in fellowship or in dealing fellowship heb putting of the hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 3, 'Or have found that which was lost, and lieth concerning it, and sweareth falsely; in any of all these that a man doeth, sinning therein:', 'or have found that which was lost and lieth concerning it and sweareth falsely in any of all these that a man doeth sinning therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 4, 'Then it shall be, because he hath sinned, and is guilty, that he shall restore that which he took violently away, or the thing which he hath deceitfully gotten, or that which was delivered him to keep, or the lost thing which he found,', 'then it shall be because he hath sinned and is guilty that he shall restore that which he took violently away or the thing which he hath deceitfully gotten or that which was delivered him to keep or the lost thing which he found');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 5, 'Or all that about which he hath sworn falsely; he shall even restore it in the principal, and shall add the fifth part more thereto, {and} give it unto him to whom it appertaineth, in the day of his trespass offering. {in the day...: or, in the day of his being found guilty: Heb. in the day of his trespass}', 'or all that about which he hath sworn falsely he shall even restore it in the principal and shall add the fifth part more thereto and give it unto him to whom it appertaineth in the day of his trespass offering in the day or in the day of his being found guilty heb in the day of his trespass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 6, 'And he shall bring his trespass offering unto the LORD, a ram without blemish out of the flock, with thy estimation, for a trespass offering, unto the priest:', 'and he shall bring his trespass offering unto the lord a ram without blemish out of the flock with thy estimation for a trespass offering unto the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 7, 'And the priest shall make an atonement for him before the LORD: and it shall be forgiven him for any thing of all that he hath done in trespassing therein.', 'and the priest shall make an atonement for him before the lord and it shall be forgiven him for any thing of all that he hath done in trespassing therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 8, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 9, 'Command Aaron and his sons, saying, This {is} the law of the burnt offering: It {is} the burnt offering, because of the burning upon the altar all night unto the morning, and the fire of the altar shall be burning in it. {because...: or, for the burning}', 'command aaron and his sons saying this is the law of the burnt offering it is the burnt offering because of the burning upon the altar all night unto the morning and the fire of the altar shall be burning in it because or for the burning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 10, 'And the priest shall put on his linen garment, and his linen breeches shall he put upon his flesh, and take up the ashes which the fire hath consumed with the burnt offering on the altar, and he shall put them beside the altar.', 'and the priest shall put on his linen garment and his linen breeches shall he put upon his flesh and take up the ashes which the fire hath consumed with the burnt offering on the altar and he shall put them beside the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 11, 'And he shall put off his garments, and put on other garments, and carry forth the ashes without the camp unto a clean place.', 'and he shall put off his garments and put on other garments and carry forth the ashes without the camp unto a clean place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 12, 'And the fire upon the altar shall be burning in it; it shall not be put out: and the priest shall burn wood on it every morning, and lay the burnt offering in order upon it; and he shall burn thereon the fat of the peace offerings.', 'and the fire upon the altar shall be burning in it it shall not be put out and the priest shall burn wood on it every morning and lay the burnt offering in order upon it and he shall burn thereon the fat of the peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 13, 'The fire shall ever be burning upon the altar; it shall never go out.', 'the fire shall ever be burning upon the altar it shall never go out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 14, 'And this {is} the law of the meat offering: the sons of Aaron shall offer it before the LORD, before the altar.', 'and this is the law of the meat offering the sons of aaron shall offer it before the lord before the altar');
