INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 16, 'And the remainder thereof shall Aaron and his sons eat: with unleavened bread shall it be eaten in the holy place; in the court of the tabernacle of the congregation they shall eat it.', 'and the remainder thereof shall aaron and his sons eat with unleavened bread shall it be eaten in the holy place in the court of the tabernacle of the congregation they shall eat it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 17, 'It shall not be baken with leaven. I have given it {unto them for} their portion of my offerings made by fire; it {is} most holy, as {is} the sin offering, and as the trespass offering.', 'it shall not be baken with leaven i have given it unto them for their portion of my offerings made by fire it is most holy as is the sin offering and as the trespass offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 18, 'All the males among the children of Aaron shall eat of it. {It shall be} a statute for ever in your generations concerning the offerings of the LORD made by fire: every one that toucheth them shall be holy.', 'all the males among the children of aaron shall eat of it it shall be a statute for ever in your generations concerning the offerings of the lord made by fire every one that toucheth them shall be holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 19, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 20, 'This {is} the offering of Aaron and of his sons, which they shall offer unto the LORD in the day when he is anointed; the tenth part of an ephah of fine flour for a meat offering perpetual, half of it in the morning, and half thereof at night.', 'this is the offering of aaron and of his sons which they shall offer unto the lord in the day when he is anointed the tenth part of an ephah of fine flour for a meat offering perpetual half of it in the morning and half thereof at night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 21, 'In a pan it shall be made with oil; {and when it is} baken, thou shalt bring it in: {and} the baken pieces of the meat offering shalt thou offer {for} a sweet savour unto the LORD.', 'in a pan it shall be made with oil and when it is baken thou shalt bring it in and the baken pieces of the meat offering shalt thou offer for a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 22, 'And the priest of his sons that is anointed in his stead shall offer it: {it is} a statute for ever unto the LORD; it shall be wholly burnt.', 'and the priest of his sons that is anointed in his stead shall offer it it is a statute for ever unto the lord it shall be wholly burnt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 23, 'For every meat offering for the priest shall be wholly burnt: it shall not be eaten.', 'for every meat offering for the priest shall be wholly burnt it shall not be eaten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 24, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 25, 'Speak unto Aaron and to his sons, saying, This {is} the law of the sin offering: In the place where the burnt offering is killed shall the sin offering be killed before the LORD: it {is} most holy.', 'speak unto aaron and to his sons saying this is the law of the sin offering in the place where the burnt offering is killed shall the sin offering be killed before the lord it is most holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 26, 'The priest that offereth it for sin shall eat it: in the holy place shall it be eaten, in the court of the tabernacle of the congregation.', 'the priest that offereth it for sin shall eat it in the holy place shall it be eaten in the court of the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 27, 'Whatsoever shall touch the flesh thereof shall be holy: and when there is sprinkled of the blood thereof upon any garment, thou shalt wash that whereon it was sprinkled in the holy place.', 'whatsoever shall touch the flesh thereof shall be holy and when there is sprinkled of the blood thereof upon any garment thou shalt wash that whereon it was sprinkled in the holy place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 28, 'But the earthen vessel wherein it is sodden shall be broken: and if it be sodden in a brasen pot, it shall be both scoured, and rinsed in water.', 'but the earthen vessel wherein it is sodden shall be broken and if it be sodden in a brasen pot it shall be both scoured and rinsed in water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 29, 'All the males among the priests shall eat thereof: it {is} most holy.', 'all the males among the priests shall eat thereof it is most holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 6, 30, 'And no sin offering, whereof {any} of the blood is brought into the tabernacle of the congregation to reconcile {withal} in the holy {place}, shall be eaten: it shall be burnt in the fire.', 'and no sin offering whereof any of the blood is brought into the tabernacle of the congregation to reconcile withal in the holy place shall be eaten it shall be burnt in the fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 1, 'Likewise this {is} the law of the trespass offering: it {is} most holy.', 'likewise this is the law of the trespass offering it is most holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 2, 'In the place where they kill the burnt offering shall they kill the trespass offering: and the blood thereof shall he sprinkle round about upon the altar.', 'in the place where they kill the burnt offering shall they kill the trespass offering and the blood thereof shall he sprinkle round about upon the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 3, 'And he shall offer of it all the fat thereof; the rump, and the fat that covereth the inwards,', 'and he shall offer of it all the fat thereof the rump and the fat that covereth the inwards');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 4, 'And the two kidneys, and the fat that {is} on them, which {is} by the flanks, and the caul {that is} above the liver, with the kidneys, it shall he take away:', 'and the two kidneys and the fat that is on them which is by the flanks and the caul that is above the liver with the kidneys it shall he take away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 5, 'And the priest shall burn them upon the altar {for} an offering made by fire unto the LORD: it {is} a trespass offering.', 'and the priest shall burn them upon the altar for an offering made by fire unto the lord it is a trespass offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 6, 'Every male among the priests shall eat thereof: it shall be eaten in the holy place: it {is} most holy.', 'every male among the priests shall eat thereof it shall be eaten in the holy place it is most holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 7, 'As the sin offering {is}, so {is} the trespass offering: {there is} one law for them: the priest that maketh atonement therewith shall have {it}.', 'as the sin offering is so is the trespass offering there is one law for them the priest that maketh atonement therewith shall have it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 8, 'And the priest that offereth any man''s burnt offering, {even} the priest shall have to himself the skin of the burnt offering which he hath offered.', 'and the priest that offereth any man s burnt offering even the priest shall have to himself the skin of the burnt offering which he hath offered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 9, 'And all the meat offering that is baken in the oven, and all that is dressed in the fryingpan, and in the pan, shall be the priest''s that offereth it. {in the pan: or, on the flat plate or, slice}', 'and all the meat offering that is baken in the oven and all that is dressed in the fryingpan and in the pan shall be the priest s that offereth it in the pan or on the flat plate or slice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 10, 'And every meat offering, mingled with oil, and dry, shall all the sons of Aaron have, one {as much} as another.', 'and every meat offering mingled with oil and dry shall all the sons of aaron have one as much as another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 11, 'And this {is} the law of the sacrifice of peace offerings, which he shall offer unto the LORD.', 'and this is the law of the sacrifice of peace offerings which he shall offer unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 12, 'If he offer it for a thanksgiving, then he shall offer with the sacrifice of thanksgiving unleavened cakes mingled with oil, and unleavened wafers anointed with oil, and cakes mingled with oil, of fine flour, fried.', 'if he offer it for a thanksgiving then he shall offer with the sacrifice of thanksgiving unleavened cakes mingled with oil and unleavened wafers anointed with oil and cakes mingled with oil of fine flour fried');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 13, 'Besides the cakes, he shall offer {for} his offering leavened bread with the sacrifice of thanksgiving of his peace offerings.', 'besides the cakes he shall offer for his offering leavened bread with the sacrifice of thanksgiving of his peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 14, 'And of it he shall offer one out of the whole oblation {for} an heave offering unto the LORD, {and} it shall be the priest''s that sprinkleth the blood of the peace offerings.', 'and of it he shall offer one out of the whole oblation for an heave offering unto the lord and it shall be the priest s that sprinkleth the blood of the peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 15, 'And the flesh of the sacrifice of his peace offerings for thanksgiving shall be eaten the same day that it is offered; he shall not leave any of it until the morning.', 'and the flesh of the sacrifice of his peace offerings for thanksgiving shall be eaten the same day that it is offered he shall not leave any of it until the morning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 16, 'But if the sacrifice of his offering {be} a vow, or a voluntary offering, it shall be eaten the same day that he offereth his sacrifice: and on the morrow also the remainder of it shall be eaten:', 'but if the sacrifice of his offering be a vow or a voluntary offering it shall be eaten the same day that he offereth his sacrifice and on the morrow also the remainder of it shall be eaten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 17, 'But the remainder of the flesh of the sacrifice on the third day shall be burnt with fire.', 'but the remainder of the flesh of the sacrifice on the third day shall be burnt with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 18, 'And if {any} of the flesh of the sacrifice of his peace offerings be eaten at all on the third day, it shall not be accepted, neither shall it be imputed unto him that offereth it: it shall be an abomination, and the soul that eateth of it shall bear his iniquity.', 'and if any of the flesh of the sacrifice of his peace offerings be eaten at all on the third day it shall not be accepted neither shall it be imputed unto him that offereth it it shall be an abomination and the soul that eateth of it shall bear his iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 19, 'And the flesh that toucheth any unclean {thing} shall not be eaten; it shall be burnt with fire: and as for the flesh, all that be clean shall eat thereof.', 'and the flesh that toucheth any unclean thing shall not be eaten it shall be burnt with fire and as for the flesh all that be clean shall eat thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 20, 'But the soul that eateth {of} the flesh of the sacrifice of peace offerings, that {pertain} unto the LORD, having his uncleanness upon him, even that soul shall be cut off from his people.', 'but the soul that eateth of the flesh of the sacrifice of peace offerings that pertain unto the lord having his uncleanness upon him even that soul shall be cut off from his people');
