INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 22, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 23, 'Speak unto the children of Israel, saying, Ye shall eat no manner of fat, of ox, or of sheep, or of goat.', 'speak unto the children of israel saying ye shall eat no manner of fat of ox or of sheep or of goat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 24, 'And the fat of the beast that dieth of itself, and the fat of that which is torn with beasts, may be used in any other use: but ye shall in no wise eat of it. {beast...: Heb. carcase}', 'and the fat of the beast that dieth of itself and the fat of that which is torn with beasts may be used in any other use but ye shall in no wise eat of it beast heb carcase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 25, 'For whosoever eateth the fat of the beast, of which men offer an offering made by fire unto the LORD, even the soul that eateth {it} shall be cut off from his people.', 'for whosoever eateth the fat of the beast of which men offer an offering made by fire unto the lord even the soul that eateth it shall be cut off from his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 26, 'Moreover ye shall eat no manner of blood, {whether it be} of fowl or of beast, in any of your dwellings.', 'moreover ye shall eat no manner of blood whether it be of fowl or of beast in any of your dwellings');
