INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 29, 'Speak unto the children of Israel, saying, He that offereth the sacrifice of his peace offerings unto the LORD shall bring his oblation unto the LORD of the sacrifice of his peace offerings.', 'speak unto the children of israel saying he that offereth the sacrifice of his peace offerings unto the lord shall bring his oblation unto the lord of the sacrifice of his peace offerings');
