INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 31, 'And the priest shall burn the fat upon the altar: but the breast shall be Aaron''s and his sons''.', 'and the priest shall burn the fat upon the altar but the breast shall be aaron s and his sons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 32, 'And the right shoulder shall ye give unto the priest {for} an heave offering of the sacrifices of your peace offerings.', 'and the right shoulder shall ye give unto the priest for an heave offering of the sacrifices of your peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 33, 'He among the sons of Aaron, that offereth the blood of the peace offerings, and the fat, shall have the right shoulder for {his} part.', 'he among the sons of aaron that offereth the blood of the peace offerings and the fat shall have the right shoulder for his part');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 34, 'For the wave breast and the heave shoulder have I taken of the children of Israel from off the sacrifices of their peace offerings, and have given them unto Aaron the priest and unto his sons by a statute for ever from among the children of Israel.', 'for the wave breast and the heave shoulder have i taken of the children of israel from off the sacrifices of their peace offerings and have given them unto aaron the priest and unto his sons by a statute for ever from among the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 35, 'This {is the portion} of the anointing of Aaron, and of the anointing of his sons, out of the offerings of the LORD made by fire, in the day {when} he presented them to minister unto the LORD in the priest''s office;', 'this is the portion of the anointing of aaron and of the anointing of his sons out of the offerings of the lord made by fire in the day when he presented them to minister unto the lord in the priest s office');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 36, 'Which the LORD commanded to be given them of the children of Israel, in the day that he anointed them, {by} a statute for ever throughout their generations.', 'which the lord commanded to be given them of the children of israel in the day that he anointed them by a statute for ever throughout their generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 37, 'This {is} the law of the burnt offering, of the meat offering, and of the sin offering, and of the trespass offering, and of the consecrations, and of the sacrifice of the peace offerings;', 'this is the law of the burnt offering of the meat offering and of the sin offering and of the trespass offering and of the consecrations and of the sacrifice of the peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 7, 38, 'Which the LORD commanded Moses in mount Sinai, in the day that he commanded the children of Israel to offer their oblations unto the LORD, in the wilderness of Sinai.', 'which the lord commanded moses in mount sinai in the day that he commanded the children of israel to offer their oblations unto the lord in the wilderness of sinai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 2, 'Take Aaron and his sons with him, and the garments, and the anointing oil, and a bullock for the sin offering, and two rams, and a basket of unleavened bread;', 'take aaron and his sons with him and the garments and the anointing oil and a bullock for the sin offering and two rams and a basket of unleavened bread');
