INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 7, 'And he put upon him the coat, and girded him with the girdle, and clothed him with the robe, and put the ephod upon him, and he girded him with the curious girdle of the ephod, and bound {it} unto him therewith.', 'and he put upon him the coat and girded him with the girdle and clothed him with the robe and put the ephod upon him and he girded him with the curious girdle of the ephod and bound it unto him therewith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 8, 'And he put the breastplate upon him: also he put in the breastplate the Urim and the Thummim.', 'and he put the breastplate upon him also he put in the breastplate the urim and the thummim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 9, 'And he put the mitre upon his head; also upon the mitre, {even} upon his forefront, did he put the golden plate, the holy crown; as the LORD commanded Moses.', 'and he put the mitre upon his head also upon the mitre even upon his forefront did he put the golden plate the holy crown as the lord commanded moses');
