INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 13, 'And Moses brought Aaron''s sons, and put coats upon them, and girded them with girdles, and put bonnets upon them; as the LORD commanded Moses. {put bonnets: Heb. bound bonnets}', 'and moses brought aaron s sons and put coats upon them and girded them with girdles and put bonnets upon them as the lord commanded moses put bonnets heb bound bonnets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 14, 'And he brought the bullock for the sin offering: and Aaron and his sons laid their hands upon the head of the bullock for the sin offering.', 'and he brought the bullock for the sin offering and aaron and his sons laid their hands upon the head of the bullock for the sin offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 15, 'And he slew {it}; and Moses took the blood, and put {it} upon the horns of the altar round about with his finger, and purified the altar, and poured the blood at the bottom of the altar, and sanctified it, to make reconciliation upon it.', 'and he slew it and moses took the blood and put it upon the horns of the altar round about with his finger and purified the altar and poured the blood at the bottom of the altar and sanctified it to make reconciliation upon it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 16, 'And he took all the fat that {was} upon the inwards, and the caul {above} the liver, and the two kidneys, and their fat, and Moses burned {it} upon the altar.', 'and he took all the fat that was upon the inwards and the caul above the liver and the two kidneys and their fat and moses burned it upon the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 17, 'But the bullock, and his hide, his flesh, and his dung, he burnt with fire without the camp; as the LORD commanded Moses.', 'but the bullock and his hide his flesh and his dung he burnt with fire without the camp as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 18, 'And he brought the ram for the burnt offering: and Aaron and his sons laid their hands upon the head of the ram.', 'and he brought the ram for the burnt offering and aaron and his sons laid their hands upon the head of the ram');
