INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 21, 'And he washed the inwards and the legs in water; and Moses burnt the whole ram upon the altar: it {was} a burnt sacrifice for a sweet savour, {and} an offering made by fire unto the LORD; as the LORD commanded Moses.', 'and he washed the inwards and the legs in water and moses burnt the whole ram upon the altar it was a burnt sacrifice for a sweet savour and an offering made by fire unto the lord as the lord commanded moses');
