INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 26, 'And out of the basket of unleavened bread, that {was} before the LORD, he took one unleavened cake, and a cake of oiled bread, and one wafer, and put {them} on the fat, and upon the right shoulder:', 'and out of the basket of unleavened bread that was before the lord he took one unleavened cake and a cake of oiled bread and one wafer and put them on the fat and upon the right shoulder');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 27, 'And he put all upon Aaron''s hands, and upon his sons'' hands, and waved them {for} a wave offering before the LORD.', 'and he put all upon aaron s hands and upon his sons hands and waved them for a wave offering before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 28, 'And Moses took them from off their hands, and burnt {them} on the altar upon the burnt offering: they {were} consecrations for a sweet savour: it {is} an offering made by fire unto the LORD.', 'and moses took them from off their hands and burnt them on the altar upon the burnt offering they were consecrations for a sweet savour it is an offering made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 29, 'And Moses took the breast, and waved it {for} a wave offering before the LORD: {for} of the ram of consecration it was Moses'' part; as the LORD commanded Moses.', 'and moses took the breast and waved it for a wave offering before the lord for of the ram of consecration it was moses part as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 30, 'And Moses took of the anointing oil, and of the blood which {was} upon the altar, and sprinkled {it} upon Aaron, {and} upon his garments, and upon his sons, and upon his sons'' garments with him; and sanctified Aaron, {and} his garments, and his sons, and his sons'' garments with him.', 'and moses took of the anointing oil and of the blood which was upon the altar and sprinkled it upon aaron and upon his garments and upon his sons and upon his sons garments with him and sanctified aaron and his garments and his sons and his sons garments with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 31, 'And Moses said unto Aaron and to his sons, Boil the flesh {at} the door of the tabernacle of the congregation: and there eat it with the bread that {is} in the basket of consecrations, as I commanded, saying, Aaron and his sons shall eat it.', 'and moses said unto aaron and to his sons boil the flesh at the door of the tabernacle of the congregation and there eat it with the bread that is in the basket of consecrations as i commanded saying aaron and his sons shall eat it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 32, 'And that which remaineth of the flesh and of the bread shall ye burn with fire.', 'and that which remaineth of the flesh and of the bread shall ye burn with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 33, 'And ye shall not go out of the door of the tabernacle of the congregation {in} seven days, until the days of your consecration be at an end: for seven days shall he consecrate you.', 'and ye shall not go out of the door of the tabernacle of the congregation in seven days until the days of your consecration be at an end for seven days shall he consecrate you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 34, 'As he hath done this day, {so} the LORD hath commanded to do, to make an atonement for you.', 'as he hath done this day so the lord hath commanded to do to make an atonement for you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 8, 35, 'Therefore shall ye abide {at} the door of the tabernacle of the congregation day and night seven days, and keep the charge of the LORD, that ye die not: for so I am commanded.', 'therefore shall ye abide at the door of the tabernacle of the congregation day and night seven days and keep the charge of the lord that ye die not for so i am commanded');
