INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 9, 6, 'And Moses said, This {is} the thing which the LORD commanded that ye should do: and the glory of the LORD shall appear unto you.', 'and moses said this is the thing which the lord commanded that ye should do and the glory of the lord shall appear unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 9, 7, 'And Moses said unto Aaron, Go unto the altar, and offer thy sin offering, and thy burnt offering, and make an atonement for thyself, and for the people: and offer the offering of the people, and make an atonement for them; as the LORD commanded.', 'and moses said unto aaron go unto the altar and offer thy sin offering and thy burnt offering and make an atonement for thyself and for the people and offer the offering of the people and make an atonement for them as the lord commanded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 9, 8, 'Aaron therefore went unto the altar, and slew the calf of the sin offering, which {was} for himself.', 'aaron therefore went unto the altar and slew the calf of the sin offering which was for himself');
