INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 9, 22, 'And Aaron lifted up his hand toward the people, and blessed them, and came down from offering of the sin offering, and the burnt offering, and peace offerings.', 'and aaron lifted up his hand toward the people and blessed them and came down from offering of the sin offering and the burnt offering and peace offerings');
