INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 9, 24, 'And there came a fire out from before the LORD, and consumed upon the altar the burnt offering and the fat: {which} when all the people saw, they shouted, and fell on their faces.', 'and there came a fire out from before the lord and consumed upon the altar the burnt offering and the fat which when all the people saw they shouted and fell on their faces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 1, 'And Nadab and Abihu, the sons of Aaron, took either of them his censer, and put fire therein, and put incense thereon, and offered strange fire before the LORD, which he commanded them not.', 'and nadab and abihu the sons of aaron took either of them his censer and put fire therein and put incense thereon and offered strange fire before the lord which he commanded them not');
