INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 3, 'Then Moses said unto Aaron, This {is it} that the LORD spake, saying, I will be sanctified in them that come nigh me, and before all the people I will be glorified. And Aaron held his peace.', 'then moses said unto aaron this is it that the lord spake saying i will be sanctified in them that come nigh me and before all the people i will be glorified and aaron held his peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 4, 'And Moses called Mishael and Elzaphan, the sons of Uzziel the uncle of Aaron, and said unto them, Come near, carry your brethren from before the sanctuary out of the camp.', 'and moses called mishael and elzaphan the sons of uzziel the uncle of aaron and said unto them come near carry your brethren from before the sanctuary out of the camp');
