INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 6, 'And Moses said unto Aaron, and unto Eleazar and unto Ithamar, his sons, Uncover not your heads, neither rend your clothes; lest ye die, and lest wrath come upon all the people: but let your brethren, the whole house of Israel, bewail the burning which the LORD hath kindled.', 'and moses said unto aaron and unto eleazar and unto ithamar his sons uncover not your heads neither rend your clothes lest ye die and lest wrath come upon all the people but let your brethren the whole house of israel bewail the burning which the lord hath kindled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 7, 'And ye shall not go out from the door of the tabernacle of the congregation, lest ye die: for the anointing oil of the LORD {is} upon you. And they did according to the word of Moses.', 'and ye shall not go out from the door of the tabernacle of the congregation lest ye die for the anointing oil of the lord is upon you and they did according to the word of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 8, 'And the LORD spake unto Aaron, saying,', 'and the lord spake unto aaron saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 9, 'Do not drink wine nor strong drink, thou, nor thy sons with thee, when ye go into the tabernacle of the congregation, lest ye die: {it shall be} a statute for ever throughout your generations:', 'do not drink wine nor strong drink thou nor thy sons with thee when ye go into the tabernacle of the congregation lest ye die it shall be a statute for ever throughout your generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 10, 'And that ye may put difference between holy and unholy, and between unclean and clean;', 'and that ye may put difference between holy and unholy and between unclean and clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 11, 'And that ye may teach the children of Israel all the statutes which the LORD hath spoken unto them by the hand of Moses.', 'and that ye may teach the children of israel all the statutes which the lord hath spoken unto them by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 12, 'And Moses spake unto Aaron, and unto Eleazar and unto Ithamar, his sons that were left, Take the meat offering that remaineth of the offerings of the LORD made by fire, and eat it without leaven beside the altar: for it {is} most holy:', 'and moses spake unto aaron and unto eleazar and unto ithamar his sons that were left take the meat offering that remaineth of the offerings of the lord made by fire and eat it without leaven beside the altar for it is most holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 13, 'And ye shall eat it in the holy place, because it {is} thy due, and thy sons'' due, of the sacrifices of the LORD made by fire: for so I am commanded.', 'and ye shall eat it in the holy place because it is thy due and thy sons due of the sacrifices of the lord made by fire for so i am commanded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 14, 'And the wave breast and heave shoulder shall ye eat in a clean place; thou, and thy sons, and thy daughters with thee: for {they be} thy due, and thy sons'' due, {which} are given out of the sacrifices of peace offerings of the children of Israel.', 'and the wave breast and heave shoulder shall ye eat in a clean place thou and thy sons and thy daughters with thee for they be thy due and thy sons due which are given out of the sacrifices of peace offerings of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 15, 'The heave shoulder and the wave breast shall they bring with the offerings made by fire of the fat, to wave {it for} a wave offering before the LORD; and it shall be thine, and thy sons'' with thee, by a statute for ever; as the LORD hath commanded.', 'the heave shoulder and the wave breast shall they bring with the offerings made by fire of the fat to wave it for a wave offering before the lord and it shall be thine and thy sons with thee by a statute for ever as the lord hath commanded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 16, 'And Moses diligently sought the goat of the sin offering, and, behold, it was burnt: and he was angry with Eleazar and Ithamar, the sons of Aaron {which were} left {alive}, saying,', 'and moses diligently sought the goat of the sin offering and behold it was burnt and he was angry with eleazar and ithamar the sons of aaron which were left alive saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 17, 'Wherefore have ye not eaten the sin offering in the holy place, seeing it {is} most holy, and {God} hath given it you to bear the iniquity of the congregation, to make atonement for them before the LORD?', 'wherefore have ye not eaten the sin offering in the holy place seeing it is most holy and god hath given it you to bear the iniquity of the congregation to make atonement for them before the lord');
