INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 10, 20, 'And when Moses heard {that}, he was content.', 'and when moses heard that he was content');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 1, 'And the LORD spake unto Moses and to Aaron, saying unto them,', 'and the lord spake unto moses and to aaron saying unto them');
