INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 3, 'Whatsoever parteth the hoof, and is clovenfooted, {and} cheweth the cud, among the beasts, that shall ye eat.', 'whatsoever parteth the hoof and is clovenfooted and cheweth the cud among the beasts that shall ye eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 4, 'Nevertheless these shall ye not eat of them that chew the cud, or of them that divide the hoof: {as} the camel, because he cheweth the cud, but divideth not the hoof; he {is} unclean unto you.', 'nevertheless these shall ye not eat of them that chew the cud or of them that divide the hoof as the camel because he cheweth the cud but divideth not the hoof he is unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 5, 'And the coney, because he cheweth the cud, but divideth not the hoof; he {is} unclean unto you.', 'and the coney because he cheweth the cud but divideth not the hoof he is unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 6, 'And the hare, because he cheweth the cud, but divideth not the hoof; he {is} unclean unto you.', 'and the hare because he cheweth the cud but divideth not the hoof he is unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 7, 'And the swine, though he divide the hoof, and be clovenfooted, yet he cheweth not the cud; he {is} unclean to you.', 'and the swine though he divide the hoof and be clovenfooted yet he cheweth not the cud he is unclean to you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 8, 'Of their flesh shall ye not eat, and their carcase shall ye not touch; they {are} unclean to you.', 'of their flesh shall ye not eat and their carcase shall ye not touch they are unclean to you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 9, 'These shall ye eat of all that {are} in the waters: whatsoever hath fins and scales in the waters, in the seas, and in the rivers, them shall ye eat.', 'these shall ye eat of all that are in the waters whatsoever hath fins and scales in the waters in the seas and in the rivers them shall ye eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 10, 'And all that have not fins and scales in the seas, and in the rivers, of all that move in the waters, and of any living thing which {is} in the waters, they {shall be} an abomination unto you:', 'and all that have not fins and scales in the seas and in the rivers of all that move in the waters and of any living thing which is in the waters they shall be an abomination unto you');
