INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 12, 'Whatsoever hath no fins nor scales in the waters, that {shall be} an abomination unto you.', 'whatsoever hath no fins nor scales in the waters that shall be an abomination unto you');
