INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 23, 'But all {other} flying creeping things, which have four feet, {shall be} an abomination unto you.', 'but all other flying creeping things which have four feet shall be an abomination unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 24, 'And for these ye shall be unclean: whosoever toucheth the carcase of them shall be unclean until the even.', 'and for these ye shall be unclean whosoever toucheth the carcase of them shall be unclean until the even');
