INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 27, 'And whatsoever goeth upon his paws, among all manner of beasts that go on {all} four, those {are} unclean unto you: whoso toucheth their carcase shall be unclean until the even.', 'and whatsoever goeth upon his paws among all manner of beasts that go on all four those are unclean unto you whoso toucheth their carcase shall be unclean until the even');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 28, 'And he that beareth the carcase of them shall wash his clothes, and be unclean until the even: they {are} unclean unto you.', 'and he that beareth the carcase of them shall wash his clothes and be unclean until the even they are unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 29, 'These also {shall be} unclean unto you among the creeping things that creep upon the earth; the weasel, and the mouse, and the tortoise after his kind,', 'these also shall be unclean unto you among the creeping things that creep upon the earth the weasel and the mouse and the tortoise after his kind');
