INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 31, 'These {are} unclean to you among all that creep: whosoever doth touch them, when they be dead, shall be unclean until the even.', 'these are unclean to you among all that creep whosoever doth touch them when they be dead shall be unclean until the even');
