INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 33, 'And every earthen vessel, whereinto {any} of them falleth, whatsoever {is} in it shall be unclean; and ye shall break it.', 'and every earthen vessel whereinto any of them falleth whatsoever is in it shall be unclean and ye shall break it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 34, 'Of all meat which may be eaten, {that} on which {such} water cometh shall be unclean: and all drink that may be drunk in every {such} vessel shall be unclean.', 'of all meat which may be eaten that on which such water cometh shall be unclean and all drink that may be drunk in every such vessel shall be unclean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 35, 'And every {thing} whereupon {any part} of their carcase falleth shall be unclean; {whether it be} oven, or ranges for pots, they shall be broken down: {for} they {are} unclean, and shall be unclean unto you.', 'and every thing whereupon any part of their carcase falleth shall be unclean whether it be oven or ranges for pots they shall be broken down for they are unclean and shall be unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 36, 'Nevertheless a fountain or pit, {wherein there is} plenty of water, shall be clean: but that which toucheth their carcase shall be unclean. {wherein...: Heb. a gathering together of waters}', 'nevertheless a fountain or pit wherein there is plenty of water shall be clean but that which toucheth their carcase shall be unclean wherein heb a gathering together of waters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 37, 'And if {any part} of their carcase fall upon any sowing seed which is to be sown, it {shall be} clean.', 'and if any part of their carcase fall upon any sowing seed which is to be sown it shall be clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 38, 'But if {any} water be put upon the seed, and {any part} of their carcase fall thereon, it {shall be} unclean unto you.', 'but if any water be put upon the seed and any part of their carcase fall thereon it shall be unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 39, 'And if any beast, of which ye may eat, die; he that toucheth the carcase thereof shall be unclean until the even.', 'and if any beast of which ye may eat die he that toucheth the carcase thereof shall be unclean until the even');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 40, 'And he that eateth of the carcase of it shall wash his clothes, and be unclean until the even: he also that beareth the carcase of it shall wash his clothes, and be unclean until the even.', 'and he that eateth of the carcase of it shall wash his clothes and be unclean until the even he also that beareth the carcase of it shall wash his clothes and be unclean until the even');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 41, 'And every creeping thing that creepeth upon the earth {shall be} an abomination; it shall not be eaten.', 'and every creeping thing that creepeth upon the earth shall be an abomination it shall not be eaten');
