INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 43, 'Ye shall not make yourselves abominable with any creeping thing that creepeth, neither shall ye make yourselves unclean with them, that ye should be defiled thereby. {yourselves abominable: Heb. your souls, etc}', 'ye shall not make yourselves abominable with any creeping thing that creepeth neither shall ye make yourselves unclean with them that ye should be defiled thereby yourselves abominable heb your souls etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 44, 'For I {am} the LORD your God: ye shall therefore sanctify yourselves, and ye shall be holy; for I {am} holy: neither shall ye defile yourselves with any manner of creeping thing that creepeth upon the earth.', 'for i am the lord your god ye shall therefore sanctify yourselves and ye shall be holy for i am holy neither shall ye defile yourselves with any manner of creeping thing that creepeth upon the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 45, 'For I {am} the LORD that bringeth you up out of the land of Egypt, to be your God: ye shall therefore be holy, for I {am} holy.', 'for i am the lord that bringeth you up out of the land of egypt to be your god ye shall therefore be holy for i am holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 46, 'This {is} the law of the beasts, and of the fowl, and of every living creature that moveth in the waters, and of every creature that creepeth upon the earth:', 'this is the law of the beasts and of the fowl and of every living creature that moveth in the waters and of every creature that creepeth upon the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 11, 47, 'To make a difference between the unclean and the clean, and between the beast that may be eaten and the beast that may not be eaten.', 'to make a difference between the unclean and the clean and between the beast that may be eaten and the beast that may not be eaten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 12, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 12, 2, 'Speak unto the children of Israel, saying, If a woman have conceived seed, and born a man child: then she shall be unclean seven days; according to the days of the separation for her infirmity shall she be unclean.', 'speak unto the children of israel saying if a woman have conceived seed and born a man child then she shall be unclean seven days according to the days of the separation for her infirmity shall she be unclean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 12, 3, 'And in the eighth day the flesh of his foreskin shall be circumcised.', 'and in the eighth day the flesh of his foreskin shall be circumcised');
