INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 12, 5, 'But if she bear a maid child, then she shall be unclean two weeks, as in her separation: and she shall continue in the blood of her purifying threescore and six days.', 'but if she bear a maid child then she shall be unclean two weeks as in her separation and she shall continue in the blood of her purifying threescore and six days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 12, 6, 'And when the days of her purifying are fulfilled, for a son, or for a daughter, she shall bring a lamb of the first year for a burnt offering, and a young pigeon, or a turtledove, for a sin offering, unto the door of the tabernacle of the congregation, unto the priest: {of the first...: Heb. a son of his year}', 'and when the days of her purifying are fulfilled for a son or for a daughter she shall bring a lamb of the first year for a burnt offering and a young pigeon or a turtledove for a sin offering unto the door of the tabernacle of the congregation unto the priest of the first heb a son of his year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 12, 7, 'Who shall offer it before the LORD, and make an atonement for her; and she shall be cleansed from the issue of her blood. This {is} the law for her that hath born a male or a female.', 'who shall offer it before the lord and make an atonement for her and she shall be cleansed from the issue of her blood this is the law for her that hath born a male or a female');
