INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 1, 'And the LORD spake unto Moses and Aaron, saying,', 'and the lord spake unto moses and aaron saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 2, 'When a man shall have in the skin of his flesh a rising, a scab, or bright spot, and it be in the skin of his flesh {like} the plague of leprosy; then he shall be brought unto Aaron the priest, or unto one of his sons the priests: {rising: or, swelling}', 'when a man shall have in the skin of his flesh a rising a scab or bright spot and it be in the skin of his flesh like the plague of leprosy then he shall be brought unto aaron the priest or unto one of his sons the priests rising or swelling');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 3, 'And the priest shall look on the plague in the skin of the flesh: and {when} the hair in the plague is turned white, and the plague in sight {be} deeper than the skin of his flesh, it {is} a plague of leprosy: and the priest shall look on him, and pronounce him unclean.', 'and the priest shall look on the plague in the skin of the flesh and when the hair in the plague is turned white and the plague in sight be deeper than the skin of his flesh it is a plague of leprosy and the priest shall look on him and pronounce him unclean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 4, 'If the bright spot {be} white in the skin of his flesh, and in sight {be} not deeper than the skin, and the hair thereof be not turned white; then the priest shall shut up {him that hath} the plague seven days:', 'if the bright spot be white in the skin of his flesh and in sight be not deeper than the skin and the hair thereof be not turned white then the priest shall shut up him that hath the plague seven days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 5, 'And the priest shall look on him the seventh day: and, behold, {if} the plague in his sight be at a stay, {and} the plague spread not in the skin; then the priest shall shut him up seven days more:', 'and the priest shall look on him the seventh day and behold if the plague in his sight be at a stay and the plague spread not in the skin then the priest shall shut him up seven days more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 6, 'And the priest shall look on him again the seventh day: and, behold, {if} the plague {be} somewhat dark, {and} the plague spread not in the skin, the priest shall pronounce him clean: it {is but} a scab: and he shall wash his clothes, and be clean.', 'and the priest shall look on him again the seventh day and behold if the plague be somewhat dark and the plague spread not in the skin the priest shall pronounce him clean it is but a scab and he shall wash his clothes and be clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 7, 'But if the scab spread much abroad in the skin, after that he hath been seen of the priest for his cleansing, he shall be seen of the priest again:', 'but if the scab spread much abroad in the skin after that he hath been seen of the priest for his cleansing he shall be seen of the priest again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 8, 'And {if} the priest see that, behold, the scab spreadeth in the skin, then the priest shall pronounce him unclean: it {is} a leprosy.', 'and if the priest see that behold the scab spreadeth in the skin then the priest shall pronounce him unclean it is a leprosy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 9, 'When the plague of leprosy is in a man, then he shall be brought unto the priest;', 'when the plague of leprosy is in a man then he shall be brought unto the priest');
