INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 11, 'It {is} an old leprosy in the skin of his flesh, and the priest shall pronounce him unclean, and shall not shut him up: for he {is} unclean.', 'it is an old leprosy in the skin of his flesh and the priest shall pronounce him unclean and shall not shut him up for he is unclean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 12, 'And if a leprosy break out abroad in the skin, and the leprosy cover all the skin of {him that hath} the plague from his head even to his foot, wheresoever the priest looketh;', 'and if a leprosy break out abroad in the skin and the leprosy cover all the skin of him that hath the plague from his head even to his foot wheresoever the priest looketh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 13, 'Then the priest shall consider: and, behold, {if} the leprosy have covered all his flesh, he shall pronounce {him} clean {that hath} the plague: it is all turned white: he {is} clean.', 'then the priest shall consider and behold if the leprosy have covered all his flesh he shall pronounce him clean that hath the plague it is all turned white he is clean');
