INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 15, 'And the priest shall see the raw flesh, and pronounce him to be unclean: {for} the raw flesh {is} unclean: it {is} a leprosy.', 'and the priest shall see the raw flesh and pronounce him to be unclean for the raw flesh is unclean it is a leprosy');
