INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 17, 'And the priest shall see him: and, behold, {if} the plague be turned into white; then the priest shall pronounce {him} clean {that hath} the plague: he {is} clean.', 'and the priest shall see him and behold if the plague be turned into white then the priest shall pronounce him clean that hath the plague he is clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 18, 'The flesh also, in which, {even} in the skin thereof, was a boil, and is healed,', 'the flesh also in which even in the skin thereof was a boil and is healed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 19, 'And in the place of the boil there be a white rising, or a bright spot, white, and somewhat reddish, and it be shewed to the priest;', 'and in the place of the boil there be a white rising or a bright spot white and somewhat reddish and it be shewed to the priest');
