INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 21, 'But if the priest look on it, and, behold, {there be} no white hairs therein, and {if} it {be} not lower than the skin, but {be} somewhat dark; then the priest shall shut him up seven days:', 'but if the priest look on it and behold there be no white hairs therein and if it be not lower than the skin but be somewhat dark then the priest shall shut him up seven days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 22, 'And if it spread much abroad in the skin, then the priest shall pronounce him unclean: it {is} a plague.', 'and if it spread much abroad in the skin then the priest shall pronounce him unclean it is a plague');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 23, 'But if the bright spot stay in his place, {and} spread not, it {is} a burning boil; and the priest shall pronounce him clean.', 'but if the bright spot stay in his place and spread not it is a burning boil and the priest shall pronounce him clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 13, 24, 'Or if there be {any} flesh, in the skin whereof {there is} a hot burning, and the quick {flesh} that burneth have a white bright spot, somewhat reddish, or white; {a hot...: Heb. a burning of fire}', 'or if there be any flesh in the skin whereof there is a hot burning and the quick flesh that burneth have a white bright spot somewhat reddish or white a hot heb a burning of fire');
