INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 14, 34, 'When ye be come into the land of Canaan, which I give to you for a possession, and I put the plague of leprosy in a house of the land of your possession;', 'when ye be come into the land of canaan which i give to you for a possession and i put the plague of leprosy in a house of the land of your possession');
