INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 26, 'Every bed whereon she lieth all the days of her issue shall be unto her as the bed of her separation: and whatsoever she sitteth upon shall be unclean, as the uncleanness of her separation.', 'every bed whereon she lieth all the days of her issue shall be unto her as the bed of her separation and whatsoever she sitteth upon shall be unclean as the uncleanness of her separation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 27, 'And whosoever toucheth those things shall be unclean, and shall wash his clothes, and bathe {himself} in water, and be unclean until the even.', 'and whosoever toucheth those things shall be unclean and shall wash his clothes and bathe himself in water and be unclean until the even');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 28, 'But if she be cleansed of her issue, then she shall number to herself seven days, and after that she shall be clean.', 'but if she be cleansed of her issue then she shall number to herself seven days and after that she shall be clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 29, 'And on the eighth day she shall take unto her two turtles, or two young pigeons, and bring them unto the priest, to the door of the tabernacle of the congregation.', 'and on the eighth day she shall take unto her two turtles or two young pigeons and bring them unto the priest to the door of the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 30, 'And the priest shall offer the one {for} a sin offering, and the other {for} a burnt offering; and the priest shall make an atonement for her before the LORD for the issue of her uncleanness.', 'and the priest shall offer the one for a sin offering and the other for a burnt offering and the priest shall make an atonement for her before the lord for the issue of her uncleanness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 31, 'Thus shall ye separate the children of Israel from their uncleanness; that they die not in their uncleanness, when they defile my tabernacle that {is} among them.', 'thus shall ye separate the children of israel from their uncleanness that they die not in their uncleanness when they defile my tabernacle that is among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 32, 'This {is} the law of him that hath an issue, and {of him} whose seed goeth from him, and is defiled therewith;', 'this is the law of him that hath an issue and of him whose seed goeth from him and is defiled therewith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 15, 33, 'And of her that is sick of her flowers, and of him that hath an issue, of the man, and of the woman, and of him that lieth with her that is unclean.', 'and of her that is sick of her flowers and of him that hath an issue of the man and of the woman and of him that lieth with her that is unclean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 1, 'And the LORD spake unto Moses after the death of the two sons of Aaron, when they offered before the LORD, and died;', 'and the lord spake unto moses after the death of the two sons of aaron when they offered before the lord and died');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 2, 'And the LORD said unto Moses, Speak unto Aaron thy brother, that he come not at all times into the holy {place} within the vail before the mercy seat, which {is} upon the ark; that he die not: for I will appear in the cloud upon the mercy seat.', 'and the lord said unto moses speak unto aaron thy brother that he come not at all times into the holy place within the vail before the mercy seat which is upon the ark that he die not for i will appear in the cloud upon the mercy seat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 3, 'Thus shall Aaron come into the holy {place}: with a young bullock for a sin offering, and a ram for a burnt offering.', 'thus shall aaron come into the holy place with a young bullock for a sin offering and a ram for a burnt offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 4, 'He shall put on the holy linen coat, and he shall have the linen breeches upon his flesh, and shall be girded with a linen girdle, and with the linen mitre shall he be attired: these {are} holy garments; therefore shall he wash his flesh in water, and {so} put them on.', 'he shall put on the holy linen coat and he shall have the linen breeches upon his flesh and shall be girded with a linen girdle and with the linen mitre shall he be attired these are holy garments therefore shall he wash his flesh in water and so put them on');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 5, 'And he shall take of the congregation of the children of Israel two kids of the goats for a sin offering, and one ram for a burnt offering.', 'and he shall take of the congregation of the children of israel two kids of the goats for a sin offering and one ram for a burnt offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 6, 'And Aaron shall offer his bullock of the sin offering, which {is} for himself, and make an atonement for himself, and for his house.', 'and aaron shall offer his bullock of the sin offering which is for himself and make an atonement for himself and for his house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 7, 'And he shall take the two goats, and present them before the LORD {at} the door of the tabernacle of the congregation.', 'and he shall take the two goats and present them before the lord at the door of the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 8, 'And Aaron shall cast lots upon the two goats; one lot for the LORD, and the other lot for the scapegoat. {scapegoat: Heb. Azazel}', 'and aaron shall cast lots upon the two goats one lot for the lord and the other lot for the scapegoat scapegoat heb azazel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 9, 'And Aaron shall bring the goat upon which the LORD''S lot fell, and offer him {for} a sin offering. {fell: Heb. went up}', 'and aaron shall bring the goat upon which the lord s lot fell and offer him for a sin offering fell heb went up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 10, 'But the goat, on which the lot fell to be the scapegoat, shall be presented alive before the LORD, to make an atonement with him, {and} to let him go for a scapegoat into the wilderness.', 'but the goat on which the lot fell to be the scapegoat shall be presented alive before the lord to make an atonement with him and to let him go for a scapegoat into the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 11, 'And Aaron shall bring the bullock of the sin offering, which {is} for himself, and shall make an atonement for himself, and for his house, and shall kill the bullock of the sin offering which {is} for himself:', 'and aaron shall bring the bullock of the sin offering which is for himself and shall make an atonement for himself and for his house and shall kill the bullock of the sin offering which is for himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 12, 'And he shall take a censer full of burning coals of fire from off the altar before the LORD, and his hands full of sweet incense beaten small, and bring {it} within the vail:', 'and he shall take a censer full of burning coals of fire from off the altar before the lord and his hands full of sweet incense beaten small and bring it within the vail');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 13, 'And he shall put the incense upon the fire before the LORD, that the cloud of the incense may cover the mercy seat that {is} upon the testimony, that he die not:', 'and he shall put the incense upon the fire before the lord that the cloud of the incense may cover the mercy seat that is upon the testimony that he die not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 14, 'And he shall take of the blood of the bullock, and sprinkle {it} with his finger upon the mercy seat eastward; and before the mercy seat shall he sprinkle of the blood with his finger seven times.', 'and he shall take of the blood of the bullock and sprinkle it with his finger upon the mercy seat eastward and before the mercy seat shall he sprinkle of the blood with his finger seven times');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 15, 'Then shall he kill the goat of the sin offering, that {is} for the people, and bring his blood within the vail, and do with that blood as he did with the blood of the bullock, and sprinkle it upon the mercy seat, and before the mercy seat:', 'then shall he kill the goat of the sin offering that is for the people and bring his blood within the vail and do with that blood as he did with the blood of the bullock and sprinkle it upon the mercy seat and before the mercy seat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 16, 'And he shall make an atonement for the holy {place}, because of the uncleanness of the children of Israel, and because of their transgressions in all their sins: and so shall he do for the tabernacle of the congregation, that remaineth among them in the midst of their uncleanness. {remaineth: Heb. dwelleth}', 'and he shall make an atonement for the holy place because of the uncleanness of the children of israel and because of their transgressions in all their sins and so shall he do for the tabernacle of the congregation that remaineth among them in the midst of their uncleanness remaineth heb dwelleth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 17, 'And there shall be no man in the tabernacle of the congregation when he goeth in to make an atonement in the holy {place}, until he come out, and have made an atonement for himself, and for his household, and for all the congregation of Israel.', 'and there shall be no man in the tabernacle of the congregation when he goeth in to make an atonement in the holy place until he come out and have made an atonement for himself and for his household and for all the congregation of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 18, 'And he shall go out unto the altar that {is} before the LORD, and make an atonement for it; and shall take of the blood of the bullock, and of the blood of the goat, and put {it} upon the horns of the altar round about.', 'and he shall go out unto the altar that is before the lord and make an atonement for it and shall take of the blood of the bullock and of the blood of the goat and put it upon the horns of the altar round about');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 19, 'And he shall sprinkle of the blood upon it with his finger seven times, and cleanse it, and hallow it from the uncleanness of the children of Israel.', 'and he shall sprinkle of the blood upon it with his finger seven times and cleanse it and hallow it from the uncleanness of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 20, 'And when he hath made an end of reconciling the holy {place}, and the tabernacle of the congregation, and the altar, he shall bring the live goat:', 'and when he hath made an end of reconciling the holy place and the tabernacle of the congregation and the altar he shall bring the live goat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 21, 'And Aaron shall lay both his hands upon the head of the live goat, and confess over him all the iniquities of the children of Israel, and all their transgressions in all their sins, putting them upon the head of the goat, and shall send {him} away by the hand of a fit man into the wilderness: {a fit...: Heb. a man of opportunity}', 'and aaron shall lay both his hands upon the head of the live goat and confess over him all the iniquities of the children of israel and all their transgressions in all their sins putting them upon the head of the goat and shall send him away by the hand of a fit man into the wilderness a fit heb a man of opportunity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 22, 'And the goat shall bear upon him all their iniquities unto a land not inhabited: and he shall let go the goat in the wilderness. {not...: Heb. of separation}', 'and the goat shall bear upon him all their iniquities unto a land not inhabited and he shall let go the goat in the wilderness not heb of separation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 23, 'And Aaron shall come into the tabernacle of the congregation, and shall put off the linen garments, which he put on when he went into the holy {place}, and shall leave them there:', 'and aaron shall come into the tabernacle of the congregation and shall put off the linen garments which he put on when he went into the holy place and shall leave them there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 24, 'And he shall wash his flesh with water in the holy place, and put on his garments, and come forth, and offer his burnt offering, and the burnt offering of the people, and make an atonement for himself, and for the people.', 'and he shall wash his flesh with water in the holy place and put on his garments and come forth and offer his burnt offering and the burnt offering of the people and make an atonement for himself and for the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 25, 'And the fat of the sin offering shall he burn upon the altar.', 'and the fat of the sin offering shall he burn upon the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 26, 'And he that let go the goat for the scapegoat shall wash his clothes, and bathe his flesh in water, and afterward come into the camp.', 'and he that let go the goat for the scapegoat shall wash his clothes and bathe his flesh in water and afterward come into the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 27, 'And the bullock {for} the sin offering, and the goat {for} the sin offering, whose blood was brought in to make atonement in the holy {place}, shall {one} carry forth without the camp; and they shall burn in the fire their skins, and their flesh, and their dung.', 'and the bullock for the sin offering and the goat for the sin offering whose blood was brought in to make atonement in the holy place shall one carry forth without the camp and they shall burn in the fire their skins and their flesh and their dung');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 28, 'And he that burneth them shall wash his clothes, and bathe his flesh in water, and afterward he shall come into the camp.', 'and he that burneth them shall wash his clothes and bathe his flesh in water and afterward he shall come into the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 29, 'And {this} shall be a statute for ever unto you: {that} in the seventh month, on the tenth {day} of the month, ye shall afflict your souls, and do no work at all, {whether it be} one of your own country, or a stranger that sojourneth among you:', 'and this shall be a statute for ever unto you that in the seventh month on the tenth day of the month ye shall afflict your souls and do no work at all whether it be one of your own country or a stranger that sojourneth among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 30, 'For on that day shall {the priest} make an atonement for you, to cleanse you, {that} ye may be clean from all your sins before the LORD.', 'for on that day shall the priest make an atonement for you to cleanse you that ye may be clean from all your sins before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 31, 'It {shall be} a sabbath of rest unto you, and ye shall afflict your souls, by a statute for ever.', 'it shall be a sabbath of rest unto you and ye shall afflict your souls by a statute for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 32, 'And the priest, whom he shall anoint, and whom he shall consecrate to minister in the priest''s office in his father''s stead, shall make the atonement, and shall put on the linen clothes, {even} the holy garments: {consecrate: Heb. fill his hand}', 'and the priest whom he shall anoint and whom he shall consecrate to minister in the priest s office in his father s stead shall make the atonement and shall put on the linen clothes even the holy garments consecrate heb fill his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 33, 'And he shall make an atonement for the holy sanctuary, and he shall make an atonement for the tabernacle of the congregation, and for the altar, and he shall make an atonement for the priests, and for all the people of the congregation.', 'and he shall make an atonement for the holy sanctuary and he shall make an atonement for the tabernacle of the congregation and for the altar and he shall make an atonement for the priests and for all the people of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 16, 34, 'And this shall be an everlasting statute unto you, to make an atonement for the children of Israel for all their sins once a year. And he did as the LORD commanded Moses.', 'and this shall be an everlasting statute unto you to make an atonement for the children of israel for all their sins once a year and he did as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 2, 'Speak unto Aaron, and unto his sons, and unto all the children of Israel, and say unto them; This {is} the thing which the LORD hath commanded, saying,', 'speak unto aaron and unto his sons and unto all the children of israel and say unto them this is the thing which the lord hath commanded saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 3, 'What man soever {there be} of the house of Israel, that killeth an ox, or lamb, or goat, in the camp, or that killeth {it} out of the camp,', 'what man soever there be of the house of israel that killeth an ox or lamb or goat in the camp or that killeth it out of the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 4, 'And bringeth it not unto the door of the tabernacle of the congregation, to offer an offering unto the LORD before the tabernacle of the LORD; blood shall be imputed unto that man; he hath shed blood; and that man shall be cut off from among his people:', 'and bringeth it not unto the door of the tabernacle of the congregation to offer an offering unto the lord before the tabernacle of the lord blood shall be imputed unto that man he hath shed blood and that man shall be cut off from among his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 5, 'To the end that the children of Israel may bring their sacrifices, which they offer in the open field, even that they may bring them unto the LORD, unto the door of the tabernacle of the congregation, unto the priest, and offer them {for} peace offerings unto the LORD.', 'to the end that the children of israel may bring their sacrifices which they offer in the open field even that they may bring them unto the lord unto the door of the tabernacle of the congregation unto the priest and offer them for peace offerings unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 6, 'And the priest shall sprinkle the blood upon the altar of the LORD {at} the door of the tabernacle of the congregation, and burn the fat for a sweet savour unto the LORD.', 'and the priest shall sprinkle the blood upon the altar of the lord at the door of the tabernacle of the congregation and burn the fat for a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 7, 'And they shall no more offer their sacrifices unto devils, after whom they have gone a whoring. This shall be a statute for ever unto them throughout their generations.', 'and they shall no more offer their sacrifices unto devils after whom they have gone a whoring this shall be a statute for ever unto them throughout their generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 8, 'And thou shalt say unto them, Whatsoever man {there be} of the house of Israel, or of the strangers which sojourn among you, that offereth a burnt offering or sacrifice,', 'and thou shalt say unto them whatsoever man there be of the house of israel or of the strangers which sojourn among you that offereth a burnt offering or sacrifice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 9, 'And bringeth it not unto the door of the tabernacle of the congregation, to offer it unto the LORD; even that man shall be cut off from among his people.', 'and bringeth it not unto the door of the tabernacle of the congregation to offer it unto the lord even that man shall be cut off from among his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 10, 'And whatsoever man {there be} of the house of Israel, or of the strangers that sojourn among you, that eateth any manner of blood; I will even set my face against that soul that eateth blood, and will cut him off from among his people.', 'and whatsoever man there be of the house of israel or of the strangers that sojourn among you that eateth any manner of blood i will even set my face against that soul that eateth blood and will cut him off from among his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 11, 'For the life of the flesh {is} in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it {is} the blood {that} maketh an atonement for the soul.', 'for the life of the flesh is in the blood and i have given it to you upon the altar to make an atonement for your souls for it is the blood that maketh an atonement for the soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 12, 'Therefore I said unto the children of Israel, No soul of you shall eat blood, neither shall any stranger that sojourneth among you eat blood.', 'therefore i said unto the children of israel no soul of you shall eat blood neither shall any stranger that sojourneth among you eat blood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 13, 'And whatsoever man {there be} of the children of Israel, or of the strangers that sojourn among you, which hunteth and catcheth any beast or fowl that may be eaten; he shall even pour out the blood thereof, and cover it with dust. {which...: Heb. that hunteth any hunting}', 'and whatsoever man there be of the children of israel or of the strangers that sojourn among you which hunteth and catcheth any beast or fowl that may be eaten he shall even pour out the blood thereof and cover it with dust which heb that hunteth any hunting');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 14, 'For {it is} the life of all flesh; the blood of it {is} for the life thereof: therefore I said unto the children of Israel, Ye shall eat the blood of no manner of flesh: for the life of all flesh {is} the blood thereof: whosoever eateth it shall be cut off.', 'for it is the life of all flesh the blood of it is for the life thereof therefore i said unto the children of israel ye shall eat the blood of no manner of flesh for the life of all flesh is the blood thereof whosoever eateth it shall be cut off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 15, 'And every soul that eateth that which died {of itself}, or that which was torn {with beasts, whether it be} one of your own country, or a stranger, he shall both wash his clothes, and bathe {himself} in water, and be unclean until the even: then shall he be clean. {that which died...: Heb. a carcase}', 'and every soul that eateth that which died of itself or that which was torn with beasts whether it be one of your own country or a stranger he shall both wash his clothes and bathe himself in water and be unclean until the even then shall he be clean that which died heb a carcase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 17, 16, 'But if he wash {them} not, nor bathe his flesh; then he shall bear his iniquity.', 'but if he wash them not nor bathe his flesh then he shall bear his iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 2, 'Speak unto the children of Israel, and say unto them, I am the LORD your God.', 'speak unto the children of israel and say unto them i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 3, 'After the doings of the land of Egypt, wherein ye dwelt, shall ye not do: and after the doings of the land of Canaan, whither I bring you, shall ye not do: neither shall ye walk in their ordinances.', 'after the doings of the land of egypt wherein ye dwelt shall ye not do and after the doings of the land of canaan whither i bring you shall ye not do neither shall ye walk in their ordinances');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 4, 'Ye shall do my judgments, and keep mine ordinances, to walk therein: I {am} the LORD your God.', 'ye shall do my judgments and keep mine ordinances to walk therein i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 5, 'Ye shall therefore keep my statutes, and my judgments: which if a man do, he shall live in them: I {am} the LORD.', 'ye shall therefore keep my statutes and my judgments which if a man do he shall live in them i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 6, 'None of you shall approach to any that is near of kin to him, to uncover {their} nakedness: I {am} the LORD. {near...: Heb. remainder of his flesh}', 'none of you shall approach to any that is near of kin to him to uncover their nakedness i am the lord near heb remainder of his flesh');
