INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 8, 'The nakedness of thy father''s wife shalt thou not uncover: it {is} thy father''s nakedness.', 'the nakedness of thy father s wife shalt thou not uncover it is thy father s nakedness');
