INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 18, 'Neither shalt thou take a wife to her sister, to vex {her}, to uncover her nakedness, beside the other in her life {time}. {a wife...: or, one wife to another}', 'neither shalt thou take a wife to her sister to vex her to uncover her nakedness beside the other in her life time a wife or one wife to another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 19, 'Also thou shalt not approach unto a woman to uncover her nakedness, as long as she is put apart for her uncleanness.', 'also thou shalt not approach unto a woman to uncover her nakedness as long as she is put apart for her uncleanness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 20, 'Moreover thou shalt not lie carnally with thy neighbour''s wife, to defile thyself with her.', 'moreover thou shalt not lie carnally with thy neighbour s wife to defile thyself with her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 21, 'And thou shalt not let any of thy seed pass through {the fire} to Molech, neither shalt thou profane the name of thy God: I {am} the LORD. {Molech: Gr. Moloch}', 'and thou shalt not let any of thy seed pass through the fire to molech neither shalt thou profane the name of thy god i am the lord molech gr moloch');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 22, 'Thou shalt not lie with mankind, as with womankind: it {is} abomination.', 'thou shalt not lie with mankind as with womankind it is abomination');
