INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 24, 'Defile not ye yourselves in any of these things: for in all these the nations are defiled which I cast out before you:', 'defile not ye yourselves in any of these things for in all these the nations are defiled which i cast out before you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 25, 'And the land is defiled: therefore I do visit the iniquity thereof upon it, and the land itself vomiteth out her inhabitants.', 'and the land is defiled therefore i do visit the iniquity thereof upon it and the land itself vomiteth out her inhabitants');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 26, 'Ye shall therefore keep my statutes and my judgments, and shall not commit {any} of these abominations; {neither} any of your own nation, nor any stranger that sojourneth among you:', 'ye shall therefore keep my statutes and my judgments and shall not commit any of these abominations neither any of your own nation nor any stranger that sojourneth among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 27, '(For all these abominations have the men of the land done, which {were} before you, and the land is defiled;)', 'for all these abominations have the men of the land done which were before you and the land is defiled');
