INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 18, 30, 'Therefore shall ye keep mine ordinance, that {ye} commit not {any one} of these abominable customs, which were committed before you, and that ye defile not yourselves therein: I {am} the LORD your God.', 'therefore shall ye keep mine ordinance that ye commit not any one of these abominable customs which were committed before you and that ye defile not yourselves therein i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
