INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 4, 'Turn ye not unto idols, nor make to yourselves molten gods: I {am} the LORD your God.', 'turn ye not unto idols nor make to yourselves molten gods i am the lord your god');
