INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 7, 'And if it be eaten at all on the third day, it {is} abominable; it shall not be accepted.', 'and if it be eaten at all on the third day it is abominable it shall not be accepted');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 8, 'Therefore {every one} that eateth it shall bear his iniquity, because he hath profaned the hallowed thing of the LORD: and that soul shall be cut off from among his people.', 'therefore every one that eateth it shall bear his iniquity because he hath profaned the hallowed thing of the lord and that soul shall be cut off from among his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 9, 'And when ye reap the harvest of your land, thou shalt not wholly reap the corners of thy field, neither shalt thou gather the gleanings of thy harvest.', 'and when ye reap the harvest of your land thou shalt not wholly reap the corners of thy field neither shalt thou gather the gleanings of thy harvest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 10, 'And thou shalt not glean thy vineyard, neither shalt thou gather {every} grape of thy vineyard; thou shalt leave them for the poor and stranger: I {am} the LORD your God.', 'and thou shalt not glean thy vineyard neither shalt thou gather every grape of thy vineyard thou shalt leave them for the poor and stranger i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 11, 'Ye shall not steal, neither deal falsely, neither lie one to another.', 'ye shall not steal neither deal falsely neither lie one to another');
