INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 16, 'Thou shalt not go up and down {as} a talebearer among thy people: neither shalt thou stand against the blood of thy neighbour: I {am} the LORD.', 'thou shalt not go up and down as a talebearer among thy people neither shalt thou stand against the blood of thy neighbour i am the lord');
