INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 19, 'Ye shall keep my statutes. Thou shalt not let thy cattle gender with a diverse kind: thou shalt not sow thy field with mingled seed: neither shall a garment mingled of linen and woollen come upon thee.', 'ye shall keep my statutes thou shalt not let thy cattle gender with a diverse kind thou shalt not sow thy field with mingled seed neither shall a garment mingled of linen and woollen come upon thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 20, 'And whosoever lieth carnally with a woman, that {is} a bondmaid, betrothed to an husband, and not at all redeemed, nor freedom given her; she shall be scourged; they shall not be put to death, because she was not free. {betrothed...: or, abused by any: Heb. reproached by (or, for) man} {she shall...: or, they, etc: Heb. there shall be a scourging}', 'and whosoever lieth carnally with a woman that is a bondmaid betrothed to an husband and not at all redeemed nor freedom given her she shall be scourged they shall not be put to death because she was not free betrothed or abused by any heb reproached by or for man she shall or they etc heb there shall be a scourging');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 21, 'And he shall bring his trespass offering unto the LORD, unto the door of the tabernacle of the congregation, {even} a ram for a trespass offering.', 'and he shall bring his trespass offering unto the lord unto the door of the tabernacle of the congregation even a ram for a trespass offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 22, 'And the priest shall make an atonement for him with the ram of the trespass offering before the LORD for his sin which he hath done: and the sin which he hath done shall be forgiven him.', 'and the priest shall make an atonement for him with the ram of the trespass offering before the lord for his sin which he hath done and the sin which he hath done shall be forgiven him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 23, 'And when ye shall come into the land, and shall have planted all manner of trees for food, then ye shall count the fruit thereof as uncircumcised: three years shall it be as uncircumcised unto you: it shall not be eaten of.', 'and when ye shall come into the land and shall have planted all manner of trees for food then ye shall count the fruit thereof as uncircumcised three years shall it be as uncircumcised unto you it shall not be eaten of');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 24, 'But in the fourth year all the fruit thereof shall be holy to praise the LORD {withal}. {holy...: Heb. holiness of praises to the LORD}', 'but in the fourth year all the fruit thereof shall be holy to praise the lord withal holy heb holiness of praises to the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 25, 'And in the fifth year shall ye eat of the fruit thereof, that it may yield unto you the increase thereof: I {am} the LORD your God.', 'and in the fifth year shall ye eat of the fruit thereof that it may yield unto you the increase thereof i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 26, 'Ye shall not eat {any thing} with the blood: neither shall ye use enchantment, nor observe times.', 'ye shall not eat any thing with the blood neither shall ye use enchantment nor observe times');
