INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 29, 'Do not prostitute thy daughter, to cause her to be a whore; lest the land fall to whoredom, and the land become full of wickedness. {prostitute: Heb. profane}', 'do not prostitute thy daughter to cause her to be a whore lest the land fall to whoredom and the land become full of wickedness prostitute heb profane');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 30, 'Ye shall keep my sabbaths, and reverence my sanctuary: I {am} the LORD.', 'ye shall keep my sabbaths and reverence my sanctuary i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 19, 31, 'Regard not them that have familiar spirits, neither seek after wizards, to be defiled by them: I {am} the LORD your God.', 'regard not them that have familiar spirits neither seek after wizards to be defiled by them i am the lord your god');
