INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 3, 'And I will set my face against that man, and will cut him off from among his people; because he hath given of his seed unto Molech, to defile my sanctuary, and to profane my holy name.', 'and i will set my face against that man and will cut him off from among his people because he hath given of his seed unto molech to defile my sanctuary and to profane my holy name');
