INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 11, 'And the man that lieth with his father''s wife hath uncovered his father''s nakedness: both of them shall surely be put to death; their blood {shall be} upon them.', 'and the man that lieth with his father s wife hath uncovered his father s nakedness both of them shall surely be put to death their blood shall be upon them');
