INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 14, 'And if a man take a wife and her mother, it {is} wickedness: they shall be burnt with fire, both he and they; that there be no wickedness among you.', 'and if a man take a wife and her mother it is wickedness they shall be burnt with fire both he and they that there be no wickedness among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 15, 'And if a man lie with a beast, he shall surely be put to death: and ye shall slay the beast.', 'and if a man lie with a beast he shall surely be put to death and ye shall slay the beast');
