INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 18, 'And if a man shall lie with a woman having her sickness, and shall uncover her nakedness; he hath discovered her fountain, and she hath uncovered the fountain of her blood: and both of them shall be cut off from among their people. {discovered: Heb. made naked}', 'and if a man shall lie with a woman having her sickness and shall uncover her nakedness he hath discovered her fountain and she hath uncovered the fountain of her blood and both of them shall be cut off from among their people discovered heb made naked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 19, 'And thou shalt not uncover the nakedness of thy mother''s sister, nor of thy father''s sister: for he uncovereth his near kin: they shall bear their iniquity. {uncovereth: Heb. hath made naked}', 'and thou shalt not uncover the nakedness of thy mother s sister nor of thy father s sister for he uncovereth his near kin they shall bear their iniquity uncovereth heb hath made naked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 20, 'And if a man shall lie with his uncle''s wife, he hath uncovered his uncle''s nakedness: they shall bear their sin; they shall die childless.', 'and if a man shall lie with his uncle s wife he hath uncovered his uncle s nakedness they shall bear their sin they shall die childless');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 21, 'And if a man shall take his brother''s wife, it {is} an unclean thing: he hath uncovered his brother''s nakedness; they shall be childless. {an...: Heb. a separation}', 'and if a man shall take his brother s wife it is an unclean thing he hath uncovered his brother s nakedness they shall be childless an heb a separation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 20, 22, 'Ye shall therefore keep all my statutes, and all my judgments, and do them: that the land, whither I bring you to dwell therein, spue you not out.', 'ye shall therefore keep all my statutes and all my judgments and do them that the land whither i bring you to dwell therein spue you not out');
