INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 4, 'What man soever of the seed of Aaron {is} a leper, or hath a running issue; he shall not eat of the holy things, until he be clean. And whoso toucheth any thing {that is} unclean {by} the dead, or a man whose seed goeth from him; {running...: Heb. running of the reins}', 'what man soever of the seed of aaron is a leper or hath a running issue he shall not eat of the holy things until he be clean and whoso toucheth any thing that is unclean by the dead or a man whose seed goeth from him running heb running of the reins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 5, 'Or whosoever toucheth any creeping thing, whereby he may be made unclean, or a man of whom he may take uncleanness, whatsoever uncleanness he hath;', 'or whosoever toucheth any creeping thing whereby he may be made unclean or a man of whom he may take uncleanness whatsoever uncleanness he hath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 6, 'The soul which hath touched any such shall be unclean until even, and shall not eat of the holy things, unless he wash his flesh with water.', 'the soul which hath touched any such shall be unclean until even and shall not eat of the holy things unless he wash his flesh with water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 7, 'And when the sun is down, he shall be clean, and shall afterward eat of the holy things; because it {is} his food.', 'and when the sun is down he shall be clean and shall afterward eat of the holy things because it is his food');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 8, 'That which dieth of itself, or is torn {with beasts}, he shall not eat to defile himself therewith: I {am} the LORD.', 'that which dieth of itself or is torn with beasts he shall not eat to defile himself therewith i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 9, 'They shall therefore keep mine ordinance, lest they bear sin for it, and die therefore, if they profane it: I the LORD do sanctify them.', 'they shall therefore keep mine ordinance lest they bear sin for it and die therefore if they profane it i the lord do sanctify them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 10, 'There shall no stranger eat {of} the holy thing: a sojourner of the priest, or an hired servant, shall not eat {of} the holy thing.', 'there shall no stranger eat of the holy thing a sojourner of the priest or an hired servant shall not eat of the holy thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 11, 'But if the priest buy {any} soul with his money, he shall eat of it, and he that is born in his house: they shall eat of his meat. {with...: Heb. with the purchase of his money}', 'but if the priest buy any soul with his money he shall eat of it and he that is born in his house they shall eat of his meat with heb with the purchase of his money');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 12, 'If the priest''s daughter also be {married} unto a stranger, she may not eat of an offering of the holy things. {a stranger: Heb. a man a stranger}', 'if the priest s daughter also be married unto a stranger she may not eat of an offering of the holy things a stranger heb a man a stranger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 13, 'But if the priest''s daughter be a widow, or divorced, and have no child, and is returned unto her father''s house, as in her youth, she shall eat of her father''s meat: but there shall no stranger eat thereof.', 'but if the priest s daughter be a widow or divorced and have no child and is returned unto her father s house as in her youth she shall eat of her father s meat but there shall no stranger eat thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 14, 'And if a man eat {of} the holy thing unwittingly, then he shall put the fifth {part} thereof unto it, and shall give {it} unto the priest with the holy thing.', 'and if a man eat of the holy thing unwittingly then he shall put the fifth part thereof unto it and shall give it unto the priest with the holy thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 15, 'And they shall not profane the holy things of the children of Israel, which they offer unto the LORD;', 'and they shall not profane the holy things of the children of israel which they offer unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 16, 'Or suffer them to bear the iniquity of trespass, when they eat their holy things: for I the LORD do sanctify them. {suffer...: or, lade themselves with the iniquity of trespass in their eating}', 'or suffer them to bear the iniquity of trespass when they eat their holy things for i the lord do sanctify them suffer or lade themselves with the iniquity of trespass in their eating');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 17, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 18, 'Speak unto Aaron, and to his sons, and unto all the children of Israel, and say unto them, Whatsoever {he be} of the house of Israel, or of the strangers in Israel, that will offer his oblation for all his vows, and for all his freewill offerings, which they will offer unto the LORD for a burnt offering;', 'speak unto aaron and to his sons and unto all the children of israel and say unto them whatsoever he be of the house of israel or of the strangers in israel that will offer his oblation for all his vows and for all his freewill offerings which they will offer unto the lord for a burnt offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 19, '{Ye shall offer} at your own will a male without blemish, of the beeves, of the sheep, or of the goats.', 'ye shall offer at your own will a male without blemish of the beeves of the sheep or of the goats');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 20, '{But} whatsoever hath a blemish, {that} shall ye not offer: for it shall not be acceptable for you.', 'but whatsoever hath a blemish that shall ye not offer for it shall not be acceptable for you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 21, 'And whosoever offereth a sacrifice of peace offerings unto the LORD to accomplish {his} vow, or a freewill offering in beeves or sheep, it shall be perfect to be accepted; there shall be no blemish therein. {sheep: or, goats}', 'and whosoever offereth a sacrifice of peace offerings unto the lord to accomplish his vow or a freewill offering in beeves or sheep it shall be perfect to be accepted there shall be no blemish therein sheep or goats');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 22, 'Blind, or broken, or maimed, or having a wen, or scurvy, or scabbed, ye shall not offer these unto the LORD, nor make an offering by fire of them upon the altar unto the LORD.', 'blind or broken or maimed or having a wen or scurvy or scabbed ye shall not offer these unto the lord nor make an offering by fire of them upon the altar unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 23, 'Either a bullock or a lamb that hath any thing superfluous or lacking in his parts, that mayest thou offer {for} a freewill offering; but for a vow it shall not be accepted. {lamb: or, kid}', 'either a bullock or a lamb that hath any thing superfluous or lacking in his parts that mayest thou offer for a freewill offering but for a vow it shall not be accepted lamb or kid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 24, 'Ye shall not offer unto the LORD that which is bruised, or crushed, or broken, or cut; neither shall ye make {any offering thereof} in your land.', 'ye shall not offer unto the lord that which is bruised or crushed or broken or cut neither shall ye make any offering thereof in your land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 25, 'Neither from a stranger''s hand shall ye offer the bread of your God of any of these; because their corruption {is} in them, {and} blemishes {be} in them: they shall not be accepted for you.', 'neither from a stranger s hand shall ye offer the bread of your god of any of these because their corruption is in them and blemishes be in them they shall not be accepted for you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 26, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 27, 'When a bullock, or a sheep, or a goat, is brought forth, then it shall be seven days under the dam; and from the eighth day and thenceforth it shall be accepted for an offering made by fire unto the LORD.', 'when a bullock or a sheep or a goat is brought forth then it shall be seven days under the dam and from the eighth day and thenceforth it shall be accepted for an offering made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 28, 'And {whether it be} cow or ewe, ye shall not kill it and her young both in one day. {ewe: or, she goat}', 'and whether it be cow or ewe ye shall not kill it and her young both in one day ewe or she goat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 29, 'And when ye will offer a sacrifice of thanksgiving unto the LORD, offer {it} at your own will.', 'and when ye will offer a sacrifice of thanksgiving unto the lord offer it at your own will');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 30, 'On the same day it shall be eaten up; ye shall leave none of it until the morrow: I {am} the LORD.', 'on the same day it shall be eaten up ye shall leave none of it until the morrow i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 31, 'Therefore shall ye keep my commandments, and do them: I {am} the LORD.', 'therefore shall ye keep my commandments and do them i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 32, 'Neither shall ye profane my holy name; but I will be hallowed among the children of Israel: I {am} the LORD which hallow you,', 'neither shall ye profane my holy name but i will be hallowed among the children of israel i am the lord which hallow you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 22, 33, 'That brought you out of the land of Egypt, to be your God: I {am} the LORD.', 'that brought you out of the land of egypt to be your god i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 2, 'Speak unto the children of Israel, and say unto them, {Concerning} the feasts of the LORD, which ye shall proclaim {to be} holy convocations, {even} these {are} my feasts.', 'speak unto the children of israel and say unto them concerning the feasts of the lord which ye shall proclaim to be holy convocations even these are my feasts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 3, 'Six days shall work be done: but the seventh day {is} the sabbath of rest, an holy convocation; ye shall do no work {therein}: it {is} the sabbath of the LORD in all your dwellings.', 'six days shall work be done but the seventh day is the sabbath of rest an holy convocation ye shall do no work therein it is the sabbath of the lord in all your dwellings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 4, 'These {are} the feasts of the LORD, {even} holy convocations, which ye shall proclaim in their seasons.', 'these are the feasts of the lord even holy convocations which ye shall proclaim in their seasons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 5, 'In the fourteenth {day} of the first month at even {is} the LORD''S passover.', 'in the fourteenth day of the first month at even is the lord s passover');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 6, 'And on the fifteenth day of the same month {is} the feast of unleavened bread unto the LORD: seven days ye must eat unleavened bread.', 'and on the fifteenth day of the same month is the feast of unleavened bread unto the lord seven days ye must eat unleavened bread');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 7, 'In the first day ye shall have an holy convocation: ye shall do no servile work therein.', 'in the first day ye shall have an holy convocation ye shall do no servile work therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 8, 'But ye shall offer an offering made by fire unto the LORD seven days: in the seventh day {is} an holy convocation: ye shall do no servile work {therein}.', 'but ye shall offer an offering made by fire unto the lord seven days in the seventh day is an holy convocation ye shall do no servile work therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 9, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 10, 'Speak unto the children of Israel, and say unto them, When ye be come into the land which I give unto you, and shall reap the harvest thereof, then ye shall bring a sheaf of the firstfruits of your harvest unto the priest: {sheaf: or, handful: Heb. omer}', 'speak unto the children of israel and say unto them when ye be come into the land which i give unto you and shall reap the harvest thereof then ye shall bring a sheaf of the firstfruits of your harvest unto the priest sheaf or handful heb omer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 11, 'And he shall wave the sheaf before the LORD, to be accepted for you: on the morrow after the sabbath the priest shall wave it.', 'and he shall wave the sheaf before the lord to be accepted for you on the morrow after the sabbath the priest shall wave it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 12, 'And ye shall offer that day when ye wave the sheaf an he lamb without blemish of the first year for a burnt offering unto the LORD.', 'and ye shall offer that day when ye wave the sheaf an he lamb without blemish of the first year for a burnt offering unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 13, 'And the meat offering thereof {shall be} two tenth deals of fine flour mingled with oil, an offering made by fire unto the LORD {for} a sweet savour: and the drink offering thereof {shall be} of wine, the fourth {part} of an hin.', 'and the meat offering thereof shall be two tenth deals of fine flour mingled with oil an offering made by fire unto the lord for a sweet savour and the drink offering thereof shall be of wine the fourth part of an hin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 14, 'And ye shall eat neither bread, nor parched corn, nor green ears, until the selfsame day that ye have brought an offering unto your God: {it shall be} a statute for ever throughout your generations in all your dwellings.', 'and ye shall eat neither bread nor parched corn nor green ears until the selfsame day that ye have brought an offering unto your god it shall be a statute for ever throughout your generations in all your dwellings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 15, 'And ye shall count unto you from the morrow after the sabbath, from the day that ye brought the sheaf of the wave offering; seven sabbaths shall be complete:', 'and ye shall count unto you from the morrow after the sabbath from the day that ye brought the sheaf of the wave offering seven sabbaths shall be complete');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 16, 'Even unto the morrow after the seventh sabbath shall ye number fifty days; and ye shall offer a new meat offering unto the LORD.', 'even unto the morrow after the seventh sabbath shall ye number fifty days and ye shall offer a new meat offering unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 17, 'Ye shall bring out of your habitations two wave loaves of two tenth deals: they shall be of fine flour; they shall be baken with leaven; {they are} the firstfruits unto the LORD.', 'ye shall bring out of your habitations two wave loaves of two tenth deals they shall be of fine flour they shall be baken with leaven they are the firstfruits unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 18, 'And ye shall offer with the bread seven lambs without blemish of the first year, and one young bullock, and two rams: they shall be {for} a burnt offering unto the LORD, with their meat offering, and their drink offerings, {even} an offering made by fire, of sweet savour unto the LORD.', 'and ye shall offer with the bread seven lambs without blemish of the first year and one young bullock and two rams they shall be for a burnt offering unto the lord with their meat offering and their drink offerings even an offering made by fire of sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 19, 'Then ye shall sacrifice one kid of the goats for a sin offering, and two lambs of the first year for a sacrifice of peace offerings.', 'then ye shall sacrifice one kid of the goats for a sin offering and two lambs of the first year for a sacrifice of peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 20, 'And the priest shall wave them with the bread of the firstfruits {for} a wave offering before the LORD, with the two lambs: they shall be holy to the LORD for the priest.', 'and the priest shall wave them with the bread of the firstfruits for a wave offering before the lord with the two lambs they shall be holy to the lord for the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 21, 'And ye shall proclaim on the selfsame day, {that} it may be an holy convocation unto you: ye shall do no servile work {therein: it shall be} a statute for ever in all your dwellings throughout your generations.', 'and ye shall proclaim on the selfsame day that it may be an holy convocation unto you ye shall do no servile work therein it shall be a statute for ever in all your dwellings throughout your generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 22, 'And when ye reap the harvest of your land, thou shalt not make clean riddance of the corners of thy field when thou reapest, neither shalt thou gather any gleaning of thy harvest: thou shalt leave them unto the poor, and to the stranger: I {am} the LORD your God.', 'and when ye reap the harvest of your land thou shalt not make clean riddance of the corners of thy field when thou reapest neither shalt thou gather any gleaning of thy harvest thou shalt leave them unto the poor and to the stranger i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 23, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 24, 'Speak unto the children of Israel, saying, In the seventh month, in the first {day} of the month, shall ye have a sabbath, a memorial of blowing of trumpets, an holy convocation.', 'speak unto the children of israel saying in the seventh month in the first day of the month shall ye have a sabbath a memorial of blowing of trumpets an holy convocation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 25, 'Ye shall do no servile work {therein}: but ye shall offer an offering made by fire unto the LORD.', 'ye shall do no servile work therein but ye shall offer an offering made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 26, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 27, 'Also on the tenth {day} of this seventh month {there shall be} a day of atonement: it shall be an holy convocation unto you; and ye shall afflict your souls, and offer an offering made by fire unto the LORD.', 'also on the tenth day of this seventh month there shall be a day of atonement it shall be an holy convocation unto you and ye shall afflict your souls and offer an offering made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 28, 'And ye shall do no work in that same day: for it {is} a day of atonement, to make an atonement for you before the LORD your God.', 'and ye shall do no work in that same day for it is a day of atonement to make an atonement for you before the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 29, 'For whatsoever soul {it be} that shall not be afflicted in that same day, he shall be cut off from among his people.', 'for whatsoever soul it be that shall not be afflicted in that same day he shall be cut off from among his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 30, 'And whatsoever soul {it be} that doeth any work in that same day, the same soul will I destroy from among his people.', 'and whatsoever soul it be that doeth any work in that same day the same soul will i destroy from among his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 31, 'Ye shall do no manner of work: {it shall be} a statute for ever throughout your generations in all your dwellings.', 'ye shall do no manner of work it shall be a statute for ever throughout your generations in all your dwellings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 32, 'It {shall be} unto you a sabbath of rest, and ye shall afflict your souls: in the ninth {day} of the month at even, from even unto even, shall ye celebrate your sabbath. {celebrate: Heb. rest}', 'it shall be unto you a sabbath of rest and ye shall afflict your souls in the ninth day of the month at even from even unto even shall ye celebrate your sabbath celebrate heb rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 33, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 34, 'Speak unto the children of Israel, saying, The fifteenth day of this seventh month {shall be} the feast of tabernacles {for} seven days unto the LORD.', 'speak unto the children of israel saying the fifteenth day of this seventh month shall be the feast of tabernacles for seven days unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 35, 'On the first day {shall be} an holy convocation: ye shall do no servile work {therein}.', 'on the first day shall be an holy convocation ye shall do no servile work therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 36, 'Seven days ye shall offer an offering made by fire unto the LORD: on the eighth day shall be an holy convocation unto you; and ye shall offer an offering made by fire unto the LORD: it {is} a solemn assembly; {and} ye shall do no servile work {therein}. {solemn...: Heb. day of restraint}', 'seven days ye shall offer an offering made by fire unto the lord on the eighth day shall be an holy convocation unto you and ye shall offer an offering made by fire unto the lord it is a solemn assembly and ye shall do no servile work therein solemn heb day of restraint');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 37, 'These {are} the feasts of the LORD, which ye shall proclaim {to be} holy convocations, to offer an offering made by fire unto the LORD, a burnt offering, and a meat offering, a sacrifice, and drink offerings, every thing upon his day:', 'these are the feasts of the lord which ye shall proclaim to be holy convocations to offer an offering made by fire unto the lord a burnt offering and a meat offering a sacrifice and drink offerings every thing upon his day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 38, 'Beside the sabbaths of the LORD, and beside your gifts, and beside all your vows, and beside all your freewill offerings, which ye give unto the LORD.', 'beside the sabbaths of the lord and beside your gifts and beside all your vows and beside all your freewill offerings which ye give unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 39, 'Also in the fifteenth day of the seventh month, when ye have gathered in the fruit of the land, ye shall keep a feast unto the LORD seven days: on the first day {shall be} a sabbath, and on the eighth day {shall be} a sabbath.', 'also in the fifteenth day of the seventh month when ye have gathered in the fruit of the land ye shall keep a feast unto the lord seven days on the first day shall be a sabbath and on the eighth day shall be a sabbath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 40, 'And ye shall take you on the first day the boughs of goodly trees, branches of palm trees, and the boughs of thick trees, and willows of the brook; and ye shall rejoice before the LORD your God seven days. {boughs of goodly trees: Heb. fruit of, etc}', 'and ye shall take you on the first day the boughs of goodly trees branches of palm trees and the boughs of thick trees and willows of the brook and ye shall rejoice before the lord your god seven days boughs of goodly trees heb fruit of etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 41, 'And ye shall keep it a feast unto the LORD seven days in the year. {It shall be} a statute for ever in your generations: ye shall celebrate it in the seventh month.', 'and ye shall keep it a feast unto the lord seven days in the year it shall be a statute for ever in your generations ye shall celebrate it in the seventh month');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 42, 'Ye shall dwell in booths seven days; all that are Israelites born shall dwell in booths:', 'ye shall dwell in booths seven days all that are israelites born shall dwell in booths');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 43, 'That your generations may know that I made the children of Israel to dwell in booths, when I brought them out of the land of Egypt: I {am} the LORD your God.', 'that your generations may know that i made the children of israel to dwell in booths when i brought them out of the land of egypt i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 23, 44, 'And Moses declared unto the children of Israel the feasts of the LORD.', 'and moses declared unto the children of israel the feasts of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 2, 'Command the children of Israel, that they bring unto thee pure oil olive beaten for the light, to cause the lamps to burn continually. {to cause: Heb. to cause to ascend}', 'command the children of israel that they bring unto thee pure oil olive beaten for the light to cause the lamps to burn continually to cause heb to cause to ascend');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 3, 'Without the vail of the testimony, in the tabernacle of the congregation, shall Aaron order it from the evening unto the morning before the LORD continually: {it shall be} a statute for ever in your generations.', 'without the vail of the testimony in the tabernacle of the congregation shall aaron order it from the evening unto the morning before the lord continually it shall be a statute for ever in your generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 4, 'He shall order the lamps upon the pure candlestick before the LORD continually.', 'he shall order the lamps upon the pure candlestick before the lord continually');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 5, 'And thou shalt take fine flour, and bake twelve cakes thereof: two tenth deals shall be in one cake.', 'and thou shalt take fine flour and bake twelve cakes thereof two tenth deals shall be in one cake');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 6, 'And thou shalt set them in two rows, six on a row, upon the pure table before the LORD.', 'and thou shalt set them in two rows six on a row upon the pure table before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 7, 'And thou shalt put pure frankincense upon {each} row, that it may be on the bread for a memorial, {even} an offering made by fire unto the LORD.', 'and thou shalt put pure frankincense upon each row that it may be on the bread for a memorial even an offering made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 8, 'Every sabbath he shall set it in order before the LORD continually, {being taken} from the children of Israel by an everlasting covenant.', 'every sabbath he shall set it in order before the lord continually being taken from the children of israel by an everlasting covenant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 9, 'And it shall be Aaron''s and his sons''; and they shall eat it in the holy place: for it {is} most holy unto him of the offerings of the LORD made by fire by a perpetual statute.', 'and it shall be aaron s and his sons and they shall eat it in the holy place for it is most holy unto him of the offerings of the lord made by fire by a perpetual statute');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 10, 'And the son of an Israelitish woman, whose father {was} an Egyptian, went out among the children of Israel: and this son of the Israelitish {woman} and a man of Israel strove together in the camp;', 'and the son of an israelitish woman whose father was an egyptian went out among the children of israel and this son of the israelitish woman and a man of israel strove together in the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 11, 'And the Israelitish woman''s son blasphemed the name {of the LORD}, and cursed. And they brought him unto Moses: (and his mother''s name {was} Shelomith, the daughter of Dibri, of the tribe of Dan:)', 'and the israelitish woman s son blasphemed the name of the lord and cursed and they brought him unto moses and his mother s name was shelomith the daughter of dibri of the tribe of dan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 12, 'And they put him in ward, that the mind of the LORD might be shewed them. {that...: Heb. to expound unto them according to the mouth of the LORD}', 'and they put him in ward that the mind of the lord might be shewed them that heb to expound unto them according to the mouth of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 13, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 14, 'Bring forth him that hath cursed without the camp; and let all that heard {him} lay their hands upon his head, and let all the congregation stone him.', 'bring forth him that hath cursed without the camp and let all that heard him lay their hands upon his head and let all the congregation stone him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 15, 'And thou shalt speak unto the children of Israel, saying, Whosoever curseth his God shall bear his sin.', 'and thou shalt speak unto the children of israel saying whosoever curseth his god shall bear his sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 16, 'And he that blasphemeth the name of the LORD, he shall surely be put to death, {and} all the congregation shall certainly stone him: as well the stranger, as he that is born in the land, when he blasphemeth the name {of the LORD}, shall be put to death.', 'and he that blasphemeth the name of the lord he shall surely be put to death and all the congregation shall certainly stone him as well the stranger as he that is born in the land when he blasphemeth the name of the lord shall be put to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 17, 'And he that killeth any man shall surely be put to death. {killeth...: Heb. smiteth the life of a man}', 'and he that killeth any man shall surely be put to death killeth heb smiteth the life of a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 18, 'And he that killeth a beast shall make it good; beast for beast. {beast for...: Heb. life for life}', 'and he that killeth a beast shall make it good beast for beast beast for heb life for life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 19, 'And if a man cause a blemish in his neighbour; as he hath done, so shall it be done to him;', 'and if a man cause a blemish in his neighbour as he hath done so shall it be done to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 20, 'Breach for breach, eye for eye, tooth for tooth: as he hath caused a blemish in a man, so shall it be done to him {again}.', 'breach for breach eye for eye tooth for tooth as he hath caused a blemish in a man so shall it be done to him again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 21, 'And he that killeth a beast, he shall restore it: and he that killeth a man, he shall be put to death.', 'and he that killeth a beast he shall restore it and he that killeth a man he shall be put to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 22, 'Ye shall have one manner of law, as well for the stranger, as for one of your own country: for I {am} the LORD your God.', 'ye shall have one manner of law as well for the stranger as for one of your own country for i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 24, 23, 'And Moses spake to the children of Israel, that they should bring forth him that had cursed out of the camp, and stone him with stones. And the children of Israel did as the LORD commanded Moses.', 'and moses spake to the children of israel that they should bring forth him that had cursed out of the camp and stone him with stones and the children of israel did as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 1, 'And the LORD spake unto Moses in mount Sinai, saying,', 'and the lord spake unto moses in mount sinai saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 2, 'Speak unto the children of Israel, and say unto them, When ye come into the land which I give you, then shall the land keep a sabbath unto the LORD. {keep: Heb. rest}', 'speak unto the children of israel and say unto them when ye come into the land which i give you then shall the land keep a sabbath unto the lord keep heb rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 3, 'Six years thou shalt sow thy field, and six years thou shalt prune thy vineyard, and gather in the fruit thereof;', 'six years thou shalt sow thy field and six years thou shalt prune thy vineyard and gather in the fruit thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 4, 'But in the seventh year shall be a sabbath of rest unto the land, a sabbath for the LORD: thou shalt neither sow thy field, nor prune thy vineyard.', 'but in the seventh year shall be a sabbath of rest unto the land a sabbath for the lord thou shalt neither sow thy field nor prune thy vineyard');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 5, 'That which groweth of its own accord of thy harvest thou shalt not reap, neither gather the grapes of thy vine undressed: {for} it is a year of rest unto the land. {of thy vine...: Heb. of thy separation}', 'that which groweth of its own accord of thy harvest thou shalt not reap neither gather the grapes of thy vine undressed for it is a year of rest unto the land of thy vine heb of thy separation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 6, 'And the sabbath of the land shall be meat for you; for thee, and for thy servant, and for thy maid, and for thy hired servant, and for thy stranger that sojourneth with thee,', 'and the sabbath of the land shall be meat for you for thee and for thy servant and for thy maid and for thy hired servant and for thy stranger that sojourneth with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 7, 'And for thy cattle, and for the beast that {are} in thy land, shall all the increase thereof be meat.', 'and for thy cattle and for the beast that are in thy land shall all the increase thereof be meat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 8, 'And thou shalt number seven sabbaths of years unto thee, seven times seven years; and the space of the seven sabbaths of years shall be unto thee forty and nine years.', 'and thou shalt number seven sabbaths of years unto thee seven times seven years and the space of the seven sabbaths of years shall be unto thee forty and nine years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 9, 'Then shalt thou cause the trumpet of the jubile to sound on the tenth {day} of the seventh month, in the day of atonement shall ye make the trumpet sound throughout all your land. {of the jubile: Heb. loud of sound}', 'then shalt thou cause the trumpet of the jubile to sound on the tenth day of the seventh month in the day of atonement shall ye make the trumpet sound throughout all your land of the jubile heb loud of sound');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 10, 'And ye shall hallow the fiftieth year, and proclaim liberty throughout {all} the land unto all the inhabitants thereof: it shall be a jubile unto you; and ye shall return every man unto his possession, and ye shall return every man unto his family.', 'and ye shall hallow the fiftieth year and proclaim liberty throughout all the land unto all the inhabitants thereof it shall be a jubile unto you and ye shall return every man unto his possession and ye shall return every man unto his family');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 11, 'A jubile shall that fiftieth year be unto you: ye shall not sow, neither reap that which groweth of itself in it, nor gather {the grapes} in it of thy vine undressed.', 'a jubile shall that fiftieth year be unto you ye shall not sow neither reap that which groweth of itself in it nor gather the grapes in it of thy vine undressed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 12, 'For it {is} the jubile; it shall be holy unto you: ye shall eat the increase thereof out of the field.', 'for it is the jubile it shall be holy unto you ye shall eat the increase thereof out of the field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 13, 'In the year of this jubile ye shall return every man unto his possession.', 'in the year of this jubile ye shall return every man unto his possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 14, 'And if thou sell ought unto thy neighbour, or buyest {ought} of thy neighbour''s hand, ye shall not oppress one another:', 'and if thou sell ought unto thy neighbour or buyest ought of thy neighbour s hand ye shall not oppress one another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 15, 'According to the number of years after the jubile thou shalt buy of thy neighbour, {and} according unto the number of years of the fruits he shall sell unto thee:', 'according to the number of years after the jubile thou shalt buy of thy neighbour and according unto the number of years of the fruits he shall sell unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 16, 'According to the multitude of years thou shalt increase the price thereof, and according to the fewness of years thou shalt diminish the price of it: for {according} to the number {of the years} of the fruits doth he sell unto thee.', 'according to the multitude of years thou shalt increase the price thereof and according to the fewness of years thou shalt diminish the price of it for according to the number of the years of the fruits doth he sell unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 17, 'Ye shall not therefore oppress one another; but thou shalt fear thy God: for I {am} the LORD your God.', 'ye shall not therefore oppress one another but thou shalt fear thy god for i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 18, 'Wherefore ye shall do my statutes, and keep my judgments, and do them; and ye shall dwell in the land in safety.', 'wherefore ye shall do my statutes and keep my judgments and do them and ye shall dwell in the land in safety');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 19, 'And the land shall yield her fruit, and ye shall eat your fill, and dwell therein in safety.', 'and the land shall yield her fruit and ye shall eat your fill and dwell therein in safety');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 20, 'And if ye shall say, What shall we eat the seventh year? behold, we shall not sow, nor gather in our increase:', 'and if ye shall say what shall we eat the seventh year behold we shall not sow nor gather in our increase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 21, 'Then I will command my blessing upon you in the sixth year, and it shall bring forth fruit for three years.', 'then i will command my blessing upon you in the sixth year and it shall bring forth fruit for three years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 22, 'And ye shall sow the eighth year, and eat {yet} of old fruit until the ninth year; until her fruits come in ye shall eat {of} the old {store}.', 'and ye shall sow the eighth year and eat yet of old fruit until the ninth year until her fruits come in ye shall eat of the old store');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 23, 'The land shall not be sold for ever: for the land {is} mine; for ye {are} strangers and sojourners with me. {for ever: or, to be quite cut off: Heb. for cutting off}', 'the land shall not be sold for ever for the land is mine for ye are strangers and sojourners with me for ever or to be quite cut off heb for cutting off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 24, 'And in all the land of your possession ye shall grant a redemption for the land.', 'and in all the land of your possession ye shall grant a redemption for the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 25, 'If thy brother be waxen poor, and hath sold away {some} of his possession, and if any of his kin come to redeem it, then shall he redeem that which his brother sold.', 'if thy brother be waxen poor and hath sold away some of his possession and if any of his kin come to redeem it then shall he redeem that which his brother sold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 26, 'And if the man have none to redeem it, and himself be able to redeem it; {himself...: Heb. his hand hath attained and found sufficiency}', 'and if the man have none to redeem it and himself be able to redeem it himself heb his hand hath attained and found sufficiency');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 27, 'Then let him count the years of the sale thereof, and restore the overplus unto the man to whom he sold it; that he may return unto his possession.', 'then let him count the years of the sale thereof and restore the overplus unto the man to whom he sold it that he may return unto his possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 28, 'But if he be not able to restore {it} to him, then that which is sold shall remain in the hand of him that hath bought it until the year of jubile: and in the jubile it shall go out, and he shall return unto his possession.', 'but if he be not able to restore it to him then that which is sold shall remain in the hand of him that hath bought it until the year of jubile and in the jubile it shall go out and he shall return unto his possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 29, 'And if a man sell a dwelling house in a walled city, then he may redeem it within a whole year after it is sold; {within} a full year may he redeem it.', 'and if a man sell a dwelling house in a walled city then he may redeem it within a whole year after it is sold within a full year may he redeem it');
