INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 31, 'But the houses of the villages which have no wall round about them shall be counted as the fields of the country: they may be redeemed, and they shall go out in the jubile. {they may...: Heb. redemption belongeth unto it}', 'but the houses of the villages which have no wall round about them shall be counted as the fields of the country they may be redeemed and they shall go out in the jubile they may heb redemption belongeth unto it');
