INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 51, 'If {there be} yet many years {behind}, according unto them he shall give again the price of his redemption out of the money that he was bought for.', 'if there be yet many years behind according unto them he shall give again the price of his redemption out of the money that he was bought for');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 25, 52, 'And if there remain but few years unto the year of jubile, then he shall count with him, {and} according unto his years shall he give him again the price of his redemption.', 'and if there remain but few years unto the year of jubile then he shall count with him and according unto his years shall he give him again the price of his redemption');
