INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 13, 'I {am} the LORD your God, which brought you forth out of the land of Egypt, that ye should not be their bondmen; and I have broken the bands of your yoke, and made you go upright.', 'i am the lord your god which brought you forth out of the land of egypt that ye should not be their bondmen and i have broken the bands of your yoke and made you go upright');
