INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 17, 'And I will set my face against you, and ye shall be slain before your enemies: they that hate you shall reign over you; and ye shall flee when none pursueth you.', 'and i will set my face against you and ye shall be slain before your enemies they that hate you shall reign over you and ye shall flee when none pursueth you');
