INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 22, 'I will also send wild beasts among you, which shall rob you of your children, and destroy your cattle, and make you few in number; and your {high} ways shall be desolate.', 'i will also send wild beasts among you which shall rob you of your children and destroy your cattle and make you few in number and your high ways shall be desolate');
