INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 25, 'And I will bring a sword upon you, that shall avenge the quarrel of {my} covenant: and when ye are gathered together within your cities, I will send the pestilence among you; and ye shall be delivered into the hand of the enemy.', 'and i will bring a sword upon you that shall avenge the quarrel of my covenant and when ye are gathered together within your cities i will send the pestilence among you and ye shall be delivered into the hand of the enemy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 26, '{And} when I have broken the staff of your bread, ten women shall bake your bread in one oven, and they shall deliver {you} your bread again by weight: and ye shall eat, and not be satisfied.', 'and when i have broken the staff of your bread ten women shall bake your bread in one oven and they shall deliver you your bread again by weight and ye shall eat and not be satisfied');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 27, 'And if ye will not for all this hearken unto me, but walk contrary unto me;', 'and if ye will not for all this hearken unto me but walk contrary unto me');
