INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 31, 'And I will make your cities waste, and bring your sanctuaries unto desolation, and I will not smell the savour of your sweet odours.', 'and i will make your cities waste and bring your sanctuaries unto desolation and i will not smell the savour of your sweet odours');
