INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 34, 'Then shall the land enjoy her sabbaths, as long as it lieth desolate, and ye {be} in your enemies'' land; {even} then shall the land rest, and enjoy her sabbaths.', 'then shall the land enjoy her sabbaths as long as it lieth desolate and ye be in your enemies land even then shall the land rest and enjoy her sabbaths');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 35, 'As long as it lieth desolate it shall rest; because it did not rest in your sabbaths, when ye dwelt upon it.', 'as long as it lieth desolate it shall rest because it did not rest in your sabbaths when ye dwelt upon it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 36, 'And upon them that are left {alive} of you I will send a faintness into their hearts in the lands of their enemies; and the sound of a shaken leaf shall chase them; and they shall flee, as fleeing from a sword; and they shall fall when none pursueth. {shaken: Heb. driven}', 'and upon them that are left alive of you i will send a faintness into their hearts in the lands of their enemies and the sound of a shaken leaf shall chase them and they shall flee as fleeing from a sword and they shall fall when none pursueth shaken heb driven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 37, 'And they shall fall one upon another, as it were before a sword, when none pursueth: and ye shall have no power to stand before your enemies.', 'and they shall fall one upon another as it were before a sword when none pursueth and ye shall have no power to stand before your enemies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 38, 'And ye shall perish among the heathen, and the land of your enemies shall eat you up.', 'and ye shall perish among the heathen and the land of your enemies shall eat you up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 39, 'And they that are left of you shall pine away in their iniquity in your enemies'' lands; and also in the iniquities of their fathers shall they pine away with them.', 'and they that are left of you shall pine away in their iniquity in your enemies lands and also in the iniquities of their fathers shall they pine away with them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 40, 'If they shall confess their iniquity, and the iniquity of their fathers, with their trespass which they trespassed against me, and that also they have walked contrary unto me;', 'if they shall confess their iniquity and the iniquity of their fathers with their trespass which they trespassed against me and that also they have walked contrary unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 41, 'And {that} I also have walked contrary unto them, and have brought them into the land of their enemies; if then their uncircumcised hearts be humbled, and they then accept of the punishment of their iniquity:', 'and that i also have walked contrary unto them and have brought them into the land of their enemies if then their uncircumcised hearts be humbled and they then accept of the punishment of their iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 42, 'Then will I remember my covenant with Jacob, and also my covenant with Isaac, and also my covenant with Abraham will I remember; and I will remember the land.', 'then will i remember my covenant with jacob and also my covenant with isaac and also my covenant with abraham will i remember and i will remember the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 43, 'The land also shall be left of them, and shall enjoy her sabbaths, while she lieth desolate without them: and they shall accept of the punishment of their iniquity: because, even because they despised my judgments, and because their soul abhorred my statutes.', 'the land also shall be left of them and shall enjoy her sabbaths while she lieth desolate without them and they shall accept of the punishment of their iniquity because even because they despised my judgments and because their soul abhorred my statutes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 44, 'And yet for all that, when they be in the land of their enemies, I will not cast them away, neither will I abhor them, to destroy them utterly, and to break my covenant with them: for I {am} the LORD their God.', 'and yet for all that when they be in the land of their enemies i will not cast them away neither will i abhor them to destroy them utterly and to break my covenant with them for i am the lord their god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 45, 'But I will for their sakes remember the covenant of their ancestors, whom I brought forth out of the land of Egypt in the sight of the heathen, that I might be their God: I {am} the LORD.', 'but i will for their sakes remember the covenant of their ancestors whom i brought forth out of the land of egypt in the sight of the heathen that i might be their god i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 26, 46, 'These {are} the statutes and judgments and laws, which the LORD made between him and the children of Israel in mount Sinai by the hand of Moses.', 'these are the statutes and judgments and laws which the lord made between him and the children of israel in mount sinai by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 2, 'Speak unto the children of Israel, and say unto them, When a man shall make a singular vow, the persons {shall be} for the LORD by thy estimation.', 'speak unto the children of israel and say unto them when a man shall make a singular vow the persons shall be for the lord by thy estimation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 3, 'And thy estimation shall be of the male from twenty years old even unto sixty years old, even thy estimation shall be fifty shekels of silver, after the shekel of the sanctuary.', 'and thy estimation shall be of the male from twenty years old even unto sixty years old even thy estimation shall be fifty shekels of silver after the shekel of the sanctuary');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 4, 'And if it {be} a female, then thy estimation shall be thirty shekels.', 'and if it be a female then thy estimation shall be thirty shekels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 5, 'And if {it be} from five years old even unto twenty years old, then thy estimation shall be of the male twenty shekels, and for the female ten shekels.', 'and if it be from five years old even unto twenty years old then thy estimation shall be of the male twenty shekels and for the female ten shekels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 6, 'And if {it be} from a month old even unto five years old, then thy estimation shall be of the male five shekels of silver, and for the female thy estimation {shall be} three shekels of silver.', 'and if it be from a month old even unto five years old then thy estimation shall be of the male five shekels of silver and for the female thy estimation shall be three shekels of silver');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 7, 'And if {it be} from sixty years old and above; if {it be} a male, then thy estimation shall be fifteen shekels, and for the female ten shekels.', 'and if it be from sixty years old and above if it be a male then thy estimation shall be fifteen shekels and for the female ten shekels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 8, 'But if he be poorer than thy estimation, then he shall present himself before the priest, and the priest shall value him; according to his ability that vowed shall the priest value him.', 'but if he be poorer than thy estimation then he shall present himself before the priest and the priest shall value him according to his ability that vowed shall the priest value him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 9, 'And if {it be} a beast, whereof men bring an offering unto the LORD, all that {any man} giveth of such unto the LORD shall be holy.', 'and if it be a beast whereof men bring an offering unto the lord all that any man giveth of such unto the lord shall be holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 10, 'He shall not alter it, nor change it, a good for a bad, or a bad for a good: and if he shall at all change beast for beast, then it and the exchange thereof shall be holy.', 'he shall not alter it nor change it a good for a bad or a bad for a good and if he shall at all change beast for beast then it and the exchange thereof shall be holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 11, 'And if {it be} any unclean beast, of which they do not offer a sacrifice unto the LORD, then he shall present the beast before the priest:', 'and if it be any unclean beast of which they do not offer a sacrifice unto the lord then he shall present the beast before the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 12, 'And the priest shall value it, whether it be good or bad: as thou valuest it, {who art} the priest, so shall it be. {as...: Heb. according to thy estimation, O priest, etc}', 'and the priest shall value it whether it be good or bad as thou valuest it who art the priest so shall it be as heb according to thy estimation o priest etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 13, 'But if he will at all redeem it, then he shall add a fifth {part} thereof unto thy estimation.', 'but if he will at all redeem it then he shall add a fifth part thereof unto thy estimation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 14, 'And when a man shall sanctify his house {to be} holy unto the LORD, then the priest shall estimate it, whether it be good or bad: as the priest shall estimate it, so shall it stand.', 'and when a man shall sanctify his house to be holy unto the lord then the priest shall estimate it whether it be good or bad as the priest shall estimate it so shall it stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 15, 'And if he that sanctified it will redeem his house, then he shall add the fifth {part} of the money of thy estimation unto it, and it shall be his.', 'and if he that sanctified it will redeem his house then he shall add the fifth part of the money of thy estimation unto it and it shall be his');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 16, 'And if a man shall sanctify unto the LORD {some part} of a field of his possession, then thy estimation shall be according to the seed thereof: an homer of barley seed {shall be valued} at fifty shekels of silver. {an...: or, the land of an homer, etc}', 'and if a man shall sanctify unto the lord some part of a field of his possession then thy estimation shall be according to the seed thereof an homer of barley seed shall be valued at fifty shekels of silver an or the land of an homer etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 17, 'If he sanctify his field from the year of jubile, according to thy estimation it shall stand.', 'if he sanctify his field from the year of jubile according to thy estimation it shall stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 18, 'But if he sanctify his field after the jubile, then the priest shall reckon unto him the money according to the years that remain, even unto the year of the jubile, and it shall be abated from thy estimation.', 'but if he sanctify his field after the jubile then the priest shall reckon unto him the money according to the years that remain even unto the year of the jubile and it shall be abated from thy estimation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 19, 'And if he that sanctified the field will in any wise redeem it, then he shall add the fifth {part} of the money of thy estimation unto it, and it shall be assured to him.', 'and if he that sanctified the field will in any wise redeem it then he shall add the fifth part of the money of thy estimation unto it and it shall be assured to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 20, 'And if he will not redeem the field, or if he have sold the field to another man, it shall not be redeemed any more.', 'and if he will not redeem the field or if he have sold the field to another man it shall not be redeemed any more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 21, 'But the field, when it goeth out in the jubile, shall be holy unto the LORD, as a field devoted; the possession thereof shall be the priest''s.', 'but the field when it goeth out in the jubile shall be holy unto the lord as a field devoted the possession thereof shall be the priest s');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 22, 'And if {a man} sanctify unto the LORD a field which he hath bought, which {is} not of the fields of his possession;', 'and if a man sanctify unto the lord a field which he hath bought which is not of the fields of his possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 23, 'Then the priest shall reckon unto him the worth of thy estimation, {even} unto the year of the jubile: and he shall give thine estimation in that day, {as} a holy thing unto the LORD.', 'then the priest shall reckon unto him the worth of thy estimation even unto the year of the jubile and he shall give thine estimation in that day as a holy thing unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 24, 'In the year of the jubile the field shall return unto him of whom it was bought, {even} to him to whom the possession of the land {did belong}.', 'in the year of the jubile the field shall return unto him of whom it was bought even to him to whom the possession of the land did belong');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 25, 'And all thy estimations shall be according to the shekel of the sanctuary: twenty gerahs shall be the shekel.', 'and all thy estimations shall be according to the shekel of the sanctuary twenty gerahs shall be the shekel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 26, 'Only the firstling of the beasts, which should be the LORD''S firstling, no man shall sanctify it; whether {it be} ox, or sheep: it {is} the LORD''S. {firstling of: Heb. firstborn, etc}', 'only the firstling of the beasts which should be the lord s firstling no man shall sanctify it whether it be ox or sheep it is the lord s firstling of heb firstborn etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 27, 'And if {it be} of an unclean beast, then he shall redeem {it} according to thine estimation, and shall add a fifth {part} of it thereto: or if it be not redeemed, then it shall be sold according to thy estimation.', 'and if it be of an unclean beast then he shall redeem it according to thine estimation and shall add a fifth part of it thereto or if it be not redeemed then it shall be sold according to thy estimation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 28, 'Notwithstanding no devoted thing, that a man shall devote unto the LORD of all that he hath, {both} of man and beast, and of the field of his possession, shall be sold or redeemed: every devoted thing {is} most holy unto the LORD.', 'notwithstanding no devoted thing that a man shall devote unto the lord of all that he hath both of man and beast and of the field of his possession shall be sold or redeemed every devoted thing is most holy unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 29, 'None devoted, which shall be devoted of men, shall be redeemed; {but} shall surely be put to death.', 'none devoted which shall be devoted of men shall be redeemed but shall surely be put to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 30, 'And all the tithe of the land, {whether} of the seed of the land, {or} of the fruit of the tree, {is} the LORD''S: {it is} holy unto the LORD.', 'and all the tithe of the land whether of the seed of the land or of the fruit of the tree is the lord s it is holy unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 31, 'And if a man will at all redeem {ought} of his tithes, he shall add thereto the fifth {part} thereof.', 'and if a man will at all redeem ought of his tithes he shall add thereto the fifth part thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 32, 'And concerning the tithe of the herd, or of the flock, {even} of whatsoever passeth under the rod, the tenth shall be holy unto the LORD.', 'and concerning the tithe of the herd or of the flock even of whatsoever passeth under the rod the tenth shall be holy unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 3, 'Unknown', 27, 33, 'He shall not search whether it be good or bad, neither shall he change it: and if he change it at all, then both it and the change thereof shall be holy; it shall not be redeemed.', 'he shall not search whether it be good or bad neither shall he change it and if he change it at all then both it and the change thereof shall be holy it shall not be redeemed');
