INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 6, 'And shall put thereon the covering of badgers'' skins, and shall spread over {it} a cloth wholly of blue, and shall put in the staves thereof.', 'and shall put thereon the covering of badgers skins and shall spread over it a cloth wholly of blue and shall put in the staves thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 7, 'And upon the table of shewbread they shall spread a cloth of blue, and put thereon the dishes, and the spoons, and the bowls, and covers to cover withal: and the continual bread shall be thereon: {cover...: or, pour out withal}', 'and upon the table of shewbread they shall spread a cloth of blue and put thereon the dishes and the spoons and the bowls and covers to cover withal and the continual bread shall be thereon cover or pour out withal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 8, 'And they shall spread upon them a cloth of scarlet, and cover the same with a covering of badgers'' skins, and shall put in the staves thereof.', 'and they shall spread upon them a cloth of scarlet and cover the same with a covering of badgers skins and shall put in the staves thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 9, 'And they shall take a cloth of blue, and cover the candlestick of the light, and his lamps, and his tongs, and his snuffdishes, and all the oil vessels thereof, wherewith they minister unto it:', 'and they shall take a cloth of blue and cover the candlestick of the light and his lamps and his tongs and his snuffdishes and all the oil vessels thereof wherewith they minister unto it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 10, 'And they shall put it and all the vessels thereof within a covering of badgers'' skins, and shall put {it} upon a bar.', 'and they shall put it and all the vessels thereof within a covering of badgers skins and shall put it upon a bar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 11, 'And upon the golden altar they shall spread a cloth of blue, and cover it with a covering of badgers'' skins, and shall put to the staves thereof:', 'and upon the golden altar they shall spread a cloth of blue and cover it with a covering of badgers skins and shall put to the staves thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 12, 'And they shall take all the instruments of ministry, wherewith they minister in the sanctuary, and put {them} in a cloth of blue, and cover them with a covering of badgers'' skins, and shall put {them} on a bar:', 'and they shall take all the instruments of ministry wherewith they minister in the sanctuary and put them in a cloth of blue and cover them with a covering of badgers skins and shall put them on a bar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 13, 'And they shall take away the ashes from the altar, and spread a purple cloth thereon:', 'and they shall take away the ashes from the altar and spread a purple cloth thereon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 14, 'And they shall put upon it all the vessels thereof, wherewith they minister about it, {even} the censers, the fleshhooks, and the shovels, and the basons, all the vessels of the altar; and they shall spread upon it a covering of badgers'' skins, and put to the staves of it. {basons: or, bowls}', 'and they shall put upon it all the vessels thereof wherewith they minister about it even the censers the fleshhooks and the shovels and the basons all the vessels of the altar and they shall spread upon it a covering of badgers skins and put to the staves of it basons or bowls');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 15, 'And when Aaron and his sons have made an end of covering the sanctuary, and all the vessels of the sanctuary, as the camp is to set forward; after that, the sons of Kohath shall come to bear {it}: but they shall not touch {any} holy thing, lest they die. These {things are} the burden of the sons of Kohath in the tabernacle of the congregation.', 'and when aaron and his sons have made an end of covering the sanctuary and all the vessels of the sanctuary as the camp is to set forward after that the sons of kohath shall come to bear it but they shall not touch any holy thing lest they die these things are the burden of the sons of kohath in the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 16, 'And to the office of Eleazar the son of Aaron the priest {pertaineth} the oil for the light, and the sweet incense, and the daily meat offering, and the anointing oil, {and} the oversight of all the tabernacle, and of all that therein {is}, in the sanctuary, and in the vessels thereof.', 'and to the office of eleazar the son of aaron the priest pertaineth the oil for the light and the sweet incense and the daily meat offering and the anointing oil and the oversight of all the tabernacle and of all that therein is in the sanctuary and in the vessels thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 17, 'And the LORD spake unto Moses and unto Aaron, saying,', 'and the lord spake unto moses and unto aaron saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 18, 'Cut ye not off the tribe of the families of the Kohathites from among the Levites:', 'cut ye not off the tribe of the families of the kohathites from among the levites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 19, 'But thus do unto them, that they may live, and not die, when they approach unto the most holy things: Aaron and his sons shall go in, and appoint them every one to his service and to his burden:', 'but thus do unto them that they may live and not die when they approach unto the most holy things aaron and his sons shall go in and appoint them every one to his service and to his burden');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 20, 'But they shall not go in to see when the holy things are covered, lest they die.', 'but they shall not go in to see when the holy things are covered lest they die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 21, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 22, 'Take also the sum of the sons of Gershon, throughout the houses of their fathers, by their families;', 'take also the sum of the sons of gershon throughout the houses of their fathers by their families');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 23, 'From thirty years old and upward until fifty years old shalt thou number them; all that enter in to perform the service, to do the work in the tabernacle of the congregation. {to perform...: Heb. to war the warfare}', 'from thirty years old and upward until fifty years old shalt thou number them all that enter in to perform the service to do the work in the tabernacle of the congregation to perform heb to war the warfare');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 24, 'This {is} the service of the families of the Gershonites, to serve, and for burdens: {burdens: or, carriage}', 'this is the service of the families of the gershonites to serve and for burdens burdens or carriage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 25, 'And they shall bear the curtains of the tabernacle, and the tabernacle of the congregation, his covering, and the covering of the badgers'' skins that {is} above upon it, and the hanging for the door of the tabernacle of the congregation,', 'and they shall bear the curtains of the tabernacle and the tabernacle of the congregation his covering and the covering of the badgers skins that is above upon it and the hanging for the door of the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 26, 'And the hangings of the court, and the hanging for the door of the gate of the court, which {is} by the tabernacle and by the altar round about, and their cords, and all the instruments of their service, and all that is made for them: so shall they serve.', 'and the hangings of the court and the hanging for the door of the gate of the court which is by the tabernacle and by the altar round about and their cords and all the instruments of their service and all that is made for them so shall they serve');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 27, 'At the appointment of Aaron and his sons shall be all the service of the sons of the Gershonites, in all their burdens, and in all their service: and ye shall appoint unto them in charge all their burdens. {appointment: Heb. mouth}', 'at the appointment of aaron and his sons shall be all the service of the sons of the gershonites in all their burdens and in all their service and ye shall appoint unto them in charge all their burdens appointment heb mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 28, 'This {is} the service of the families of the sons of Gershon in the tabernacle of the congregation: and their charge {shall be} under the hand of Ithamar the son of Aaron the priest.', 'this is the service of the families of the sons of gershon in the tabernacle of the congregation and their charge shall be under the hand of ithamar the son of aaron the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 29, 'As for the sons of Merari, thou shalt number them after their families, by the house of their fathers;', 'as for the sons of merari thou shalt number them after their families by the house of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 30, 'From thirty years old and upward even unto fifty years old shalt thou number them, every one that entereth into the service, to do the work of the tabernacle of the congregation. {service: Heb. warfare}', 'from thirty years old and upward even unto fifty years old shalt thou number them every one that entereth into the service to do the work of the tabernacle of the congregation service heb warfare');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 31, 'And this {is} the charge of their burden, according to all their service in the tabernacle of the congregation; the boards of the tabernacle, and the bars thereof, and the pillars thereof, and sockets thereof,', 'and this is the charge of their burden according to all their service in the tabernacle of the congregation the boards of the tabernacle and the bars thereof and the pillars thereof and sockets thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 32, 'And the pillars of the court round about, and their sockets, and their pins, and their cords, with all their instruments, and with all their service: and by name ye shall reckon the instruments of the charge of their burden.', 'and the pillars of the court round about and their sockets and their pins and their cords with all their instruments and with all their service and by name ye shall reckon the instruments of the charge of their burden');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 33, 'This {is} the service of the families of the sons of Merari, according to all their service, in the tabernacle of the congregation, under the hand of Ithamar the son of Aaron the priest.', 'this is the service of the families of the sons of merari according to all their service in the tabernacle of the congregation under the hand of ithamar the son of aaron the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 34, 'And Moses and Aaron and the chief of the congregation numbered the sons of the Kohathites after their families, and after the house of their fathers,', 'and moses and aaron and the chief of the congregation numbered the sons of the kohathites after their families and after the house of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 35, 'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation:', 'from thirty years old and upward even unto fifty years old every one that entereth into the service for the work in the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 36, 'And those that were numbered of them by their families were two thousand seven hundred and fifty.', 'and those that were numbered of them by their families were two thousand seven hundred and fifty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 37, 'These {were} they that were numbered of the families of the Kohathites, all that might do service in the tabernacle of the congregation, which Moses and Aaron did number according to the commandment of the LORD by the hand of Moses.', 'these were they that were numbered of the families of the kohathites all that might do service in the tabernacle of the congregation which moses and aaron did number according to the commandment of the lord by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 38, 'And those that were numbered of the sons of Gershon, throughout their families, and by the house of their fathers,', 'and those that were numbered of the sons of gershon throughout their families and by the house of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 39, 'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,', 'from thirty years old and upward even unto fifty years old every one that entereth into the service for the work in the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 40, 'Even those that were numbered of them, throughout their families, by the house of their fathers, were two thousand and six hundred and thirty.', 'even those that were numbered of them throughout their families by the house of their fathers were two thousand and six hundred and thirty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 41, 'These {are} they that were numbered of the families of the sons of Gershon, of all that might do service in the tabernacle of the congregation, whom Moses and Aaron did number according to the commandment of the LORD.', 'these are they that were numbered of the families of the sons of gershon of all that might do service in the tabernacle of the congregation whom moses and aaron did number according to the commandment of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 42, 'And those that were numbered of the families of the sons of Merari, throughout their families, by the house of their fathers,', 'and those that were numbered of the families of the sons of merari throughout their families by the house of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 43, 'From thirty years old and upward even unto fifty years old, every one that entereth into the service, for the work in the tabernacle of the congregation,', 'from thirty years old and upward even unto fifty years old every one that entereth into the service for the work in the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 44, 'Even those that were numbered of them after their families, were three thousand and two hundred.', 'even those that were numbered of them after their families were three thousand and two hundred');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 45, 'These {be} those that were numbered of the families of the sons of Merari, whom Moses and Aaron numbered according to the word of the LORD by the hand of Moses.', 'these be those that were numbered of the families of the sons of merari whom moses and aaron numbered according to the word of the lord by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 46, 'All those that were numbered of the Levites, whom Moses and Aaron and the chief of Israel numbered, after their families, and after the house of their fathers,', 'all those that were numbered of the levites whom moses and aaron and the chief of israel numbered after their families and after the house of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 47, 'From thirty years old and upward even unto fifty years old, every one that came to do the service of the ministry, and the service of the burden in the tabernacle of the congregation,', 'from thirty years old and upward even unto fifty years old every one that came to do the service of the ministry and the service of the burden in the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 48, 'Even those that were numbered of them, were eight thousand and five hundred and fourscore.', 'even those that were numbered of them were eight thousand and five hundred and fourscore');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 4, 49, 'According to the commandment of the LORD they were numbered by the hand of Moses, every one according to his service, and according to his burden: thus were they numbered of him, as the LORD commanded Moses.', 'according to the commandment of the lord they were numbered by the hand of moses every one according to his service and according to his burden thus were they numbered of him as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 2, 'Command the children of Israel, that they put out of the camp every leper, and every one that hath an issue, and whosoever is defiled by the dead:', 'command the children of israel that they put out of the camp every leper and every one that hath an issue and whosoever is defiled by the dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 3, 'Both male and female shall ye put out, without the camp shall ye put them; that they defile not their camps, in the midst whereof I dwell.', 'both male and female shall ye put out without the camp shall ye put them that they defile not their camps in the midst whereof i dwell');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 4, 'And the children of Israel did so, and put them out without the camp: as the LORD spake unto Moses, so did the children of Israel.', 'and the children of israel did so and put them out without the camp as the lord spake unto moses so did the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 5, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 6, 'Speak unto the children of Israel, When a man or woman shall commit any sin that men commit, to do a trespass against the LORD, and that person be guilty;', 'speak unto the children of israel when a man or woman shall commit any sin that men commit to do a trespass against the lord and that person be guilty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 7, 'Then they shall confess their sin which they have done: and he shall recompense his trespass with the principal thereof, and add unto it the fifth {part} thereof, and give {it} unto {him} against whom he hath trespassed.', 'then they shall confess their sin which they have done and he shall recompense his trespass with the principal thereof and add unto it the fifth part thereof and give it unto him against whom he hath trespassed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 8, 'But if the man have no kinsman to recompense the trespass unto, let the trespass be recompensed unto the LORD, {even} to the priest; beside the ram of the atonement, whereby an atonement shall be made for him.', 'but if the man have no kinsman to recompense the trespass unto let the trespass be recompensed unto the lord even to the priest beside the ram of the atonement whereby an atonement shall be made for him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 9, 'And every offering of all the holy things of the children of Israel, which they bring unto the priest, shall be his. {offering: or, heave offering}', 'and every offering of all the holy things of the children of israel which they bring unto the priest shall be his offering or heave offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 10, 'And every man''s hallowed things shall be his: whatsoever any man giveth the priest, it shall be his.', 'and every man s hallowed things shall be his whatsoever any man giveth the priest it shall be his');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 11, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 12, 'Speak unto the children of Israel, and say unto them, If any man''s wife go aside, and commit a trespass against him,', 'speak unto the children of israel and say unto them if any man s wife go aside and commit a trespass against him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 13, 'And a man lie with her carnally, and it be hid from the eyes of her husband, and be kept close, and she be defiled, and {there be} no witness against her, neither she be taken {with the manner};', 'and a man lie with her carnally and it be hid from the eyes of her husband and be kept close and she be defiled and there be no witness against her neither she be taken with the manner');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 14, 'And the spirit of jealousy come upon him, and he be jealous of his wife, and she be defiled: or if the spirit of jealousy come upon him, and he be jealous of his wife, and she be not defiled:', 'and the spirit of jealousy come upon him and he be jealous of his wife and she be defiled or if the spirit of jealousy come upon him and he be jealous of his wife and she be not defiled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 15, 'Then shall the man bring his wife unto the priest, and he shall bring her offering for her, the tenth {part} of an ephah of barley meal; he shall pour no oil upon it, nor put frankincense thereon; for it {is} an offering of jealousy, an offering of memorial, bringing iniquity to remembrance.', 'then shall the man bring his wife unto the priest and he shall bring her offering for her the tenth part of an ephah of barley meal he shall pour no oil upon it nor put frankincense thereon for it is an offering of jealousy an offering of memorial bringing iniquity to remembrance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 16, 'And the priest shall bring her near, and set her before the LORD:', 'and the priest shall bring her near and set her before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 17, 'And the priest shall take holy water in an earthen vessel; and of the dust that is in the floor of the tabernacle the priest shall take, and put {it} into the water:', 'and the priest shall take holy water in an earthen vessel and of the dust that is in the floor of the tabernacle the priest shall take and put it into the water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 18, 'And the priest shall set the woman before the LORD, and uncover the woman''s head, and put the offering of memorial in her hands, which {is} the jealousy offering: and the priest shall have in his hand the bitter water that causeth the curse:', 'and the priest shall set the woman before the lord and uncover the woman s head and put the offering of memorial in her hands which is the jealousy offering and the priest shall have in his hand the bitter water that causeth the curse');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 19, 'And the priest shall charge her by an oath, and say unto the woman, If no man have lain with thee, and if thou hast not gone aside to uncleanness {with another} instead of thy husband, be thou free from this bitter water that causeth the curse: {with another...: or, being in the power of thy husband: Heb. under thy husband}', 'and the priest shall charge her by an oath and say unto the woman if no man have lain with thee and if thou hast not gone aside to uncleanness with another instead of thy husband be thou free from this bitter water that causeth the curse with another or being in the power of thy husband heb under thy husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 20, 'But if thou hast gone aside {to another} instead of thy husband, and if thou be defiled, and some man have lain with thee beside thine husband:', 'but if thou hast gone aside to another instead of thy husband and if thou be defiled and some man have lain with thee beside thine husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 21, 'Then the priest shall charge the woman with an oath of cursing, and the priest shall say unto the woman, The LORD make thee a curse and an oath among thy people, when the LORD doth make thy thigh to rot, and thy belly to swell; {rot: Heb. fall}', 'then the priest shall charge the woman with an oath of cursing and the priest shall say unto the woman the lord make thee a curse and an oath among thy people when the lord doth make thy thigh to rot and thy belly to swell rot heb fall');
