INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 26, 'And the priest shall take an handful of the offering, {even} the memorial thereof, and burn {it} upon the altar, and afterward shall cause the woman to drink the water.', 'and the priest shall take an handful of the offering even the memorial thereof and burn it upon the altar and afterward shall cause the woman to drink the water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 27, 'And when he hath made her to drink the water, then it shall come to pass, {that}, if she be defiled, and have done trespass against her husband, that the water that causeth the curse shall enter into her, {and become} bitter, and her belly shall swell, and her thigh shall rot: and the woman shall be a curse among her people.', 'and when he hath made her to drink the water then it shall come to pass that if she be defiled and have done trespass against her husband that the water that causeth the curse shall enter into her and become bitter and her belly shall swell and her thigh shall rot and the woman shall be a curse among her people');
