INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 29, 'This {is} the law of jealousies, when a wife goeth aside {to another} instead of her husband, and is defiled;', 'this is the law of jealousies when a wife goeth aside to another instead of her husband and is defiled');
