INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 5, 31, 'Then shall the man be guiltless from iniquity, and this woman shall bear her iniquity.', 'then shall the man be guiltless from iniquity and this woman shall bear her iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 2, 'Speak unto the children of Israel, and say unto them, When either man or woman shall separate {themselves} to vow a vow of a Nazarite, to separate {themselves} unto the LORD: {to separate...: or, to make themselves Nazarites}', 'speak unto the children of israel and say unto them when either man or woman shall separate themselves to vow a vow of a nazarite to separate themselves unto the lord to separate or to make themselves nazarites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 3, 'He shall separate {himself} from wine and strong drink, and shall drink no vinegar of wine, or vinegar of strong drink, neither shall he drink any liquor of grapes, nor eat moist grapes, or dried.', 'he shall separate himself from wine and strong drink and shall drink no vinegar of wine or vinegar of strong drink neither shall he drink any liquor of grapes nor eat moist grapes or dried');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 4, 'All the days of his separation shall he eat nothing that is made of the vine tree, from the kernels even to the husk. {separation: or, Nazariteship} {vine...: Heb. vine of the wine}', 'all the days of his separation shall he eat nothing that is made of the vine tree from the kernels even to the husk separation or nazariteship vine heb vine of the wine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 5, 'All the days of the vow of his separation there shall no razor come upon his head: until the days be fulfilled, in the which he separateth {himself} unto the LORD, he shall be holy, {and} shall let the locks of the hair of his head grow.', 'all the days of the vow of his separation there shall no razor come upon his head until the days be fulfilled in the which he separateth himself unto the lord he shall be holy and shall let the locks of the hair of his head grow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 6, 'All the days that he separateth {himself} unto the LORD he shall come at no dead body.', 'all the days that he separateth himself unto the lord he shall come at no dead body');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 7, 'He shall not make himself unclean for his father, or for his mother, for his brother, or for his sister, when they die: because the consecration of his God {is} upon his head. {consecration: Heb. separation}', 'he shall not make himself unclean for his father or for his mother for his brother or for his sister when they die because the consecration of his god is upon his head consecration heb separation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 8, 'All the days of his separation he {is} holy unto the LORD.', 'all the days of his separation he is holy unto the lord');
