INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 12, 'And he shall consecrate unto the LORD the days of his separation, and shall bring a lamb of the first year for a trespass offering: but the days that were before shall be lost, because his separation was defiled. {be lost: Heb. fall}', 'and he shall consecrate unto the lord the days of his separation and shall bring a lamb of the first year for a trespass offering but the days that were before shall be lost because his separation was defiled be lost heb fall');
