INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 6, 17, 'And he shall offer the ram {for} a sacrifice of peace offerings unto the LORD, with the basket of unleavened bread: the priest shall offer also his meat offering, and his drink offering.', 'and he shall offer the ram for a sacrifice of peace offerings unto the lord with the basket of unleavened bread the priest shall offer also his meat offering and his drink offering');
