INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 7, 84, 'This {was} the dedication of the altar, in the day when it was anointed, by the princes of Israel: twelve chargers of silver, twelve silver bowls, twelve spoons of gold:', 'this was the dedication of the altar in the day when it was anointed by the princes of israel twelve chargers of silver twelve silver bowls twelve spoons of gold');
