INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 7, 89, 'And when Moses was gone into the tabernacle of the congregation to speak with him, then he heard the voice of one speaking unto him from off the mercy seat that {was} upon the ark of testimony, from between the two cherubims: and he spake unto him. {with him: that is, with God}', 'and when moses was gone into the tabernacle of the congregation to speak with him then he heard the voice of one speaking unto him from off the mercy seat that was upon the ark of testimony from between the two cherubims and he spake unto him with him that is with god');
