INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 2, 'Speak unto Aaron, and say unto him, When thou lightest the lamps, the seven lamps shall give light over against the candlestick.', 'speak unto aaron and say unto him when thou lightest the lamps the seven lamps shall give light over against the candlestick');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 3, 'And Aaron did so; he lighted the lamps thereof over against the candlestick, as the LORD commanded Moses.', 'and aaron did so he lighted the lamps thereof over against the candlestick as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 4, 'And this work of the candlestick {was of} beaten gold, unto the shaft thereof, unto the flowers thereof, {was} beaten work: according unto the pattern which the LORD had shewed Moses, so he made the candlestick.', 'and this work of the candlestick was of beaten gold unto the shaft thereof unto the flowers thereof was beaten work according unto the pattern which the lord had shewed moses so he made the candlestick');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 5, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 6, 'Take the Levites from among the children of Israel, and cleanse them.', 'take the levites from among the children of israel and cleanse them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 7, 'And thus shalt thou do unto them, to cleanse them: Sprinkle water of purifying upon them, and let them shave all their flesh, and let them wash their clothes, and {so} make themselves clean. {let them shave...: Heb. let them cause a razor to pass over, etc}', 'and thus shalt thou do unto them to cleanse them sprinkle water of purifying upon them and let them shave all their flesh and let them wash their clothes and so make themselves clean let them shave heb let them cause a razor to pass over etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 8, 'Then let them take a young bullock with his meat offering, {even} fine flour mingled with oil, and another young bullock shalt thou take for a sin offering.', 'then let them take a young bullock with his meat offering even fine flour mingled with oil and another young bullock shalt thou take for a sin offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 9, 'And thou shalt bring the Levites before the tabernacle of the congregation: and thou shalt gather the whole assembly of the children of Israel together:', 'and thou shalt bring the levites before the tabernacle of the congregation and thou shalt gather the whole assembly of the children of israel together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 10, 'And thou shalt bring the Levites before the LORD: and the children of Israel shall put their hands upon the Levites:', 'and thou shalt bring the levites before the lord and the children of israel shall put their hands upon the levites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 11, 'And Aaron shall offer the Levites before the LORD {for} an offering of the children of Israel, that they may execute the service of the LORD. {offer: Heb. wave} {offering: Heb. wave offering} {they...: Heb. they may be to execute, etc}', 'and aaron shall offer the levites before the lord for an offering of the children of israel that they may execute the service of the lord offer heb wave offering heb wave offering they heb they may be to execute etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 12, 'And the Levites shall lay their hands upon the heads of the bullocks: and thou shalt offer the one {for} a sin offering, and the other {for} a burnt offering, unto the LORD, to make an atonement for the Levites.', 'and the levites shall lay their hands upon the heads of the bullocks and thou shalt offer the one for a sin offering and the other for a burnt offering unto the lord to make an atonement for the levites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 13, 'And thou shalt set the Levites before Aaron, and before his sons, and offer them {for} an offering unto the LORD.', 'and thou shalt set the levites before aaron and before his sons and offer them for an offering unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 14, 'Thus shalt thou separate the Levites from among the children of Israel: and the Levites shall be mine.', 'thus shalt thou separate the levites from among the children of israel and the levites shall be mine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 15, 'And after that shall the Levites go in to do the service of the tabernacle of the congregation: and thou shalt cleanse them, and offer them {for} an offering.', 'and after that shall the levites go in to do the service of the tabernacle of the congregation and thou shalt cleanse them and offer them for an offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 16, 'For they {are} wholly given unto me from among the children of Israel; instead of such as open every womb, {even instead of} the firstborn of all the children of Israel, have I taken them unto me.', 'for they are wholly given unto me from among the children of israel instead of such as open every womb even instead of the firstborn of all the children of israel have i taken them unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 17, 'For all the firstborn of the children of Israel {are} mine, {both} man and beast: on the day that I smote every firstborn in the land of Egypt I sanctified them for myself.', 'for all the firstborn of the children of israel are mine both man and beast on the day that i smote every firstborn in the land of egypt i sanctified them for myself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 18, 'And I have taken the Levites for all the firstborn of the children of Israel.', 'and i have taken the levites for all the firstborn of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 19, 'And I have given the Levites {as} a gift to Aaron and to his sons from among the children of Israel, to do the service of the children of Israel in the tabernacle of the congregation, and to make an atonement for the children of Israel: that there be no plague among the children of Israel, when the children of Israel come nigh unto the sanctuary. {a gift: Heb. given}', 'and i have given the levites as a gift to aaron and to his sons from among the children of israel to do the service of the children of israel in the tabernacle of the congregation and to make an atonement for the children of israel that there be no plague among the children of israel when the children of israel come nigh unto the sanctuary a gift heb given');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 20, 'And Moses, and Aaron, and all the congregation of the children of Israel, did to the Levites according unto all that the LORD commanded Moses concerning the Levites, so did the children of Israel unto them.', 'and moses and aaron and all the congregation of the children of israel did to the levites according unto all that the lord commanded moses concerning the levites so did the children of israel unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 21, 'And the Levites were purified, and they washed their clothes; and Aaron offered them {as} an offering before the LORD; and Aaron made an atonement for them to cleanse them.', 'and the levites were purified and they washed their clothes and aaron offered them as an offering before the lord and aaron made an atonement for them to cleanse them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 22, 'And after that went the Levites in to do their service in the tabernacle of the congregation before Aaron, and before his sons: as the LORD had commanded Moses concerning the Levites, so did they unto them.', 'and after that went the levites in to do their service in the tabernacle of the congregation before aaron and before his sons as the lord had commanded moses concerning the levites so did they unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 23, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 24, 'This {is it} that {belongeth} unto the Levites: from twenty and five years old and upward they shall go in to wait upon the service of the tabernacle of the congregation: {to...: Heb. to war the warfare of, etc}', 'this is it that belongeth unto the levites from twenty and five years old and upward they shall go in to wait upon the service of the tabernacle of the congregation to heb to war the warfare of etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 25, 'And from the age of fifty years they shall cease waiting upon the service {thereof}, and shall serve no more: {cease...: Heb. return from the warfare of the service}', 'and from the age of fifty years they shall cease waiting upon the service thereof and shall serve no more cease heb return from the warfare of the service');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 8, 26, 'But shall minister with their brethren in the tabernacle of the congregation, to keep the charge, and shall do no service. Thus shalt thou do unto the Levites touching their charge.', 'but shall minister with their brethren in the tabernacle of the congregation to keep the charge and shall do no service thus shalt thou do unto the levites touching their charge');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 1, 'And the LORD spake unto Moses in the wilderness of Sinai, in the first month of the second year after they were come out of the land of Egypt, saying,', 'and the lord spake unto moses in the wilderness of sinai in the first month of the second year after they were come out of the land of egypt saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 2, 'Let the children of Israel also keep the passover at his appointed season.', 'let the children of israel also keep the passover at his appointed season');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 3, 'In the fourteenth day of this month, at even, ye shall keep it in his appointed season: according to all the rites of it, and according to all the ceremonies thereof, shall ye keep it. {at even: Heb. between the two evenings}', 'in the fourteenth day of this month at even ye shall keep it in his appointed season according to all the rites of it and according to all the ceremonies thereof shall ye keep it at even heb between the two evenings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 4, 'And Moses spake unto the children of Israel, that they should keep the passover.', 'and moses spake unto the children of israel that they should keep the passover');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 5, 'And they kept the passover on the fourteenth day of the first month at even in the wilderness of Sinai: according to all that the LORD commanded Moses, so did the children of Israel.', 'and they kept the passover on the fourteenth day of the first month at even in the wilderness of sinai according to all that the lord commanded moses so did the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 6, 'And there were certain men, who were defiled by the dead body of a man, that they could not keep the passover on that day: and they came before Moses and before Aaron on that day:', 'and there were certain men who were defiled by the dead body of a man that they could not keep the passover on that day and they came before moses and before aaron on that day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 7, 'And those men said unto him, We {are} defiled by the dead body of a man: wherefore are we kept back, that we may not offer an offering of the LORD in his appointed season among the children of Israel?', 'and those men said unto him we are defiled by the dead body of a man wherefore are we kept back that we may not offer an offering of the lord in his appointed season among the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 8, 'And Moses said unto them, Stand still, and I will hear what the LORD will command concerning you.', 'and moses said unto them stand still and i will hear what the lord will command concerning you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 9, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 10, 'Speak unto the children of Israel, saying, If any man of you or of your posterity shall be unclean by reason of a dead body, or {be} in a journey afar off, yet he shall keep the passover unto the LORD.', 'speak unto the children of israel saying if any man of you or of your posterity shall be unclean by reason of a dead body or be in a journey afar off yet he shall keep the passover unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 11, 'The fourteenth day of the second month at even they shall keep it, {and} eat it with unleavened bread and bitter {herbs}.', 'the fourteenth day of the second month at even they shall keep it and eat it with unleavened bread and bitter herbs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 12, 'They shall leave none of it unto the morning, nor break any bone of it: according to all the ordinances of the passover they shall keep it.', 'they shall leave none of it unto the morning nor break any bone of it according to all the ordinances of the passover they shall keep it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 13, 'But the man that {is} clean, and is not in a journey, and forbeareth to keep the passover, even the same soul shall be cut off from among his people: because he brought not the offering of the LORD in his appointed season, that man shall bear his sin.', 'but the man that is clean and is not in a journey and forbeareth to keep the passover even the same soul shall be cut off from among his people because he brought not the offering of the lord in his appointed season that man shall bear his sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 14, 'And if a stranger shall sojourn among you, and will keep the passover unto the LORD; according to the ordinance of the passover, and according to the manner thereof, so shall he do: ye shall have one ordinance, both for the stranger, and for him that was born in the land.', 'and if a stranger shall sojourn among you and will keep the passover unto the lord according to the ordinance of the passover and according to the manner thereof so shall he do ye shall have one ordinance both for the stranger and for him that was born in the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 15, 'And on the day that the tabernacle was reared up the cloud covered the tabernacle, {namely}, the tent of the testimony: and at even there was upon the tabernacle as it were the appearance of fire, until the morning.', 'and on the day that the tabernacle was reared up the cloud covered the tabernacle namely the tent of the testimony and at even there was upon the tabernacle as it were the appearance of fire until the morning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 16, 'So it was alway: the cloud covered it {by day}, and the appearance of fire by night.', 'so it was alway the cloud covered it by day and the appearance of fire by night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 17, 'And when the cloud was taken up from the tabernacle, then after that the children of Israel journeyed: and in the place where the cloud abode, there the children of Israel pitched their tents.', 'and when the cloud was taken up from the tabernacle then after that the children of israel journeyed and in the place where the cloud abode there the children of israel pitched their tents');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 18, 'At the commandment of the LORD the children of Israel journeyed, and at the commandment of the LORD they pitched: as long as the cloud abode upon the tabernacle they rested in their tents.', 'at the commandment of the lord the children of israel journeyed and at the commandment of the lord they pitched as long as the cloud abode upon the tabernacle they rested in their tents');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 19, 'And when the cloud tarried long upon the tabernacle many days, then the children of Israel kept the charge of the LORD, and journeyed not. {tarried...: Heb. prolonged}', 'and when the cloud tarried long upon the tabernacle many days then the children of israel kept the charge of the lord and journeyed not tarried heb prolonged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 20, 'And {so} it was, when the cloud was a few days upon the tabernacle; according to the commandment of the LORD they abode in their tents, and according to the commandment of the LORD they journeyed.', 'and so it was when the cloud was a few days upon the tabernacle according to the commandment of the lord they abode in their tents and according to the commandment of the lord they journeyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 21, 'And {so} it was, when the cloud abode from even unto the morning, and {that} the cloud was taken up in the morning, then they journeyed: whether {it was} by day or by night that the cloud was taken up, they journeyed. {abode: Heb. was}', 'and so it was when the cloud abode from even unto the morning and that the cloud was taken up in the morning then they journeyed whether it was by day or by night that the cloud was taken up they journeyed abode heb was');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 22, 'Or {whether it were} two days, or a month, or a year, that the cloud tarried upon the tabernacle, remaining thereon, the children of Israel abode in their tents, and journeyed not: but when it was taken up, they journeyed.', 'or whether it were two days or a month or a year that the cloud tarried upon the tabernacle remaining thereon the children of israel abode in their tents and journeyed not but when it was taken up they journeyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 9, 23, 'At the commandment of the LORD they rested in the tents, and at the commandment of the LORD they journeyed: they kept the charge of the LORD, at the commandment of the LORD by the hand of Moses.', 'at the commandment of the lord they rested in the tents and at the commandment of the lord they journeyed they kept the charge of the lord at the commandment of the lord by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 2, 'Make thee two trumpets of silver; of a whole piece shalt thou make them: that thou mayest use them for the calling of the assembly, and for the journeying of the camps.', 'make thee two trumpets of silver of a whole piece shalt thou make them that thou mayest use them for the calling of the assembly and for the journeying of the camps');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 3, 'And when they shall blow with them, all the assembly shall assemble themselves to thee at the door of the tabernacle of the congregation.', 'and when they shall blow with them all the assembly shall assemble themselves to thee at the door of the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 4, 'And if they blow {but} with one {trumpet}, then the princes, {which are} heads of the thousands of Israel, shall gather themselves unto thee.', 'and if they blow but with one trumpet then the princes which are heads of the thousands of israel shall gather themselves unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 5, 'When ye blow an alarm, then the camps that lie on the east parts shall go forward.', 'when ye blow an alarm then the camps that lie on the east parts shall go forward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 6, 'When ye blow an alarm the second time, then the camps that lie on the south side shall take their journey: they shall blow an alarm for their journeys.', 'when ye blow an alarm the second time then the camps that lie on the south side shall take their journey they shall blow an alarm for their journeys');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 7, 'But when the congregation is to be gathered together, ye shall blow, but ye shall not sound an alarm.', 'but when the congregation is to be gathered together ye shall blow but ye shall not sound an alarm');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 8, 'And the sons of Aaron, the priests, shall blow with the trumpets; and they shall be to you for an ordinance for ever throughout your generations.', 'and the sons of aaron the priests shall blow with the trumpets and they shall be to you for an ordinance for ever throughout your generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 9, 'And if ye go to war in your land against the enemy that oppresseth you, then ye shall blow an alarm with the trumpets; and ye shall be remembered before the LORD your God, and ye shall be saved from your enemies.', 'and if ye go to war in your land against the enemy that oppresseth you then ye shall blow an alarm with the trumpets and ye shall be remembered before the lord your god and ye shall be saved from your enemies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 10, 'Also in the day of your gladness, and in your solemn days, and in the beginnings of your months, ye shall blow with the trumpets over your burnt offerings, and over the sacrifices of your peace offerings; that they may be to you for a memorial before your God: I {am} the LORD your God.', 'also in the day of your gladness and in your solemn days and in the beginnings of your months ye shall blow with the trumpets over your burnt offerings and over the sacrifices of your peace offerings that they may be to you for a memorial before your god i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 11, 'And it came to pass on the twentieth {day} of the second month, in the second year, that the cloud was taken up from off the tabernacle of the testimony.', 'and it came to pass on the twentieth day of the second month in the second year that the cloud was taken up from off the tabernacle of the testimony');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 10, 12, 'And the children of Israel took their journeys out of the wilderness of Sinai; and the cloud rested in the wilderness of Paran.', 'and the children of israel took their journeys out of the wilderness of sinai and the cloud rested in the wilderness of paran');
