INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 10, 'Then Moses heard the people weep throughout their families, every man in the door of his tent: and the anger of the LORD was kindled greatly; Moses also was displeased.', 'then moses heard the people weep throughout their families every man in the door of his tent and the anger of the lord was kindled greatly moses also was displeased');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 11, 'And Moses said unto the LORD, Wherefore hast thou afflicted thy servant? and wherefore have I not found favour in thy sight, that thou layest the burden of all this people upon me?', 'and moses said unto the lord wherefore hast thou afflicted thy servant and wherefore have i not found favour in thy sight that thou layest the burden of all this people upon me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 12, 'Have I conceived all this people? have I begotten them, that thou shouldest say unto me, Carry them in thy bosom, as a nursing father beareth the sucking child, unto the land which thou swarest unto their fathers?', 'have i conceived all this people have i begotten them that thou shouldest say unto me carry them in thy bosom as a nursing father beareth the sucking child unto the land which thou swarest unto their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 13, 'Whence should I have flesh to give unto all this people? for they weep unto me, saying, Give us flesh, that we may eat.', 'whence should i have flesh to give unto all this people for they weep unto me saying give us flesh that we may eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 14, 'I am not able to bear all this people alone, because {it is} too heavy for me.', 'i am not able to bear all this people alone because it is too heavy for me');
