INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 16, 'And the LORD said unto Moses, Gather unto me seventy men of the elders of Israel, whom thou knowest to be the elders of the people, and officers over them; and bring them unto the tabernacle of the congregation, that they may stand there with thee.', 'and the lord said unto moses gather unto me seventy men of the elders of israel whom thou knowest to be the elders of the people and officers over them and bring them unto the tabernacle of the congregation that they may stand there with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 17, 'And I will come down and talk with thee there: and I will take of the spirit which {is} upon thee, and will put {it} upon them; and they shall bear the burden of the people with thee, that thou bear {it} not thyself alone.', 'and i will come down and talk with thee there and i will take of the spirit which is upon thee and will put it upon them and they shall bear the burden of the people with thee that thou bear it not thyself alone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 18, 'And say thou unto the people, Sanctify yourselves against to morrow, and ye shall eat flesh: for ye have wept in the ears of the LORD, saying, Who shall give us flesh to eat? for {it was} well with us in Egypt: therefore the LORD will give you flesh, and ye shall eat.', 'and say thou unto the people sanctify yourselves against to morrow and ye shall eat flesh for ye have wept in the ears of the lord saying who shall give us flesh to eat for it was well with us in egypt therefore the lord will give you flesh and ye shall eat');
