INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 22, 'Shall the flocks and the herds be slain for them, to suffice them? or shall all the fish of the sea be gathered together for them, to suffice them?', 'shall the flocks and the herds be slain for them to suffice them or shall all the fish of the sea be gathered together for them to suffice them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 23, 'And the LORD said unto Moses, Is the LORD''S hand waxed short? thou shalt see now whether my word shall come to pass unto thee or not.', 'and the lord said unto moses is the lord s hand waxed short thou shalt see now whether my word shall come to pass unto thee or not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 24, 'And Moses went out, and told the people the words of the LORD, and gathered the seventy men of the elders of the people, and set them round about the tabernacle.', 'and moses went out and told the people the words of the lord and gathered the seventy men of the elders of the people and set them round about the tabernacle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 25, 'And the LORD came down in a cloud, and spake unto him, and took of the spirit that {was} upon him, and gave {it} unto the seventy elders: and it came to pass, {that}, when the spirit rested upon them, they prophesied, and did not cease.', 'and the lord came down in a cloud and spake unto him and took of the spirit that was upon him and gave it unto the seventy elders and it came to pass that when the spirit rested upon them they prophesied and did not cease');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 26, 'But there remained two {of the} men in the camp, the name of the one {was} Eldad, and the name of the other Medad: and the spirit rested upon them; and they {were} of them that were written, but went not out unto the tabernacle: and they prophesied in the camp.', 'but there remained two of the men in the camp the name of the one was eldad and the name of the other medad and the spirit rested upon them and they were of them that were written but went not out unto the tabernacle and they prophesied in the camp');
