INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 28, 'And Joshua the son of Nun, the servant of Moses, {one} of his young men, answered and said, My lord Moses, forbid them.', 'and joshua the son of nun the servant of moses one of his young men answered and said my lord moses forbid them');
