INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 31, 'And there went forth a wind from the LORD, and brought quails from the sea, and let {them} fall by the camp, as it were a day''s journey on this side, and as it were a day''s journey on the other side, round about the camp, and as it were two cubits {high} upon the face of the earth. {as it were a day''s...: Heb. as it were the way of a day}', 'and there went forth a wind from the lord and brought quails from the sea and let them fall by the camp as it were a day s journey on this side and as it were a day s journey on the other side round about the camp and as it were two cubits high upon the face of the earth as it were a day s heb as it were the way of a day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 32, 'And the people stood up all that day, and all {that} night, and all the next day, and they gathered the quails: he that gathered least gathered ten homers: and they spread {them} all abroad for themselves round about the camp.', 'and the people stood up all that day and all that night and all the next day and they gathered the quails he that gathered least gathered ten homers and they spread them all abroad for themselves round about the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 11, 33, 'And while the flesh {was} yet between their teeth, ere it was chewed, the wrath of the LORD was kindled against the people, and the LORD smote the people with a very great plague.', 'and while the flesh was yet between their teeth ere it was chewed the wrath of the lord was kindled against the people and the lord smote the people with a very great plague');
