INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 17, 'And Moses sent them to spy out the land of Canaan, and said unto them, Get you up this {way} southward, and go up into the mountain:', 'and moses sent them to spy out the land of canaan and said unto them get you up this way southward and go up into the mountain');
