INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 20, 'And what the land {is}, whether it {be} fat or lean, whether there be wood therein, or not. And be ye of good courage, and bring of the fruit of the land. Now the time {was} the time of the firstripe grapes.', 'and what the land is whether it be fat or lean whether there be wood therein or not and be ye of good courage and bring of the fruit of the land now the time was the time of the firstripe grapes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 21, 'So they went up, and searched the land from the wilderness of Zin unto Rehob, as men come to Hamath.', 'so they went up and searched the land from the wilderness of zin unto rehob as men come to hamath');
