INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 23, 'And they came unto the brook of Eshcol, and cut down from thence a branch with one cluster of grapes, and they bare it between two upon a staff; and {they brought} of the pomegranates, and of the figs. {brook: or, valley}', 'and they came unto the brook of eshcol and cut down from thence a branch with one cluster of grapes and they bare it between two upon a staff and they brought of the pomegranates and of the figs brook or valley');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 24, 'The place was called the brook Eshcol, because of the cluster of grapes which the children of Israel cut down from thence. {brook: or, valley} {Eshcol: that is, A cluster of grapes}', 'the place was called the brook eshcol because of the cluster of grapes which the children of israel cut down from thence brook or valley eshcol that is a cluster of grapes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 25, 'And they returned from searching of the land after forty days.', 'and they returned from searching of the land after forty days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 26, 'And they went and came to Moses, and to Aaron, and to all the congregation of the children of Israel, unto the wilderness of Paran, to Kadesh; and brought back word unto them, and unto all the congregation, and shewed them the fruit of the land.', 'and they went and came to moses and to aaron and to all the congregation of the children of israel unto the wilderness of paran to kadesh and brought back word unto them and unto all the congregation and shewed them the fruit of the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 27, 'And they told him, and said, We came unto the land whither thou sentest us, and surely it floweth with milk and honey; and this {is} the fruit of it.', 'and they told him and said we came unto the land whither thou sentest us and surely it floweth with milk and honey and this is the fruit of it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 28, 'Nevertheless the people {be} strong that dwell in the land, and the cities {are} walled, {and} very great: and moreover we saw the children of Anak there.', 'nevertheless the people be strong that dwell in the land and the cities are walled and very great and moreover we saw the children of anak there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 29, 'The Amalekites dwell in the land of the south: and the Hittites, and the Jebusites, and the Amorites, dwell in the mountains: and the Canaanites dwell by the sea, and by the coast of Jordan.', 'the amalekites dwell in the land of the south and the hittites and the jebusites and the amorites dwell in the mountains and the canaanites dwell by the sea and by the coast of jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 13, 30, 'And Caleb stilled the people before Moses, and said, Let us go up at once, and possess it; for we are well able to overcome it.', 'and caleb stilled the people before moses and said let us go up at once and possess it for we are well able to overcome it');
