INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 4, 'And they said one to another, Let us make a captain, and let us return into Egypt.', 'and they said one to another let us make a captain and let us return into egypt');
