INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 8, 'If the LORD delight in us, then he will bring us into this land, and give it us; a land which floweth with milk and honey.', 'if the lord delight in us then he will bring us into this land and give it us a land which floweth with milk and honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 9, 'Only rebel not ye against the LORD, neither fear ye the people of the land; for they {are} bread for us: their defence is departed from them, and the LORD {is} with us: fear them not. {defence: Heb. shadow}', 'only rebel not ye against the lord neither fear ye the people of the land for they are bread for us their defence is departed from them and the lord is with us fear them not defence heb shadow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 10, 'But all the congregation bade stone them with stones. And the glory of the LORD appeared in the tabernacle of the congregation before all the children of Israel.', 'but all the congregation bade stone them with stones and the glory of the lord appeared in the tabernacle of the congregation before all the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 11, 'And the LORD said unto Moses, How long will this people provoke me? and how long will it be ere they believe me, for all the signs which I have shewed among them?', 'and the lord said unto moses how long will this people provoke me and how long will it be ere they believe me for all the signs which i have shewed among them');
