INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 13, 'And Moses said unto the LORD, Then the Egyptians shall hear {it}, (for thou broughtest up this people in thy might from among them;)', 'and moses said unto the lord then the egyptians shall hear it for thou broughtest up this people in thy might from among them');
