INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 16, 'Because the LORD was not able to bring this people into the land which he sware unto them, therefore he hath slain them in the wilderness.', 'because the lord was not able to bring this people into the land which he sware unto them therefore he hath slain them in the wilderness');
