INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 31, 'But your little ones, which ye said should be a prey, them will I bring in, and they shall know the land which ye have despised.', 'but your little ones which ye said should be a prey them will i bring in and they shall know the land which ye have despised');
