INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 14, 39, 'And Moses told these sayings unto all the children of Israel: and the people mourned greatly.', 'and moses told these sayings unto all the children of israel and the people mourned greatly');
