INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 3, 'And will make an offering by fire unto the LORD, a burnt offering, or a sacrifice in performing a vow, or in a freewill offering, or in your solemn feasts, to make a sweet savour unto the LORD, of the herd, or of the flock: {performing: Heb. separating}', 'and will make an offering by fire unto the lord a burnt offering or a sacrifice in performing a vow or in a freewill offering or in your solemn feasts to make a sweet savour unto the lord of the herd or of the flock performing heb separating');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 4, 'Then shall he that offereth his offering unto the LORD bring a meat offering of a tenth deal of flour mingled with the fourth {part} of an hin of oil.', 'then shall he that offereth his offering unto the lord bring a meat offering of a tenth deal of flour mingled with the fourth part of an hin of oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 5, 'And the fourth {part} of an hin of wine for a drink offering shalt thou prepare with the burnt offering or sacrifice, for one lamb.', 'and the fourth part of an hin of wine for a drink offering shalt thou prepare with the burnt offering or sacrifice for one lamb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 6, 'Or for a ram, thou shalt prepare {for} a meat offering two tenth deals of flour mingled with the third {part} of an hin of oil.', 'or for a ram thou shalt prepare for a meat offering two tenth deals of flour mingled with the third part of an hin of oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 7, 'And for a drink offering thou shalt offer the third {part} of an hin of wine, {for} a sweet savour unto the LORD.', 'and for a drink offering thou shalt offer the third part of an hin of wine for a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 8, 'And when thou preparest a bullock {for} a burnt offering, or {for} a sacrifice in performing a vow, or peace offerings unto the LORD:', 'and when thou preparest a bullock for a burnt offering or for a sacrifice in performing a vow or peace offerings unto the lord');
