INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 10, 'And thou shalt bring for a drink offering half an hin of wine, {for} an offering made by fire, of a sweet savour unto the LORD.', 'and thou shalt bring for a drink offering half an hin of wine for an offering made by fire of a sweet savour unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 11, 'Thus shall it be done for one bullock, or for one ram, or for a lamb, or a kid.', 'thus shall it be done for one bullock or for one ram or for a lamb or a kid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 12, 'According to the number that ye shall prepare, so shall ye do to every one according to their number.', 'according to the number that ye shall prepare so shall ye do to every one according to their number');
