INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 15, 'One ordinance {shall be both} for you of the congregation, and also for the stranger that sojourneth {with you}, an ordinance for ever in your generations: as ye {are}, so shall the stranger be before the LORD.', 'one ordinance shall be both for you of the congregation and also for the stranger that sojourneth with you an ordinance for ever in your generations as ye are so shall the stranger be before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 16, 'One law and one manner shall be for you, and for the stranger that sojourneth with you.', 'one law and one manner shall be for you and for the stranger that sojourneth with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 17, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 18, 'Speak unto the children of Israel, and say unto them, When ye come into the land whither I bring you,', 'speak unto the children of israel and say unto them when ye come into the land whither i bring you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 19, 'Then it shall be, that, when ye eat of the bread of the land, ye shall offer up an heave offering unto the LORD.', 'then it shall be that when ye eat of the bread of the land ye shall offer up an heave offering unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 20, 'Ye shall offer up a cake of the first of your dough {for} an heave offering: as {ye do} the heave offering of the threshingfloor, so shall ye heave it.', 'ye shall offer up a cake of the first of your dough for an heave offering as ye do the heave offering of the threshingfloor so shall ye heave it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 21, 'Of the first of your dough ye shall give unto the LORD an heave offering in your generations.', 'of the first of your dough ye shall give unto the lord an heave offering in your generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 15, 22, 'And if ye have erred, and not observed all these commandments, which the LORD hath spoken unto Moses,', 'and if ye have erred and not observed all these commandments which the lord hath spoken unto moses');
