INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 4, 'And when Moses heard {it}, he fell upon his face:', 'and when moses heard it he fell upon his face');
