INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 7, 'And put fire therein, and put incense in them before the LORD to morrow: and it shall be {that} the man whom the LORD doth choose, he {shall be} holy: {ye take} too much upon you, ye sons of Levi.', 'and put fire therein and put incense in them before the lord to morrow and it shall be that the man whom the lord doth choose he shall be holy ye take too much upon you ye sons of levi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 8, 'And Moses said unto Korah, Hear, I pray you, ye sons of Levi:', 'and moses said unto korah hear i pray you ye sons of levi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 9, '{Seemeth it but} a small thing unto you, that the God of Israel hath separated you from the congregation of Israel, to bring you near to himself to do the service of the tabernacle of the LORD, and to stand before the congregation to minister unto them?', 'seemeth it but a small thing unto you that the god of israel hath separated you from the congregation of israel to bring you near to himself to do the service of the tabernacle of the lord and to stand before the congregation to minister unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 10, 'And he hath brought thee near {to him}, and all thy brethren the sons of Levi with thee: and seek ye the priesthood also?', 'and he hath brought thee near to him and all thy brethren the sons of levi with thee and seek ye the priesthood also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 11, 'For which cause {both} thou and all thy company {are} gathered together against the LORD: and what {is} Aaron, that ye murmur against him?', 'for which cause both thou and all thy company are gathered together against the lord and what is aaron that ye murmur against him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 12, 'And Moses sent to call Dathan and Abiram, the sons of Eliab: which said, We will not come up:', 'and moses sent to call dathan and abiram the sons of eliab which said we will not come up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 13, '{Is it} a small thing that thou hast brought us up out of a land that floweth with milk and honey, to kill us in the wilderness, except thou make thyself altogether a prince over us?', 'is it a small thing that thou hast brought us up out of a land that floweth with milk and honey to kill us in the wilderness except thou make thyself altogether a prince over us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 14, 'Moreover thou hast not brought us into a land that floweth with milk and honey, or given us inheritance of fields and vineyards: wilt thou put out the eyes of these men? we will not come up. {put...: Heb. bore out}', 'moreover thou hast not brought us into a land that floweth with milk and honey or given us inheritance of fields and vineyards wilt thou put out the eyes of these men we will not come up put heb bore out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 15, 'And Moses was very wroth, and said unto the LORD, Respect not thou their offering: I have not taken one ass from them, neither have I hurt one of them.', 'and moses was very wroth and said unto the lord respect not thou their offering i have not taken one ass from them neither have i hurt one of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 16, 'And Moses said unto Korah, Be thou and all thy company before the LORD, thou, and they, and Aaron, to morrow:', 'and moses said unto korah be thou and all thy company before the lord thou and they and aaron to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 17, 'And take every man his censer, and put incense in them, and bring ye before the LORD every man his censer, two hundred and fifty censers; thou also, and Aaron, each {of you} his censer.', 'and take every man his censer and put incense in them and bring ye before the lord every man his censer two hundred and fifty censers thou also and aaron each of you his censer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 18, 'And they took every man his censer, and put fire in them, and laid incense thereon, and stood in the door of the tabernacle of the congregation with Moses and Aaron.', 'and they took every man his censer and put fire in them and laid incense thereon and stood in the door of the tabernacle of the congregation with moses and aaron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 19, 'And Korah gathered all the congregation against them unto the door of the tabernacle of the congregation: and the glory of the LORD appeared unto all the congregation.', 'and korah gathered all the congregation against them unto the door of the tabernacle of the congregation and the glory of the lord appeared unto all the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 20, 'And the LORD spake unto Moses and unto Aaron, saying,', 'and the lord spake unto moses and unto aaron saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 21, 'Separate yourselves from among this congregation, that I may consume them in a moment.', 'separate yourselves from among this congregation that i may consume them in a moment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 22, 'And they fell upon their faces, and said, O God, the God of the spirits of all flesh, shall one man sin, and wilt thou be wroth with all the congregation?', 'and they fell upon their faces and said o god the god of the spirits of all flesh shall one man sin and wilt thou be wroth with all the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 23, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 24, 'Speak unto the congregation, saying, Get you up from about the tabernacle of Korah, Dathan, and Abiram.', 'speak unto the congregation saying get you up from about the tabernacle of korah dathan and abiram');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 25, 'And Moses rose up and went unto Dathan and Abiram; and the elders of Israel followed him.', 'and moses rose up and went unto dathan and abiram and the elders of israel followed him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 26, 'And he spake unto the congregation, saying, Depart, I pray you, from the tents of these wicked men, and touch nothing of theirs, lest ye be consumed in all their sins.', 'and he spake unto the congregation saying depart i pray you from the tents of these wicked men and touch nothing of theirs lest ye be consumed in all their sins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 27, 'So they gat up from the tabernacle of Korah, Dathan, and Abiram, on every side: and Dathan and Abiram came out, and stood in the door of their tents, and their wives, and their sons, and their little children.', 'so they gat up from the tabernacle of korah dathan and abiram on every side and dathan and abiram came out and stood in the door of their tents and their wives and their sons and their little children');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 28, 'And Moses said, Hereby ye shall know that the LORD hath sent me to do all these works; for {I have} not {done them} of mine own mind.', 'and moses said hereby ye shall know that the lord hath sent me to do all these works for i have not done them of mine own mind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 29, 'If these men die the common death of all men, or if they be visited after the visitation of all men; {then} the LORD hath not sent me. {the common...: Heb. as every man dieth}', 'if these men die the common death of all men or if they be visited after the visitation of all men then the lord hath not sent me the common heb as every man dieth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 30, 'But if the LORD make a new thing, and the earth open her mouth, and swallow them up, with all that {appertain} unto them, and they go down quick into the pit; then ye shall understand that these men have provoked the LORD. {make...: Heb. create a creature}', 'but if the lord make a new thing and the earth open her mouth and swallow them up with all that appertain unto them and they go down quick into the pit then ye shall understand that these men have provoked the lord make heb create a creature');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 31, 'And it came to pass, as he had made an end of speaking all these words, that the ground clave asunder that {was} under them:', 'and it came to pass as he had made an end of speaking all these words that the ground clave asunder that was under them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 32, 'And the earth opened her mouth, and swallowed them up, and their houses, and all the men that {appertained} unto Korah, and all {their} goods.', 'and the earth opened her mouth and swallowed them up and their houses and all the men that appertained unto korah and all their goods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 33, 'They, and all that {appertained} to them, went down alive into the pit, and the earth closed upon them: and they perished from among the congregation.', 'they and all that appertained to them went down alive into the pit and the earth closed upon them and they perished from among the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 34, 'And all Israel that {were} round about them fled at the cry of them: for they said, Lest the earth swallow us up {also}.', 'and all israel that were round about them fled at the cry of them for they said lest the earth swallow us up also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 35, 'And there came out a fire from the LORD, and consumed the two hundred and fifty men that offered incense.', 'and there came out a fire from the lord and consumed the two hundred and fifty men that offered incense');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 36, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 37, 'Speak unto Eleazar the son of Aaron the priest, that he take up the censers out of the burning, and scatter thou the fire yonder; for they are hallowed.', 'speak unto eleazar the son of aaron the priest that he take up the censers out of the burning and scatter thou the fire yonder for they are hallowed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 38, 'The censers of these sinners against their own souls, let them make them broad plates {for} a covering of the altar: for they offered them before the LORD, therefore they are hallowed: and they shall be a sign unto the children of Israel.', 'the censers of these sinners against their own souls let them make them broad plates for a covering of the altar for they offered them before the lord therefore they are hallowed and they shall be a sign unto the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 39, 'And Eleazar the priest took the brasen censers, wherewith they that were burnt had offered; and they were made broad {plates for} a covering of the altar:', 'and eleazar the priest took the brasen censers wherewith they that were burnt had offered and they were made broad plates for a covering of the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 40, '{To be} a memorial unto the children of Israel, that no stranger, which {is} not of the seed of Aaron, come near to offer incense before the LORD; that he be not as Korah, and as his company: as the LORD said to him by the hand of Moses.', 'to be a memorial unto the children of israel that no stranger which is not of the seed of aaron come near to offer incense before the lord that he be not as korah and as his company as the lord said to him by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 41, 'But on the morrow all the congregation of the children of Israel murmured against Moses and against Aaron, saying, Ye have killed the people of the LORD.', 'but on the morrow all the congregation of the children of israel murmured against moses and against aaron saying ye have killed the people of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 42, 'And it came to pass, when the congregation was gathered against Moses and against Aaron, that they looked toward the tabernacle of the congregation: and, behold, the cloud covered it, and the glory of the LORD appeared.', 'and it came to pass when the congregation was gathered against moses and against aaron that they looked toward the tabernacle of the congregation and behold the cloud covered it and the glory of the lord appeared');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 43, 'And Moses and Aaron came before the tabernacle of the congregation.', 'and moses and aaron came before the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 44, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 45, 'Get you up from among this congregation, that I may consume them as in a moment. And they fell upon their faces.', 'get you up from among this congregation that i may consume them as in a moment and they fell upon their faces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 46, 'And Moses said unto Aaron, Take a censer, and put fire therein from off the altar, and put on incense, and go quickly unto the congregation, and make an atonement for them: for there is wrath gone out from the LORD; the plague is begun.', 'and moses said unto aaron take a censer and put fire therein from off the altar and put on incense and go quickly unto the congregation and make an atonement for them for there is wrath gone out from the lord the plague is begun');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 47, 'And Aaron took as Moses commanded, and ran into the midst of the congregation; and, behold, the plague was begun among the people: and he put on incense, and made an atonement for the people.', 'and aaron took as moses commanded and ran into the midst of the congregation and behold the plague was begun among the people and he put on incense and made an atonement for the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 16, 48, 'And he stood between the dead and the living; and the plague was stayed.', 'and he stood between the dead and the living and the plague was stayed');
