INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 17, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 17, 2, 'Speak unto the children of Israel, and take of every one of them a rod according to the house of {their} fathers, of all their princes according to the house of their fathers twelve rods: write thou every man''s name upon his rod.', 'speak unto the children of israel and take of every one of them a rod according to the house of their fathers of all their princes according to the house of their fathers twelve rods write thou every man s name upon his rod');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 17, 3, 'And thou shalt write Aaron''s name upon the rod of Levi: for one rod {shall be} for the head of the house of their fathers.', 'and thou shalt write aaron s name upon the rod of levi for one rod shall be for the head of the house of their fathers');
