INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 12, 'From thence they removed, and pitched in the valley of Zared.', 'from thence they removed and pitched in the valley of zared');
