INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 14, 'Wherefore it is said in the book of the wars of the LORD, What he did in the Red sea, and in the brooks of Arnon, {What...: or, Vaheb in Suphah}', 'wherefore it is said in the book of the wars of the lord what he did in the red sea and in the brooks of arnon what or vaheb in suphah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 15, 'And at the stream of the brooks that goeth down to the dwelling of Ar, and lieth upon the border of Moab. {lieth: Heb. leaneth}', 'and at the stream of the brooks that goeth down to the dwelling of ar and lieth upon the border of moab lieth heb leaneth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 16, 'And from thence {they went} to Beer: that {is} the well whereof the LORD spake unto Moses, Gather the people together, and I will give them water.', 'and from thence they went to beer that is the well whereof the lord spake unto moses gather the people together and i will give them water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 17, 'Then Israel sang this song, Spring up, O well; sing ye unto it: {Spring...: Heb. Ascend} {sing: or, answer}', 'then israel sang this song spring up o well sing ye unto it spring heb ascend sing or answer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 18, 'The princes digged the well, the nobles of the people digged it, by {the direction of} the lawgiver, with their staves. And from the wilderness {they went} to Mattanah:', 'the princes digged the well the nobles of the people digged it by the direction of the lawgiver with their staves and from the wilderness they went to mattanah');
