INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 20, 'And from Bamoth {in} the valley, that {is} in the country of Moab, to the top of Pisgah, which looketh toward Jeshimon. {country: Heb. field} {Pisgah: or, the hill} {Jeshimon: or, the wilderness}', 'and from bamoth in the valley that is in the country of moab to the top of pisgah which looketh toward jeshimon country heb field pisgah or the hill jeshimon or the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 21, 'And Israel sent messengers unto Sihon king of the Amorites, saying,', 'and israel sent messengers unto sihon king of the amorites saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 22, 'Let me pass through thy land: we will not turn into the fields, or into the vineyards; we will not drink {of} the waters of the well: {but} we will go along by the king''s {high} way, until we be past thy borders.', 'let me pass through thy land we will not turn into the fields or into the vineyards we will not drink of the waters of the well but we will go along by the king s high way until we be past thy borders');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 23, 'And Sihon would not suffer Israel to pass through his border: but Sihon gathered all his people together, and went out against Israel into the wilderness: and he came to Jahaz, and fought against Israel.', 'and sihon would not suffer israel to pass through his border but sihon gathered all his people together and went out against israel into the wilderness and he came to jahaz and fought against israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 24, 'And Israel smote him with the edge of the sword, and possessed his land from Arnon unto Jabbok, even unto the children of Ammon: for the border of the children of Ammon {was} strong.', 'and israel smote him with the edge of the sword and possessed his land from arnon unto jabbok even unto the children of ammon for the border of the children of ammon was strong');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 25, 'And Israel took all these cities: and Israel dwelt in all the cities of the Amorites, in Heshbon, and in all the villages thereof. {villages: Heb. daughters}', 'and israel took all these cities and israel dwelt in all the cities of the amorites in heshbon and in all the villages thereof villages heb daughters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 26, 'For Heshbon {was} the city of Sihon the king of the Amorites, who had fought against the former king of Moab, and taken all his land out of his hand, even unto Arnon.', 'for heshbon was the city of sihon the king of the amorites who had fought against the former king of moab and taken all his land out of his hand even unto arnon');
