INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 28, 'For there is a fire gone out of Heshbon, a flame from the city of Sihon: it hath consumed Ar of Moab, {and} the lords of the high places of Arnon.', 'for there is a fire gone out of heshbon a flame from the city of sihon it hath consumed ar of moab and the lords of the high places of arnon');
