INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 32, 'And Moses sent to spy out Jaazer, and they took the villages thereof, and drove out the Amorites that {were} there.', 'and moses sent to spy out jaazer and they took the villages thereof and drove out the amorites that were there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 33, 'And they turned and went up by the way of Bashan: and Og the king of Bashan went out against them, he, and all his people, to the battle at Edrei.', 'and they turned and went up by the way of bashan and og the king of bashan went out against them he and all his people to the battle at edrei');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 21, 34, 'And the LORD said unto Moses, Fear him not: for I have delivered him into thy hand, and all his people, and his land; and thou shalt do to him as thou didst unto Sihon king of the Amorites, which dwelt at Heshbon.', 'and the lord said unto moses fear him not for i have delivered him into thy hand and all his people and his land and thou shalt do to him as thou didst unto sihon king of the amorites which dwelt at heshbon');
