INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 1, 'And the children of Israel set forward, and pitched in the plains of Moab on this side Jordan {by} Jericho.', 'and the children of israel set forward and pitched in the plains of moab on this side jordan by jericho');
