INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 5, 'He sent messengers therefore unto Balaam the son of Beor to Pethor, which {is} by the river of the land of the children of his people, to call him, saying, Behold, there is a people come out from Egypt: behold, they cover the face of the earth, and they abide over against me: {face: Heb. eye}', 'he sent messengers therefore unto balaam the son of beor to pethor which is by the river of the land of the children of his people to call him saying behold there is a people come out from egypt behold they cover the face of the earth and they abide over against me face heb eye');
