INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 11, 'Behold, {there is} a people come out of Egypt, which covereth the face of the earth: come now, curse me them; peradventure I shall be able to overcome them, and drive them out. {I shall...: Heb. I shall prevail in fighting against him}', 'behold there is a people come out of egypt which covereth the face of the earth come now curse me them peradventure i shall be able to overcome them and drive them out i shall heb i shall prevail in fighting against him');
