INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 13, 'And Balaam rose up in the morning, and said unto the princes of Balak, Get you into your land: for the LORD refuseth to give me leave to go with you.', 'and balaam rose up in the morning and said unto the princes of balak get you into your land for the lord refuseth to give me leave to go with you');
