INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 16, 'And they came to Balaam, and said to him, Thus saith Balak the son of Zippor, Let nothing, I pray thee, hinder thee from coming unto me: {Let...: Heb. Be not thou hindered from, etc}', 'and they came to balaam and said to him thus saith balak the son of zippor let nothing i pray thee hinder thee from coming unto me let heb be not thou hindered from etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 17, 'For I will promote thee unto very great honour, and I will do whatsoever thou sayest unto me: come therefore, I pray thee, curse me this people.', 'for i will promote thee unto very great honour and i will do whatsoever thou sayest unto me come therefore i pray thee curse me this people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 18, 'And Balaam answered and said unto the servants of Balak, If Balak would give me his house full of silver and gold, I cannot go beyond the word of the LORD my God, to do less or more.', 'and balaam answered and said unto the servants of balak if balak would give me his house full of silver and gold i cannot go beyond the word of the lord my god to do less or more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 19, 'Now therefore, I pray you, tarry ye also here this night, that I may know what the LORD will say unto me more.', 'now therefore i pray you tarry ye also here this night that i may know what the lord will say unto me more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 20, 'And God came unto Balaam at night, and said unto him, If the men come to call thee, rise up, {and} go with them; but yet the word which I shall say unto thee, that shalt thou do.', 'and god came unto balaam at night and said unto him if the men come to call thee rise up and go with them but yet the word which i shall say unto thee that shalt thou do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 21, 'And Balaam rose up in the morning, and saddled his ass, and went with the princes of Moab.', 'and balaam rose up in the morning and saddled his ass and went with the princes of moab');
