INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 23, 'And the ass saw the angel of the LORD standing in the way, and his sword drawn in his hand: and the ass turned aside out of the way, and went into the field: and Balaam smote the ass, to turn her into the way.', 'and the ass saw the angel of the lord standing in the way and his sword drawn in his hand and the ass turned aside out of the way and went into the field and balaam smote the ass to turn her into the way');
