INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 25, 'And when the ass saw the angel of the LORD, she thrust herself unto the wall, and crushed Balaam''s foot against the wall: and he smote her again.', 'and when the ass saw the angel of the lord she thrust herself unto the wall and crushed balaam s foot against the wall and he smote her again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 26, 'And the angel of the LORD went further, and stood in a narrow place, where {was} no way to turn either to the right hand or to the left.', 'and the angel of the lord went further and stood in a narrow place where was no way to turn either to the right hand or to the left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 27, 'And when the ass saw the angel of the LORD, she fell down under Balaam: and Balaam''s anger was kindled, and he smote the ass with a staff.', 'and when the ass saw the angel of the lord she fell down under balaam and balaam s anger was kindled and he smote the ass with a staff');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 28, 'And the LORD opened the mouth of the ass, and she said unto Balaam, What have I done unto thee, that thou hast smitten me these three times?', 'and the lord opened the mouth of the ass and she said unto balaam what have i done unto thee that thou hast smitten me these three times');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 29, 'And Balaam said unto the ass, Because thou hast mocked me: I would there were a sword in mine hand, for now would I kill thee.', 'and balaam said unto the ass because thou hast mocked me i would there were a sword in mine hand for now would i kill thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 30, 'And the ass said unto Balaam, {Am} not I thine ass, upon which thou hast ridden ever since {I was} thine unto this day? was I ever wont to do so unto thee? And he said, Nay. {upon...: Heb. who hast ridden upon me} {ever since...: or, ever since thou wast, etc}', 'and the ass said unto balaam am not i thine ass upon which thou hast ridden ever since i was thine unto this day was i ever wont to do so unto thee and he said nay upon heb who hast ridden upon me ever since or ever since thou wast etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 31, 'Then the LORD opened the eyes of Balaam, and he saw the angel of the LORD standing in the way, and his sword drawn in his hand: and he bowed down his head, and fell flat on his face. {fell...: or, bowed himself}', 'then the lord opened the eyes of balaam and he saw the angel of the lord standing in the way and his sword drawn in his hand and he bowed down his head and fell flat on his face fell or bowed himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 32, 'And the angel of the LORD said unto him, Wherefore hast thou smitten thine ass these three times? behold, I went out to withstand thee, because {thy} way is perverse before me: {to...: Heb. to be an adversary unto thee}', 'and the angel of the lord said unto him wherefore hast thou smitten thine ass these three times behold i went out to withstand thee because thy way is perverse before me to heb to be an adversary unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 33, 'And the ass saw me, and turned from me these three times: unless she had turned from me, surely now also I had slain thee, and saved her alive.', 'and the ass saw me and turned from me these three times unless she had turned from me surely now also i had slain thee and saved her alive');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 34, 'And Balaam said unto the angel of the LORD, I have sinned; for I knew not that thou stoodest in the way against me: now therefore, if it displease thee, I will get me back again. {displease...: Heb. be evil in thine eyes}', 'and balaam said unto the angel of the lord i have sinned for i knew not that thou stoodest in the way against me now therefore if it displease thee i will get me back again displease heb be evil in thine eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 22, 35, 'And the angel of the LORD said unto Balaam, Go with the men: but only the word that I shall speak unto thee, that thou shalt speak. So Balaam went with the princes of Balak.', 'and the angel of the lord said unto balaam go with the men but only the word that i shall speak unto thee that thou shalt speak so balaam went with the princes of balak');
