INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 59, 'And the name of Amram''s wife {was} Jochebed, the daughter of Levi, whom {her mother} bare to Levi in Egypt: and she bare unto Amram Aaron and Moses, and Miriam their sister.', 'and the name of amram s wife was jochebed the daughter of levi whom her mother bare to levi in egypt and she bare unto amram aaron and moses and miriam their sister');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 60, 'And unto Aaron was born Nadab, and Abihu, Eleazar, and Ithamar.', 'and unto aaron was born nadab and abihu eleazar and ithamar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 61, 'And Nadab and Abihu died, when they offered strange fire before the LORD.', 'and nadab and abihu died when they offered strange fire before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 62, 'And those that were numbered of them were twenty and three thousand, all males from a month old and upward: for they were not numbered among the children of Israel, because there was no inheritance given them among the children of Israel.', 'and those that were numbered of them were twenty and three thousand all males from a month old and upward for they were not numbered among the children of israel because there was no inheritance given them among the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 63, 'These {are} they that were numbered by Moses and Eleazar the priest, who numbered the children of Israel in the plains of Moab by Jordan {near} Jericho.', 'these are they that were numbered by moses and eleazar the priest who numbered the children of israel in the plains of moab by jordan near jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 64, 'But among these there was not a man of them whom Moses and Aaron the priest numbered, when they numbered the children of Israel in the wilderness of Sinai.', 'but among these there was not a man of them whom moses and aaron the priest numbered when they numbered the children of israel in the wilderness of sinai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 26, 65, 'For the LORD had said of them, They shall surely die in the wilderness. And there was not left a man of them, save Caleb the son of Jephunneh, and Joshua the son of Nun.', 'for the lord had said of them they shall surely die in the wilderness and there was not left a man of them save caleb the son of jephunneh and joshua the son of nun');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 1, 'Then came the daughters of Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, of the families of Manasseh the son of Joseph: and these {are} the names of his daughters; Mahlah, Noah, and Hoglah, and Milcah, and Tirzah.', 'then came the daughters of zelophehad the son of hepher the son of gilead the son of machir the son of manasseh of the families of manasseh the son of joseph and these are the names of his daughters mahlah noah and hoglah and milcah and tirzah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 2, 'And they stood before Moses, and before Eleazar the priest, and before the princes and all the congregation, {by} the door of the tabernacle of the congregation, saying,', 'and they stood before moses and before eleazar the priest and before the princes and all the congregation by the door of the tabernacle of the congregation saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 3, 'Our father died in the wilderness, and he was not in the company of them that gathered themselves together against the LORD in the company of Korah; but died in his own sin, and had no sons.', 'our father died in the wilderness and he was not in the company of them that gathered themselves together against the lord in the company of korah but died in his own sin and had no sons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 4, 'Why should the name of our father be done away from among his family, because he hath no son? Give unto us {therefore} a possession among the brethren of our father. {done...: Heb. diminished}', 'why should the name of our father be done away from among his family because he hath no son give unto us therefore a possession among the brethren of our father done heb diminished');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 5, 'And Moses brought their cause before the LORD.', 'and moses brought their cause before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 6, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 7, 'The daughters of Zelophehad speak right: thou shalt surely give them a possession of an inheritance among their father''s brethren; and thou shalt cause the inheritance of their father to pass unto them.', 'the daughters of zelophehad speak right thou shalt surely give them a possession of an inheritance among their father s brethren and thou shalt cause the inheritance of their father to pass unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 8, 'And thou shalt speak unto the children of Israel, saying, If a man die, and have no son, then ye shall cause his inheritance to pass unto his daughter.', 'and thou shalt speak unto the children of israel saying if a man die and have no son then ye shall cause his inheritance to pass unto his daughter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 9, 'And if he have no daughter, then ye shall give his inheritance unto his brethren.', 'and if he have no daughter then ye shall give his inheritance unto his brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 10, 'And if he have no brethren, then ye shall give his inheritance unto his father''s brethren.', 'and if he have no brethren then ye shall give his inheritance unto his father s brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 11, 'And if his father have no brethren, then ye shall give his inheritance unto his kinsman that is next to him of his family, and he shall possess it: and it shall be unto the children of Israel a statute of judgment, as the LORD commanded Moses.', 'and if his father have no brethren then ye shall give his inheritance unto his kinsman that is next to him of his family and he shall possess it and it shall be unto the children of israel a statute of judgment as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 12, 'And the LORD said unto Moses, Get thee up into this mount Abarim, and see the land which I have given unto the children of Israel.', 'and the lord said unto moses get thee up into this mount abarim and see the land which i have given unto the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 13, 'And when thou hast seen it, thou also shalt be gathered unto thy people, as Aaron thy brother was gathered.', 'and when thou hast seen it thou also shalt be gathered unto thy people as aaron thy brother was gathered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 14, 'For ye rebelled against my commandment in the desert of Zin, in the strife of the congregation, to sanctify me at the water before their eyes: that {is} the water of Meribah in Kadesh in the wilderness of Zin.', 'for ye rebelled against my commandment in the desert of zin in the strife of the congregation to sanctify me at the water before their eyes that is the water of meribah in kadesh in the wilderness of zin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 15, 'And Moses spake unto the LORD, saying,', 'and moses spake unto the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 16, 'Let the LORD, the God of the spirits of all flesh, set a man over the congregation,', 'let the lord the god of the spirits of all flesh set a man over the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 17, 'Which may go out before them, and which may go in before them, and which may lead them out, and which may bring them in; that the congregation of the LORD be not as sheep which have no shepherd.', 'which may go out before them and which may go in before them and which may lead them out and which may bring them in that the congregation of the lord be not as sheep which have no shepherd');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 18, 'And the LORD said unto Moses, Take thee Joshua the son of Nun, a man in whom {is} the spirit, and lay thine hand upon him;', 'and the lord said unto moses take thee joshua the son of nun a man in whom is the spirit and lay thine hand upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 19, 'And set him before Eleazar the priest, and before all the congregation; and give him a charge in their sight.', 'and set him before eleazar the priest and before all the congregation and give him a charge in their sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 20, 'And thou shalt put {some} of thine honour upon him, that all the congregation of the children of Israel may be obedient.', 'and thou shalt put some of thine honour upon him that all the congregation of the children of israel may be obedient');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 21, 'And he shall stand before Eleazar the priest, who shall ask {counsel} for him after the judgment of Urim before the LORD: at his word shall they go out, and at his word they shall come in, {both} he, and all the children of Israel with him, even all the congregation.', 'and he shall stand before eleazar the priest who shall ask counsel for him after the judgment of urim before the lord at his word shall they go out and at his word they shall come in both he and all the children of israel with him even all the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 22, 'And Moses did as the LORD commanded him: and he took Joshua, and set him before Eleazar the priest, and before all the congregation:', 'and moses did as the lord commanded him and he took joshua and set him before eleazar the priest and before all the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 27, 23, 'And he laid his hands upon him, and gave him a charge, as the LORD commanded by the hand of Moses.', 'and he laid his hands upon him and gave him a charge as the lord commanded by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 2, 'Command the children of Israel, and say unto them, My offering, {and} my bread for my sacrifices made by fire, {for} a sweet savour unto me, shall ye observe to offer unto me in their due season. {a sweet...: Heb. a savour of my rest}', 'command the children of israel and say unto them my offering and my bread for my sacrifices made by fire for a sweet savour unto me shall ye observe to offer unto me in their due season a sweet heb a savour of my rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 3, 'And thou shalt say unto them, This {is} the offering made by fire which ye shall offer unto the LORD; two lambs of the first year without spot day by day, {for} a continual burnt offering. {day by day: Heb. in a day}', 'and thou shalt say unto them this is the offering made by fire which ye shall offer unto the lord two lambs of the first year without spot day by day for a continual burnt offering day by day heb in a day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 4, 'The one lamb shalt thou offer in the morning, and the other lamb shalt thou offer at even; {at even: Heb. between the two evenings}', 'the one lamb shalt thou offer in the morning and the other lamb shalt thou offer at even at even heb between the two evenings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 5, 'And a tenth {part} of an ephah of flour for a meat offering, mingled with the fourth {part} of an hin of beaten oil.', 'and a tenth part of an ephah of flour for a meat offering mingled with the fourth part of an hin of beaten oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 6, '{It is} a continual burnt offering, which was ordained in mount Sinai for a sweet savour, a sacrifice made by fire unto the LORD.', 'it is a continual burnt offering which was ordained in mount sinai for a sweet savour a sacrifice made by fire unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 7, 'And the drink offering thereof {shall be} the fourth {part} of an hin for the one lamb: in the holy {place} shalt thou cause the strong wine to be poured unto the LORD {for} a drink offering.', 'and the drink offering thereof shall be the fourth part of an hin for the one lamb in the holy place shalt thou cause the strong wine to be poured unto the lord for a drink offering');
