INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 15, 'And one kid of the goats for a sin offering unto the LORD shall be offered, beside the continual burnt offering, and his drink offering.', 'and one kid of the goats for a sin offering unto the lord shall be offered beside the continual burnt offering and his drink offering');
