INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 17, 'And in the fifteenth day of this month {is} the feast: seven days shall unleavened bread be eaten.', 'and in the fifteenth day of this month is the feast seven days shall unleavened bread be eaten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 18, 'In the first day {shall be} an holy convocation; ye shall do no manner of servile work {therein}:', 'in the first day shall be an holy convocation ye shall do no manner of servile work therein');
