INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 23, 'Ye shall offer these beside the burnt offering in the morning, which {is} for a continual burnt offering.', 'ye shall offer these beside the burnt offering in the morning which is for a continual burnt offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 28, 24, 'After this manner ye shall offer daily, throughout the seven days, the meat of the sacrifice made by fire, of a sweet savour unto the LORD: it shall be offered beside the continual burnt offering, and his drink offering.', 'after this manner ye shall offer daily throughout the seven days the meat of the sacrifice made by fire of a sweet savour unto the lord it shall be offered beside the continual burnt offering and his drink offering');
