INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 2, 'If a man vow a vow unto the LORD, or swear an oath to bind his soul with a bond; he shall not break his word, he shall do according to all that proceedeth out of his mouth. {break: Heb. profane}', 'if a man vow a vow unto the lord or swear an oath to bind his soul with a bond he shall not break his word he shall do according to all that proceedeth out of his mouth break heb profane');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 3, 'If a woman also vow a vow unto the LORD, and bind herself by a bond, {being} in her father''s house in her youth;', 'if a woman also vow a vow unto the lord and bind herself by a bond being in her father s house in her youth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 4, 'And her father hear her vow, and her bond wherewith she hath bound her soul, and her father shall hold his peace at her: then all her vows shall stand, and every bond wherewith she hath bound her soul shall stand.', 'and her father hear her vow and her bond wherewith she hath bound her soul and her father shall hold his peace at her then all her vows shall stand and every bond wherewith she hath bound her soul shall stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 5, 'But if her father disallow her in the day that he heareth; not any of her vows, or of her bonds wherewith she hath bound her soul, shall stand: and the LORD shall forgive her, because her father disallowed her.', 'but if her father disallow her in the day that he heareth not any of her vows or of her bonds wherewith she hath bound her soul shall stand and the lord shall forgive her because her father disallowed her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 6, 'And if she had at all an husband, when she vowed, or uttered ought out of her lips, wherewith she bound her soul; {she vowed: Heb. her vows were upon her}', 'and if she had at all an husband when she vowed or uttered ought out of her lips wherewith she bound her soul she vowed heb her vows were upon her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 7, 'And her husband heard {it,} and held his peace at her in the day that he heard {it}: then her vows shall stand, and her bonds wherewith she bound her soul shall stand.', 'and her husband heard it and held his peace at her in the day that he heard it then her vows shall stand and her bonds wherewith she bound her soul shall stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 8, 'But if her husband disallowed her on the day that he heard {it}; then he shall make her vow which she vowed, and that which she uttered with her lips, wherewith she bound her soul, of none effect: and the LORD shall forgive her.', 'but if her husband disallowed her on the day that he heard it then he shall make her vow which she vowed and that which she uttered with her lips wherewith she bound her soul of none effect and the lord shall forgive her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 9, 'But every vow of a widow, and of her that is divorced, wherewith they have bound their souls, shall stand against her.', 'but every vow of a widow and of her that is divorced wherewith they have bound their souls shall stand against her');
