INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 12, 'But if her husband hath utterly made them void on the day he heard {them; then} whatsoever proceeded out of her lips concerning her vows, or concerning the bond of her soul, shall not stand: her husband hath made them void; and the LORD shall forgive her.', 'but if her husband hath utterly made them void on the day he heard them then whatsoever proceeded out of her lips concerning her vows or concerning the bond of her soul shall not stand her husband hath made them void and the lord shall forgive her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 13, 'Every vow, and every binding oath to afflict the soul, her husband may establish it, or her husband may make it void.', 'every vow and every binding oath to afflict the soul her husband may establish it or her husband may make it void');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 30, 14, 'But if her husband altogether hold his peace at her from day to day; then he establisheth all her vows, or all her bonds, which {are} upon her: he confirmeth them, because he held his peace at her in the day that he heard {them}.', 'but if her husband altogether hold his peace at her from day to day then he establisheth all her vows or all her bonds which are upon her he confirmeth them because he held his peace at her in the day that he heard them');
