INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 31, 7, 'And they warred against the Midianites, as the LORD commanded Moses; and they slew all the males.', 'and they warred against the midianites as the lord commanded moses and they slew all the males');
