INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 13, 'And the LORD''S anger was kindled against Israel, and he made them wander in the wilderness forty years, until all the generation, that had done evil in the sight of the LORD, was consumed.', 'and the lord s anger was kindled against israel and he made them wander in the wilderness forty years until all the generation that had done evil in the sight of the lord was consumed');
