INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 15, 'For if ye turn away from after him, he will yet again leave them in the wilderness; and ye shall destroy all this people.', 'for if ye turn away from after him he will yet again leave them in the wilderness and ye shall destroy all this people');
