INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 17, 'But we ourselves will go ready armed before the children of Israel, until we have brought them unto their place: and our little ones shall dwell in the fenced cities because of the inhabitants of the land.', 'but we ourselves will go ready armed before the children of israel until we have brought them unto their place and our little ones shall dwell in the fenced cities because of the inhabitants of the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 18, 'We will not return unto our houses, until the children of Israel have inherited every man his inheritance.', 'we will not return unto our houses until the children of israel have inherited every man his inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 19, 'For we will not inherit with them on yonder side Jordan, or forward; because our inheritance is fallen to us on this side Jordan eastward.', 'for we will not inherit with them on yonder side jordan or forward because our inheritance is fallen to us on this side jordan eastward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 20, 'And Moses said unto them, If ye will do this thing, if ye will go armed before the LORD to war,', 'and moses said unto them if ye will do this thing if ye will go armed before the lord to war');
