INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 22, 'And the land be subdued before the LORD: then afterward ye shall return, and be guiltless before the LORD, and before Israel; and this land shall be your possession before the LORD.', 'and the land be subdued before the lord then afterward ye shall return and be guiltless before the lord and before israel and this land shall be your possession before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 23, 'But if ye will not do so, behold, ye have sinned against the LORD: and be sure your sin will find you out.', 'but if ye will not do so behold ye have sinned against the lord and be sure your sin will find you out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 24, 'Build you cities for your little ones, and folds for your sheep; and do that which hath proceeded out of your mouth.', 'build you cities for your little ones and folds for your sheep and do that which hath proceeded out of your mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 25, 'And the children of Gad and the children of Reuben spake unto Moses, saying, Thy servants will do as my lord commandeth.', 'and the children of gad and the children of reuben spake unto moses saying thy servants will do as my lord commandeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 26, 'Our little ones, our wives, our flocks, and all our cattle, shall be there in the cities of Gilead:', 'our little ones our wives our flocks and all our cattle shall be there in the cities of gilead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 27, 'But thy servants will pass over, every man armed for war, before the LORD to battle, as my lord saith.', 'but thy servants will pass over every man armed for war before the lord to battle as my lord saith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 28, 'So concerning them Moses commanded Eleazar the priest, and Joshua the son of Nun, and the chief fathers of the tribes of the children of Israel:', 'so concerning them moses commanded eleazar the priest and joshua the son of nun and the chief fathers of the tribes of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 29, 'And Moses said unto them, If the children of Gad and the children of Reuben will pass with you over Jordan, every man armed to battle, before the LORD, and the land shall be subdued before you; then ye shall give them the land of Gilead for a possession:', 'and moses said unto them if the children of gad and the children of reuben will pass with you over jordan every man armed to battle before the lord and the land shall be subdued before you then ye shall give them the land of gilead for a possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 30, 'But if they will not pass over with you armed, they shall have possessions among you in the land of Canaan.', 'but if they will not pass over with you armed they shall have possessions among you in the land of canaan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 31, 'And the children of Gad and the children of Reuben answered, saying, As the LORD hath said unto thy servants, so will we do.', 'and the children of gad and the children of reuben answered saying as the lord hath said unto thy servants so will we do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 32, 'We will pass over armed before the LORD into the land of Canaan, that the possession of our inheritance on this side Jordan {may be} ours.', 'we will pass over armed before the lord into the land of canaan that the possession of our inheritance on this side jordan may be ours');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 33, 'And Moses gave unto them, {even} to the children of Gad, and to the children of Reuben, and unto half the tribe of Manasseh the son of Joseph, the kingdom of Sihon king of the Amorites, and the kingdom of Og king of Bashan, the land, with the cities thereof in the coasts, {even} the cities of the country round about.', 'and moses gave unto them even to the children of gad and to the children of reuben and unto half the tribe of manasseh the son of joseph the kingdom of sihon king of the amorites and the kingdom of og king of bashan the land with the cities thereof in the coasts even the cities of the country round about');
