INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 32, 39, 'And the children of Machir the son of Manasseh went to Gilead, and took it, and dispossessed the Amorite which {was} in it.', 'and the children of machir the son of manasseh went to gilead and took it and dispossessed the amorite which was in it');
