INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 4, 'For the Egyptians buried all {their} firstborn, which the LORD had smitten among them: upon their gods also the LORD executed judgments.', 'for the egyptians buried all their firstborn which the lord had smitten among them upon their gods also the lord executed judgments');
