INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 50, 'And the LORD spake unto Moses in the plains of Moab by Jordan {near} Jericho, saying,', 'and the lord spake unto moses in the plains of moab by jordan near jericho saying');
