INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 52, 'Then ye shall drive out all the inhabitants of the land from before you, and destroy all their pictures, and destroy all their molten images, and quite pluck down all their high places:', 'then ye shall drive out all the inhabitants of the land from before you and destroy all their pictures and destroy all their molten images and quite pluck down all their high places');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 53, 'And ye shall dispossess {the inhabitants} of the land, and dwell therein: for I have given you the land to possess it.', 'and ye shall dispossess the inhabitants of the land and dwell therein for i have given you the land to possess it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 54, 'And ye shall divide the land by lot for an inheritance among your families: {and} to the more ye shall give the more inheritance, and to the fewer ye shall give the less inheritance: every man''s {inheritance} shall be in the place where his lot falleth; according to the tribes of your fathers ye shall inherit. {give the more...: Heb. multiply his inheritance} {give the less...: Heb. diminish his inheritance}', 'and ye shall divide the land by lot for an inheritance among your families and to the more ye shall give the more inheritance and to the fewer ye shall give the less inheritance every man s inheritance shall be in the place where his lot falleth according to the tribes of your fathers ye shall inherit give the more heb multiply his inheritance give the less heb diminish his inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 55, 'But if ye will not drive out the inhabitants of the land from before you; then it shall come to pass, that those which ye let remain of them {shall be} pricks in your eyes, and thorns in your sides, and shall vex you in the land wherein ye dwell.', 'but if ye will not drive out the inhabitants of the land from before you then it shall come to pass that those which ye let remain of them shall be pricks in your eyes and thorns in your sides and shall vex you in the land wherein ye dwell');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 33, 56, 'Moreover it shall come to pass, {that} I shall do unto you, as I thought to do unto them.', 'moreover it shall come to pass that i shall do unto you as i thought to do unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 1, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
