INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 3, 'Then your south quarter shall be from the wilderness of Zin along by the coast of Edom, and your south border shall be the outmost coast of the salt sea eastward:', 'then your south quarter shall be from the wilderness of zin along by the coast of edom and your south border shall be the outmost coast of the salt sea eastward');
