INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 5, 'And the border shall fetch a compass from Azmon unto the river of Egypt, and the goings out of it shall be at the sea.', 'and the border shall fetch a compass from azmon unto the river of egypt and the goings out of it shall be at the sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 6, 'And {as for} the western border, ye shall even have the great sea for a border: this shall be your west border.', 'and as for the western border ye shall even have the great sea for a border this shall be your west border');
