INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 9, 'And the border shall go on to Ziphron, and the goings out of it shall be at Hazarenan: this shall be your north border.', 'and the border shall go on to ziphron and the goings out of it shall be at hazarenan this shall be your north border');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 10, 'And ye shall point out your east border from Hazarenan to Shepham:', 'and ye shall point out your east border from hazarenan to shepham');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 11, 'And the coast shall go down from Shepham to Riblah, on the east side of Ain; and the border shall descend, and shall reach unto the side of the sea of Chinnereth eastward: {side of the sea: Heb. shoulder of the sea}', 'and the coast shall go down from shepham to riblah on the east side of ain and the border shall descend and shall reach unto the side of the sea of chinnereth eastward side of the sea heb shoulder of the sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 12, 'And the border shall go down to Jordan, and the goings out of it shall be at the salt sea: this shall be your land with the coasts thereof round about.', 'and the border shall go down to jordan and the goings out of it shall be at the salt sea this shall be your land with the coasts thereof round about');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 13, 'And Moses commanded the children of Israel, saying, This {is} the land which ye shall inherit by lot, which the LORD commanded to give unto the nine tribes, and to the half tribe:', 'and moses commanded the children of israel saying this is the land which ye shall inherit by lot which the lord commanded to give unto the nine tribes and to the half tribe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 14, 'For the tribe of the children of Reuben according to the house of their fathers, and the tribe of the children of Gad according to the house of their fathers, have received {their inheritance}; and half the tribe of Manasseh have received their inheritance:', 'for the tribe of the children of reuben according to the house of their fathers and the tribe of the children of gad according to the house of their fathers have received their inheritance and half the tribe of manasseh have received their inheritance');
