INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 4, 'Unknown', 34, 16, 'And the LORD spake unto Moses, saying,', 'and the lord spake unto moses saying');
