INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 22, 'And ye came near unto me every one of you, and said, We will send men before us, and they shall search us out the land, and bring us word again by what way we must go up, and into what cities we shall come.', 'and ye came near unto me every one of you and said we will send men before us and they shall search us out the land and bring us word again by what way we must go up and into what cities we shall come');
