INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 41, 'Then ye answered and said unto me, We have sinned against the LORD, we will go up and fight, according to all that the LORD our God commanded us. And when ye had girded on every man his weapons of war, ye were ready to go up into the hill.', 'then ye answered and said unto me we have sinned against the lord we will go up and fight according to all that the lord our god commanded us and when ye had girded on every man his weapons of war ye were ready to go up into the hill');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 42, 'And the LORD said unto me, Say unto them, Go not up, neither fight; for I {am} not among you; lest ye be smitten before your enemies.', 'and the lord said unto me say unto them go not up neither fight for i am not among you lest ye be smitten before your enemies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 43, 'So I spake unto you; and ye would not hear, but rebelled against the commandment of the LORD, and went presumptuously up into the hill. {went...: Heb. ye were presumptuous, and went up}', 'so i spake unto you and ye would not hear but rebelled against the commandment of the lord and went presumptuously up into the hill went heb ye were presumptuous and went up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 44, 'And the Amorites, which dwelt in that mountain, came out against you, and chased you, as bees do, and destroyed you in Seir, {even} unto Hormah.', 'and the amorites which dwelt in that mountain came out against you and chased you as bees do and destroyed you in seir even unto hormah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 45, 'And ye returned and wept before the LORD; but the LORD would not hearken to your voice, nor give ear unto you.', 'and ye returned and wept before the lord but the lord would not hearken to your voice nor give ear unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 1, 46, 'So ye abode in Kadesh many days, according unto the days that ye abode {there}.', 'so ye abode in kadesh many days according unto the days that ye abode there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 1, 'Then we turned, and took our journey into the wilderness by the way of the Red sea, as the LORD spake unto me: and we compassed mount Seir many days.', 'then we turned and took our journey into the wilderness by the way of the red sea as the lord spake unto me and we compassed mount seir many days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 2, 'And the LORD spake unto me, saying,', 'and the lord spake unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 3, 'Ye have compassed this mountain long enough: turn you northward.', 'ye have compassed this mountain long enough turn you northward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 4, 'And command thou the people, saying, Ye {are} to pass through the coast of your brethren the children of Esau, which dwell in Seir; and they shall be afraid of you: take ye good heed unto yourselves therefore:', 'and command thou the people saying ye are to pass through the coast of your brethren the children of esau which dwell in seir and they shall be afraid of you take ye good heed unto yourselves therefore');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 5, 'Meddle not with them; for I will not give you of their land, no, not so much as a foot breadth; because I have given mount Seir unto Esau {for} a possession. {no...: Heb. even to the treading of the sole of the foot}', 'meddle not with them for i will not give you of their land no not so much as a foot breadth because i have given mount seir unto esau for a possession no heb even to the treading of the sole of the foot');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 6, 'Ye shall buy meat of them for money, that ye may eat; and ye shall also buy water of them for money, that ye may drink.', 'ye shall buy meat of them for money that ye may eat and ye shall also buy water of them for money that ye may drink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 7, 'For the LORD thy God hath blessed thee in all the works of thy hand: he knoweth thy walking through this great wilderness: these forty years the LORD thy God {hath been} with thee; thou hast lacked nothing.', 'for the lord thy god hath blessed thee in all the works of thy hand he knoweth thy walking through this great wilderness these forty years the lord thy god hath been with thee thou hast lacked nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 8, 'And when we passed by from our brethren the children of Esau, which dwelt in Seir, through the way of the plain from Elath, and from Eziongaber, we turned and passed by the way of the wilderness of Moab.', 'and when we passed by from our brethren the children of esau which dwelt in seir through the way of the plain from elath and from eziongaber we turned and passed by the way of the wilderness of moab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 9, 'And the LORD said unto me, Distress not the Moabites, neither contend with them in battle: for I will not give thee of their land {for} a possession; because I have given Ar unto the children of Lot {for} a possession. {Distress...: or, Use no hostility against Moab}', 'and the lord said unto me distress not the moabites neither contend with them in battle for i will not give thee of their land for a possession because i have given ar unto the children of lot for a possession distress or use no hostility against moab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 10, 'The Emims dwelt therein in times past, a people great, and many, and tall, as the Anakims;', 'the emims dwelt therein in times past a people great and many and tall as the anakims');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 11, 'Which also were accounted giants, as the Anakims; but the Moabites call them Emims.', 'which also were accounted giants as the anakims but the moabites call them emims');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 12, 'The Horims also dwelt in Seir beforetime; but the children of Esau succeeded them, when they had destroyed them from before them, and dwelt in their stead; as Israel did unto the land of his possession, which the LORD gave unto them. {succeeded: Heb. inherited} {stead: or, room}', 'the horims also dwelt in seir beforetime but the children of esau succeeded them when they had destroyed them from before them and dwelt in their stead as israel did unto the land of his possession which the lord gave unto them succeeded heb inherited stead or room');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 13, 'Now rise up, {said I}, and get you over the brook Zered. And we went over the brook Zered. {brook: or, valley}', 'now rise up said i and get you over the brook zered and we went over the brook zered brook or valley');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 14, 'And the space in which we came from Kadeshbarnea, until we were come over the brook Zered, {was} thirty and eight years; until all the generation of the men of war were wasted out from among the host, as the LORD sware unto them. {brook: or, valley}', 'and the space in which we came from kadeshbarnea until we were come over the brook zered was thirty and eight years until all the generation of the men of war were wasted out from among the host as the lord sware unto them brook or valley');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 15, 'For indeed the hand of the LORD was against them, to destroy them from among the host, until they were consumed.', 'for indeed the hand of the lord was against them to destroy them from among the host until they were consumed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 16, 'So it came to pass, when all the men of war were consumed and dead from among the people,', 'so it came to pass when all the men of war were consumed and dead from among the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 17, 'That the LORD spake unto me, saying,', 'that the lord spake unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 18, 'Thou art to pass over through Ar, the coast of Moab, this day:', 'thou art to pass over through ar the coast of moab this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 19, 'And {when} thou comest nigh over against the children of Ammon, distress them not, nor meddle with them: for I will not give thee of the land of the children of Ammon {any} possession; because I have given it unto the children of Lot {for} a possession.', 'and when thou comest nigh over against the children of ammon distress them not nor meddle with them for i will not give thee of the land of the children of ammon any possession because i have given it unto the children of lot for a possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 20, '(That also was accounted a land of giants: giants dwelt therein in old time; and the Ammonites call them Zamzummims; {Zamzummims: also called, Zuzims}', 'that also was accounted a land of giants giants dwelt therein in old time and the ammonites call them zamzummims zamzummims also called zuzims');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 21, 'A people great, and many, and tall, as the Anakims; but the LORD destroyed them before them; and they succeeded them, and dwelt in their stead:', 'a people great and many and tall as the anakims but the lord destroyed them before them and they succeeded them and dwelt in their stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 22, 'As he did to the children of Esau, which dwelt in Seir, when he destroyed the Horims from before them; and they succeeded them, and dwelt in their stead even unto this day:', 'as he did to the children of esau which dwelt in seir when he destroyed the horims from before them and they succeeded them and dwelt in their stead even unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 23, 'And the Avims which dwelt in Hazerim, {even} unto Azzah, the Caphtorims, which came forth out of Caphtor, destroyed them, and dwelt in their stead.)', 'and the avims which dwelt in hazerim even unto azzah the caphtorims which came forth out of caphtor destroyed them and dwelt in their stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 24, 'Rise ye up, take your journey, and pass over the river Arnon: behold, I have given into thine hand Sihon the Amorite, king of Heshbon, and his land: begin to possess {it}, and contend with him in battle. {begin...: Heb. begin, possess}', 'rise ye up take your journey and pass over the river arnon behold i have given into thine hand sihon the amorite king of heshbon and his land begin to possess it and contend with him in battle begin heb begin possess');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 25, 'This day will I begin to put the dread of thee and the fear of thee upon the nations {that are} under the whole heaven, who shall hear report of thee, and shall tremble, and be in anguish because of thee.', 'this day will i begin to put the dread of thee and the fear of thee upon the nations that are under the whole heaven who shall hear report of thee and shall tremble and be in anguish because of thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 26, 'And I sent messengers out of the wilderness of Kedemoth unto Sihon king of Heshbon with words of peace, saying,', 'and i sent messengers out of the wilderness of kedemoth unto sihon king of heshbon with words of peace saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 27, 'Let me pass through thy land: I will go along by the high way, I will neither turn unto the right hand nor to the left.', 'let me pass through thy land i will go along by the high way i will neither turn unto the right hand nor to the left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 28, 'Thou shalt sell me meat for money, that I may eat; and give me water for money, that I may drink: only I will pass through on my feet;', 'thou shalt sell me meat for money that i may eat and give me water for money that i may drink only i will pass through on my feet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 29, '(As the children of Esau which dwell in Seir, and the Moabites which dwell in Ar, did unto me;) until I shall pass over Jordan into the land which the LORD our God giveth us.', 'as the children of esau which dwell in seir and the moabites which dwell in ar did unto me until i shall pass over jordan into the land which the lord our god giveth us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 30, 'But Sihon king of Heshbon would not let us pass by him: for the LORD thy God hardened his spirit, and made his heart obstinate, that he might deliver him into thy hand, as {appeareth} this day.', 'but sihon king of heshbon would not let us pass by him for the lord thy god hardened his spirit and made his heart obstinate that he might deliver him into thy hand as appeareth this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 31, 'And the LORD said unto me, Behold, I have begun to give Sihon and his land before thee: begin to possess, that thou mayest inherit his land.', 'and the lord said unto me behold i have begun to give sihon and his land before thee begin to possess that thou mayest inherit his land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 32, 'Then Sihon came out against us, he and all his people, to fight at Jahaz.', 'then sihon came out against us he and all his people to fight at jahaz');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 33, 'And the LORD our God delivered him before us; and we smote him, and his sons, and all his people.', 'and the lord our god delivered him before us and we smote him and his sons and all his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 34, 'And we took all his cities at that time, and utterly destroyed the men, and the women, and the little ones, of every city, we left none to remain: {the men...: Heb. every city of men, and women, and little ones}', 'and we took all his cities at that time and utterly destroyed the men and the women and the little ones of every city we left none to remain the men heb every city of men and women and little ones');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 35, 'Only the cattle we took for a prey unto ourselves, and the spoil of the cities which we took.', 'only the cattle we took for a prey unto ourselves and the spoil of the cities which we took');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 36, 'From Aroer, which {is} by the brink of the river of Arnon, and {from} the city that {is} by the river, even unto Gilead, there was not one city too strong for us: the LORD our God delivered all unto us:', 'from aroer which is by the brink of the river of arnon and from the city that is by the river even unto gilead there was not one city too strong for us the lord our god delivered all unto us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 2, 37, 'Only unto the land of the children of Ammon thou camest not, {nor} unto any place of the river Jabbok, nor unto the cities in the mountains, nor unto whatsoever the LORD our God forbad us.', 'only unto the land of the children of ammon thou camest not nor unto any place of the river jabbok nor unto the cities in the mountains nor unto whatsoever the lord our god forbad us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 1, 'Then we turned, and went up the way to Bashan: and Og the king of Bashan came out against us, he and all his people, to battle at Edrei.', 'then we turned and went up the way to bashan and og the king of bashan came out against us he and all his people to battle at edrei');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 2, 'And the LORD said unto me, Fear him not: for I will deliver him, and all his people, and his land, into thy hand; and thou shalt do unto him as thou didst unto Sihon king of the Amorites, which dwelt at Heshbon.', 'and the lord said unto me fear him not for i will deliver him and all his people and his land into thy hand and thou shalt do unto him as thou didst unto sihon king of the amorites which dwelt at heshbon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 3, 'So the LORD our God delivered into our hands Og also, the king of Bashan, and all his people: and we smote him until none was left to him remaining.', 'so the lord our god delivered into our hands og also the king of bashan and all his people and we smote him until none was left to him remaining');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 4, 'And we took all his cities at that time, there was not a city which we took not from them, threescore cities, all the region of Argob, the kingdom of Og in Bashan.', 'and we took all his cities at that time there was not a city which we took not from them threescore cities all the region of argob the kingdom of og in bashan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 5, 'All these cities {were} fenced with high walls, gates, and bars; beside unwalled towns a great many.', 'all these cities were fenced with high walls gates and bars beside unwalled towns a great many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 6, 'And we utterly destroyed them, as we did unto Sihon king of Heshbon, utterly destroying the men, women, and children, of every city.', 'and we utterly destroyed them as we did unto sihon king of heshbon utterly destroying the men women and children of every city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 7, 'But all the cattle, and the spoil of the cities, we took for a prey to ourselves.', 'but all the cattle and the spoil of the cities we took for a prey to ourselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 8, 'And we took at that time out of the hand of the two kings of the Amorites the land that {was} on this side Jordan, from the river of Arnon unto mount Hermon;', 'and we took at that time out of the hand of the two kings of the amorites the land that was on this side jordan from the river of arnon unto mount hermon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 9, '({Which} Hermon the Sidonians call Sirion; and the Amorites call it Shenir;)', 'which hermon the sidonians call sirion and the amorites call it shenir');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 10, 'All the cities of the plain, and all Gilead, and all Bashan, unto Salchah and Edrei, cities of the kingdom of Og in Bashan.', 'all the cities of the plain and all gilead and all bashan unto salchah and edrei cities of the kingdom of og in bashan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 11, 'For only Og king of Bashan remained of the remnant of giants; behold, his bedstead {was} a bedstead of iron; {is} it not in Rabbath of the children of Ammon? nine cubits {was} the length thereof, and four cubits the breadth of it, after the cubit of a man.', 'for only og king of bashan remained of the remnant of giants behold his bedstead was a bedstead of iron is it not in rabbath of the children of ammon nine cubits was the length thereof and four cubits the breadth of it after the cubit of a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 12, 'And this land, {which} we possessed at that time, from Aroer, which {is} by the river Arnon, and half mount Gilead, and the cities thereof, gave I unto the Reubenites and to the Gadites.', 'and this land which we possessed at that time from aroer which is by the river arnon and half mount gilead and the cities thereof gave i unto the reubenites and to the gadites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 13, 'And the rest of Gilead, and all Bashan, {being} the kingdom of Og, gave I unto the half tribe of Manasseh; all the region of Argob, with all Bashan, which was called the land of giants.', 'and the rest of gilead and all bashan being the kingdom of og gave i unto the half tribe of manasseh all the region of argob with all bashan which was called the land of giants');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 14, 'Jair the son of Manasseh took all the country of Argob unto the coasts of Geshuri and Maachathi; and called them after his own name, Bashanhavothjair, unto this day.', 'jair the son of manasseh took all the country of argob unto the coasts of geshuri and maachathi and called them after his own name bashanhavothjair unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 15, 'And I gave Gilead unto Machir.', 'and i gave gilead unto machir');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 16, 'And unto the Reubenites and unto the Gadites I gave from Gilead even unto the river Arnon half the valley, and the border even unto the river Jabbok, {which is} the border of the children of Ammon;', 'and unto the reubenites and unto the gadites i gave from gilead even unto the river arnon half the valley and the border even unto the river jabbok which is the border of the children of ammon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 17, 'The plain also, and Jordan, and the coast {thereof}, from Chinnereth even unto the sea of the plain, {even} the salt sea, under Ashdothpisgah eastward. {Ashdothpisgah; or, the springs of Pisgah, or, the hill}', 'the plain also and jordan and the coast thereof from chinnereth even unto the sea of the plain even the salt sea under ashdothpisgah eastward ashdothpisgah or the springs of pisgah or the hill');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 3, 18, 'And I commanded you at that time, saying, The LORD your God hath given you this land to possess it: ye shall pass over armed before your brethren the children of Israel, all {that are} meet for the war. {meet...: Heb. sons of power}', 'and i commanded you at that time saying the lord your god hath given you this land to possess it ye shall pass over armed before your brethren the children of israel all that are meet for the war meet heb sons of power');
