INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 4, 31, '(For the LORD thy God {is} a merciful God;) he will not forsake thee, neither destroy thee, nor forget the covenant of thy fathers which he sware unto them.', 'for the lord thy god is a merciful god he will not forsake thee neither destroy thee nor forget the covenant of thy fathers which he sware unto them');
