INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 5, '(I stood between the LORD and you at that time, to shew you the word of the LORD: for ye were afraid by reason of the fire, and went not up into the mount;) saying,', 'i stood between the lord and you at that time to shew you the word of the lord for ye were afraid by reason of the fire and went not up into the mount saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 6, 'I {am} the LORD thy God, which brought thee out of the land of Egypt, from the house of bondage. {bondage: Heb. servants}', 'i am the lord thy god which brought thee out of the land of egypt from the house of bondage bondage heb servants');
