INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 9, 'Thou shalt not bow down thyself unto them, nor serve them: for I the LORD thy God {am} a jealous God, visiting the iniquity of the fathers upon the children unto the third and fourth {generation} of them that hate me,', 'thou shalt not bow down thyself unto them nor serve them for i the lord thy god am a jealous god visiting the iniquity of the fathers upon the children unto the third and fourth generation of them that hate me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 10, 'And shewing mercy unto thousands of them that love me and keep my commandments.', 'and shewing mercy unto thousands of them that love me and keep my commandments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 11, 'Thou shalt not take the name of the LORD thy God in vain: for the LORD will not hold {him} guiltless that taketh his name in vain.', 'thou shalt not take the name of the lord thy god in vain for the lord will not hold him guiltless that taketh his name in vain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 12, 'Keep the sabbath day to sanctify it, as the LORD thy God hath commanded thee.', 'keep the sabbath day to sanctify it as the lord thy god hath commanded thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 13, 'Six days thou shalt labour, and do all thy work:', 'six days thou shalt labour and do all thy work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 14, 'But the seventh day {is} the sabbath of the LORD thy God: {in it} thou shalt not do any work, thou, nor thy son, nor thy daughter, nor thy manservant, nor thy maidservant, nor thine ox, nor thine ass, nor any of thy cattle, nor thy stranger that {is} within thy gates; that thy manservant and thy maidservant may rest as well as thou.', 'but the seventh day is the sabbath of the lord thy god in it thou shalt not do any work thou nor thy son nor thy daughter nor thy manservant nor thy maidservant nor thine ox nor thine ass nor any of thy cattle nor thy stranger that is within thy gates that thy manservant and thy maidservant may rest as well as thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 15, 'And remember that thou wast a servant in the land of Egypt, and {that} the LORD thy God brought thee out thence through a mighty hand and by a stretched out arm: therefore the LORD thy God commanded thee to keep the sabbath day.', 'and remember that thou wast a servant in the land of egypt and that the lord thy god brought thee out thence through a mighty hand and by a stretched out arm therefore the lord thy god commanded thee to keep the sabbath day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 16, 'Honour thy father and thy mother, as the LORD thy God hath commanded thee; that thy days may be prolonged, and that it may go well with thee, in the land which the LORD thy God giveth thee.', 'honour thy father and thy mother as the lord thy god hath commanded thee that thy days may be prolonged and that it may go well with thee in the land which the lord thy god giveth thee');
