INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 20, 'Neither shalt thou bear false witness against thy neighbour.', 'neither shalt thou bear false witness against thy neighbour');
