INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 22, 'These words the LORD spake unto all your assembly in the mount out of the midst of the fire, of the cloud, and of the thick darkness, with a great voice: and he added no more. And he wrote them in two tables of stone, and delivered them unto me.', 'these words the lord spake unto all your assembly in the mount out of the midst of the fire of the cloud and of the thick darkness with a great voice and he added no more and he wrote them in two tables of stone and delivered them unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 23, 'And it came to pass, when ye heard the voice out of the midst of the darkness, (for the mountain did burn with fire,) that ye came near unto me, {even} all the heads of your tribes, and your elders;', 'and it came to pass when ye heard the voice out of the midst of the darkness for the mountain did burn with fire that ye came near unto me even all the heads of your tribes and your elders');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 24, 'And ye said, Behold, the LORD our God hath shewed us his glory and his greatness, and we have heard his voice out of the midst of the fire: we have seen this day that God doth talk with man, and he liveth.', 'and ye said behold the lord our god hath shewed us his glory and his greatness and we have heard his voice out of the midst of the fire we have seen this day that god doth talk with man and he liveth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 25, 'Now therefore why should we die? for this great fire will consume us: if we hear the voice of the LORD our God any more, then we shall die. {hear: Heb. add to hear}', 'now therefore why should we die for this great fire will consume us if we hear the voice of the lord our god any more then we shall die hear heb add to hear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 26, 'For who {is there of} all flesh, that hath heard the voice of the living God speaking out of the midst of the fire, as we {have}, and lived?', 'for who is there of all flesh that hath heard the voice of the living god speaking out of the midst of the fire as we have and lived');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 27, 'Go thou near, and hear all that the LORD our God shall say: and speak thou unto us all that the LORD our God shall speak unto thee; and we will hear {it}, and do {it}.', 'go thou near and hear all that the lord our god shall say and speak thou unto us all that the lord our god shall speak unto thee and we will hear it and do it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 28, 'And the LORD heard the voice of your words, when ye spake unto me; and the LORD said unto me, I have heard the voice of the words of this people, which they have spoken unto thee: they have well said all that they have spoken.', 'and the lord heard the voice of your words when ye spake unto me and the lord said unto me i have heard the voice of the words of this people which they have spoken unto thee they have well said all that they have spoken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 29, 'O that there were such an heart in them, that they would fear me, and keep all my commandments always, that it might be well with them, and with their children for ever!', 'o that there were such an heart in them that they would fear me and keep all my commandments always that it might be well with them and with their children for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 30, 'Go say to them, Get you into your tents again.', 'go say to them get you into your tents again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 31, 'But as for thee, stand thou here by me, and I will speak unto thee all the commandments, and the statutes, and the judgments, which thou shalt teach them, that they may do {them} in the land which I give them to possess it.', 'but as for thee stand thou here by me and i will speak unto thee all the commandments and the statutes and the judgments which thou shalt teach them that they may do them in the land which i give them to possess it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 32, 'Ye shall observe to do therefore as the LORD your God hath commanded you: ye shall not turn aside to the right hand or to the left.', 'ye shall observe to do therefore as the lord your god hath commanded you ye shall not turn aside to the right hand or to the left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 5, 33, 'Ye shall walk in all the ways which the LORD your God hath commanded you, that ye may live, and {that it may be} well with you, and {that} ye may prolong {your} days in the land which ye shall possess.', 'ye shall walk in all the ways which the lord your god hath commanded you that ye may live and that it may be well with you and that ye may prolong your days in the land which ye shall possess');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 1, 'Now these {are} the commandments, the statutes, and the judgments, which the LORD your God commanded to teach you, that ye might do {them} in the land whither ye go to possess it: {go: Heb. pass over}', 'now these are the commandments the statutes and the judgments which the lord your god commanded to teach you that ye might do them in the land whither ye go to possess it go heb pass over');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 2, 'That thou mightest fear the LORD thy God, to keep all his statutes and his commandments, which I command thee, thou, and thy son, and thy son''s son, all the days of thy life; and that thy days may be prolonged.', 'that thou mightest fear the lord thy god to keep all his statutes and his commandments which i command thee thou and thy son and thy son s son all the days of thy life and that thy days may be prolonged');
