INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 4, 'Hear, O Israel: The LORD our God {is} one LORD:', 'hear o israel the lord our god is one lord');
