INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 7, 'And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up. {teach: Heb. whet, or, sharpen}', 'and thou shalt teach them diligently unto thy children and shalt talk of them when thou sittest in thine house and when thou walkest by the way and when thou liest down and when thou risest up teach heb whet or sharpen');
