INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 9, 'And thou shalt write them upon the posts of thy house, and on thy gates.', 'and thou shalt write them upon the posts of thy house and on thy gates');
