INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 11, 'And houses full of all good {things}, which thou filledst not, and wells digged, which thou diggedst not, vineyards and olive trees, which thou plantedst not; when thou shalt have eaten and be full;', 'and houses full of all good things which thou filledst not and wells digged which thou diggedst not vineyards and olive trees which thou plantedst not when thou shalt have eaten and be full');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 12, '{Then} beware lest thou forget the LORD, which brought thee forth out of the land of Egypt, from the house of bondage. {bondage: Heb. bondmen or, servants}', 'then beware lest thou forget the lord which brought thee forth out of the land of egypt from the house of bondage bondage heb bondmen or servants');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 13, 'Thou shalt fear the LORD thy God, and serve him, and shalt swear by his name.', 'thou shalt fear the lord thy god and serve him and shalt swear by his name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 14, 'Ye shall not go after other gods, of the gods of the people which {are} round about you;', 'ye shall not go after other gods of the gods of the people which are round about you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 15, '(For the LORD thy God {is} a jealous God among you) lest the anger of the LORD thy God be kindled against thee, and destroy thee from off the face of the earth.', 'for the lord thy god is a jealous god among you lest the anger of the lord thy god be kindled against thee and destroy thee from off the face of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 16, 'Ye shall not tempt the LORD your God, as ye tempted {him} in Massah.', 'ye shall not tempt the lord your god as ye tempted him in massah');
