INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 18, 'And thou shalt do {that which is} right and good in the sight of the LORD: that it may be well with thee, and that thou mayest go in and possess the good land which the LORD sware unto thy fathers,', 'and thou shalt do that which is right and good in the sight of the lord that it may be well with thee and that thou mayest go in and possess the good land which the lord sware unto thy fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 19, 'To cast out all thine enemies from before thee, as the LORD hath spoken.', 'to cast out all thine enemies from before thee as the lord hath spoken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 20, '{And} when thy son asketh thee in time to come, saying, What {mean} the testimonies, and the statutes, and the judgments, which the LORD our God hath commanded you? {in...: Heb. to morrow}', 'and when thy son asketh thee in time to come saying what mean the testimonies and the statutes and the judgments which the lord our god hath commanded you in heb to morrow');
