INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 22, 'And the LORD shewed signs and wonders, great and sore, upon Egypt, upon Pharaoh, and upon all his household, before our eyes: {sore: Heb. evil}', 'and the lord shewed signs and wonders great and sore upon egypt upon pharaoh and upon all his household before our eyes sore heb evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 23, 'And he brought us out from thence, that he might bring us in, to give us the land which he sware unto our fathers.', 'and he brought us out from thence that he might bring us in to give us the land which he sware unto our fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 24, 'And the LORD commanded us to do all these statutes, to fear the LORD our God, for our good always, that he might preserve us alive, as {it is} at this day.', 'and the lord commanded us to do all these statutes to fear the lord our god for our good always that he might preserve us alive as it is at this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 6, 25, 'And it shall be our righteousness, if we observe to do all these commandments before the LORD our God, as he hath commanded us.', 'and it shall be our righteousness if we observe to do all these commandments before the lord our god as he hath commanded us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 1, 'When the LORD thy God shall bring thee into the land whither thou goest to possess it, and hath cast out many nations before thee, the Hittites, and the Girgashites, and the Amorites, and the Canaanites, and the Perizzites, and the Hivites, and the Jebusites, seven nations greater and mightier than thou;', 'when the lord thy god shall bring thee into the land whither thou goest to possess it and hath cast out many nations before thee the hittites and the girgashites and the amorites and the canaanites and the perizzites and the hivites and the jebusites seven nations greater and mightier than thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 2, 'And when the LORD thy God shall deliver them before thee; thou shalt smite them, {and} utterly destroy them; thou shalt make no covenant with them, nor shew mercy unto them:', 'and when the lord thy god shall deliver them before thee thou shalt smite them and utterly destroy them thou shalt make no covenant with them nor shew mercy unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 3, 'Neither shalt thou make marriages with them; thy daughter thou shalt not give unto his son, nor his daughter shalt thou take unto thy son.', 'neither shalt thou make marriages with them thy daughter thou shalt not give unto his son nor his daughter shalt thou take unto thy son');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 4, 'For they will turn away thy son from following me, that they may serve other gods: so will the anger of the LORD be kindled against you, and destroy thee suddenly.', 'for they will turn away thy son from following me that they may serve other gods so will the anger of the lord be kindled against you and destroy thee suddenly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 5, 'But thus shall ye deal with them; ye shall destroy their altars, and break down their images, and cut down their groves, and burn their graven images with fire. {their images: Heb. their statues, or, pillars}', 'but thus shall ye deal with them ye shall destroy their altars and break down their images and cut down their groves and burn their graven images with fire their images heb their statues or pillars');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 6, 'For thou {art} an holy people unto the LORD thy God: the LORD thy God hath chosen thee to be a special people unto himself, above all people that {are} upon the face of the earth.', 'for thou art an holy people unto the lord thy god the lord thy god hath chosen thee to be a special people unto himself above all people that are upon the face of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 7, 'The LORD did not set his love upon you, nor choose you, because ye were more in number than any people; for ye {were} the fewest of all people:', 'the lord did not set his love upon you nor choose you because ye were more in number than any people for ye were the fewest of all people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 8, 'But because the LORD loved you, and because he would keep the oath which he had sworn unto your fathers, hath the LORD brought you out with a mighty hand, and redeemed you out of the house of bondmen, from the hand of Pharaoh king of Egypt.', 'but because the lord loved you and because he would keep the oath which he had sworn unto your fathers hath the lord brought you out with a mighty hand and redeemed you out of the house of bondmen from the hand of pharaoh king of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 9, 'Know therefore that the LORD thy God, he {is} God, the faithful God, which keepeth covenant and mercy with them that love him and keep his commandments to a thousand generations;', 'know therefore that the lord thy god he is god the faithful god which keepeth covenant and mercy with them that love him and keep his commandments to a thousand generations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 10, 'And repayeth them that hate him to their face, to destroy them: he will not be slack to him that hateth him, he will repay him to his face.', 'and repayeth them that hate him to their face to destroy them he will not be slack to him that hateth him he will repay him to his face');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 11, 'Thou shalt therefore keep the commandments, and the statutes, and the judgments, which I command thee this day, to do them.', 'thou shalt therefore keep the commandments and the statutes and the judgments which i command thee this day to do them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 12, 'Wherefore it shall come to pass, if ye hearken to these judgments, and keep, and do them, that the LORD thy God shall keep unto thee the covenant and the mercy which he sware unto thy fathers: {if: Heb. because}', 'wherefore it shall come to pass if ye hearken to these judgments and keep and do them that the lord thy god shall keep unto thee the covenant and the mercy which he sware unto thy fathers if heb because');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 13, 'And he will love thee, and bless thee, and multiply thee: he will also bless the fruit of thy womb, and the fruit of thy land, thy corn, and thy wine, and thine oil, the increase of thy kine, and the flocks of thy sheep, in the land which he sware unto thy fathers to give thee.', 'and he will love thee and bless thee and multiply thee he will also bless the fruit of thy womb and the fruit of thy land thy corn and thy wine and thine oil the increase of thy kine and the flocks of thy sheep in the land which he sware unto thy fathers to give thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 14, 'Thou shalt be blessed above all people: there shall not be male or female barren among you, or among your cattle.', 'thou shalt be blessed above all people there shall not be male or female barren among you or among your cattle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 15, 'And the LORD will take away from thee all sickness, and will put none of the evil diseases of Egypt, which thou knowest, upon thee; but will lay them upon all {them} that hate thee.', 'and the lord will take away from thee all sickness and will put none of the evil diseases of egypt which thou knowest upon thee but will lay them upon all them that hate thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 16, 'And thou shalt consume all the people which the LORD thy God shall deliver thee; thine eye shall have no pity upon them: neither shalt thou serve their gods; for that {will be} a snare unto thee.', 'and thou shalt consume all the people which the lord thy god shall deliver thee thine eye shall have no pity upon them neither shalt thou serve their gods for that will be a snare unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 17, 'If thou shalt say in thine heart, These nations {are} more than I; how can I dispossess them?', 'if thou shalt say in thine heart these nations are more than i how can i dispossess them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 18, 'Thou shalt not be afraid of them: {but} shalt well remember what the LORD thy God did unto Pharaoh, and unto all Egypt;', 'thou shalt not be afraid of them but shalt well remember what the lord thy god did unto pharaoh and unto all egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 19, 'The great temptations which thine eyes saw, and the signs, and the wonders, and the mighty hand, and the stretched out arm, whereby the LORD thy God brought thee out: so shall the LORD thy God do unto all the people of whom thou art afraid.', 'the great temptations which thine eyes saw and the signs and the wonders and the mighty hand and the stretched out arm whereby the lord thy god brought thee out so shall the lord thy god do unto all the people of whom thou art afraid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 20, 'Moreover the LORD thy God will send the hornet among them, until they that are left, and hide themselves from thee, be destroyed.', 'moreover the lord thy god will send the hornet among them until they that are left and hide themselves from thee be destroyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 21, 'Thou shalt not be affrighted at them: for the LORD thy God {is} among you, a mighty God and terrible.', 'thou shalt not be affrighted at them for the lord thy god is among you a mighty god and terrible');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 22, 'And the LORD thy God will put out those nations before thee by little and little: thou mayest not consume them at once, lest the beasts of the field increase upon thee. {put...: Heb. pluck off}', 'and the lord thy god will put out those nations before thee by little and little thou mayest not consume them at once lest the beasts of the field increase upon thee put heb pluck off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 23, 'But the LORD thy God shall deliver them unto thee, and shall destroy them with a mighty destruction, until they be destroyed. {unto...: Heb. before thy face}', 'but the lord thy god shall deliver them unto thee and shall destroy them with a mighty destruction until they be destroyed unto heb before thy face');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 24, 'And he shall deliver their kings into thine hand, and thou shalt destroy their name from under heaven: there shall no man be able to stand before thee, until thou have destroyed them.', 'and he shall deliver their kings into thine hand and thou shalt destroy their name from under heaven there shall no man be able to stand before thee until thou have destroyed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 25, 'The graven images of their gods shall ye burn with fire: thou shalt not desire the silver or gold {that is} on them, nor take {it} unto thee, lest thou be snared therein: for it {is} an abomination to the LORD thy God.', 'the graven images of their gods shall ye burn with fire thou shalt not desire the silver or gold that is on them nor take it unto thee lest thou be snared therein for it is an abomination to the lord thy god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 7, 26, 'Neither shalt thou bring an abomination into thine house, lest thou be a cursed thing like it: {but} thou shalt utterly detest it, and thou shalt utterly abhor it; for it {is} a cursed thing.', 'neither shalt thou bring an abomination into thine house lest thou be a cursed thing like it but thou shalt utterly detest it and thou shalt utterly abhor it for it is a cursed thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 1, 'All the commandments which I command thee this day shall ye observe to do, that ye may live, and multiply, and go in and possess the land which the LORD sware unto your fathers.', 'all the commandments which i command thee this day shall ye observe to do that ye may live and multiply and go in and possess the land which the lord sware unto your fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 2, 'And thou shalt remember all the way which the LORD thy God led thee these forty years in the wilderness, to humble thee, {and} to prove thee, to know what {was} in thine heart, whether thou wouldest keep his commandments, or no.', 'and thou shalt remember all the way which the lord thy god led thee these forty years in the wilderness to humble thee and to prove thee to know what was in thine heart whether thou wouldest keep his commandments or no');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 3, 'And he humbled thee, and suffered thee to hunger, and fed thee with manna, which thou knewest not, neither did thy fathers know; that he might make thee know that man doth not live by bread only, but by every {word} that proceedeth out of the mouth of the LORD doth man live.', 'and he humbled thee and suffered thee to hunger and fed thee with manna which thou knewest not neither did thy fathers know that he might make thee know that man doth not live by bread only but by every word that proceedeth out of the mouth of the lord doth man live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 4, 'Thy raiment waxed not old upon thee, neither did thy foot swell, these forty years.', 'thy raiment waxed not old upon thee neither did thy foot swell these forty years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 5, 'Thou shalt also consider in thine heart, that, as a man chasteneth his son, {so} the LORD thy God chasteneth thee.', 'thou shalt also consider in thine heart that as a man chasteneth his son so the lord thy god chasteneth thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 6, 'Therefore thou shalt keep the commandments of the LORD thy God, to walk in his ways, and to fear him.', 'therefore thou shalt keep the commandments of the lord thy god to walk in his ways and to fear him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 7, 'For the LORD thy God bringeth thee into a good land, a land of brooks of water, of fountains and depths that spring out of valleys and hills;', 'for the lord thy god bringeth thee into a good land a land of brooks of water of fountains and depths that spring out of valleys and hills');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 8, 'A land of wheat, and barley, and vines, and fig trees, and pomegranates; a land of oil olive, and honey; {of oil...: Heb. of olive tree of oil}', 'a land of wheat and barley and vines and fig trees and pomegranates a land of oil olive and honey of oil heb of olive tree of oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 9, 'A land wherein thou shalt eat bread without scarceness, thou shalt not lack any {thing} in it; a land whose stones {are} iron, and out of whose hills thou mayest dig brass.', 'a land wherein thou shalt eat bread without scarceness thou shalt not lack any thing in it a land whose stones are iron and out of whose hills thou mayest dig brass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 10, 'When thou hast eaten and art full, then thou shalt bless the LORD thy God for the good land which he hath given thee.', 'when thou hast eaten and art full then thou shalt bless the lord thy god for the good land which he hath given thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 11, 'Beware that thou forget not the LORD thy God, in not keeping his commandments, and his judgments, and his statutes, which I command thee this day:', 'beware that thou forget not the lord thy god in not keeping his commandments and his judgments and his statutes which i command thee this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 12, 'Lest {when} thou hast eaten and art full, and hast built goodly houses, and dwelt {therein};', 'lest when thou hast eaten and art full and hast built goodly houses and dwelt therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 13, 'And {when} thy herds and thy flocks multiply, and thy silver and thy gold is multiplied, and all that thou hast is multiplied;', 'and when thy herds and thy flocks multiply and thy silver and thy gold is multiplied and all that thou hast is multiplied');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 14, 'Then thine heart be lifted up, and thou forget the LORD thy God, which brought thee forth out of the land of Egypt, from the house of bondage;', 'then thine heart be lifted up and thou forget the lord thy god which brought thee forth out of the land of egypt from the house of bondage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 15, 'Who led thee through that great and terrible wilderness, {wherein were} fiery serpents, and scorpions, and drought, where {there was} no water; who brought thee forth water out of the rock of flint;', 'who led thee through that great and terrible wilderness wherein were fiery serpents and scorpions and drought where there was no water who brought thee forth water out of the rock of flint');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 16, 'Who fed thee in the wilderness with manna, which thy fathers knew not, that he might humble thee, and that he might prove thee, to do thee good at thy latter end;', 'who fed thee in the wilderness with manna which thy fathers knew not that he might humble thee and that he might prove thee to do thee good at thy latter end');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 17, 'And thou say in thine heart, My power and the might of {mine} hand hath gotten me this wealth.', 'and thou say in thine heart my power and the might of mine hand hath gotten me this wealth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 18, 'But thou shalt remember the LORD thy God: for {it is} he that giveth thee power to get wealth, that he may establish his covenant which he sware unto thy fathers, as {it is} this day.', 'but thou shalt remember the lord thy god for it is he that giveth thee power to get wealth that he may establish his covenant which he sware unto thy fathers as it is this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 19, 'And it shall be, if thou do at all forget the LORD thy God, and walk after other gods, and serve them, and worship them, I testify against you this day that ye shall surely perish.', 'and it shall be if thou do at all forget the lord thy god and walk after other gods and serve them and worship them i testify against you this day that ye shall surely perish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 8, 20, 'As the nations which the LORD destroyeth before your face, so shall ye perish; because ye would not be obedient unto the voice of the LORD your God.', 'as the nations which the lord destroyeth before your face so shall ye perish because ye would not be obedient unto the voice of the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 1, 'Hear, O Israel: Thou {art} to pass over Jordan this day, to go in to possess nations greater and mightier than thyself, cities great and fenced up to heaven,', 'hear o israel thou art to pass over jordan this day to go in to possess nations greater and mightier than thyself cities great and fenced up to heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 2, 'A people great and tall, the children of the Anakims, whom thou knowest, and {of whom} thou hast heard {say}, Who can stand before the children of Anak!', 'a people great and tall the children of the anakims whom thou knowest and of whom thou hast heard say who can stand before the children of anak');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 3, 'Understand therefore this day, that the LORD thy God {is} he which goeth over before thee; {as} a consuming fire he shall destroy them, and he shall bring them down before thy face: so shalt thou drive them out, and destroy them quickly, as the LORD hath said unto thee.', 'understand therefore this day that the lord thy god is he which goeth over before thee as a consuming fire he shall destroy them and he shall bring them down before thy face so shalt thou drive them out and destroy them quickly as the lord hath said unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 4, 'Speak not thou in thine heart, after that the LORD thy God hath cast them out from before thee, saying, For my righteousness the LORD hath brought me in to possess this land: but for the wickedness of these nations the LORD doth drive them out from before thee.', 'speak not thou in thine heart after that the lord thy god hath cast them out from before thee saying for my righteousness the lord hath brought me in to possess this land but for the wickedness of these nations the lord doth drive them out from before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 5, 'Not for thy righteousness, or for the uprightness of thine heart, dost thou go to possess their land: but for the wickedness of these nations the LORD thy God doth drive them out from before thee, and that he may perform the word which the LORD sware unto thy fathers, Abraham, Isaac, and Jacob.', 'not for thy righteousness or for the uprightness of thine heart dost thou go to possess their land but for the wickedness of these nations the lord thy god doth drive them out from before thee and that he may perform the word which the lord sware unto thy fathers abraham isaac and jacob');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 6, 'Understand therefore, that the LORD thy God giveth thee not this good land to possess it for thy righteousness; for thou {art} a stiffnecked people.', 'understand therefore that the lord thy god giveth thee not this good land to possess it for thy righteousness for thou art a stiffnecked people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 7, 'Remember, {and} forget not, how thou provokedst the LORD thy God to wrath in the wilderness: from the day that thou didst depart out of the land of Egypt, until ye came unto this place, ye have been rebellious against the LORD.', 'remember and forget not how thou provokedst the lord thy god to wrath in the wilderness from the day that thou didst depart out of the land of egypt until ye came unto this place ye have been rebellious against the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 8, 'Also in Horeb ye provoked the LORD to wrath, so that the LORD was angry with you to have destroyed you.', 'also in horeb ye provoked the lord to wrath so that the lord was angry with you to have destroyed you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 9, 'When I was gone up into the mount to receive the tables of stone, {even} the tables of the covenant which the LORD made with you, then I abode in the mount forty days and forty nights, I neither did eat bread nor drink water:', 'when i was gone up into the mount to receive the tables of stone even the tables of the covenant which the lord made with you then i abode in the mount forty days and forty nights i neither did eat bread nor drink water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 10, 'And the LORD delivered unto me two tables of stone written with the finger of God; and on them {was written} according to all the words, which the LORD spake with you in the mount out of the midst of the fire in the day of the assembly.', 'and the lord delivered unto me two tables of stone written with the finger of god and on them was written according to all the words which the lord spake with you in the mount out of the midst of the fire in the day of the assembly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 11, 'And it came to pass at the end of forty days and forty nights, {that} the LORD gave me the two tables of stone, {even} the tables of the covenant.', 'and it came to pass at the end of forty days and forty nights that the lord gave me the two tables of stone even the tables of the covenant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 9, 12, 'And the LORD said unto me, Arise, get thee down quickly from hence; for thy people which thou hast brought forth out of Egypt have corrupted {themselves}; they are quickly turned aside out of the way which I commanded them; they have made them a molten image.', 'and the lord said unto me arise get thee down quickly from hence for thy people which thou hast brought forth out of egypt have corrupted themselves they are quickly turned aside out of the way which i commanded them they have made them a molten image');
