INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 1, 'At that time the LORD said unto me, Hew thee two tables of stone like unto the first, and come up unto me into the mount, and make thee an ark of wood.', 'at that time the lord said unto me hew thee two tables of stone like unto the first and come up unto me into the mount and make thee an ark of wood');
