INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 3, 'And I made an ark {of} shittim wood, and hewed two tables of stone like unto the first, and went up into the mount, having the two tables in mine hand.', 'and i made an ark of shittim wood and hewed two tables of stone like unto the first and went up into the mount having the two tables in mine hand');
