INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 5, 'And I turned myself and came down from the mount, and put the tables in the ark which I had made; and there they be, as the LORD commanded me.', 'and i turned myself and came down from the mount and put the tables in the ark which i had made and there they be as the lord commanded me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 6, 'And the children of Israel took their journey from Beeroth of the children of Jaakan to Mosera: there Aaron died, and there he was buried; and Eleazar his son ministered in the priest''s office in his stead.', 'and the children of israel took their journey from beeroth of the children of jaakan to mosera there aaron died and there he was buried and eleazar his son ministered in the priest s office in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 7, 'From thence they journeyed unto Gudgodah; and from Gudgodah to Jotbath, a land of rivers of waters.', 'from thence they journeyed unto gudgodah and from gudgodah to jotbath a land of rivers of waters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 8, 'At that time the LORD separated the tribe of Levi, to bear the ark of the covenant of the LORD, to stand before the LORD to minister unto him, and to bless in his name, unto this day.', 'at that time the lord separated the tribe of levi to bear the ark of the covenant of the lord to stand before the lord to minister unto him and to bless in his name unto this day');
