INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 11, 'And the LORD said unto me, Arise, take {thy} journey before the people, that they may go in and possess the land, which I sware unto their fathers to give unto them. {take...: Heb. go in journey}', 'and the lord said unto me arise take thy journey before the people that they may go in and possess the land which i sware unto their fathers to give unto them take heb go in journey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 12, 'And now, Israel, what doth the LORD thy God require of thee, but to fear the LORD thy God, to walk in all his ways, and to love him, and to serve the LORD thy God with all thy heart and with all thy soul,', 'and now israel what doth the lord thy god require of thee but to fear the lord thy god to walk in all his ways and to love him and to serve the lord thy god with all thy heart and with all thy soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 13, 'To keep the commandments of the LORD, and his statutes, which I command thee this day for thy good?', 'to keep the commandments of the lord and his statutes which i command thee this day for thy good');
