INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 16, 'Circumcise therefore the foreskin of your heart, and be no more stiffnecked.', 'circumcise therefore the foreskin of your heart and be no more stiffnecked');
