INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 19, 'Love ye therefore the stranger: for ye were strangers in the land of Egypt.', 'love ye therefore the stranger for ye were strangers in the land of egypt');
