INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 21, 'He {is} thy praise, and he {is} thy God, that hath done for thee these great and terrible things, which thine eyes have seen.', 'he is thy praise and he is thy god that hath done for thee these great and terrible things which thine eyes have seen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 10, 22, 'Thy fathers went down into Egypt with threescore and ten persons; and now the LORD thy God hath made thee as the stars of heaven for multitude.', 'thy fathers went down into egypt with threescore and ten persons and now the lord thy god hath made thee as the stars of heaven for multitude');
