INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 9, 'And that ye may prolong {your} days in the land, which the LORD sware unto your fathers to give unto them and to their seed, a land that floweth with milk and honey.', 'and that ye may prolong your days in the land which the lord sware unto your fathers to give unto them and to their seed a land that floweth with milk and honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 10, 'For the land, whither thou goest in to possess it, {is} not as the land of Egypt, from whence ye came out, where thou sowedst thy seed, and wateredst {it} with thy foot, as a garden of herbs:', 'for the land whither thou goest in to possess it is not as the land of egypt from whence ye came out where thou sowedst thy seed and wateredst it with thy foot as a garden of herbs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 11, 'But the land, whither ye go to possess it, {is} a land of hills and valleys, {and} drinketh water of the rain of heaven:', 'but the land whither ye go to possess it is a land of hills and valleys and drinketh water of the rain of heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 12, 'A land which the LORD thy God careth for: the eyes of the LORD thy God {are} always upon it, from the beginning of the year even unto the end of the year. {careth...: Heb. seeketh}', 'a land which the lord thy god careth for the eyes of the lord thy god are always upon it from the beginning of the year even unto the end of the year careth heb seeketh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 13, 'And it shall come to pass, if ye shall hearken diligently unto my commandments which I command you this day, to love the LORD your God, and to serve him with all your heart and with all your soul,', 'and it shall come to pass if ye shall hearken diligently unto my commandments which i command you this day to love the lord your god and to serve him with all your heart and with all your soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 14, 'That I will give {you} the rain of your land in his due season, the first rain and the latter rain, that thou mayest gather in thy corn, and thy wine, and thine oil.', 'that i will give you the rain of your land in his due season the first rain and the latter rain that thou mayest gather in thy corn and thy wine and thine oil');
