INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 16, 'Take heed to yourselves, that your heart be not deceived, and ye turn aside, and serve other gods, and worship them;', 'take heed to yourselves that your heart be not deceived and ye turn aside and serve other gods and worship them');
