INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 22, 'For if ye shall diligently keep all these commandments which I command you, to do them, to love the LORD your God, to walk in all his ways, and to cleave unto him;', 'for if ye shall diligently keep all these commandments which i command you to do them to love the lord your god to walk in all his ways and to cleave unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 23, 'Then will the LORD drive out all these nations from before you, and ye shall possess greater nations and mightier than yourselves.', 'then will the lord drive out all these nations from before you and ye shall possess greater nations and mightier than yourselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 24, 'Every place whereon the soles of your feet shall tread shall be yours: from the wilderness and Lebanon, from the river, the river Euphrates, even unto the uttermost sea shall your coast be.', 'every place whereon the soles of your feet shall tread shall be yours from the wilderness and lebanon from the river the river euphrates even unto the uttermost sea shall your coast be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 25, 'There shall no man be able to stand before you: {for} the LORD your God shall lay the fear of you and the dread of you upon all the land that ye shall tread upon, as he hath said unto you.', 'there shall no man be able to stand before you for the lord your god shall lay the fear of you and the dread of you upon all the land that ye shall tread upon as he hath said unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 26, 'Behold, I set before you this day a blessing and a curse;', 'behold i set before you this day a blessing and a curse');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 27, 'A blessing, if ye obey the commandments of the LORD your God, which I command you this day:', 'a blessing if ye obey the commandments of the lord your god which i command you this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 28, 'And a curse, if ye will not obey the commandments of the LORD your God, but turn aside out of the way which I command you this day, to go after other gods, which ye have not known.', 'and a curse if ye will not obey the commandments of the lord your god but turn aside out of the way which i command you this day to go after other gods which ye have not known');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 29, 'And it shall come to pass, when the LORD thy God hath brought thee in unto the land whither thou goest to possess it, that thou shalt put the blessing upon mount Gerizim, and the curse upon mount Ebal.', 'and it shall come to pass when the lord thy god hath brought thee in unto the land whither thou goest to possess it that thou shalt put the blessing upon mount gerizim and the curse upon mount ebal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 30, '{Are} they not on the other side Jordan, by the way where the sun goeth down, in the land of the Canaanites, which dwell in the champaign over against Gilgal, beside the plains of Moreh?', 'are they not on the other side jordan by the way where the sun goeth down in the land of the canaanites which dwell in the champaign over against gilgal beside the plains of moreh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 31, 'For ye shall pass over Jordan to go in to possess the land which the LORD your God giveth you, and ye shall possess it, and dwell therein.', 'for ye shall pass over jordan to go in to possess the land which the lord your god giveth you and ye shall possess it and dwell therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 11, 32, 'And ye shall observe to do all the statutes and judgments which I set before you this day.', 'and ye shall observe to do all the statutes and judgments which i set before you this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 1, 'These {are} the statutes and judgments, which ye shall observe to do in the land, which the LORD God of thy fathers giveth thee to possess it, all the days that ye live upon the earth.', 'these are the statutes and judgments which ye shall observe to do in the land which the lord god of thy fathers giveth thee to possess it all the days that ye live upon the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 2, 'Ye shall utterly destroy all the places, wherein the nations which ye shall possess served their gods, upon the high mountains, and upon the hills, and under every green tree: {possess: or, inherit}', 'ye shall utterly destroy all the places wherein the nations which ye shall possess served their gods upon the high mountains and upon the hills and under every green tree possess or inherit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 3, 'And ye shall overthrow their altars, and break their pillars, and burn their groves with fire; and ye shall hew down the graven images of their gods, and destroy the names of them out of that place. {overthrow: Heb. break down}', 'and ye shall overthrow their altars and break their pillars and burn their groves with fire and ye shall hew down the graven images of their gods and destroy the names of them out of that place overthrow heb break down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 4, 'Ye shall not do so unto the LORD your God.', 'ye shall not do so unto the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 5, 'But unto the place which the LORD your God shall choose out of all your tribes to put his name there, {even} unto his habitation shall ye seek, and thither thou shalt come:', 'but unto the place which the lord your god shall choose out of all your tribes to put his name there even unto his habitation shall ye seek and thither thou shalt come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 6, 'And thither ye shall bring your burnt offerings, and your sacrifices, and your tithes, and heave offerings of your hand, and your vows, and your freewill offerings, and the firstlings of your herds and of your flocks:', 'and thither ye shall bring your burnt offerings and your sacrifices and your tithes and heave offerings of your hand and your vows and your freewill offerings and the firstlings of your herds and of your flocks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 7, 'And there ye shall eat before the LORD your God, and ye shall rejoice in all that ye put your hand unto, ye and your households, wherein the LORD thy God hath blessed thee.', 'and there ye shall eat before the lord your god and ye shall rejoice in all that ye put your hand unto ye and your households wherein the lord thy god hath blessed thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 8, 'Ye shall not do after all {the things} that we do here this day, every man whatsoever {is} right in his own eyes.', 'ye shall not do after all the things that we do here this day every man whatsoever is right in his own eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 9, 'For ye are not as yet come to the rest and to the inheritance, which the LORD your God giveth you.', 'for ye are not as yet come to the rest and to the inheritance which the lord your god giveth you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 10, 'But {when} ye go over Jordan, and dwell in the land which the LORD your God giveth you to inherit, and {when} he giveth you rest from all your enemies round about, so that ye dwell in safety;', 'but when ye go over jordan and dwell in the land which the lord your god giveth you to inherit and when he giveth you rest from all your enemies round about so that ye dwell in safety');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 11, 'Then there shall be a place which the LORD your God shall choose to cause his name to dwell there; thither shall ye bring all that I command you; your burnt offerings, and your sacrifices, your tithes, and the heave offering of your hand, and all your choice vows which ye vow unto the LORD: {your choice...: Heb. the choice of your vows}', 'then there shall be a place which the lord your god shall choose to cause his name to dwell there thither shall ye bring all that i command you your burnt offerings and your sacrifices your tithes and the heave offering of your hand and all your choice vows which ye vow unto the lord your choice heb the choice of your vows');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 12, 'And ye shall rejoice before the LORD your God, ye, and your sons, and your daughters, and your menservants, and your maidservants, and the Levite that {is} within your gates; forasmuch as he hath no part nor inheritance with you.', 'and ye shall rejoice before the lord your god ye and your sons and your daughters and your menservants and your maidservants and the levite that is within your gates forasmuch as he hath no part nor inheritance with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 13, 'Take heed to thyself that thou offer not thy burnt offerings in every place that thou seest:', 'take heed to thyself that thou offer not thy burnt offerings in every place that thou seest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 14, 'But in the place which the LORD shall choose in one of thy tribes, there thou shalt offer thy burnt offerings, and there thou shalt do all that I command thee.', 'but in the place which the lord shall choose in one of thy tribes there thou shalt offer thy burnt offerings and there thou shalt do all that i command thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 15, 'Notwithstanding thou mayest kill and eat flesh in all thy gates, whatsoever thy soul lusteth after, according to the blessing of the LORD thy God which he hath given thee: the unclean and the clean may eat thereof, as of the roebuck, and as of the hart.', 'notwithstanding thou mayest kill and eat flesh in all thy gates whatsoever thy soul lusteth after according to the blessing of the lord thy god which he hath given thee the unclean and the clean may eat thereof as of the roebuck and as of the hart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 16, 'Only ye shall not eat the blood; ye shall pour it upon the earth as water.', 'only ye shall not eat the blood ye shall pour it upon the earth as water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 17, 'Thou mayest not eat within thy gates the tithe of thy corn, or of thy wine, or of thy oil, or the firstlings of thy herds or of thy flock, nor any of thy vows which thou vowest, nor thy freewill offerings, or heave offering of thine hand:', 'thou mayest not eat within thy gates the tithe of thy corn or of thy wine or of thy oil or the firstlings of thy herds or of thy flock nor any of thy vows which thou vowest nor thy freewill offerings or heave offering of thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 18, 'But thou must eat them before the LORD thy God in the place which the LORD thy God shall choose, thou, and thy son, and thy daughter, and thy manservant, and thy maidservant, and the Levite that {is} within thy gates: and thou shalt rejoice before the LORD thy God in all that thou puttest thine hands unto.', 'but thou must eat them before the lord thy god in the place which the lord thy god shall choose thou and thy son and thy daughter and thy manservant and thy maidservant and the levite that is within thy gates and thou shalt rejoice before the lord thy god in all that thou puttest thine hands unto');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 19, 'Take heed to thyself that thou forsake not the Levite as long as thou livest upon the earth. {as long...: Heb. all thy days}', 'take heed to thyself that thou forsake not the levite as long as thou livest upon the earth as long heb all thy days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 20, 'When the LORD thy God shall enlarge thy border, as he hath promised thee, and thou shalt say, I will eat flesh, because thy soul longeth to eat flesh; thou mayest eat flesh, whatsoever thy soul lusteth after.', 'when the lord thy god shall enlarge thy border as he hath promised thee and thou shalt say i will eat flesh because thy soul longeth to eat flesh thou mayest eat flesh whatsoever thy soul lusteth after');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 21, 'If the place which the LORD thy God hath chosen to put his name there be too far from thee, then thou shalt kill of thy herd and of thy flock, which the LORD hath given thee, as I have commanded thee, and thou shalt eat in thy gates whatsoever thy soul lusteth after.', 'if the place which the lord thy god hath chosen to put his name there be too far from thee then thou shalt kill of thy herd and of thy flock which the lord hath given thee as i have commanded thee and thou shalt eat in thy gates whatsoever thy soul lusteth after');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 22, 'Even as the roebuck and the hart is eaten, so thou shalt eat them: the unclean and the clean shall eat {of} them alike.', 'even as the roebuck and the hart is eaten so thou shalt eat them the unclean and the clean shall eat of them alike');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 23, 'Only be sure that thou eat not the blood: for the blood {is} the life; and thou mayest not eat the life with the flesh. {be...: Heb. be strong}', 'only be sure that thou eat not the blood for the blood is the life and thou mayest not eat the life with the flesh be heb be strong');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 24, 'Thou shalt not eat it; thou shalt pour it upon the earth as water.', 'thou shalt not eat it thou shalt pour it upon the earth as water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 25, 'Thou shalt not eat it; that it may go well with thee, and with thy children after thee, when thou shalt do {that which is} right in the sight of the LORD.', 'thou shalt not eat it that it may go well with thee and with thy children after thee when thou shalt do that which is right in the sight of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 26, 'Only thy holy things which thou hast, and thy vows, thou shalt take, and go unto the place which the LORD shall choose:', 'only thy holy things which thou hast and thy vows thou shalt take and go unto the place which the lord shall choose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 27, 'And thou shalt offer thy burnt offerings, the flesh and the blood, upon the altar of the LORD thy God: and the blood of thy sacrifices shall be poured out upon the altar of the LORD thy God, and thou shalt eat the flesh.', 'and thou shalt offer thy burnt offerings the flesh and the blood upon the altar of the lord thy god and the blood of thy sacrifices shall be poured out upon the altar of the lord thy god and thou shalt eat the flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 28, 'Observe and hear all these words which I command thee, that it may go well with thee, and with thy children after thee for ever, when thou doest {that which is} good and right in the sight of the LORD thy God.', 'observe and hear all these words which i command thee that it may go well with thee and with thy children after thee for ever when thou doest that which is good and right in the sight of the lord thy god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 29, 'When the LORD thy God shall cut off the nations from before thee, whither thou goest to possess them, and thou succeedest them, and dwellest in their land; {succeedest...: Heb. inheritest, or, possessest them}', 'when the lord thy god shall cut off the nations from before thee whither thou goest to possess them and thou succeedest them and dwellest in their land succeedest heb inheritest or possessest them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 30, 'Take heed to thyself that thou be not snared by following them, after that they be destroyed from before thee; and that thou enquire not after their gods, saying, How did these nations serve their gods? even so will I do likewise. {by...: Heb. after them}', 'take heed to thyself that thou be not snared by following them after that they be destroyed from before thee and that thou enquire not after their gods saying how did these nations serve their gods even so will i do likewise by heb after them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 31, 'Thou shalt not do so unto the LORD thy God: for every abomination to the LORD, which he hateth, have they done unto their gods; for even their sons and their daughters they have burnt in the fire to their gods. {to the: Heb. of the}', 'thou shalt not do so unto the lord thy god for every abomination to the lord which he hateth have they done unto their gods for even their sons and their daughters they have burnt in the fire to their gods to the heb of the');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 12, 32, 'What thing soever I command you, observe to do it: thou shalt not add thereto, nor diminish from it.', 'what thing soever i command you observe to do it thou shalt not add thereto nor diminish from it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 1, 'If there arise among you a prophet, or a dreamer of dreams, and giveth thee a sign or a wonder,', 'if there arise among you a prophet or a dreamer of dreams and giveth thee a sign or a wonder');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 2, 'And the sign or the wonder come to pass, whereof he spake unto thee, saying, Let us go after other gods, which thou hast not known, and let us serve them;', 'and the sign or the wonder come to pass whereof he spake unto thee saying let us go after other gods which thou hast not known and let us serve them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 3, 'Thou shalt not hearken unto the words of that prophet, or that dreamer of dreams: for the LORD your God proveth you, to know whether ye love the LORD your God with all your heart and with all your soul.', 'thou shalt not hearken unto the words of that prophet or that dreamer of dreams for the lord your god proveth you to know whether ye love the lord your god with all your heart and with all your soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 4, 'Ye shall walk after the LORD your God, and fear him, and keep his commandments, and obey his voice, and ye shall serve him, and cleave unto him.', 'ye shall walk after the lord your god and fear him and keep his commandments and obey his voice and ye shall serve him and cleave unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 5, 'And that prophet, or that dreamer of dreams, shall be put to death; because he hath spoken to turn {you} away from the LORD your God, which brought you out of the land of Egypt, and redeemed you out of the house of bondage, to thrust thee out of the way which the LORD thy God commanded thee to walk in. So shalt thou put the evil away from the midst of thee. {to turn...: Heb. revolt against the LORD}', 'and that prophet or that dreamer of dreams shall be put to death because he hath spoken to turn you away from the lord your god which brought you out of the land of egypt and redeemed you out of the house of bondage to thrust thee out of the way which the lord thy god commanded thee to walk in so shalt thou put the evil away from the midst of thee to turn heb revolt against the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 6, 'If thy brother, the son of thy mother, or thy son, or thy daughter, or the wife of thy bosom, or thy friend, which {is} as thine own soul, entice thee secretly, saying, Let us go and serve other gods, which thou hast not known, thou, nor thy fathers;', 'if thy brother the son of thy mother or thy son or thy daughter or the wife of thy bosom or thy friend which is as thine own soul entice thee secretly saying let us go and serve other gods which thou hast not known thou nor thy fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 7, '{Namely}, of the gods of the people which {are} round about you, nigh unto thee, or far off from thee, from the {one} end of the earth even unto the {other} end of the earth;', 'namely of the gods of the people which are round about you nigh unto thee or far off from thee from the one end of the earth even unto the other end of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 8, 'Thou shalt not consent unto him, nor hearken unto him; neither shall thine eye pity him, neither shalt thou spare, neither shalt thou conceal him:', 'thou shalt not consent unto him nor hearken unto him neither shall thine eye pity him neither shalt thou spare neither shalt thou conceal him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 9, 'But thou shalt surely kill him; thine hand shall be first upon him to put him to death, and afterwards the hand of all the people.', 'but thou shalt surely kill him thine hand shall be first upon him to put him to death and afterwards the hand of all the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 10, 'And thou shalt stone him with stones, that he die; because he hath sought to thrust thee away from the LORD thy God, which brought thee out of the land of Egypt, from the house of bondage. {bondage: Heb. bondmen}', 'and thou shalt stone him with stones that he die because he hath sought to thrust thee away from the lord thy god which brought thee out of the land of egypt from the house of bondage bondage heb bondmen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 11, 'And all Israel shall hear, and fear, and shall do no more any such wickedness as this is among you.', 'and all israel shall hear and fear and shall do no more any such wickedness as this is among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 12, 'If thou shalt hear {say} in one of thy cities, which the LORD thy God hath given thee to dwell there, saying,', 'if thou shalt hear say in one of thy cities which the lord thy god hath given thee to dwell there saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 13, '{Certain} men, the children of Belial, are gone out from among you, and have withdrawn the inhabitants of their city, saying, Let us go and serve other gods, which ye have not known; {the children...: or, naughty men}', 'certain men the children of belial are gone out from among you and have withdrawn the inhabitants of their city saying let us go and serve other gods which ye have not known the children or naughty men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 14, 'Then shalt thou enquire, and make search, and ask diligently; and, behold, {if it be} truth, {and} the thing certain, {that} such abomination is wrought among you;', 'then shalt thou enquire and make search and ask diligently and behold if it be truth and the thing certain that such abomination is wrought among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 15, 'Thou shalt surely smite the inhabitants of that city with the edge of the sword, destroying it utterly, and all that {is} therein, and the cattle thereof, with the edge of the sword.', 'thou shalt surely smite the inhabitants of that city with the edge of the sword destroying it utterly and all that is therein and the cattle thereof with the edge of the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 16, 'And thou shalt gather all the spoil of it into the midst of the street thereof, and shalt burn with fire the city, and all the spoil thereof every whit, for the LORD thy God: and it shall be an heap for ever; it shall not be built again.', 'and thou shalt gather all the spoil of it into the midst of the street thereof and shalt burn with fire the city and all the spoil thereof every whit for the lord thy god and it shall be an heap for ever it shall not be built again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 17, 'And there shall cleave nought of the cursed thing to thine hand: that the LORD may turn from the fierceness of his anger, and shew thee mercy, and have compassion upon thee, and multiply thee, as he hath sworn unto thy fathers; {cursed: or, devoted}', 'and there shall cleave nought of the cursed thing to thine hand that the lord may turn from the fierceness of his anger and shew thee mercy and have compassion upon thee and multiply thee as he hath sworn unto thy fathers cursed or devoted');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 13, 18, 'When thou shalt hearken to the voice of the LORD thy God, to keep all his commandments which I command thee this day, to do {that which is} right in the eyes of the LORD thy God.', 'when thou shalt hearken to the voice of the lord thy god to keep all his commandments which i command thee this day to do that which is right in the eyes of the lord thy god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 1, 'Ye {are} the children of the LORD your God: ye shall not cut yourselves, nor make any baldness between your eyes for the dead.', 'ye are the children of the lord your god ye shall not cut yourselves nor make any baldness between your eyes for the dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 2, 'For thou {art} an holy people unto the LORD thy God, and the LORD hath chosen thee to be a peculiar people unto himself, above all the nations that {are} upon the earth.', 'for thou art an holy people unto the lord thy god and the lord hath chosen thee to be a peculiar people unto himself above all the nations that are upon the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 3, 'Thou shalt not eat any abominable thing.', 'thou shalt not eat any abominable thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 4, 'These {are} the beasts which ye shall eat: the ox, the sheep, and the goat,', 'these are the beasts which ye shall eat the ox the sheep and the goat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 5, 'The hart, and the roebuck, and the fallow deer, and the wild goat, and the pygarg, and the wild ox, and the chamois. {pygarg: or bison: Heb. dishon}', 'the hart and the roebuck and the fallow deer and the wild goat and the pygarg and the wild ox and the chamois pygarg or bison heb dishon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 6, 'And every beast that parteth the hoof, and cleaveth the cleft into two claws, {and} cheweth the cud among the beasts, that ye shall eat.', 'and every beast that parteth the hoof and cleaveth the cleft into two claws and cheweth the cud among the beasts that ye shall eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 7, 'Nevertheless these ye shall not eat of them that chew the cud, or of them that divide the cloven hoof; {as} the camel, and the hare, and the coney: for they chew the cud, but divide not the hoof; {therefore} they {are} unclean unto you.', 'nevertheless these ye shall not eat of them that chew the cud or of them that divide the cloven hoof as the camel and the hare and the coney for they chew the cud but divide not the hoof therefore they are unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 8, 'And the swine, because it divideth the hoof, yet cheweth not the cud, it {is} unclean unto you: ye shall not eat of their flesh, nor touch their dead carcase.', 'and the swine because it divideth the hoof yet cheweth not the cud it is unclean unto you ye shall not eat of their flesh nor touch their dead carcase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 9, 'These ye shall eat of all that {are} in the waters: all that have fins and scales shall ye eat:', 'these ye shall eat of all that are in the waters all that have fins and scales shall ye eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 10, 'And whatsoever hath not fins and scales ye may not eat; it {is} unclean unto you.', 'and whatsoever hath not fins and scales ye may not eat it is unclean unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 11, '{Of} all clean birds ye shall eat.', 'of all clean birds ye shall eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 12, 'But these {are they} of which ye shall not eat: the eagle, and the ossifrage, and the ospray,', 'but these are they of which ye shall not eat the eagle and the ossifrage and the ospray');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 13, 'And the glede, and the kite, and the vulture after his kind,', 'and the glede and the kite and the vulture after his kind');
