INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 15, 'And the owl, and the night hawk, and the cuckow, and the hawk after his kind,', 'and the owl and the night hawk and the cuckow and the hawk after his kind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 16, 'The little owl, and the great owl, and the swan,', 'the little owl and the great owl and the swan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 17, 'And the pelican, and the gier eagle, and the cormorant,', 'and the pelican and the gier eagle and the cormorant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 18, 'And the stork, and the heron after her kind, and the lapwing, and the bat.', 'and the stork and the heron after her kind and the lapwing and the bat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 19, 'And every creeping thing that flieth {is} unclean unto you: they shall not be eaten.', 'and every creeping thing that flieth is unclean unto you they shall not be eaten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 20, '{But of} all clean fowls ye may eat.', 'but of all clean fowls ye may eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 21, 'Ye shall not eat {of} any thing that dieth of itself: thou shalt give it unto the stranger that {is} in thy gates, that he may eat it; or thou mayest sell it unto an alien: for thou {art} an holy people unto the LORD thy God. Thou shalt not seethe a kid in his mother''s milk.', 'ye shall not eat of any thing that dieth of itself thou shalt give it unto the stranger that is in thy gates that he may eat it or thou mayest sell it unto an alien for thou art an holy people unto the lord thy god thou shalt not seethe a kid in his mother s milk');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 22, 'Thou shalt truly tithe all the increase of thy seed, that the field bringeth forth year by year.', 'thou shalt truly tithe all the increase of thy seed that the field bringeth forth year by year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 23, 'And thou shalt eat before the LORD thy God, in the place which he shall choose to place his name there, the tithe of thy corn, of thy wine, and of thine oil, and the firstlings of thy herds and of thy flocks; that thou mayest learn to fear the LORD thy God always.', 'and thou shalt eat before the lord thy god in the place which he shall choose to place his name there the tithe of thy corn of thy wine and of thine oil and the firstlings of thy herds and of thy flocks that thou mayest learn to fear the lord thy god always');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 24, 'And if the way be too long for thee, so that thou art not able to carry it; {or} if the place be too far from thee, which the LORD thy God shall choose to set his name there, when the LORD thy God hath blessed thee:', 'and if the way be too long for thee so that thou art not able to carry it or if the place be too far from thee which the lord thy god shall choose to set his name there when the lord thy god hath blessed thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 25, 'Then shalt thou turn {it} into money, and bind up the money in thine hand, and shalt go unto the place which the LORD thy God shall choose:', 'then shalt thou turn it into money and bind up the money in thine hand and shalt go unto the place which the lord thy god shall choose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 26, 'And thou shalt bestow that money for whatsoever thy soul lusteth after, for oxen, or for sheep, or for wine, or for strong drink, or for whatsoever thy soul desireth: and thou shalt eat there before the LORD thy God, and thou shalt rejoice, thou, and thine household, {desireth: Heb. asketh of thee}', 'and thou shalt bestow that money for whatsoever thy soul lusteth after for oxen or for sheep or for wine or for strong drink or for whatsoever thy soul desireth and thou shalt eat there before the lord thy god and thou shalt rejoice thou and thine household desireth heb asketh of thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 27, 'And the Levite that {is} within thy gates; thou shalt not forsake him; for he hath no part nor inheritance with thee.', 'and the levite that is within thy gates thou shalt not forsake him for he hath no part nor inheritance with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 28, 'At the end of three years thou shalt bring forth all the tithe of thine increase the same year, and shalt lay {it} up within thy gates:', 'at the end of three years thou shalt bring forth all the tithe of thine increase the same year and shalt lay it up within thy gates');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 14, 29, 'And the Levite, (because he hath no part nor inheritance with thee,) and the stranger, and the fatherless, and the widow, which {are} within thy gates, shall come, and shall eat and be satisfied; that the LORD thy God may bless thee in all the work of thine hand which thou doest.', 'and the levite because he hath no part nor inheritance with thee and the stranger and the fatherless and the widow which are within thy gates shall come and shall eat and be satisfied that the lord thy god may bless thee in all the work of thine hand which thou doest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 1, 'At the end of {every} seven years thou shalt make a release.', 'at the end of every seven years thou shalt make a release');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 2, 'And this {is} the manner of the release: Every creditor that lendeth {ought} unto his neighbour shall release {it}; he shall not exact {it} of his neighbour, or of his brother; because it is called the LORD''S release. {creditor: Heb. master of the lending of his hand}', 'and this is the manner of the release every creditor that lendeth ought unto his neighbour shall release it he shall not exact it of his neighbour or of his brother because it is called the lord s release creditor heb master of the lending of his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 3, 'Of a foreigner thou mayest exact {it again}: but {that} which is thine with thy brother thine hand shall release;', 'of a foreigner thou mayest exact it again but that which is thine with thy brother thine hand shall release');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 4, 'Save when there shall be no poor among you; for the LORD shall greatly bless thee in the land which the LORD thy God giveth thee {for} an inheritance to possess it: {Save...: or, To the end that there be no poor among you}', 'save when there shall be no poor among you for the lord shall greatly bless thee in the land which the lord thy god giveth thee for an inheritance to possess it save or to the end that there be no poor among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 5, 'Only if thou carefully hearken unto the voice of the LORD thy God, to observe to do all these commandments which I command thee this day.', 'only if thou carefully hearken unto the voice of the lord thy god to observe to do all these commandments which i command thee this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 6, 'For the LORD thy God blesseth thee, as he promised thee: and thou shalt lend unto many nations, but thou shalt not borrow; and thou shalt reign over many nations, but they shall not reign over thee.', 'for the lord thy god blesseth thee as he promised thee and thou shalt lend unto many nations but thou shalt not borrow and thou shalt reign over many nations but they shall not reign over thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 7, 'If there be among you a poor man of one of thy brethren within any of thy gates in thy land which the LORD thy God giveth thee, thou shalt not harden thine heart, nor shut thine hand from thy poor brother:', 'if there be among you a poor man of one of thy brethren within any of thy gates in thy land which the lord thy god giveth thee thou shalt not harden thine heart nor shut thine hand from thy poor brother');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 8, 'But thou shalt open thine hand wide unto him, and shalt surely lend him sufficient for his need, {in that} which he wanteth.', 'but thou shalt open thine hand wide unto him and shalt surely lend him sufficient for his need in that which he wanteth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 9, 'Beware that there be not a thought in thy wicked heart, saying, The seventh year, the year of release, is at hand; and thine eye be evil against thy poor brother, and thou givest him nought; and he cry unto the LORD against thee, and it be sin unto thee. {thought: Heb. word} {wicked: Heb. Belial}', 'beware that there be not a thought in thy wicked heart saying the seventh year the year of release is at hand and thine eye be evil against thy poor brother and thou givest him nought and he cry unto the lord against thee and it be sin unto thee thought heb word wicked heb belial');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 10, 'Thou shalt surely give him, and thine heart shall not be grieved when thou givest unto him: because that for this thing the LORD thy God shall bless thee in all thy works, and in all that thou puttest thine hand unto.', 'thou shalt surely give him and thine heart shall not be grieved when thou givest unto him because that for this thing the lord thy god shall bless thee in all thy works and in all that thou puttest thine hand unto');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 11, 'For the poor shall never cease out of the land: therefore I command thee, saying, Thou shalt open thine hand wide unto thy brother, to thy poor, and to thy needy, in thy land.', 'for the poor shall never cease out of the land therefore i command thee saying thou shalt open thine hand wide unto thy brother to thy poor and to thy needy in thy land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 12, '{And} if thy brother, an Hebrew man, or an Hebrew woman, be sold unto thee, and serve thee six years; then in the seventh year thou shalt let him go free from thee.', 'and if thy brother an hebrew man or an hebrew woman be sold unto thee and serve thee six years then in the seventh year thou shalt let him go free from thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 13, 'And when thou sendest him out free from thee, thou shalt not let him go away empty:', 'and when thou sendest him out free from thee thou shalt not let him go away empty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 14, 'Thou shalt furnish him liberally out of thy flock, and out of thy floor, and out of thy winepress: {of that} wherewith the LORD thy God hath blessed thee thou shalt give unto him.', 'thou shalt furnish him liberally out of thy flock and out of thy floor and out of thy winepress of that wherewith the lord thy god hath blessed thee thou shalt give unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 15, 'And thou shalt remember that thou wast a bondman in the land of Egypt, and the LORD thy God redeemed thee: therefore I command thee this thing to day.', 'and thou shalt remember that thou wast a bondman in the land of egypt and the lord thy god redeemed thee therefore i command thee this thing to day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 16, 'And it shall be, if he say unto thee, I will not go away from thee; because he loveth thee and thine house, because he is well with thee;', 'and it shall be if he say unto thee i will not go away from thee because he loveth thee and thine house because he is well with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 17, 'Then thou shalt take an aul, and thrust {it} through his ear unto the door, and he shall be thy servant for ever. And also unto thy maidservant thou shalt do likewise.', 'then thou shalt take an aul and thrust it through his ear unto the door and he shall be thy servant for ever and also unto thy maidservant thou shalt do likewise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 18, 'It shall not seem hard unto thee, when thou sendest him away free from thee; for he hath been worth a double hired servant {to thee}, in serving thee six years: and the LORD thy God shall bless thee in all that thou doest.', 'it shall not seem hard unto thee when thou sendest him away free from thee for he hath been worth a double hired servant to thee in serving thee six years and the lord thy god shall bless thee in all that thou doest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 19, 'All the firstling males that come of thy herd and of thy flock thou shalt sanctify unto the LORD thy God: thou shalt do no work with the firstling of thy bullock, nor shear the firstling of thy sheep.', 'all the firstling males that come of thy herd and of thy flock thou shalt sanctify unto the lord thy god thou shalt do no work with the firstling of thy bullock nor shear the firstling of thy sheep');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 20, 'Thou shalt eat {it} before the LORD thy God year by year in the place which the LORD shall choose, thou and thy household.', 'thou shalt eat it before the lord thy god year by year in the place which the lord shall choose thou and thy household');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 21, 'And if there be {any} blemish therein, {as if it be} lame, or blind, {or have} any ill blemish, thou shalt not sacrifice it unto the LORD thy God.', 'and if there be any blemish therein as if it be lame or blind or have any ill blemish thou shalt not sacrifice it unto the lord thy god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 22, 'Thou shalt eat it within thy gates: the unclean and the clean {person shall eat it} alike, as the roebuck, and as the hart.', 'thou shalt eat it within thy gates the unclean and the clean person shall eat it alike as the roebuck and as the hart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 15, 23, 'Only thou shalt not eat the blood thereof; thou shalt pour it upon the ground as water.', 'only thou shalt not eat the blood thereof thou shalt pour it upon the ground as water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 1, 'Observe the month of Abib, and keep the passover unto the LORD thy God: for in the month of Abib the LORD thy God brought thee forth out of Egypt by night.', 'observe the month of abib and keep the passover unto the lord thy god for in the month of abib the lord thy god brought thee forth out of egypt by night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 2, 'Thou shalt therefore sacrifice the passover unto the LORD thy God, of the flock and the herd, in the place which the LORD shall choose to place his name there.', 'thou shalt therefore sacrifice the passover unto the lord thy god of the flock and the herd in the place which the lord shall choose to place his name there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 3, 'Thou shalt eat no leavened bread with it; seven days shalt thou eat unleavened bread therewith, {even} the bread of affliction; for thou camest forth out of the land of Egypt in haste: that thou mayest remember the day when thou camest forth out of the land of Egypt all the days of thy life.', 'thou shalt eat no leavened bread with it seven days shalt thou eat unleavened bread therewith even the bread of affliction for thou camest forth out of the land of egypt in haste that thou mayest remember the day when thou camest forth out of the land of egypt all the days of thy life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 4, 'And there shall be no leavened bread seen with thee in all thy coast seven days; neither shall there {any thing} of the flesh, which thou sacrificedst the first day at even, remain all night until the morning.', 'and there shall be no leavened bread seen with thee in all thy coast seven days neither shall there any thing of the flesh which thou sacrificedst the first day at even remain all night until the morning');
