INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 7, 'And thou shalt roast and eat {it} in the place which the LORD thy God shall choose: and thou shalt turn in the morning, and go unto thy tents.', 'and thou shalt roast and eat it in the place which the lord thy god shall choose and thou shalt turn in the morning and go unto thy tents');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 8, 'Six days thou shalt eat unleavened bread: and on the seventh day {shall be} a solemn assembly to the LORD thy God: thou shalt do no work {therein}. {solemn...: Heb. restraint}', 'six days thou shalt eat unleavened bread and on the seventh day shall be a solemn assembly to the lord thy god thou shalt do no work therein solemn heb restraint');
