INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 15, 'Seven days shalt thou keep a solemn feast unto the LORD thy God in the place which the LORD shall choose: because the LORD thy God shall bless thee in all thine increase, and in all the works of thine hands, therefore thou shalt surely rejoice.', 'seven days shalt thou keep a solemn feast unto the lord thy god in the place which the lord shall choose because the lord thy god shall bless thee in all thine increase and in all the works of thine hands therefore thou shalt surely rejoice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 16, 'Three times in a year shall all thy males appear before the LORD thy God in the place which he shall choose; in the feast of unleavened bread, and in the feast of weeks, and in the feast of tabernacles: and they shall not appear before the LORD empty:', 'three times in a year shall all thy males appear before the lord thy god in the place which he shall choose in the feast of unleavened bread and in the feast of weeks and in the feast of tabernacles and they shall not appear before the lord empty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 17, 'Every man {shall give} as he is able, according to the blessing of the LORD thy God which he hath given thee. {as...: Heb. according to the gift of his hand}', 'every man shall give as he is able according to the blessing of the lord thy god which he hath given thee as heb according to the gift of his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 18, 'Judges and officers shalt thou make thee in all thy gates, which the LORD thy God giveth thee, throughout thy tribes: and they shall judge the people with just judgment.', 'judges and officers shalt thou make thee in all thy gates which the lord thy god giveth thee throughout thy tribes and they shall judge the people with just judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 19, 'Thou shalt not wrest judgment; thou shalt not respect persons, neither take a gift: for a gift doth blind the eyes of the wise, and pervert the words of the righteous. {words: or, matters}', 'thou shalt not wrest judgment thou shalt not respect persons neither take a gift for a gift doth blind the eyes of the wise and pervert the words of the righteous words or matters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 20, 'That which is altogether just shalt thou follow, that thou mayest live, and inherit the land which the LORD thy God giveth thee. {That which...: Heb. Justice, justice}', 'that which is altogether just shalt thou follow that thou mayest live and inherit the land which the lord thy god giveth thee that which heb justice justice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 21, 'Thou shalt not plant thee a grove of any trees near unto the altar of the LORD thy God, which thou shalt make thee.', 'thou shalt not plant thee a grove of any trees near unto the altar of the lord thy god which thou shalt make thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 16, 22, 'Neither shalt thou set thee up {any} image; which the LORD thy God hateth. {image: or, statue, or, pillar}', 'neither shalt thou set thee up any image which the lord thy god hateth image or statue or pillar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 1, 'Thou shalt not sacrifice unto the LORD thy God {any} bullock, or sheep, wherein is blemish, {or} any evilfavouredness: for that {is} an abomination unto the LORD thy God. {sheep: or, goat}', 'thou shalt not sacrifice unto the lord thy god any bullock or sheep wherein is blemish or any evilfavouredness for that is an abomination unto the lord thy god sheep or goat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 2, 'If there be found among you, within any of thy gates which the LORD thy God giveth thee, man or woman, that hath wrought wickedness in the sight of the LORD thy God, in transgressing his covenant,', 'if there be found among you within any of thy gates which the lord thy god giveth thee man or woman that hath wrought wickedness in the sight of the lord thy god in transgressing his covenant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 3, 'And hath gone and served other gods, and worshipped them, either the sun, or moon, or any of the host of heaven, which I have not commanded;', 'and hath gone and served other gods and worshipped them either the sun or moon or any of the host of heaven which i have not commanded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 4, 'And it be told thee, and thou hast heard {of it}, and enquired diligently, and, behold, {it be} true, {and} the thing certain, {that} such abomination is wrought in Israel:', 'and it be told thee and thou hast heard of it and enquired diligently and behold it be true and the thing certain that such abomination is wrought in israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 5, 'Then shalt thou bring forth that man or that woman, which have committed that wicked thing, unto thy gates, {even} that man or that woman, and shalt stone them with stones, till they die.', 'then shalt thou bring forth that man or that woman which have committed that wicked thing unto thy gates even that man or that woman and shalt stone them with stones till they die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 6, 'At the mouth of two witnesses, or three witnesses, shall he that is worthy of death be put to death; {but} at the mouth of one witness he shall not be put to death.', 'at the mouth of two witnesses or three witnesses shall he that is worthy of death be put to death but at the mouth of one witness he shall not be put to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 7, 'The hands of the witnesses shall be first upon him to put him to death, and afterward the hands of all the people. So thou shalt put the evil away from among you.', 'the hands of the witnesses shall be first upon him to put him to death and afterward the hands of all the people so thou shalt put the evil away from among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 8, 'If there arise a matter too hard for thee in judgment, between blood and blood, between plea and plea, and between stroke and stroke, {being} matters of controversy within thy gates: then shalt thou arise, and get thee up into the place which the LORD thy God shall choose;', 'if there arise a matter too hard for thee in judgment between blood and blood between plea and plea and between stroke and stroke being matters of controversy within thy gates then shalt thou arise and get thee up into the place which the lord thy god shall choose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 9, 'And thou shalt come unto the priests the Levites, and unto the judge that shall be in those days, and enquire; and they shall shew thee the sentence of judgment:', 'and thou shalt come unto the priests the levites and unto the judge that shall be in those days and enquire and they shall shew thee the sentence of judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 10, 'And thou shalt do according to the sentence, which they of that place which the LORD shall choose shall shew thee; and thou shalt observe to do according to all that they inform thee:', 'and thou shalt do according to the sentence which they of that place which the lord shall choose shall shew thee and thou shalt observe to do according to all that they inform thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 11, 'According to the sentence of the law which they shall teach thee, and according to the judgment which they shall tell thee, thou shalt do: thou shalt not decline from the sentence which they shall shew thee, {to} the right hand, nor {to} the left.', 'according to the sentence of the law which they shall teach thee and according to the judgment which they shall tell thee thou shalt do thou shalt not decline from the sentence which they shall shew thee to the right hand nor to the left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 12, 'And the man that will do presumptuously, and will not hearken unto the priest that standeth to minister there before the LORD thy God, or unto the judge, even that man shall die: and thou shalt put away the evil from Israel. {and will...: Heb. not to hearken}', 'and the man that will do presumptuously and will not hearken unto the priest that standeth to minister there before the lord thy god or unto the judge even that man shall die and thou shalt put away the evil from israel and will heb not to hearken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 13, 'And all the people shall hear, and fear, and do no more presumptuously.', 'and all the people shall hear and fear and do no more presumptuously');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 14, 'When thou art come unto the land which the LORD thy God giveth thee, and shalt possess it, and shalt dwell therein, and shalt say, I will set a king over me, like as all the nations that {are} about me;', 'when thou art come unto the land which the lord thy god giveth thee and shalt possess it and shalt dwell therein and shalt say i will set a king over me like as all the nations that are about me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 15, 'Thou shalt in any wise set {him} king over thee, whom the LORD thy God shall choose: {one} from among thy brethren shalt thou set king over thee: thou mayest not set a stranger over thee, which {is} not thy brother.', 'thou shalt in any wise set him king over thee whom the lord thy god shall choose one from among thy brethren shalt thou set king over thee thou mayest not set a stranger over thee which is not thy brother');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 16, 'But he shall not multiply horses to himself, nor cause the people to return to Egypt, to the end that he should multiply horses: forasmuch as the LORD hath said unto you, Ye shall henceforth return no more that way.', 'but he shall not multiply horses to himself nor cause the people to return to egypt to the end that he should multiply horses forasmuch as the lord hath said unto you ye shall henceforth return no more that way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 17, 'Neither shall he multiply wives to himself, that his heart turn not away: neither shall he greatly multiply to himself silver and gold.', 'neither shall he multiply wives to himself that his heart turn not away neither shall he greatly multiply to himself silver and gold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 18, 'And it shall be, when he sitteth upon the throne of his kingdom, that he shall write him a copy of this law in a book out of {that which is} before the priests the Levites:', 'and it shall be when he sitteth upon the throne of his kingdom that he shall write him a copy of this law in a book out of that which is before the priests the levites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 19, 'And it shall be with him, and he shall read therein all the days of his life: that he may learn to fear the LORD his God, to keep all the words of this law and these statutes, to do them:', 'and it shall be with him and he shall read therein all the days of his life that he may learn to fear the lord his god to keep all the words of this law and these statutes to do them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 17, 20, 'That his heart be not lifted up above his brethren, and that he turn not aside from the commandment, {to} the right hand, or {to} the left: to the end that he may prolong {his} days in his kingdom, he, and his children, in the midst of Israel.', 'that his heart be not lifted up above his brethren and that he turn not aside from the commandment to the right hand or to the left to the end that he may prolong his days in his kingdom he and his children in the midst of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 1, 'The priests the Levites, {and} all the tribe of Levi, shall have no part nor inheritance with Israel: they shall eat the offerings of the LORD made by fire, and his inheritance.', 'the priests the levites and all the tribe of levi shall have no part nor inheritance with israel they shall eat the offerings of the lord made by fire and his inheritance');
