INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 3, 'And this shall be the priest''s due from the people, from them that offer a sacrifice, whether {it be} ox or sheep; and they shall give unto the priest the shoulder, and the two cheeks, and the maw.', 'and this shall be the priest s due from the people from them that offer a sacrifice whether it be ox or sheep and they shall give unto the priest the shoulder and the two cheeks and the maw');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 4, 'The firstfruit {also} of thy corn, of thy wine, and of thine oil, and the first of the fleece of thy sheep, shalt thou give him.', 'the firstfruit also of thy corn of thy wine and of thine oil and the first of the fleece of thy sheep shalt thou give him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 5, 'For the LORD thy God hath chosen him out of all thy tribes, to stand to minister in the name of the LORD, him and his sons for ever.', 'for the lord thy god hath chosen him out of all thy tribes to stand to minister in the name of the lord him and his sons for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 6, 'And if a Levite come from any of thy gates out of all Israel, where he sojourned, and come with all the desire of his mind unto the place which the LORD shall choose;', 'and if a levite come from any of thy gates out of all israel where he sojourned and come with all the desire of his mind unto the place which the lord shall choose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 7, 'Then he shall minister in the name of the LORD his God, as all his brethren the Levites {do}, which stand there before the LORD.', 'then he shall minister in the name of the lord his god as all his brethren the levites do which stand there before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 8, 'They shall have like portions to eat, beside that which cometh of the sale of his patrimony. {that...: Heb. his sale by the fathers}', 'they shall have like portions to eat beside that which cometh of the sale of his patrimony that heb his sale by the fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 9, 'When thou art come into the land which the LORD thy God giveth thee, thou shalt not learn to do after the abominations of those nations.', 'when thou art come into the land which the lord thy god giveth thee thou shalt not learn to do after the abominations of those nations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 10, 'There shall not be found among you {any one} that maketh his son or his daughter to pass through the fire, {or} that useth divination, {or} an observer of times, or an enchanter, or a witch,', 'there shall not be found among you any one that maketh his son or his daughter to pass through the fire or that useth divination or an observer of times or an enchanter or a witch');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 11, 'Or a charmer, or a consulter with familiar spirits, or a wizard, or a necromancer.', 'or a charmer or a consulter with familiar spirits or a wizard or a necromancer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 12, 'For all that do these things {are} an abomination unto the LORD: and because of these abominations the LORD thy God doth drive them out from before thee.', 'for all that do these things are an abomination unto the lord and because of these abominations the lord thy god doth drive them out from before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 13, 'Thou shalt be perfect with the LORD thy God. {perfect: or, upright, or, sincere}', 'thou shalt be perfect with the lord thy god perfect or upright or sincere');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 14, 'For these nations, which thou shalt possess, hearkened unto observers of times, and unto diviners: but as for thee, the LORD thy God hath not suffered thee so {to do}. {possess: or, inherit}', 'for these nations which thou shalt possess hearkened unto observers of times and unto diviners but as for thee the lord thy god hath not suffered thee so to do possess or inherit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 15, 'The LORD thy God will raise up unto thee a Prophet from the midst of thee, of thy brethren, like unto me; unto him ye shall hearken;', 'the lord thy god will raise up unto thee a prophet from the midst of thee of thy brethren like unto me unto him ye shall hearken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 16, 'According to all that thou desiredst of the LORD thy God in Horeb in the day of the assembly, saying, Let me not hear again the voice of the LORD my God, neither let me see this great fire any more, that I die not.', 'according to all that thou desiredst of the lord thy god in horeb in the day of the assembly saying let me not hear again the voice of the lord my god neither let me see this great fire any more that i die not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 18, 17, 'And the LORD said unto me, They have well {spoken that} which they have spoken.', 'and the lord said unto me they have well spoken that which they have spoken');
