INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 22, 17, 'And, lo, he hath given occasions of speech {against her}, saying, I found not thy daughter a maid; and yet these {are the tokens of} my daughter''s virginity. And they shall spread the cloth before the elders of the city.', 'and lo he hath given occasions of speech against her saying i found not thy daughter a maid and yet these are the tokens of my daughter s virginity and they shall spread the cloth before the elders of the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 22, 18, 'And the elders of that city shall take that man and chastise him;', 'and the elders of that city shall take that man and chastise him');
