INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 3, 'An Ammonite or Moabite shall not enter into the congregation of the LORD; even to their tenth generation shall they not enter into the congregation of the LORD for ever:', 'an ammonite or moabite shall not enter into the congregation of the lord even to their tenth generation shall they not enter into the congregation of the lord for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 4, 'Because they met you not with bread and with water in the way, when ye came forth out of Egypt; and because they hired against thee Balaam the son of Beor of Pethor of Mesopotamia, to curse thee.', 'because they met you not with bread and with water in the way when ye came forth out of egypt and because they hired against thee balaam the son of beor of pethor of mesopotamia to curse thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 5, 'Nevertheless the LORD thy God would not hearken unto Balaam; but the LORD thy God turned the curse into a blessing unto thee, because the LORD thy God loved thee.', 'nevertheless the lord thy god would not hearken unto balaam but the lord thy god turned the curse into a blessing unto thee because the lord thy god loved thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 6, 'Thou shalt not seek their peace nor their prosperity all thy days for ever. {prosperity: Heb. good}', 'thou shalt not seek their peace nor their prosperity all thy days for ever prosperity heb good');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 7, 'Thou shalt not abhor an Edomite; for he {is} thy brother: thou shalt not abhor an Egyptian; because thou wast a stranger in his land.', 'thou shalt not abhor an edomite for he is thy brother thou shalt not abhor an egyptian because thou wast a stranger in his land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 8, 'The children that are begotten of them shall enter into the congregation of the LORD in their third generation.', 'the children that are begotten of them shall enter into the congregation of the lord in their third generation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 9, 'When the host goeth forth against thine enemies, then keep thee from every wicked thing.', 'when the host goeth forth against thine enemies then keep thee from every wicked thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 10, 'If there be among you any man, that is not clean by reason of uncleanness that chanceth him by night, then shall he go abroad out of the camp, he shall not come within the camp:', 'if there be among you any man that is not clean by reason of uncleanness that chanceth him by night then shall he go abroad out of the camp he shall not come within the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 11, 'But it shall be, when evening cometh on, he shall wash {himself} with water: and when the sun is down, he shall come into the camp {again}. {cometh...: Heb. turneth toward}', 'but it shall be when evening cometh on he shall wash himself with water and when the sun is down he shall come into the camp again cometh heb turneth toward');
