INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 14, 'For the LORD thy God walketh in the midst of thy camp, to deliver thee, and to give up thine enemies before thee; therefore shall thy camp be holy: that he see no unclean thing in thee, and turn away from thee. {unclean...: Heb. nakedness of any thing}', 'for the lord thy god walketh in the midst of thy camp to deliver thee and to give up thine enemies before thee therefore shall thy camp be holy that he see no unclean thing in thee and turn away from thee unclean heb nakedness of any thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 23, 15, 'Thou shalt not deliver unto his master the servant which is escaped from his master unto thee:', 'thou shalt not deliver unto his master the servant which is escaped from his master unto thee');
