INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 14, 'But the word {is} very nigh unto thee, in thy mouth, and in thy heart, that thou mayest do it.', 'but the word is very nigh unto thee in thy mouth and in thy heart that thou mayest do it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 15, 'See, I have set before thee this day life and good, and death and evil;', 'see i have set before thee this day life and good and death and evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 16, 'In that I command thee this day to love the LORD thy God, to walk in his ways, and to keep his commandments and his statutes and his judgments, that thou mayest live and multiply: and the LORD thy God shall bless thee in the land whither thou goest to possess it.', 'in that i command thee this day to love the lord thy god to walk in his ways and to keep his commandments and his statutes and his judgments that thou mayest live and multiply and the lord thy god shall bless thee in the land whither thou goest to possess it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 17, 'But if thine heart turn away, so that thou wilt not hear, but shalt be drawn away, and worship other gods, and serve them;', 'but if thine heart turn away so that thou wilt not hear but shalt be drawn away and worship other gods and serve them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 18, 'I denounce unto you this day, that ye shall surely perish, {and that} ye shall not prolong {your} days upon the land, whither thou passest over Jordan to go to possess it.', 'i denounce unto you this day that ye shall surely perish and that ye shall not prolong your days upon the land whither thou passest over jordan to go to possess it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 19, 'I call heaven and earth to record this day against you, {that} I have set before you life and death, blessing and cursing: therefore choose life, that both thou and thy seed may live:', 'i call heaven and earth to record this day against you that i have set before you life and death blessing and cursing therefore choose life that both thou and thy seed may live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 30, 20, 'That thou mayest love the LORD thy God, {and} that thou mayest obey his voice, and that thou mayest cleave unto him: for he {is} thy life, and the length of thy days: that thou mayest dwell in the land which the LORD sware unto thy fathers, to Abraham, to Isaac, and to Jacob, to give them.', 'that thou mayest love the lord thy god and that thou mayest obey his voice and that thou mayest cleave unto him for he is thy life and the length of thy days that thou mayest dwell in the land which the lord sware unto thy fathers to abraham to isaac and to jacob to give them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 1, 'And Moses went and spake these words unto all Israel.', 'and moses went and spake these words unto all israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 2, 'And he said unto them, I {am} an hundred and twenty years old this day; I can no more go out and come in: also the LORD hath said unto me, Thou shalt not go over this Jordan.', 'and he said unto them i am an hundred and twenty years old this day i can no more go out and come in also the lord hath said unto me thou shalt not go over this jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 3, 'The LORD thy God, he will go over before thee, {and} he will destroy these nations from before thee, and thou shalt possess them: {and} Joshua, he shall go over before thee, as the LORD hath said.', 'the lord thy god he will go over before thee and he will destroy these nations from before thee and thou shalt possess them and joshua he shall go over before thee as the lord hath said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 4, 'And the LORD shall do unto them as he did to Sihon and to Og, kings of the Amorites, and unto the land of them, whom he destroyed.', 'and the lord shall do unto them as he did to sihon and to og kings of the amorites and unto the land of them whom he destroyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 5, 'And the LORD shall give them up before your face, that ye may do unto them according unto all the commandments which I have commanded you.', 'and the lord shall give them up before your face that ye may do unto them according unto all the commandments which i have commanded you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 6, 'Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he {it is} that doth go with thee; he will not fail thee, nor forsake thee.', 'be strong and of a good courage fear not nor be afraid of them for the lord thy god he it is that doth go with thee he will not fail thee nor forsake thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 7, 'And Moses called unto Joshua, and said unto him in the sight of all Israel, Be strong and of a good courage: for thou must go with this people unto the land which the LORD hath sworn unto their fathers to give them; and thou shalt cause them to inherit it.', 'and moses called unto joshua and said unto him in the sight of all israel be strong and of a good courage for thou must go with this people unto the land which the lord hath sworn unto their fathers to give them and thou shalt cause them to inherit it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 8, 'And the LORD, he {it is} that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.', 'and the lord he it is that doth go before thee he will be with thee he will not fail thee neither forsake thee fear not neither be dismayed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 9, 'And Moses wrote this law, and delivered it unto the priests the sons of Levi, which bare the ark of the covenant of the LORD, and unto all the elders of Israel.', 'and moses wrote this law and delivered it unto the priests the sons of levi which bare the ark of the covenant of the lord and unto all the elders of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 10, 'And Moses commanded them, saying, At the end of {every} seven years, in the solemnity of the year of release, in the feast of tabernacles,', 'and moses commanded them saying at the end of every seven years in the solemnity of the year of release in the feast of tabernacles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 11, 'When all Israel is come to appear before the LORD thy God in the place which he shall choose, thou shalt read this law before all Israel in their hearing.', 'when all israel is come to appear before the lord thy god in the place which he shall choose thou shalt read this law before all israel in their hearing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 12, 'Gather the people together, men, and women, and children, and thy stranger that {is} within thy gates, that they may hear, and that they may learn, and fear the LORD your God, and observe to do all the words of this law:', 'gather the people together men and women and children and thy stranger that is within thy gates that they may hear and that they may learn and fear the lord your god and observe to do all the words of this law');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 13, 'And {that} their children, which have not known {any thing}, may hear, and learn to fear the LORD your God, as long as ye live in the land whither ye go over Jordan to possess it.', 'and that their children which have not known any thing may hear and learn to fear the lord your god as long as ye live in the land whither ye go over jordan to possess it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 14, 'And the LORD said unto Moses, Behold, thy days approach that thou must die: call Joshua, and present yourselves in the tabernacle of the congregation, that I may give him a charge. And Moses and Joshua went, and presented themselves in the tabernacle of the congregation.', 'and the lord said unto moses behold thy days approach that thou must die call joshua and present yourselves in the tabernacle of the congregation that i may give him a charge and moses and joshua went and presented themselves in the tabernacle of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 15, 'And the LORD appeared in the tabernacle in a pillar of a cloud: and the pillar of the cloud stood over the door of the tabernacle.', 'and the lord appeared in the tabernacle in a pillar of a cloud and the pillar of the cloud stood over the door of the tabernacle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 16, 'And the LORD said unto Moses, Behold, thou shalt sleep with thy fathers; and this people will rise up, and go a whoring after the gods of the strangers of the land, whither they go {to be} among them, and will forsake me, and break my covenant which I have made with them. {sleep: Heb. lie down}', 'and the lord said unto moses behold thou shalt sleep with thy fathers and this people will rise up and go a whoring after the gods of the strangers of the land whither they go to be among them and will forsake me and break my covenant which i have made with them sleep heb lie down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 5, 'Unknown', 31, 17, 'Then my anger shall be kindled against them in that day, and I will forsake them, and I will hide my face from them, and they shall be devoured, and many evils and troubles shall befall them; so that they will say in that day, Are not these evils come upon us, because our God {is} not among us? {befall: Heb. find}', 'then my anger shall be kindled against them in that day and i will forsake them and i will hide my face from them and they shall be devoured and many evils and troubles shall befall them so that they will say in that day are not these evils come upon us because our god is not among us befall heb find');
