INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 1, 14, 'Your wives, your little ones, and your cattle, shall remain in the land which Moses gave you on this side Jordan; but ye shall pass before your brethren armed, all the mighty men of valour, and help them; {armed: Heb. marshalled by five}', 'your wives your little ones and your cattle shall remain in the land which moses gave you on this side jordan but ye shall pass before your brethren armed all the mighty men of valour and help them armed heb marshalled by five');
