INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 1, 16, 'And they answered Joshua, saying, All that thou commandest us we will do, and whithersoever thou sendest us, we will go.', 'and they answered joshua saying all that thou commandest us we will do and whithersoever thou sendest us we will go');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 1, 17, 'According as we hearkened unto Moses in all things, so will we hearken unto thee: only the LORD thy God be with thee, as he was with Moses.', 'according as we hearkened unto moses in all things so will we hearken unto thee only the lord thy god be with thee as he was with moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 1, 18, 'Whosoever {he be} that doth rebel against thy commandment, and will not hearken unto thy words in all that thou commandest him, he shall be put to death: only be strong and of a good courage.', 'whosoever he be that doth rebel against thy commandment and will not hearken unto thy words in all that thou commandest him he shall be put to death only be strong and of a good courage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 1, 'And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot''s house, named Rahab, and lodged there. {sent: or, had sent} {lodged: Heb. lay}', 'and joshua the son of nun sent out of shittim two men to spy secretly saying go view the land even jericho and they went and came into an harlot s house named rahab and lodged there sent or had sent lodged heb lay');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 2, 'And it was told the king of Jericho, saying, Behold, there came men in hither to night of the children of Israel to search out the country.', 'and it was told the king of jericho saying behold there came men in hither to night of the children of israel to search out the country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 3, 'And the king of Jericho sent unto Rahab, saying, Bring forth the men that are come to thee, which are entered into thine house: for they be come to search out all the country.', 'and the king of jericho sent unto rahab saying bring forth the men that are come to thee which are entered into thine house for they be come to search out all the country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 4, 'And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they {were}:', 'and the woman took the two men and hid them and said thus there came men unto me but i wist not whence they were');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 5, 'And it came to pass {about the time} of shutting of the gate, when it was dark, that the men went out: whither the men went I wot not: pursue after them quickly; for ye shall overtake them.', 'and it came to pass about the time of shutting of the gate when it was dark that the men went out whither the men went i wot not pursue after them quickly for ye shall overtake them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 6, 'But she had brought them up to the roof of the house, and hid them with the stalks of flax, which she had laid in order upon the roof.', 'but she had brought them up to the roof of the house and hid them with the stalks of flax which she had laid in order upon the roof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 7, 'And the men pursued after them the way to Jordan unto the fords: and as soon as they which pursued after them were gone out, they shut the gate.', 'and the men pursued after them the way to jordan unto the fords and as soon as they which pursued after them were gone out they shut the gate');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 8, 'And before they were laid down, she came up unto them upon the roof;', 'and before they were laid down she came up unto them upon the roof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 9, 'And she said unto the men, I know that the LORD hath given you the land, and that your terror is fallen upon us, and that all the inhabitants of the land faint because of you. {faint: Heb. melt}', 'and she said unto the men i know that the lord hath given you the land and that your terror is fallen upon us and that all the inhabitants of the land faint because of you faint heb melt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 10, 'For we have heard how the LORD dried up the water of the Red sea for you, when ye came out of Egypt; and what ye did unto the two kings of the Amorites, that {were} on the other side Jordan, Sihon and Og, whom ye utterly destroyed.', 'for we have heard how the lord dried up the water of the red sea for you when ye came out of egypt and what ye did unto the two kings of the amorites that were on the other side jordan sihon and og whom ye utterly destroyed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 11, 'And as soon as we had heard {these things}, our hearts did melt, neither did there remain any more courage in any man, because of you: for the LORD your God, he {is} God in heaven above, and in earth beneath. {did there...: Heb. rose up}', 'and as soon as we had heard these things our hearts did melt neither did there remain any more courage in any man because of you for the lord your god he is god in heaven above and in earth beneath did there heb rose up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 12, 'Now therefore, I pray you, swear unto me by the LORD, since I have shewed you kindness, that ye will also shew kindness unto my father''s house, and give me a true token:', 'now therefore i pray you swear unto me by the lord since i have shewed you kindness that ye will also shew kindness unto my father s house and give me a true token');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 13, 'And {that} ye will save alive my father, and my mother, and my brethren, and my sisters, and all that they have, and deliver our lives from death.', 'and that ye will save alive my father and my mother and my brethren and my sisters and all that they have and deliver our lives from death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 14, 'And the men answered her, Our life for yours, if ye utter not this our business. And it shall be, when the LORD hath given us the land, that we will deal kindly and truly with thee. {for...: Heb. instead of you to die}', 'and the men answered her our life for yours if ye utter not this our business and it shall be when the lord hath given us the land that we will deal kindly and truly with thee for heb instead of you to die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 15, 'Then she let them down by a cord through the window: for her house {was} upon the town wall, and she dwelt upon the wall.', 'then she let them down by a cord through the window for her house was upon the town wall and she dwelt upon the wall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 16, 'And she said unto them, Get you to the mountain, lest the pursuers meet you; and hide yourselves there three days, until the pursuers be returned: and afterward may ye go your way.', 'and she said unto them get you to the mountain lest the pursuers meet you and hide yourselves there three days until the pursuers be returned and afterward may ye go your way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 17, 'And the men said unto her, We {will be} blameless of this thine oath which thou hast made us swear.', 'and the men said unto her we will be blameless of this thine oath which thou hast made us swear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 18, 'Behold, {when} we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father''s household, home unto thee. {bring: Heb. gather}', 'behold when we come into the land thou shalt bind this line of scarlet thread in the window which thou didst let us down by and thou shalt bring thy father and thy mother and thy brethren and all thy father s household home unto thee bring heb gather');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 19, 'And it shall be, {that} whosoever shall go out of the doors of thy house into the street, his blood {shall be} upon his head, and we {will be} guiltless: and whosoever shall be with thee in the house, his blood {shall be} on our head, if {any} hand be upon him.', 'and it shall be that whosoever shall go out of the doors of thy house into the street his blood shall be upon his head and we will be guiltless and whosoever shall be with thee in the house his blood shall be on our head if any hand be upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 20, 'And if thou utter this our business, then we will be quit of thine oath which thou hast made us to swear.', 'and if thou utter this our business then we will be quit of thine oath which thou hast made us to swear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 21, 'And she said, According unto your words, so {be} it. And she sent them away, and they departed: and she bound the scarlet line in the window.', 'and she said according unto your words so be it and she sent them away and they departed and she bound the scarlet line in the window');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 22, 'And they went, and came unto the mountain, and abode there three days, until the pursuers were returned: and the pursuers sought {them} throughout all the way, but found {them} not.', 'and they went and came unto the mountain and abode there three days until the pursuers were returned and the pursuers sought them throughout all the way but found them not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 23, 'So the two men returned, and descended from the mountain, and passed over, and came to Joshua the son of Nun, and told him all {things} that befell them:', 'so the two men returned and descended from the mountain and passed over and came to joshua the son of nun and told him all things that befell them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 2, 24, 'And they said unto Joshua, Truly the LORD hath delivered into our hands all the land; for even all the inhabitants of the country do faint because of us. {faint: Heb. melt}', 'and they said unto joshua truly the lord hath delivered into our hands all the land for even all the inhabitants of the country do faint because of us faint heb melt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 1, 'And Joshua rose early in the morning; and they removed from Shittim, and came to Jordan, he and all the children of Israel, and lodged there before they passed over.', 'and joshua rose early in the morning and they removed from shittim and came to jordan he and all the children of israel and lodged there before they passed over');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 2, 'And it came to pass after three days, that the officers went through the host;', 'and it came to pass after three days that the officers went through the host');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 3, 'And they commanded the people, saying, When ye see the ark of the covenant of the LORD your God, and the priests the Levites bearing it, then ye shall remove from your place, and go after it.', 'and they commanded the people saying when ye see the ark of the covenant of the lord your god and the priests the levites bearing it then ye shall remove from your place and go after it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 4, 'Yet there shall be a space between you and it, about two thousand cubits by measure: come not near unto it, that ye may know the way by which ye must go: for ye have not passed {this} way heretofore. {heretofore: Heb. since yesterday, and the third day}', 'yet there shall be a space between you and it about two thousand cubits by measure come not near unto it that ye may know the way by which ye must go for ye have not passed this way heretofore heretofore heb since yesterday and the third day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 5, 'And Joshua said unto the people, Sanctify yourselves: for to morrow the LORD will do wonders among you.', 'and joshua said unto the people sanctify yourselves for to morrow the lord will do wonders among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 6, 'And Joshua spake unto the priests, saying, Take up the ark of the covenant, and pass over before the people. And they took up the ark of the covenant, and went before the people.', 'and joshua spake unto the priests saying take up the ark of the covenant and pass over before the people and they took up the ark of the covenant and went before the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 7, 'And the LORD said unto Joshua, This day will I begin to magnify thee in the sight of all Israel, that they may know that, as I was with Moses, {so} I will be with thee.', 'and the lord said unto joshua this day will i begin to magnify thee in the sight of all israel that they may know that as i was with moses so i will be with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 8, 'And thou shalt command the priests that bear the ark of the covenant, saying, When ye are come to the brink of the water of Jordan, ye shall stand still in Jordan.', 'and thou shalt command the priests that bear the ark of the covenant saying when ye are come to the brink of the water of jordan ye shall stand still in jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 9, 'And Joshua said unto the children of Israel, Come hither, and hear the words of the LORD your God.', 'and joshua said unto the children of israel come hither and hear the words of the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 10, 'And Joshua said, Hereby ye shall know that the living God {is} among you, and {that} he will without fail drive out from before you the Canaanites, and the Hittites, and the Hivites, and the Perizzites, and the Girgashites, and the Amorites, and the Jebusites.', 'and joshua said hereby ye shall know that the living god is among you and that he will without fail drive out from before you the canaanites and the hittites and the hivites and the perizzites and the girgashites and the amorites and the jebusites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 11, 'Behold, the ark of the covenant of the Lord of all the earth passeth over before you into Jordan.', 'behold the ark of the covenant of the lord of all the earth passeth over before you into jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 12, 'Now therefore take you twelve men out of the tribes of Israel, out of every tribe a man.', 'now therefore take you twelve men out of the tribes of israel out of every tribe a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 13, 'And it shall come to pass, as soon as the soles of the feet of the priests that bear the ark of the LORD, the Lord of all the earth, shall rest in the waters of Jordan, {that} the waters of Jordan shall be cut off {from} the waters that come down from above; and they shall stand upon an heap.', 'and it shall come to pass as soon as the soles of the feet of the priests that bear the ark of the lord the lord of all the earth shall rest in the waters of jordan that the waters of jordan shall be cut off from the waters that come down from above and they shall stand upon an heap');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 14, 'And it came to pass, when the people removed from their tents, to pass over Jordan, and the priests bearing the ark of the covenant before the people;', 'and it came to pass when the people removed from their tents to pass over jordan and the priests bearing the ark of the covenant before the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 15, 'And as they that bare the ark were come unto Jordan, and the feet of the priests that bare the ark were dipped in the brim of the water, (for Jordan overfloweth all his banks all the time of harvest,)', 'and as they that bare the ark were come unto jordan and the feet of the priests that bare the ark were dipped in the brim of the water for jordan overfloweth all his banks all the time of harvest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 16, 'That the waters which came down from above stood {and} rose up upon an heap very far from the city Adam, that {is} beside Zaretan: and those that came down toward the sea of the plain, {even} the salt sea, failed, {and} were cut off: and the people passed over right against Jericho.', 'that the waters which came down from above stood and rose up upon an heap very far from the city adam that is beside zaretan and those that came down toward the sea of the plain even the salt sea failed and were cut off and the people passed over right against jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 3, 17, 'And the priests that bare the ark of the covenant of the LORD stood firm on dry ground in the midst of Jordan, and all the Israelites passed over on dry ground, until all the people were passed clean over Jordan.', 'and the priests that bare the ark of the covenant of the lord stood firm on dry ground in the midst of jordan and all the israelites passed over on dry ground until all the people were passed clean over jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 1, 'And it came to pass, when all the people were clean passed over Jordan, that the LORD spake unto Joshua, saying,', 'and it came to pass when all the people were clean passed over jordan that the lord spake unto joshua saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 2, 'Take you twelve men out of the people, out of every tribe a man,', 'take you twelve men out of the people out of every tribe a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 3, 'And command ye them, saying, Take you hence out of the midst of Jordan, out of the place where the priests'' feet stood firm, twelve stones, and ye shall carry them over with you, and leave them in the lodging place, where ye shall lodge this night.', 'and command ye them saying take you hence out of the midst of jordan out of the place where the priests feet stood firm twelve stones and ye shall carry them over with you and leave them in the lodging place where ye shall lodge this night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 4, 'Then Joshua called the twelve men, whom he had prepared of the children of Israel, out of every tribe a man:', 'then joshua called the twelve men whom he had prepared of the children of israel out of every tribe a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 5, 'And Joshua said unto them, Pass over before the ark of the LORD your God into the midst of Jordan, and take ye up every man of you a stone upon his shoulder, according unto the number of the tribes of the children of Israel:', 'and joshua said unto them pass over before the ark of the lord your god into the midst of jordan and take ye up every man of you a stone upon his shoulder according unto the number of the tribes of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 6, 'That this may be a sign among you, {that} when your children ask {their fathers} in time to come, saying, What {mean} ye by these stones? {in time...: Heb. to morrow}', 'that this may be a sign among you that when your children ask their fathers in time to come saying what mean ye by these stones in time heb to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 7, 'Then ye shall answer them, That the waters of Jordan were cut off before the ark of the covenant of the LORD; when it passed over Jordan, the waters of Jordan were cut off: and these stones shall be for a memorial unto the children of Israel for ever.', 'then ye shall answer them that the waters of jordan were cut off before the ark of the covenant of the lord when it passed over jordan the waters of jordan were cut off and these stones shall be for a memorial unto the children of israel for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 8, 'And the children of Israel did so as Joshua commanded, and took up twelve stones out of the midst of Jordan, as the LORD spake unto Joshua, according to the number of the tribes of the children of Israel, and carried them over with them unto the place where they lodged, and laid them down there.', 'and the children of israel did so as joshua commanded and took up twelve stones out of the midst of jordan as the lord spake unto joshua according to the number of the tribes of the children of israel and carried them over with them unto the place where they lodged and laid them down there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 9, 'And Joshua set up twelve stones in the midst of Jordan, in the place where the feet of the priests which bare the ark of the covenant stood: and they are there unto this day.', 'and joshua set up twelve stones in the midst of jordan in the place where the feet of the priests which bare the ark of the covenant stood and they are there unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 10, 'For the priests which bare the ark stood in the midst of Jordan, until every thing was finished that the LORD commanded Joshua to speak unto the people, according to all that Moses commanded Joshua: and the people hasted and passed over.', 'for the priests which bare the ark stood in the midst of jordan until every thing was finished that the lord commanded joshua to speak unto the people according to all that moses commanded joshua and the people hasted and passed over');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 11, 'And it came to pass, when all the people were clean passed over, that the ark of the LORD passed over, and the priests, in the presence of the people.', 'and it came to pass when all the people were clean passed over that the ark of the lord passed over and the priests in the presence of the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 12, 'And the children of Reuben, and the children of Gad, and half the tribe of Manasseh, passed over armed before the children of Israel, as Moses spake unto them:', 'and the children of reuben and the children of gad and half the tribe of manasseh passed over armed before the children of israel as moses spake unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 13, 'About forty thousand prepared for war passed over before the LORD unto battle, to the plains of Jericho. {prepared: or, ready armed}', 'about forty thousand prepared for war passed over before the lord unto battle to the plains of jericho prepared or ready armed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 14, 'On that day the LORD magnified Joshua in the sight of all Israel; and they feared him, as they feared Moses, all the days of his life.', 'on that day the lord magnified joshua in the sight of all israel and they feared him as they feared moses all the days of his life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 15, 'And the LORD spake unto Joshua, saying,', 'and the lord spake unto joshua saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 16, 'Command the priests that bear the ark of the testimony, that they come up out of Jordan.', 'command the priests that bear the ark of the testimony that they come up out of jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 17, 'Joshua therefore commanded the priests, saying, Come ye up out of Jordan.', 'joshua therefore commanded the priests saying come ye up out of jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 18, 'And it came to pass, when the priests that bare the ark of the covenant of the LORD were come up out of the midst of Jordan, {and} the soles of the priests'' feet were lifted up unto the dry land, that the waters of Jordan returned unto their place, and flowed over all his banks, as {they did} before. {lifted...: Heb. plucked up} {flowed: Heb. went}', 'and it came to pass when the priests that bare the ark of the covenant of the lord were come up out of the midst of jordan and the soles of the priests feet were lifted up unto the dry land that the waters of jordan returned unto their place and flowed over all his banks as they did before lifted heb plucked up flowed heb went');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 19, 'And the people came up out of Jordan on the tenth {day} of the first month, and encamped in Gilgal, in the east border of Jericho.', 'and the people came up out of jordan on the tenth day of the first month and encamped in gilgal in the east border of jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 20, 'And those twelve stones, which they took out of Jordan, did Joshua pitch in Gilgal.', 'and those twelve stones which they took out of jordan did joshua pitch in gilgal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 21, 'And he spake unto the children of Israel, saying, When your children shall ask their fathers in time to come, saying, What {mean} these stones? {in time...: Heb. to morrow}', 'and he spake unto the children of israel saying when your children shall ask their fathers in time to come saying what mean these stones in time heb to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 22, 'Then ye shall let your children know, saying, Israel came over this Jordan on dry land.', 'then ye shall let your children know saying israel came over this jordan on dry land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 23, 'For the LORD your God dried up the waters of Jordan from before you, until ye were passed over, as the LORD your God did to the Red sea, which he dried up from before us, until we were gone over:', 'for the lord your god dried up the waters of jordan from before you until ye were passed over as the lord your god did to the red sea which he dried up from before us until we were gone over');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 4, 24, 'That all the people of the earth might know the hand of the LORD, that it {is} mighty: that ye might fear the LORD your God for ever. {for ever: Heb. all days}', 'that all the people of the earth might know the hand of the lord that it is mighty that ye might fear the lord your god for ever for ever heb all days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 1, 'And it came to pass, when all the kings of the Amorites, which {were} on the side of Jordan westward, and all the kings of the Canaanites, which {were} by the sea, heard that the LORD had dried up the waters of Jordan from before the children of Israel, until we were passed over, that their heart melted, neither was there spirit in them any more, because of the children of Israel.', 'and it came to pass when all the kings of the amorites which were on the side of jordan westward and all the kings of the canaanites which were by the sea heard that the lord had dried up the waters of jordan from before the children of israel until we were passed over that their heart melted neither was there spirit in them any more because of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 2, 'At that time the LORD said unto Joshua, Make thee sharp knives, and circumcise again the children of Israel the second time. {sharp...: or, knives of flints}', 'at that time the lord said unto joshua make thee sharp knives and circumcise again the children of israel the second time sharp or knives of flints');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 3, 'And Joshua made him sharp knives, and circumcised the children of Israel at the hill of the foreskins. {sharp...: or, knives of flints} {the hill...: or, Gibeah-haaraloth}', 'and joshua made him sharp knives and circumcised the children of israel at the hill of the foreskins sharp or knives of flints the hill or gibeah haaraloth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 4, 'And this {is} the cause why Joshua did circumcise: All the people that came out of Egypt, {that were} males, {even} all the men of war, died in the wilderness by the way, after they came out of Egypt.', 'and this is the cause why joshua did circumcise all the people that came out of egypt that were males even all the men of war died in the wilderness by the way after they came out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 5, 'Now all the people that came out were circumcised: but all the people {that were} born in the wilderness by the way as they came forth out of Egypt, {them} they had not circumcised.', 'now all the people that came out were circumcised but all the people that were born in the wilderness by the way as they came forth out of egypt them they had not circumcised');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 6, 'For the children of Israel walked forty years in the wilderness, till all the people {that were} men of war, which came out of Egypt, were consumed, because they obeyed not the voice of the LORD: unto whom the LORD sware that he would not shew them the land, which the LORD sware unto their fathers that he would give us, a land that floweth with milk and honey.', 'for the children of israel walked forty years in the wilderness till all the people that were men of war which came out of egypt were consumed because they obeyed not the voice of the lord unto whom the lord sware that he would not shew them the land which the lord sware unto their fathers that he would give us a land that floweth with milk and honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 7, 'And their children, {whom} he raised up in their stead, them Joshua circumcised: for they were uncircumcised, because they had not circumcised them by the way.', 'and their children whom he raised up in their stead them joshua circumcised for they were uncircumcised because they had not circumcised them by the way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 8, 'And it came to pass, when they had done circumcising all the people, that they abode in their places in the camp, till they were whole. {they had...: Heb. the people had made an end to be circumcised}', 'and it came to pass when they had done circumcising all the people that they abode in their places in the camp till they were whole they had heb the people had made an end to be circumcised');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 9, 'And the LORD said unto Joshua, This day have I rolled away the reproach of Egypt from off you. Wherefore the name of the place is called Gilgal unto this day. {Gilgal: that is Rolling}', 'and the lord said unto joshua this day have i rolled away the reproach of egypt from off you wherefore the name of the place is called gilgal unto this day gilgal that is rolling');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 10, 'And the children of Israel encamped in Gilgal, and kept the passover on the fourteenth day of the month at even in the plains of Jericho.', 'and the children of israel encamped in gilgal and kept the passover on the fourteenth day of the month at even in the plains of jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 11, 'And they did eat of the old corn of the land on the morrow after the passover, unleavened cakes, and parched {corn} in the selfsame day.', 'and they did eat of the old corn of the land on the morrow after the passover unleavened cakes and parched corn in the selfsame day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 12, 'And the manna ceased on the morrow after they had eaten of the old corn of the land; neither had the children of Israel manna any more; but they did eat of the fruit of the land of Canaan that year.', 'and the manna ceased on the morrow after they had eaten of the old corn of the land neither had the children of israel manna any more but they did eat of the fruit of the land of canaan that year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 13, 'And it came to pass, when Joshua was by Jericho, that he lifted up his eyes and looked, and, behold, there stood a man over against him with his sword drawn in his hand: and Joshua went unto him, and said unto him, {Art} thou for us, or for our adversaries?', 'and it came to pass when joshua was by jericho that he lifted up his eyes and looked and behold there stood a man over against him with his sword drawn in his hand and joshua went unto him and said unto him art thou for us or for our adversaries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 14, 'And he said, Nay; but {as} captain of the host of the LORD am I now come. And Joshua fell on his face to the earth, and did worship, and said unto him, What saith my lord unto his servant? {captain: or, prince}', 'and he said nay but as captain of the host of the lord am i now come and joshua fell on his face to the earth and did worship and said unto him what saith my lord unto his servant captain or prince');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 5, 15, 'And the captain of the LORD''S host said unto Joshua, Loose thy shoe from off thy foot; for the place whereon thou standest {is} holy. And Joshua did so.', 'and the captain of the lord s host said unto joshua loose thy shoe from off thy foot for the place whereon thou standest is holy and joshua did so');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 1, 'Now Jericho was straitly shut up because of the children of Israel: none went out, and none came in. {was...: Heb. did shut up, and was shut up}', 'now jericho was straitly shut up because of the children of israel none went out and none came in was heb did shut up and was shut up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 2, 'And the LORD said unto Joshua, See, I have given into thine hand Jericho, and the king thereof, {and} the mighty men of valour.', 'and the lord said unto joshua see i have given into thine hand jericho and the king thereof and the mighty men of valour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 3, 'And ye shall compass the city, all {ye} men of war, {and} go round about the city once. Thus shalt thou do six days.', 'and ye shall compass the city all ye men of war and go round about the city once thus shalt thou do six days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 4, 'And seven priests shall bear before the ark seven trumpets of rams'' horns: and the seventh day ye shall compass the city seven times, and the priests shall blow with the trumpets.', 'and seven priests shall bear before the ark seven trumpets of rams horns and the seventh day ye shall compass the city seven times and the priests shall blow with the trumpets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 5, 'And it shall come to pass, that when they make a long {blast} with the ram''s horn, {and} when ye hear the sound of the trumpet, all the people shall shout with a great shout; and the wall of the city shall fall down flat, and the people shall ascend up every man straight before him. {flat: Heb. under it}', 'and it shall come to pass that when they make a long blast with the ram s horn and when ye hear the sound of the trumpet all the people shall shout with a great shout and the wall of the city shall fall down flat and the people shall ascend up every man straight before him flat heb under it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 6, 'And Joshua the son of Nun called the priests, and said unto them, Take up the ark of the covenant, and let seven priests bear seven trumpets of rams'' horns before the ark of the LORD.', 'and joshua the son of nun called the priests and said unto them take up the ark of the covenant and let seven priests bear seven trumpets of rams horns before the ark of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 7, 'And he said unto the people, Pass on, and compass the city, and let him that is armed pass on before the ark of the LORD.', 'and he said unto the people pass on and compass the city and let him that is armed pass on before the ark of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 8, 'And it came to pass, when Joshua had spoken unto the people, that the seven priests bearing the seven trumpets of rams'' horns passed on before the LORD, and blew with the trumpets: and the ark of the covenant of the LORD followed them.', 'and it came to pass when joshua had spoken unto the people that the seven priests bearing the seven trumpets of rams horns passed on before the lord and blew with the trumpets and the ark of the covenant of the lord followed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 9, 'And the armed men went before the priests that blew with the trumpets, and the rereward came after the ark, {the priests} going on, and blowing with the trumpets. {rereward: Heb. gathering host}', 'and the armed men went before the priests that blew with the trumpets and the rereward came after the ark the priests going on and blowing with the trumpets rereward heb gathering host');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 10, 'And Joshua had commanded the people, saying, Ye shall not shout, nor make any noise with your voice, neither shall {any} word proceed out of your mouth, until the day I bid you shout; then shall ye shout. {any noise...: Heb. your voice to be heard}', 'and joshua had commanded the people saying ye shall not shout nor make any noise with your voice neither shall any word proceed out of your mouth until the day i bid you shout then shall ye shout any noise heb your voice to be heard');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 11, 'So the ark of the LORD compassed the city, going about {it} once: and they came into the camp, and lodged in the camp.', 'so the ark of the lord compassed the city going about it once and they came into the camp and lodged in the camp');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 12, 'And Joshua rose early in the morning, and the priests took up the ark of the LORD.', 'and joshua rose early in the morning and the priests took up the ark of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 13, 'And seven priests bearing seven trumpets of rams'' horns before the ark of the LORD went on continually, and blew with the trumpets: and the armed men went before them; but the rereward came after the ark of the LORD, {the priests} going on, and blowing with the trumpets.', 'and seven priests bearing seven trumpets of rams horns before the ark of the lord went on continually and blew with the trumpets and the armed men went before them but the rereward came after the ark of the lord the priests going on and blowing with the trumpets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 14, 'And the second day they compassed the city once, and returned into the camp: so they did six days.', 'and the second day they compassed the city once and returned into the camp so they did six days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 15, 'And it came to pass on the seventh day, that they rose early about the dawning of the day, and compassed the city after the same manner seven times: only on that day they compassed the city seven times.', 'and it came to pass on the seventh day that they rose early about the dawning of the day and compassed the city after the same manner seven times only on that day they compassed the city seven times');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 16, 'And it came to pass at the seventh time, when the priests blew with the trumpets, Joshua said unto the people, Shout; for the LORD hath given you the city.', 'and it came to pass at the seventh time when the priests blew with the trumpets joshua said unto the people shout for the lord hath given you the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 17, 'And the city shall be accursed, {even} it, and all that {are} therein, to the LORD: only Rahab the harlot shall live, she and all that {are} with her in the house, because she hid the messengers that we sent. {accursed: or, devoted}', 'and the city shall be accursed even it and all that are therein to the lord only rahab the harlot shall live she and all that are with her in the house because she hid the messengers that we sent accursed or devoted');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 18, 'And ye, in any wise keep {yourselves} from the accursed thing, lest ye make {yourselves} accursed, when ye take of the accursed thing, and make the camp of Israel a curse, and trouble it. {accursed: or, devoted} {a curse: or, devoted}', 'and ye in any wise keep yourselves from the accursed thing lest ye make yourselves accursed when ye take of the accursed thing and make the camp of israel a curse and trouble it accursed or devoted a curse or devoted');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 19, 'But all the silver, and gold, and vessels of brass and iron, {are} consecrated unto the LORD: they shall come into the treasury of the LORD. {consecrated: Heb. holiness}', 'but all the silver and gold and vessels of brass and iron are consecrated unto the lord they shall come into the treasury of the lord consecrated heb holiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 20, 'So the people shouted when {the priests} blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city. {flat: Heb. under it}', 'so the people shouted when the priests blew with the trumpets and it came to pass when the people heard the sound of the trumpet and the people shouted with a great shout that the wall fell down flat so that the people went up into the city every man straight before him and they took the city flat heb under it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 21, 'And they utterly destroyed all that {was} in the city, both man and woman, young and old, and ox, and sheep, and ass, with the edge of the sword.', 'and they utterly destroyed all that was in the city both man and woman young and old and ox and sheep and ass with the edge of the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 22, 'But Joshua had said unto the two men that had spied out the country, Go into the harlot''s house, and bring out thence the woman, and all that she hath, as ye sware unto her.', 'but joshua had said unto the two men that had spied out the country go into the harlot s house and bring out thence the woman and all that she hath as ye sware unto her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 23, 'And the young men that were spies went in, and brought out Rahab, and her father, and her mother, and her brethren, and all that she had; and they brought out all her kindred, and left them without the camp of Israel. {kindred: Heb. families}', 'and the young men that were spies went in and brought out rahab and her father and her mother and her brethren and all that she had and they brought out all her kindred and left them without the camp of israel kindred heb families');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 24, 'And they burnt the city with fire, and all that {was} therein: only the silver, and the gold, and the vessels of brass and of iron, they put into the treasury of the house of the LORD.', 'and they burnt the city with fire and all that was therein only the silver and the gold and the vessels of brass and of iron they put into the treasury of the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 25, 'And Joshua saved Rahab the harlot alive, and her father''s household, and all that she had; and she dwelleth in Israel {even} unto this day; because she hid the messengers, which Joshua sent to spy out Jericho.', 'and joshua saved rahab the harlot alive and her father s household and all that she had and she dwelleth in israel even unto this day because she hid the messengers which joshua sent to spy out jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 26, 'And Joshua adjured {them} at that time, saying, Cursed {be} the man before the LORD, that riseth up and buildeth this city Jericho: he shall lay the foundation thereof in his firstborn, and in his youngest {son} shall he set up the gates of it.', 'and joshua adjured them at that time saying cursed be the man before the lord that riseth up and buildeth this city jericho he shall lay the foundation thereof in his firstborn and in his youngest son shall he set up the gates of it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 6, 27, 'So the LORD was with Joshua; and his fame was {noised} throughout all the country.', 'so the lord was with joshua and his fame was noised throughout all the country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 1, 'But the children of Israel committed a trespass in the accursed thing: for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took of the accursed thing: and the anger of the LORD was kindled against the children of Israel. {Achan: also called, Achar} {Zabdi: also called, Zimri}', 'but the children of israel committed a trespass in the accursed thing for achan the son of carmi the son of zabdi the son of zerah of the tribe of judah took of the accursed thing and the anger of the lord was kindled against the children of israel achan also called achar zabdi also called zimri');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 2, 'And Joshua sent men from Jericho to Ai, which {is} beside Bethaven, on the east side of Bethel, and spake unto them, saying, Go up and view the country. And the men went up and viewed Ai.', 'and joshua sent men from jericho to ai which is beside bethaven on the east side of bethel and spake unto them saying go up and view the country and the men went up and viewed ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 3, 'And they returned to Joshua, and said unto him, Let not all the people go up; but let about two or three thousand men go up and smite Ai; {and} make not all the people to labour thither; for they {are but} few. {about...: Heb. about two thousand men, or, about three thousand men}', 'and they returned to joshua and said unto him let not all the people go up but let about two or three thousand men go up and smite ai and make not all the people to labour thither for they are but few about heb about two thousand men or about three thousand men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 4, 'So there went up thither of the people about three thousand men: and they fled before the men of Ai.', 'so there went up thither of the people about three thousand men and they fled before the men of ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 5, 'And the men of Ai smote of them about thirty and six men: for they chased them {from} before the gate {even} unto Shebarim, and smote them in the going down: wherefore the hearts of the people melted, and became as water. {in...: or, in Morad}', 'and the men of ai smote of them about thirty and six men for they chased them from before the gate even unto shebarim and smote them in the going down wherefore the hearts of the people melted and became as water in or in morad');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 6, 'And Joshua rent his clothes, and fell to the earth upon his face before the ark of the LORD until the eventide, he and the elders of Israel, and put dust upon their heads.', 'and joshua rent his clothes and fell to the earth upon his face before the ark of the lord until the eventide he and the elders of israel and put dust upon their heads');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 7, 'And Joshua said, Alas, O Lord GOD, wherefore hast thou at all brought this people over Jordan, to deliver us into the hand of the Amorites, to destroy us? would to God we had been content, and dwelt on the other side Jordan!', 'and joshua said alas o lord god wherefore hast thou at all brought this people over jordan to deliver us into the hand of the amorites to destroy us would to god we had been content and dwelt on the other side jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 8, 'O Lord, what shall I say, when Israel turneth their backs before their enemies! {backs: Heb. necks}', 'o lord what shall i say when israel turneth their backs before their enemies backs heb necks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 9, 'For the Canaanites and all the inhabitants of the land shall hear {of it}, and shall environ us round, and cut off our name from the earth: and what wilt thou do unto thy great name?', 'for the canaanites and all the inhabitants of the land shall hear of it and shall environ us round and cut off our name from the earth and what wilt thou do unto thy great name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 10, 'And the LORD said unto Joshua, Get thee up; wherefore liest thou thus upon thy face? {liest: Heb. fallest}', 'and the lord said unto joshua get thee up wherefore liest thou thus upon thy face liest heb fallest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 11, 'Israel hath sinned, and they have also transgressed my covenant which I commanded them: for they have even taken of the accursed thing, and have also stolen, and dissembled also, and they have put {it} even among their own stuff.', 'israel hath sinned and they have also transgressed my covenant which i commanded them for they have even taken of the accursed thing and have also stolen and dissembled also and they have put it even among their own stuff');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 12, 'Therefore the children of Israel could not stand before their enemies, {but} turned {their} backs before their enemies, because they were accursed: neither will I be with you any more, except ye destroy the accursed from among you.', 'therefore the children of israel could not stand before their enemies but turned their backs before their enemies because they were accursed neither will i be with you any more except ye destroy the accursed from among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 13, 'Up, sanctify the people, and say, Sanctify yourselves against to morrow: for thus saith the LORD God of Israel, {There is} an accursed thing in the midst of thee, O Israel: thou canst not stand before thine enemies, until ye take away the accursed thing from among you.', 'up sanctify the people and say sanctify yourselves against to morrow for thus saith the lord god of israel there is an accursed thing in the midst of thee o israel thou canst not stand before thine enemies until ye take away the accursed thing from among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 14, 'In the morning therefore ye shall be brought according to your tribes: and it shall be, {that} the tribe which the LORD taketh shall come according to the families {thereof}; and the family which the LORD shall take shall come by households; and the household which the LORD shall take shall come man by man.', 'in the morning therefore ye shall be brought according to your tribes and it shall be that the tribe which the lord taketh shall come according to the families thereof and the family which the lord shall take shall come by households and the household which the lord shall take shall come man by man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 15, 'And it shall be, {that} he that is taken with the accursed thing shall be burnt with fire, he and all that he hath: because he hath transgressed the covenant of the LORD, and because he hath wrought folly in Israel. {folly: or, wickedness}', 'and it shall be that he that is taken with the accursed thing shall be burnt with fire he and all that he hath because he hath transgressed the covenant of the lord and because he hath wrought folly in israel folly or wickedness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 16, 'So Joshua rose up early in the morning, and brought Israel by their tribes; and the tribe of Judah was taken:', 'so joshua rose up early in the morning and brought israel by their tribes and the tribe of judah was taken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 17, 'And he brought the family of Judah; and he took the family of the Zarhites: and he brought the family of the Zarhites man by man; and Zabdi was taken:', 'and he brought the family of judah and he took the family of the zarhites and he brought the family of the zarhites man by man and zabdi was taken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 18, 'And he brought his household man by man; and Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, was taken.', 'and he brought his household man by man and achan the son of carmi the son of zabdi the son of zerah of the tribe of judah was taken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 19, 'And Joshua said unto Achan, My son, give, I pray thee, glory to the LORD God of Israel, and make confession unto him; and tell me now what thou hast done; hide {it} not from me.', 'and joshua said unto achan my son give i pray thee glory to the lord god of israel and make confession unto him and tell me now what thou hast done hide it not from me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 20, 'And Achan answered Joshua, and said, Indeed I have sinned against the LORD God of Israel, and thus and thus have I done:', 'and achan answered joshua and said indeed i have sinned against the lord god of israel and thus and thus have i done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 21, 'When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they {are} hid in the earth in the midst of my tent, and the silver under it. {wedge: Heb. tongue}', 'when i saw among the spoils a goodly babylonish garment and two hundred shekels of silver and a wedge of gold of fifty shekels weight then i coveted them and took them and behold they are hid in the earth in the midst of my tent and the silver under it wedge heb tongue');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 22, 'So Joshua sent messengers, and they ran unto the tent; and, behold, {it was} hid in his tent, and the silver under it.', 'so joshua sent messengers and they ran unto the tent and behold it was hid in his tent and the silver under it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 23, 'And they took them out of the midst of the tent, and brought them unto Joshua, and unto all the children of Israel, and laid them out before the LORD. {laid: Heb. poured}', 'and they took them out of the midst of the tent and brought them unto joshua and unto all the children of israel and laid them out before the lord laid heb poured');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 24, 'And Joshua, and all Israel with him, took Achan the son of Zerah, and the silver, and the garment, and the wedge of gold, and his sons, and his daughters, and his oxen, and his asses, and his sheep, and his tent, and all that he had: and they brought them unto the valley of Achor.', 'and joshua and all israel with him took achan the son of zerah and the silver and the garment and the wedge of gold and his sons and his daughters and his oxen and his asses and his sheep and his tent and all that he had and they brought them unto the valley of achor');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 25, 'And Joshua said, Why hast thou troubled us? the LORD shall trouble thee this day. And all Israel stoned him with stones, and burned them with fire, after they had stoned them with stones.', 'and joshua said why hast thou troubled us the lord shall trouble thee this day and all israel stoned him with stones and burned them with fire after they had stoned them with stones');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 7, 26, 'And they raised over him a great heap of stones unto this day. So the LORD turned from the fierceness of his anger. Wherefore the name of that place was called, The valley of Achor, unto this day. {Achor: that is, Trouble}', 'and they raised over him a great heap of stones unto this day so the lord turned from the fierceness of his anger wherefore the name of that place was called the valley of achor unto this day achor that is trouble');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 1, 'And the LORD said unto Joshua, Fear not, neither be thou dismayed: take all the people of war with thee, and arise, go up to Ai: see, I have given into thy hand the king of Ai, and his people, and his city, and his land:', 'and the lord said unto joshua fear not neither be thou dismayed take all the people of war with thee and arise go up to ai see i have given into thy hand the king of ai and his people and his city and his land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 2, 'And thou shalt do to Ai and her king as thou didst unto Jericho and her king: only the spoil thereof, and the cattle thereof, shall ye take for a prey unto yourselves: lay thee an ambush for the city behind it.', 'and thou shalt do to ai and her king as thou didst unto jericho and her king only the spoil thereof and the cattle thereof shall ye take for a prey unto yourselves lay thee an ambush for the city behind it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 3, 'So Joshua arose, and all the people of war, to go up against Ai: and Joshua chose out thirty thousand mighty men of valour, and sent them away by night.', 'so joshua arose and all the people of war to go up against ai and joshua chose out thirty thousand mighty men of valour and sent them away by night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 4, 'And he commanded them, saying, Behold, ye shall lie in wait against the city, {even} behind the city: go not very far from the city, but be ye all ready:', 'and he commanded them saying behold ye shall lie in wait against the city even behind the city go not very far from the city but be ye all ready');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 5, 'And I, and all the people that {are} with me, will approach unto the city: and it shall come to pass, when they come out against us, as at the first, that we will flee before them,', 'and i and all the people that are with me will approach unto the city and it shall come to pass when they come out against us as at the first that we will flee before them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 6, '(For they will come out after us) till we have drawn them from the city; for they will say, They flee before us, as at the first: therefore we will flee before them. {drawn: Heb. pulled}', 'for they will come out after us till we have drawn them from the city for they will say they flee before us as at the first therefore we will flee before them drawn heb pulled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 7, 'Then ye shall rise up from the ambush, and seize upon the city: for the LORD your God will deliver it into your hand.', 'then ye shall rise up from the ambush and seize upon the city for the lord your god will deliver it into your hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 8, 'And it shall be, when ye have taken the city, {that} ye shall set the city on fire: according to the commandment of the LORD shall ye do. See, I have commanded you.', 'and it shall be when ye have taken the city that ye shall set the city on fire according to the commandment of the lord shall ye do see i have commanded you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 9, 'Joshua therefore sent them forth: and they went to lie in ambush, and abode between Bethel and Ai, on the west side of Ai: but Joshua lodged that night among the people.', 'joshua therefore sent them forth and they went to lie in ambush and abode between bethel and ai on the west side of ai but joshua lodged that night among the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 10, 'And Joshua rose up early in the morning, and numbered the people, and went up, he and the elders of Israel, before the people to Ai.', 'and joshua rose up early in the morning and numbered the people and went up he and the elders of israel before the people to ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 11, 'And all the people, {even the people} of war that {were} with him, went up, and drew nigh, and came before the city, and pitched on the north side of Ai: now {there was} a valley between them and Ai.', 'and all the people even the people of war that were with him went up and drew nigh and came before the city and pitched on the north side of ai now there was a valley between them and ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 12, 'And he took about five thousand men, and set them to lie in ambush between Bethel and Ai, on the west side of the city. {of...: or, of Ai}', 'and he took about five thousand men and set them to lie in ambush between bethel and ai on the west side of the city of or of ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 13, 'And when they had set the people, {even} all the host that {was} on the north of the city, and their liers in wait on the west of the city, Joshua went that night into the midst of the valley. {liers...: Heb. lying in wait}', 'and when they had set the people even all the host that was on the north of the city and their liers in wait on the west of the city joshua went that night into the midst of the valley liers heb lying in wait');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 14, 'And it came to pass, when the king of Ai saw {it}, that they hasted and rose up early, and the men of the city went out against Israel to battle, he and all his people, at a time appointed, before the plain; but he wist not that {there were} liers in ambush against him behind the city.', 'and it came to pass when the king of ai saw it that they hasted and rose up early and the men of the city went out against israel to battle he and all his people at a time appointed before the plain but he wist not that there were liers in ambush against him behind the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 15, 'And Joshua and all Israel made as if they were beaten before them, and fled by the way of the wilderness.', 'and joshua and all israel made as if they were beaten before them and fled by the way of the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 16, 'And all the people that {were} in Ai were called together to pursue after them: and they pursued after Joshua, and were drawn away from the city.', 'and all the people that were in ai were called together to pursue after them and they pursued after joshua and were drawn away from the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 17, 'And there was not a man left in Ai or Bethel, that went not out after Israel: and they left the city open, and pursued after Israel.', 'and there was not a man left in ai or bethel that went not out after israel and they left the city open and pursued after israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 18, 'And the LORD said unto Joshua, Stretch out the spear that {is} in thy hand toward Ai; for I will give it into thine hand. And Joshua stretched out the spear that {he had} in his hand toward the city.', 'and the lord said unto joshua stretch out the spear that is in thy hand toward ai for i will give it into thine hand and joshua stretched out the spear that he had in his hand toward the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 19, 'And the ambush arose quickly out of their place, and they ran as soon as he had stretched out his hand: and they entered into the city, and took it, and hasted and set the city on fire.', 'and the ambush arose quickly out of their place and they ran as soon as he had stretched out his hand and they entered into the city and took it and hasted and set the city on fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 20, 'And when the men of Ai looked behind them, they saw, and, behold, the smoke of the city ascended up to heaven, and they had no power to flee this way or that way: and the people that fled to the wilderness turned back upon the pursuers. {power: Heb. hand}', 'and when the men of ai looked behind them they saw and behold the smoke of the city ascended up to heaven and they had no power to flee this way or that way and the people that fled to the wilderness turned back upon the pursuers power heb hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 21, 'And when Joshua and all Israel saw that the ambush had taken the city, and that the smoke of the city ascended, then they turned again, and slew the men of Ai.', 'and when joshua and all israel saw that the ambush had taken the city and that the smoke of the city ascended then they turned again and slew the men of ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 22, 'And the other issued out of the city against them; so they were in the midst of Israel, some on this side, and some on that side: and they smote them, so that they let none of them remain or escape.', 'and the other issued out of the city against them so they were in the midst of israel some on this side and some on that side and they smote them so that they let none of them remain or escape');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 23, 'And the king of Ai they took alive, and brought him to Joshua.', 'and the king of ai they took alive and brought him to joshua');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 24, 'And it came to pass, when Israel had made an end of slaying all the inhabitants of Ai in the field, in the wilderness wherein they chased them, and when they were all fallen on the edge of the sword, until they were consumed, that all the Israelites returned unto Ai, and smote it with the edge of the sword.', 'and it came to pass when israel had made an end of slaying all the inhabitants of ai in the field in the wilderness wherein they chased them and when they were all fallen on the edge of the sword until they were consumed that all the israelites returned unto ai and smote it with the edge of the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 25, 'And {so} it was, {that} all that fell that day, both of men and women, {were} twelve thousand, {even} all the men of Ai.', 'and so it was that all that fell that day both of men and women were twelve thousand even all the men of ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 26, 'For Joshua drew not his hand back, wherewith he stretched out the spear, until he had utterly destroyed all the inhabitants of Ai.', 'for joshua drew not his hand back wherewith he stretched out the spear until he had utterly destroyed all the inhabitants of ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 27, 'Only the cattle and the spoil of that city Israel took for a prey unto themselves, according unto the word of the LORD which he commanded Joshua.', 'only the cattle and the spoil of that city israel took for a prey unto themselves according unto the word of the lord which he commanded joshua');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 28, 'And Joshua burnt Ai, and made it an heap for ever, {even} a desolation unto this day.', 'and joshua burnt ai and made it an heap for ever even a desolation unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 29, 'And the king of Ai he hanged on a tree until eventide: and as soon as the sun was down, Joshua commanded that they should take his carcase down from the tree, and cast it at the entering of the gate of the city, and raise thereon a great heap of stones, {that remaineth} unto this day.', 'and the king of ai he hanged on a tree until eventide and as soon as the sun was down joshua commanded that they should take his carcase down from the tree and cast it at the entering of the gate of the city and raise thereon a great heap of stones that remaineth unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 30, 'Then Joshua built an altar unto the LORD God of Israel in mount Ebal,', 'then joshua built an altar unto the lord god of israel in mount ebal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 31, 'As Moses the servant of the LORD commanded the children of Israel, as it is written in the book of the law of Moses, an altar of whole stones, over which no man hath lift up {any} iron: and they offered thereon burnt offerings unto the LORD, and sacrificed peace offerings.', 'as moses the servant of the lord commanded the children of israel as it is written in the book of the law of moses an altar of whole stones over which no man hath lift up any iron and they offered thereon burnt offerings unto the lord and sacrificed peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 32, 'And he wrote there upon the stones a copy of the law of Moses, which he wrote in the presence of the children of Israel.', 'and he wrote there upon the stones a copy of the law of moses which he wrote in the presence of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 33, 'And all Israel, and their elders, and officers, and their judges, stood on this side the ark and on that side before the priests the Levites, which bare the ark of the covenant of the LORD, as well the stranger, as he that was born among them; half of them over against mount Gerizim, and half of them over against mount Ebal; as Moses the servant of the LORD had commanded before, that they should bless the people of Israel.', 'and all israel and their elders and officers and their judges stood on this side the ark and on that side before the priests the levites which bare the ark of the covenant of the lord as well the stranger as he that was born among them half of them over against mount gerizim and half of them over against mount ebal as moses the servant of the lord had commanded before that they should bless the people of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 34, 'And afterward he read all the words of the law, the blessings and cursings, according to all that is written in the book of the law.', 'and afterward he read all the words of the law the blessings and cursings according to all that is written in the book of the law');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 8, 35, 'There was not a word of all that Moses commanded, which Joshua read not before all the congregation of Israel, with the women, and the little ones, and the strangers that were conversant among them. {were...: Heb. walked}', 'there was not a word of all that moses commanded which joshua read not before all the congregation of israel with the women and the little ones and the strangers that were conversant among them were heb walked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 1, 'And it came to pass, when all the kings which {were} on this side Jordan, in the hills, and in the valleys, and in all the coasts of the great sea over against Lebanon, the Hittite, and the Amorite, the Canaanite, the Perizzite, the Hivite, and the Jebusite, heard {thereof};', 'and it came to pass when all the kings which were on this side jordan in the hills and in the valleys and in all the coasts of the great sea over against lebanon the hittite and the amorite the canaanite the perizzite the hivite and the jebusite heard thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 2, 'That they gathered themselves together, to fight with Joshua and with Israel, with one accord. {accord: Heb. mouth}', 'that they gathered themselves together to fight with joshua and with israel with one accord accord heb mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 3, 'And when the inhabitants of Gibeon heard what Joshua had done unto Jericho and to Ai,', 'and when the inhabitants of gibeon heard what joshua had done unto jericho and to ai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 4, 'They did work wilily, and went and made as if they had been ambassadors, and took old sacks upon their asses, and wine bottles, old, and rent, and bound up;', 'they did work wilily and went and made as if they had been ambassadors and took old sacks upon their asses and wine bottles old and rent and bound up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 5, 'And old shoes and clouted upon their feet, and old garments upon them; and all the bread of their provision was dry {and} mouldy.', 'and old shoes and clouted upon their feet and old garments upon them and all the bread of their provision was dry and mouldy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 6, 'And they went to Joshua unto the camp at Gilgal, and said unto him, and to the men of Israel, We be come from a far country: now therefore make ye a league with us.', 'and they went to joshua unto the camp at gilgal and said unto him and to the men of israel we be come from a far country now therefore make ye a league with us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 7, 'And the men of Israel said unto the Hivites, Peradventure ye dwell among us; and how shall we make a league with you?', 'and the men of israel said unto the hivites peradventure ye dwell among us and how shall we make a league with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 8, 'And they said unto Joshua, We {are} thy servants. And Joshua said unto them, Who {are} ye? and from whence come ye?', 'and they said unto joshua we are thy servants and joshua said unto them who are ye and from whence come ye');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 9, 'And they said unto him, From a very far country thy servants are come because of the name of the LORD thy God: for we have heard the fame of him, and all that he did in Egypt,', 'and they said unto him from a very far country thy servants are come because of the name of the lord thy god for we have heard the fame of him and all that he did in egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 10, 'And all that he did to the two kings of the Amorites, that {were} beyond Jordan, to Sihon king of Heshbon, and to Og king of Bashan, which {was} at Ashtaroth.', 'and all that he did to the two kings of the amorites that were beyond jordan to sihon king of heshbon and to og king of bashan which was at ashtaroth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 11, 'Wherefore our elders and all the inhabitants of our country spake to us, saying, Take victuals with you for the journey, and go to meet them, and say unto them, We {are} your servants: therefore now make ye a league with us. {with you: Heb. in your hand}', 'wherefore our elders and all the inhabitants of our country spake to us saying take victuals with you for the journey and go to meet them and say unto them we are your servants therefore now make ye a league with us with you heb in your hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 12, 'This our bread we took hot {for} our provision out of our houses on the day we came forth to go unto you; but now, behold, it is dry, and it is mouldy:', 'this our bread we took hot for our provision out of our houses on the day we came forth to go unto you but now behold it is dry and it is mouldy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 13, 'And these bottles of wine, which we filled, {were} new; and, behold, they be rent: and these our garments and our shoes are become old by reason of the very long journey.', 'and these bottles of wine which we filled were new and behold they be rent and these our garments and our shoes are become old by reason of the very long journey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 14, 'And the men took of their victuals, and asked not {counsel} at the mouth of the LORD. {the men...: or, they received the men by reason of their victuals}', 'and the men took of their victuals and asked not counsel at the mouth of the lord the men or they received the men by reason of their victuals');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 15, 'And Joshua made peace with them, and made a league with them, to let them live: and the princes of the congregation sware unto them.', 'and joshua made peace with them and made a league with them to let them live and the princes of the congregation sware unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 16, 'And it came to pass at the end of three days after they had made a league with them, that they heard that they {were} their neighbours, and {that} they dwelt among them.', 'and it came to pass at the end of three days after they had made a league with them that they heard that they were their neighbours and that they dwelt among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 17, 'And the children of Israel journeyed, and came unto their cities on the third day. Now their cities {were} Gibeon, and Chephirah, and Beeroth, and Kirjathjearim.', 'and the children of israel journeyed and came unto their cities on the third day now their cities were gibeon and chephirah and beeroth and kirjathjearim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 18, 'And the children of Israel smote them not, because the princes of the congregation had sworn unto them by the LORD God of Israel. And all the congregation murmured against the princes.', 'and the children of israel smote them not because the princes of the congregation had sworn unto them by the lord god of israel and all the congregation murmured against the princes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 19, 'But all the princes said unto all the congregation, We have sworn unto them by the LORD God of Israel: now therefore we may not touch them.', 'but all the princes said unto all the congregation we have sworn unto them by the lord god of israel now therefore we may not touch them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 20, 'This we will do to them; we will even let them live, lest wrath be upon us, because of the oath which we sware unto them.', 'this we will do to them we will even let them live lest wrath be upon us because of the oath which we sware unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 21, 'And the princes said unto them, Let them live; but let them be hewers of wood and drawers of water unto all the congregation; as the princes had promised them.', 'and the princes said unto them let them live but let them be hewers of wood and drawers of water unto all the congregation as the princes had promised them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 22, 'And Joshua called for them, and he spake unto them, saying, Wherefore have ye beguiled us, saying, We {are} very far from you; when ye dwell among us?', 'and joshua called for them and he spake unto them saying wherefore have ye beguiled us saying we are very far from you when ye dwell among us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 23, 'Now therefore ye {are} cursed, and there shall none of you be freed from being bondmen, and hewers of wood and drawers of water for the house of my God. {none...: Heb. not be cut off from you}', 'now therefore ye are cursed and there shall none of you be freed from being bondmen and hewers of wood and drawers of water for the house of my god none heb not be cut off from you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 24, 'And they answered Joshua, and said, Because it was certainly told thy servants, how that the LORD thy God commanded his servant Moses to give you all the land, and to destroy all the inhabitants of the land from before you, therefore we were sore afraid of our lives because of you, and have done this thing.', 'and they answered joshua and said because it was certainly told thy servants how that the lord thy god commanded his servant moses to give you all the land and to destroy all the inhabitants of the land from before you therefore we were sore afraid of our lives because of you and have done this thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 25, 'And now, behold, we {are} in thine hand: as it seemeth good and right unto thee to do unto us, do.', 'and now behold we are in thine hand as it seemeth good and right unto thee to do unto us do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 26, 'And so did he unto them, and delivered them out of the hand of the children of Israel, that they slew them not.', 'and so did he unto them and delivered them out of the hand of the children of israel that they slew them not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 9, 27, 'And Joshua made them that day hewers of wood and drawers of water for the congregation, and for the altar of the LORD, even unto this day, in the place which he should choose. {made: Heb. gave, or, delivered to be}', 'and joshua made them that day hewers of wood and drawers of water for the congregation and for the altar of the lord even unto this day in the place which he should choose made heb gave or delivered to be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 1, 'Now it came to pass, when Adonizedek king of Jerusalem had heard how Joshua had taken Ai, and had utterly destroyed it; as he had done to Jericho and her king, so he had done to Ai and her king; and how the inhabitants of Gibeon had made peace with Israel, and were among them;', 'now it came to pass when adonizedek king of jerusalem had heard how joshua had taken ai and had utterly destroyed it as he had done to jericho and her king so he had done to ai and her king and how the inhabitants of gibeon had made peace with israel and were among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 2, 'That they feared greatly, because Gibeon {was} a great city, as one of the royal cities, and because it {was} greater than Ai, and all the men thereof {were} mighty. {royal...: Heb. cities of the kingdom}', 'that they feared greatly because gibeon was a great city as one of the royal cities and because it was greater than ai and all the men thereof were mighty royal heb cities of the kingdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 3, 'Wherefore Adonizedek king of Jerusalem sent unto Hoham king of Hebron, and unto Piram king of Jarmuth, and unto Japhia king of Lachish, and unto Debir king of Eglon, saying,', 'wherefore adonizedek king of jerusalem sent unto hoham king of hebron and unto piram king of jarmuth and unto japhia king of lachish and unto debir king of eglon saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 4, 'Come up unto me, and help me, that we may smite Gibeon: for it hath made peace with Joshua and with the children of Israel.', 'come up unto me and help me that we may smite gibeon for it hath made peace with joshua and with the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 5, 'Therefore the five kings of the Amorites, the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, the king of Eglon, gathered themselves together, and went up, they and all their hosts, and encamped before Gibeon, and made war against it.', 'therefore the five kings of the amorites the king of jerusalem the king of hebron the king of jarmuth the king of lachish the king of eglon gathered themselves together and went up they and all their hosts and encamped before gibeon and made war against it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 6, 'And the men of Gibeon sent unto Joshua to the camp to Gilgal, saying, Slack not thy hand from thy servants; come up to us quickly, and save us, and help us: for all the kings of the Amorites that dwell in the mountains are gathered together against us.', 'and the men of gibeon sent unto joshua to the camp to gilgal saying slack not thy hand from thy servants come up to us quickly and save us and help us for all the kings of the amorites that dwell in the mountains are gathered together against us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 7, 'So Joshua ascended from Gilgal, he, and all the people of war with him, and all the mighty men of valour.', 'so joshua ascended from gilgal he and all the people of war with him and all the mighty men of valour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 8, 'And the LORD said unto Joshua, Fear them not: for I have delivered them into thine hand; there shall not a man of them stand before thee.', 'and the lord said unto joshua fear them not for i have delivered them into thine hand there shall not a man of them stand before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 9, 'Joshua therefore came unto them suddenly, {and} went up from Gilgal all night.', 'joshua therefore came unto them suddenly and went up from gilgal all night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 10, 'And the LORD discomfited them before Israel, and slew them with a great slaughter at Gibeon, and chased them along the way that goeth up to Bethhoron, and smote them to Azekah, and unto Makkedah.', 'and the lord discomfited them before israel and slew them with a great slaughter at gibeon and chased them along the way that goeth up to bethhoron and smote them to azekah and unto makkedah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 11, 'And it came to pass, as they fled from before Israel, {and} were in the going down to Bethhoron, that the LORD cast down great stones from heaven upon them unto Azekah, and they died: {they were} more which died with hailstones than {they} whom the children of Israel slew with the sword.', 'and it came to pass as they fled from before israel and were in the going down to bethhoron that the lord cast down great stones from heaven upon them unto azekah and they died they were more which died with hailstones than they whom the children of israel slew with the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 12, 'Then spake Joshua to the LORD in the day when the LORD delivered up the Amorites before the children of Israel, and he said in the sight of Israel, Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon. {stand...: Heb. be silent}', 'then spake joshua to the lord in the day when the lord delivered up the amorites before the children of israel and he said in the sight of israel sun stand thou still upon gibeon and thou moon in the valley of ajalon stand heb be silent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 13, 'And the sun stood still, and the moon stayed, until the people had avenged themselves upon their enemies. {Is} not this written in the book of Jasher? So the sun stood still in the midst of heaven, and hasted not to go down about a whole day. {Jasher: or, the upright?}', 'and the sun stood still and the moon stayed until the people had avenged themselves upon their enemies is not this written in the book of jasher so the sun stood still in the midst of heaven and hasted not to go down about a whole day jasher or the upright');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 14, 'And there was no day like that before it or after it, that the LORD hearkened unto the voice of a man: for the LORD fought for Israel.', 'and there was no day like that before it or after it that the lord hearkened unto the voice of a man for the lord fought for israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 15, 'And Joshua returned, and all Israel with him, unto the camp to Gilgal.', 'and joshua returned and all israel with him unto the camp to gilgal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 16, 'But these five kings fled, and hid themselves in a cave at Makkedah.', 'but these five kings fled and hid themselves in a cave at makkedah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 17, 'And it was told Joshua, saying, The five kings are found hid in a cave at Makkedah.', 'and it was told joshua saying the five kings are found hid in a cave at makkedah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 18, 'And Joshua said, Roll great stones upon the mouth of the cave, and set men by it for to keep them:', 'and joshua said roll great stones upon the mouth of the cave and set men by it for to keep them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 19, 'And stay ye not, {but} pursue after your enemies, and smite the hindmost of them; suffer them not to enter into their cities: for the LORD your God hath delivered them into your hand. {smite...: Heb. cut off the tail}', 'and stay ye not but pursue after your enemies and smite the hindmost of them suffer them not to enter into their cities for the lord your god hath delivered them into your hand smite heb cut off the tail');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 20, 'And it came to pass, when Joshua and the children of Israel had made an end of slaying them with a very great slaughter, till they were consumed, that the rest {which} remained of them entered into fenced cities.', 'and it came to pass when joshua and the children of israel had made an end of slaying them with a very great slaughter till they were consumed that the rest which remained of them entered into fenced cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 21, 'And all the people returned to the camp to Joshua at Makkedah in peace: none moved his tongue against any of the children of Israel.', 'and all the people returned to the camp to joshua at makkedah in peace none moved his tongue against any of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 22, 'Then said Joshua, Open the mouth of the cave, and bring out those five kings unto me out of the cave.', 'then said joshua open the mouth of the cave and bring out those five kings unto me out of the cave');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 23, 'And they did so, and brought forth those five kings unto him out of the cave, the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, {and} the king of Eglon.', 'and they did so and brought forth those five kings unto him out of the cave the king of jerusalem the king of hebron the king of jarmuth the king of lachish and the king of eglon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 24, 'And it came to pass, when they brought out those kings unto Joshua, that Joshua called for all the men of Israel, and said unto the captains of the men of war which went with him, Come near, put your feet upon the necks of these kings. And they came near, and put their feet upon the necks of them.', 'and it came to pass when they brought out those kings unto joshua that joshua called for all the men of israel and said unto the captains of the men of war which went with him come near put your feet upon the necks of these kings and they came near and put their feet upon the necks of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 25, 'And Joshua said unto them, Fear not, nor be dismayed, be strong and of good courage: for thus shall the LORD do to all your enemies against whom ye fight.', 'and joshua said unto them fear not nor be dismayed be strong and of good courage for thus shall the lord do to all your enemies against whom ye fight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 26, 'And afterward Joshua smote them, and slew them, and hanged them on five trees: and they were hanging upon the trees until the evening.', 'and afterward joshua smote them and slew them and hanged them on five trees and they were hanging upon the trees until the evening');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 27, 'And it came to pass at the time of the going down of the sun, {that} Joshua commanded, and they took them down off the trees, and cast them into the cave wherein they had been hid, and laid great stones in the cave''s mouth, {which remain} until this very day.', 'and it came to pass at the time of the going down of the sun that joshua commanded and they took them down off the trees and cast them into the cave wherein they had been hid and laid great stones in the cave s mouth which remain until this very day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 28, 'And that day Joshua took Makkedah, and smote it with the edge of the sword, and the king thereof he utterly destroyed, them, and all the souls that {were} therein; he let none remain: and he did to the king of Makkedah as he did unto the king of Jericho.', 'and that day joshua took makkedah and smote it with the edge of the sword and the king thereof he utterly destroyed them and all the souls that were therein he let none remain and he did to the king of makkedah as he did unto the king of jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 29, 'Then Joshua passed from Makkedah, and all Israel with him, unto Libnah, and fought against Libnah:', 'then joshua passed from makkedah and all israel with him unto libnah and fought against libnah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 30, 'And the LORD delivered it also, and the king thereof, into the hand of Israel; and he smote it with the edge of the sword, and all the souls that {were} therein; he let none remain in it; but did unto the king thereof as he did unto the king of Jericho.', 'and the lord delivered it also and the king thereof into the hand of israel and he smote it with the edge of the sword and all the souls that were therein he let none remain in it but did unto the king thereof as he did unto the king of jericho');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 31, 'And Joshua passed from Libnah, and all Israel with him, unto Lachish, and encamped against it, and fought against it:', 'and joshua passed from libnah and all israel with him unto lachish and encamped against it and fought against it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 32, 'And the LORD delivered Lachish into the hand of Israel, which took it on the second day, and smote it with the edge of the sword, and all the souls that {were} therein, according to all that he had done to Libnah.', 'and the lord delivered lachish into the hand of israel which took it on the second day and smote it with the edge of the sword and all the souls that were therein according to all that he had done to libnah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 33, 'Then Horam king of Gezer came up to help Lachish; and Joshua smote him and his people, until he had left him none remaining.', 'then horam king of gezer came up to help lachish and joshua smote him and his people until he had left him none remaining');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 34, 'And from Lachish Joshua passed unto Eglon, and all Israel with him; and they encamped against it, and fought against it:', 'and from lachish joshua passed unto eglon and all israel with him and they encamped against it and fought against it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 35, 'And they took it on that day, and smote it with the edge of the sword, and all the souls that {were} therein he utterly destroyed that day, according to all that he had done to Lachish.', 'and they took it on that day and smote it with the edge of the sword and all the souls that were therein he utterly destroyed that day according to all that he had done to lachish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 36, 'And Joshua went up from Eglon, and all Israel with him, unto Hebron; and they fought against it:', 'and joshua went up from eglon and all israel with him unto hebron and they fought against it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 37, 'And they took it, and smote it with the edge of the sword, and the king thereof, and all the cities thereof, and all the souls that {were} therein; he left none remaining, according to all that he had done to Eglon; but destroyed it utterly, and all the souls that {were} therein.', 'and they took it and smote it with the edge of the sword and the king thereof and all the cities thereof and all the souls that were therein he left none remaining according to all that he had done to eglon but destroyed it utterly and all the souls that were therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 38, 'And Joshua returned, and all Israel with him, to Debir; and fought against it:', 'and joshua returned and all israel with him to debir and fought against it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 39, 'And he took it, and the king thereof, and all the cities thereof; and they smote them with the edge of the sword, and utterly destroyed all the souls that {were} therein; he left none remaining: as he had done to Hebron, so he did to Debir, and to the king thereof; as he had done also to Libnah, and to her king.', 'and he took it and the king thereof and all the cities thereof and they smote them with the edge of the sword and utterly destroyed all the souls that were therein he left none remaining as he had done to hebron so he did to debir and to the king thereof as he had done also to libnah and to her king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 40, 'So Joshua smote all the country of the hills, and of the south, and of the vale, and of the springs, and all their kings: he left none remaining, but utterly destroyed all that breathed, as the LORD God of Israel commanded.', 'so joshua smote all the country of the hills and of the south and of the vale and of the springs and all their kings he left none remaining but utterly destroyed all that breathed as the lord god of israel commanded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 41, 'And Joshua smote them from Kadeshbarnea even unto Gaza, and all the country of Goshen, even unto Gibeon.', 'and joshua smote them from kadeshbarnea even unto gaza and all the country of goshen even unto gibeon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 42, 'And all these kings and their land did Joshua take at one time, because the LORD God of Israel fought for Israel.', 'and all these kings and their land did joshua take at one time because the lord god of israel fought for israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 10, 43, 'And Joshua returned, and all Israel with him, unto the camp to Gilgal.', 'and joshua returned and all israel with him unto the camp to gilgal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 1, 'And it came to pass, when Jabin king of Hazor had heard {those things}, that he sent to Jobab king of Madon, and to the king of Shimron, and to the king of Achshaph,', 'and it came to pass when jabin king of hazor had heard those things that he sent to jobab king of madon and to the king of shimron and to the king of achshaph');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 2, 'And to the kings that {were} on the north of the mountains, and of the plains south of Chinneroth, and in the valley, and in the borders of Dor on the west,', 'and to the kings that were on the north of the mountains and of the plains south of chinneroth and in the valley and in the borders of dor on the west');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 3, '{And to} the Canaanite on the east and on the west, and {to} the Amorite, and the Hittite, and the Perizzite, and the Jebusite in the mountains, and {to} the Hivite under Hermon in the land of Mizpeh.', 'and to the canaanite on the east and on the west and to the amorite and the hittite and the perizzite and the jebusite in the mountains and to the hivite under hermon in the land of mizpeh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 4, 'And they went out, they and all their hosts with them, much people, even as the sand that {is} upon the sea shore in multitude, with horses and chariots very many.', 'and they went out they and all their hosts with them much people even as the sand that is upon the sea shore in multitude with horses and chariots very many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 5, 'And when all these kings were met together, they came and pitched together at the waters of Merom, to fight against Israel. {met...: Heb. assembled by appointment}', 'and when all these kings were met together they came and pitched together at the waters of merom to fight against israel met heb assembled by appointment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 6, 'And the LORD said unto Joshua, Be not afraid because of them: for to morrow about this time will I deliver them up all slain before Israel: thou shalt hough their horses, and burn their chariots with fire.', 'and the lord said unto joshua be not afraid because of them for to morrow about this time will i deliver them up all slain before israel thou shalt hough their horses and burn their chariots with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 7, 'So Joshua came, and all the people of war with him, against them by the waters of Merom suddenly; and they fell upon them.', 'so joshua came and all the people of war with him against them by the waters of merom suddenly and they fell upon them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 8, 'And the LORD delivered them into the hand of Israel, who smote them, and chased them unto great Zidon, and unto Misrephothmaim, and unto the valley of Mizpeh eastward; and they smote them, until they left them none remaining. {great Zidon: or, Zidonrabbah} {Misrephothmaim: or, Salt pits: Heb. Burnings of waters}', 'and the lord delivered them into the hand of israel who smote them and chased them unto great zidon and unto misrephothmaim and unto the valley of mizpeh eastward and they smote them until they left them none remaining great zidon or zidonrabbah misrephothmaim or salt pits heb burnings of waters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 9, 'And Joshua did unto them as the LORD bade him: he houghed their horses, and burnt their chariots with fire.', 'and joshua did unto them as the lord bade him he houghed their horses and burnt their chariots with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 10, 'And Joshua at that time turned back, and took Hazor, and smote the king thereof with the sword: for Hazor beforetime was the head of all those kingdoms.', 'and joshua at that time turned back and took hazor and smote the king thereof with the sword for hazor beforetime was the head of all those kingdoms');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 11, 'And they smote all the souls that {were} therein with the edge of the sword, utterly destroying {them}: there was not any left to breathe: and he burnt Hazor with fire. {any...: Heb. any breath}', 'and they smote all the souls that were therein with the edge of the sword utterly destroying them there was not any left to breathe and he burnt hazor with fire any heb any breath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 12, 'And all the cities of those kings, and all the kings of them, did Joshua take, and smote them with the edge of the sword, {and} he utterly destroyed them, as Moses the servant of the LORD commanded.', 'and all the cities of those kings and all the kings of them did joshua take and smote them with the edge of the sword and he utterly destroyed them as moses the servant of the lord commanded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 13, 'But {as for} the cities that stood still in their strength, Israel burned none of them, save Hazor only; {that} did Joshua burn. {in their...: Heb. on their heap}', 'but as for the cities that stood still in their strength israel burned none of them save hazor only that did joshua burn in their heb on their heap');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 14, 'And all the spoil of these cities, and the cattle, the children of Israel took for a prey unto themselves; but every man they smote with the edge of the sword, until they had destroyed them, neither left they any to breathe.', 'and all the spoil of these cities and the cattle the children of israel took for a prey unto themselves but every man they smote with the edge of the sword until they had destroyed them neither left they any to breathe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 15, 'As the LORD commanded Moses his servant, so did Moses command Joshua, and so did Joshua; he left nothing undone of all that the LORD commanded Moses. {left...: Heb. removed nothing}', 'as the lord commanded moses his servant so did moses command joshua and so did joshua he left nothing undone of all that the lord commanded moses left heb removed nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 16, 'So Joshua took all that land, the hills, and all the south country, and all the land of Goshen, and the valley, and the plain, and the mountain of Israel, and the valley of the same;', 'so joshua took all that land the hills and all the south country and all the land of goshen and the valley and the plain and the mountain of israel and the valley of the same');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 17, '{Even} from the mount Halak, that goeth up to Seir, even unto Baalgad in the valley of Lebanon under mount Hermon: and all their kings he took, and smote them, and slew them. {the mount...: or, the smooth mountain}', 'even from the mount halak that goeth up to seir even unto baalgad in the valley of lebanon under mount hermon and all their kings he took and smote them and slew them the mount or the smooth mountain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 18, 'Joshua made war a long time with all those kings.', 'joshua made war a long time with all those kings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 19, 'There was not a city that made peace with the children of Israel, save the Hivites the inhabitants of Gibeon: all {other} they took in battle.', 'there was not a city that made peace with the children of israel save the hivites the inhabitants of gibeon all other they took in battle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 20, 'For it was of the LORD to harden their hearts, that they should come against Israel in battle, that he might destroy them utterly, {and} that they might have no favour, but that he might destroy them, as the LORD commanded Moses.', 'for it was of the lord to harden their hearts that they should come against israel in battle that he might destroy them utterly and that they might have no favour but that he might destroy them as the lord commanded moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 21, 'And at that time came Joshua, and cut off the Anakims from the mountains, from Hebron, from Debir, from Anab, and from all the mountains of Judah, and from all the mountains of Israel: Joshua destroyed them utterly with their cities.', 'and at that time came joshua and cut off the anakims from the mountains from hebron from debir from anab and from all the mountains of judah and from all the mountains of israel joshua destroyed them utterly with their cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 22, 'There was none of the Anakims left in the land of the children of Israel: only in Gaza, in Gath, and in Ashdod, there remained.', 'there was none of the anakims left in the land of the children of israel only in gaza in gath and in ashdod there remained');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 11, 23, 'So Joshua took the whole land, according to all that the LORD said unto Moses; and Joshua gave it for an inheritance unto Israel according to their divisions by their tribes. And the land rested from war.', 'so joshua took the whole land according to all that the lord said unto moses and joshua gave it for an inheritance unto israel according to their divisions by their tribes and the land rested from war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 1, 'Now these {are} the kings of the land, which the children of Israel smote, and possessed their land on the other side Jordan toward the rising of the sun, from the river Arnon unto mount Hermon, and all the plain on the east:', 'now these are the kings of the land which the children of israel smote and possessed their land on the other side jordan toward the rising of the sun from the river arnon unto mount hermon and all the plain on the east');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 2, 'Sihon king of the Amorites, who dwelt in Heshbon, {and} ruled from Aroer, which {is} upon the bank of the river Arnon, and from the middle of the river, and from half Gilead, even unto the river Jabbok, {which is} the border of the children of Ammon;', 'sihon king of the amorites who dwelt in heshbon and ruled from aroer which is upon the bank of the river arnon and from the middle of the river and from half gilead even unto the river jabbok which is the border of the children of ammon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 3, 'And from the plain to the sea of Chinneroth on the east, and unto the sea of the plain, {even} the salt sea on the east, the way to Bethjeshimoth; and from the south, under Ashdothpisgah: {the south: or, Teman} {Ashdothpisgah: or, the springs of Pisgah, or, the hill}', 'and from the plain to the sea of chinneroth on the east and unto the sea of the plain even the salt sea on the east the way to bethjeshimoth and from the south under ashdothpisgah the south or teman ashdothpisgah or the springs of pisgah or the hill');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 4, 'And the coast of Og king of Bashan, {which was} of the remnant of the giants, that dwelt at Ashtaroth and at Edrei,', 'and the coast of og king of bashan which was of the remnant of the giants that dwelt at ashtaroth and at edrei');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 5, 'And reigned in mount Hermon, and in Salcah, and in all Bashan, unto the border of the Geshurites and the Maachathites, and half Gilead, the border of Sihon king of Heshbon.', 'and reigned in mount hermon and in salcah and in all bashan unto the border of the geshurites and the maachathites and half gilead the border of sihon king of heshbon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 6, 'Them did Moses the servant of the LORD and the children of Israel smite: and Moses the servant of the LORD gave it {for} a possession unto the Reubenites, and the Gadites, and the half tribe of Manasseh.', 'them did moses the servant of the lord and the children of israel smite and moses the servant of the lord gave it for a possession unto the reubenites and the gadites and the half tribe of manasseh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 7, 'And these {are} the kings of the country which Joshua and the children of Israel smote on this side Jordan on the west, from Baalgad in the valley of Lebanon even unto the mount Halak, that goeth up to Seir; which Joshua gave unto the tribes of Israel {for} a possession according to their divisions;', 'and these are the kings of the country which joshua and the children of israel smote on this side jordan on the west from baalgad in the valley of lebanon even unto the mount halak that goeth up to seir which joshua gave unto the tribes of israel for a possession according to their divisions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 8, 'In the mountains, and in the valleys, and in the plains, and in the springs, and in the wilderness, and in the south country; the Hittites, the Amorites, and the Canaanites, the Perizzites, the Hivites, and the Jebusites:', 'in the mountains and in the valleys and in the plains and in the springs and in the wilderness and in the south country the hittites the amorites and the canaanites the perizzites the hivites and the jebusites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 12, 9, 'The king of Jericho, one; the king of Ai, which {is} beside Bethel, one;', 'the king of jericho one the king of ai which is beside bethel one');
