INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 2, 'This {is} the land that yet remaineth: all the borders of the Philistines, and all Geshuri,', 'this is the land that yet remaineth all the borders of the philistines and all geshuri');
