INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 4, 'From the south, all the land of the Canaanites, and Mearah that {is} beside the Sidonians, unto Aphek, to the borders of the Amorites: {Mearah: or, the cave}', 'from the south all the land of the canaanites and mearah that is beside the sidonians unto aphek to the borders of the amorites mearah or the cave');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 5, 'And the land of the Giblites, and all Lebanon, toward the sunrising, from Baalgad under mount Hermon unto the entering into Hamath.', 'and the land of the giblites and all lebanon toward the sunrising from baalgad under mount hermon unto the entering into hamath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 6, 'All the inhabitants of the hill country from Lebanon unto Misrephothmaim, {and} all the Sidonians, them will I drive out from before the children of Israel: only divide thou it by lot unto the Israelites for an inheritance, as I have commanded thee.', 'all the inhabitants of the hill country from lebanon unto misrephothmaim and all the sidonians them will i drive out from before the children of israel only divide thou it by lot unto the israelites for an inheritance as i have commanded thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 7, 'Now therefore divide this land for an inheritance unto the nine tribes, and the half tribe of Manasseh,', 'now therefore divide this land for an inheritance unto the nine tribes and the half tribe of manasseh');
