INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 11, 'And Gilead, and the border of the Geshurites and Maachathites, and all mount Hermon, and all Bashan unto Salcah;', 'and gilead and the border of the geshurites and maachathites and all mount hermon and all bashan unto salcah');
