INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 13, 'Nevertheless the children of Israel expelled not the Geshurites, nor the Maachathites: but the Geshurites and the Maachathites dwell among the Israelites until this day.', 'nevertheless the children of israel expelled not the geshurites nor the maachathites but the geshurites and the maachathites dwell among the israelites until this day');
