INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 21, 'And all the cities of the plain, and all the kingdom of Sihon king of the Amorites, which reigned in Heshbon, whom Moses smote with the princes of Midian, Evi, and Rekem, and Zur, and Hur, and Reba, {which were} dukes of Sihon, dwelling in the country.', 'and all the cities of the plain and all the kingdom of sihon king of the amorites which reigned in heshbon whom moses smote with the princes of midian evi and rekem and zur and hur and reba which were dukes of sihon dwelling in the country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 22, 'Balaam also the son of Beor, the soothsayer, did the children of Israel slay with the sword among them that were slain by them. {soothsayer: or, diviner}', 'balaam also the son of beor the soothsayer did the children of israel slay with the sword among them that were slain by them soothsayer or diviner');
