INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 25, 'And their coast was Jazer, and all the cities of Gilead, and half the land of the children of Ammon, unto Aroer that {is} before Rabbah;', 'and their coast was jazer and all the cities of gilead and half the land of the children of ammon unto aroer that is before rabbah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 26, 'And from Heshbon unto Ramathmizpeh, and Betonim; and from Mahanaim unto the border of Debir;', 'and from heshbon unto ramathmizpeh and betonim and from mahanaim unto the border of debir');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 27, 'And in the valley, Betharam, and Bethnimrah, and Succoth, and Zaphon, the rest of the kingdom of Sihon king of Heshbon, Jordan and {his} border, {even} unto the edge of the sea of Chinnereth on the other side Jordan eastward.', 'and in the valley betharam and bethnimrah and succoth and zaphon the rest of the kingdom of sihon king of heshbon jordan and his border even unto the edge of the sea of chinnereth on the other side jordan eastward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 28, 'This {is} the inheritance of the children of Gad after their families, the cities, and their villages.', 'this is the inheritance of the children of gad after their families the cities and their villages');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 29, 'And Moses gave {inheritance} unto the half tribe of Manasseh: and {this} was {the possession} of the half tribe of the children of Manasseh by their families.', 'and moses gave inheritance unto the half tribe of manasseh and this was the possession of the half tribe of the children of manasseh by their families');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 30, 'And their coast was from Mahanaim, all Bashan, all the kingdom of Og king of Bashan, and all the towns of Jair, which {are} in Bashan, threescore cities:', 'and their coast was from mahanaim all bashan all the kingdom of og king of bashan and all the towns of jair which are in bashan threescore cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 31, 'And half Gilead, and Ashtaroth, and Edrei, cities of the kingdom of Og in Bashan, {were pertaining} unto the children of Machir the son of Manasseh, {even} to the one half of the children of Machir by their families.', 'and half gilead and ashtaroth and edrei cities of the kingdom of og in bashan were pertaining unto the children of machir the son of manasseh even to the one half of the children of machir by their families');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 32, 'These {are the countries} which Moses did distribute for inheritance in the plains of Moab, on the other side Jordan, by Jericho, eastward.', 'these are the countries which moses did distribute for inheritance in the plains of moab on the other side jordan by jericho eastward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 13, 33, 'But unto the tribe of Levi Moses gave not {any} inheritance: the LORD God of Israel {was} their inheritance, as he said unto them.', 'but unto the tribe of levi moses gave not any inheritance the lord god of israel was their inheritance as he said unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 1, 'And these {are the countries} which the children of Israel inherited in the land of Canaan, which Eleazar the priest, and Joshua the son of Nun, and the heads of the fathers of the tribes of the children of Israel, distributed for inheritance to them.', 'and these are the countries which the children of israel inherited in the land of canaan which eleazar the priest and joshua the son of nun and the heads of the fathers of the tribes of the children of israel distributed for inheritance to them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 2, 'By lot {was} their inheritance, as the LORD commanded by the hand of Moses, for the nine tribes, and {for} the half tribe.', 'by lot was their inheritance as the lord commanded by the hand of moses for the nine tribes and for the half tribe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 3, 'For Moses had given the inheritance of two tribes and an half tribe on the other side Jordan: but unto the Levites he gave none inheritance among them.', 'for moses had given the inheritance of two tribes and an half tribe on the other side jordan but unto the levites he gave none inheritance among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 4, 'For the children of Joseph were two tribes, Manasseh and Ephraim: therefore they gave no part unto the Levites in the land, save cities to dwell {in}, with their suburbs for their cattle and for their substance.', 'for the children of joseph were two tribes manasseh and ephraim therefore they gave no part unto the levites in the land save cities to dwell in with their suburbs for their cattle and for their substance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 5, 'As the LORD commanded Moses, so the children of Israel did, and they divided the land.', 'as the lord commanded moses so the children of israel did and they divided the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 6, 'Then the children of Judah came unto Joshua in Gilgal: and Caleb the son of Jephunneh the Kenezite said unto him, Thou knowest the thing that the LORD said unto Moses the man of God concerning me and thee in Kadeshbarnea.', 'then the children of judah came unto joshua in gilgal and caleb the son of jephunneh the kenezite said unto him thou knowest the thing that the lord said unto moses the man of god concerning me and thee in kadeshbarnea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 7, 'Forty years old {was} I when Moses the servant of the LORD sent me from Kadeshbarnea to espy out the land; and I brought him word again as {it was} in mine heart.', 'forty years old was i when moses the servant of the lord sent me from kadeshbarnea to espy out the land and i brought him word again as it was in mine heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 8, 'Nevertheless my brethren that went up with me made the heart of the people melt: but I wholly followed the LORD my God.', 'nevertheless my brethren that went up with me made the heart of the people melt but i wholly followed the lord my god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 9, 'And Moses sware on that day, saying, Surely the land whereon thy feet have trodden shall be thine inheritance, and thy children''s for ever, because thou hast wholly followed the LORD my God.', 'and moses sware on that day saying surely the land whereon thy feet have trodden shall be thine inheritance and thy children s for ever because thou hast wholly followed the lord my god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 10, 'And now, behold, the LORD hath kept me alive, as he said, these forty and five years, even since the LORD spake this word unto Moses, while {the children of} Israel wandered in the wilderness: and now, lo, I {am} this day fourscore and five years old. {wandered: Heb. walked}', 'and now behold the lord hath kept me alive as he said these forty and five years even since the lord spake this word unto moses while the children of israel wandered in the wilderness and now lo i am this day fourscore and five years old wandered heb walked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 11, 'As yet I {am as} strong this day as {I was} in the day that Moses sent me: as my strength {was} then, even so {is} my strength now, for war, both to go out, and to come in.', 'as yet i am as strong this day as i was in the day that moses sent me as my strength was then even so is my strength now for war both to go out and to come in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 12, 'Now therefore give me this mountain, whereof the LORD spake in that day; for thou heardest in that day how the Anakims {were} there, and {that} the cities {were} great {and} fenced: if so be the LORD {will be} with me, then I shall be able to drive them out, as the LORD said.', 'now therefore give me this mountain whereof the lord spake in that day for thou heardest in that day how the anakims were there and that the cities were great and fenced if so be the lord will be with me then i shall be able to drive them out as the lord said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 13, 'And Joshua blessed him, and gave unto Caleb the son of Jephunneh Hebron for an inheritance.', 'and joshua blessed him and gave unto caleb the son of jephunneh hebron for an inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 14, 'Hebron therefore became the inheritance of Caleb the son of Jephunneh the Kenezite unto this day, because that he wholly followed the LORD God of Israel.', 'hebron therefore became the inheritance of caleb the son of jephunneh the kenezite unto this day because that he wholly followed the lord god of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 14, 15, 'And the name of Hebron before {was} Kirjatharba; {which Arba was} a great man among the Anakims. And the land had rest from war.', 'and the name of hebron before was kirjatharba which arba was a great man among the anakims and the land had rest from war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 1, '{This} then was the lot of the tribe of the children of Judah by their families; {even} to the border of Edom the wilderness of Zin southward {was} the uttermost part of the south coast.', 'this then was the lot of the tribe of the children of judah by their families even to the border of edom the wilderness of zin southward was the uttermost part of the south coast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 2, 'And their south border was from the shore of the salt sea, from the bay that looketh southward: {bay: Heb. tongue}', 'and their south border was from the shore of the salt sea from the bay that looketh southward bay heb tongue');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 3, 'And it went out to the south side to Maalehacrabbim, and passed along to Zin, and ascended up on the south side unto Kadeshbarnea, and passed along to Hezron, and went up to Adar, and fetched a compass to Karkaa: {Maalehacrebbim: or, the going up to Acrabbim}', 'and it went out to the south side to maalehacrabbim and passed along to zin and ascended up on the south side unto kadeshbarnea and passed along to hezron and went up to adar and fetched a compass to karkaa maalehacrebbim or the going up to acrabbim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 4, '{From thence} it passed toward Azmon, and went out unto the river of Egypt; and the goings out of that coast were at the sea: this shall be your south coast.', 'from thence it passed toward azmon and went out unto the river of egypt and the goings out of that coast were at the sea this shall be your south coast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 5, 'And the east border {was} the salt sea, {even} unto the end of Jordan. And {their} border in the north quarter {was} from the bay of the sea at the uttermost part of Jordan:', 'and the east border was the salt sea even unto the end of jordan and their border in the north quarter was from the bay of the sea at the uttermost part of jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 6, 'And the border went up to Bethhogla, and passed along by the north of Betharabah; and the border went up to the stone of Bohan the son of Reuben:', 'and the border went up to bethhogla and passed along by the north of betharabah and the border went up to the stone of bohan the son of reuben');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 7, 'And the border went up toward Debir from the valley of Achor, and so northward, looking toward Gilgal, that {is} before the going up to Adummim, which {is} on the south side of the river: and the border passed toward the waters of Enshemesh, and the goings out thereof were at Enrogel:', 'and the border went up toward debir from the valley of achor and so northward looking toward gilgal that is before the going up to adummim which is on the south side of the river and the border passed toward the waters of enshemesh and the goings out thereof were at enrogel');
