INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 15, 9, 'And the border was drawn from the top of the hill unto the fountain of the water of Nephtoah, and went out to the cities of mount Ephron; and the border was drawn to Baalah, which {is} Kirjathjearim:', 'and the border was drawn from the top of the hill unto the fountain of the water of nephtoah and went out to the cities of mount ephron and the border was drawn to baalah which is kirjathjearim');
