INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 16, 8, 'The border went out from Tappuah westward unto the river Kanah; and the goings out thereof were at the sea. This {is} the inheritance of the tribe of the children of Ephraim by their families.', 'the border went out from tappuah westward unto the river kanah and the goings out thereof were at the sea this is the inheritance of the tribe of the children of ephraim by their families');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 16, 9, 'And the separate cities for the children of Ephraim {were} among the inheritance of the children of Manasseh, all the cities with their villages.', 'and the separate cities for the children of ephraim were among the inheritance of the children of manasseh all the cities with their villages');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 16, 10, 'And they drave not out the Canaanites that dwelt in Gezer: but the Canaanites dwell among the Ephraimites unto this day, and serve under tribute.', 'and they drave not out the canaanites that dwelt in gezer but the canaanites dwell among the ephraimites unto this day and serve under tribute');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 1, 'There was also a lot for the tribe of Manasseh; for he {was} the firstborn of Joseph; {to wit}, for Machir the firstborn of Manasseh, the father of Gilead: because he was a man of war, therefore he had Gilead and Bashan.', 'there was also a lot for the tribe of manasseh for he was the firstborn of joseph to wit for machir the firstborn of manasseh the father of gilead because he was a man of war therefore he had gilead and bashan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 2, 'There was also {a lot} for the rest of the children of Manasseh by their families; for the children of Abiezer, and for the children of Helek, and for the children of Asriel, and for the children of Shechem, and for the children of Hepher, and for the children of Shemida: these {were} the male children of Manasseh the son of Joseph by their families. {Abiezer: also called, Jeezer}', 'there was also a lot for the rest of the children of manasseh by their families for the children of abiezer and for the children of helek and for the children of asriel and for the children of shechem and for the children of hepher and for the children of shemida these were the male children of manasseh the son of joseph by their families abiezer also called jeezer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 3, 'But Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, had no sons, but daughters: and these {are} the names of his daughters, Mahlah, and Noah, Hoglah, Milcah, and Tirzah.', 'but zelophehad the son of hepher the son of gilead the son of machir the son of manasseh had no sons but daughters and these are the names of his daughters mahlah and noah hoglah milcah and tirzah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 4, 'And they came near before Eleazar the priest, and before Joshua the son of Nun, and before the princes, saying, The LORD commanded Moses to give us an inheritance among our brethren. Therefore according to the commandment of the LORD he gave them an inheritance among the brethren of their father.', 'and they came near before eleazar the priest and before joshua the son of nun and before the princes saying the lord commanded moses to give us an inheritance among our brethren therefore according to the commandment of the lord he gave them an inheritance among the brethren of their father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 5, 'And there fell ten portions to Manasseh, beside the land of Gilead and Bashan, which {were} on the other side Jordan;', 'and there fell ten portions to manasseh beside the land of gilead and bashan which were on the other side jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 6, 'Because the daughters of Manasseh had an inheritance among his sons: and the rest of Manasseh''s sons had the land of Gilead.', 'because the daughters of manasseh had an inheritance among his sons and the rest of manasseh s sons had the land of gilead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 7, 'And the coast of Manasseh was from Asher to Michmethah, that {lieth} before Shechem; and the border went along on the right hand unto the inhabitants of Entappuah.', 'and the coast of manasseh was from asher to michmethah that lieth before shechem and the border went along on the right hand unto the inhabitants of entappuah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 8, '{Now} Manasseh had the land of Tappuah: but Tappuah on the border of Manasseh {belonged} to the children of Ephraim;', 'now manasseh had the land of tappuah but tappuah on the border of manasseh belonged to the children of ephraim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 9, 'And the coast descended unto the river Kanah, southward of the river: these cities of Ephraim {are} among the cities of Manasseh: the coast of Manasseh also {was} on the north side of the river, and the outgoings of it were at the sea: {river Kanah: or, brook of reeds}', 'and the coast descended unto the river kanah southward of the river these cities of ephraim are among the cities of manasseh the coast of manasseh also was on the north side of the river and the outgoings of it were at the sea river kanah or brook of reeds');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 10, 'Southward {it was} Ephraim''s, and northward {it was} Manasseh''s, and the sea is his border; and they met together in Asher on the north, and in Issachar on the east.', 'southward it was ephraim s and northward it was manasseh s and the sea is his border and they met together in asher on the north and in issachar on the east');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 11, 'And Manasseh had in Issachar and in Asher Bethshean and her towns, and Ibleam and her towns, and the inhabitants of Dor and her towns, and the inhabitants of Endor and her towns, and the inhabitants of Taanach and her towns, and the inhabitants of Megiddo and her towns, {even} three countries.', 'and manasseh had in issachar and in asher bethshean and her towns and ibleam and her towns and the inhabitants of dor and her towns and the inhabitants of endor and her towns and the inhabitants of taanach and her towns and the inhabitants of megiddo and her towns even three countries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 12, 'Yet the children of Manasseh could not drive out {the inhabitants of} those cities; but the Canaanites would dwell in that land.', 'yet the children of manasseh could not drive out the inhabitants of those cities but the canaanites would dwell in that land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 13, 'Yet it came to pass, when the children of Israel were waxen strong, that they put the Canaanites to tribute; but did not utterly drive them out.', 'yet it came to pass when the children of israel were waxen strong that they put the canaanites to tribute but did not utterly drive them out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 14, 'And the children of Joseph spake unto Joshua, saying, Why hast thou given me {but} one lot and one portion to inherit, seeing I {am} a great people, forasmuch as the LORD hath blessed me hitherto?', 'and the children of joseph spake unto joshua saying why hast thou given me but one lot and one portion to inherit seeing i am a great people forasmuch as the lord hath blessed me hitherto');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 15, 'And Joshua answered them, If thou {be} a great people, {then} get thee up to the wood {country}, and cut down for thyself there in the land of the Perizzites and of the giants, if mount Ephraim be too narrow for thee. {giants: or, Rephaims}', 'and joshua answered them if thou be a great people then get thee up to the wood country and cut down for thyself there in the land of the perizzites and of the giants if mount ephraim be too narrow for thee giants or rephaims');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 16, 'And the children of Joseph said, The hill is not enough for us: and all the Canaanites that dwell in the land of the valley have chariots of iron, {both they} who {are} of Bethshean and her towns, and {they} who {are} of the valley of Jezreel.', 'and the children of joseph said the hill is not enough for us and all the canaanites that dwell in the land of the valley have chariots of iron both they who are of bethshean and her towns and they who are of the valley of jezreel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 17, 'And Joshua spake unto the house of Joseph, {even} to Ephraim and to Manasseh, saying, Thou {art} a great people, and hast great power: thou shalt not have one lot {only}:', 'and joshua spake unto the house of joseph even to ephraim and to manasseh saying thou art a great people and hast great power thou shalt not have one lot only');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 17, 18, 'But the mountain shall be thine; for it {is} a wood, and thou shalt cut it down: and the outgoings of it shall be thine: for thou shalt drive out the Canaanites, though they have iron chariots, {and} though they {be} strong.', 'but the mountain shall be thine for it is a wood and thou shalt cut it down and the outgoings of it shall be thine for thou shalt drive out the canaanites though they have iron chariots and though they be strong');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 1, 'And the whole congregation of the children of Israel assembled together at Shiloh, and set up the tabernacle of the congregation there. And the land was subdued before them.', 'and the whole congregation of the children of israel assembled together at shiloh and set up the tabernacle of the congregation there and the land was subdued before them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 2, 'And there remained among the children of Israel seven tribes, which had not yet received their inheritance.', 'and there remained among the children of israel seven tribes which had not yet received their inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 3, 'And Joshua said unto the children of Israel, How long {are} ye slack to go to possess the land, which the LORD God of your fathers hath given you?', 'and joshua said unto the children of israel how long are ye slack to go to possess the land which the lord god of your fathers hath given you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 4, 'Give out from among you three men for {each} tribe: and I will send them, and they shall rise, and go through the land, and describe it according to the inheritance of them; and they shall come {again} to me.', 'give out from among you three men for each tribe and i will send them and they shall rise and go through the land and describe it according to the inheritance of them and they shall come again to me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 5, 'And they shall divide it into seven parts: Judah shall abide in their coast on the south, and the house of Joseph shall abide in their coasts on the north.', 'and they shall divide it into seven parts judah shall abide in their coast on the south and the house of joseph shall abide in their coasts on the north');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 6, 'Ye shall therefore describe the land {into} seven parts, and bring {the description} hither to me, that I may cast lots for you here before the LORD our God.', 'ye shall therefore describe the land into seven parts and bring the description hither to me that i may cast lots for you here before the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 7, 'But the Levites have no part among you; for the priesthood of the LORD {is} their inheritance: and Gad, and Reuben, and half the tribe of Manasseh, have received their inheritance beyond Jordan on the east, which Moses the servant of the LORD gave them.', 'but the levites have no part among you for the priesthood of the lord is their inheritance and gad and reuben and half the tribe of manasseh have received their inheritance beyond jordan on the east which moses the servant of the lord gave them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 8, 'And the men arose, and went away: and Joshua charged them that went to describe the land, saying, Go and walk through the land, and describe it, and come again to me, that I may here cast lots for you before the LORD in Shiloh.', 'and the men arose and went away and joshua charged them that went to describe the land saying go and walk through the land and describe it and come again to me that i may here cast lots for you before the lord in shiloh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 9, 'And the men went and passed through the land, and described it by cities into seven parts in a book, and came {again} to Joshua to the host at Shiloh.', 'and the men went and passed through the land and described it by cities into seven parts in a book and came again to joshua to the host at shiloh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 10, 'And Joshua cast lots for them in Shiloh before the LORD: and there Joshua divided the land unto the children of Israel according to their divisions.', 'and joshua cast lots for them in shiloh before the lord and there joshua divided the land unto the children of israel according to their divisions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 11, 'And the lot of the tribe of the children of Benjamin came up according to their families: and the coast of their lot came forth between the children of Judah and the children of Joseph.', 'and the lot of the tribe of the children of benjamin came up according to their families and the coast of their lot came forth between the children of judah and the children of joseph');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 12, 'And their border on the north side was from Jordan; and the border went up to the side of Jericho on the north side, and went up through the mountains westward; and the goings out thereof were at the wilderness of Bethaven.', 'and their border on the north side was from jordan and the border went up to the side of jericho on the north side and went up through the mountains westward and the goings out thereof were at the wilderness of bethaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 13, 'And the border went over from thence toward Luz, to the side of Luz, which {is} Bethel, southward; and the border descended to Atarothadar, near the hill that {lieth} on the south side of the nether Bethhoron.', 'and the border went over from thence toward luz to the side of luz which is bethel southward and the border descended to atarothadar near the hill that lieth on the south side of the nether bethhoron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 14, 'And the border was drawn {thence}, and compassed the corner of the sea southward, from the hill that {lieth} before Bethhoron southward; and the goings out thereof were at Kirjathbaal, which {is} Kirjathjearim, a city of the children of Judah: this {was} the west quarter.', 'and the border was drawn thence and compassed the corner of the sea southward from the hill that lieth before bethhoron southward and the goings out thereof were at kirjathbaal which is kirjathjearim a city of the children of judah this was the west quarter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 15, 'And the south quarter {was} from the end of Kirjathjearim, and the border went out on the west, and went out to the well of waters of Nephtoah:', 'and the south quarter was from the end of kirjathjearim and the border went out on the west and went out to the well of waters of nephtoah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 16, 'And the border came down to the end of the mountain that {lieth} before the valley of the son of Hinnom, {and} which {is} in the valley of the giants on the north, and descended to the valley of Hinnom, to the side of Jebusi on the south, and descended to Enrogel,', 'and the border came down to the end of the mountain that lieth before the valley of the son of hinnom and which is in the valley of the giants on the north and descended to the valley of hinnom to the side of jebusi on the south and descended to enrogel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 17, 'And was drawn from the north, and went forth to Enshemesh, and went forth toward Geliloth, which {is} over against the going up of Adummim, and descended to the stone of Bohan the son of Reuben,', 'and was drawn from the north and went forth to enshemesh and went forth toward geliloth which is over against the going up of adummim and descended to the stone of bohan the son of reuben');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 18, 18, 'And passed along toward the side over against Arabah northward, and went down unto Arabah: {Arabah: or, the plain}', 'and passed along toward the side over against arabah northward and went down unto arabah arabah or the plain');
