INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 19, 9, 'Out of the portion of the children of Judah {was} the inheritance of the children of Simeon: for the part of the children of Judah was too much for them: therefore the children of Simeon had their inheritance within the inheritance of them.', 'out of the portion of the children of judah was the inheritance of the children of simeon for the part of the children of judah was too much for them therefore the children of simeon had their inheritance within the inheritance of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 19, 10, 'And the third lot came up for the children of Zebulun according to their families: and the border of their inheritance was unto Sarid:', 'and the third lot came up for the children of zebulun according to their families and the border of their inheritance was unto sarid');
