INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 19, 47, 'And the coast of the children of Dan went out {too little} for them: therefore the children of Dan went up to fight against Leshem, and took it, and smote it with the edge of the sword, and possessed it, and dwelt therein, and called Leshem, Dan, after the name of Dan their father.', 'and the coast of the children of dan went out too little for them therefore the children of dan went up to fight against leshem and took it and smote it with the edge of the sword and possessed it and dwelt therein and called leshem dan after the name of dan their father');
