INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 19, 49, 'When they had made an end of dividing the land for inheritance by their coasts, the children of Israel gave an inheritance to Joshua the son of Nun among them:', 'when they had made an end of dividing the land for inheritance by their coasts the children of israel gave an inheritance to joshua the son of nun among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 19, 50, 'According to the word of the LORD they gave him the city which he asked, {even} Timnathserah in mount Ephraim: and he built the city, and dwelt therein.', 'according to the word of the lord they gave him the city which he asked even timnathserah in mount ephraim and he built the city and dwelt therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 19, 51, 'These {are} the inheritances, which Eleazar the priest, and Joshua the son of Nun, and the heads of the fathers of the tribes of the children of Israel, divided for an inheritance by lot in Shiloh before the LORD, at the door of the tabernacle of the congregation. So they made an end of dividing the country.', 'these are the inheritances which eleazar the priest and joshua the son of nun and the heads of the fathers of the tribes of the children of israel divided for an inheritance by lot in shiloh before the lord at the door of the tabernacle of the congregation so they made an end of dividing the country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 1, 'The LORD also spake unto Joshua, saying,', 'the lord also spake unto joshua saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 2, 'Speak to the children of Israel, saying, Appoint out for you cities of refuge, whereof I spake unto you by the hand of Moses:', 'speak to the children of israel saying appoint out for you cities of refuge whereof i spake unto you by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 3, 'That the slayer that killeth {any} person unawares {and} unwittingly may flee thither: and they shall be your refuge from the avenger of blood.', 'that the slayer that killeth any person unawares and unwittingly may flee thither and they shall be your refuge from the avenger of blood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 4, 'And when he that doth flee unto one of those cities shall stand at the entering of the gate of the city, and shall declare his cause in the ears of the elders of that city, they shall take him into the city unto them, and give him a place, that he may dwell among them.', 'and when he that doth flee unto one of those cities shall stand at the entering of the gate of the city and shall declare his cause in the ears of the elders of that city they shall take him into the city unto them and give him a place that he may dwell among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 5, 'And if the avenger of blood pursue after him, then they shall not deliver the slayer up into his hand; because he smote his neighbour unwittingly, and hated him not beforetime.', 'and if the avenger of blood pursue after him then they shall not deliver the slayer up into his hand because he smote his neighbour unwittingly and hated him not beforetime');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 6, 'And he shall dwell in that city, until he stand before the congregation for judgment, {and} until the death of the high priest that shall be in those days: then shall the slayer return, and come unto his own city, and unto his own house, unto the city from whence he fled.', 'and he shall dwell in that city until he stand before the congregation for judgment and until the death of the high priest that shall be in those days then shall the slayer return and come unto his own city and unto his own house unto the city from whence he fled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 7, 'And they appointed Kedesh in Galilee in mount Naphtali, and Shechem in mount Ephraim, and Kirjatharba, which {is} Hebron, in the mountain of Judah. {appointed: Heb. sanctified}', 'and they appointed kedesh in galilee in mount naphtali and shechem in mount ephraim and kirjatharba which is hebron in the mountain of judah appointed heb sanctified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 8, 'And on the other side Jordan by Jericho eastward, they assigned Bezer in the wilderness upon the plain out of the tribe of Reuben, and Ramoth in Gilead out of the tribe of Gad, and Golan in Bashan out of the tribe of Manasseh.', 'and on the other side jordan by jericho eastward they assigned bezer in the wilderness upon the plain out of the tribe of reuben and ramoth in gilead out of the tribe of gad and golan in bashan out of the tribe of manasseh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 20, 9, 'These were the cities appointed for all the children of Israel, and for the stranger that sojourneth among them, that whosoever killeth {any} person at unawares might flee thither, and not die by the hand of the avenger of blood, until he stood before the congregation.', 'these were the cities appointed for all the children of israel and for the stranger that sojourneth among them that whosoever killeth any person at unawares might flee thither and not die by the hand of the avenger of blood until he stood before the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 1, 'Then came near the heads of the fathers of the Levites unto Eleazar the priest, and unto Joshua the son of Nun, and unto the heads of the fathers of the tribes of the children of Israel;', 'then came near the heads of the fathers of the levites unto eleazar the priest and unto joshua the son of nun and unto the heads of the fathers of the tribes of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 2, 'And they spake unto them at Shiloh in the land of Canaan, saying, The LORD commanded by the hand of Moses to give us cities to dwell in, with the suburbs thereof for our cattle.', 'and they spake unto them at shiloh in the land of canaan saying the lord commanded by the hand of moses to give us cities to dwell in with the suburbs thereof for our cattle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 3, 'And the children of Israel gave unto the Levites out of their inheritance, at the commandment of the LORD, these cities and their suburbs.', 'and the children of israel gave unto the levites out of their inheritance at the commandment of the lord these cities and their suburbs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 4, 'And the lot came out for the families of the Kohathites: and the children of Aaron the priest, {which were} of the Levites, had by lot out of the tribe of Judah, and out of the tribe of Simeon, and out of the tribe of Benjamin, thirteen cities.', 'and the lot came out for the families of the kohathites and the children of aaron the priest which were of the levites had by lot out of the tribe of judah and out of the tribe of simeon and out of the tribe of benjamin thirteen cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 5, 'And the rest of the children of Kohath {had} by lot out of the families of the tribe of Ephraim, and out of the tribe of Dan, and out of the half tribe of Manasseh, ten cities.', 'and the rest of the children of kohath had by lot out of the families of the tribe of ephraim and out of the tribe of dan and out of the half tribe of manasseh ten cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 6, 'And the children of Gershon {had} by lot out of the families of the tribe of Issachar, and out of the tribe of Asher, and out of the tribe of Naphtali, and out of the half tribe of Manasseh in Bashan, thirteen cities.', 'and the children of gershon had by lot out of the families of the tribe of issachar and out of the tribe of asher and out of the tribe of naphtali and out of the half tribe of manasseh in bashan thirteen cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 7, 'The children of Merari by their families {had} out of the tribe of Reuben, and out of the tribe of Gad, and out of the tribe of Zebulun, twelve cities.', 'the children of merari by their families had out of the tribe of reuben and out of the tribe of gad and out of the tribe of zebulun twelve cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 8, 'And the children of Israel gave by lot unto the Levites these cities with their suburbs, as the LORD commanded by the hand of Moses.', 'and the children of israel gave by lot unto the levites these cities with their suburbs as the lord commanded by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 9, 'And they gave out of the tribe of the children of Judah, and out of the tribe of the children of Simeon, these cities which are {here} mentioned by name, {mentioned: Heb. called}', 'and they gave out of the tribe of the children of judah and out of the tribe of the children of simeon these cities which are here mentioned by name mentioned heb called');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 10, 'Which the children of Aaron, {being} of the families of the Kohathites, {who were} of the children of Levi, had: for theirs was the first lot.', 'which the children of aaron being of the families of the kohathites who were of the children of levi had for theirs was the first lot');
