INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 43, 'And the LORD gave unto Israel all the land which he sware to give unto their fathers; and they possessed it, and dwelt therein.', 'and the lord gave unto israel all the land which he sware to give unto their fathers and they possessed it and dwelt therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 44, 'And the LORD gave them rest round about, according to all that he sware unto their fathers: and there stood not a man of all their enemies before them; the LORD delivered all their enemies into their hand.', 'and the lord gave them rest round about according to all that he sware unto their fathers and there stood not a man of all their enemies before them the lord delivered all their enemies into their hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 21, 45, 'There failed not ought of any good thing which the LORD had spoken unto the house of Israel; all came to pass.', 'there failed not ought of any good thing which the lord had spoken unto the house of israel all came to pass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 1, 'Then Joshua called the Reubenites, and the Gadites, and the half tribe of Manasseh,', 'then joshua called the reubenites and the gadites and the half tribe of manasseh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 2, 'And said unto them, Ye have kept all that Moses the servant of the LORD commanded you, and have obeyed my voice in all that I commanded you:', 'and said unto them ye have kept all that moses the servant of the lord commanded you and have obeyed my voice in all that i commanded you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 3, 'Ye have not left your brethren these many days unto this day, but have kept the charge of the commandment of the LORD your God.', 'ye have not left your brethren these many days unto this day but have kept the charge of the commandment of the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 4, 'And now the LORD your God hath given rest unto your brethren, as he promised them: therefore now return ye, and get you unto your tents, {and} unto the land of your possession, which Moses the servant of the LORD gave you on the other side Jordan.', 'and now the lord your god hath given rest unto your brethren as he promised them therefore now return ye and get you unto your tents and unto the land of your possession which moses the servant of the lord gave you on the other side jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 5, 'But take diligent heed to do the commandment and the law, which Moses the servant of the LORD charged you, to love the LORD your God, and to walk in all his ways, and to keep his commandments, and to cleave unto him, and to serve him with all your heart and with all your soul.', 'but take diligent heed to do the commandment and the law which moses the servant of the lord charged you to love the lord your god and to walk in all his ways and to keep his commandments and to cleave unto him and to serve him with all your heart and with all your soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 6, 'So Joshua blessed them, and sent them away: and they went unto their tents.', 'so joshua blessed them and sent them away and they went unto their tents');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 7, 'Now to the {one} half of the tribe of Manasseh Moses had given {possession} in Bashan: but unto the {other} half thereof gave Joshua among their brethren on this side Jordan westward. And when Joshua sent them away also unto their tents, then he blessed them,', 'now to the one half of the tribe of manasseh moses had given possession in bashan but unto the other half thereof gave joshua among their brethren on this side jordan westward and when joshua sent them away also unto their tents then he blessed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 8, 'And he spake unto them, saying, Return with much riches unto your tents, and with very much cattle, with silver, and with gold, and with brass, and with iron, and with very much raiment: divide the spoil of your enemies with your brethren.', 'and he spake unto them saying return with much riches unto your tents and with very much cattle with silver and with gold and with brass and with iron and with very much raiment divide the spoil of your enemies with your brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 9, 'And the children of Reuben and the children of Gad and the half tribe of Manasseh returned, and departed from the children of Israel out of Shiloh, which {is} in the land of Canaan, to go unto the country of Gilead, to the land of their possession, whereof they were possessed, according to the word of the LORD by the hand of Moses.', 'and the children of reuben and the children of gad and the half tribe of manasseh returned and departed from the children of israel out of shiloh which is in the land of canaan to go unto the country of gilead to the land of their possession whereof they were possessed according to the word of the lord by the hand of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 10, 'And when they came unto the borders of Jordan, that {are} in the land of Canaan, the children of Reuben and the children of Gad and the half tribe of Manasseh built there an altar by Jordan, a great altar to see to.', 'and when they came unto the borders of jordan that are in the land of canaan the children of reuben and the children of gad and the half tribe of manasseh built there an altar by jordan a great altar to see to');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 11, 'And the children of Israel heard say, Behold, the children of Reuben and the children of Gad and the half tribe of Manasseh have built an altar over against the land of Canaan, in the borders of Jordan, at the passage of the children of Israel.', 'and the children of israel heard say behold the children of reuben and the children of gad and the half tribe of manasseh have built an altar over against the land of canaan in the borders of jordan at the passage of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 12, 'And when the children of Israel heard {of it}, the whole congregation of the children of Israel gathered themselves together at Shiloh, to go up to war against them.', 'and when the children of israel heard of it the whole congregation of the children of israel gathered themselves together at shiloh to go up to war against them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 13, 'And the children of Israel sent unto the children of Reuben, and to the children of Gad, and to the half tribe of Manasseh, into the land of Gilead, Phinehas the son of Eleazar the priest,', 'and the children of israel sent unto the children of reuben and to the children of gad and to the half tribe of manasseh into the land of gilead phinehas the son of eleazar the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 14, 'And with him ten princes, of each chief house a prince throughout all the tribes of Israel; and each one {was} an head of the house of their fathers among the thousands of Israel. {chief...: Heb. house of the father}', 'and with him ten princes of each chief house a prince throughout all the tribes of israel and each one was an head of the house of their fathers among the thousands of israel chief heb house of the father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 15, 'And they came unto the children of Reuben, and to the children of Gad, and to the half tribe of Manasseh, unto the land of Gilead, and they spake with them, saying,', 'and they came unto the children of reuben and to the children of gad and to the half tribe of manasseh unto the land of gilead and they spake with them saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 16, 'Thus saith the whole congregation of the LORD, What trespass {is} this that ye have committed against the God of Israel, to turn away this day from following the LORD, in that ye have builded you an altar, that ye might rebel this day against the LORD?', 'thus saith the whole congregation of the lord what trespass is this that ye have committed against the god of israel to turn away this day from following the lord in that ye have builded you an altar that ye might rebel this day against the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 17, '{Is} the iniquity of Peor too little for us, from which we are not cleansed until this day, although there was a plague in the congregation of the LORD,', 'is the iniquity of peor too little for us from which we are not cleansed until this day although there was a plague in the congregation of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 18, 'But that ye must turn away this day from following the LORD? and it will be, {seeing} ye rebel to day against the LORD, that to morrow he will be wroth with the whole congregation of Israel.', 'but that ye must turn away this day from following the lord and it will be seeing ye rebel to day against the lord that to morrow he will be wroth with the whole congregation of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 19, 'Notwithstanding, if the land of your possession {be} unclean, {then} pass ye over unto the land of the possession of the LORD, wherein the LORD''S tabernacle dwelleth, and take possession among us: but rebel not against the LORD, nor rebel against us, in building you an altar beside the altar of the LORD our God.', 'notwithstanding if the land of your possession be unclean then pass ye over unto the land of the possession of the lord wherein the lord s tabernacle dwelleth and take possession among us but rebel not against the lord nor rebel against us in building you an altar beside the altar of the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 20, 'Did not Achan the son of Zerah commit a trespass in the accursed thing, and wrath fell on all the congregation of Israel? and that man perished not alone in his iniquity.', 'did not achan the son of zerah commit a trespass in the accursed thing and wrath fell on all the congregation of israel and that man perished not alone in his iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 21, 'Then the children of Reuben and the children of Gad and the half tribe of Manasseh answered, and said unto the heads of the thousands of Israel,', 'then the children of reuben and the children of gad and the half tribe of manasseh answered and said unto the heads of the thousands of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 22, 'The LORD God of gods, the LORD God of gods, he knoweth, and Israel he shall know; if {it be} in rebellion, or if in transgression against the LORD, (save us not this day,)', 'the lord god of gods the lord god of gods he knoweth and israel he shall know if it be in rebellion or if in transgression against the lord save us not this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 23, 'That we have built us an altar to turn from following the LORD, or if to offer thereon burnt offering or meat offering, or if to offer peace offerings thereon, let the LORD himself require {it};', 'that we have built us an altar to turn from following the lord or if to offer thereon burnt offering or meat offering or if to offer peace offerings thereon let the lord himself require it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 24, 'And if we have not {rather} done it for fear of {this} thing, saying, In time to come your children might speak unto our children, saying, What have ye to do with the LORD God of Israel? {In time...: Heb. To morrow}', 'and if we have not rather done it for fear of this thing saying in time to come your children might speak unto our children saying what have ye to do with the lord god of israel in time heb to morrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 25, 'For the LORD hath made Jordan a border between us and you, ye children of Reuben and children of Gad; ye have no part in the LORD: so shall your children make our children cease from fearing the LORD.', 'for the lord hath made jordan a border between us and you ye children of reuben and children of gad ye have no part in the lord so shall your children make our children cease from fearing the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 26, 'Therefore we said, Let us now prepare to build us an altar, not for burnt offering, nor for sacrifice:', 'therefore we said let us now prepare to build us an altar not for burnt offering nor for sacrifice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 27, 'But {that} it {may be} a witness between us, and you, and our generations after us, that we might do the service of the LORD before him with our burnt offerings, and with our sacrifices, and with our peace offerings; that your children may not say to our children in time to come, Ye have no part in the LORD.', 'but that it may be a witness between us and you and our generations after us that we might do the service of the lord before him with our burnt offerings and with our sacrifices and with our peace offerings that your children may not say to our children in time to come ye have no part in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 28, 'Therefore said we, that it shall be, when they should {so} say to us or to our generations in time to come, that we may say {again}, Behold the pattern of the altar of the LORD, which our fathers made, not for burnt offerings, nor for sacrifices; but it {is} a witness between us and you.', 'therefore said we that it shall be when they should so say to us or to our generations in time to come that we may say again behold the pattern of the altar of the lord which our fathers made not for burnt offerings nor for sacrifices but it is a witness between us and you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 29, 'God forbid that we should rebel against the LORD, and turn this day from following the LORD, to build an altar for burnt offerings, for meat offerings, or for sacrifices, beside the altar of the LORD our God that {is} before his tabernacle.', 'god forbid that we should rebel against the lord and turn this day from following the lord to build an altar for burnt offerings for meat offerings or for sacrifices beside the altar of the lord our god that is before his tabernacle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 30, 'And when Phinehas the priest, and the princes of the congregation and heads of the thousands of Israel which {were} with him, heard the words that the children of Reuben and the children of Gad and the children of Manasseh spake, it pleased them. {pleased...: Heb. was good in their eyes}', 'and when phinehas the priest and the princes of the congregation and heads of the thousands of israel which were with him heard the words that the children of reuben and the children of gad and the children of manasseh spake it pleased them pleased heb was good in their eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 31, 'And Phinehas the son of Eleazar the priest said unto the children of Reuben, and to the children of Gad, and to the children of Manasseh, This day we perceive that the LORD {is} among us, because ye have not committed this trespass against the LORD: now ye have delivered the children of Israel out of the hand of the LORD. {now: Heb. then}', 'and phinehas the son of eleazar the priest said unto the children of reuben and to the children of gad and to the children of manasseh this day we perceive that the lord is among us because ye have not committed this trespass against the lord now ye have delivered the children of israel out of the hand of the lord now heb then');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 32, 'And Phinehas the son of Eleazar the priest, and the princes, returned from the children of Reuben, and from the children of Gad, out of the land of Gilead, unto the land of Canaan, to the children of Israel, and brought them word again.', 'and phinehas the son of eleazar the priest and the princes returned from the children of reuben and from the children of gad out of the land of gilead unto the land of canaan to the children of israel and brought them word again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 33, 'And the thing pleased the children of Israel; and the children of Israel blessed God, and did not intend to go up against them in battle, to destroy the land wherein the children of Reuben and Gad dwelt.', 'and the thing pleased the children of israel and the children of israel blessed god and did not intend to go up against them in battle to destroy the land wherein the children of reuben and gad dwelt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 22, 34, 'And the children of Reuben and the children of Gad called the altar {Ed}: for it {shall be} a witness between us that the LORD {is} God. {Ed: that is, A witness}', 'and the children of reuben and the children of gad called the altar ed for it shall be a witness between us that the lord is god ed that is a witness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 1, 'And it came to pass a long time after that the LORD had given rest unto Israel from all their enemies round about, that Joshua waxed old {and} stricken in age. {stricken...: Heb. come into days}', 'and it came to pass a long time after that the lord had given rest unto israel from all their enemies round about that joshua waxed old and stricken in age stricken heb come into days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 2, 'And Joshua called for all Israel, {and} for their elders, and for their heads, and for their judges, and for their officers, and said unto them, I am old {and} stricken in age:', 'and joshua called for all israel and for their elders and for their heads and for their judges and for their officers and said unto them i am old and stricken in age');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 3, 'And ye have seen all that the LORD your God hath done unto all these nations because of you; for the LORD your God {is} he that hath fought for you.', 'and ye have seen all that the lord your god hath done unto all these nations because of you for the lord your god is he that hath fought for you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 4, 'Behold, I have divided unto you by lot these nations that remain, to be an inheritance for your tribes, from Jordan, with all the nations that I have cut off, even unto the great sea westward. {westward: Heb. at the sunset}', 'behold i have divided unto you by lot these nations that remain to be an inheritance for your tribes from jordan with all the nations that i have cut off even unto the great sea westward westward heb at the sunset');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 5, 'And the LORD your God, he shall expel them from before you, and drive them from out of your sight; and ye shall possess their land, as the LORD your God hath promised unto you.', 'and the lord your god he shall expel them from before you and drive them from out of your sight and ye shall possess their land as the lord your god hath promised unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 6, 'Be ye therefore very courageous to keep and to do all that is written in the book of the law of Moses, that ye turn not aside therefrom {to} the right hand or {to} the left;', 'be ye therefore very courageous to keep and to do all that is written in the book of the law of moses that ye turn not aside therefrom to the right hand or to the left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 7, 'That ye come not among these nations, these that remain among you; neither make mention of the name of their gods, nor cause to swear {by them}, neither serve them, nor bow yourselves unto them:', 'that ye come not among these nations these that remain among you neither make mention of the name of their gods nor cause to swear by them neither serve them nor bow yourselves unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 8, 'But cleave unto the LORD your God, as ye have done unto this day. {But cleave...: or, For if ye will cleave, etc}', 'but cleave unto the lord your god as ye have done unto this day but cleave or for if ye will cleave etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 9, 'For the LORD hath driven out from before you great nations and strong: but {as for} you, no man hath been able to stand before you unto this day. {For the LORD...: or, Then the LORD will drive}', 'for the lord hath driven out from before you great nations and strong but as for you no man hath been able to stand before you unto this day for the lord or then the lord will drive');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 10, 'One man of you shall chase a thousand: for the LORD your God, he {it is} that fighteth for you, as he hath promised you.', 'one man of you shall chase a thousand for the lord your god he it is that fighteth for you as he hath promised you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 11, 'Take good heed therefore unto yourselves, that ye love the LORD your God. {yourselves: Heb. your souls}', 'take good heed therefore unto yourselves that ye love the lord your god yourselves heb your souls');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 12, 'Else if ye do in any wise go back, and cleave unto the remnant of these nations, {even} these that remain among you, and shall make marriages with them, and go in unto them, and they to you:', 'else if ye do in any wise go back and cleave unto the remnant of these nations even these that remain among you and shall make marriages with them and go in unto them and they to you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 13, 'Know for a certainty that the LORD your God will no more drive out {any of} these nations from before you; but they shall be snares and traps unto you, and scourges in your sides, and thorns in your eyes, until ye perish from off this good land which the LORD your God hath given you.', 'know for a certainty that the lord your god will no more drive out any of these nations from before you but they shall be snares and traps unto you and scourges in your sides and thorns in your eyes until ye perish from off this good land which the lord your god hath given you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 14, 'And, behold, this day I {am} going the way of all the earth: and ye know in all your hearts and in all your souls, that not one thing hath failed of all the good things which the LORD your God spake concerning you; all are come to pass unto you, {and} not one thing hath failed thereof.', 'and behold this day i am going the way of all the earth and ye know in all your hearts and in all your souls that not one thing hath failed of all the good things which the lord your god spake concerning you all are come to pass unto you and not one thing hath failed thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 15, 'Therefore it shall come to pass, {that} as all good things are come upon you, which the LORD your God promised you; so shall the LORD bring upon you all evil things, until he have destroyed you from off this good land which the LORD your God hath given you.', 'therefore it shall come to pass that as all good things are come upon you which the lord your god promised you so shall the lord bring upon you all evil things until he have destroyed you from off this good land which the lord your god hath given you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 23, 16, 'When ye have transgressed the covenant of the LORD your God, which he commanded you, and have gone and served other gods, and bowed yourselves to them; then shall the anger of the LORD be kindled against you, and ye shall perish quickly from off the good land which he hath given unto you.', 'when ye have transgressed the covenant of the lord your god which he commanded you and have gone and served other gods and bowed yourselves to them then shall the anger of the lord be kindled against you and ye shall perish quickly from off the good land which he hath given unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 1, 'And Joshua gathered all the tribes of Israel to Shechem, and called for the elders of Israel, and for their heads, and for their judges, and for their officers; and they presented themselves before God.', 'and joshua gathered all the tribes of israel to shechem and called for the elders of israel and for their heads and for their judges and for their officers and they presented themselves before god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 2, 'And Joshua said unto all the people, Thus saith the LORD God of Israel, Your fathers dwelt on the other side of the flood in old time, {even} Terah, the father of Abraham, and the father of Nachor: and they served other gods.', 'and joshua said unto all the people thus saith the lord god of israel your fathers dwelt on the other side of the flood in old time even terah the father of abraham and the father of nachor and they served other gods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 3, 'And I took your father Abraham from the other side of the flood, and led him throughout all the land of Canaan, and multiplied his seed, and gave him Isaac.', 'and i took your father abraham from the other side of the flood and led him throughout all the land of canaan and multiplied his seed and gave him isaac');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 4, 'And I gave unto Isaac Jacob and Esau: and I gave unto Esau mount Seir, to possess it; but Jacob and his children went down into Egypt.', 'and i gave unto isaac jacob and esau and i gave unto esau mount seir to possess it but jacob and his children went down into egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 5, 'I sent Moses also and Aaron, and I plagued Egypt, according to that which I did among them: and afterward I brought you out.', 'i sent moses also and aaron and i plagued egypt according to that which i did among them and afterward i brought you out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 6, 'And I brought your fathers out of Egypt: and ye came unto the sea; and the Egyptians pursued after your fathers with chariots and horsemen unto the Red sea.', 'and i brought your fathers out of egypt and ye came unto the sea and the egyptians pursued after your fathers with chariots and horsemen unto the red sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 7, 'And when they cried unto the LORD, he put darkness between you and the Egyptians, and brought the sea upon them, and covered them; and your eyes have seen what I have done in Egypt: and ye dwelt in the wilderness a long season.', 'and when they cried unto the lord he put darkness between you and the egyptians and brought the sea upon them and covered them and your eyes have seen what i have done in egypt and ye dwelt in the wilderness a long season');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 8, 'And I brought you into the land of the Amorites, which dwelt on the other side Jordan; and they fought with you: and I gave them into your hand, that ye might possess their land; and I destroyed them from before you.', 'and i brought you into the land of the amorites which dwelt on the other side jordan and they fought with you and i gave them into your hand that ye might possess their land and i destroyed them from before you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 9, 'Then Balak the son of Zippor, king of Moab, arose and warred against Israel, and sent and called Balaam the son of Beor to curse you:', 'then balak the son of zippor king of moab arose and warred against israel and sent and called balaam the son of beor to curse you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 10, 'But I would not hearken unto Balaam; therefore he blessed you still: so I delivered you out of his hand.', 'but i would not hearken unto balaam therefore he blessed you still so i delivered you out of his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 11, 'And ye went over Jordan, and came unto Jericho: and the men of Jericho fought against you, the Amorites, and the Perizzites, and the Canaanites, and the Hittites, and the Girgashites, the Hivites, and the Jebusites; and I delivered them into your hand.', 'and ye went over jordan and came unto jericho and the men of jericho fought against you the amorites and the perizzites and the canaanites and the hittites and the girgashites the hivites and the jebusites and i delivered them into your hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 12, 'And I sent the hornet before you, which drave them out from before you, {even} the two kings of the Amorites; {but} not with thy sword, nor with thy bow.', 'and i sent the hornet before you which drave them out from before you even the two kings of the amorites but not with thy sword nor with thy bow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 13, 'And I have given you a land for which ye did not labour, and cities which ye built not, and ye dwell in them; of the vineyards and oliveyards which ye planted not do ye eat.', 'and i have given you a land for which ye did not labour and cities which ye built not and ye dwell in them of the vineyards and oliveyards which ye planted not do ye eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 14, 'Now therefore fear the LORD, and serve him in sincerity and in truth: and put away the gods which your fathers served on the other side of the flood, and in Egypt; and serve ye the LORD.', 'now therefore fear the lord and serve him in sincerity and in truth and put away the gods which your fathers served on the other side of the flood and in egypt and serve ye the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 15, 'And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that {were} on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.', 'and if it seem evil unto you to serve the lord choose you this day whom ye will serve whether the gods which your fathers served that were on the other side of the flood or the gods of the amorites in whose land ye dwell but as for me and my house we will serve the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 16, 'And the people answered and said, God forbid that we should forsake the LORD, to serve other gods;', 'and the people answered and said god forbid that we should forsake the lord to serve other gods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 17, 'For the LORD our God, he {it is} that brought us up and our fathers out of the land of Egypt, from the house of bondage, and which did those great signs in our sight, and preserved us in all the way wherein we went, and among all the people through whom we passed:', 'for the lord our god he it is that brought us up and our fathers out of the land of egypt from the house of bondage and which did those great signs in our sight and preserved us in all the way wherein we went and among all the people through whom we passed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 18, 'And the LORD drave out from before us all the people, even the Amorites which dwelt in the land: {therefore} will we also serve the LORD; for he {is} our God.', 'and the lord drave out from before us all the people even the amorites which dwelt in the land therefore will we also serve the lord for he is our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 19, 'And Joshua said unto the people, Ye cannot serve the LORD: for he {is} an holy God; he {is} a jealous God; he will not forgive your transgressions nor your sins. {holy God: Heb. holy Gods}', 'and joshua said unto the people ye cannot serve the lord for he is an holy god he is a jealous god he will not forgive your transgressions nor your sins holy god heb holy gods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 20, 'If ye forsake the LORD, and serve strange gods, then he will turn and do you hurt, and consume you, after that he hath done you good.', 'if ye forsake the lord and serve strange gods then he will turn and do you hurt and consume you after that he hath done you good');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 21, 'And the people said unto Joshua, Nay; but we will serve the LORD.', 'and the people said unto joshua nay but we will serve the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 22, 'And Joshua said unto the people, Ye {are} witnesses against yourselves that ye have chosen you the LORD, to serve him. And they said, {We are} witnesses.', 'and joshua said unto the people ye are witnesses against yourselves that ye have chosen you the lord to serve him and they said we are witnesses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 23, 'Now therefore put away, {said he}, the strange gods which {are} among you, and incline your heart unto the LORD God of Israel.', 'now therefore put away said he the strange gods which are among you and incline your heart unto the lord god of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 24, 'And the people said unto Joshua, The LORD our God will we serve, and his voice will we obey.', 'and the people said unto joshua the lord our god will we serve and his voice will we obey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 25, 'So Joshua made a covenant with the people that day, and set them a statute and an ordinance in Shechem.', 'so joshua made a covenant with the people that day and set them a statute and an ordinance in shechem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 26, 'And Joshua wrote these words in the book of the law of God, and took a great stone, and set it up there under an oak, that {was} by the sanctuary of the LORD.', 'and joshua wrote these words in the book of the law of god and took a great stone and set it up there under an oak that was by the sanctuary of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 27, 'And Joshua said unto all the people, Behold, this stone shall be a witness unto us; for it hath heard all the words of the LORD which he spake unto us: it shall be therefore a witness unto you, lest ye deny your God.', 'and joshua said unto all the people behold this stone shall be a witness unto us for it hath heard all the words of the lord which he spake unto us it shall be therefore a witness unto you lest ye deny your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 28, 'So Joshua let the people depart, every man unto his inheritance.', 'so joshua let the people depart every man unto his inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 29, 'And it came to pass after these things, that Joshua the son of Nun, the servant of the LORD, died, {being} an hundred and ten years old.', 'and it came to pass after these things that joshua the son of nun the servant of the lord died being an hundred and ten years old');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 30, 'And they buried him in the border of his inheritance in Timnathserah, which {is} in mount Ephraim, on the north side of the hill of Gaash.', 'and they buried him in the border of his inheritance in timnathserah which is in mount ephraim on the north side of the hill of gaash');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 31, 'And Israel served the LORD all the days of Joshua, and all the days of the elders that overlived Joshua, and which had known all the works of the LORD, that he had done for Israel. {overlived...: Heb. prolonged their days after Joshua}', 'and israel served the lord all the days of joshua and all the days of the elders that overlived joshua and which had known all the works of the lord that he had done for israel overlived heb prolonged their days after joshua');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 32, 'And the bones of Joseph, which the children of Israel brought up out of Egypt, buried they in Shechem, in a parcel of ground which Jacob bought of the sons of Hamor the father of Shechem for an hundred pieces of silver: and it became the inheritance of the children of Joseph. {pieces...: or, lambs}', 'and the bones of joseph which the children of israel brought up out of egypt buried they in shechem in a parcel of ground which jacob bought of the sons of hamor the father of shechem for an hundred pieces of silver and it became the inheritance of the children of joseph pieces or lambs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 6, 'Unknown', 24, 33, 'And Eleazar the son of Aaron died; and they buried him in a hill {that pertained to} Phinehas his son, which was given him in mount Ephraim.', 'and eleazar the son of aaron died and they buried him in a hill that pertained to phinehas his son which was given him in mount ephraim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 1, 'Now after the death of Joshua it came to pass, that the children of Israel asked the LORD, saying, Who shall go up for us against the Canaanites first, to fight against them?', 'now after the death of joshua it came to pass that the children of israel asked the lord saying who shall go up for us against the canaanites first to fight against them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 2, 'And the LORD said, Judah shall go up: behold, I have delivered the land into his hand.', 'and the lord said judah shall go up behold i have delivered the land into his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 3, 'And Judah said unto Simeon his brother, Come up with me into my lot, that we may fight against the Canaanites; and I likewise will go with thee into thy lot. So Simeon went with him.', 'and judah said unto simeon his brother come up with me into my lot that we may fight against the canaanites and i likewise will go with thee into thy lot so simeon went with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 4, 'And Judah went up; and the LORD delivered the Canaanites and the Perizzites into their hand: and they slew of them in Bezek ten thousand men.', 'and judah went up and the lord delivered the canaanites and the perizzites into their hand and they slew of them in bezek ten thousand men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 5, 'And they found Adonibezek in Bezek: and they fought against him, and they slew the Canaanites and the Perizzites.', 'and they found adonibezek in bezek and they fought against him and they slew the canaanites and the perizzites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 6, 'But Adonibezek fled; and they pursued after him, and caught him, and cut off his thumbs and his great toes.', 'but adonibezek fled and they pursued after him and caught him and cut off his thumbs and his great toes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 7, 'And Adonibezek said, Threescore and ten kings, having their thumbs and their great toes cut off, gathered {their meat} under my table: as I have done, so God hath requited me. And they brought him to Jerusalem, and there he died. {their thumbs...: Heb. the thumbs of their hands and of their feet} {gathered: or, gleaned}', 'and adonibezek said threescore and ten kings having their thumbs and their great toes cut off gathered their meat under my table as i have done so god hath requited me and they brought him to jerusalem and there he died their thumbs heb the thumbs of their hands and of their feet gathered or gleaned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 8, 'Now the children of Judah had fought against Jerusalem, and had taken it, and smitten it with the edge of the sword, and set the city on fire.', 'now the children of judah had fought against jerusalem and had taken it and smitten it with the edge of the sword and set the city on fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 9, 'And afterward the children of Judah went down to fight against the Canaanites, that dwelt in the mountain, and in the south, and in the valley. {valley: or, low country}', 'and afterward the children of judah went down to fight against the canaanites that dwelt in the mountain and in the south and in the valley valley or low country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 10, 'And Judah went against the Canaanites that dwelt in Hebron: (now the name of Hebron before {was} Kirjatharba:) and they slew Sheshai, and Ahiman, and Talmai.', 'and judah went against the canaanites that dwelt in hebron now the name of hebron before was kirjatharba and they slew sheshai and ahiman and talmai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 11, 'And from thence he went against the inhabitants of Debir: and the name of Debir before {was} Kirjathsepher:', 'and from thence he went against the inhabitants of debir and the name of debir before was kirjathsepher');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 12, 'And Caleb said, He that smiteth Kirjathsepher, and taketh it, to him will I give Achsah my daughter to wife.', 'and caleb said he that smiteth kirjathsepher and taketh it to him will i give achsah my daughter to wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 13, 'And Othniel the son of Kenaz, Caleb''s younger brother, took it: and he gave him Achsah his daughter to wife.', 'and othniel the son of kenaz caleb s younger brother took it and he gave him achsah his daughter to wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 14, 'And it came to pass, when she came {to him}, that she moved him to ask of her father a field: and she lighted from off {her} ass; and Caleb said unto her, What wilt thou?', 'and it came to pass when she came to him that she moved him to ask of her father a field and she lighted from off her ass and caleb said unto her what wilt thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 15, 'And she said unto him, Give me a blessing: for thou hast given me a south land; give me also springs of water. And Caleb gave her the upper springs and the nether springs.', 'and she said unto him give me a blessing for thou hast given me a south land give me also springs of water and caleb gave her the upper springs and the nether springs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 16, 'And the children of the Kenite, Moses'' father in law, went up out of the city of palm trees with the children of Judah into the wilderness of Judah, which {lieth} in the south of Arad; and they went and dwelt among the people.', 'and the children of the kenite moses father in law went up out of the city of palm trees with the children of judah into the wilderness of judah which lieth in the south of arad and they went and dwelt among the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 17, 'And Judah went with Simeon his brother, and they slew the Canaanites that inhabited Zephath, and utterly destroyed it. And the name of the city was called Hormah.', 'and judah went with simeon his brother and they slew the canaanites that inhabited zephath and utterly destroyed it and the name of the city was called hormah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 18, 'Also Judah took Gaza with the coast thereof, and Askelon with the coast thereof, and Ekron with the coast thereof.', 'also judah took gaza with the coast thereof and askelon with the coast thereof and ekron with the coast thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 19, 'And the LORD was with Judah; and he drave out {the inhabitants of} the mountain; but could not drive out the inhabitants of the valley, because they had chariots of iron. {drave...: or, possessed the mountain}', 'and the lord was with judah and he drave out the inhabitants of the mountain but could not drive out the inhabitants of the valley because they had chariots of iron drave or possessed the mountain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 20, 'And they gave Hebron unto Caleb, as Moses said: and he expelled thence the three sons of Anak.', 'and they gave hebron unto caleb as moses said and he expelled thence the three sons of anak');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 21, 'And the children of Benjamin did not drive out the Jebusites that inhabited Jerusalem; but the Jebusites dwell with the children of Benjamin in Jerusalem unto this day.', 'and the children of benjamin did not drive out the jebusites that inhabited jerusalem but the jebusites dwell with the children of benjamin in jerusalem unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 22, 'And the house of Joseph, they also went up against Bethel: and the LORD {was} with them.', 'and the house of joseph they also went up against bethel and the lord was with them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 23, 'And the house of Joseph sent to descry Bethel. (Now the name of the city before {was} Luz.)', 'and the house of joseph sent to descry bethel now the name of the city before was luz');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 24, 'And the spies saw a man come forth out of the city, and they said unto him, Shew us, we pray thee, the entrance into the city, and we will shew thee mercy.', 'and the spies saw a man come forth out of the city and they said unto him shew us we pray thee the entrance into the city and we will shew thee mercy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 25, 'And when he shewed them the entrance into the city, they smote the city with the edge of the sword; but they let go the man and all his family.', 'and when he shewed them the entrance into the city they smote the city with the edge of the sword but they let go the man and all his family');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 26, 'And the man went into the land of the Hittites, and built a city, and called the name thereof Luz: which {is} the name thereof unto this day.', 'and the man went into the land of the hittites and built a city and called the name thereof luz which is the name thereof unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 27, 'Neither did Manasseh drive out {the inhabitants of} Bethshean and her towns, nor Taanach and her towns, nor the inhabitants of Dor and her towns, nor the inhabitants of Ibleam and her towns, nor the inhabitants of Megiddo and her towns: but the Canaanites would dwell in that land.', 'neither did manasseh drive out the inhabitants of bethshean and her towns nor taanach and her towns nor the inhabitants of dor and her towns nor the inhabitants of ibleam and her towns nor the inhabitants of megiddo and her towns but the canaanites would dwell in that land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 28, 'And it came to pass, when Israel was strong, that they put the Canaanites to tribute, and did not utterly drive them out.', 'and it came to pass when israel was strong that they put the canaanites to tribute and did not utterly drive them out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 29, 'Neither did Ephraim drive out the Canaanites that dwelt in Gezer; but the Canaanites dwelt in Gezer among them.', 'neither did ephraim drive out the canaanites that dwelt in gezer but the canaanites dwelt in gezer among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 30, 'Neither did Zebulun drive out the inhabitants of Kitron, nor the inhabitants of Nahalol; but the Canaanites dwelt among them, and became tributaries.', 'neither did zebulun drive out the inhabitants of kitron nor the inhabitants of nahalol but the canaanites dwelt among them and became tributaries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 31, 'Neither did Asher drive out the inhabitants of Accho, nor the inhabitants of Zidon, nor of Ahlab, nor of Achzib, nor of Helbah, nor of Aphik, nor of Rehob:', 'neither did asher drive out the inhabitants of accho nor the inhabitants of zidon nor of ahlab nor of achzib nor of helbah nor of aphik nor of rehob');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 32, 'But the Asherites dwelt among the Canaanites, the inhabitants of the land: for they did not drive them out.', 'but the asherites dwelt among the canaanites the inhabitants of the land for they did not drive them out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 33, 'Neither did Naphtali drive out the inhabitants of Bethshemesh, nor the inhabitants of Bethanath; but he dwelt among the Canaanites, the inhabitants of the land: nevertheless the inhabitants of Bethshemesh and of Bethanath became tributaries unto them.', 'neither did naphtali drive out the inhabitants of bethshemesh nor the inhabitants of bethanath but he dwelt among the canaanites the inhabitants of the land nevertheless the inhabitants of bethshemesh and of bethanath became tributaries unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 34, 'And the Amorites forced the children of Dan into the mountain: for they would not suffer them to come down to the valley:', 'and the amorites forced the children of dan into the mountain for they would not suffer them to come down to the valley');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 35, 'But the Amorites would dwell in mount Heres in Aijalon, and in Shaalbim: yet the hand of the house of Joseph prevailed, so that they became tributaries. {prevailed: Heb. was heavy}', 'but the amorites would dwell in mount heres in aijalon and in shaalbim yet the hand of the house of joseph prevailed so that they became tributaries prevailed heb was heavy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 1, 36, 'And the coast of the Amorites {was} from the going up to Akrabbim, from the rock, and upward. {the going...: or, Maalehacrabbim}', 'and the coast of the amorites was from the going up to akrabbim from the rock and upward the going or maalehacrabbim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 1, 'And an angel of the LORD came up from Gilgal to Bochim, and said, I made you to go up out of Egypt, and have brought you unto the land which I sware unto your fathers; and I said, I will never break my covenant with you. {angel: or, messenger}', 'and an angel of the lord came up from gilgal to bochim and said i made you to go up out of egypt and have brought you unto the land which i sware unto your fathers and i said i will never break my covenant with you angel or messenger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 2, 'And ye shall make no league with the inhabitants of this land; ye shall throw down their altars: but ye have not obeyed my voice: why have ye done this?', 'and ye shall make no league with the inhabitants of this land ye shall throw down their altars but ye have not obeyed my voice why have ye done this');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 3, 'Wherefore I also said, I will not drive them out from before you; but they shall be {as thorns} in your sides, and their gods shall be a snare unto you.', 'wherefore i also said i will not drive them out from before you but they shall be as thorns in your sides and their gods shall be a snare unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 4, 'And it came to pass, when the angel of the LORD spake these words unto all the children of Israel, that the people lifted up their voice, and wept.', 'and it came to pass when the angel of the lord spake these words unto all the children of israel that the people lifted up their voice and wept');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 5, 'And they called the name of that place Bochim: and they sacrificed there unto the LORD. {Bochim: that is, Weepers}', 'and they called the name of that place bochim and they sacrificed there unto the lord bochim that is weepers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 6, 'And when Joshua had let the people go, the children of Israel went every man unto his inheritance to possess the land.', 'and when joshua had let the people go the children of israel went every man unto his inheritance to possess the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 7, 'And the people served the LORD all the days of Joshua, and all the days of the elders that outlived Joshua, who had seen all the great works of the LORD, that he did for Israel. {outlived: Heb. prolonged days after}', 'and the people served the lord all the days of joshua and all the days of the elders that outlived joshua who had seen all the great works of the lord that he did for israel outlived heb prolonged days after');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 8, 'And Joshua the son of Nun, the servant of the LORD, died, {being} an hundred and ten years old.', 'and joshua the son of nun the servant of the lord died being an hundred and ten years old');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 9, 'And they buried him in the border of his inheritance in Timnathheres, in the mount of Ephraim, on the north side of the hill Gaash. {Timnathhares: also called, Timnathserah}', 'and they buried him in the border of his inheritance in timnathheres in the mount of ephraim on the north side of the hill gaash timnathhares also called timnathserah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 10, 'And also all that generation were gathered unto their fathers: and there arose another generation after them, which knew not the LORD, nor yet the works which he had done for Israel.', 'and also all that generation were gathered unto their fathers and there arose another generation after them which knew not the lord nor yet the works which he had done for israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 11, 'And the children of Israel did evil in the sight of the LORD, and served Baalim:', 'and the children of israel did evil in the sight of the lord and served baalim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 12, 'And they forsook the LORD God of their fathers, which brought them out of the land of Egypt, and followed other gods, of the gods of the people that {were} round about them, and bowed themselves unto them, and provoked the LORD to anger.', 'and they forsook the lord god of their fathers which brought them out of the land of egypt and followed other gods of the gods of the people that were round about them and bowed themselves unto them and provoked the lord to anger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 13, 'And they forsook the LORD, and served Baal and Ashtaroth.', 'and they forsook the lord and served baal and ashtaroth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 14, 'And the anger of the LORD was hot against Israel, and he delivered them into the hands of spoilers that spoiled them, and he sold them into the hands of their enemies round about, so that they could not any longer stand before their enemies.', 'and the anger of the lord was hot against israel and he delivered them into the hands of spoilers that spoiled them and he sold them into the hands of their enemies round about so that they could not any longer stand before their enemies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 15, 'Whithersoever they went out, the hand of the LORD was against them for evil, as the LORD had said, and as the LORD had sworn unto them: and they were greatly distressed.', 'whithersoever they went out the hand of the lord was against them for evil as the lord had said and as the lord had sworn unto them and they were greatly distressed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 16, 'Nevertheless the LORD raised up judges, which delivered them out of the hand of those that spoiled them. {delivered: Heb. saved}', 'nevertheless the lord raised up judges which delivered them out of the hand of those that spoiled them delivered heb saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 17, 'And yet they would not hearken unto their judges, but they went a whoring after other gods, and bowed themselves unto them: they turned quickly out of the way which their fathers walked in, obeying the commandments of the LORD; {but} they did not so.', 'and yet they would not hearken unto their judges but they went a whoring after other gods and bowed themselves unto them they turned quickly out of the way which their fathers walked in obeying the commandments of the lord but they did not so');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 18, 'And when the LORD raised them up judges, then the LORD was with the judge, and delivered them out of the hand of their enemies all the days of the judge: for it repented the LORD because of their groanings by reason of them that oppressed them and vexed them.', 'and when the lord raised them up judges then the lord was with the judge and delivered them out of the hand of their enemies all the days of the judge for it repented the lord because of their groanings by reason of them that oppressed them and vexed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 19, 'And it came to pass, when the judge was dead, {that} they returned, and corrupted {themselves} more than their fathers, in following other gods to serve them, and to bow down unto them; they ceased not from their own doings, nor from their stubborn way. {corrupted...: or, were corrupt} {ceased...: Heb. let nothing fall of their}', 'and it came to pass when the judge was dead that they returned and corrupted themselves more than their fathers in following other gods to serve them and to bow down unto them they ceased not from their own doings nor from their stubborn way corrupted or were corrupt ceased heb let nothing fall of their');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 20, 'And the anger of the LORD was hot against Israel; and he said, Because that this people hath transgressed my covenant which I commanded their fathers, and have not hearkened unto my voice;', 'and the anger of the lord was hot against israel and he said because that this people hath transgressed my covenant which i commanded their fathers and have not hearkened unto my voice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 2, 21, 'I also will not henceforth drive out any from before them of the nations which Joshua left when he died:', 'i also will not henceforth drive out any from before them of the nations which joshua left when he died');
