INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 4, 21, 'Then Jael Heber''s wife took a nail of the tent, and took an hammer in her hand, and went softly unto him, and smote the nail into his temples, and fastened it into the ground: for he was fast asleep and weary. So he died. {and took: Heb. and put}', 'then jael heber s wife took a nail of the tent and took an hammer in her hand and went softly unto him and smote the nail into his temples and fastened it into the ground for he was fast asleep and weary so he died and took heb and put');
