INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 13, 'And they passed thence unto mount Ephraim, and came unto the house of Micah.', 'and they passed thence unto mount ephraim and came unto the house of micah');
