INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 20, 'And the priest''s heart was glad, and he took the ephod, and the teraphim, and the graven image, and went in the midst of the people.', 'and the priest s heart was glad and he took the ephod and the teraphim and the graven image and went in the midst of the people');
