INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 23, 'And they cried unto the children of Dan. And they turned their faces, and said unto Micah, What aileth thee, that thou comest with such a company? {comest...: Heb. art gathered together?}', 'and they cried unto the children of dan and they turned their faces and said unto micah what aileth thee that thou comest with such a company comest heb art gathered together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 24, 'And he said, Ye have taken away my gods which I made, and the priest, and ye are gone away: and what have I more? and what {is} this {that} ye say unto me, What aileth thee?', 'and he said ye have taken away my gods which i made and the priest and ye are gone away and what have i more and what is this that ye say unto me what aileth thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 25, 'And the children of Dan said unto him, Let not thy voice be heard among us, lest angry fellows run upon thee, and thou lose thy life, with the lives of thy household. {angry: Heb. bitter of soul}', 'and the children of dan said unto him let not thy voice be heard among us lest angry fellows run upon thee and thou lose thy life with the lives of thy household angry heb bitter of soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 26, 'And the children of Dan went their way: and when Micah saw that they {were} too strong for him, he turned and went back unto his house.', 'and the children of dan went their way and when micah saw that they were too strong for him he turned and went back unto his house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 27, 'And they took {the things} which Micah had made, and the priest which he had, and came unto Laish, unto a people {that were} at quiet and secure: and they smote them with the edge of the sword, and burnt the city with fire.', 'and they took the things which micah had made and the priest which he had and came unto laish unto a people that were at quiet and secure and they smote them with the edge of the sword and burnt the city with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 28, 'And {there was} no deliverer, because it {was} far from Zidon, and they had no business with {any} man; and it was in the valley that {lieth} by Bethrehob. And they built a city, and dwelt therein.', 'and there was no deliverer because it was far from zidon and they had no business with any man and it was in the valley that lieth by bethrehob and they built a city and dwelt therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 29, 'And they called the name of the city Dan, after the name of Dan their father, who was born unto Israel: howbeit the name of the city {was} Laish at the first.', 'and they called the name of the city dan after the name of dan their father who was born unto israel howbeit the name of the city was laish at the first');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 18, 30, 'And the children of Dan set up the graven image: and Jonathan, the son of Gershom, the son of Manasseh, he and his sons were priests to the tribe of Dan until the day of the captivity of the land.', 'and the children of dan set up the graven image and jonathan the son of gershom the son of manasseh he and his sons were priests to the tribe of dan until the day of the captivity of the land');
