INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 8, 'And he arose early in the morning on the fifth day to depart: and the damsel''s father said, Comfort thine heart, I pray thee. And they tarried until afternoon, and they did eat both of them. {until afternoon: Heb. till the day declined}', 'and he arose early in the morning on the fifth day to depart and the damsel s father said comfort thine heart i pray thee and they tarried until afternoon and they did eat both of them until afternoon heb till the day declined');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 9, 'And when the man rose up to depart, he, and his concubine, and his servant, his father in law, the damsel''s father, said unto him, Behold, now the day draweth toward evening, I pray you tarry all night: behold, the day groweth to an end, lodge here, that thine heart may be merry; and to morrow get you early on your way, that thou mayest go home. {draweth: Heb. is weak} {the day groweth to an end: Heb. it is the pitching time of the day} {home: Heb. to thy tent}', 'and when the man rose up to depart he and his concubine and his servant his father in law the damsel s father said unto him behold now the day draweth toward evening i pray you tarry all night behold the day groweth to an end lodge here that thine heart may be merry and to morrow get you early on your way that thou mayest go home draweth heb is weak the day groweth to an end heb it is the pitching time of the day home heb to thy tent');
