INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 11, '{And} when they {were} by Jebus, the day was far spent; and the servant said unto his master, Come, I pray thee, and let us turn in into this city of the Jebusites, and lodge in it.', 'and when they were by jebus the day was far spent and the servant said unto his master come i pray thee and let us turn in into this city of the jebusites and lodge in it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 12, 'And his master said unto him, We will not turn aside hither into the city of a stranger, that {is} not of the children of Israel; we will pass over to Gibeah.', 'and his master said unto him we will not turn aside hither into the city of a stranger that is not of the children of israel we will pass over to gibeah');
