INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 17, 'And when he had lifted up his eyes, he saw a wayfaring man in the street of the city: and the old man said, Whither goest thou? and whence comest thou?', 'and when he had lifted up his eyes he saw a wayfaring man in the street of the city and the old man said whither goest thou and whence comest thou');
