INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 19, 'Yet there is both straw and provender for our asses; and there is bread and wine also for me, and for thy handmaid, and for the young man {which is} with thy servants: {there is} no want of any thing.', 'yet there is both straw and provender for our asses and there is bread and wine also for me and for thy handmaid and for the young man which is with thy servants there is no want of any thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 20, 'And the old man said, Peace {be} with thee; howsoever {let} all thy wants {lie} upon me; only lodge not in the street.', 'and the old man said peace be with thee howsoever let all thy wants lie upon me only lodge not in the street');
