INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 22, '{Now} as they were making their hearts merry, behold, the men of the city, certain sons of Belial, beset the house round about, {and} beat at the door, and spake to the master of the house, the old man, saying, Bring forth the man that came into thine house, that we may know him.', 'now as they were making their hearts merry behold the men of the city certain sons of belial beset the house round about and beat at the door and spake to the master of the house the old man saying bring forth the man that came into thine house that we may know him');
