INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 24, 'Behold, {here is} my daughter a maiden, and his concubine; them I will bring out now, and humble ye them, and do with them what seemeth good unto you: but unto this man do not so vile a thing. {so vile...: Heb. the matter of this folly}', 'behold here is my daughter a maiden and his concubine them i will bring out now and humble ye them and do with them what seemeth good unto you but unto this man do not so vile a thing so vile heb the matter of this folly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 25, 'But the men would not hearken to him: so the man took his concubine, and brought her forth unto them; and they knew her, and abused her all the night until the morning: and when the day began to spring, they let her go.', 'but the men would not hearken to him so the man took his concubine and brought her forth unto them and they knew her and abused her all the night until the morning and when the day began to spring they let her go');
