INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 19, 27, 'And her lord rose up in the morning, and opened the doors of the house, and went out to go his way: and, behold, the woman his concubine was fallen down {at} the door of the house, and her hands {were} upon the threshold.', 'and her lord rose up in the morning and opened the doors of the house and went out to go his way and behold the woman his concubine was fallen down at the door of the house and her hands were upon the threshold');
