INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 16, 'Among all this people {there were} seven hundred chosen men lefthanded; every one could sling stones at an hair {breadth}, and not miss.', 'among all this people there were seven hundred chosen men lefthanded every one could sling stones at an hair breadth and not miss');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 17, 'And the men of Israel, beside Benjamin, were numbered four hundred thousand men that drew sword: all these {were} men of war.', 'and the men of israel beside benjamin were numbered four hundred thousand men that drew sword all these were men of war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 18, 'And the children of Israel arose, and went up to the house of God, and asked counsel of God, and said, Which of us shall go up first to the battle against the children of Benjamin? And the LORD said, Judah {shall go up} first.', 'and the children of israel arose and went up to the house of god and asked counsel of god and said which of us shall go up first to the battle against the children of benjamin and the lord said judah shall go up first');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 19, 'And the children of Israel rose up in the morning, and encamped against Gibeah.', 'and the children of israel rose up in the morning and encamped against gibeah');
