INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 23, '(And the children of Israel went up and wept before the LORD until even, and asked counsel of the LORD, saying, Shall I go up again to battle against the children of Benjamin my brother? And the LORD said, Go up against him.)', 'and the children of israel went up and wept before the lord until even and asked counsel of the lord saying shall i go up again to battle against the children of benjamin my brother and the lord said go up against him');
