INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 26, 'Then all the children of Israel, and all the people, went up, and came unto the house of God, and wept, and sat there before the LORD, and fasted that day until even, and offered burnt offerings and peace offerings before the LORD.', 'then all the children of israel and all the people went up and came unto the house of god and wept and sat there before the lord and fasted that day until even and offered burnt offerings and peace offerings before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 27, 'And the children of Israel enquired of the LORD, (for the ark of the covenant of God {was} there in those days,', 'and the children of israel enquired of the lord for the ark of the covenant of god was there in those days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 28, 'And Phinehas, the son of Eleazar, the son of Aaron, stood before it in those days,) saying, Shall I yet again go out to battle against the children of Benjamin my brother, or shall I cease? And the LORD said, Go up; for to morrow I will deliver them into thine hand.', 'and phinehas the son of eleazar the son of aaron stood before it in those days saying shall i yet again go out to battle against the children of benjamin my brother or shall i cease and the lord said go up for to morrow i will deliver them into thine hand');
