INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 32, 'And the children of Benjamin said, They {are} smitten down before us, as at the first. But the children of Israel said, Let us flee, and draw them from the city unto the highways.', 'and the children of benjamin said they are smitten down before us as at the first but the children of israel said let us flee and draw them from the city unto the highways');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 33, 'And all the men of Israel rose up out of their place, and put themselves in array at Baaltamar: and the liers in wait of Israel came forth out of their places, {even} out of the meadows of Gibeah.', 'and all the men of israel rose up out of their place and put themselves in array at baaltamar and the liers in wait of israel came forth out of their places even out of the meadows of gibeah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 34, 'And there came against Gibeah ten thousand chosen men out of all Israel, and the battle was sore: but they knew not that evil {was} near them.', 'and there came against gibeah ten thousand chosen men out of all israel and the battle was sore but they knew not that evil was near them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 35, 'And the LORD smote Benjamin before Israel: and the children of Israel destroyed of the Benjamites that day twenty and five thousand and an hundred men: all these drew the sword.', 'and the lord smote benjamin before israel and the children of israel destroyed of the benjamites that day twenty and five thousand and an hundred men all these drew the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 36, 'So the children of Benjamin saw that they were smitten: for the men of Israel gave place to the Benjamites, because they trusted unto the liers in wait which they had set beside Gibeah.', 'so the children of benjamin saw that they were smitten for the men of israel gave place to the benjamites because they trusted unto the liers in wait which they had set beside gibeah');
