INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 40, 'But when the flame began to arise up out of the city with a pillar of smoke, the Benjamites looked behind them, and, behold, the flame of the city ascended up to heaven. {the flame of: Heb. the whole consumption of}', 'but when the flame began to arise up out of the city with a pillar of smoke the benjamites looked behind them and behold the flame of the city ascended up to heaven the flame of heb the whole consumption of');
