INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 42, 'Therefore they turned {their backs} before the men of Israel unto the way of the wilderness; but the battle overtook them; and them which {came} out of the cities they destroyed in the midst of them.', 'therefore they turned their backs before the men of israel unto the way of the wilderness but the battle overtook them and them which came out of the cities they destroyed in the midst of them');
