INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 44, 'And there fell of Benjamin eighteen thousand men; all these {were} men of valour.', 'and there fell of benjamin eighteen thousand men all these were men of valour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 45, 'And they turned and fled toward the wilderness unto the rock of Rimmon: and they gleaned of them in the highways five thousand men; and pursued hard after them unto Gidom, and slew two thousand men of them.', 'and they turned and fled toward the wilderness unto the rock of rimmon and they gleaned of them in the highways five thousand men and pursued hard after them unto gidom and slew two thousand men of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 46, 'So that all which fell that day of Benjamin were twenty and five thousand men that drew the sword; all these {were} men of valour.', 'so that all which fell that day of benjamin were twenty and five thousand men that drew the sword all these were men of valour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 20, 47, 'But six hundred men turned and fled to the wilderness unto the rock Rimmon, and abode in the rock Rimmon four months.', 'but six hundred men turned and fled to the wilderness unto the rock rimmon and abode in the rock rimmon four months');
