INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 5, 'And the children of Israel said, Who {is there} among all the tribes of Israel that came not up with the congregation unto the LORD? For they had made a great oath concerning him that came not up to the LORD to Mizpeh, saying, He shall surely be put to death.', 'and the children of israel said who is there among all the tribes of israel that came not up with the congregation unto the lord for they had made a great oath concerning him that came not up to the lord to mizpeh saying he shall surely be put to death');
