INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 7, 'How shall we do for wives for them that remain, seeing we have sworn by the LORD that we will not give them of our daughters to wives?', 'how shall we do for wives for them that remain seeing we have sworn by the lord that we will not give them of our daughters to wives');
