INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 11, 'And this {is} the thing that ye shall do, Ye shall utterly destroy every male, and every woman that hath lain by man. {hath lain...: Heb. knoweth the lying with man}', 'and this is the thing that ye shall do ye shall utterly destroy every male and every woman that hath lain by man hath lain heb knoweth the lying with man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 12, 'And they found among the inhabitants of Jabeshgilead four hundred young virgins, that had known no man by lying with any male: and they brought them unto the camp to Shiloh, which {is} in the land of Canaan. {young...: Heb. young women virgins}', 'and they found among the inhabitants of jabeshgilead four hundred young virgins that had known no man by lying with any male and they brought them unto the camp to shiloh which is in the land of canaan young heb young women virgins');
