INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 14, 'And Benjamin came again at that time; and they gave them wives which they had saved alive of the women of Jabeshgilead: and yet so they sufficed them not.', 'and benjamin came again at that time and they gave them wives which they had saved alive of the women of jabeshgilead and yet so they sufficed them not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 15, 'And the people repented them for Benjamin, because that the LORD had made a breach in the tribes of Israel.', 'and the people repented them for benjamin because that the lord had made a breach in the tribes of israel');
