INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 21, 'And see, and, behold, if the daughters of Shiloh come out to dance in dances, then come ye out of the vineyards, and catch you every man his wife of the daughters of Shiloh, and go to the land of Benjamin.', 'and see and behold if the daughters of shiloh come out to dance in dances then come ye out of the vineyards and catch you every man his wife of the daughters of shiloh and go to the land of benjamin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 22, 'And it shall be, when their fathers or their brethren come unto us to complain, that we will say unto them, Be favourable unto them for our sakes: because we reserved not to each man his wife in the war: for ye did not give unto them at this time, {that} ye should be guilty. {Be favourable...: or, Gratify us in them}', 'and it shall be when their fathers or their brethren come unto us to complain that we will say unto them be favourable unto them for our sakes because we reserved not to each man his wife in the war for ye did not give unto them at this time that ye should be guilty be favourable or gratify us in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 23, 'And the children of Benjamin did so, and took {them} wives, according to their number, of them that danced, whom they caught: and they went and returned unto their inheritance, and repaired the cities, and dwelt in them.', 'and the children of benjamin did so and took them wives according to their number of them that danced whom they caught and they went and returned unto their inheritance and repaired the cities and dwelt in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 24, 'And the children of Israel departed thence at that time, every man to his tribe and to his family, and they went out from thence every man to his inheritance.', 'and the children of israel departed thence at that time every man to his tribe and to his family and they went out from thence every man to his inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 7, 'Unknown', 21, 25, 'In those days {there was} no king in Israel: every man did {that which was} right in his own eyes.', 'in those days there was no king in israel every man did that which was right in his own eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 1, 'Now it came to pass in the days when the judges ruled, that there was a famine in the land. And a certain man of Bethlehemjudah went to sojourn in the country of Moab, he, and his wife, and his two sons. {ruled: Heb. judged}', 'now it came to pass in the days when the judges ruled that there was a famine in the land and a certain man of bethlehemjudah went to sojourn in the country of moab he and his wife and his two sons ruled heb judged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 2, 'And the name of the man {was} Elimelech, and the name of his wife Naomi, and the name of his two sons Mahlon and Chilion, Ephrathites of Bethlehemjudah. And they came into the country of Moab, and continued there. {continued: Heb. were}', 'and the name of the man was elimelech and the name of his wife naomi and the name of his two sons mahlon and chilion ephrathites of bethlehemjudah and they came into the country of moab and continued there continued heb were');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 3, 'And Elimelech Naomi''s husband died; and she was left, and her two sons.', 'and elimelech naomi s husband died and she was left and her two sons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 4, 'And they took them wives of the women of Moab; the name of the one {was} Orpah, and the name of the other Ruth: and they dwelled there about ten years.', 'and they took them wives of the women of moab the name of the one was orpah and the name of the other ruth and they dwelled there about ten years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 5, 'And Mahlon and Chilion died also both of them; and the woman was left of her two sons and her husband.', 'and mahlon and chilion died also both of them and the woman was left of her two sons and her husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 6, 'Then she arose with her daughters in law, that she might return from the country of Moab: for she had heard in the country of Moab how that the LORD had visited his people in giving them bread.', 'then she arose with her daughters in law that she might return from the country of moab for she had heard in the country of moab how that the lord had visited his people in giving them bread');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 7, 'Wherefore she went forth out of the place where she was, and her two daughters in law with her; and they went on the way to return unto the land of Judah.', 'wherefore she went forth out of the place where she was and her two daughters in law with her and they went on the way to return unto the land of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 8, 'And Naomi said unto her two daughters in law, Go, return each to her mother''s house: the LORD deal kindly with you, as ye have dealt with the dead, and with me.', 'and naomi said unto her two daughters in law go return each to her mother s house the lord deal kindly with you as ye have dealt with the dead and with me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 9, 'The LORD grant you that ye may find rest, each {of you} in the house of her husband. Then she kissed them; and they lifted up their voice, and wept.', 'the lord grant you that ye may find rest each of you in the house of her husband then she kissed them and they lifted up their voice and wept');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 10, 'And they said unto her, Surely we will return with thee unto thy people.', 'and they said unto her surely we will return with thee unto thy people');
