INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 12, 'Turn again, my daughters, go {your way}; for I am too old to have an husband. If I should say, I have hope, {if} I should have an husband also to night, and should also bear sons; {should have...: or were with an husband}', 'turn again my daughters go your way for i am too old to have an husband if i should say i have hope if i should have an husband also to night and should also bear sons should have or were with an husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 13, 'Would ye tarry for them till they were grown? would ye stay for them from having husbands? nay, my daughters; for it grieveth me much for your sakes that the hand of the LORD is gone out against me. {tarry: Heb. hope} {it grieveth...: Heb. I have much bitterness}', 'would ye tarry for them till they were grown would ye stay for them from having husbands nay my daughters for it grieveth me much for your sakes that the hand of the lord is gone out against me tarry heb hope it grieveth heb i have much bitterness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 14, 'And they lifted up their voice, and wept again: and Orpah kissed her mother in law; but Ruth clave unto her.', 'and they lifted up their voice and wept again and orpah kissed her mother in law but ruth clave unto her');
