INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 16, 'And Ruth said, Intreat me not to leave thee, {or} to return from following after thee: for whither thou goest, I will go; and where thou lodgest, I will lodge: thy people {shall be} my people, and thy God my God: {Intreat...: or, Be not against me}', 'and ruth said intreat me not to leave thee or to return from following after thee for whither thou goest i will go and where thou lodgest i will lodge thy people shall be my people and thy god my god intreat or be not against me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 17, 'Where thou diest, will I die, and there will I be buried: the LORD do so to me, and more also, {if ought} but death part thee and me.', 'where thou diest will i die and there will i be buried the lord do so to me and more also if ought but death part thee and me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 18, 'When she saw that she was stedfastly minded to go with her, then she left speaking unto her. {was...: Heb. strengthened herself}', 'when she saw that she was stedfastly minded to go with her then she left speaking unto her was heb strengthened herself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 19, 'So they two went until they came to Bethlehem. And it came to pass, when they were come to Bethlehem, that all the city was moved about them, and they said, {Is} this Naomi?', 'so they two went until they came to bethlehem and it came to pass when they were come to bethlehem that all the city was moved about them and they said is this naomi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 20, 'And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me. {Naomi: that is, Pleasant} {Mara: that is, Bitter}', 'and she said unto them call me not naomi call me mara for the almighty hath dealt very bitterly with me naomi that is pleasant mara that is bitter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 21, 'I went out full, and the LORD hath brought me home again empty: why {then} call ye me Naomi, seeing the LORD hath testified against me, and the Almighty hath afflicted me?', 'i went out full and the lord hath brought me home again empty why then call ye me naomi seeing the lord hath testified against me and the almighty hath afflicted me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 1, 22, 'So Naomi returned, and Ruth the Moabitess, her daughter in law, with her, which returned out of the country of Moab: and they came to Bethlehem in the beginning of barley harvest.', 'so naomi returned and ruth the moabitess her daughter in law with her which returned out of the country of moab and they came to bethlehem in the beginning of barley harvest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 1, 'And Naomi had a kinsman of her husband''s, a mighty man of wealth, of the family of Elimelech; and his name {was} Boaz. {Boaz: Gr. Booz}', 'and naomi had a kinsman of her husband s a mighty man of wealth of the family of elimelech and his name was boaz boaz gr booz');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 2, 'And Ruth the Moabitess said unto Naomi, Let me now go to the field, and glean ears of corn after {him} in whose sight I shall find grace. And she said unto her, Go, my daughter.', 'and ruth the moabitess said unto naomi let me now go to the field and glean ears of corn after him in whose sight i shall find grace and she said unto her go my daughter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 3, 'And she went, and came, and gleaned in the field after the reapers: and her hap was to light on a part of the field {belonging} unto Boaz, who {was} of the kindred of Elimelech. {hap...: Heb. hap happened}', 'and she went and came and gleaned in the field after the reapers and her hap was to light on a part of the field belonging unto boaz who was of the kindred of elimelech hap heb hap happened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 4, 'And, behold, Boaz came from Bethlehem, and said unto the reapers, The LORD {be} with you. And they answered him, The LORD bless thee.', 'and behold boaz came from bethlehem and said unto the reapers the lord be with you and they answered him the lord bless thee');
