INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 6, 'And the servant that was set over the reapers answered and said, It {is} the Moabitish damsel that came back with Naomi out of the country of Moab:', 'and the servant that was set over the reapers answered and said it is the moabitish damsel that came back with naomi out of the country of moab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 7, 'And she said, I pray you, let me glean and gather after the reapers among the sheaves: so she came, and hath continued even from the morning until now, that she tarried a little in the house.', 'and she said i pray you let me glean and gather after the reapers among the sheaves so she came and hath continued even from the morning until now that she tarried a little in the house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 8, 'Then said Boaz unto Ruth, Hearest thou not, my daughter? Go not to glean in another field, neither go from hence, but abide here fast by my maidens:', 'then said boaz unto ruth hearest thou not my daughter go not to glean in another field neither go from hence but abide here fast by my maidens');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 9, '{Let} thine eyes {be} on the field that they do reap, and go thou after them: have I not charged the young men that they shall not touch thee? and when thou art athirst, go unto the vessels, and drink of {that} which the young men have drawn.', 'let thine eyes be on the field that they do reap and go thou after them have i not charged the young men that they shall not touch thee and when thou art athirst go unto the vessels and drink of that which the young men have drawn');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 10, 'Then she fell on her face, and bowed herself to the ground, and said unto him, Why have I found grace in thine eyes, that thou shouldest take knowledge of me, seeing I {am} a stranger?', 'then she fell on her face and bowed herself to the ground and said unto him why have i found grace in thine eyes that thou shouldest take knowledge of me seeing i am a stranger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 11, 'And Boaz answered and said unto her, It hath fully been shewed me, all that thou hast done unto thy mother in law since the death of thine husband: and {how} thou hast left thy father and thy mother, and the land of thy nativity, and art come unto a people which thou knewest not heretofore.', 'and boaz answered and said unto her it hath fully been shewed me all that thou hast done unto thy mother in law since the death of thine husband and how thou hast left thy father and thy mother and the land of thy nativity and art come unto a people which thou knewest not heretofore');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 12, 'The LORD recompense thy work, and a full reward be given thee of the LORD God of Israel, under whose wings thou art come to trust.', 'the lord recompense thy work and a full reward be given thee of the lord god of israel under whose wings thou art come to trust');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 13, 'Then she said, Let me find favour in thy sight, my lord; for that thou hast comforted me, and for that thou hast spoken friendly unto thine handmaid, though I be not like unto one of thine handmaidens. {Let me...: or, I find} {friendly: Heb. to the heart}', 'then she said let me find favour in thy sight my lord for that thou hast comforted me and for that thou hast spoken friendly unto thine handmaid though i be not like unto one of thine handmaidens let me or i find friendly heb to the heart');
