INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 22, 'And Naomi said unto Ruth her daughter in law, {It is} good, my daughter, that thou go out with his maidens, that they meet thee not in any other field. {meet...: or, fall upon thee}', 'and naomi said unto ruth her daughter in law it is good my daughter that thou go out with his maidens that they meet thee not in any other field meet or fall upon thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 2, 23, 'So she kept fast by the maidens of Boaz to glean unto the end of barley harvest and of wheat harvest; and dwelt with her mother in law.', 'so she kept fast by the maidens of boaz to glean unto the end of barley harvest and of wheat harvest and dwelt with her mother in law');
