INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 4, 'And it shall be, when he lieth down, that thou shalt mark the place where he shall lie, and thou shalt go in, and uncover his feet, and lay thee down; and he will tell thee what thou shalt do. {uncover: or, lift up the clothes that are on}', 'and it shall be when he lieth down that thou shalt mark the place where he shall lie and thou shalt go in and uncover his feet and lay thee down and he will tell thee what thou shalt do uncover or lift up the clothes that are on');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 5, 'And she said unto her, All that thou sayest unto me I will do.', 'and she said unto her all that thou sayest unto me i will do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 6, 'And she went down unto the floor, and did according to all that her mother in law bade her.', 'and she went down unto the floor and did according to all that her mother in law bade her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 7, 'And when Boaz had eaten and drunk, and his heart was merry, he went to lie down at the end of the heap of corn: and she came softly, and uncovered his feet, and laid her down.', 'and when boaz had eaten and drunk and his heart was merry he went to lie down at the end of the heap of corn and she came softly and uncovered his feet and laid her down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 8, 'And it came to pass at midnight, that the man was afraid, and turned himself: and, behold, a woman lay at his feet. {turned: or, took hold on}', 'and it came to pass at midnight that the man was afraid and turned himself and behold a woman lay at his feet turned or took hold on');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 9, 'And he said, Who {art} thou? And she answered, I {am} Ruth thine handmaid: spread therefore thy skirt over thine handmaid; for thou {art} a near kinsman. {a near...: or, one that hath right to redeem}', 'and he said who art thou and she answered i am ruth thine handmaid spread therefore thy skirt over thine handmaid for thou art a near kinsman a near or one that hath right to redeem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 10, 'And he said, Blessed {be} thou of the LORD, my daughter: {for} thou hast shewed more kindness in the latter end than at the beginning, inasmuch as thou followedst not young men, whether poor or rich.', 'and he said blessed be thou of the lord my daughter for thou hast shewed more kindness in the latter end than at the beginning inasmuch as thou followedst not young men whether poor or rich');
