INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 12, 'And now it is true that I {am thy} near kinsman: howbeit there is a kinsman nearer than I.', 'and now it is true that i am thy near kinsman howbeit there is a kinsman nearer than i');
