INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 14, 'And she lay at his feet until the morning: and she rose up before one could know another. And he said, Let it not be known that a woman came into the floor.', 'and she lay at his feet until the morning and she rose up before one could know another and he said let it not be known that a woman came into the floor');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 15, 'Also he said, Bring the vail that {thou hast} upon thee, and hold it. And when she held it, he measured six {measures} of barley, and laid {it} on her: and she went into the city. {vail: or, sheet, or, apron}', 'also he said bring the vail that thou hast upon thee and hold it and when she held it he measured six measures of barley and laid it on her and she went into the city vail or sheet or apron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 16, 'And when she came to her mother in law, she said, Who {art} thou, my daughter? And she told her all that the man had done to her.', 'and when she came to her mother in law she said who art thou my daughter and she told her all that the man had done to her');
