INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 3, 18, 'Then said she, Sit still, my daughter, until thou know how the matter will fall: for the man will not be in rest, until he have finished the thing this day.', 'then said she sit still my daughter until thou know how the matter will fall for the man will not be in rest until he have finished the thing this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 1, 'Then went Boaz up to the gate, and sat him down there: and, behold, the kinsman of whom Boaz spake came by; unto whom he said, Ho, such a one! turn aside, sit down here. And he turned aside, and sat down.', 'then went boaz up to the gate and sat him down there and behold the kinsman of whom boaz spake came by unto whom he said ho such a one turn aside sit down here and he turned aside and sat down');
