INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 4, 'And I thought to advertise thee, saying, Buy {it} before the inhabitants, and before the elders of my people. If thou wilt redeem {it}, redeem {it}: but if thou wilt not redeem {it, then} tell me, that I may know: for {there is} none to redeem {it} beside thee; and I {am} after thee. And he said, I will redeem {it}. {I thought...: Heb. I said, I will reveal in thine ear}', 'and i thought to advertise thee saying buy it before the inhabitants and before the elders of my people if thou wilt redeem it redeem it but if thou wilt not redeem it then tell me that i may know for there is none to redeem it beside thee and i am after thee and he said i will redeem it i thought heb i said i will reveal in thine ear');
