INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 6, 'And the kinsman said, I cannot redeem {it} for myself, lest I mar mine own inheritance: redeem thou my right to thyself; for I cannot redeem {it}.', 'and the kinsman said i cannot redeem it for myself lest i mar mine own inheritance redeem thou my right to thyself for i cannot redeem it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 7, 'Now this {was the manner} in former time in Israel concerning redeeming and concerning changing, for to confirm all things; a man plucked off his shoe, and gave {it} to his neighbour: and this {was} a testimony in Israel.', 'now this was the manner in former time in israel concerning redeeming and concerning changing for to confirm all things a man plucked off his shoe and gave it to his neighbour and this was a testimony in israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 8, 'Therefore the kinsman said unto Boaz, Buy {it} for thee. So he drew off his shoe.', 'therefore the kinsman said unto boaz buy it for thee so he drew off his shoe');
