INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 11, 'And all the people that {were} in the gate, and the elders, said, {We are} witnesses. The LORD make the woman that is come into thine house like Rachel and like Leah, which two did build the house of Israel: and do thou worthily in Ephratah, and be famous in Bethlehem: {do thou...: or, get thee riches, or, power} {be famous: Heb. proclaim thy name}', 'and all the people that were in the gate and the elders said we are witnesses the lord make the woman that is come into thine house like rachel and like leah which two did build the house of israel and do thou worthily in ephratah and be famous in bethlehem do thou or get thee riches or power be famous heb proclaim thy name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 8, 'Unknown', 4, 12, 'And let thy house be like the house of Pharez, whom Tamar bare unto Judah, of the seed which the LORD shall give thee of this young woman.', 'and let thy house be like the house of pharez whom tamar bare unto judah of the seed which the lord shall give thee of this young woman');
