INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 1, 'Now there was a certain man of Ramathaimzophim, of mount Ephraim, and his name {was} Elkanah, the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephrathite:', 'now there was a certain man of ramathaimzophim of mount ephraim and his name was elkanah the son of jeroham the son of elihu the son of tohu the son of zuph an ephrathite');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 2, 'And he had two wives; the name of the one {was} Hannah, and the name of the other Peninnah: and Peninnah had children, but Hannah had no children.', 'and he had two wives the name of the one was hannah and the name of the other peninnah and peninnah had children but hannah had no children');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 3, 'And this man went up out of his city yearly to worship and to sacrifice unto the LORD of hosts in Shiloh. And the two sons of Eli, Hophni and Phinehas, the priests of the LORD, {were} there. {yearly: Heb. from year to year}', 'and this man went up out of his city yearly to worship and to sacrifice unto the lord of hosts in shiloh and the two sons of eli hophni and phinehas the priests of the lord were there yearly heb from year to year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 4, 'And when the time was that Elkanah offered, he gave to Peninnah his wife, and to all her sons and her daughters, portions:', 'and when the time was that elkanah offered he gave to peninnah his wife and to all her sons and her daughters portions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 5, 'But unto Hannah he gave a worthy portion; for he loved Hannah: but the LORD had shut up her womb. {worthy: or, double}', 'but unto hannah he gave a worthy portion for he loved hannah but the lord had shut up her womb worthy or double');
