INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 7, 'And {as} he did so year by year, when she went up to the house of the LORD, so she provoked her; therefore she wept, and did not eat. {when...: or, from the time that she, etc: Heb. from her going up}', 'and as he did so year by year when she went up to the house of the lord so she provoked her therefore she wept and did not eat when or from the time that she etc heb from her going up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 1, 8, 'Then said Elkanah her husband to her, Hannah, why weepest thou? and why eatest thou not? and why is thy heart grieved? {am} not I better to thee than ten sons?', 'then said elkanah her husband to her hannah why weepest thou and why eatest thou not and why is thy heart grieved am not i better to thee than ten sons');
