INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 3, 4, 'That the LORD called Samuel: and he answered, Here {am} I.', 'that the lord called samuel and he answered here am i');
