INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 3, 8, 'And the LORD called Samuel again the third time. And he arose and went to Eli, and said, Here {am} I; for thou didst call me. And Eli perceived that the LORD had called the child.', 'and the lord called samuel again the third time and he arose and went to eli and said here am i for thou didst call me and eli perceived that the lord had called the child');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 3, 9, 'Therefore Eli said unto Samuel, Go, lie down: and it shall be, if he call thee, that thou shalt say, Speak, LORD; for thy servant heareth. So Samuel went and lay down in his place.', 'therefore eli said unto samuel go lie down and it shall be if he call thee that thou shalt say speak lord for thy servant heareth so samuel went and lay down in his place');
