INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 3, 14, 'And therefore I have sworn unto the house of Eli, that the iniquity of Eli''s house shall not be purged with sacrifice nor offering for ever.', 'and therefore i have sworn unto the house of eli that the iniquity of eli s house shall not be purged with sacrifice nor offering for ever');
