INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 3, 17, 'And he said, What {is} the thing that {the LORD} hath said unto thee? I pray thee hide {it} not from me: God do so to thee, and more also, if thou hide {any} thing from me of all the things that he said unto thee. {more also: Heb. so add} {thing: or, word}', 'and he said what is the thing that the lord hath said unto thee i pray thee hide it not from me god do so to thee and more also if thou hide any thing from me of all the things that he said unto thee more also heb so add thing or word');
