INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 10, 25, 'Then Samuel told the people the manner of the kingdom, and wrote {it} in a book, and laid {it} up before the LORD. And Samuel sent all the people away, every man to his house.', 'then samuel told the people the manner of the kingdom and wrote it in a book and laid it up before the lord and samuel sent all the people away every man to his house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 10, 26, 'And Saul also went home to Gibeah; and there went with him a band of men, whose hearts God had touched.', 'and saul also went home to gibeah and there went with him a band of men whose hearts god had touched');
