INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 1, 'Then Nahash the Ammonite came up, and encamped against Jabeshgilead: and all the men of Jabesh said unto Nahash, Make a covenant with us, and we will serve thee.', 'then nahash the ammonite came up and encamped against jabeshgilead and all the men of jabesh said unto nahash make a covenant with us and we will serve thee');
