INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 3, 'And the elders of Jabesh said unto him, Give us seven days'' respite, that we may send messengers unto all the coasts of Israel: and then, if {there be} no man to save us, we will come out to thee. {Give...: Heb. Forbear us}', 'and the elders of jabesh said unto him give us seven days respite that we may send messengers unto all the coasts of israel and then if there be no man to save us we will come out to thee give heb forbear us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 4, 'Then came the messengers to Gibeah of Saul, and told the tidings in the ears of the people: and all the people lifted up their voices, and wept.', 'then came the messengers to gibeah of saul and told the tidings in the ears of the people and all the people lifted up their voices and wept');
