INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 6, 'And the Spirit of God came upon Saul when he heard those tidings, and his anger was kindled greatly.', 'and the spirit of god came upon saul when he heard those tidings and his anger was kindled greatly');
