INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 8, 'And when he numbered them in Bezek, the children of Israel were three hundred thousand, and the men of Judah thirty thousand.', 'and when he numbered them in bezek the children of israel were three hundred thousand and the men of judah thirty thousand');
