INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 10, 'Therefore the men of Jabesh said, To morrow we will come out unto you, and ye shall do with us all that seemeth good unto you.', 'therefore the men of jabesh said to morrow we will come out unto you and ye shall do with us all that seemeth good unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 11, 'And it was {so} on the morrow, that Saul put the people in three companies; and they came into the midst of the host in the morning watch, and slew the Ammonites until the heat of the day: and it came to pass, that they which remained were scattered, so that two of them were not left together.', 'and it was so on the morrow that saul put the people in three companies and they came into the midst of the host in the morning watch and slew the ammonites until the heat of the day and it came to pass that they which remained were scattered so that two of them were not left together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 12, 'And the people said unto Samuel, Who {is} he that said, Shall Saul reign over us? bring the men, that we may put them to death.', 'and the people said unto samuel who is he that said shall saul reign over us bring the men that we may put them to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 11, 13, 'And Saul said, There shall not a man be put to death this day: for to day the LORD hath wrought salvation in Israel.', 'and saul said there shall not a man be put to death this day for to day the lord hath wrought salvation in israel');
