INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 1, 'And Samuel said unto all Israel, Behold, I have hearkened unto your voice in all that ye said unto me, and have made a king over you.', 'and samuel said unto all israel behold i have hearkened unto your voice in all that ye said unto me and have made a king over you');
