INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 3, 'Behold, here I {am}: witness against me before the LORD, and before his anointed: whose ox have I taken? or whose ass have I taken? or whom have I defrauded? whom have I oppressed? or of whose hand have I received {any} bribe to blind mine eyes therewith? and I will restore it you. {bribe: Heb. ransom} {to blind...: or, that I should hide mine eyes at him}', 'behold here i am witness against me before the lord and before his anointed whose ox have i taken or whose ass have i taken or whom have i defrauded whom have i oppressed or of whose hand have i received any bribe to blind mine eyes therewith and i will restore it you bribe heb ransom to blind or that i should hide mine eyes at him');
