INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 6, 'And Samuel said unto the people, {It is} the LORD that advanced Moses and Aaron, and that brought your fathers up out of the land of Egypt. {advanced: or, made}', 'and samuel said unto the people it is the lord that advanced moses and aaron and that brought your fathers up out of the land of egypt advanced or made');
