INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 8, 'When Jacob was come into Egypt, and your fathers cried unto the LORD, then the LORD sent Moses and Aaron, which brought forth your fathers out of Egypt, and made them dwell in this place.', 'when jacob was come into egypt and your fathers cried unto the lord then the lord sent moses and aaron which brought forth your fathers out of egypt and made them dwell in this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 9, 'And when they forgat the LORD their God, he sold them into the hand of Sisera, captain of the host of Hazor, and into the hand of the Philistines, and into the hand of the king of Moab, and they fought against them.', 'and when they forgat the lord their god he sold them into the hand of sisera captain of the host of hazor and into the hand of the philistines and into the hand of the king of moab and they fought against them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 10, 'And they cried unto the LORD, and said, We have sinned, because we have forsaken the LORD, and have served Baalim and Ashtaroth: but now deliver us out of the hand of our enemies, and we will serve thee.', 'and they cried unto the lord and said we have sinned because we have forsaken the lord and have served baalim and ashtaroth but now deliver us out of the hand of our enemies and we will serve thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 11, 'And the LORD sent Jerubbaal, and Bedan, and Jephthah, and Samuel, and delivered you out of the hand of your enemies on every side, and ye dwelled safe.', 'and the lord sent jerubbaal and bedan and jephthah and samuel and delivered you out of the hand of your enemies on every side and ye dwelled safe');
