INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 12, 20, 'And Samuel said unto the people, Fear not: ye have done all this wickedness: yet turn not aside from following the LORD, but serve the LORD with all your heart;', 'and samuel said unto the people fear not ye have done all this wickedness yet turn not aside from following the lord but serve the lord with all your heart');
