INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 4, 'And all Israel heard say {that} Saul had smitten a garrison of the Philistines, and {that} Israel also was had in abomination with the Philistines. And the people were called together after Saul to Gilgal. {was...: Heb. did stink}', 'and all israel heard say that saul had smitten a garrison of the philistines and that israel also was had in abomination with the philistines and the people were called together after saul to gilgal was heb did stink');
