INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 6, 'When the men of Israel saw that they were in a strait, (for the people were distressed,) then the people did hide themselves in caves, and in thickets, and in rocks, and in high places, and in pits.', 'when the men of israel saw that they were in a strait for the people were distressed then the people did hide themselves in caves and in thickets and in rocks and in high places and in pits');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 7, 'And {some of} the Hebrews went over Jordan to the land of Gad and Gilead. As for Saul, he {was} yet in Gilgal, and all the people followed him trembling. {followed...: Heb. trembled after him}', 'and some of the hebrews went over jordan to the land of gad and gilead as for saul he was yet in gilgal and all the people followed him trembling followed heb trembled after him');
