INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 11, 'And Samuel said, What hast thou done? And Saul said, Because I saw that the people were scattered from me, and {that} thou camest not within the days appointed, and {that} the Philistines gathered themselves together at Michmash;', 'and samuel said what hast thou done and saul said because i saw that the people were scattered from me and that thou camest not within the days appointed and that the philistines gathered themselves together at michmash');
