INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 20, 'But all the Israelites went down to the Philistines, to sharpen every man his share, and his coulter, and his axe, and his mattock.', 'but all the israelites went down to the philistines to sharpen every man his share and his coulter and his axe and his mattock');
