INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 22, 'So it came to pass in the day of battle, that there was neither sword nor spear found in the hand of any of the people that {were} with Saul and Jonathan: but with Saul and with Jonathan his son was there found.', 'so it came to pass in the day of battle that there was neither sword nor spear found in the hand of any of the people that were with saul and jonathan but with saul and with jonathan his son was there found');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 13, 23, 'And the garrison of the Philistines went out to the passage of Michmash. {garrison: or, standing camp}', 'and the garrison of the philistines went out to the passage of michmash garrison or standing camp');
