INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 4, 'And between the passages, by which Jonathan sought to go over unto the Philistines'' garrison, {there was} a sharp rock on the one side, and a sharp rock on the other side: and the name of the one {was} Bozez, and the name of the other Seneh.', 'and between the passages by which jonathan sought to go over unto the philistines garrison there was a sharp rock on the one side and a sharp rock on the other side and the name of the one was bozez and the name of the other seneh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 5, 'The forefront of the one {was} situate northward over against Michmash, and the other southward over against Gibeah. {forefront: Heb. tooth}', 'the forefront of the one was situate northward over against michmash and the other southward over against gibeah forefront heb tooth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 6, 'And Jonathan said to the young man that bare his armour, Come, and let us go over unto the garrison of these uncircumcised: it may be that the LORD will work for us: for {there is} no restraint to the LORD to save by many or by few.', 'and jonathan said to the young man that bare his armour come and let us go over unto the garrison of these uncircumcised it may be that the lord will work for us for there is no restraint to the lord to save by many or by few');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 7, 'And his armourbearer said unto him, Do all that {is} in thine heart: turn thee; behold, I {am} with thee according to thy heart.', 'and his armourbearer said unto him do all that is in thine heart turn thee behold i am with thee according to thy heart');
