INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 9, 'If they say thus unto us, Tarry until we come to you; then we will stand still in our place, and will not go up unto them. {Tarry: Heb. Be still}', 'if they say thus unto us tarry until we come to you then we will stand still in our place and will not go up unto them tarry heb be still');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 10, 'But if they say thus, Come up unto us; then we will go up: for the LORD hath delivered them into our hand: and this {shall be} a sign unto us.', 'but if they say thus come up unto us then we will go up for the lord hath delivered them into our hand and this shall be a sign unto us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 11, 'And both of them discovered themselves unto the garrison of the Philistines: and the Philistines said, Behold, the Hebrews come forth out of the holes where they had hid themselves.', 'and both of them discovered themselves unto the garrison of the philistines and the philistines said behold the hebrews come forth out of the holes where they had hid themselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 12, 'And the men of the garrison answered Jonathan and his armourbearer, and said, Come up to us, and we will shew you a thing. And Jonathan said unto his armourbearer, Come up after me: for the LORD hath delivered them into the hand of Israel.', 'and the men of the garrison answered jonathan and his armourbearer and said come up to us and we will shew you a thing and jonathan said unto his armourbearer come up after me for the lord hath delivered them into the hand of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 13, 'And Jonathan climbed up upon his hands and upon his feet, and his armourbearer after him: and they fell before Jonathan; and his armourbearer slew after him.', 'and jonathan climbed up upon his hands and upon his feet and his armourbearer after him and they fell before jonathan and his armourbearer slew after him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 14, 'And that first slaughter, which Jonathan and his armourbearer made, was about twenty men, within as it were an half acre of land, {which} a yoke {of oxen might plow}. {an...: or, half a furrow of an acre of land}', 'and that first slaughter which jonathan and his armourbearer made was about twenty men within as it were an half acre of land which a yoke of oxen might plow an or half a furrow of an acre of land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 15, 'And there was trembling in the host, in the field, and among all the people: the garrison, and the spoilers, they also trembled, and the earth quaked: so it was a very great trembling. {a very...: Heb. a trembling of God}', 'and there was trembling in the host in the field and among all the people the garrison and the spoilers they also trembled and the earth quaked so it was a very great trembling a very heb a trembling of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 16, 'And the watchmen of Saul in Gibeah of Benjamin looked; and, behold, the multitude melted away, and they went on beating down {one another}.', 'and the watchmen of saul in gibeah of benjamin looked and behold the multitude melted away and they went on beating down one another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 17, 'Then said Saul unto the people that {were} with him, Number now, and see who is gone from us. And when they had numbered, behold, Jonathan and his armourbearer {were} not {there}.', 'then said saul unto the people that were with him number now and see who is gone from us and when they had numbered behold jonathan and his armourbearer were not there');
