INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 19, 'And it came to pass, while Saul talked unto the priest, that the noise that {was} in the host of the Philistines went on and increased: and Saul said unto the priest, Withdraw thine hand. {noise: or, tumult}', 'and it came to pass while saul talked unto the priest that the noise that was in the host of the philistines went on and increased and saul said unto the priest withdraw thine hand noise or tumult');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 20, 'And Saul and all the people that {were} with him assembled themselves, and they came to the battle: and, behold, every man''s sword was against his fellow, {and there was} a very great discomfiture. {assembled...: Heb. were cried together}', 'and saul and all the people that were with him assembled themselves and they came to the battle and behold every man s sword was against his fellow and there was a very great discomfiture assembled heb were cried together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 21, 'Moreover the Hebrews {that} were with the Philistines before that time, which went up with them into the camp {from the country} round about, even they also {turned} to be with the Israelites that {were} with Saul and Jonathan.', 'moreover the hebrews that were with the philistines before that time which went up with them into the camp from the country round about even they also turned to be with the israelites that were with saul and jonathan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 22, 'Likewise all the men of Israel which had hid themselves in mount Ephraim, {when} they heard that the Philistines fled, even they also followed hard after them in the battle.', 'likewise all the men of israel which had hid themselves in mount ephraim when they heard that the philistines fled even they also followed hard after them in the battle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 23, 'So the LORD saved Israel that day: and the battle passed over unto Bethaven.', 'so the lord saved israel that day and the battle passed over unto bethaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 24, 'And the men of Israel were distressed that day: for Saul had adjured the people, saying, Cursed {be} the man that eateth {any} food until evening, that I may be avenged on mine enemies. So none of the people tasted {any} food.', 'and the men of israel were distressed that day for saul had adjured the people saying cursed be the man that eateth any food until evening that i may be avenged on mine enemies so none of the people tasted any food');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 25, 'And all {they of} the land came to a wood; and there was honey upon the ground.', 'and all they of the land came to a wood and there was honey upon the ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 26, 'And when the people were come into the wood, behold, the honey dropped; but no man put his hand to his mouth: for the people feared the oath.', 'and when the people were come into the wood behold the honey dropped but no man put his hand to his mouth for the people feared the oath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 27, 'But Jonathan heard not when his father charged the people with the oath: wherefore he put forth the end of the rod that {was} in his hand, and dipped it in an honeycomb, and put his hand to his mouth; and his eyes were enlightened.', 'but jonathan heard not when his father charged the people with the oath wherefore he put forth the end of the rod that was in his hand and dipped it in an honeycomb and put his hand to his mouth and his eyes were enlightened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 28, 'Then answered one of the people, and said, Thy father straitly charged the people with an oath, saying, Cursed {be} the man that eateth {any} food this day. And the people were faint. {faint: or, weary}', 'then answered one of the people and said thy father straitly charged the people with an oath saying cursed be the man that eateth any food this day and the people were faint faint or weary');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 29, 'Then said Jonathan, My father hath troubled the land: see, I pray you, how mine eyes have been enlightened, because I tasted a little of this honey.', 'then said jonathan my father hath troubled the land see i pray you how mine eyes have been enlightened because i tasted a little of this honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 30, 'How much more, if haply the people had eaten freely to day of the spoil of their enemies which they found? for had there not been now a much greater slaughter among the Philistines?', 'how much more if haply the people had eaten freely to day of the spoil of their enemies which they found for had there not been now a much greater slaughter among the philistines');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 31, 'And they smote the Philistines that day from Michmash to Aijalon: and the people were very faint.', 'and they smote the philistines that day from michmash to aijalon and the people were very faint');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 32, 'And the people flew upon the spoil, and took sheep, and oxen, and calves, and slew {them} on the ground: and the people did eat {them} with the blood.', 'and the people flew upon the spoil and took sheep and oxen and calves and slew them on the ground and the people did eat them with the blood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 14, 33, 'Then they told Saul, saying, Behold, the people sin against the LORD, in that they eat with the blood. And he said, Ye have transgressed: roll a great stone unto me this day. {transgressed: or, dealt treacherously}', 'then they told saul saying behold the people sin against the lord in that they eat with the blood and he said ye have transgressed roll a great stone unto me this day transgressed or dealt treacherously');
