INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 36, 'Thy servant slew both the lion and the bear: and this uncircumcised Philistine shall be as one of them, seeing he hath defied the armies of the living God.', 'thy servant slew both the lion and the bear and this uncircumcised philistine shall be as one of them seeing he hath defied the armies of the living god');
