INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 48, 'And it came to pass, when the Philistine arose, and came and drew nigh to meet David, that David hasted, and ran toward the army to meet the Philistine.', 'and it came to pass when the philistine arose and came and drew nigh to meet david that david hasted and ran toward the army to meet the philistine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 49, 'And David put his hand in his bag, and took thence a stone, and slang {it}, and smote the Philistine in his forehead, that the stone sunk into his forehead; and he fell upon his face to the earth.', 'and david put his hand in his bag and took thence a stone and slang it and smote the philistine in his forehead that the stone sunk into his forehead and he fell upon his face to the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 50, 'So David prevailed over the Philistine with a sling and with a stone, and smote the Philistine, and slew him; but {there was} no sword in the hand of David.', 'so david prevailed over the philistine with a sling and with a stone and smote the philistine and slew him but there was no sword in the hand of david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 51, 'Therefore David ran, and stood upon the Philistine, and took his sword, and drew it out of the sheath thereof, and slew him, and cut off his head therewith. And when the Philistines saw their champion was dead, they fled.', 'therefore david ran and stood upon the philistine and took his sword and drew it out of the sheath thereof and slew him and cut off his head therewith and when the philistines saw their champion was dead they fled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 52, 'And the men of Israel and of Judah arose, and shouted, and pursued the Philistines, until thou come to the valley, and to the gates of Ekron. And the wounded of the Philistines fell down by the way to Shaaraim, even unto Gath, and unto Ekron.', 'and the men of israel and of judah arose and shouted and pursued the philistines until thou come to the valley and to the gates of ekron and the wounded of the philistines fell down by the way to shaaraim even unto gath and unto ekron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 53, 'And the children of Israel returned from chasing after the Philistines, and they spoiled their tents.', 'and the children of israel returned from chasing after the philistines and they spoiled their tents');
