INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 17, 58, 'And Saul said to him, Whose son {art} thou, {thou} young man? And David answered, I {am} the son of thy servant Jesse the Bethlehemite.', 'and saul said to him whose son art thou thou young man and david answered i am the son of thy servant jesse the bethlehemite');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 1, 'And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul.', 'and it came to pass when he had made an end of speaking unto saul that the soul of jonathan was knit with the soul of david and jonathan loved him as his own soul');
