INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 5, 'And David went out whithersoever Saul sent him, {and} behaved himself wisely: and Saul set him over the men of war, and he was accepted in the sight of all the people, and also in the sight of Saul''s servants. {behaved...: or, prospered}', 'and david went out whithersoever saul sent him and behaved himself wisely and saul set him over the men of war and he was accepted in the sight of all the people and also in the sight of saul s servants behaved or prospered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 6, 'And it came to pass as they came, when David was returned from the slaughter of the Philistine, that the women came out of all cities of Israel, singing and dancing, to meet king Saul, with tabrets, with joy, and with instruments of musick. {Philistine: or, Philistines} {instruments...: Heb. three stringed instruments}', 'and it came to pass as they came when david was returned from the slaughter of the philistine that the women came out of all cities of israel singing and dancing to meet king saul with tabrets with joy and with instruments of musick philistine or philistines instruments heb three stringed instruments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 7, 'And the women answered {one another} as they played, and said, Saul hath slain his thousands, and David his ten thousands.', 'and the women answered one another as they played and said saul hath slain his thousands and david his ten thousands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 8, 'And Saul was very wroth, and the saying displeased him; and he said, They have ascribed unto David ten thousands, and to me they have ascribed {but} thousands: and {what} can he have more but the kingdom? {displeased him: Heb. was evil in his eyes}', 'and saul was very wroth and the saying displeased him and he said they have ascribed unto david ten thousands and to me they have ascribed but thousands and what can he have more but the kingdom displeased him heb was evil in his eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 9, 'And Saul eyed David from that day and forward.', 'and saul eyed david from that day and forward');
