INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 18, 30, 'Then the princes of the Philistines went forth: and it came to pass, after they went forth, {that} David behaved himself more wisely than all the servants of Saul; so that his name was much set by. {set by: Heb. precious}', 'then the princes of the philistines went forth and it came to pass after they went forth that david behaved himself more wisely than all the servants of saul so that his name was much set by set by heb precious');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 19, 1, 'And Saul spake to Jonathan his son, and to all his servants, that they should kill David.', 'and saul spake to jonathan his son and to all his servants that they should kill david');
