INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 19, 5, 'For he did put his life in his hand, and slew the Philistine, and the LORD wrought a great salvation for all Israel: thou sawest {it}, and didst rejoice: wherefore then wilt thou sin against innocent blood, to slay David without a cause?', 'for he did put his life in his hand and slew the philistine and the lord wrought a great salvation for all israel thou sawest it and didst rejoice wherefore then wilt thou sin against innocent blood to slay david without a cause');
