INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 29, 8, 'And David said unto Achish, But what have I done? and what hast thou found in thy servant so long as I have been with thee unto this day, that I may not go fight against the enemies of my lord the king? {with...: Heb. before thee}', 'and david said unto achish but what have i done and what hast thou found in thy servant so long as i have been with thee unto this day that i may not go fight against the enemies of my lord the king with heb before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 29, 9, 'And Achish answered and said to David, I know that thou {art} good in my sight, as an angel of God: notwithstanding the princes of the Philistines have said, He shall not go up with us to the battle.', 'and achish answered and said to david i know that thou art good in my sight as an angel of god notwithstanding the princes of the philistines have said he shall not go up with us to the battle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 29, 10, 'Wherefore now rise up early in the morning with thy master''s servants that are come with thee: and as soon as ye be up early in the morning, and have light, depart.', 'wherefore now rise up early in the morning with thy master s servants that are come with thee and as soon as ye be up early in the morning and have light depart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 29, 11, 'So David and his men rose up early to depart in the morning, to return into the land of the Philistines. And the Philistines went up to Jezreel.', 'so david and his men rose up early to depart in the morning to return into the land of the philistines and the philistines went up to jezreel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 30, 1, 'And it came to pass, when David and his men were come to Ziklag on the third day, that the Amalekites had invaded the south, and Ziklag, and smitten Ziklag, and burned it with fire;', 'and it came to pass when david and his men were come to ziklag on the third day that the amalekites had invaded the south and ziklag and smitten ziklag and burned it with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 30, 2, 'And had taken the women captives, that {were} therein: they slew not any, either great or small, but carried {them} away, and went on their way.', 'and had taken the women captives that were therein they slew not any either great or small but carried them away and went on their way');
