INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 30, 5, 'And David''s two wives were taken captives, Ahinoam the Jezreelitess, and Abigail the wife of Nabal the Carmelite.', 'and david s two wives were taken captives ahinoam the jezreelitess and abigail the wife of nabal the carmelite');
