INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 30, 7, 'And David said to Abiathar the priest, Ahimelech''s son, I pray thee, bring me hither the ephod. And Abiathar brought thither the ephod to David.', 'and david said to abiathar the priest ahimelech s son i pray thee bring me hither the ephod and abiathar brought thither the ephod to david');
