INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 9, 'Unknown', 30, 9, 'So David went, he and the six hundred men that {were} with him, and came to the brook Besor, where those that were left behind stayed.', 'so david went he and the six hundred men that were with him and came to the brook besor where those that were left behind stayed');
