INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 1, 'And it came to pass after this, that David enquired of the LORD, saying, Shall I go up into any of the cities of Judah? And the LORD said unto him, Go up. And David said, Whither shall I go up? And he said, Unto Hebron.', 'and it came to pass after this that david enquired of the lord saying shall i go up into any of the cities of judah and the lord said unto him go up and david said whither shall i go up and he said unto hebron');
