INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 9, 'And made him king over Gilead, and over the Ashurites, and over Jezreel, and over Ephraim, and over Benjamin, and over all Israel.', 'and made him king over gilead and over the ashurites and over jezreel and over ephraim and over benjamin and over all israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 10, 'Ishbosheth Saul''s son {was} forty years old when he began to reign over Israel, and reigned two years. But the house of Judah followed David.', 'ishbosheth saul s son was forty years old when he began to reign over israel and reigned two years but the house of judah followed david');
