INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 17, 'And there was a very sore battle that day; and Abner was beaten, and the men of Israel, before the servants of David.', 'and there was a very sore battle that day and abner was beaten and the men of israel before the servants of david');
