INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 19, 'And Asahel pursued after Abner; and in going he turned not to the right hand nor to the left from following Abner. {from...: Heb. from after Abner}', 'and asahel pursued after abner and in going he turned not to the right hand nor to the left from following abner from heb from after abner');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 20, 'Then Abner looked behind him, and said, {Art} thou Asahel? And he answered, I {am}.', 'then abner looked behind him and said art thou asahel and he answered i am');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 21, 'And Abner said to him, Turn thee aside to thy right hand or to thy left, and lay thee hold on one of the young men, and take thee his armour. But Asahel would not turn aside from following of him. {armour: or, spoil}', 'and abner said to him turn thee aside to thy right hand or to thy left and lay thee hold on one of the young men and take thee his armour but asahel would not turn aside from following of him armour or spoil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 22, 'And Abner said again to Asahel, Turn thee aside from following me: wherefore should I smite thee to the ground? how then should I hold up my face to Joab thy brother?', 'and abner said again to asahel turn thee aside from following me wherefore should i smite thee to the ground how then should i hold up my face to joab thy brother');
