INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 24, 'Joab also and Abishai pursued after Abner: and the sun went down when they were come to the hill of Ammah, that {lieth} before Giah by the way of the wilderness of Gibeon.', 'joab also and abishai pursued after abner and the sun went down when they were come to the hill of ammah that lieth before giah by the way of the wilderness of gibeon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 25, 'And the children of Benjamin gathered themselves together after Abner, and became one troop, and stood on the top of an hill.', 'and the children of benjamin gathered themselves together after abner and became one troop and stood on the top of an hill');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 26, 'Then Abner called to Joab, and said, Shall the sword devour for ever? knowest thou not that it will be bitterness in the latter end? how long shall it be then, ere thou bid the people return from following their brethren?', 'then abner called to joab and said shall the sword devour for ever knowest thou not that it will be bitterness in the latter end how long shall it be then ere thou bid the people return from following their brethren');
