INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 28, 'So Joab blew a trumpet, and all the people stood still, and pursued after Israel no more, neither fought they any more.', 'so joab blew a trumpet and all the people stood still and pursued after israel no more neither fought they any more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 2, 29, 'And Abner and his men walked all that night through the plain, and passed over Jordan, and went through all Bithron, and they came to Mahanaim.', 'and abner and his men walked all that night through the plain and passed over jordan and went through all bithron and they came to mahanaim');
