INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 3, 10, 'To translate the kingdom from the house of Saul, and to set up the throne of David over Israel and over Judah, from Dan even to Beersheba.', 'to translate the kingdom from the house of saul and to set up the throne of david over israel and over judah from dan even to beersheba');
