INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 3, 13, 'And he said, Well; I will make a league with thee: but one thing I require of thee, that is, Thou shalt not see my face, except thou first bring Michal Saul''s daughter, when thou comest to see my face. {that is: Heb. saying}', 'and he said well i will make a league with thee but one thing i require of thee that is thou shalt not see my face except thou first bring michal saul s daughter when thou comest to see my face that is heb saying');
