INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 3, 16, 'And her husband went with her along weeping behind her to Bahurim. Then said Abner unto him, Go, return. And he returned. {along...: Heb. going and weeping}', 'and her husband went with her along weeping behind her to bahurim then said abner unto him go return and he returned along heb going and weeping');
