INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 5, 17, 'But when the Philistines heard that they had anointed David king over Israel, all the Philistines came up to seek David; and David heard {of it}, and went down to the hold.', 'but when the philistines heard that they had anointed david king over israel all the philistines came up to seek david and david heard of it and went down to the hold');
