INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 5, 19, 'And David enquired of the LORD, saying, Shall I go up to the Philistines? wilt thou deliver them into mine hand? And the LORD said unto David, Go up: for I will doubtless deliver the Philistines into thine hand.', 'and david enquired of the lord saying shall i go up to the philistines wilt thou deliver them into mine hand and the lord said unto david go up for i will doubtless deliver the philistines into thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 5, 20, 'And David came to Baalperazim, and David smote them there, and said, The LORD hath broken forth upon mine enemies before me, as the breach of waters. Therefore he called the name of that place Baalperazim. {Baalperazim: that is, the plain of breaches}', 'and david came to baalperazim and david smote them there and said the lord hath broken forth upon mine enemies before me as the breach of waters therefore he called the name of that place baalperazim baalperazim that is the plain of breaches');
