INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 5, 22, 'And the Philistines came up yet again, and spread themselves in the valley of Rephaim.', 'and the philistines came up yet again and spread themselves in the valley of rephaim');
