INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 2, 'And the victory that day was {turned} into mourning unto all the people: for the people heard say that day how the king was grieved for his son. {victory: Heb. salvation, or, deliverance}', 'and the victory that day was turned into mourning unto all the people for the people heard say that day how the king was grieved for his son victory heb salvation or deliverance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 3, 'And the people gat them by stealth that day into the city, as people being ashamed steal away when they flee in battle.', 'and the people gat them by stealth that day into the city as people being ashamed steal away when they flee in battle');
