INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 35, 'I {am} this day fourscore years old: {and} can I discern between good and evil? can thy servant taste what I eat or what I drink? can I hear any more the voice of singing men and singing women? wherefore then should thy servant be yet a burden unto my lord the king?', 'i am this day fourscore years old and can i discern between good and evil can thy servant taste what i eat or what i drink can i hear any more the voice of singing men and singing women wherefore then should thy servant be yet a burden unto my lord the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 36, 'Thy servant will go a little way over Jordan with the king: and why should the king recompense it me with such a reward?', 'thy servant will go a little way over jordan with the king and why should the king recompense it me with such a reward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 37, 'Let thy servant, I pray thee, turn back again, that I may die in mine own city, {and be buried} by the grave of my father and of my mother. But behold thy servant Chimham; let him go over with my lord the king; and do to him what shall seem good unto thee.', 'let thy servant i pray thee turn back again that i may die in mine own city and be buried by the grave of my father and of my mother but behold thy servant chimham let him go over with my lord the king and do to him what shall seem good unto thee');
