INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 41, 'And, behold, all the men of Israel came to the king, and said unto the king, Why have our brethren the men of Judah stolen thee away, and have brought the king, and his household, and all David''s men with him, over Jordan?', 'and behold all the men of israel came to the king and said unto the king why have our brethren the men of judah stolen thee away and have brought the king and his household and all david s men with him over jordan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 42, 'And all the men of Judah answered the men of Israel, Because the king {is} near of kin to us: wherefore then be ye angry for this matter? have we eaten at all of the king''s {cost}? or hath he given us any gift?', 'and all the men of judah answered the men of israel because the king is near of kin to us wherefore then be ye angry for this matter have we eaten at all of the king s cost or hath he given us any gift');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 19, 43, 'And the men of Israel answered the men of Judah, and said, We have ten parts in the king, and we have also more {right} in David than ye: why then did ye despise us, that our advice should not be first had in bringing back our king? And the words of the men of Judah were fiercer than the words of the men of Israel. {despise...: Heb. set us at light}', 'and the men of israel answered the men of judah and said we have ten parts in the king and we have also more right in david than ye why then did ye despise us that our advice should not be first had in bringing back our king and the words of the men of judah were fiercer than the words of the men of israel despise heb set us at light');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 1, 'And there happened to be there a man of Belial, whose name {was} Sheba, the son of Bichri, a Benjamite: and he blew a trumpet, and said, We have no part in David, neither have we inheritance in the son of Jesse: every man to his tents, O Israel.', 'and there happened to be there a man of belial whose name was sheba the son of bichri a benjamite and he blew a trumpet and said we have no part in david neither have we inheritance in the son of jesse every man to his tents o israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 2, 'So every man of Israel went up from after David, {and} followed Sheba the son of Bichri: but the men of Judah clave unto their king, from Jordan even to Jerusalem.', 'so every man of israel went up from after david and followed sheba the son of bichri but the men of judah clave unto their king from jordan even to jerusalem');
