INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 18, 'Then she spake, saying, They were wont to speak in old time, saying, They shall surely ask {counsel} at Abel: and so they ended {the matter}. {They were...: or, They plainly spake in the beginning, saying, Surely they will ask of Abel, and so make an end}', 'then she spake saying they were wont to speak in old time saying they shall surely ask counsel at abel and so they ended the matter they were or they plainly spake in the beginning saying surely they will ask of abel and so make an end');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 19, 'I {am one of them that are} peaceable {and} faithful in Israel: thou seekest to destroy a city and a mother in Israel: why wilt thou swallow up the inheritance of the LORD?', 'i am one of them that are peaceable and faithful in israel thou seekest to destroy a city and a mother in israel why wilt thou swallow up the inheritance of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 20, 'And Joab answered and said, Far be it, far be it from me, that I should swallow up or destroy.', 'and joab answered and said far be it far be it from me that i should swallow up or destroy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 21, 'The matter {is} not so: but a man of mount Ephraim, Sheba the son of Bichri by name, hath lifted up his hand against the king, {even} against David: deliver him only, and I will depart from the city. And the woman said unto Joab, Behold, his head shall be thrown to thee over the wall. {by name: Heb. by his name}', 'the matter is not so but a man of mount ephraim sheba the son of bichri by name hath lifted up his hand against the king even against david deliver him only and i will depart from the city and the woman said unto joab behold his head shall be thrown to thee over the wall by name heb by his name');
