INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 23, 'Now Joab {was} over all the host of Israel: and Benaiah the son of Jehoiada {was} over the Cherethites and over the Pelethites:', 'now joab was over all the host of israel and benaiah the son of jehoiada was over the cherethites and over the pelethites');
