INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 25, 'And Sheva {was} scribe: and Zadok and Abiathar {were} the priests:', 'and sheva was scribe and zadok and abiathar were the priests');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 20, 26, 'And Ira also the Jairite was a chief ruler about David. {a chief...: or, a prince}', 'and ira also the jairite was a chief ruler about david a chief or a prince');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 21, 1, 'Then there was a famine in the days of David three years, year after year; and David enquired of the LORD. And the LORD answered, {It is} for Saul, and for {his} bloody house, because he slew the Gibeonites. {enquired...: Heb. sought the face, etc}', 'then there was a famine in the days of david three years year after year and david enquired of the lord and the lord answered it is for saul and for his bloody house because he slew the gibeonites enquired heb sought the face etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 21, 2, 'And the king called the Gibeonites, and said unto them; (now the Gibeonites {were} not of the children of Israel, but of the remnant of the Amorites; and the children of Israel had sworn unto them: and Saul sought to slay them in his zeal to the children of Israel and Judah.)', 'and the king called the gibeonites and said unto them now the gibeonites were not of the children of israel but of the remnant of the amorites and the children of israel had sworn unto them and saul sought to slay them in his zeal to the children of israel and judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 21, 3, 'Wherefore David said unto the Gibeonites, What shall I do for you? and wherewith shall I make the atonement, that ye may bless the inheritance of the LORD?', 'wherefore david said unto the gibeonites what shall i do for you and wherewith shall i make the atonement that ye may bless the inheritance of the lord');
