INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 24, 18, 'And Gad came that day to David, and said unto him, Go up, rear an altar unto the LORD in the threshingfloor of Araunah the Jebusite. {Araunah: Heb. Araniah}', 'and gad came that day to david and said unto him go up rear an altar unto the lord in the threshingfloor of araunah the jebusite araunah heb araniah');
