INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 24, 20, 'And Araunah looked, and saw the king and his servants coming on toward him: and Araunah went out, and bowed himself before the king on his face upon the ground.', 'and araunah looked and saw the king and his servants coming on toward him and araunah went out and bowed himself before the king on his face upon the ground');
