INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 24, 22, 'And Araunah said unto David, Let my lord the king take and offer up what {seemeth} good unto him: behold, {here be} oxen for burnt sacrifice, and threshing instruments and {other} instruments of the oxen for wood.', 'and araunah said unto david let my lord the king take and offer up what seemeth good unto him behold here be oxen for burnt sacrifice and threshing instruments and other instruments of the oxen for wood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 24, 23, 'All these {things} did Araunah, {as} a king, give unto the king. And Araunah said unto the king, The LORD thy God accept thee.', 'all these things did araunah as a king give unto the king and araunah said unto the king the lord thy god accept thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 10, 'Unknown', 24, 24, 'And the king said unto Araunah, Nay; but I will surely buy {it} of thee at a price: neither will I offer burnt offerings unto the LORD my God of that which doth cost me nothing. So David bought the threshingfloor and the oxen for fifty shekels of silver.', 'and the king said unto araunah nay but i will surely buy it of thee at a price neither will i offer burnt offerings unto the lord my god of that which doth cost me nothing so david bought the threshingfloor and the oxen for fifty shekels of silver');
