INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 2, 'Wherefore his servants said unto him, Let there be sought for my lord the king a young virgin: and let her stand before the king, and let her cherish him, and let her lie in thy bosom, that my lord the king may get heat. {Let there...: Heb. Let them seek} {a young...: Heb. a damsel, a virgin} {cherish...: Heb. be a cherisher unto him}', 'wherefore his servants said unto him let there be sought for my lord the king a young virgin and let her stand before the king and let her cherish him and let her lie in thy bosom that my lord the king may get heat let there heb let them seek a young heb a damsel a virgin cherish heb be a cherisher unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 3, 'So they sought for a fair damsel throughout all the coasts of Israel, and found Abishag a Shunammite, and brought her to the king.', 'so they sought for a fair damsel throughout all the coasts of israel and found abishag a shunammite and brought her to the king');
