INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 9, 'And Adonijah slew sheep and oxen and fat cattle by the stone of Zoheleth, which {is} by Enrogel, and called all his brethren the king''s sons, and all the men of Judah the king''s servants: {Enrogel: or, the well Rogel}', 'and adonijah slew sheep and oxen and fat cattle by the stone of zoheleth which is by enrogel and called all his brethren the king s sons and all the men of judah the king s servants enrogel or the well rogel');
