INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 17, 'And she said unto him, My lord, thou swarest by the LORD thy God unto thine handmaid, {saying}, Assuredly Solomon thy son shall reign after me, and he shall sit upon my throne.', 'and she said unto him my lord thou swarest by the lord thy god unto thine handmaid saying assuredly solomon thy son shall reign after me and he shall sit upon my throne');
