INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 19, 'And he hath slain oxen and fat cattle and sheep in abundance, and hath called all the sons of the king, and Abiathar the priest, and Joab the captain of the host: but Solomon thy servant hath he not called.', 'and he hath slain oxen and fat cattle and sheep in abundance and hath called all the sons of the king and abiathar the priest and joab the captain of the host but solomon thy servant hath he not called');
