INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 21, 'Otherwise it shall come to pass, when my lord the king shall sleep with his fathers, that I and my son Solomon shall be counted offenders. {offenders: Heb. sinners}', 'otherwise it shall come to pass when my lord the king shall sleep with his fathers that i and my son solomon shall be counted offenders offenders heb sinners');
