INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 23, 'And they told the king, saying, Behold Nathan the prophet. And when he was come in before the king, he bowed himself before the king with his face to the ground.', 'and they told the king saying behold nathan the prophet and when he was come in before the king he bowed himself before the king with his face to the ground');
