INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 25, 'For he is gone down this day, and hath slain oxen and fat cattle and sheep in abundance, and hath called all the king''s sons, and the captains of the host, and Abiathar the priest; and, behold, they eat and drink before him, and say, God save king Adonijah. {God...: Heb. Let king Adonijah live}', 'for he is gone down this day and hath slain oxen and fat cattle and sheep in abundance and hath called all the king s sons and the captains of the host and abiathar the priest and behold they eat and drink before him and say god save king adonijah god heb let king adonijah live');
