INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 30, 'Even as I sware unto thee by the LORD God of Israel, saying, Assuredly Solomon thy son shall reign after me, and he shall sit upon my throne in my stead; even so will I certainly do this day.', 'even as i sware unto thee by the lord god of israel saying assuredly solomon thy son shall reign after me and he shall sit upon my throne in my stead even so will i certainly do this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 31, 'Then Bathsheba bowed with {her} face to the earth, and did reverence to the king, and said, Let my lord king David live for ever.', 'then bathsheba bowed with her face to the earth and did reverence to the king and said let my lord king david live for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 32, 'And king David said, Call me Zadok the priest, and Nathan the prophet, and Benaiah the son of Jehoiada. And they came before the king.', 'and king david said call me zadok the priest and nathan the prophet and benaiah the son of jehoiada and they came before the king');
