INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 34, 'And let Zadok the priest and Nathan the prophet anoint him there king over Israel: and blow ye with the trumpet, and say, God save king Solomon.', 'and let zadok the priest and nathan the prophet anoint him there king over israel and blow ye with the trumpet and say god save king solomon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 35, 'Then ye shall come up after him, that he may come and sit upon my throne; for he shall be king in my stead: and I have appointed him to be ruler over Israel and over Judah.', 'then ye shall come up after him that he may come and sit upon my throne for he shall be king in my stead and i have appointed him to be ruler over israel and over judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 36, 'And Benaiah the son of Jehoiada answered the king, and said, Amen: the LORD God of my lord the king say so {too}.', 'and benaiah the son of jehoiada answered the king and said amen the lord god of my lord the king say so too');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 37, 'As the LORD hath been with my lord the king, even so be he with Solomon, and make his throne greater than the throne of my lord king David.', 'as the lord hath been with my lord the king even so be he with solomon and make his throne greater than the throne of my lord king david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 38, 'So Zadok the priest, and Nathan the prophet, and Benaiah the son of Jehoiada, and the Cherethites, and the Pelethites, went down, and caused Solomon to ride upon king David''s mule, and brought him to Gihon.', 'so zadok the priest and nathan the prophet and benaiah the son of jehoiada and the cherethites and the pelethites went down and caused solomon to ride upon king david s mule and brought him to gihon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 39, 'And Zadok the priest took an horn of oil out of the tabernacle, and anointed Solomon. And they blew the trumpet; and all the people said, God save king Solomon.', 'and zadok the priest took an horn of oil out of the tabernacle and anointed solomon and they blew the trumpet and all the people said god save king solomon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 40, 'And all the people came up after him, and the people piped with pipes, and rejoiced with great joy, so that the earth rent with the sound of them. {pipes: or, flutes}', 'and all the people came up after him and the people piped with pipes and rejoiced with great joy so that the earth rent with the sound of them pipes or flutes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 41, 'And Adonijah and all the guests that {were} with him heard {it} as they had made an end of eating. And when Joab heard the sound of the trumpet, he said, Wherefore {is this} noise of the city being in an uproar?', 'and adonijah and all the guests that were with him heard it as they had made an end of eating and when joab heard the sound of the trumpet he said wherefore is this noise of the city being in an uproar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 1, 42, 'And while he yet spake, behold, Jonathan the son of Abiathar the priest came: and Adonijah said unto him, Come in; for thou {art} a valiant man, and bringest good tidings.', 'and while he yet spake behold jonathan the son of abiathar the priest came and adonijah said unto him come in for thou art a valiant man and bringest good tidings');
