INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 2, 'And Solomon sent to Hiram, saying,', 'and solomon sent to hiram saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 3, 'Thou knowest how that David my father could not build an house unto the name of the LORD his God for the wars which were about him on every side, until the LORD put them under the soles of his feet.', 'thou knowest how that david my father could not build an house unto the name of the lord his god for the wars which were about him on every side until the lord put them under the soles of his feet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 4, 'But now the LORD my God hath given me rest on every side, {so that there is} neither adversary nor evil occurrent.', 'but now the lord my god hath given me rest on every side so that there is neither adversary nor evil occurrent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 5, 'And, behold, I purpose to build an house unto the name of the LORD my God, as the LORD spake unto David my father, saying, Thy son, whom I will set upon thy throne in thy room, he shall build an house unto my name. {purpose: Heb. say}', 'and behold i purpose to build an house unto the name of the lord my god as the lord spake unto david my father saying thy son whom i will set upon thy throne in thy room he shall build an house unto my name purpose heb say');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 6, 'Now therefore command thou that they hew me cedar trees out of Lebanon; and my servants shall be with thy servants: and unto thee will I give hire for thy servants according to all that thou shalt appoint: for thou knowest that {there is} not among us any that can skill to hew timber like unto the Sidonians. {appoint: Heb. say}', 'now therefore command thou that they hew me cedar trees out of lebanon and my servants shall be with thy servants and unto thee will i give hire for thy servants according to all that thou shalt appoint for thou knowest that there is not among us any that can skill to hew timber like unto the sidonians appoint heb say');
