INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 9, 'My servants shall bring {them} down from Lebanon unto the sea: and I will convey them by sea in floats unto the place that thou shalt appoint me, and will cause them to be discharged there, and thou shalt receive {them}: and thou shalt accomplish my desire, in giving food for my household. {appoint: Heb. send}', 'my servants shall bring them down from lebanon unto the sea and i will convey them by sea in floats unto the place that thou shalt appoint me and will cause them to be discharged there and thou shalt receive them and thou shalt accomplish my desire in giving food for my household appoint heb send');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 10, 'So Hiram gave Solomon cedar trees and fir trees {according to} all his desire.', 'so hiram gave solomon cedar trees and fir trees according to all his desire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 11, 'And Solomon gave Hiram twenty thousand measures of wheat {for} food to his household, and twenty measures of pure oil: thus gave Solomon to Hiram year by year. {measures: Heb. cors}', 'and solomon gave hiram twenty thousand measures of wheat for food to his household and twenty measures of pure oil thus gave solomon to hiram year by year measures heb cors');
