INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 15, 'And Solomon had threescore and ten thousand that bare burdens, and fourscore thousand hewers in the mountains;', 'and solomon had threescore and ten thousand that bare burdens and fourscore thousand hewers in the mountains');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 16, 'Beside the chief of Solomon''s officers which {were} over the work, three thousand and three hundred, which ruled over the people that wrought in the work.', 'beside the chief of solomon s officers which were over the work three thousand and three hundred which ruled over the people that wrought in the work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 17, 'And the king commanded, and they brought great stones, costly stones, {and} hewed stones, to lay the foundation of the house.', 'and the king commanded and they brought great stones costly stones and hewed stones to lay the foundation of the house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 5, 18, 'And Solomon''s builders and Hiram''s builders did hew {them}, and the stonesquarers: so they prepared timber and stones to build the house. {stonesquares: or, Giblites}', 'and solomon s builders and hiram s builders did hew them and the stonesquarers so they prepared timber and stones to build the house stonesquares or giblites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 1, 'And it came to pass in the four hundred and eightieth year after the children of Israel were come out of the land of Egypt, in the fourth year of Solomon''s reign over Israel, in the month Zif, which {is} the second month, that he began to build the house of the LORD. {began...: Heb. built}', 'and it came to pass in the four hundred and eightieth year after the children of israel were come out of the land of egypt in the fourth year of solomon s reign over israel in the month zif which is the second month that he began to build the house of the lord began heb built');
