INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 3, 'And the porch before the temple of the house, twenty cubits {was} the length thereof, according to the breadth of the house; {and} ten cubits {was} the breadth thereof before the house.', 'and the porch before the temple of the house twenty cubits was the length thereof according to the breadth of the house and ten cubits was the breadth thereof before the house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 4, 'And for the house he made windows of narrow lights. {of...: or, broad within, and narrow without: or, skewed and closed}', 'and for the house he made windows of narrow lights of or broad within and narrow without or skewed and closed');
