INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 6, 'The nethermost chamber {was} five cubits broad, and the middle {was} six cubits broad, and the third {was} seven cubits broad: for without {in the wall} of the house he made narrowed rests round about, that {the beams} should not be fastened in the walls of the house. {narrowed...: Heb. narrowings, or, rebatements}', 'the nethermost chamber was five cubits broad and the middle was six cubits broad and the third was seven cubits broad for without in the wall of the house he made narrowed rests round about that the beams should not be fastened in the walls of the house narrowed heb narrowings or rebatements');
