INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 8, 'The door for the middle chamber {was} in the right side of the house: and they went up with winding stairs into the middle {chamber}, and out of the middle into the third. {side: Heb. shoulder}', 'the door for the middle chamber was in the right side of the house and they went up with winding stairs into the middle chamber and out of the middle into the third side heb shoulder');
