INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 12, '{Concerning} this house which thou art in building, if thou wilt walk in my statutes, and execute my judgments, and keep all my commandments to walk in them; then will I perform my word with thee, which I spake unto David thy father:', 'concerning this house which thou art in building if thou wilt walk in my statutes and execute my judgments and keep all my commandments to walk in them then will i perform my word with thee which i spake unto david thy father');
