INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 16, 'And he built twenty cubits on the sides of the house, both the floor and the walls with boards of cedar: he even built {them} for it within, {even} for the oracle, {even} for the most holy {place}.', 'and he built twenty cubits on the sides of the house both the floor and the walls with boards of cedar he even built them for it within even for the oracle even for the most holy place');
