INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 23, 'And within the oracle he made two cherubims {of} olive tree, {each} ten cubits high. {olive: or, oily: Heb. trees of oil}', 'and within the oracle he made two cherubims of olive tree each ten cubits high olive or oily heb trees of oil');
