INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 31, 'And for the entering of the oracle he made doors {of} olive tree: the lintel {and} side posts {were} a fifth part {of the wall}. {a fifth...: or, fivesquare}', 'and for the entering of the oracle he made doors of olive tree the lintel and side posts were a fifth part of the wall a fifth or fivesquare');
