INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 6, 34, 'And the two doors {were of} fir tree: the two leaves of the one door {were} folding, and the two leaves of the other door {were} folding.', 'and the two doors were of fir tree the two leaves of the one door were folding and the two leaves of the other door were folding');
