INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 6, 'And he made a porch of pillars; the length thereof {was} fifty cubits, and the breadth thereof thirty cubits: and the porch {was} before them: and the {other} pillars and the thick beam {were} before them. {before them: or, according to them}', 'and he made a porch of pillars the length thereof was fifty cubits and the breadth thereof thirty cubits and the porch was before them and the other pillars and the thick beam were before them before them or according to them');
