INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 15, 'For he cast two pillars of brass, of eighteen cubits high apiece: and a line of twelve cubits did compass either of them about. {cast: Heb. fashioned}', 'for he cast two pillars of brass of eighteen cubits high apiece and a line of twelve cubits did compass either of them about cast heb fashioned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 16, 'And he made two chapiters {of} molten brass, to set upon the tops of the pillars: the height of the one chapiter {was} five cubits, and the height of the other chapiter {was} five cubits:', 'and he made two chapiters of molten brass to set upon the tops of the pillars the height of the one chapiter was five cubits and the height of the other chapiter was five cubits');
