INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 21, 'And he set up the pillars in the porch of the temple: and he set up the right pillar, and called the name thereof Jachin: and he set up the left pillar, and called the name thereof Boaz. {Jachin: that is, He shall establish} {Boaz: that is, In it is strength}', 'and he set up the pillars in the porch of the temple and he set up the right pillar and called the name thereof jachin and he set up the left pillar and called the name thereof boaz jachin that is he shall establish boaz that is in it is strength');
