INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 23, 'And he made a molten sea, ten cubits from the one brim to the other: {it was} round all about, and his height {was} five cubits: and a line of thirty cubits did compass it round about. {from...: Heb. from his brim to his brim}', 'and he made a molten sea ten cubits from the one brim to the other it was round all about and his height was five cubits and a line of thirty cubits did compass it round about from heb from his brim to his brim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 24, 'And under the brim of it round about {there were} knops compassing it, ten in a cubit, compassing the sea round about: the knops {were} cast in two rows, when it was cast.', 'and under the brim of it round about there were knops compassing it ten in a cubit compassing the sea round about the knops were cast in two rows when it was cast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 25, 'It stood upon twelve oxen, three looking toward the north, and three looking toward the west, and three looking toward the south, and three looking toward the east: and the sea {was set} above upon them, and all their hinder parts {were} inward.', 'it stood upon twelve oxen three looking toward the north and three looking toward the west and three looking toward the south and three looking toward the east and the sea was set above upon them and all their hinder parts were inward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 26, 'And it {was} an hand breadth thick, and the brim thereof was wrought like the brim of a cup, with flowers of lilies: it contained two thousand baths.', 'and it was an hand breadth thick and the brim thereof was wrought like the brim of a cup with flowers of lilies it contained two thousand baths');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 27, 'And he made ten bases of brass; four cubits {was} the length of one base, and four cubits the breadth thereof, and three cubits the height of it.', 'and he made ten bases of brass four cubits was the length of one base and four cubits the breadth thereof and three cubits the height of it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 28, 'And the work of the bases {was} on this {manner}: they had borders, and the borders {were} between the ledges:', 'and the work of the bases was on this manner they had borders and the borders were between the ledges');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 29, 'And on the borders that {were} between the ledges {were} lions, oxen, and cherubims: and upon the ledges {there was} a base above: and beneath the lions and oxen {were} certain additions made of thin work.', 'and on the borders that were between the ledges were lions oxen and cherubims and upon the ledges there was a base above and beneath the lions and oxen were certain additions made of thin work');
