INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 31, 'And the mouth of it within the chapiter and above {was} a cubit: but the mouth thereof {was} round {after} the work of the base, a cubit and an half: and also upon the mouth of it {were} gravings with their borders, foursquare, not round.', 'and the mouth of it within the chapiter and above was a cubit but the mouth thereof was round after the work of the base a cubit and an half and also upon the mouth of it were gravings with their borders foursquare not round');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 32, 'And under the borders {were} four wheels; and the axletrees of the wheels {were joined} to the base: and the height of a wheel {was} a cubit and half a cubit. {joined...: Heb. in the base}', 'and under the borders were four wheels and the axletrees of the wheels were joined to the base and the height of a wheel was a cubit and half a cubit joined heb in the base');
