INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 37, 'After this {manner} he made the ten bases: all of them had one casting, one measure, {and} one size.', 'after this manner he made the ten bases all of them had one casting one measure and one size');
