INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 7, 48, 'And Solomon made all the vessels that {pertained} unto the house of the LORD: the altar of gold, and the table of gold, whereupon the shewbread {was},', 'and solomon made all the vessels that pertained unto the house of the lord the altar of gold and the table of gold whereupon the shewbread was');
