INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 10, 'And it came to pass, when the priests were come out of the holy {place}, that the cloud filled the house of the LORD,', 'and it came to pass when the priests were come out of the holy place that the cloud filled the house of the lord');
