INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 16, 'Since the day that I brought forth my people Israel out of Egypt, I chose no city out of all the tribes of Israel to build an house, that my name might be therein; but I chose David to be over my people Israel.', 'since the day that i brought forth my people israel out of egypt i chose no city out of all the tribes of israel to build an house that my name might be therein but i chose david to be over my people israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 17, 'And it was in the heart of David my father to build an house for the name of the LORD God of Israel.', 'and it was in the heart of david my father to build an house for the name of the lord god of israel');
