INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 21, 'And I have set there a place for the ark, wherein {is} the covenant of the LORD, which he made with our fathers, when he brought them out of the land of Egypt.', 'and i have set there a place for the ark wherein is the covenant of the lord which he made with our fathers when he brought them out of the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 22, 'And Solomon stood before the altar of the LORD in the presence of all the congregation of Israel, and spread forth his hands toward heaven:', 'and solomon stood before the altar of the lord in the presence of all the congregation of israel and spread forth his hands toward heaven');
