INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 25, 'Therefore now, LORD God of Israel, keep with thy servant David my father that thou promisedst him, saying, There shall not fail thee a man in my sight to sit on the throne of Israel; so that thy children take heed to their way, that they walk before me as thou hast walked before me. {fail...: Heb. be cut off unto thee a man from my sight} {so that: Heb. only if}', 'therefore now lord god of israel keep with thy servant david my father that thou promisedst him saying there shall not fail thee a man in my sight to sit on the throne of israel so that thy children take heed to their way that they walk before me as thou hast walked before me fail heb be cut off unto thee a man from my sight so that heb only if');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 26, 'And now, O God of Israel, let thy word, I pray thee, be verified, which thou spakest unto thy servant David my father.', 'and now o god of israel let thy word i pray thee be verified which thou spakest unto thy servant david my father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 27, 'But will God indeed dwell on the earth? behold, the heaven and heaven of heavens cannot contain thee; how much less this house that I have builded?', 'but will god indeed dwell on the earth behold the heaven and heaven of heavens cannot contain thee how much less this house that i have builded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 28, 'Yet have thou respect unto the prayer of thy servant, and to his supplication, O LORD my God, to hearken unto the cry and to the prayer, which thy servant prayeth before thee to day:', 'yet have thou respect unto the prayer of thy servant and to his supplication o lord my god to hearken unto the cry and to the prayer which thy servant prayeth before thee to day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 29, 'That thine eyes may be open toward this house night and day, {even} toward the place of which thou hast said, My name shall be there: that thou mayest hearken unto the prayer which thy servant shall make toward this place. {toward this place: or, in this place}', 'that thine eyes may be open toward this house night and day even toward the place of which thou hast said my name shall be there that thou mayest hearken unto the prayer which thy servant shall make toward this place toward this place or in this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 30, 'And hearken thou to the supplication of thy servant, and of thy people Israel, when they shall pray toward this place: and hear thou in heaven thy dwelling place: and when thou hearest, forgive. {toward this place: or, in this place}', 'and hearken thou to the supplication of thy servant and of thy people israel when they shall pray toward this place and hear thou in heaven thy dwelling place and when thou hearest forgive toward this place or in this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 31, 'If any man trespass against his neighbour, and an oath be laid upon him to cause him to swear, and the oath come before thine altar in this house: {and an oath...: Heb. and he require an oath of him}', 'if any man trespass against his neighbour and an oath be laid upon him to cause him to swear and the oath come before thine altar in this house and an oath heb and he require an oath of him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 32, 'Then hear thou in heaven, and do, and judge thy servants, condemning the wicked, to bring his way upon his head; and justifying the righteous, to give him according to his righteousness.', 'then hear thou in heaven and do and judge thy servants condemning the wicked to bring his way upon his head and justifying the righteous to give him according to his righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 33, 'When thy people Israel be smitten down before the enemy, because they have sinned against thee, and shall turn again to thee, and confess thy name, and pray, and make supplication unto thee in this house: {in: or, toward}', 'when thy people israel be smitten down before the enemy because they have sinned against thee and shall turn again to thee and confess thy name and pray and make supplication unto thee in this house in or toward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 34, 'Then hear thou in heaven, and forgive the sin of thy people Israel, and bring them again unto the land which thou gavest unto their fathers.', 'then hear thou in heaven and forgive the sin of thy people israel and bring them again unto the land which thou gavest unto their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 35, 'When heaven is shut up, and there is no rain, because they have sinned against thee; if they pray toward this place, and confess thy name, and turn from their sin, when thou afflictest them:', 'when heaven is shut up and there is no rain because they have sinned against thee if they pray toward this place and confess thy name and turn from their sin when thou afflictest them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 36, 'Then hear thou in heaven, and forgive the sin of thy servants, and of thy people Israel, that thou teach them the good way wherein they should walk, and give rain upon thy land, which thou hast given to thy people for an inheritance.', 'then hear thou in heaven and forgive the sin of thy servants and of thy people israel that thou teach them the good way wherein they should walk and give rain upon thy land which thou hast given to thy people for an inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 37, 'If there be in the land famine, if there be pestilence, blasting, mildew, locust, {or} if there be caterpiller; if their enemy besiege them in the land of their cities; whatsoever plague, whatsoever sickness {there be}; {cities: or, jurisdiction}', 'if there be in the land famine if there be pestilence blasting mildew locust or if there be caterpiller if their enemy besiege them in the land of their cities whatsoever plague whatsoever sickness there be cities or jurisdiction');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 38, 'What prayer and supplication soever be {made} by any man, {or} by all thy people Israel, which shall know every man the plague of his own heart, and spread forth his hands toward this house:', 'what prayer and supplication soever be made by any man or by all thy people israel which shall know every man the plague of his own heart and spread forth his hands toward this house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 39, 'Then hear thou in heaven thy dwelling place, and forgive, and do, and give to every man according to his ways, whose heart thou knowest; (for thou, {even} thou only, knowest the hearts of all the children of men;)', 'then hear thou in heaven thy dwelling place and forgive and do and give to every man according to his ways whose heart thou knowest for thou even thou only knowest the hearts of all the children of men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 40, 'That they may fear thee all the days that they live in the land which thou gavest unto our fathers.', 'that they may fear thee all the days that they live in the land which thou gavest unto our fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 41, 'Moreover concerning a stranger, that {is} not of thy people Israel, but cometh out of a far country for thy name''s sake;', 'moreover concerning a stranger that is not of thy people israel but cometh out of a far country for thy name s sake');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 42, '(For they shall hear of thy great name, and of thy strong hand, and of thy stretched out arm;) when he shall come and pray toward this house;', 'for they shall hear of thy great name and of thy strong hand and of thy stretched out arm when he shall come and pray toward this house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 43, 'Hear thou in heaven thy dwelling place, and do according to all that the stranger calleth to thee for: that all people of the earth may know thy name, to fear thee, as {do} thy people Israel; and that they may know that this house, which I have builded, is called by thy name. {this...: Heb. thy name is called upon this house}', 'hear thou in heaven thy dwelling place and do according to all that the stranger calleth to thee for that all people of the earth may know thy name to fear thee as do thy people israel and that they may know that this house which i have builded is called by thy name this heb thy name is called upon this house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 44, 'If thy people go out to battle against their enemy, whithersoever thou shalt send them, and shall pray unto the LORD toward the city which thou hast chosen, and {toward} the house that I have built for thy name: {toward the city: Heb. the way of the city}', 'if thy people go out to battle against their enemy whithersoever thou shalt send them and shall pray unto the lord toward the city which thou hast chosen and toward the house that i have built for thy name toward the city heb the way of the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 45, 'Then hear thou in heaven their prayer and their supplication, and maintain their cause. {cause: or, right}', 'then hear thou in heaven their prayer and their supplication and maintain their cause cause or right');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 46, 'If they sin against thee, (for {there is} no man that sinneth not,) and thou be angry with them, and deliver them to the enemy, so that they carry them away captives unto the land of the enemy, far or near;', 'if they sin against thee for there is no man that sinneth not and thou be angry with them and deliver them to the enemy so that they carry them away captives unto the land of the enemy far or near');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 47, '{Yet} if they shall bethink themselves in the land whither they were carried captives, and repent, and make supplication unto thee in the land of them that carried them captives, saying, We have sinned, and have done perversely, we have committed wickedness; {bethink...: Heb. bring back to their heart}', 'yet if they shall bethink themselves in the land whither they were carried captives and repent and make supplication unto thee in the land of them that carried them captives saying we have sinned and have done perversely we have committed wickedness bethink heb bring back to their heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 48, 'And {so} return unto thee with all their heart, and with all their soul, in the land of their enemies, which led them away captive, and pray unto thee toward their land, which thou gavest unto their fathers, the city which thou hast chosen, and the house which I have built for thy name:', 'and so return unto thee with all their heart and with all their soul in the land of their enemies which led them away captive and pray unto thee toward their land which thou gavest unto their fathers the city which thou hast chosen and the house which i have built for thy name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 49, 'Then hear thou their prayer and their supplication in heaven thy dwelling place, and maintain their cause, {cause: or, right}', 'then hear thou their prayer and their supplication in heaven thy dwelling place and maintain their cause cause or right');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 50, 'And forgive thy people that have sinned against thee, and all their transgressions wherein they have transgressed against thee, and give them compassion before them who carried them captive, that they may have compassion on them:', 'and forgive thy people that have sinned against thee and all their transgressions wherein they have transgressed against thee and give them compassion before them who carried them captive that they may have compassion on them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 51, 'For they {be} thy people, and thine inheritance, which thou broughtest forth out of Egypt, from the midst of the furnace of iron:', 'for they be thy people and thine inheritance which thou broughtest forth out of egypt from the midst of the furnace of iron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 52, 'That thine eyes may be open unto the supplication of thy servant, and unto the supplication of thy people Israel, to hearken unto them in all that they call for unto thee.', 'that thine eyes may be open unto the supplication of thy servant and unto the supplication of thy people israel to hearken unto them in all that they call for unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 53, 'For thou didst separate them from among all the people of the earth, {to be} thine inheritance, as thou spakest by the hand of Moses thy servant, when thou broughtest our fathers out of Egypt, O Lord GOD.', 'for thou didst separate them from among all the people of the earth to be thine inheritance as thou spakest by the hand of moses thy servant when thou broughtest our fathers out of egypt o lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 54, 'And it was {so}, that when Solomon had made an end of praying all this prayer and supplication unto the LORD, he arose from before the altar of the LORD, from kneeling on his knees with his hands spread up to heaven.', 'and it was so that when solomon had made an end of praying all this prayer and supplication unto the lord he arose from before the altar of the lord from kneeling on his knees with his hands spread up to heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 55, 'And he stood, and blessed all the congregation of Israel with a loud voice, saying,', 'and he stood and blessed all the congregation of israel with a loud voice saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 56, 'Blessed {be} the LORD, that hath given rest unto his people Israel, according to all that he promised: there hath not failed one word of all his good promise, which he promised by the hand of Moses his servant. {failed: Heb. fallen}', 'blessed be the lord that hath given rest unto his people israel according to all that he promised there hath not failed one word of all his good promise which he promised by the hand of moses his servant failed heb fallen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 57, 'The LORD our God be with us, as he was with our fathers: let him not leave us, nor forsake us:', 'the lord our god be with us as he was with our fathers let him not leave us nor forsake us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 58, 'That he may incline our hearts unto him, to walk in all his ways, and to keep his commandments, and his statutes, and his judgments, which he commanded our fathers.', 'that he may incline our hearts unto him to walk in all his ways and to keep his commandments and his statutes and his judgments which he commanded our fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 59, 'And let these my words, wherewith I have made supplication before the LORD, be nigh unto the LORD our God day and night, that he maintain the cause of his servant, and the cause of his people Israel at all times, as the matter shall require: {at all...: Heb. the thing of a day in his day}', 'and let these my words wherewith i have made supplication before the lord be nigh unto the lord our god day and night that he maintain the cause of his servant and the cause of his people israel at all times as the matter shall require at all heb the thing of a day in his day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 60, 'That all the people of the earth may know that the LORD {is} God, {and that there is} none else.', 'that all the people of the earth may know that the lord is god and that there is none else');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 61, 'Let your heart therefore be perfect with the LORD our God, to walk in his statutes, and to keep his commandments, as at this day.', 'let your heart therefore be perfect with the lord our god to walk in his statutes and to keep his commandments as at this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 62, 'And the king, and all Israel with him, offered sacrifice before the LORD.', 'and the king and all israel with him offered sacrifice before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 63, 'And Solomon offered a sacrifice of peace offerings, which he offered unto the LORD, two and twenty thousand oxen, and an hundred and twenty thousand sheep. So the king and all the children of Israel dedicated the house of the LORD.', 'and solomon offered a sacrifice of peace offerings which he offered unto the lord two and twenty thousand oxen and an hundred and twenty thousand sheep so the king and all the children of israel dedicated the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 64, 'The same day did the king hallow the middle of the court that {was} before the house of the LORD: for there he offered burnt offerings, and meat offerings, and the fat of the peace offerings: because the brasen altar that {was} before the LORD {was} too little to receive the burnt offerings, and meat offerings, and the fat of the peace offerings.', 'the same day did the king hallow the middle of the court that was before the house of the lord for there he offered burnt offerings and meat offerings and the fat of the peace offerings because the brasen altar that was before the lord was too little to receive the burnt offerings and meat offerings and the fat of the peace offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 65, 'And at that time Solomon held a feast, and all Israel with him, a great congregation, from the entering in of Hamath unto the river of Egypt, before the LORD our God, seven days and seven days, {even} fourteen days.', 'and at that time solomon held a feast and all israel with him a great congregation from the entering in of hamath unto the river of egypt before the lord our god seven days and seven days even fourteen days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 8, 66, 'On the eighth day he sent the people away: and they blessed the king, and went unto their tents joyful and glad of heart for all the goodness that the LORD had done for David his servant, and for Israel his people. {blessed: or, thanked}', 'on the eighth day he sent the people away and they blessed the king and went unto their tents joyful and glad of heart for all the goodness that the lord had done for david his servant and for israel his people blessed or thanked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 1, 'And it came to pass, when Solomon had finished the building of the house of the LORD, and the king''s house, and all Solomon''s desire which he was pleased to do,', 'and it came to pass when solomon had finished the building of the house of the lord and the king s house and all solomon s desire which he was pleased to do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 2, 'That the LORD appeared to Solomon the second time, as he had appeared unto him at Gibeon.', 'that the lord appeared to solomon the second time as he had appeared unto him at gibeon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 3, 'And the LORD said unto him, I have heard thy prayer and thy supplication, that thou hast made before me: I have hallowed this house, which thou hast built, to put my name there for ever; and mine eyes and mine heart shall be there perpetually.', 'and the lord said unto him i have heard thy prayer and thy supplication that thou hast made before me i have hallowed this house which thou hast built to put my name there for ever and mine eyes and mine heart shall be there perpetually');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 4, 'And if thou wilt walk before me, as David thy father walked, in integrity of heart, and in uprightness, to do according to all that I have commanded thee, {and} wilt keep my statutes and my judgments:', 'and if thou wilt walk before me as david thy father walked in integrity of heart and in uprightness to do according to all that i have commanded thee and wilt keep my statutes and my judgments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 5, 'Then I will establish the throne of thy kingdom upon Israel for ever, as I promised to David thy father, saying, There shall not fail thee a man upon the throne of Israel.', 'then i will establish the throne of thy kingdom upon israel for ever as i promised to david thy father saying there shall not fail thee a man upon the throne of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 6, '{But} if ye shall at all turn from following me, ye or your children, and will not keep my commandments {and} my statutes which I have set before you, but go and serve other gods, and worship them:', 'but if ye shall at all turn from following me ye or your children and will not keep my commandments and my statutes which i have set before you but go and serve other gods and worship them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 7, 'Then will I cut off Israel out of the land which I have given them; and this house, which I have hallowed for my name, will I cast out of my sight; and Israel shall be a proverb and a byword among all people:', 'then will i cut off israel out of the land which i have given them and this house which i have hallowed for my name will i cast out of my sight and israel shall be a proverb and a byword among all people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 8, 'And at this house, {which} is high, every one that passeth by it shall be astonished, and shall hiss; and they shall say, Why hath the LORD done thus unto this land, and to this house?', 'and at this house which is high every one that passeth by it shall be astonished and shall hiss and they shall say why hath the lord done thus unto this land and to this house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 9, 'And they shall answer, Because they forsook the LORD their God, who brought forth their fathers out of the land of Egypt, and have taken hold upon other gods, and have worshipped them, and served them: therefore hath the LORD brought upon them all this evil.', 'and they shall answer because they forsook the lord their god who brought forth their fathers out of the land of egypt and have taken hold upon other gods and have worshipped them and served them therefore hath the lord brought upon them all this evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 10, 'And it came to pass at the end of twenty years, when Solomon had built the two houses, the house of the LORD, and the king''s house,', 'and it came to pass at the end of twenty years when solomon had built the two houses the house of the lord and the king s house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 11, '({Now} Hiram the king of Tyre had furnished Solomon with cedar trees and fir trees, and with gold, according to all his desire,) that then king Solomon gave Hiram twenty cities in the land of Galilee.', 'now hiram the king of tyre had furnished solomon with cedar trees and fir trees and with gold according to all his desire that then king solomon gave hiram twenty cities in the land of galilee');
