INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 20, '{And} all the people {that were} left of the Amorites, Hittites, Perizzites, Hivites, and Jebusites, which {were} not of the children of Israel,', 'and all the people that were left of the amorites hittites perizzites hivites and jebusites which were not of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 21, 'Their children that were left after them in the land, whom the children of Israel also were not able utterly to destroy, upon those did Solomon levy a tribute of bondservice unto this day.', 'their children that were left after them in the land whom the children of israel also were not able utterly to destroy upon those did solomon levy a tribute of bondservice unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 9, 22, 'But of the children of Israel did Solomon make no bondmen: but they {were} men of war, and his servants, and his princes, and his captains, and rulers of his chariots, and his horsemen.', 'but of the children of israel did solomon make no bondmen but they were men of war and his servants and his princes and his captains and rulers of his chariots and his horsemen');
