INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 10, 8, 'Happy {are} thy men, happy {are} these thy servants, which stand continually before thee, {and} that hear thy wisdom.', 'happy are thy men happy are these thy servants which stand continually before thee and that hear thy wisdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 10, 9, 'Blessed be the LORD thy God, which delighted in thee, to set thee on the throne of Israel: because the LORD loved Israel for ever, therefore made he thee king, to do judgment and justice.', 'blessed be the lord thy god which delighted in thee to set thee on the throne of israel because the lord loved israel for ever therefore made he thee king to do judgment and justice');
