INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 18, 23, 'Let them therefore give us two bullocks; and let them choose one bullock for themselves, and cut it in pieces, and lay {it} on wood, and put no fire {under}: and I will dress the other bullock, and lay {it} on wood, and put no fire {under}:', 'let them therefore give us two bullocks and let them choose one bullock for themselves and cut it in pieces and lay it on wood and put no fire under and i will dress the other bullock and lay it on wood and put no fire under');
