INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 19, 12, 'And after the earthquake a fire; {but} the LORD {was} not in the fire: and after the fire a still small voice.', 'and after the earthquake a fire but the lord was not in the fire and after the fire a still small voice');
