INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 19, 18, 'Yet I have left {me} seven thousand in Israel, all the knees which have not bowed unto Baal, and every mouth which hath not kissed him. {I have...: or, I will leave}', 'yet i have left me seven thousand in israel all the knees which have not bowed unto baal and every mouth which hath not kissed him i have or i will leave');
