INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 20, 19, 'So these young men of the princes of the provinces came out of the city, and the army which followed them.', 'so these young men of the princes of the provinces came out of the city and the army which followed them');
