INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 22, 10, 'And the king of Israel and Jehoshaphat the king of Judah sat each on his throne, having put on their robes, in a void place in the entrance of the gate of Samaria; and all the prophets prophesied before them. {void...: Heb. floor}', 'and the king of israel and jehoshaphat the king of judah sat each on his throne having put on their robes in a void place in the entrance of the gate of samaria and all the prophets prophesied before them void heb floor');
