INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 11, 'Unknown', 22, 31, 'But the king of Syria commanded his thirty and two captains that had rule over his chariots, saying, Fight neither with small nor great, save only with the king of Israel.', 'but the king of syria commanded his thirty and two captains that had rule over his chariots saying fight neither with small nor great save only with the king of israel');
