INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 10, 'And the king of Israel said, Alas! that the LORD hath called these three kings together, to deliver them into the hand of Moab!', 'and the king of israel said alas that the lord hath called these three kings together to deliver them into the hand of moab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 11, 'But Jehoshaphat said, {Is there} not here a prophet of the LORD, that we may enquire of the LORD by him? And one of the king of Israel''s servants answered and said, Here {is} Elisha the son of Shaphat, which poured water on the hands of Elijah.', 'but jehoshaphat said is there not here a prophet of the lord that we may enquire of the lord by him and one of the king of israel s servants answered and said here is elisha the son of shaphat which poured water on the hands of elijah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 12, 'And Jehoshaphat said, The word of the LORD is with him. So the king of Israel and Jehoshaphat and the king of Edom went down to him.', 'and jehoshaphat said the word of the lord is with him so the king of israel and jehoshaphat and the king of edom went down to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 13, 'And Elisha said unto the king of Israel, What have I to do with thee? get thee to the prophets of thy father, and to the prophets of thy mother. And the king of Israel said unto him, Nay: for the LORD hath called these three kings together, to deliver them into the hand of Moab.', 'and elisha said unto the king of israel what have i to do with thee get thee to the prophets of thy father and to the prophets of thy mother and the king of israel said unto him nay for the lord hath called these three kings together to deliver them into the hand of moab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 14, 'And Elisha said, {As} the LORD of hosts liveth, before whom I stand, surely, were it not that I regard the presence of Jehoshaphat the king of Judah, I would not look toward thee, nor see thee.', 'and elisha said as the lord of hosts liveth before whom i stand surely were it not that i regard the presence of jehoshaphat the king of judah i would not look toward thee nor see thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 15, 'But now bring me a minstrel. And it came to pass, when the minstrel played, that the hand of the LORD came upon him.', 'but now bring me a minstrel and it came to pass when the minstrel played that the hand of the lord came upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 16, 'And he said, Thus saith the LORD, Make this valley full of ditches.', 'and he said thus saith the lord make this valley full of ditches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 17, 'For thus saith the LORD, Ye shall not see wind, neither shall ye see rain; yet that valley shall be filled with water, that ye may drink, both ye, and your cattle, and your beasts.', 'for thus saith the lord ye shall not see wind neither shall ye see rain yet that valley shall be filled with water that ye may drink both ye and your cattle and your beasts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 18, 'And this is {but} a light thing in the sight of the LORD: he will deliver the Moabites also into your hand.', 'and this is but a light thing in the sight of the lord he will deliver the moabites also into your hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 19, 'And ye shall smite every fenced city, and every choice city, and shall fell every good tree, and stop all wells of water, and mar every good piece of land with stones. {mar: Heb. grieve}', 'and ye shall smite every fenced city and every choice city and shall fell every good tree and stop all wells of water and mar every good piece of land with stones mar heb grieve');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 20, 'And it came to pass in the morning, when the meat offering was offered, that, behold, there came water by the way of Edom, and the country was filled with water.', 'and it came to pass in the morning when the meat offering was offered that behold there came water by the way of edom and the country was filled with water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 3, 21, 'And when all the Moabites heard that the kings were come up to fight against them, they gathered all that were able to put on armour, and upward, and stood in the border. {gathered: Heb. were cried together} {put on...: Heb. gird himself with a girdle}', 'and when all the moabites heard that the kings were come up to fight against them they gathered all that were able to put on armour and upward and stood in the border gathered heb were cried together put on heb gird himself with a girdle');
