INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 5, 12, '{Are} not Abana and Pharpar, rivers of Damascus, better than all the waters of Israel? may I not wash in them, and be clean? So he turned and went away in a rage. {Abana: or, Amana}', 'are not abana and pharpar rivers of damascus better than all the waters of israel may i not wash in them and be clean so he turned and went away in a rage abana or amana');
