INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 5, 14, 'Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean.', 'then went he down and dipped himself seven times in jordan according to the saying of the man of god and his flesh came again like unto the flesh of a little child and he was clean');
