INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 5, 18, 'In this thing the LORD pardon thy servant, {that} when my master goeth into the house of Rimmon to worship there, and he leaneth on my hand, and I bow myself in the house of Rimmon: when I bow down myself in the house of Rimmon, the LORD pardon thy servant in this thing.', 'in this thing the lord pardon thy servant that when my master goeth into the house of rimmon to worship there and he leaneth on my hand and i bow myself in the house of rimmon when i bow down myself in the house of rimmon the lord pardon thy servant in this thing');
