INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 5, 22, 'And he said, All {is} well. My master hath sent me, saying, Behold, even now there be come to me from mount Ephraim two young men of the sons of the prophets: give them, I pray thee, a talent of silver, and two changes of garments.', 'and he said all is well my master hath sent me saying behold even now there be come to me from mount ephraim two young men of the sons of the prophets give them i pray thee a talent of silver and two changes of garments');
