INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 8, 'Then the king of Syria warred against Israel, and took counsel with his servants, saying, In such and such a place {shall be} my camp. {camp: or, encamping}', 'then the king of syria warred against israel and took counsel with his servants saying in such and such a place shall be my camp camp or encamping');
