INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 11, 'Therefore the heart of the king of Syria was sore troubled for this thing; and he called his servants, and said unto them, Will ye not shew me which of us {is} for the king of Israel?', 'therefore the heart of the king of syria was sore troubled for this thing and he called his servants and said unto them will ye not shew me which of us is for the king of israel');
