INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 17, 'And Elisha prayed, and said, LORD, I pray thee, open his eyes, that he may see. And the LORD opened the eyes of the young man; and he saw: and, behold, the mountain {was} full of horses and chariots of fire round about Elisha.', 'and elisha prayed and said lord i pray thee open his eyes that he may see and the lord opened the eyes of the young man and he saw and behold the mountain was full of horses and chariots of fire round about elisha');
