INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 21, 'And the king of Israel said unto Elisha, when he saw them, My father, shall I smite {them}? shall I smite {them}?', 'and the king of israel said unto elisha when he saw them my father shall i smite them shall i smite them');
