INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 23, 'And he prepared great provision for them: and when they had eaten and drunk, he sent them away, and they went to their master. So the bands of Syria came no more into the land of Israel.', 'and he prepared great provision for them and when they had eaten and drunk he sent them away and they went to their master so the bands of syria came no more into the land of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 24, 'And it came to pass after this, that Benhadad king of Syria gathered all his host, and went up, and besieged Samaria.', 'and it came to pass after this that benhadad king of syria gathered all his host and went up and besieged samaria');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 6, 25, 'And there was a great famine in Samaria: and, behold, they besieged it, until an ass''s head was {sold} for fourscore {pieces} of silver, and the fourth part of a cab of dove''s dung for five {pieces} of silver.', 'and there was a great famine in samaria and behold they besieged it until an ass s head was sold for fourscore pieces of silver and the fourth part of a cab of dove s dung for five pieces of silver');
