INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 13, 2, 'And he did {that which was} evil in the sight of the LORD, and followed the sins of Jeroboam the son of Nebat, which made Israel to sin; he departed not therefrom. {followed: Heb. walked after}', 'and he did that which was evil in the sight of the lord and followed the sins of jeroboam the son of nebat which made israel to sin he departed not therefrom followed heb walked after');
