INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 13, 4, 'And Jehoahaz besought the LORD, and the LORD hearkened unto him: for he saw the oppression of Israel, because the king of Syria oppressed them.', 'and jehoahaz besought the lord and the lord hearkened unto him for he saw the oppression of israel because the king of syria oppressed them');
