INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 13, 7, 'Neither did he leave of the people to Jehoahaz but fifty horsemen, and ten chariots, and ten thousand footmen; for the king of Syria had destroyed them, and had made them like the dust by threshing.', 'neither did he leave of the people to jehoahaz but fifty horsemen and ten chariots and ten thousand footmen for the king of syria had destroyed them and had made them like the dust by threshing');
