INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 14, 13, 'And Jehoash king of Israel took Amaziah king of Judah, the son of Jehoash the son of Ahaziah, at Bethshemesh, and came to Jerusalem, and brake down the wall of Jerusalem from the gate of Ephraim unto the corner gate, four hundred cubits.', 'and jehoash king of israel took amaziah king of judah the son of jehoash the son of ahaziah at bethshemesh and came to jerusalem and brake down the wall of jerusalem from the gate of ephraim unto the corner gate four hundred cubits');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 14, 14, 'And he took all the gold and silver, and all the vessels that were found in the house of the LORD, and in the treasures of the king''s house, and hostages, and returned to Samaria.', 'and he took all the gold and silver and all the vessels that were found in the house of the lord and in the treasures of the king s house and hostages and returned to samaria');
