INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 16, 2, 'Twenty years old {was} Ahaz when he began to reign, and reigned sixteen years in Jerusalem, and did not {that which was} right in the sight of the LORD his God, like David his father.', 'twenty years old was ahaz when he began to reign and reigned sixteen years in jerusalem and did not that which was right in the sight of the lord his god like david his father');
