INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 18, 36, 'But the people held their peace, and answered him not a word: for the king''s commandment was, saying, Answer him not.', 'but the people held their peace and answered him not a word for the king s commandment was saying answer him not');
