INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 1, 'And it came to pass, when king Hezekiah heard {it}, that he rent his clothes, and covered himself with sackcloth, and went into the house of the LORD.', 'and it came to pass when king hezekiah heard it that he rent his clothes and covered himself with sackcloth and went into the house of the lord');
