INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 4, 'It may be the LORD thy God will hear all the words of Rabshakeh, whom the king of Assyria his master hath sent to reproach the living God; and will reprove the words which the LORD thy God hath heard: wherefore lift up {thy} prayer for the remnant that are left. {left: Heb. found}', 'it may be the lord thy god will hear all the words of rabshakeh whom the king of assyria his master hath sent to reproach the living god and will reprove the words which the lord thy god hath heard wherefore lift up thy prayer for the remnant that are left left heb found');
