INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 11, 'Behold, thou hast heard what the kings of Assyria have done to all lands, by destroying them utterly: and shalt thou be delivered?', 'behold thou hast heard what the kings of assyria have done to all lands by destroying them utterly and shalt thou be delivered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 12, 'Have the gods of the nations delivered them which my fathers have destroyed; {as} Gozan, and Haran, and Rezeph, and the children of Eden which {were} in Thelasar?', 'have the gods of the nations delivered them which my fathers have destroyed as gozan and haran and rezeph and the children of eden which were in thelasar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 13, 'Where {is} the king of Hamath, and the king of Arpad, and the king of the city of Sepharvaim, of Hena, and Ivah?', 'where is the king of hamath and the king of arpad and the king of the city of sepharvaim of hena and ivah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 14, 'And Hezekiah received the letter of the hand of the messengers, and read it: and Hezekiah went up into the house of the LORD, and spread it before the LORD.', 'and hezekiah received the letter of the hand of the messengers and read it and hezekiah went up into the house of the lord and spread it before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 15, 'And Hezekiah prayed before the LORD, and said, O LORD God of Israel, which dwellest {between} the cherubims, thou art the God, {even} thou alone, of all the kingdoms of the earth; thou hast made heaven and earth.', 'and hezekiah prayed before the lord and said o lord god of israel which dwellest between the cherubims thou art the god even thou alone of all the kingdoms of the earth thou hast made heaven and earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 16, 'LORD, bow down thine ear, and hear: open, LORD, thine eyes, and see: and hear the words of Sennacherib, which hath sent him to reproach the living God.', 'lord bow down thine ear and hear open lord thine eyes and see and hear the words of sennacherib which hath sent him to reproach the living god');
