INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 20, 'Then Isaiah the son of Amoz sent to Hezekiah, saying, Thus saith the LORD God of Israel, {That} which thou hast prayed to me against Sennacherib king of Assyria I have heard.', 'then isaiah the son of amoz sent to hezekiah saying thus saith the lord god of israel that which thou hast prayed to me against sennacherib king of assyria i have heard');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 21, 'This {is} the word that the LORD hath spoken concerning him; The virgin the daughter of Zion hath despised thee, {and} laughed thee to scorn; the daughter of Jerusalem hath shaken her head at thee.', 'this is the word that the lord hath spoken concerning him the virgin the daughter of zion hath despised thee and laughed thee to scorn the daughter of jerusalem hath shaken her head at thee');
