INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 23, 'By thy messengers thou hast reproached the Lord, and hast said, With the multitude of my chariots I am come up to the height of the mountains, to the sides of Lebanon, and will cut down the tall cedar trees thereof, {and} the choice fir trees thereof: and I will enter into the lodgings of his borders, {and into} the forest of his Carmel. {By: Heb. By the hand of} {tall...: Heb. tallness, etc} {of his Carmel: or, and his fruitful field}', 'by thy messengers thou hast reproached the lord and hast said with the multitude of my chariots i am come up to the height of the mountains to the sides of lebanon and will cut down the tall cedar trees thereof and the choice fir trees thereof and i will enter into the lodgings of his borders and into the forest of his carmel by heb by the hand of tall heb tallness etc of his carmel or and his fruitful field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 24, 'I have digged and drunk strange waters, and with the sole of my feet have I dried up all the rivers of besieged places. {besieged: or, fenced}', 'i have digged and drunk strange waters and with the sole of my feet have i dried up all the rivers of besieged places besieged or fenced');
