INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 29, 'And this {shall be} a sign unto thee, Ye shall eat this year such things as grow of themselves, and in the second year that which springeth of the same; and in the third year sow ye, and reap, and plant vineyards, and eat the fruits thereof.', 'and this shall be a sign unto thee ye shall eat this year such things as grow of themselves and in the second year that which springeth of the same and in the third year sow ye and reap and plant vineyards and eat the fruits thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 30, 'And the remnant that is escaped of the house of Judah shall yet again take root downward, and bear fruit upward. {remnant...: Heb. escaping of the house of Judah that remaineth}', 'and the remnant that is escaped of the house of judah shall yet again take root downward and bear fruit upward remnant heb escaping of the house of judah that remaineth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 31, 'For out of Jerusalem shall go forth a remnant, and they that escape out of mount Zion: the zeal of the LORD {of hosts} shall do this. {they...: Heb. the escaping}', 'for out of jerusalem shall go forth a remnant and they that escape out of mount zion the zeal of the lord of hosts shall do this they heb the escaping');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 32, 'Therefore thus saith the LORD concerning the king of Assyria, He shall not come into this city, nor shoot an arrow there, nor come before it with shield, nor cast a bank against it.', 'therefore thus saith the lord concerning the king of assyria he shall not come into this city nor shoot an arrow there nor come before it with shield nor cast a bank against it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 33, 'By the way that he came, by the same shall he return, and shall not come into this city, saith the LORD.', 'by the way that he came by the same shall he return and shall not come into this city saith the lord');
