INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 35, 'And it came to pass that night, that the angel of the LORD went out, and smote in the camp of the Assyrians an hundred fourscore and five thousand: and when they arose early in the morning, behold, they {were} all dead corpses.', 'and it came to pass that night that the angel of the lord went out and smote in the camp of the assyrians an hundred fourscore and five thousand and when they arose early in the morning behold they were all dead corpses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 36, 'So Sennacherib king of Assyria departed, and went and returned, and dwelt at Nineveh.', 'so sennacherib king of assyria departed and went and returned and dwelt at nineveh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 19, 37, 'And it came to pass, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons smote him with the sword: and they escaped into the land of Armenia. And Esarhaddon his son reigned in his stead. {Armenia: Heb. Ararat}', 'and it came to pass as he was worshipping in the house of nisroch his god that adrammelech and sharezer his sons smote him with the sword and they escaped into the land of armenia and esarhaddon his son reigned in his stead armenia heb ararat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 1, 'In those days was Hezekiah sick unto death. And the prophet Isaiah the son of Amoz came to him, and said unto him, Thus saith the LORD, Set thine house in order; for thou shalt die, and not live. {Set...: Heb. Give charge concerning thine house}', 'in those days was hezekiah sick unto death and the prophet isaiah the son of amoz came to him and said unto him thus saith the lord set thine house in order for thou shalt die and not live set heb give charge concerning thine house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 2, 'Then he turned his face to the wall, and prayed unto the LORD, saying,', 'then he turned his face to the wall and prayed unto the lord saying');
