INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 4, 'And it came to pass, afore Isaiah was gone out into the middle court, that the word of the LORD came to him, saying, {court: or, city}', 'and it came to pass afore isaiah was gone out into the middle court that the word of the lord came to him saying court or city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 5, 'Turn again, and tell Hezekiah the captain of my people, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will heal thee: on the third day thou shalt go up unto the house of the LORD.', 'turn again and tell hezekiah the captain of my people thus saith the lord the god of david thy father i have heard thy prayer i have seen thy tears behold i will heal thee on the third day thou shalt go up unto the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 6, 'And I will add unto thy days fifteen years; and I will deliver thee and this city out of the hand of the king of Assyria; and I will defend this city for mine own sake, and for my servant David''s sake.', 'and i will add unto thy days fifteen years and i will deliver thee and this city out of the hand of the king of assyria and i will defend this city for mine own sake and for my servant david s sake');
