INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 8, 'And Hezekiah said unto Isaiah, What {shall be} the sign that the LORD will heal me, and that I shall go up into the house of the LORD the third day?', 'and hezekiah said unto isaiah what shall be the sign that the lord will heal me and that i shall go up into the house of the lord the third day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 9, 'And Isaiah said, This sign shalt thou have of the LORD, that the LORD will do the thing that he hath spoken: shall the shadow go forward ten degrees, or go back ten degrees?', 'and isaiah said this sign shalt thou have of the lord that the lord will do the thing that he hath spoken shall the shadow go forward ten degrees or go back ten degrees');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 10, 'And Hezekiah answered, It is a light thing for the shadow to go down ten degrees: nay, but let the shadow return backward ten degrees.', 'and hezekiah answered it is a light thing for the shadow to go down ten degrees nay but let the shadow return backward ten degrees');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 11, 'And Isaiah the prophet cried unto the LORD: and he brought the shadow ten degrees backward, by which it had gone down in the dial of Ahaz. {dial: Heb. degrees}', 'and isaiah the prophet cried unto the lord and he brought the shadow ten degrees backward by which it had gone down in the dial of ahaz dial heb degrees');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 12, 'At that time Berodachbaladan, the son of Baladan, king of Babylon, sent letters and a present unto Hezekiah: for he had heard that Hezekiah had been sick. {Berodachbaladan: or, Merodachbaladan}', 'at that time berodachbaladan the son of baladan king of babylon sent letters and a present unto hezekiah for he had heard that hezekiah had been sick berodachbaladan or merodachbaladan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 13, 'And Hezekiah hearkened unto them, and shewed them all the house of his precious things, the silver, and the gold, and the spices, and the precious ointment, and {all} the house of his armour, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah shewed them not. {precious things: or, spicery} {armour: or, jewels: Heb. vessels}', 'and hezekiah hearkened unto them and shewed them all the house of his precious things the silver and the gold and the spices and the precious ointment and all the house of his armour and all that was found in his treasures there was nothing in his house nor in all his dominion that hezekiah shewed them not precious things or spicery armour or jewels heb vessels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 14, 'Then came Isaiah the prophet unto king Hezekiah, and said unto him, What said these men? and from whence came they unto thee? And Hezekiah said, They are come from a far country, {even} from Babylon.', 'then came isaiah the prophet unto king hezekiah and said unto him what said these men and from whence came they unto thee and hezekiah said they are come from a far country even from babylon');
