INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 20, 16, 'And Isaiah said unto Hezekiah, Hear the word of the LORD.', 'and isaiah said unto hezekiah hear the word of the lord');
