INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 12, 'Therefore thus saith the LORD God of Israel, Behold, I {am} bringing {such} evil upon Jerusalem and Judah, that whosoever heareth of it, both his ears shall tingle.', 'therefore thus saith the lord god of israel behold i am bringing such evil upon jerusalem and judah that whosoever heareth of it both his ears shall tingle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 13, 'And I will stretch over Jerusalem the line of Samaria, and the plummet of the house of Ahab: and I will wipe Jerusalem as {a man} wipeth a dish, wiping {it}, and turning {it} upside down. {wiping...: Heb. he wipeth and turneth it upon the face thereof}', 'and i will stretch over jerusalem the line of samaria and the plummet of the house of ahab and i will wipe jerusalem as a man wipeth a dish wiping it and turning it upside down wiping heb he wipeth and turneth it upon the face thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 14, 'And I will forsake the remnant of mine inheritance, and deliver them into the hand of their enemies; and they shall become a prey and a spoil to all their enemies;', 'and i will forsake the remnant of mine inheritance and deliver them into the hand of their enemies and they shall become a prey and a spoil to all their enemies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 15, 'Because they have done {that which was} evil in my sight, and have provoked me to anger, since the day their fathers came forth out of Egypt, even unto this day.', 'because they have done that which was evil in my sight and have provoked me to anger since the day their fathers came forth out of egypt even unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 16, 'Moreover Manasseh shed innocent blood very much, till he had filled Jerusalem from one end to another; beside his sin wherewith he made Judah to sin, in doing {that which was} evil in the sight of the LORD. {from...: Heb. from mouth to mouth}', 'moreover manasseh shed innocent blood very much till he had filled jerusalem from one end to another beside his sin wherewith he made judah to sin in doing that which was evil in the sight of the lord from heb from mouth to mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 17, 'Now the rest of the acts of Manasseh, and all that he did, and his sin that he sinned, {are} they not written in the book of the chronicles of the kings of Judah?', 'now the rest of the acts of manasseh and all that he did and his sin that he sinned are they not written in the book of the chronicles of the kings of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 18, 'And Manasseh slept with his fathers, and was buried in the garden of his own house, in the garden of Uzza: and Amon his son reigned in his stead.', 'and manasseh slept with his fathers and was buried in the garden of his own house in the garden of uzza and amon his son reigned in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 19, 'Amon {was} twenty and two years old when he began to reign, and he reigned two years in Jerusalem. And his mother''s name {was} Meshullemeth, the daughter of Haruz of Jotbah.', 'amon was twenty and two years old when he began to reign and he reigned two years in jerusalem and his mother s name was meshullemeth the daughter of haruz of jotbah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 20, 'And he did {that which was} evil in the sight of the LORD, as his father Manasseh did.', 'and he did that which was evil in the sight of the lord as his father manasseh did');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 21, 'And he walked in all the way that his father walked in, and served the idols that his father served, and worshipped them:', 'and he walked in all the way that his father walked in and served the idols that his father served and worshipped them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 22, 'And he forsook the LORD God of his fathers, and walked not in the way of the LORD.', 'and he forsook the lord god of his fathers and walked not in the way of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 23, 'And the servants of Amon conspired against him, and slew the king in his own house.', 'and the servants of amon conspired against him and slew the king in his own house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 24, 'And the people of the land slew all them that had conspired against king Amon; and the people of the land made Josiah his son king in his stead.', 'and the people of the land slew all them that had conspired against king amon and the people of the land made josiah his son king in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 25, 'Now the rest of the acts of Amon which he did, {are} they not written in the book of the chronicles of the kings of Judah?', 'now the rest of the acts of amon which he did are they not written in the book of the chronicles of the kings of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 21, 26, 'And he was buried in his sepulchre in the garden of Uzza: and Josiah his son reigned in his stead. {Josiah: Gr. Josias}', 'and he was buried in his sepulchre in the garden of uzza and josiah his son reigned in his stead josiah gr josias');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 1, 'Josiah {was} eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his mother''s name {was} Jedidah, the daughter of Adaiah of Boscath.', 'josiah was eight years old when he began to reign and he reigned thirty and one years in jerusalem and his mother s name was jedidah the daughter of adaiah of boscath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 2, 'And he did {that which was} right in the sight of the LORD, and walked in all the way of David his father, and turned not aside to the right hand or to the left.', 'and he did that which was right in the sight of the lord and walked in all the way of david his father and turned not aside to the right hand or to the left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 3, 'And it came to pass in the eighteenth year of king Josiah, {that} the king sent Shaphan the son of Azaliah, the son of Meshullam, the scribe, to the house of the LORD, saying,', 'and it came to pass in the eighteenth year of king josiah that the king sent shaphan the son of azaliah the son of meshullam the scribe to the house of the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 4, 'Go up to Hilkiah the high priest, that he may sum the silver which is brought into the house of the LORD, which the keepers of the door have gathered of the people: {door: Heb. threshold}', 'go up to hilkiah the high priest that he may sum the silver which is brought into the house of the lord which the keepers of the door have gathered of the people door heb threshold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 5, 'And let them deliver it into the hand of the doers of the work, that have the oversight of the house of the LORD: and let them give it to the doers of the work which {is} in the house of the LORD, to repair the breaches of the house,', 'and let them deliver it into the hand of the doers of the work that have the oversight of the house of the lord and let them give it to the doers of the work which is in the house of the lord to repair the breaches of the house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 6, 'Unto carpenters, and builders, and masons, and to buy timber and hewn stone to repair the house.', 'unto carpenters and builders and masons and to buy timber and hewn stone to repair the house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 7, 'Howbeit there was no reckoning made with them of the money that was delivered into their hand, because they dealt faithfully.', 'howbeit there was no reckoning made with them of the money that was delivered into their hand because they dealt faithfully');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 8, 'And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it.', 'and hilkiah the high priest said unto shaphan the scribe i have found the book of the law in the house of the lord and hilkiah gave the book to shaphan and he read it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 9, 'And Shaphan the scribe came to the king, and brought the king word again, and said, Thy servants have gathered the money that was found in the house, and have delivered it into the hand of them that do the work, that have the oversight of the house of the LORD. {gathered: Heb. melted}', 'and shaphan the scribe came to the king and brought the king word again and said thy servants have gathered the money that was found in the house and have delivered it into the hand of them that do the work that have the oversight of the house of the lord gathered heb melted');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 10, 'And Shaphan the scribe shewed the king, saying, Hilkiah the priest hath delivered me a book. And Shaphan read it before the king.', 'and shaphan the scribe shewed the king saying hilkiah the priest hath delivered me a book and shaphan read it before the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 11, 'And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes.', 'and it came to pass when the king had heard the words of the book of the law that he rent his clothes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 12, 'And the king commanded Hilkiah the priest, and Ahikam the son of Shaphan, and Achbor the son of Michaiah, and Shaphan the scribe, and Asahiah a servant of the king''s, saying, {Achbor: or, Abdon} {Michaiah: or, Micah}', 'and the king commanded hilkiah the priest and ahikam the son of shaphan and achbor the son of michaiah and shaphan the scribe and asahiah a servant of the king s saying achbor or abdon michaiah or micah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 13, 'Go ye, enquire of the LORD for me, and for the people, and for all Judah, concerning the words of this book that is found: for great {is} the wrath of the LORD that is kindled against us, because our fathers have not hearkened unto the words of this book, to do according unto all that which is written concerning us.', 'go ye enquire of the lord for me and for the people and for all judah concerning the words of this book that is found for great is the wrath of the lord that is kindled against us because our fathers have not hearkened unto the words of this book to do according unto all that which is written concerning us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 14, 'So Hilkiah the priest, and Ahikam, and Achbor, and Shaphan, and Asahiah, went unto Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe; (now she dwelt in Jerusalem in the college;) and they communed with her. {wardrobe: Heb. garments} {in the...: or, in the second part}', 'so hilkiah the priest and ahikam and achbor and shaphan and asahiah went unto huldah the prophetess the wife of shallum the son of tikvah the son of harhas keeper of the wardrobe now she dwelt in jerusalem in the college and they communed with her wardrobe heb garments in the or in the second part');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 15, 'And she said unto them, Thus saith the LORD God of Israel, Tell the man that sent you to me,', 'and she said unto them thus saith the lord god of israel tell the man that sent you to me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 16, 'Thus saith the LORD, Behold, I will bring evil upon this place, and upon the inhabitants thereof, {even} all the words of the book which the king of Judah hath read:', 'thus saith the lord behold i will bring evil upon this place and upon the inhabitants thereof even all the words of the book which the king of judah hath read');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 17, 'Because they have forsaken me, and have burned incense unto other gods, that they might provoke me to anger with all the works of their hands; therefore my wrath shall be kindled against this place, and shall not be quenched.', 'because they have forsaken me and have burned incense unto other gods that they might provoke me to anger with all the works of their hands therefore my wrath shall be kindled against this place and shall not be quenched');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 18, 'But to the king of Judah which sent you to enquire of the LORD, thus shall ye say to him, Thus saith the LORD God of Israel, {As touching} the words which thou hast heard;', 'but to the king of judah which sent you to enquire of the lord thus shall ye say to him thus saith the lord god of israel as touching the words which thou hast heard');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 19, 'Because thine heart was tender, and thou hast humbled thyself before the LORD, when thou heardest what I spake against this place, and against the inhabitants thereof, that they should become a desolation and a curse, and hast rent thy clothes, and wept before me; I also have heard {thee}, saith the LORD.', 'because thine heart was tender and thou hast humbled thyself before the lord when thou heardest what i spake against this place and against the inhabitants thereof that they should become a desolation and a curse and hast rent thy clothes and wept before me i also have heard thee saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 22, 20, 'Behold therefore, I will gather thee unto thy fathers, and thou shalt be gathered into thy grave in peace; and thine eyes shall not see all the evil which I will bring upon this place. And they brought the king word again.', 'behold therefore i will gather thee unto thy fathers and thou shalt be gathered into thy grave in peace and thine eyes shall not see all the evil which i will bring upon this place and they brought the king word again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 1, 'And the king sent, and they gathered unto him all the elders of Judah and of Jerusalem.', 'and the king sent and they gathered unto him all the elders of judah and of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 2, 'And the king went up into the house of the LORD, and all the men of Judah and all the inhabitants of Jerusalem with him, and the priests, and the prophets, and all the people, both small and great: and he read in their ears all the words of the book of the covenant which was found in the house of the LORD. {both...: Heb. from small even unto great}', 'and the king went up into the house of the lord and all the men of judah and all the inhabitants of jerusalem with him and the priests and the prophets and all the people both small and great and he read in their ears all the words of the book of the covenant which was found in the house of the lord both heb from small even unto great');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 3, 'And the king stood by a pillar, and made a covenant before the LORD, to walk after the LORD, and to keep his commandments and his testimonies and his statutes with all {their} heart and all {their} soul, to perform the words of this covenant that were written in this book. And all the people stood to the covenant.', 'and the king stood by a pillar and made a covenant before the lord to walk after the lord and to keep his commandments and his testimonies and his statutes with all their heart and all their soul to perform the words of this covenant that were written in this book and all the people stood to the covenant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 4, 'And the king commanded Hilkiah the high priest, and the priests of the second order, and the keepers of the door, to bring forth out of the temple of the LORD all the vessels that were made for Baal, and for the grove, and for all the host of heaven: and he burned them without Jerusalem in the fields of Kidron, and carried the ashes of them unto Bethel.', 'and the king commanded hilkiah the high priest and the priests of the second order and the keepers of the door to bring forth out of the temple of the lord all the vessels that were made for baal and for the grove and for all the host of heaven and he burned them without jerusalem in the fields of kidron and carried the ashes of them unto bethel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 5, 'And he put down the idolatrous priests, whom the kings of Judah had ordained to burn incense in the high places in the cities of Judah, and in the places round about Jerusalem; them also that burned incense unto Baal, to the sun, and to the moon, and to the planets, and to all the host of heaven. {put...: Heb. caused to cease} {idolatrous...: Heb. Chemarim} {planets: or, twelve signs or, constellations}', 'and he put down the idolatrous priests whom the kings of judah had ordained to burn incense in the high places in the cities of judah and in the places round about jerusalem them also that burned incense unto baal to the sun and to the moon and to the planets and to all the host of heaven put heb caused to cease idolatrous heb chemarim planets or twelve signs or constellations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 6, 'And he brought out the grove from the house of the LORD, without Jerusalem, unto the brook Kidron, and burned it at the brook Kidron, and stamped {it} small to powder, and cast the powder thereof upon the graves of the children of the people.', 'and he brought out the grove from the house of the lord without jerusalem unto the brook kidron and burned it at the brook kidron and stamped it small to powder and cast the powder thereof upon the graves of the children of the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 7, 'And he brake down the houses of the sodomites, that {were} by the house of the LORD, where the women wove hangings for the grove. {hangings: Heb. houses}', 'and he brake down the houses of the sodomites that were by the house of the lord where the women wove hangings for the grove hangings heb houses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 8, 'And he brought all the priests out of the cities of Judah, and defiled the high places where the priests had burned incense, from Geba to Beersheba, and brake down the high places of the gates that {were} in the entering in of the gate of Joshua the governor of the city, which {were} on a man''s left hand at the gate of the city.', 'and he brought all the priests out of the cities of judah and defiled the high places where the priests had burned incense from geba to beersheba and brake down the high places of the gates that were in the entering in of the gate of joshua the governor of the city which were on a man s left hand at the gate of the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 9, 'Nevertheless the priests of the high places came not up to the altar of the LORD in Jerusalem, but they did eat of the unleavened bread among their brethren.', 'nevertheless the priests of the high places came not up to the altar of the lord in jerusalem but they did eat of the unleavened bread among their brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 10, 'And he defiled Topheth, which {is} in the valley of the children of Hinnom, that no man might make his son or his daughter to pass through the fire to Molech.', 'and he defiled topheth which is in the valley of the children of hinnom that no man might make his son or his daughter to pass through the fire to molech');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 11, 'And he took away the horses that the kings of Judah had given to the sun, at the entering in of the house of the LORD, by the chamber of Nathanmelech the chamberlain, which {was} in the suburbs, and burned the chariots of the sun with fire. {chamberlain: or, eunuch, or, officer}', 'and he took away the horses that the kings of judah had given to the sun at the entering in of the house of the lord by the chamber of nathanmelech the chamberlain which was in the suburbs and burned the chariots of the sun with fire chamberlain or eunuch or officer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 12, 'And the altars that {were} on the top of the upper chamber of Ahaz, which the kings of Judah had made, and the altars which Manasseh had made in the two courts of the house of the LORD, did the king beat down, and brake {them} down from thence, and cast the dust of them into the brook Kidron. {brake...: or, ran from thence}', 'and the altars that were on the top of the upper chamber of ahaz which the kings of judah had made and the altars which manasseh had made in the two courts of the house of the lord did the king beat down and brake them down from thence and cast the dust of them into the brook kidron brake or ran from thence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 13, 'And the high places that {were} before Jerusalem, which {were} on the right hand of the mount of corruption, which Solomon the king of Israel had builded for Ashtoreth the abomination of the Zidonians, and for Chemosh the abomination of the Moabites, and for Milcom the abomination of the children of Ammon, did the king defile. {the mount...: that is, the mount of Olives}', 'and the high places that were before jerusalem which were on the right hand of the mount of corruption which solomon the king of israel had builded for ashtoreth the abomination of the zidonians and for chemosh the abomination of the moabites and for milcom the abomination of the children of ammon did the king defile the mount that is the mount of olives');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 14, 'And he brake in pieces the images, and cut down the groves, and filled their places with the bones of men. {images: Heb. statues}', 'and he brake in pieces the images and cut down the groves and filled their places with the bones of men images heb statues');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 15, 'Moreover the altar that {was} at Bethel, {and} the high place which Jeroboam the son of Nebat, who made Israel to sin, had made, both that altar and the high place he brake down, and burned the high place, {and} stamped {it} small to powder, and burned the grove.', 'moreover the altar that was at bethel and the high place which jeroboam the son of nebat who made israel to sin had made both that altar and the high place he brake down and burned the high place and stamped it small to powder and burned the grove');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 16, 'And as Josiah turned himself, he spied the sepulchres that {were} there in the mount, and sent, and took the bones out of the sepulchres, and burned {them} upon the altar, and polluted it, according to the word of the LORD which the man of God proclaimed, who proclaimed these words.', 'and as josiah turned himself he spied the sepulchres that were there in the mount and sent and took the bones out of the sepulchres and burned them upon the altar and polluted it according to the word of the lord which the man of god proclaimed who proclaimed these words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 17, 'Then he said, What title {is} that that I see? And the men of the city told him, {It is} the sepulchre of the man of God, which came from Judah, and proclaimed these things that thou hast done against the altar of Bethel.', 'then he said what title is that that i see and the men of the city told him it is the sepulchre of the man of god which came from judah and proclaimed these things that thou hast done against the altar of bethel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 18, 'And he said, Let him alone; let no man move his bones. So they let his bones alone, with the bones of the prophet that came out of Samaria. {bones alone: Heb. bones to escape}', 'and he said let him alone let no man move his bones so they let his bones alone with the bones of the prophet that came out of samaria bones alone heb bones to escape');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 19, 'And all the houses also of the high places that {were} in the cities of Samaria, which the kings of Israel had made to provoke {the LORD} to anger, Josiah took away, and did to them according to all the acts that he had done in Bethel.', 'and all the houses also of the high places that were in the cities of samaria which the kings of israel had made to provoke the lord to anger josiah took away and did to them according to all the acts that he had done in bethel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 20, 'And he slew all the priests of the high places that {were} there upon the altars, and burned men''s bones upon them, and returned to Jerusalem. {slew: or, sacrificed}', 'and he slew all the priests of the high places that were there upon the altars and burned men s bones upon them and returned to jerusalem slew or sacrificed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 23, 21, 'And the king commanded all the people, saying, Keep the passover unto the LORD your God, as {it is} written in the book of this covenant.', 'and the king commanded all the people saying keep the passover unto the lord your god as it is written in the book of this covenant');
