INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 5, 'Now the rest of the acts of Jehoiakim, and all that he did, {are} they not written in the book of the chronicles of the kings of Judah?', 'now the rest of the acts of jehoiakim and all that he did are they not written in the book of the chronicles of the kings of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 6, 'So Jehoiakim slept with his fathers: and Jehoiachin his son reigned in his stead.', 'so jehoiakim slept with his fathers and jehoiachin his son reigned in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 7, 'And the king of Egypt came not again any more out of his land: for the king of Babylon had taken from the river of Egypt unto the river Euphrates all that pertained to the king of Egypt.', 'and the king of egypt came not again any more out of his land for the king of babylon had taken from the river of egypt unto the river euphrates all that pertained to the king of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 8, 'Jehoiachin {was} eighteen years old when he began to reign, and he reigned in Jerusalem three months. And his mother''s name {was} Nehushta, the daughter of Elnathan of Jerusalem. {Jehoiachin: also called Jeconiah and Coniah}', 'jehoiachin was eighteen years old when he began to reign and he reigned in jerusalem three months and his mother s name was nehushta the daughter of elnathan of jerusalem jehoiachin also called jeconiah and coniah');
