INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 10, 'At that time the servants of Nebuchadnezzar king of Babylon came up against Jerusalem, and the city was besieged. {was...: Heb. came into siege}', 'at that time the servants of nebuchadnezzar king of babylon came up against jerusalem and the city was besieged was heb came into siege');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 11, 'And Nebuchadnezzar king of Babylon came against the city, and his servants did besiege it.', 'and nebuchadnezzar king of babylon came against the city and his servants did besiege it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 12, 'And Jehoiachin the king of Judah went out to the king of Babylon, he, and his mother, and his servants, and his princes, and his officers: and the king of Babylon took him in the eighth year of his reign. {officers: or, eunuchs} {his reign: Nebuchadnezzar''s eighth year}', 'and jehoiachin the king of judah went out to the king of babylon he and his mother and his servants and his princes and his officers and the king of babylon took him in the eighth year of his reign officers or eunuchs his reign nebuchadnezzar s eighth year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 13, 'And he carried out thence all the treasures of the house of the LORD, and the treasures of the king''s house, and cut in pieces all the vessels of gold which Solomon king of Israel had made in the temple of the LORD, as the LORD had said.', 'and he carried out thence all the treasures of the house of the lord and the treasures of the king s house and cut in pieces all the vessels of gold which solomon king of israel had made in the temple of the lord as the lord had said');
