INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 16, 'And all the men of might, {even} seven thousand, and craftsmen and smiths a thousand, all {that were} strong {and} apt for war, even them the king of Babylon brought captive to Babylon.', 'and all the men of might even seven thousand and craftsmen and smiths a thousand all that were strong and apt for war even them the king of babylon brought captive to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 17, 'And the king of Babylon made Mattaniah his father''s brother king in his stead, and changed his name to Zedekiah.', 'and the king of babylon made mattaniah his father s brother king in his stead and changed his name to zedekiah');
