INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 19, 'And he did {that which was} evil in the sight of the LORD, according to all that Jehoiakim had done.', 'and he did that which was evil in the sight of the lord according to all that jehoiakim had done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 24, 20, 'For through the anger of the LORD it came to pass in Jerusalem and Judah, until he had cast them out from his presence, that Zedekiah rebelled against the king of Babylon.', 'for through the anger of the lord it came to pass in jerusalem and judah until he had cast them out from his presence that zedekiah rebelled against the king of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 1, 'And it came to pass in the ninth year of his reign, in the tenth month, in the tenth {day} of the month, {that} Nebuchadnezzar king of Babylon came, he, and all his host, against Jerusalem, and pitched against it; and they built forts against it round about.', 'and it came to pass in the ninth year of his reign in the tenth month in the tenth day of the month that nebuchadnezzar king of babylon came he and all his host against jerusalem and pitched against it and they built forts against it round about');
