INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 3, 'And on the ninth {day} of the {fourth} month the famine prevailed in the city, and there was no bread for the people of the land.', 'and on the ninth day of the fourth month the famine prevailed in the city and there was no bread for the people of the land');
