INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 6, 'So they took the king, and brought him up to the king of Babylon to Riblah; and they gave judgment upon him. {gave...: Heb. spake judgment with him}', 'so they took the king and brought him up to the king of babylon to riblah and they gave judgment upon him gave heb spake judgment with him');
