INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 11, 'Now the rest of the people {that were} left in the city, and the fugitives that fell away to the king of Babylon, with the remnant of the multitude, did Nebuzaradan the captain of the guard carry away. {fugitives: Heb. fallen away}', 'now the rest of the people that were left in the city and the fugitives that fell away to the king of babylon with the remnant of the multitude did nebuzaradan the captain of the guard carry away fugitives heb fallen away');
