INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 13, 'And the pillars of brass that {were} in the house of the LORD, and the bases, and the brasen sea that {was} in the house of the LORD, did the Chaldees break in pieces, and carried the brass of them to Babylon.', 'and the pillars of brass that were in the house of the lord and the bases and the brasen sea that was in the house of the lord did the chaldees break in pieces and carried the brass of them to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 14, 'And the pots, and the shovels, and the snuffers, and the spoons, and all the vessels of brass wherewith they ministered, took they away.', 'and the pots and the shovels and the snuffers and the spoons and all the vessels of brass wherewith they ministered took they away');
