INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 16, 'The two pillars, one sea, and the bases which Solomon had made for the house of the LORD; the brass of all these vessels was without weight. {one...: Heb. the one sea}', 'the two pillars one sea and the bases which solomon had made for the house of the lord the brass of all these vessels was without weight one heb the one sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 17, 'The height of the one pillar {was} eighteen cubits, and the chapiter upon it {was} brass: and the height of the chapiter three cubits; and the wreathen work, and pomegranates upon the chapiter round about, all of brass: and like unto these had the second pillar with wreathen work.', 'the height of the one pillar was eighteen cubits and the chapiter upon it was brass and the height of the chapiter three cubits and the wreathen work and pomegranates upon the chapiter round about all of brass and like unto these had the second pillar with wreathen work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 18, 'And the captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the door: {door: Heb. threshold}', 'and the captain of the guard took seraiah the chief priest and zephaniah the second priest and the three keepers of the door door heb threshold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 19, 'And out of the city he took an officer that was set over the men of war, and five men of them that were in the king''s presence, which were found in the city, and the principal scribe of the host, which mustered the people of the land, and threescore men of the people of the land {that were} found in the city: {officer: or, eunuch} {were in...: Heb. saw the king''s face} {principal...: or, scribe of the captain of the host}', 'and out of the city he took an officer that was set over the men of war and five men of them that were in the king s presence which were found in the city and the principal scribe of the host which mustered the people of the land and threescore men of the people of the land that were found in the city officer or eunuch were in heb saw the king s face principal or scribe of the captain of the host');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 20, 'And Nebuzaradan captain of the guard took these, and brought them to the king of Babylon to Riblah:', 'and nebuzaradan captain of the guard took these and brought them to the king of babylon to riblah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 21, 'And the king of Babylon smote them, and slew them at Riblah in the land of Hamath. So Judah was carried away out of their land.', 'and the king of babylon smote them and slew them at riblah in the land of hamath so judah was carried away out of their land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 22, 'And {as for} the people that remained in the land of Judah, whom Nebuchadnezzar king of Babylon had left, even over them he made Gedaliah the son of Ahikam, the son of Shaphan, ruler.', 'and as for the people that remained in the land of judah whom nebuchadnezzar king of babylon had left even over them he made gedaliah the son of ahikam the son of shaphan ruler');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 23, 'And when all the captains of the armies, they and their men, heard that the king of Babylon had made Gedaliah governor, there came to Gedaliah to Mizpah, even Ishmael the son of Nethaniah, and Johanan the son of Careah, and Seraiah the son of Tanhumeth the Netophathite, and Jaazaniah the son of a Maachathite, they and their men.', 'and when all the captains of the armies they and their men heard that the king of babylon had made gedaliah governor there came to gedaliah to mizpah even ishmael the son of nethaniah and johanan the son of careah and seraiah the son of tanhumeth the netophathite and jaazaniah the son of a maachathite they and their men');
