INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 12, 'Unknown', 25, 25, 'But it came to pass in the seventh month, that Ishmael the son of Nethaniah, the son of Elishama, of the seed royal, came, and ten men with him, and smote Gedaliah, that he died, and the Jews and the Chaldees that were with him at Mizpah. {royal: Heb. of the kingdom}', 'but it came to pass in the seventh month that ishmael the son of nethaniah the son of elishama of the seed royal came and ten men with him and smote gedaliah that he died and the jews and the chaldees that were with him at mizpah royal heb of the kingdom');
