INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 11, 11, 'And this {is} the number of the mighty men whom David had; Jashobeam, an Hachmonite, the chief of the captains: he lifted up his spear against three hundred slain {by him} at one time. {an Hachmonite: or, son of Hachmoni}', 'and this is the number of the mighty men whom david had jashobeam an hachmonite the chief of the captains he lifted up his spear against three hundred slain by him at one time an hachmonite or son of hachmoni');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 11, 12, 'And after him {was} Eleazar the son of Dodo, the Ahohite, who {was one} of the three mighties.', 'and after him was eleazar the son of dodo the ahohite who was one of the three mighties');
