INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 12, 'He shall build me an house, and I will stablish his throne for ever.', 'he shall build me an house and i will stablish his throne for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 13, 'I will be his father, and he shall be my son: and I will not take my mercy away from him, as I took {it} from {him} that was before thee:', 'i will be his father and he shall be my son and i will not take my mercy away from him as i took it from him that was before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 14, 'But I will settle him in mine house and in my kingdom for ever: and his throne shall be established for evermore.', 'but i will settle him in mine house and in my kingdom for ever and his throne shall be established for evermore');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 15, 'According to all these words, and according to all this vision, so did Nathan speak unto David.', 'according to all these words and according to all this vision so did nathan speak unto david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 16, 'And David the king came and sat before the LORD, and said, Who {am} I, O LORD God, and what {is} mine house, that thou hast brought me hitherto?', 'and david the king came and sat before the lord and said who am i o lord god and what is mine house that thou hast brought me hitherto');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 17, 'And {yet} this was a small thing in thine eyes, O God; for thou hast {also} spoken of thy servant''s house for a great while to come, and hast regarded me according to the estate of a man of high degree, O LORD God.', 'and yet this was a small thing in thine eyes o god for thou hast also spoken of thy servant s house for a great while to come and hast regarded me according to the estate of a man of high degree o lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 18, 'What can David {speak} more to thee for the honour of thy servant? for thou knowest thy servant.', 'what can david speak more to thee for the honour of thy servant for thou knowest thy servant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 19, 'O LORD, for thy servant''s sake, and according to thine own heart, hast thou done all this greatness, in making known all {these} great things. {great...: Heb. greatnesses}', 'o lord for thy servant s sake and according to thine own heart hast thou done all this greatness in making known all these great things great heb greatnesses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 20, 'O LORD, {there is} none like thee, neither {is there any} God beside thee, according to all that we have heard with our ears.', 'o lord there is none like thee neither is there any god beside thee according to all that we have heard with our ears');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 21, 'And what one nation in the earth {is} like thy people Israel, whom God went to redeem {to be} his own people, to make thee a name of greatness and terribleness, by driving out nations from before thy people, whom thou hast redeemed out of Egypt?', 'and what one nation in the earth is like thy people israel whom god went to redeem to be his own people to make thee a name of greatness and terribleness by driving out nations from before thy people whom thou hast redeemed out of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 22, 'For thy people Israel didst thou make thine own people for ever; and thou, LORD, becamest their God.', 'for thy people israel didst thou make thine own people for ever and thou lord becamest their god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 23, 'Therefore now, LORD, let the thing that thou hast spoken concerning thy servant and concerning his house be established for ever, and do as thou hast said.', 'therefore now lord let the thing that thou hast spoken concerning thy servant and concerning his house be established for ever and do as thou hast said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 24, 'Let it even be established, that thy name may be magnified for ever, saying, The LORD of hosts {is} the God of Israel, {even} a God to Israel: and {let} the house of David thy servant {be} established before thee.', 'let it even be established that thy name may be magnified for ever saying the lord of hosts is the god of israel even a god to israel and let the house of david thy servant be established before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 25, 'For thou, O my God, hast told thy servant that thou wilt build him an house: therefore thy servant hath found {in his heart} to pray before thee. {hast...: Heb. hast revealed the ear of thy servant}', 'for thou o my god hast told thy servant that thou wilt build him an house therefore thy servant hath found in his heart to pray before thee hast heb hast revealed the ear of thy servant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 26, 'And now, LORD, thou art God, and hast promised this goodness unto thy servant:', 'and now lord thou art god and hast promised this goodness unto thy servant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 17, 27, 'Now therefore let it please thee to bless the house of thy servant, that it may be before thee for ever: for thou blessest, O LORD, and {it shall be} blessed for ever. {let...: or, it hath pleased thee}', 'now therefore let it please thee to bless the house of thy servant that it may be before thee for ever for thou blessest o lord and it shall be blessed for ever let or it hath pleased thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 1, 'Now after this it came to pass, that David smote the Philistines, and subdued them, and took Gath and her towns out of the hand of the Philistines.', 'now after this it came to pass that david smote the philistines and subdued them and took gath and her towns out of the hand of the philistines');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 2, 'And he smote Moab; and the Moabites became David''s servants, {and} brought gifts.', 'and he smote moab and the moabites became david s servants and brought gifts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 3, 'And David smote Hadarezer king of Zobah unto Hamath, as he went to stablish his dominion by the river Euphrates. {Hadarezer: or, Hadadezer}', 'and david smote hadarezer king of zobah unto hamath as he went to stablish his dominion by the river euphrates hadarezer or hadadezer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 4, 'And David took from him a thousand chariots, and seven thousand horsemen, and twenty thousand footmen: David also houghed all the chariot {horses}, but reserved of them an hundred chariots. {seven...: or, seven hundred}', 'and david took from him a thousand chariots and seven thousand horsemen and twenty thousand footmen david also houghed all the chariot horses but reserved of them an hundred chariots seven or seven hundred');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 5, 'And when the Syrians of Damascus came to help Hadarezer king of Zobah, David slew of the Syrians two and twenty thousand men. {Damascus: Heb. Darmesek}', 'and when the syrians of damascus came to help hadarezer king of zobah david slew of the syrians two and twenty thousand men damascus heb darmesek');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 6, 'Then David put {garrisons} in Syriadamascus; and the Syrians became David''s servants, {and} brought gifts. Thus the LORD preserved David whithersoever he went.', 'then david put garrisons in syriadamascus and the syrians became david s servants and brought gifts thus the lord preserved david whithersoever he went');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 7, 'And David took the shields of gold that were on the servants of Hadarezer, and brought them to Jerusalem.', 'and david took the shields of gold that were on the servants of hadarezer and brought them to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 8, 'Likewise from Tibhath, and from Chun, cities of Hadarezer, brought David very much brass, wherewith Solomon made the brasen sea, and the pillars, and the vessels of brass. {Tibhath...: called in the book of Samuel Betah, and Berothai}', 'likewise from tibhath and from chun cities of hadarezer brought david very much brass wherewith solomon made the brasen sea and the pillars and the vessels of brass tibhath called in the book of samuel betah and berothai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 9, 'Now when Tou king of Hamath heard how David had smitten all the host of Hadarezer king of Zobah; {Tou: also called, Toi}', 'now when tou king of hamath heard how david had smitten all the host of hadarezer king of zobah tou also called toi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 10, 'He sent Hadoram his son to king David, to enquire of his welfare, and to congratulate him, because he had fought against Hadarezer, and smitten him; (for Hadarezer had war with Tou;) and {with him} all manner of vessels of gold and silver and brass. {Hadoram: also called, Joram} {to enquire...: or, to salute} {to congratulate: Heb. to bless} {had war: Heb. was the man of wars}', 'he sent hadoram his son to king david to enquire of his welfare and to congratulate him because he had fought against hadarezer and smitten him for hadarezer had war with tou and with him all manner of vessels of gold and silver and brass hadoram also called joram to enquire or to salute to congratulate heb to bless had war heb was the man of wars');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 11, 'Them also king David dedicated unto the LORD, with the silver and the gold that he brought from all {these} nations; from Edom, and from Moab, and from the children of Ammon, and from the Philistines, and from Amalek.', 'them also king david dedicated unto the lord with the silver and the gold that he brought from all these nations from edom and from moab and from the children of ammon and from the philistines and from amalek');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 12, 'Moreover Abishai the son of Zeruiah slew of the Edomites in the valley of salt eighteen thousand. {Abishai: Heb. Abshai}', 'moreover abishai the son of zeruiah slew of the edomites in the valley of salt eighteen thousand abishai heb abshai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 13, 'And he put garrisons in Edom; and all the Edomites became David''s servants. Thus the LORD preserved David whithersoever he went.', 'and he put garrisons in edom and all the edomites became david s servants thus the lord preserved david whithersoever he went');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 14, 'So David reigned over all Israel, and executed judgment and justice among all his people.', 'so david reigned over all israel and executed judgment and justice among all his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 15, 'And Joab the son of Zeruiah {was} over the host; and Jehoshaphat the son of Ahilud, recorder. {recorder: or, remembrancer}', 'and joab the son of zeruiah was over the host and jehoshaphat the son of ahilud recorder recorder or remembrancer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 16, 'And Zadok the son of Ahitub, and Abimelech the son of Abiathar, {were} the priests; and Shavsha was scribe; {Abimelech: also called, Ahimelech} {Shavsha: also called Seraiah or Shisha}', 'and zadok the son of ahitub and abimelech the son of abiathar were the priests and shavsha was scribe abimelech also called ahimelech shavsha also called seraiah or shisha');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 18, 17, 'And Benaiah the son of Jehoiada {was} over the Cherethites and the Pelethites; and the sons of David {were} chief about the king. {about...: Heb. at the hand of the king}', 'and benaiah the son of jehoiada was over the cherethites and the pelethites and the sons of david were chief about the king about heb at the hand of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 1, 'Now it came to pass after this, that Nahash the king of the children of Ammon died, and his son reigned in his stead.', 'now it came to pass after this that nahash the king of the children of ammon died and his son reigned in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 2, 'And David said, I will shew kindness unto Hanun the son of Nahash, because his father shewed kindness to me. And David sent messengers to comfort him concerning his father. So the servants of David came into the land of the children of Ammon to Hanun, to comfort him.', 'and david said i will shew kindness unto hanun the son of nahash because his father shewed kindness to me and david sent messengers to comfort him concerning his father so the servants of david came into the land of the children of ammon to hanun to comfort him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 3, 'But the princes of the children of Ammon said to Hanun, Thinkest thou that David doth honour thy father, that he hath sent comforters unto thee? are not his servants come unto thee for to search, and to overthrow, and to spy out the land? {Thinkest...: Heb. In thine eyes doth David, etc}', 'but the princes of the children of ammon said to hanun thinkest thou that david doth honour thy father that he hath sent comforters unto thee are not his servants come unto thee for to search and to overthrow and to spy out the land thinkest heb in thine eyes doth david etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 4, 'Wherefore Hanun took David''s servants, and shaved them, and cut off their garments in the midst hard by their buttocks, and sent them away.', 'wherefore hanun took david s servants and shaved them and cut off their garments in the midst hard by their buttocks and sent them away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 5, 'Then there went {certain}, and told David how the men were served. And he sent to meet them: for the men were greatly ashamed. And the king said, Tarry at Jericho until your beards be grown, and {then} return.', 'then there went certain and told david how the men were served and he sent to meet them for the men were greatly ashamed and the king said tarry at jericho until your beards be grown and then return');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 6, 'And when the children of Ammon saw that they had made themselves odious to David, Hanun and the children of Ammon sent a thousand talents of silver to hire them chariots and horsemen out of Mesopotamia, and out of Syriamaachah, and out of Zobah. {odious: Heb. to stink}', 'and when the children of ammon saw that they had made themselves odious to david hanun and the children of ammon sent a thousand talents of silver to hire them chariots and horsemen out of mesopotamia and out of syriamaachah and out of zobah odious heb to stink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 7, 'So they hired thirty and two thousand chariots, and the king of Maachah and his people; who came and pitched before Medeba. And the children of Ammon gathered themselves together from their cities, and came to battle.', 'so they hired thirty and two thousand chariots and the king of maachah and his people who came and pitched before medeba and the children of ammon gathered themselves together from their cities and came to battle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 8, 'And when David heard {of it}, he sent Joab, and all the host of the mighty men.', 'and when david heard of it he sent joab and all the host of the mighty men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 9, 'And the children of Ammon came out, and put the battle in array before the gate of the city: and the kings that were come {were} by themselves in the field.', 'and the children of ammon came out and put the battle in array before the gate of the city and the kings that were come were by themselves in the field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 10, 'Now when Joab saw that the battle was set against him before and behind, he chose out of all the choice of Israel, and put {them} in array against the Syrians. {the battle...: Heb. the face of the battle was} {choice: or, young men}', 'now when joab saw that the battle was set against him before and behind he chose out of all the choice of israel and put them in array against the syrians the battle heb the face of the battle was choice or young men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 11, 'And the rest of the people he delivered unto the hand of Abishai his brother, and they set {themselves} in array against the children of Ammon. {Abishai: Heb. Abshai}', 'and the rest of the people he delivered unto the hand of abishai his brother and they set themselves in array against the children of ammon abishai heb abshai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 12, 'And he said, If the Syrians be too strong for me, then thou shalt help me: but if the children of Ammon be too strong for thee, then I will help thee.', 'and he said if the syrians be too strong for me then thou shalt help me but if the children of ammon be too strong for thee then i will help thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 13, 'Be of good courage, and let us behave ourselves valiantly for our people, and for the cities of our God: and let the LORD do {that which is} good in his sight.', 'be of good courage and let us behave ourselves valiantly for our people and for the cities of our god and let the lord do that which is good in his sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 14, 'So Joab and the people that {were} with him drew nigh before the Syrians unto the battle; and they fled before him.', 'so joab and the people that were with him drew nigh before the syrians unto the battle and they fled before him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 15, 'And when the children of Ammon saw that the Syrians were fled, they likewise fled before Abishai his brother, and entered into the city. Then Joab came to Jerusalem.', 'and when the children of ammon saw that the syrians were fled they likewise fled before abishai his brother and entered into the city then joab came to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 16, 'And when the Syrians saw that they were put to the worse before Israel, they sent messengers, and drew forth the Syrians that {were} beyond the river: and Shophach the captain of the host of Hadarezer {went} before them. {river: that is, Euphrates} {Shophach: also called, Shobach}', 'and when the syrians saw that they were put to the worse before israel they sent messengers and drew forth the syrians that were beyond the river and shophach the captain of the host of hadarezer went before them river that is euphrates shophach also called shobach');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 17, 'And it was told David; and he gathered all Israel, and passed over Jordan, and came upon them, and set {the battle} in array against them. So when David had put the battle in array against the Syrians, they fought with him.', 'and it was told david and he gathered all israel and passed over jordan and came upon them and set the battle in array against them so when david had put the battle in array against the syrians they fought with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 18, 'But the Syrians fled before Israel; and David slew of the Syrians seven thousand {men which fought in} chariots, and forty thousand footmen, and killed Shophach the captain of the host.', 'but the syrians fled before israel and david slew of the syrians seven thousand men which fought in chariots and forty thousand footmen and killed shophach the captain of the host');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 19, 19, 'And when the servants of Hadarezer saw that they were put to the worse before Israel, they made peace with David, and became his servants: neither would the Syrians help the children of Ammon any more.', 'and when the servants of hadarezer saw that they were put to the worse before israel they made peace with david and became his servants neither would the syrians help the children of ammon any more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 1, 'And it came to pass, that after the year was expired, at the time that kings go out {to battle}, Joab led forth the power of the army, and wasted the country of the children of Ammon, and came and besieged Rabbah. But David tarried at Jerusalem. And Joab smote Rabbah, and destroyed it. {after...: Heb. at the return of the year}', 'and it came to pass that after the year was expired at the time that kings go out to battle joab led forth the power of the army and wasted the country of the children of ammon and came and besieged rabbah but david tarried at jerusalem and joab smote rabbah and destroyed it after heb at the return of the year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 2, 'And David took the crown of their king from off his head, and found it to weigh a talent of gold, and {there were} precious stones in it; and it was set upon David''s head: and he brought also exceeding much spoil out of the city. {to weigh: Heb. the weight of}', 'and david took the crown of their king from off his head and found it to weigh a talent of gold and there were precious stones in it and it was set upon david s head and he brought also exceeding much spoil out of the city to weigh heb the weight of');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 3, 'And he brought out the people that {were} in it, and cut {them} with saws, and with harrows of iron, and with axes. Even so dealt David with all the cities of the children of Ammon. And David and all the people returned to Jerusalem.', 'and he brought out the people that were in it and cut them with saws and with harrows of iron and with axes even so dealt david with all the cities of the children of ammon and david and all the people returned to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 4, 'And it came to pass after this, that there arose war at Gezer with the Philistines; at which time Sibbechai the Hushathite slew Sippai, {that was} of the children of the giant: and they were subdued. {arose: or, continued: Heb. stood} {Gezer: also called, Gob} {Sippai: also called, Saph} {the giant: or, Rapha}', 'and it came to pass after this that there arose war at gezer with the philistines at which time sibbechai the hushathite slew sippai that was of the children of the giant and they were subdued arose or continued heb stood gezer also called gob sippai also called saph the giant or rapha');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 5, 'And there was war again with the Philistines; and Elhanan the son of Jair slew Lahmi the brother of Goliath the Gittite, whose spear staff {was} like a weaver''s beam. {Jair: also called, Jaareoregim}', 'and there was war again with the philistines and elhanan the son of jair slew lahmi the brother of goliath the gittite whose spear staff was like a weaver s beam jair also called jaareoregim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 6, 'And yet again there was war at Gath, where was a man of {great} stature, whose fingers and toes {were} four and twenty, six {on each hand}, and six {on each foot}: and he also was the son of the giant. {great...: Heb. measure} {the son...: Heb. born to the giant, or, Rapha}', 'and yet again there was war at gath where was a man of great stature whose fingers and toes were four and twenty six on each hand and six on each foot and he also was the son of the giant great heb measure the son heb born to the giant or rapha');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 7, 'But when he defied Israel, Jonathan the son of Shimea David''s brother slew him. {defied: or, reproached} {Shimea: also called Shammah}', 'but when he defied israel jonathan the son of shimea david s brother slew him defied or reproached shimea also called shammah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 20, 8, 'These were born unto the giant in Gath; and they fell by the hand of David, and by the hand of his servants.', 'these were born unto the giant in gath and they fell by the hand of david and by the hand of his servants');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 1, 'And Satan stood up against Israel, and provoked David to number Israel.', 'and satan stood up against israel and provoked david to number israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 2, 'And David said to Joab and to the rulers of the people, Go, number Israel from Beersheba even to Dan; and bring the number of them to me, that I may know {it}.', 'and david said to joab and to the rulers of the people go number israel from beersheba even to dan and bring the number of them to me that i may know it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 3, 'And Joab answered, The LORD make his people an hundred times so many more as they {be}: but, my lord the king, {are} they not all my lord''s servants? why then doth my lord require this thing? why will he be a cause of trespass to Israel?', 'and joab answered the lord make his people an hundred times so many more as they be but my lord the king are they not all my lord s servants why then doth my lord require this thing why will he be a cause of trespass to israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 4, 'Nevertheless the king''s word prevailed against Joab. Wherefore Joab departed, and went throughout all Israel, and came to Jerusalem.', 'nevertheless the king s word prevailed against joab wherefore joab departed and went throughout all israel and came to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 5, 'And Joab gave the sum of the number of the people unto David. And all {they of} Israel were a thousand thousand and an hundred thousand men that drew sword: and Judah {was} four hundred threescore and ten thousand men that drew sword.', 'and joab gave the sum of the number of the people unto david and all they of israel were a thousand thousand and an hundred thousand men that drew sword and judah was four hundred threescore and ten thousand men that drew sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 6, 'But Levi and Benjamin counted he not among them: for the king''s word was abominable to Joab.', 'but levi and benjamin counted he not among them for the king s word was abominable to joab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 7, 'And God was displeased with this thing; therefore he smote Israel. {And...: Heb. And it was evil in the eyes of the LORD concerning this thing}', 'and god was displeased with this thing therefore he smote israel and heb and it was evil in the eyes of the lord concerning this thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 8, 'And David said unto God, I have sinned greatly, because I have done this thing: but now, I beseech thee, do away the iniquity of thy servant; for I have done very foolishly.', 'and david said unto god i have sinned greatly because i have done this thing but now i beseech thee do away the iniquity of thy servant for i have done very foolishly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 9, 'And the LORD spake unto Gad, David''s seer, saying,', 'and the lord spake unto gad david s seer saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 10, 'Go and tell David, saying, Thus saith the LORD, I offer thee three {things}: choose thee one of them, that I may do {it} unto thee. {offer: Heb. stretch out}', 'go and tell david saying thus saith the lord i offer thee three things choose thee one of them that i may do it unto thee offer heb stretch out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 11, 'So Gad came to David, and said unto him, Thus saith the LORD, Choose thee {Choose...: Heb. Take to thee}', 'so gad came to david and said unto him thus saith the lord choose thee choose heb take to thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 12, 'Either three years'' famine; or three months to be destroyed before thy foes, while that the sword of thine enemies overtaketh {thee}; or else three days the sword of the LORD, even the pestilence, in the land, and the angel of the LORD destroying throughout all the coasts of Israel. Now therefore advise thyself what word I shall bring again to him that sent me.', 'either three years famine or three months to be destroyed before thy foes while that the sword of thine enemies overtaketh thee or else three days the sword of the lord even the pestilence in the land and the angel of the lord destroying throughout all the coasts of israel now therefore advise thyself what word i shall bring again to him that sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 13, 'And David said unto Gad, I am in a great strait: let me fall now into the hand of the LORD; for very great {are} his mercies: but let me not fall into the hand of man. {very great: or, very many}', 'and david said unto gad i am in a great strait let me fall now into the hand of the lord for very great are his mercies but let me not fall into the hand of man very great or very many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 14, 'So the LORD sent pestilence upon Israel: and there fell of Israel seventy thousand men.', 'so the lord sent pestilence upon israel and there fell of israel seventy thousand men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 15, 'And God sent an angel unto Jerusalem to destroy it: and as he was destroying, the LORD beheld, and he repented him of the evil, and said to the angel that destroyed, It is enough, stay now thine hand. And the angel of the LORD stood by the threshingfloor of Ornan the Jebusite. {Ornan: also called, Araunah}', 'and god sent an angel unto jerusalem to destroy it and as he was destroying the lord beheld and he repented him of the evil and said to the angel that destroyed it is enough stay now thine hand and the angel of the lord stood by the threshingfloor of ornan the jebusite ornan also called araunah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 16, 'And David lifted up his eyes, and saw the angel of the LORD stand between the earth and the heaven, having a drawn sword in his hand stretched out over Jerusalem. Then David and the elders {of Israel, who were} clothed in sackcloth, fell upon their faces.', 'and david lifted up his eyes and saw the angel of the lord stand between the earth and the heaven having a drawn sword in his hand stretched out over jerusalem then david and the elders of israel who were clothed in sackcloth fell upon their faces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 17, 'And David said unto God, {Is it} not I {that} commanded the people to be numbered? even I it is that have sinned and done evil indeed; but {as for} these sheep, what have they done? let thine hand, I pray thee, O LORD my God, be on me, and on my father''s house; but not on thy people, that they should be plagued.', 'and david said unto god is it not i that commanded the people to be numbered even i it is that have sinned and done evil indeed but as for these sheep what have they done let thine hand i pray thee o lord my god be on me and on my father s house but not on thy people that they should be plagued');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 18, 'Then the angel of the LORD commanded Gad to say to David, that David should go up, and set up an altar unto the LORD in the threshingfloor of Ornan the Jebusite.', 'then the angel of the lord commanded gad to say to david that david should go up and set up an altar unto the lord in the threshingfloor of ornan the jebusite');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 19, 'And David went up at the saying of Gad, which he spake in the name of the LORD.', 'and david went up at the saying of gad which he spake in the name of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 20, 'And Ornan turned back, and saw the angel; and his four sons with him hid themselves. Now Ornan was threshing wheat. {And Ornan...: or, When Ornan turned back and saw the angel, then he and his four sons with him hid themselves}', 'and ornan turned back and saw the angel and his four sons with him hid themselves now ornan was threshing wheat and ornan or when ornan turned back and saw the angel then he and his four sons with him hid themselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 21, 'And as David came to Ornan, Ornan looked and saw David, and went out of the threshingfloor, and bowed himself to David with {his} face to the ground.', 'and as david came to ornan ornan looked and saw david and went out of the threshingfloor and bowed himself to david with his face to the ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 22, 'Then David said to Ornan, Grant me the place of {this} threshingfloor, that I may build an altar therein unto the LORD: thou shalt grant it me for the full price: that the plague may be stayed from the people. {Grant: Heb. Give}', 'then david said to ornan grant me the place of this threshingfloor that i may build an altar therein unto the lord thou shalt grant it me for the full price that the plague may be stayed from the people grant heb give');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 23, 'And Ornan said unto David, Take {it} to thee, and let my lord the king do {that which is} good in his eyes: lo, I give {thee} the oxen {also} for burnt offerings, and the threshing instruments for wood, and the wheat for the meat offering; I give it all.', 'and ornan said unto david take it to thee and let my lord the king do that which is good in his eyes lo i give thee the oxen also for burnt offerings and the threshing instruments for wood and the wheat for the meat offering i give it all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 24, 'And king David said to Ornan, Nay; but I will verily buy it for the full price: for I will not take {that} which {is} thine for the LORD, nor offer burnt offerings without cost.', 'and king david said to ornan nay but i will verily buy it for the full price for i will not take that which is thine for the lord nor offer burnt offerings without cost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 25, 'So David gave to Ornan for the place six hundred shekels of gold by weight.', 'so david gave to ornan for the place six hundred shekels of gold by weight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 26, 'And David built there an altar unto the LORD, and offered burnt offerings and peace offerings, and called upon the LORD; and he answered him from heaven by fire upon the altar of burnt offering.', 'and david built there an altar unto the lord and offered burnt offerings and peace offerings and called upon the lord and he answered him from heaven by fire upon the altar of burnt offering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 27, 'And the LORD commanded the angel; and he put up his sword again into the sheath thereof.', 'and the lord commanded the angel and he put up his sword again into the sheath thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 28, 'At that time when David saw that the LORD had answered him in the threshingfloor of Ornan the Jebusite, then he sacrificed there.', 'at that time when david saw that the lord had answered him in the threshingfloor of ornan the jebusite then he sacrificed there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 29, 'For the tabernacle of the LORD, which Moses made in the wilderness, and the altar of the burnt offering, {were} at that season in the high place at Gibeon.', 'for the tabernacle of the lord which moses made in the wilderness and the altar of the burnt offering were at that season in the high place at gibeon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 21, 30, 'But David could not go before it to enquire of God: for he was afraid because of the sword of the angel of the LORD.', 'but david could not go before it to enquire of god for he was afraid because of the sword of the angel of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 1, 'Then David said, This {is} the house of the LORD God, and this {is} the altar of the burnt offering for Israel.', 'then david said this is the house of the lord god and this is the altar of the burnt offering for israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 2, 'And David commanded to gather together the strangers that {were} in the land of Israel; and he set masons to hew wrought stones to build the house of God.', 'and david commanded to gather together the strangers that were in the land of israel and he set masons to hew wrought stones to build the house of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 3, 'And David prepared iron in abundance for the nails for the doors of the gates, and for the joinings; and brass in abundance without weight;', 'and david prepared iron in abundance for the nails for the doors of the gates and for the joinings and brass in abundance without weight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 4, 'Also cedar trees in abundance: for the Zidonians and they of Tyre brought much cedar wood to David.', 'also cedar trees in abundance for the zidonians and they of tyre brought much cedar wood to david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 5, 'And David said, Solomon my son {is} young and tender, and the house {that is} to be builded for the LORD {must be} exceeding magnifical, of fame and of glory throughout all countries: I will {therefore} now make preparation for it. So David prepared abundantly before his death.', 'and david said solomon my son is young and tender and the house that is to be builded for the lord must be exceeding magnifical of fame and of glory throughout all countries i will therefore now make preparation for it so david prepared abundantly before his death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 6, 'Then he called for Solomon his son, and charged him to build an house for the LORD God of Israel.', 'then he called for solomon his son and charged him to build an house for the lord god of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 7, 'And David said to Solomon, My son, as for me, it was in my mind to build an house unto the name of the LORD my God:', 'and david said to solomon my son as for me it was in my mind to build an house unto the name of the lord my god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 8, 'But the word of the LORD came to me, saying, Thou hast shed blood abundantly, and hast made great wars: thou shalt not build an house unto my name, because thou hast shed much blood upon the earth in my sight.', 'but the word of the lord came to me saying thou hast shed blood abundantly and hast made great wars thou shalt not build an house unto my name because thou hast shed much blood upon the earth in my sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 9, 'Behold, a son shall be born to thee, who shall be a man of rest; and I will give him rest from all his enemies round about: for his name shall be Solomon, and I will give peace and quietness unto Israel in his days. {Solomon: that is, Peaceable}', 'behold a son shall be born to thee who shall be a man of rest and i will give him rest from all his enemies round about for his name shall be solomon and i will give peace and quietness unto israel in his days solomon that is peaceable');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 10, 'He shall build an house for my name; and he shall be my son, and I {will be} his father; and I will establish the throne of his kingdom over Israel for ever.', 'he shall build an house for my name and he shall be my son and i will be his father and i will establish the throne of his kingdom over israel for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 11, 'Now, my son, the LORD be with thee; and prosper thou, and build the house of the LORD thy God, as he hath said of thee.', 'now my son the lord be with thee and prosper thou and build the house of the lord thy god as he hath said of thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 12, 'Only the LORD give thee wisdom and understanding, and give thee charge concerning Israel, that thou mayest keep the law of the LORD thy God.', 'only the lord give thee wisdom and understanding and give thee charge concerning israel that thou mayest keep the law of the lord thy god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 13, 'Then shalt thou prosper, if thou takest heed to fulfil the statutes and judgments which the LORD charged Moses with concerning Israel: be strong, and of good courage; dread not, nor be dismayed.', 'then shalt thou prosper if thou takest heed to fulfil the statutes and judgments which the lord charged moses with concerning israel be strong and of good courage dread not nor be dismayed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 14, 'Now, behold, in my trouble I have prepared for the house of the LORD an hundred thousand talents of gold, and a thousand thousand talents of silver; and of brass and iron without weight; for it is in abundance: timber also and stone have I prepared; and thou mayest add thereto. {trouble: or, poverty}', 'now behold in my trouble i have prepared for the house of the lord an hundred thousand talents of gold and a thousand thousand talents of silver and of brass and iron without weight for it is in abundance timber also and stone have i prepared and thou mayest add thereto trouble or poverty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 15, 'Moreover {there are} workmen with thee in abundance, hewers and workers of stone and timber, and all manner of cunning men for every manner of work. {workers...: that is, masons and carpenters}', 'moreover there are workmen with thee in abundance hewers and workers of stone and timber and all manner of cunning men for every manner of work workers that is masons and carpenters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 16, 'Of the gold, the silver, and the brass, and the iron, {there is} no number. Arise {therefore}, and be doing, and the LORD be with thee.', 'of the gold the silver and the brass and the iron there is no number arise therefore and be doing and the lord be with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 17, 'David also commanded all the princes of Israel to help Solomon his son, {saying},', 'david also commanded all the princes of israel to help solomon his son saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 18, '{Is} not the LORD your God with you? and hath he {not} given you rest on every side? for he hath given the inhabitants of the land into mine hand; and the land is subdued before the LORD, and before his people.', 'is not the lord your god with you and hath he not given you rest on every side for he hath given the inhabitants of the land into mine hand and the land is subdued before the lord and before his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 22, 19, 'Now set your heart and your soul to seek the LORD your God; arise therefore, and build ye the sanctuary of the LORD God, to bring the ark of the covenant of the LORD, and the holy vessels of God, into the house that is to be built to the name of the LORD.', 'now set your heart and your soul to seek the lord your god arise therefore and build ye the sanctuary of the lord god to bring the ark of the covenant of the lord and the holy vessels of god into the house that is to be built to the name of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 23, 1, 'So when David was old and full of days, he made Solomon his son king over Israel.', 'so when david was old and full of days he made solomon his son king over israel');
