INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 23, 30, 'And to stand every morning to thank and praise the LORD, and likewise at even;', 'and to stand every morning to thank and praise the lord and likewise at even');
