INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 26, 26, 'Which Shelomith and his brethren {were} over all the treasures of the dedicated things, which David the king, and the chief fathers, the captains over thousands and hundreds, and the captains of the host, had dedicated.', 'which shelomith and his brethren were over all the treasures of the dedicated things which david the king and the chief fathers the captains over thousands and hundreds and the captains of the host had dedicated');
