INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 26, 28, 'And all that Samuel the seer, and Saul the son of Kish, and Abner the son of Ner, and Joab the son of Zeruiah, had dedicated; {and} whosoever had dedicated {any thing, it was} under the hand of Shelomith, and of his brethren.', 'and all that samuel the seer and saul the son of kish and abner the son of ner and joab the son of zeruiah had dedicated and whosoever had dedicated any thing it was under the hand of shelomith and of his brethren');
