INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 26, 31, 'Among the Hebronites {was} Jerijah the chief, {even} among the Hebronites, according to the generations of his fathers. In the fortieth year of the reign of David they were sought for, and there were found among them mighty men of valour at Jazer of Gilead.', 'among the hebronites was jerijah the chief even among the hebronites according to the generations of his fathers in the fortieth year of the reign of david they were sought for and there were found among them mighty men of valour at jazer of gilead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 26, 32, 'And his brethren, men of valour, {were} two thousand and seven hundred chief fathers, whom king David made rulers over the Reubenites, the Gadites, and the half tribe of Manasseh, for every matter pertaining to God, and affairs of the king. {affairs: Heb. thing}', 'and his brethren men of valour were two thousand and seven hundred chief fathers whom king david made rulers over the reubenites the gadites and the half tribe of manasseh for every matter pertaining to god and affairs of the king affairs heb thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 27, 1, 'Now the children of Israel after their number, {to wit}, the chief fathers and captains of thousands and hundreds, and their officers that served the king in any matter of the courses, which came in and went out month by month throughout all the months of the year, of every course {were} twenty and four thousand.', 'now the children of israel after their number to wit the chief fathers and captains of thousands and hundreds and their officers that served the king in any matter of the courses which came in and went out month by month throughout all the months of the year of every course were twenty and four thousand');
