INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 28, 2, 'Then David the king stood up upon his feet, and said, Hear me, my brethren, and my people: {As for me}, I {had} in mine heart to build an house of rest for the ark of the covenant of the LORD, and for the footstool of our God, and had made ready for the building:', 'then david the king stood up upon his feet and said hear me my brethren and my people as for me i had in mine heart to build an house of rest for the ark of the covenant of the lord and for the footstool of our god and had made ready for the building');
