INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 28, 4, 'Howbeit the LORD God of Israel chose me before all the house of my father to be king over Israel for ever: for he hath chosen Judah {to be} the ruler; and of the house of Judah, the house of my father; and among the sons of my father he liked me to make {me} king over all Israel:', 'howbeit the lord god of israel chose me before all the house of my father to be king over israel for ever for he hath chosen judah to be the ruler and of the house of judah the house of my father and among the sons of my father he liked me to make me king over all israel');
