INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 28, 8, 'Now therefore in the sight of all Israel the congregation of the LORD, and in the audience of our God, keep and seek for all the commandments of the LORD your God: that ye may possess this good land, and leave {it} for an inheritance for your children after you for ever.', 'now therefore in the sight of all israel the congregation of the lord and in the audience of our god keep and seek for all the commandments of the lord your god that ye may possess this good land and leave it for an inheritance for your children after you for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 28, 9, 'And thou, Solomon my son, know thou the God of thy father, and serve him with a perfect heart and with a willing mind: for the LORD searcheth all hearts, and understandeth all the imaginations of the thoughts: if thou seek him, he will be found of thee; but if thou forsake him, he will cast thee off for ever.', 'and thou solomon my son know thou the god of thy father and serve him with a perfect heart and with a willing mind for the lord searcheth all hearts and understandeth all the imaginations of the thoughts if thou seek him he will be found of thee but if thou forsake him he will cast thee off for ever');
