INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 28, 20, 'And David said to Solomon his son, Be strong and of good courage, and do {it}: fear not, nor be dismayed: for the LORD God, {even} my God, {will be} with thee; he will not fail thee, nor forsake thee, until thou hast finished all the work for the service of the house of the LORD.', 'and david said to solomon his son be strong and of good courage and do it fear not nor be dismayed for the lord god even my god will be with thee he will not fail thee nor forsake thee until thou hast finished all the work for the service of the house of the lord');
