INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 7, 'And gave for the service of the house of God of gold five thousand talents and ten thousand drams, and of silver ten thousand talents, and of brass eighteen thousand talents, and one hundred thousand talents of iron.', 'and gave for the service of the house of god of gold five thousand talents and ten thousand drams and of silver ten thousand talents and of brass eighteen thousand talents and one hundred thousand talents of iron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 8, 'And they with whom {precious} stones were found gave {them} to the treasure of the house of the LORD, by the hand of Jehiel the Gershonite.', 'and they with whom precious stones were found gave them to the treasure of the house of the lord by the hand of jehiel the gershonite');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 9, 'Then the people rejoiced, for that they offered willingly, because with perfect heart they offered willingly to the LORD: and David the king also rejoiced with great joy.', 'then the people rejoiced for that they offered willingly because with perfect heart they offered willingly to the lord and david the king also rejoiced with great joy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 10, 'Wherefore David blessed the LORD before all the congregation: and David said, Blessed {be} thou, LORD God of Israel our father, for ever and ever.', 'wherefore david blessed the lord before all the congregation and david said blessed be thou lord god of israel our father for ever and ever');
