INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 13, 'Now therefore, our God, we thank thee, and praise thy glorious name.', 'now therefore our god we thank thee and praise thy glorious name');
