INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 17, 'I know also, my God, that thou triest the heart, and hast pleasure in uprightness. As for me, in the uprightness of mine heart I have willingly offered all these things: and now have I seen with joy thy people, which are present here, to offer willingly unto thee. {present: Heb. found}', 'i know also my god that thou triest the heart and hast pleasure in uprightness as for me in the uprightness of mine heart i have willingly offered all these things and now have i seen with joy thy people which are present here to offer willingly unto thee present heb found');
