INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 13, 'Unknown', 29, 20, 'And David said to all the congregation, Now bless the LORD your God. And all the congregation blessed the LORD God of their fathers, and bowed down their heads, and worshipped the LORD, and the king.', 'and david said to all the congregation now bless the lord your god and all the congregation blessed the lord god of their fathers and bowed down their heads and worshipped the lord and the king');
