INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 1, 8, 'And Solomon said unto God, Thou hast shewed great mercy unto David my father, and hast made me to reign in his stead.', 'and solomon said unto god thou hast shewed great mercy unto david my father and hast made me to reign in his stead');
