INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 1, 11, 'And God said to Solomon, Because this was in thine heart, and thou hast not asked riches, wealth, or honour, nor the life of thine enemies, neither yet hast asked long life; but hast asked wisdom and knowledge for thyself, that thou mayest judge my people, over whom I have made thee king:', 'and god said to solomon because this was in thine heart and thou hast not asked riches wealth or honour nor the life of thine enemies neither yet hast asked long life but hast asked wisdom and knowledge for thyself that thou mayest judge my people over whom i have made thee king');
