INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 1, 13, 'Then Solomon came {from his journey} to the high place that {was} at Gibeon to Jerusalem, from before the tabernacle of the congregation, and reigned over Israel.', 'then solomon came from his journey to the high place that was at gibeon to jerusalem from before the tabernacle of the congregation and reigned over israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 1, 14, 'And Solomon gathered chariots and horsemen: and he had a thousand and four hundred chariots, and twelve thousand horsemen, which he placed in the chariot cities, and with the king at Jerusalem.', 'and solomon gathered chariots and horsemen and he had a thousand and four hundred chariots and twelve thousand horsemen which he placed in the chariot cities and with the king at jerusalem');
