INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 1, 16, 'And Solomon had horses brought out of Egypt, and linen yarn: the king''s merchants received the linen yarn at a price. {Solomon...: Heb. the going forth of the horses which was Solomon''s}', 'and solomon had horses brought out of egypt and linen yarn the king s merchants received the linen yarn at a price solomon heb the going forth of the horses which was solomon s');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 1, 17, 'And they fetched up, and brought forth out of Egypt a chariot for six hundred {shekels} of silver, and an horse for an hundred and fifty: and so brought they out {horses} for all the kings of the Hittites, and for the kings of Syria, by their means. {means: Heb. hand}', 'and they fetched up and brought forth out of egypt a chariot for six hundred shekels of silver and an horse for an hundred and fifty and so brought they out horses for all the kings of the hittites and for the kings of syria by their means means heb hand');
