INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 2, 7, 'Send me now therefore a man cunning to work in gold, and in silver, and in brass, and in iron, and in purple, and crimson, and blue, and that can skill to grave with the cunning men that {are} with me in Judah and in Jerusalem, whom David my father did provide. {to grave: Heb. to grave gravings}', 'send me now therefore a man cunning to work in gold and in silver and in brass and in iron and in purple and crimson and blue and that can skill to grave with the cunning men that are with me in judah and in jerusalem whom david my father did provide to grave heb to grave gravings');
