INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 2, 13, 'And now I have sent a cunning man, endued with understanding, of Huram my father''s,', 'and now i have sent a cunning man endued with understanding of huram my father s');
