INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 3, 9, 'And the weight of the nails {was} fifty shekels of gold. And he overlaid the upper chambers with gold.', 'and the weight of the nails was fifty shekels of gold and he overlaid the upper chambers with gold');
