INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 3, 11, 'And the wings of the cherubims {were} twenty cubits long: one wing {of the one cherub was} five cubits, reaching to the wall of the house: and the other wing {was likewise} five cubits, reaching to the wing of the other cherub.', 'and the wings of the cherubims were twenty cubits long one wing of the one cherub was five cubits reaching to the wall of the house and the other wing was likewise five cubits reaching to the wing of the other cherub');
