INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 3, 16, 'And he made chains, {as} in the oracle, and put {them} on the heads of the pillars; and made an hundred pomegranates, and put {them} on the chains.', 'and he made chains as in the oracle and put them on the heads of the pillars and made an hundred pomegranates and put them on the chains');
