INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 5, 9, 'And they drew out the staves {of the ark}, that the ends of the staves were seen from the ark before the oracle; but they were not seen without. And there it is unto this day. {there...: or, they are there}', 'and they drew out the staves of the ark that the ends of the staves were seen from the ark before the oracle but they were not seen without and there it is unto this day there or they are there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 5, 10, '{There was} nothing in the ark save the two tables which Moses put {therein} at Horeb, when the LORD made {a covenant} with the children of Israel, when they came out of Egypt. {when the LORD: or, where, etc}', 'there was nothing in the ark save the two tables which moses put therein at horeb when the lord made a covenant with the children of israel when they came out of egypt when the lord or where etc');
