INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 5, 12, 'Also the Levites {which were} the singers, all of them of Asaph, of Heman, of Jeduthun, with their sons and their brethren, {being} arrayed in white linen, having cymbals and psalteries and harps, stood at the east end of the altar, and with them an hundred and twenty priests sounding with trumpets:)', 'also the levites which were the singers all of them of asaph of heman of jeduthun with their sons and their brethren being arrayed in white linen having cymbals and psalteries and harps stood at the east end of the altar and with them an hundred and twenty priests sounding with trumpets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 5, 13, 'It came even to pass, as the trumpeters and singers {were} as one, to make one sound to be heard in praising and thanking the LORD; and when they lifted up {their} voice with the trumpets and cymbals and instruments of musick, and praised the LORD, {saying}, For {he is} good; for his mercy {endureth} for ever: that {then} the house was filled with a cloud, {even} the house of the LORD;', 'it came even to pass as the trumpeters and singers were as one to make one sound to be heard in praising and thanking the lord and when they lifted up their voice with the trumpets and cymbals and instruments of musick and praised the lord saying for he is good for his mercy endureth for ever that then the house was filled with a cloud even the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 5, 14, 'So that the priests could not stand to minister by reason of the cloud: for the glory of the LORD had filled the house of God.', 'so that the priests could not stand to minister by reason of the cloud for the glory of the lord had filled the house of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 6, 1, 'Then said Solomon, The LORD hath said that he would dwell in the thick darkness.', 'then said solomon the lord hath said that he would dwell in the thick darkness');
