INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 6, 4, 'And he said, Blessed {be} the LORD God of Israel, who hath with his hands fulfilled {that} which he spake with his mouth to my father David, saying,', 'and he said blessed be the lord god of israel who hath with his hands fulfilled that which he spake with his mouth to my father david saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 6, 5, 'Since the day that I brought forth my people out of the land of Egypt I chose no city among all the tribes of Israel to build an house in, that my name might be there; neither chose I any man to be a ruler over my people Israel:', 'since the day that i brought forth my people out of the land of egypt i chose no city among all the tribes of israel to build an house in that my name might be there neither chose i any man to be a ruler over my people israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 6, 6, 'But I have chosen Jerusalem, that my name might be there; and have chosen David to be over my people Israel.', 'but i have chosen jerusalem that my name might be there and have chosen david to be over my people israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 6, 7, 'Now it was in the heart of David my father to build an house for the name of the LORD God of Israel.', 'now it was in the heart of david my father to build an house for the name of the lord god of israel');
