INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 10, 'And on the three and twentieth day of the seventh month he sent the people away into their tents, glad and merry in heart for the goodness that the LORD had shewed unto David, and to Solomon, and to Israel his people.', 'and on the three and twentieth day of the seventh month he sent the people away into their tents glad and merry in heart for the goodness that the lord had shewed unto david and to solomon and to israel his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 11, 'Thus Solomon finished the house of the LORD, and the king''s house: and all that came into Solomon''s heart to make in the house of the LORD, and in his own house, he prosperously effected.', 'thus solomon finished the house of the lord and the king s house and all that came into solomon s heart to make in the house of the lord and in his own house he prosperously effected');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 12, 'And the LORD appeared to Solomon by night, and said unto him, I have heard thy prayer, and have chosen this place to myself for an house of sacrifice.', 'and the lord appeared to solomon by night and said unto him i have heard thy prayer and have chosen this place to myself for an house of sacrifice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 13, 'If I shut up heaven that there be no rain, or if I command the locusts to devour the land, or if I send pestilence among my people;', 'if i shut up heaven that there be no rain or if i command the locusts to devour the land or if i send pestilence among my people');
