INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 16, 'For now have I chosen and sanctified this house, that my name may be there for ever: and mine eyes and mine heart shall be there perpetually.', 'for now have i chosen and sanctified this house that my name may be there for ever and mine eyes and mine heart shall be there perpetually');
