INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 19, 'But if ye turn away, and forsake my statutes and my commandments, which I have set before you, and shall go and serve other gods, and worship them;', 'but if ye turn away and forsake my statutes and my commandments which i have set before you and shall go and serve other gods and worship them');
