INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 21, 'And this house, which is high, shall be an astonishment to every one that passeth by it; so that he shall say, Why hath the LORD done thus unto this land, and unto this house?', 'and this house which is high shall be an astonishment to every one that passeth by it so that he shall say why hath the lord done thus unto this land and unto this house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 7, 22, 'And it shall be answered, Because they forsook the LORD God of their fathers, which brought them forth out of the land of Egypt, and laid hold on other gods, and worshipped them, and served them: therefore hath he brought all this evil upon them.', 'and it shall be answered because they forsook the lord god of their fathers which brought them forth out of the land of egypt and laid hold on other gods and worshipped them and served them therefore hath he brought all this evil upon them');
