INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 8, 2, 'That the cities which Huram had restored to Solomon, Solomon built them, and caused the children of Israel to dwell there.', 'that the cities which huram had restored to solomon solomon built them and caused the children of israel to dwell there');
