INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 10, 'And Zorah, and Aijalon, and Hebron, which {are} in Judah and in Benjamin fenced cities.', 'and zorah and aijalon and hebron which are in judah and in benjamin fenced cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 11, 'And he fortified the strong holds, and put captains in them, and store of victual, and of oil and wine.', 'and he fortified the strong holds and put captains in them and store of victual and of oil and wine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 12, 'And in every several city {he put} shields and spears, and made them exceeding strong, having Judah and Benjamin on his side.', 'and in every several city he put shields and spears and made them exceeding strong having judah and benjamin on his side');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 13, 'And the priests and the Levites that {were} in all Israel resorted to him out of all their coasts. {resorted...: Heb. presented themselves to him}', 'and the priests and the levites that were in all israel resorted to him out of all their coasts resorted heb presented themselves to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 14, 'For the Levites left their suburbs and their possession, and came to Judah and Jerusalem: for Jeroboam and his sons had cast them off from executing the priest''s office unto the LORD:', 'for the levites left their suburbs and their possession and came to judah and jerusalem for jeroboam and his sons had cast them off from executing the priest s office unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 15, 'And he ordained him priests for the high places, and for the devils, and for the calves which he had made.', 'and he ordained him priests for the high places and for the devils and for the calves which he had made');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 16, 'And after them out of all the tribes of Israel such as set their hearts to seek the LORD God of Israel came to Jerusalem, to sacrifice unto the LORD God of their fathers.', 'and after them out of all the tribes of israel such as set their hearts to seek the lord god of israel came to jerusalem to sacrifice unto the lord god of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 17, 'So they strengthened the kingdom of Judah, and made Rehoboam the son of Solomon strong, three years: for three years they walked in the way of David and Solomon.', 'so they strengthened the kingdom of judah and made rehoboam the son of solomon strong three years for three years they walked in the way of david and solomon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 18, 'And Rehoboam took him Mahalath the daughter of Jerimoth the son of David to wife, {and} Abihail the daughter of Eliab the son of Jesse;', 'and rehoboam took him mahalath the daughter of jerimoth the son of david to wife and abihail the daughter of eliab the son of jesse');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 19, 'Which bare him children; Jeush, and Shamariah, and Zaham.', 'which bare him children jeush and shamariah and zaham');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 20, 'And after her he took Maachah the daughter of Absalom; which bare him Abijah, and Attai, and Ziza, and Shelomith. {Maachah: she is also called Michaiah the daughter of Uriel}', 'and after her he took maachah the daughter of absalom which bare him abijah and attai and ziza and shelomith maachah she is also called michaiah the daughter of uriel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 21, 'And Rehoboam loved Maachah the daughter of Absalom above all his wives and his concubines: (for he took eighteen wives, and threescore concubines; and begat twenty and eight sons, and threescore daughters.)', 'and rehoboam loved maachah the daughter of absalom above all his wives and his concubines for he took eighteen wives and threescore concubines and begat twenty and eight sons and threescore daughters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 22, 'And Rehoboam made Abijah the son of Maachah the chief, {to be} ruler among his brethren: for {he thought} to make him king.', 'and rehoboam made abijah the son of maachah the chief to be ruler among his brethren for he thought to make him king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 11, 23, 'And he dealt wisely, and dispersed of all his children throughout all the countries of Judah and Benjamin, unto every fenced city: and he gave them victual in abundance. And he desired many wives. {many wives: Heb. a multitude of wives}', 'and he dealt wisely and dispersed of all his children throughout all the countries of judah and benjamin unto every fenced city and he gave them victual in abundance and he desired many wives many wives heb a multitude of wives');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 1, 'And it came to pass, when Rehoboam had established the kingdom, and had strengthened himself, he forsook the law of the LORD, and all Israel with him.', 'and it came to pass when rehoboam had established the kingdom and had strengthened himself he forsook the law of the lord and all israel with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 2, 'And it came to pass, {that} in the fifth year of king Rehoboam Shishak king of Egypt came up against Jerusalem, because they had transgressed against the LORD,', 'and it came to pass that in the fifth year of king rehoboam shishak king of egypt came up against jerusalem because they had transgressed against the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 3, 'With twelve hundred chariots, and threescore thousand horsemen: and the people {were} without number that came with him out of Egypt; the Lubims, the Sukkiims, and the Ethiopians.', 'with twelve hundred chariots and threescore thousand horsemen and the people were without number that came with him out of egypt the lubims the sukkiims and the ethiopians');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 4, 'And he took the fenced cities which {pertained} to Judah, and came to Jerusalem.', 'and he took the fenced cities which pertained to judah and came to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 5, 'Then came Shemaiah the prophet to Rehoboam, and {to} the princes of Judah, that were gathered together to Jerusalem because of Shishak, and said unto them, Thus saith the LORD, Ye have forsaken me, and therefore have I also left you in the hand of Shishak.', 'then came shemaiah the prophet to rehoboam and to the princes of judah that were gathered together to jerusalem because of shishak and said unto them thus saith the lord ye have forsaken me and therefore have i also left you in the hand of shishak');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 6, 'Whereupon the princes of Israel and the king humbled themselves; and they said, The LORD {is} righteous.', 'whereupon the princes of israel and the king humbled themselves and they said the lord is righteous');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 7, 'And when the LORD saw that they humbled themselves, the word of the LORD came to Shemaiah, saying, They have humbled themselves; {therefore} I will not destroy them, but I will grant them some deliverance; and my wrath shall not be poured out upon Jerusalem by the hand of Shishak. {some: or, a little while}', 'and when the lord saw that they humbled themselves the word of the lord came to shemaiah saying they have humbled themselves therefore i will not destroy them but i will grant them some deliverance and my wrath shall not be poured out upon jerusalem by the hand of shishak some or a little while');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 8, 'Nevertheless they shall be his servants; that they may know my service, and the service of the kingdoms of the countries.', 'nevertheless they shall be his servants that they may know my service and the service of the kingdoms of the countries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 9, 'So Shishak king of Egypt came up against Jerusalem, and took away the treasures of the house of the LORD, and the treasures of the king''s house; he took all: he carried away also the shields of gold which Solomon had made.', 'so shishak king of egypt came up against jerusalem and took away the treasures of the house of the lord and the treasures of the king s house he took all he carried away also the shields of gold which solomon had made');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 10, 'Instead of which king Rehoboam made shields of brass, and committed {them} to the hands of the chief of the guard, that kept the entrance of the king''s house.', 'instead of which king rehoboam made shields of brass and committed them to the hands of the chief of the guard that kept the entrance of the king s house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 11, 'And when the king entered into the house of the LORD, the guard came and fetched them, and brought them again into the guard chamber.', 'and when the king entered into the house of the lord the guard came and fetched them and brought them again into the guard chamber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 12, 'And when he humbled himself, the wrath of the LORD turned from him, that he would not destroy {him} altogether: and also in Judah things went well. {and also...: or, and yet in Judah there were good things}', 'and when he humbled himself the wrath of the lord turned from him that he would not destroy him altogether and also in judah things went well and also or and yet in judah there were good things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 13, 'So king Rehoboam strengthened himself in Jerusalem, and reigned: for Rehoboam {was} one and forty years old when he began to reign, and he reigned seventeen years in Jerusalem, the city which the LORD had chosen out of all the tribes of Israel, to put his name there. And his mother''s name {was} Naamah an Ammonitess.', 'so king rehoboam strengthened himself in jerusalem and reigned for rehoboam was one and forty years old when he began to reign and he reigned seventeen years in jerusalem the city which the lord had chosen out of all the tribes of israel to put his name there and his mother s name was naamah an ammonitess');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 14, 'And he did evil, because he prepared not his heart to seek the LORD. {prepared: or, fixed}', 'and he did evil because he prepared not his heart to seek the lord prepared or fixed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 15, 'Now the acts of Rehoboam, first and last, {are} they not written in the book of Shemaiah the prophet, and of Iddo the seer concerning genealogies? And {there were} wars between Rehoboam and Jeroboam continually. {book: Heb. words}', 'now the acts of rehoboam first and last are they not written in the book of shemaiah the prophet and of iddo the seer concerning genealogies and there were wars between rehoboam and jeroboam continually book heb words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 12, 16, 'And Rehoboam slept with his fathers, and was buried in the city of David: and Abijah his son reigned in his stead. {Abijah: also called, Abijam}', 'and rehoboam slept with his fathers and was buried in the city of david and abijah his son reigned in his stead abijah also called abijam');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 1, 'Now in the eighteenth year of king Jeroboam began Abijah to reign over Judah.', 'now in the eighteenth year of king jeroboam began abijah to reign over judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 2, 'He reigned three years in Jerusalem. His mother''s name also {was} Michaiah the daughter of Uriel of Gibeah. And there was war between Abijah and Jeroboam.', 'he reigned three years in jerusalem his mother s name also was michaiah the daughter of uriel of gibeah and there was war between abijah and jeroboam');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 3, 'And Abijah set the battle in array with an army of valiant men of war, {even} four hundred thousand chosen men: Jeroboam also set the battle in array against him with eight hundred thousand chosen men, {being} mighty men of valour. {Abijah set: Heb. Abijah bound together}', 'and abijah set the battle in array with an army of valiant men of war even four hundred thousand chosen men jeroboam also set the battle in array against him with eight hundred thousand chosen men being mighty men of valour abijah set heb abijah bound together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 4, 'And Abijah stood up upon mount Zemaraim, which {is} in mount Ephraim, and said, Hear me, thou Jeroboam, and all Israel;', 'and abijah stood up upon mount zemaraim which is in mount ephraim and said hear me thou jeroboam and all israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 5, 'Ought ye not to know that the LORD God of Israel gave the kingdom over Israel to David for ever, {even} to him and to his sons by a covenant of salt?', 'ought ye not to know that the lord god of israel gave the kingdom over israel to david for ever even to him and to his sons by a covenant of salt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 6, 'Yet Jeroboam the son of Nebat, the servant of Solomon the son of David, is risen up, and hath rebelled against his lord.', 'yet jeroboam the son of nebat the servant of solomon the son of david is risen up and hath rebelled against his lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 7, 'And there are gathered unto him vain men, the children of Belial, and have strengthened themselves against Rehoboam the son of Solomon, when Rehoboam was young and tenderhearted, and could not withstand them.', 'and there are gathered unto him vain men the children of belial and have strengthened themselves against rehoboam the son of solomon when rehoboam was young and tenderhearted and could not withstand them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 8, 'And now ye think to withstand the kingdom of the LORD in the hand of the sons of David; and ye {be} a great multitude, and {there are} with you golden calves, which Jeroboam made you for gods.', 'and now ye think to withstand the kingdom of the lord in the hand of the sons of david and ye be a great multitude and there are with you golden calves which jeroboam made you for gods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 9, 'Have ye not cast out the priests of the LORD, the sons of Aaron, and the Levites, and have made you priests after the manner of the nations of {other} lands? so that whosoever cometh to consecrate himself with a young bullock and seven rams, {the same} may be a priest of {them that are} no gods. {to consecrate...: Heb. to fill his hand}', 'have ye not cast out the priests of the lord the sons of aaron and the levites and have made you priests after the manner of the nations of other lands so that whosoever cometh to consecrate himself with a young bullock and seven rams the same may be a priest of them that are no gods to consecrate heb to fill his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 10, 'But as for us, the LORD {is} our God, and we have not forsaken him; and the priests, which minister unto the LORD, {are} the sons of Aaron, and the Levites {wait} upon {their} business:', 'but as for us the lord is our god and we have not forsaken him and the priests which minister unto the lord are the sons of aaron and the levites wait upon their business');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 11, 'And they burn unto the LORD every morning and every evening burnt sacrifices and sweet incense: the shewbread also {set they in order} upon the pure table; and the candlestick of gold with the lamps thereof, to burn every evening: for we keep the charge of the LORD our God; but ye have forsaken him.', 'and they burn unto the lord every morning and every evening burnt sacrifices and sweet incense the shewbread also set they in order upon the pure table and the candlestick of gold with the lamps thereof to burn every evening for we keep the charge of the lord our god but ye have forsaken him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 12, 'And, behold, God himself {is} with us for {our} captain, and his priests with sounding trumpets to cry alarm against you. O children of Israel, fight ye not against the LORD God of your fathers; for ye shall not prosper.', 'and behold god himself is with us for our captain and his priests with sounding trumpets to cry alarm against you o children of israel fight ye not against the lord god of your fathers for ye shall not prosper');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 13, 'But Jeroboam caused an ambushment to come about behind them: so they were before Judah, and the ambushment {was} behind them.', 'but jeroboam caused an ambushment to come about behind them so they were before judah and the ambushment was behind them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 14, 'And when Judah looked back, behold, the battle {was} before and behind: and they cried unto the LORD, and the priests sounded with the trumpets.', 'and when judah looked back behold the battle was before and behind and they cried unto the lord and the priests sounded with the trumpets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 15, 'Then the men of Judah gave a shout: and as the men of Judah shouted, it came to pass, that God smote Jeroboam and all Israel before Abijah and Judah.', 'then the men of judah gave a shout and as the men of judah shouted it came to pass that god smote jeroboam and all israel before abijah and judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 16, 'And the children of Israel fled before Judah: and God delivered them into their hand.', 'and the children of israel fled before judah and god delivered them into their hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 17, 'And Abijah and his people slew them with a great slaughter: so there fell down slain of Israel five hundred thousand chosen men.', 'and abijah and his people slew them with a great slaughter so there fell down slain of israel five hundred thousand chosen men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 18, 'Thus the children of Israel were brought under at that time, and the children of Judah prevailed, because they relied upon the LORD God of their fathers.', 'thus the children of israel were brought under at that time and the children of judah prevailed because they relied upon the lord god of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 19, 'And Abijah pursued after Jeroboam, and took cities from him, Bethel with the towns thereof, and Jeshanah with the towns thereof, and Ephrain with the towns thereof.', 'and abijah pursued after jeroboam and took cities from him bethel with the towns thereof and jeshanah with the towns thereof and ephrain with the towns thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 20, 'Neither did Jeroboam recover strength again in the days of Abijah: and the LORD struck him, and he died.', 'neither did jeroboam recover strength again in the days of abijah and the lord struck him and he died');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 21, 'But Abijah waxed mighty, and married fourteen wives, and begat twenty and two sons, and sixteen daughters.', 'but abijah waxed mighty and married fourteen wives and begat twenty and two sons and sixteen daughters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 13, 22, 'And the rest of the acts of Abijah, and his ways, and his sayings, {are} written in the story of the prophet Iddo.', 'and the rest of the acts of abijah and his ways and his sayings are written in the story of the prophet iddo');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 1, 'So Abijah slept with his fathers, and they buried him in the city of David: and Asa his son reigned in his stead. In his days the land was quiet ten years.', 'so abijah slept with his fathers and they buried him in the city of david and asa his son reigned in his stead in his days the land was quiet ten years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 2, 'And Asa did {that which was} good and right in the eyes of the LORD his God:', 'and asa did that which was good and right in the eyes of the lord his god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 3, 'For he took away the altars of the strange {gods}, and the high places, and brake down the images, and cut down the groves: {images: Heb. statues}', 'for he took away the altars of the strange gods and the high places and brake down the images and cut down the groves images heb statues');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 4, 'And commanded Judah to seek the LORD God of their fathers, and to do the law and the commandment.', 'and commanded judah to seek the lord god of their fathers and to do the law and the commandment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 5, 'Also he took away out of all the cities of Judah the high places and the images: and the kingdom was quiet before him. {images: Heb. sun images}', 'also he took away out of all the cities of judah the high places and the images and the kingdom was quiet before him images heb sun images');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 6, 'And he built fenced cities in Judah: for the land had rest, and he had no war in those years; because the LORD had given him rest.', 'and he built fenced cities in judah for the land had rest and he had no war in those years because the lord had given him rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 7, 'Therefore he said unto Judah, Let us build these cities, and make about {them} walls, and towers, gates, and bars, {while} the land {is} yet before us; because we have sought the LORD our God, we have sought {him}, and he hath given us rest on every side. So they built and prospered.', 'therefore he said unto judah let us build these cities and make about them walls and towers gates and bars while the land is yet before us because we have sought the lord our god we have sought him and he hath given us rest on every side so they built and prospered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 8, 'And Asa had an army {of men} that bare targets and spears, out of Judah three hundred thousand; and out of Benjamin, that bare shields and drew bows, two hundred and fourscore thousand: all these {were} mighty men of valour.', 'and asa had an army of men that bare targets and spears out of judah three hundred thousand and out of benjamin that bare shields and drew bows two hundred and fourscore thousand all these were mighty men of valour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 9, 'And there came out against them Zerah the Ethiopian with an host of a thousand thousand, and three hundred chariots; and came unto Mareshah.', 'and there came out against them zerah the ethiopian with an host of a thousand thousand and three hundred chariots and came unto mareshah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 10, 'Then Asa went out against him, and they set the battle in array in the valley of Zephathah at Mareshah.', 'then asa went out against him and they set the battle in array in the valley of zephathah at mareshah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 11, 'And Asa cried unto the LORD his God, and said, LORD, {it is} nothing with thee to help, whether with many, or with them that have no power: help us, O LORD our God; for we rest on thee, and in thy name we go against this multitude. O LORD, thou {art} our God; let not man prevail against thee. {man: or, mortal man}', 'and asa cried unto the lord his god and said lord it is nothing with thee to help whether with many or with them that have no power help us o lord our god for we rest on thee and in thy name we go against this multitude o lord thou art our god let not man prevail against thee man or mortal man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 12, 'So the LORD smote the Ethiopians before Asa, and before Judah; and the Ethiopians fled.', 'so the lord smote the ethiopians before asa and before judah and the ethiopians fled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 13, 'And Asa and the people that {were} with him pursued them unto Gerar: and the Ethiopians were overthrown, that they could not recover themselves; for they were destroyed before the LORD, and before his host; and they carried away very much spoil. {destroyed: Heb. broken}', 'and asa and the people that were with him pursued them unto gerar and the ethiopians were overthrown that they could not recover themselves for they were destroyed before the lord and before his host and they carried away very much spoil destroyed heb broken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 14, 'And they smote all the cities round about Gerar; for the fear of the LORD came upon them: and they spoiled all the cities; for there was exceeding much spoil in them.', 'and they smote all the cities round about gerar for the fear of the lord came upon them and they spoiled all the cities for there was exceeding much spoil in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 14, 15, 'They smote also the tents of cattle, and carried away sheep and camels in abundance, and returned to Jerusalem.', 'they smote also the tents of cattle and carried away sheep and camels in abundance and returned to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 1, 'And the Spirit of God came upon Azariah the son of Oded:', 'and the spirit of god came upon azariah the son of oded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 2, 'And he went out to meet Asa, and said unto him, Hear ye me, Asa, and all Judah and Benjamin; The LORD {is} with you, while ye be with him; and if ye seek him, he will be found of you; but if ye forsake him, he will forsake you. {to meet...: Heb. before Asa}', 'and he went out to meet asa and said unto him hear ye me asa and all judah and benjamin the lord is with you while ye be with him and if ye seek him he will be found of you but if ye forsake him he will forsake you to meet heb before asa');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 3, 'Now for a long season Israel {hath been} without the true God, and without a teaching priest, and without law.', 'now for a long season israel hath been without the true god and without a teaching priest and without law');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 4, 'But when they in their trouble did turn unto the LORD God of Israel, and sought him, he was found of them.', 'but when they in their trouble did turn unto the lord god of israel and sought him he was found of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 5, 'And in those times {there was} no peace to him that went out, nor to him that came in, but great vexations {were} upon all the inhabitants of the countries.', 'and in those times there was no peace to him that went out nor to him that came in but great vexations were upon all the inhabitants of the countries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 6, 'And nation was destroyed of nation, and city of city: for God did vex them with all adversity. {destroyed: Heb. beaten in pieces}', 'and nation was destroyed of nation and city of city for god did vex them with all adversity destroyed heb beaten in pieces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 7, 'Be ye strong therefore, and let not your hands be weak: for your work shall be rewarded.', 'be ye strong therefore and let not your hands be weak for your work shall be rewarded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 8, 'And when Asa heard these words, and the prophecy of Oded the prophet, he took courage, and put away the abominable idols out of all the land of Judah and Benjamin, and out of the cities which he had taken from mount Ephraim, and renewed the altar of the LORD, that {was} before the porch of the LORD. {abominable...: Heb. abominations}', 'and when asa heard these words and the prophecy of oded the prophet he took courage and put away the abominable idols out of all the land of judah and benjamin and out of the cities which he had taken from mount ephraim and renewed the altar of the lord that was before the porch of the lord abominable heb abominations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 9, 'And he gathered all Judah and Benjamin, and the strangers with them out of Ephraim and Manasseh, and out of Simeon: for they fell to him out of Israel in abundance, when they saw that the LORD his God {was} with him.', 'and he gathered all judah and benjamin and the strangers with them out of ephraim and manasseh and out of simeon for they fell to him out of israel in abundance when they saw that the lord his god was with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 10, 'So they gathered themselves together at Jerusalem in the third month, in the fifteenth year of the reign of Asa.', 'so they gathered themselves together at jerusalem in the third month in the fifteenth year of the reign of asa');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 11, 'And they offered unto the LORD the same time, of the spoil {which} they had brought, seven hundred oxen and seven thousand sheep. {the same...: Heb. in that day}', 'and they offered unto the lord the same time of the spoil which they had brought seven hundred oxen and seven thousand sheep the same heb in that day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 12, 'And they entered into a covenant to seek the LORD God of their fathers with all their heart and with all their soul;', 'and they entered into a covenant to seek the lord god of their fathers with all their heart and with all their soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 13, 'That whosoever would not seek the LORD God of Israel should be put to death, whether small or great, whether man or woman.', 'that whosoever would not seek the lord god of israel should be put to death whether small or great whether man or woman');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 14, 'And they sware unto the LORD with a loud voice, and with shouting, and with trumpets, and with cornets.', 'and they sware unto the lord with a loud voice and with shouting and with trumpets and with cornets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 15, 'And all Judah rejoiced at the oath: for they had sworn with all their heart, and sought him with their whole desire; and he was found of them: and the LORD gave them rest round about.', 'and all judah rejoiced at the oath for they had sworn with all their heart and sought him with their whole desire and he was found of them and the lord gave them rest round about');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 16, 'And also {concerning} Maachah the mother of Asa the king, he removed her from {being} queen, because she had made an idol in a grove: and Asa cut down her idol, and stamped {it}, and burnt {it} at the brook Kidron. {mother: that is, grandmother} {idol: Heb. horror}', 'and also concerning maachah the mother of asa the king he removed her from being queen because she had made an idol in a grove and asa cut down her idol and stamped it and burnt it at the brook kidron mother that is grandmother idol heb horror');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 17, 'But the high places were not taken away out of Israel: nevertheless the heart of Asa was perfect all his days.', 'but the high places were not taken away out of israel nevertheless the heart of asa was perfect all his days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 18, 'And he brought into the house of God the things that his father had dedicated, and that he himself had dedicated, silver, and gold, and vessels.', 'and he brought into the house of god the things that his father had dedicated and that he himself had dedicated silver and gold and vessels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 15, 19, 'And there was no {more} war unto the five and thirtieth year of the reign of Asa.', 'and there was no more war unto the five and thirtieth year of the reign of asa');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 1, 'In the six and thirtieth year of the reign of Asa Baasha king of Israel came up against Judah, and built Ramah, to the intent that he might let none go out or come in to Asa king of Judah.', 'in the six and thirtieth year of the reign of asa baasha king of israel came up against judah and built ramah to the intent that he might let none go out or come in to asa king of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 2, 'Then Asa brought out silver and gold out of the treasures of the house of the LORD and of the king''s house, and sent to Benhadad king of Syria, that dwelt at Damascus, saying, {Damascus: Heb. Darmesek}', 'then asa brought out silver and gold out of the treasures of the house of the lord and of the king s house and sent to benhadad king of syria that dwelt at damascus saying damascus heb darmesek');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 3, '{There is} a league between me and thee, as {there was} between my father and thy father: behold, I have sent thee silver and gold; go, break thy league with Baasha king of Israel, that he may depart from me.', 'there is a league between me and thee as there was between my father and thy father behold i have sent thee silver and gold go break thy league with baasha king of israel that he may depart from me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 4, 'And Benhadad hearkened unto king Asa, and sent the captains of his armies against the cities of Israel; and they smote Ijon, and Dan, and Abelmaim, and all the store cities of Naphtali. {his: Heb. which were his}', 'and benhadad hearkened unto king asa and sent the captains of his armies against the cities of israel and they smote ijon and dan and abelmaim and all the store cities of naphtali his heb which were his');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 5, 'And it came to pass, when Baasha heard {it}, that he left off building of Ramah, and let his work cease.', 'and it came to pass when baasha heard it that he left off building of ramah and let his work cease');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 6, 'Then Asa the king took all Judah; and they carried away the stones of Ramah, and the timber thereof, wherewith Baasha was building; and he built therewith Geba and Mizpah.', 'then asa the king took all judah and they carried away the stones of ramah and the timber thereof wherewith baasha was building and he built therewith geba and mizpah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 7, 'And at that time Hanani the seer came to Asa king of Judah, and said unto him, Because thou hast relied on the king of Syria, and not relied on the LORD thy God, therefore is the host of the king of Syria escaped out of thine hand.', 'and at that time hanani the seer came to asa king of judah and said unto him because thou hast relied on the king of syria and not relied on the lord thy god therefore is the host of the king of syria escaped out of thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 8, 'Were not the Ethiopians and the Lubims a huge host, with very many chariots and horsemen? yet, because thou didst rely on the LORD, he delivered them into thine hand. {a huge: Heb. in abundance}', 'were not the ethiopians and the lubims a huge host with very many chariots and horsemen yet because thou didst rely on the lord he delivered them into thine hand a huge heb in abundance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 9, 'For the eyes of the LORD run to and fro throughout the whole earth, to shew himself strong in the behalf of {them} whose heart {is} perfect toward him. Herein thou hast done foolishly: therefore from henceforth thou shalt have wars. {to shew...: or, strongly to hold with them, etc}', 'for the eyes of the lord run to and fro throughout the whole earth to shew himself strong in the behalf of them whose heart is perfect toward him herein thou hast done foolishly therefore from henceforth thou shalt have wars to shew or strongly to hold with them etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 10, 'Then Asa was wroth with the seer, and put him in a prison house; for {he was} in a rage with him because of this {thing}. And Asa oppressed {some} of the people the same time. {oppressed: Heb. crushed}', 'then asa was wroth with the seer and put him in a prison house for he was in a rage with him because of this thing and asa oppressed some of the people the same time oppressed heb crushed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 11, 'And, behold, the acts of Asa, first and last, lo, they {are} written in the book of the kings of Judah and Israel.', 'and behold the acts of asa first and last lo they are written in the book of the kings of judah and israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 12, 'And Asa in the thirty and ninth year of his reign was diseased in his feet, until his disease {was} exceeding {great}: yet in his disease he sought not to the LORD, but to the physicians.', 'and asa in the thirty and ninth year of his reign was diseased in his feet until his disease was exceeding great yet in his disease he sought not to the lord but to the physicians');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 13, 'And Asa slept with his fathers, and died in the one and fortieth year of his reign.', 'and asa slept with his fathers and died in the one and fortieth year of his reign');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 16, 14, 'And they buried him in his own sepulchres, which he had made for himself in the city of David, and laid him in the bed which was filled with sweet odours and divers kinds {of spices} prepared by the apothecaries'' art: and they made a very great burning for him. {had made: Heb. had digged}', 'and they buried him in his own sepulchres which he had made for himself in the city of david and laid him in the bed which was filled with sweet odours and divers kinds of spices prepared by the apothecaries art and they made a very great burning for him had made heb had digged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 1, 'And Jehoshaphat his son reigned in his stead, and strengthened himself against Israel.', 'and jehoshaphat his son reigned in his stead and strengthened himself against israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 2, 'And he placed forces in all the fenced cities of Judah, and set garrisons in the land of Judah, and in the cities of Ephraim, which Asa his father had taken.', 'and he placed forces in all the fenced cities of judah and set garrisons in the land of judah and in the cities of ephraim which asa his father had taken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 3, 'And the LORD was with Jehoshaphat, because he walked in the first ways of his father David, and sought not unto Baalim; {of...: or, of his father, and of David}', 'and the lord was with jehoshaphat because he walked in the first ways of his father david and sought not unto baalim of or of his father and of david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 4, 'But sought to the {LORD} God of his father, and walked in his commandments, and not after the doings of Israel.', 'but sought to the lord god of his father and walked in his commandments and not after the doings of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 5, 'Therefore the LORD stablished the kingdom in his hand; and all Judah brought to Jehoshaphat presents; and he had riches and honour in abundance. {brought: Heb. gave}', 'therefore the lord stablished the kingdom in his hand and all judah brought to jehoshaphat presents and he had riches and honour in abundance brought heb gave');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 6, 'And his heart was lifted up in the ways of the LORD: moreover he took away the high places and groves out of Judah. {was...: that is, was encouraged}', 'and his heart was lifted up in the ways of the lord moreover he took away the high places and groves out of judah was that is was encouraged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 7, 'Also in the third year of his reign he sent to his princes, {even} to Benhail, and to Obadiah, and to Zechariah, and to Nethaneel, and to Michaiah, to teach in the cities of Judah.', 'also in the third year of his reign he sent to his princes even to benhail and to obadiah and to zechariah and to nethaneel and to michaiah to teach in the cities of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 8, 'And with them {he sent} Levites, {even} Shemaiah, and Nethaniah, and Zebadiah, and Asahel, and Shemiramoth, and Jehonathan, and Adonijah, and Tobijah, and Tobadonijah, Levites; and with them Elishama and Jehoram, priests.', 'and with them he sent levites even shemaiah and nethaniah and zebadiah and asahel and shemiramoth and jehonathan and adonijah and tobijah and tobadonijah levites and with them elishama and jehoram priests');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 9, 'And they taught in Judah, and {had} the book of the law of the LORD with them, and went about throughout all the cities of Judah, and taught the people.', 'and they taught in judah and had the book of the law of the lord with them and went about throughout all the cities of judah and taught the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 10, 'And the fear of the LORD fell upon all the kingdoms of the lands that {were} round about Judah, so that they made no war against Jehoshaphat. {fell: Heb. was}', 'and the fear of the lord fell upon all the kingdoms of the lands that were round about judah so that they made no war against jehoshaphat fell heb was');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 11, 'Also {some} of the Philistines brought Jehoshaphat presents, and tribute silver; and the Arabians brought him flocks, seven thousand and seven hundred rams, and seven thousand and seven hundred he goats.', 'also some of the philistines brought jehoshaphat presents and tribute silver and the arabians brought him flocks seven thousand and seven hundred rams and seven thousand and seven hundred he goats');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 12, 'And Jehoshaphat waxed great exceedingly; and he built in Judah castles, and cities of store. {castles: or, palaces}', 'and jehoshaphat waxed great exceedingly and he built in judah castles and cities of store castles or palaces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 13, 'And he had much business in the cities of Judah: and the men of war, mighty men of valour, {were} in Jerusalem.', 'and he had much business in the cities of judah and the men of war mighty men of valour were in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 14, 'And these {are} the numbers of them according to the house of their fathers: Of Judah, the captains of thousands; Adnah the chief, and with him mighty men of valour three hundred thousand.', 'and these are the numbers of them according to the house of their fathers of judah the captains of thousands adnah the chief and with him mighty men of valour three hundred thousand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 15, 'And next to him {was} Jehohanan the captain, and with him two hundred and fourscore thousand. {next...: Heb. at his hand}', 'and next to him was jehohanan the captain and with him two hundred and fourscore thousand next heb at his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 16, 'And next him {was} Amasiah the son of Zichri, who willingly offered himself unto the LORD; and with him two hundred thousand mighty men of valour.', 'and next him was amasiah the son of zichri who willingly offered himself unto the lord and with him two hundred thousand mighty men of valour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 17, 'And of Benjamin; Eliada a mighty man of valour, and with him armed men with bow and shield two hundred thousand.', 'and of benjamin eliada a mighty man of valour and with him armed men with bow and shield two hundred thousand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 18, 'And next him {was} Jehozabad, and with him an hundred and fourscore thousand ready prepared for the war.', 'and next him was jehozabad and with him an hundred and fourscore thousand ready prepared for the war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 17, 19, 'These waited on the king, beside {those} whom the king put in the fenced cities throughout all Judah.', 'these waited on the king beside those whom the king put in the fenced cities throughout all judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 1, 'Now Jehoshaphat had riches and honour in abundance, and joined affinity with Ahab.', 'now jehoshaphat had riches and honour in abundance and joined affinity with ahab');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 2, 'And after {certain} years he went down to Ahab to Samaria. And Ahab killed sheep and oxen for him in abundance, and for the people that {he had} with him, and persuaded him to go up {with him} to Ramothgilead. {after...: Heb. at the end of years}', 'and after certain years he went down to ahab to samaria and ahab killed sheep and oxen for him in abundance and for the people that he had with him and persuaded him to go up with him to ramothgilead after heb at the end of years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 3, 'And Ahab king of Israel said unto Jehoshaphat king of Judah, Wilt thou go with me to Ramothgilead? And he answered him, I {am} as thou {art}, and my people as thy people; and {we will be} with thee in the war.', 'and ahab king of israel said unto jehoshaphat king of judah wilt thou go with me to ramothgilead and he answered him i am as thou art and my people as thy people and we will be with thee in the war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 4, 'And Jehoshaphat said unto the king of Israel, Enquire, I pray thee, at the word of the LORD to day.', 'and jehoshaphat said unto the king of israel enquire i pray thee at the word of the lord to day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 5, 'Therefore the king of Israel gathered together of prophets four hundred men, and said unto them, Shall we go to Ramothgilead to battle, or shall I forbear? And they said, Go up; for God will deliver {it} into the king''s hand.', 'therefore the king of israel gathered together of prophets four hundred men and said unto them shall we go to ramothgilead to battle or shall i forbear and they said go up for god will deliver it into the king s hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 6, 'But Jehoshaphat said, {Is there} not here a prophet of the LORD besides, that we might enquire of him? {besides: Heb. yet, or, more}', 'but jehoshaphat said is there not here a prophet of the lord besides that we might enquire of him besides heb yet or more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 7, 'And the king of Israel said unto Jehoshaphat, {There is} yet one man, by whom we may enquire of the LORD: but I hate him; for he never prophesied good unto me, but always evil: the same {is} Micaiah the son of Imla. And Jehoshaphat said, Let not the king say so.', 'and the king of israel said unto jehoshaphat there is yet one man by whom we may enquire of the lord but i hate him for he never prophesied good unto me but always evil the same is micaiah the son of imla and jehoshaphat said let not the king say so');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 8, 'And the king of Israel called for one {of his} officers, and said, Fetch quickly Micaiah the son of Imla. {officers: or, eunuchs} {Fetch...: Heb. Hasten}', 'and the king of israel called for one of his officers and said fetch quickly micaiah the son of imla officers or eunuchs fetch heb hasten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 9, 'And the king of Israel and Jehoshaphat king of Judah sat either of them on his throne, clothed in {their} robes, and they sat in a void place at the entering in of the gate of Samaria; and all the prophets prophesied before them. {void...: or, floor}', 'and the king of israel and jehoshaphat king of judah sat either of them on his throne clothed in their robes and they sat in a void place at the entering in of the gate of samaria and all the prophets prophesied before them void or floor');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 10, 'And Zedekiah the son of Chenaanah had made him horns of iron, and said, Thus saith the LORD, With these thou shalt push Syria until they be consumed. {they...: Heb. thou consume them}', 'and zedekiah the son of chenaanah had made him horns of iron and said thus saith the lord with these thou shalt push syria until they be consumed they heb thou consume them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 11, 'And all the prophets prophesied so, saying, Go up to Ramothgilead, and prosper: for the LORD shall deliver {it} into the hand of the king.', 'and all the prophets prophesied so saying go up to ramothgilead and prosper for the lord shall deliver it into the hand of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 12, 'And the messenger that went to call Micaiah spake to him, saying, Behold, the words of the prophets {declare} good to the king with one assent; let thy word therefore, I pray thee, be like one of theirs, and speak thou good. {with...: Heb. with one mouth}', 'and the messenger that went to call micaiah spake to him saying behold the words of the prophets declare good to the king with one assent let thy word therefore i pray thee be like one of theirs and speak thou good with heb with one mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 13, 'And Micaiah said, {As} the LORD liveth, even what my God saith, that will I speak.', 'and micaiah said as the lord liveth even what my god saith that will i speak');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 14, 'And when he was come to the king, the king said unto him, Micaiah, shall we go to Ramothgilead to battle, or shall I forbear? And he said, Go ye up, and prosper, and they shall be delivered into your hand.', 'and when he was come to the king the king said unto him micaiah shall we go to ramothgilead to battle or shall i forbear and he said go ye up and prosper and they shall be delivered into your hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 15, 'And the king said to him, How many times shall I adjure thee that thou say nothing but the truth to me in the name of the LORD?', 'and the king said to him how many times shall i adjure thee that thou say nothing but the truth to me in the name of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 16, 'Then he said, I did see all Israel scattered upon the mountains, as sheep that have no shepherd: and the LORD said, These have no master; let them return {therefore} every man to his house in peace.', 'then he said i did see all israel scattered upon the mountains as sheep that have no shepherd and the lord said these have no master let them return therefore every man to his house in peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 17, 'And the king of Israel said to Jehoshaphat, Did I not tell thee {that} he would not prophesy good unto me, but evil? {but evil: or, but for evil}', 'and the king of israel said to jehoshaphat did i not tell thee that he would not prophesy good unto me but evil but evil or but for evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 18, 'Again he said, Therefore hear the word of the LORD; I saw the LORD sitting upon his throne, and all the host of heaven standing on his right hand and {on} his left.', 'again he said therefore hear the word of the lord i saw the lord sitting upon his throne and all the host of heaven standing on his right hand and on his left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 19, 'And the LORD said, Who shall entice Ahab king of Israel, that he may go up and fall at Ramothgilead? And one spake saying after this manner, and another saying after that manner.', 'and the lord said who shall entice ahab king of israel that he may go up and fall at ramothgilead and one spake saying after this manner and another saying after that manner');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 20, 'Then there came out a spirit, and stood before the LORD, and said, I will entice him. And the LORD said unto him, Wherewith?', 'then there came out a spirit and stood before the lord and said i will entice him and the lord said unto him wherewith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 21, 'And he said, I will go out, and be a lying spirit in the mouth of all his prophets. And {the LORD} said, Thou shalt entice {him}, and thou shalt also prevail: go out, and do {even} so.', 'and he said i will go out and be a lying spirit in the mouth of all his prophets and the lord said thou shalt entice him and thou shalt also prevail go out and do even so');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 22, 'Now therefore, behold, the LORD hath put a lying spirit in the mouth of these thy prophets, and the LORD hath spoken evil against thee.', 'now therefore behold the lord hath put a lying spirit in the mouth of these thy prophets and the lord hath spoken evil against thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 23, 'Then Zedekiah the son of Chenaanah came near, and smote Micaiah upon the cheek, and said, Which way went the Spirit of the LORD from me to speak unto thee?', 'then zedekiah the son of chenaanah came near and smote micaiah upon the cheek and said which way went the spirit of the lord from me to speak unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 24, 'And Micaiah said, Behold, thou shalt see on that day when thou shalt go into an inner chamber to hide thyself. {into...: or, from chamber to chamber: Heb. a chamber in a chamber}', 'and micaiah said behold thou shalt see on that day when thou shalt go into an inner chamber to hide thyself into or from chamber to chamber heb a chamber in a chamber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 25, 'Then the king of Israel said, Take ye Micaiah, and carry him back to Amon the governor of the city, and to Joash the king''s son;', 'then the king of israel said take ye micaiah and carry him back to amon the governor of the city and to joash the king s son');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 26, 'And say, Thus saith the king, Put this {fellow} in the prison, and feed him with bread of affliction and with water of affliction, until I return in peace.', 'and say thus saith the king put this fellow in the prison and feed him with bread of affliction and with water of affliction until i return in peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 27, 'And Micaiah said, If thou certainly return in peace, {then} hath not the LORD spoken by me. And he said, Hearken, all ye people.', 'and micaiah said if thou certainly return in peace then hath not the lord spoken by me and he said hearken all ye people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 28, 'So the king of Israel and Jehoshaphat the king of Judah went up to Ramothgilead.', 'so the king of israel and jehoshaphat the king of judah went up to ramothgilead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 29, 'And the king of Israel said unto Jehoshaphat, I will disguise myself, and will go to the battle; but put thou on thy robes. So the king of Israel disguised himself; and they went to the battle.', 'and the king of israel said unto jehoshaphat i will disguise myself and will go to the battle but put thou on thy robes so the king of israel disguised himself and they went to the battle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 30, 'Now the king of Syria had commanded the captains of the chariots that {were} with him, saying, Fight ye not with small or great, save only with the king of Israel.', 'now the king of syria had commanded the captains of the chariots that were with him saying fight ye not with small or great save only with the king of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 31, 'And it came to pass, when the captains of the chariots saw Jehoshaphat, that they said, It {is} the king of Israel. Therefore they compassed about him to fight: but Jehoshaphat cried out, and the LORD helped him; and God moved them {to depart} from him.', 'and it came to pass when the captains of the chariots saw jehoshaphat that they said it is the king of israel therefore they compassed about him to fight but jehoshaphat cried out and the lord helped him and god moved them to depart from him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 32, 'For it came to pass, that, when the captains of the chariots perceived that it was not the king of Israel, they turned back again from pursuing him. {from...: Heb. from after him}', 'for it came to pass that when the captains of the chariots perceived that it was not the king of israel they turned back again from pursuing him from heb from after him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 33, 'And a {certain} man drew a bow at a venture, and smote the king of Israel between the joints of the harness: therefore he said to his chariot man, Turn thine hand, that thou mayest carry me out of the host; for I am wounded. {at a venture: Heb. in his simplicity} {between...: Heb. between the joints and between the breastplate} {wounded: Heb. made sick}', 'and a certain man drew a bow at a venture and smote the king of israel between the joints of the harness therefore he said to his chariot man turn thine hand that thou mayest carry me out of the host for i am wounded at a venture heb in his simplicity between heb between the joints and between the breastplate wounded heb made sick');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 18, 34, 'And the battle increased that day: howbeit the king of Israel stayed {himself} up in {his} chariot against the Syrians until the even: and about the time of the sun going down he died.', 'and the battle increased that day howbeit the king of israel stayed himself up in his chariot against the syrians until the even and about the time of the sun going down he died');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 1, 'And Jehoshaphat the king of Judah returned to his house in peace to Jerusalem.', 'and jehoshaphat the king of judah returned to his house in peace to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 2, 'And Jehu the son of Hanani the seer went out to meet him, and said to king Jehoshaphat, Shouldest thou help the ungodly, and love them that hate the LORD? therefore {is} wrath upon thee from before the LORD.', 'and jehu the son of hanani the seer went out to meet him and said to king jehoshaphat shouldest thou help the ungodly and love them that hate the lord therefore is wrath upon thee from before the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 3, 'Nevertheless there are good things found in thee, in that thou hast taken away the groves out of the land, and hast prepared thine heart to seek God.', 'nevertheless there are good things found in thee in that thou hast taken away the groves out of the land and hast prepared thine heart to seek god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 4, 'And Jehoshaphat dwelt at Jerusalem: and he went out again through the people from Beersheba to mount Ephraim, and brought them back unto the LORD God of their fathers. {he went...: Heb. he returned and went out}', 'and jehoshaphat dwelt at jerusalem and he went out again through the people from beersheba to mount ephraim and brought them back unto the lord god of their fathers he went heb he returned and went out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 5, 'And he set judges in the land throughout all the fenced cities of Judah, city by city,', 'and he set judges in the land throughout all the fenced cities of judah city by city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 6, 'And said to the judges, Take heed what ye do: for ye judge not for man, but for the LORD, who {is} with you in the judgment. {in...: Heb. in the matter of judgment}', 'and said to the judges take heed what ye do for ye judge not for man but for the lord who is with you in the judgment in heb in the matter of judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 7, 'Wherefore now let the fear of the LORD be upon you; take heed and do {it}: for {there is} no iniquity with the LORD our God, nor respect of persons, nor taking of gifts.', 'wherefore now let the fear of the lord be upon you take heed and do it for there is no iniquity with the lord our god nor respect of persons nor taking of gifts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 8, 'Moreover in Jerusalem did Jehoshaphat set of the Levites, and {of} the priests, and of the chief of the fathers of Israel, for the judgment of the LORD, and for controversies, when they returned to Jerusalem.', 'moreover in jerusalem did jehoshaphat set of the levites and of the priests and of the chief of the fathers of israel for the judgment of the lord and for controversies when they returned to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 9, 'And he charged them, saying, Thus shall ye do in the fear of the LORD, faithfully, and with a perfect heart.', 'and he charged them saying thus shall ye do in the fear of the lord faithfully and with a perfect heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 10, 'And what cause soever shall come to you of your brethren that dwell in their cities, between blood and blood, between law and commandment, statutes and judgments, ye shall even warn them that they trespass not against the LORD, and {so} wrath come upon you, and upon your brethren: this do, and ye shall not trespass.', 'and what cause soever shall come to you of your brethren that dwell in their cities between blood and blood between law and commandment statutes and judgments ye shall even warn them that they trespass not against the lord and so wrath come upon you and upon your brethren this do and ye shall not trespass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 19, 11, 'And, behold, Amariah the chief priest {is} over you in all matters of the LORD; and Zebadiah the son of Ishmael, the ruler of the house of Judah, for all the king''s matters: also the Levites {shall be} officers before you. Deal courageously, and the LORD shall be with the good. {Deal...: Heb. Take courage and do}', 'and behold amariah the chief priest is over you in all matters of the lord and zebadiah the son of ishmael the ruler of the house of judah for all the king s matters also the levites shall be officers before you deal courageously and the lord shall be with the good deal heb take courage and do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 1, 'It came to pass after this also, {that} the children of Moab, and the children of Ammon, and with them {other} beside the Ammonites, came against Jehoshaphat to battle.', 'it came to pass after this also that the children of moab and the children of ammon and with them other beside the ammonites came against jehoshaphat to battle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 2, 'Then there came some that told Jehoshaphat, saying, There cometh a great multitude against thee from beyond the sea on this side Syria; and, behold, they {be} in Hazazontamar, which {is} Engedi.', 'then there came some that told jehoshaphat saying there cometh a great multitude against thee from beyond the sea on this side syria and behold they be in hazazontamar which is engedi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 3, 'And Jehoshaphat feared, and set himself to seek the LORD, and proclaimed a fast throughout all Judah. {himself: Heb. his face}', 'and jehoshaphat feared and set himself to seek the lord and proclaimed a fast throughout all judah himself heb his face');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 4, 'And Judah gathered themselves together, to ask {help} of the LORD: even out of all the cities of Judah they came to seek the LORD.', 'and judah gathered themselves together to ask help of the lord even out of all the cities of judah they came to seek the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 5, 'And Jehoshaphat stood in the congregation of Judah and Jerusalem, in the house of the LORD, before the new court,', 'and jehoshaphat stood in the congregation of judah and jerusalem in the house of the lord before the new court');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 6, 'And said, O LORD God of our fathers, {art} not thou God in heaven? and rulest {not} thou over all the kingdoms of the heathen? and in thine hand {is there not} power and might, so that none is able to withstand thee?', 'and said o lord god of our fathers art not thou god in heaven and rulest not thou over all the kingdoms of the heathen and in thine hand is there not power and might so that none is able to withstand thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 7, '{Art} not thou our God, {who} didst drive out the inhabitants of this land before thy people Israel, and gavest it to the seed of Abraham thy friend for ever? {who: Heb. thou}', 'art not thou our god who didst drive out the inhabitants of this land before thy people israel and gavest it to the seed of abraham thy friend for ever who heb thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 8, 'And they dwelt therein, and have built thee a sanctuary therein for thy name, saying,', 'and they dwelt therein and have built thee a sanctuary therein for thy name saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 9, 'If, {when} evil cometh upon us, {as} the sword, judgment, or pestilence, or famine, we stand before this house, and in thy presence, (for thy name {is} in this house,) and cry unto thee in our affliction, then thou wilt hear and help.', 'if when evil cometh upon us as the sword judgment or pestilence or famine we stand before this house and in thy presence for thy name is in this house and cry unto thee in our affliction then thou wilt hear and help');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 10, 'And now, behold, the children of Ammon and Moab and mount Seir, whom thou wouldest not let Israel invade, when they came out of the land of Egypt, but they turned from them, and destroyed them not;', 'and now behold the children of ammon and moab and mount seir whom thou wouldest not let israel invade when they came out of the land of egypt but they turned from them and destroyed them not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 11, 'Behold, {I say, how} they reward us, to come to cast us out of thy possession, which thou hast given us to inherit.', 'behold i say how they reward us to come to cast us out of thy possession which thou hast given us to inherit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 12, 'O our God, wilt thou not judge them? for we have no might against this great company that cometh against us; neither know we what to do: but our eyes {are} upon thee.', 'o our god wilt thou not judge them for we have no might against this great company that cometh against us neither know we what to do but our eyes are upon thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 13, 'And all Judah stood before the LORD, with their little ones, their wives, and their children.', 'and all judah stood before the lord with their little ones their wives and their children');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 14, 'Then upon Jahaziel the son of Zechariah, the son of Benaiah, the son of Jeiel, the son of Mattaniah, a Levite of the sons of Asaph, came the Spirit of the LORD in the midst of the congregation;', 'then upon jahaziel the son of zechariah the son of benaiah the son of jeiel the son of mattaniah a levite of the sons of asaph came the spirit of the lord in the midst of the congregation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 15, 'And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the LORD unto you, Be not afraid nor dismayed by reason of this great multitude; for the battle {is} not yours, but God''s.', 'and he said hearken ye all judah and ye inhabitants of jerusalem and thou king jehoshaphat thus saith the lord unto you be not afraid nor dismayed by reason of this great multitude for the battle is not yours but god s');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 16, 'To morrow go ye down against them: behold, they come up by the cliff of Ziz; and ye shall find them at the end of the brook, before the wilderness of Jeruel. {cliff: Heb. ascent} {brook: or, valley}', 'to morrow go ye down against them behold they come up by the cliff of ziz and ye shall find them at the end of the brook before the wilderness of jeruel cliff heb ascent brook or valley');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 17, 'Ye shall not {need} to fight in this {battle}: set yourselves, stand ye {still}, and see the salvation of the LORD with you, O Judah and Jerusalem: fear not, nor be dismayed; to morrow go out against them: for the LORD {will be} with you.', 'ye shall not need to fight in this battle set yourselves stand ye still and see the salvation of the lord with you o judah and jerusalem fear not nor be dismayed to morrow go out against them for the lord will be with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 18, 'And Jehoshaphat bowed his head with {his} face to the ground: and all Judah and the inhabitants of Jerusalem fell before the LORD, worshipping the LORD.', 'and jehoshaphat bowed his head with his face to the ground and all judah and the inhabitants of jerusalem fell before the lord worshipping the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 19, 'And the Levites, of the children of the Kohathites, and of the children of the Korhites, stood up to praise the LORD God of Israel with a loud voice on high.', 'and the levites of the children of the kohathites and of the children of the korhites stood up to praise the lord god of israel with a loud voice on high');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 20, 'And they rose early in the morning, and went forth into the wilderness of Tekoa: and as they went forth, Jehoshaphat stood and said, Hear me, O Judah, and ye inhabitants of Jerusalem; Believe in the LORD your God, so shall ye be established; believe his prophets, so shall ye prosper.', 'and they rose early in the morning and went forth into the wilderness of tekoa and as they went forth jehoshaphat stood and said hear me o judah and ye inhabitants of jerusalem believe in the lord your god so shall ye be established believe his prophets so shall ye prosper');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 21, 'And when he had consulted with the people, he appointed singers unto the LORD, and that should praise the beauty of holiness, as they went out before the army, and to say, Praise the LORD; for his mercy {endureth} for ever. {that...: Heb. praisers}', 'and when he had consulted with the people he appointed singers unto the lord and that should praise the beauty of holiness as they went out before the army and to say praise the lord for his mercy endureth for ever that heb praisers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 22, 'And when they began to sing and to praise, the LORD set ambushments against the children of Ammon, Moab, and mount Seir, which were come against Judah; and they were smitten. {And when...: Heb. And in the time that they, etc} {to sing...: Heb. in singing and praise} {they were...: or, they smote one another}', 'and when they began to sing and to praise the lord set ambushments against the children of ammon moab and mount seir which were come against judah and they were smitten and when heb and in the time that they etc to sing heb in singing and praise they were or they smote one another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 23, 'For the children of Ammon and Moab stood up against the inhabitants of mount Seir, utterly to slay and destroy {them}: and when they had made an end of the inhabitants of Seir, every one helped to destroy another. {to destroy: Heb. for the destruction}', 'for the children of ammon and moab stood up against the inhabitants of mount seir utterly to slay and destroy them and when they had made an end of the inhabitants of seir every one helped to destroy another to destroy heb for the destruction');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 24, 'And when Judah came toward the watch tower in the wilderness, they looked unto the multitude, and, behold, they {were} dead bodies fallen to the earth, and none escaped. {none...: Heb. there was not an escaping}', 'and when judah came toward the watch tower in the wilderness they looked unto the multitude and behold they were dead bodies fallen to the earth and none escaped none heb there was not an escaping');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 25, 'And when Jehoshaphat and his people came to take away the spoil of them, they found among them in abundance both riches with the dead bodies, and precious jewels, which they stripped off for themselves, more than they could carry away: and they were three days in gathering of the spoil, it was so much.', 'and when jehoshaphat and his people came to take away the spoil of them they found among them in abundance both riches with the dead bodies and precious jewels which they stripped off for themselves more than they could carry away and they were three days in gathering of the spoil it was so much');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 26, 'And on the fourth day they assembled themselves in the valley of Berachah; for there they blessed the LORD: therefore the name of the same place was called, The valley of Berachah, unto this day. {Berachah: that is, blessing}', 'and on the fourth day they assembled themselves in the valley of berachah for there they blessed the lord therefore the name of the same place was called the valley of berachah unto this day berachah that is blessing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 27, 'Then they returned, every man of Judah and Jerusalem, and Jehoshaphat in the forefront of them, to go again to Jerusalem with joy; for the LORD had made them to rejoice over their enemies. {forefront: Heb. head}', 'then they returned every man of judah and jerusalem and jehoshaphat in the forefront of them to go again to jerusalem with joy for the lord had made them to rejoice over their enemies forefront heb head');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 28, 'And they came to Jerusalem with psalteries and harps and trumpets unto the house of the LORD.', 'and they came to jerusalem with psalteries and harps and trumpets unto the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 29, 'And the fear of God was on all the kingdoms of {those} countries, when they had heard that the LORD fought against the enemies of Israel.', 'and the fear of god was on all the kingdoms of those countries when they had heard that the lord fought against the enemies of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 30, 'So the realm of Jehoshaphat was quiet: for his God gave him rest round about.', 'so the realm of jehoshaphat was quiet for his god gave him rest round about');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 31, 'And Jehoshaphat reigned over Judah: {he was} thirty and five years old when he began to reign, and he reigned twenty and five years in Jerusalem. And his mother''s name {was} Azubah the daughter of Shilhi.', 'and jehoshaphat reigned over judah he was thirty and five years old when he began to reign and he reigned twenty and five years in jerusalem and his mother s name was azubah the daughter of shilhi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 32, 'And he walked in the way of Asa his father, and departed not from it, doing {that which was} right in the sight of the LORD.', 'and he walked in the way of asa his father and departed not from it doing that which was right in the sight of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 33, 'Howbeit the high places were not taken away: for as yet the people had not prepared their hearts unto the God of their fathers.', 'howbeit the high places were not taken away for as yet the people had not prepared their hearts unto the god of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 34, 'Now the rest of the acts of Jehoshaphat, first and last, behold, they {are} written in the book of Jehu the son of Hanani, who {is} mentioned in the book of the kings of Israel. {book of Jehu: Heb. words, etc} {is mentioned: Heb. was made to ascend}', 'now the rest of the acts of jehoshaphat first and last behold they are written in the book of jehu the son of hanani who is mentioned in the book of the kings of israel book of jehu heb words etc is mentioned heb was made to ascend');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 35, 'And after this did Jehoshaphat king of Judah join himself with Ahaziah king of Israel, who did very wickedly:', 'and after this did jehoshaphat king of judah join himself with ahaziah king of israel who did very wickedly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 36, 'And he joined himself with him to make ships to go to Tarshish: and they made the ships in Eziongeber.', 'and he joined himself with him to make ships to go to tarshish and they made the ships in eziongeber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 20, 37, 'Then Eliezer the son of Dodavah of Mareshah prophesied against Jehoshaphat, saying, Because thou hast joined thyself with Ahaziah, the LORD hath broken thy works. And the ships were broken, that they were not able to go to Tarshish.', 'then eliezer the son of dodavah of mareshah prophesied against jehoshaphat saying because thou hast joined thyself with ahaziah the lord hath broken thy works and the ships were broken that they were not able to go to tarshish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 1, 'Now Jehoshaphat slept with his fathers, and was buried with his fathers in the city of David. And Jehoram his son reigned in his stead.', 'now jehoshaphat slept with his fathers and was buried with his fathers in the city of david and jehoram his son reigned in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 2, 'And he had brethren the sons of Jehoshaphat, Azariah, and Jehiel, and Zechariah, and Azariah, and Michael, and Shephatiah: all these {were} the sons of Jehoshaphat king of Israel.', 'and he had brethren the sons of jehoshaphat azariah and jehiel and zechariah and azariah and michael and shephatiah all these were the sons of jehoshaphat king of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 3, 'And their father gave them great gifts of silver, and of gold, and of precious things, with fenced cities in Judah: but the kingdom gave he to Jehoram; because he {was} the firstborn.', 'and their father gave them great gifts of silver and of gold and of precious things with fenced cities in judah but the kingdom gave he to jehoram because he was the firstborn');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 4, 'Now when Jehoram was risen up to the kingdom of his father, he strengthened himself, and slew all his brethren with the sword, and {divers} also of the princes of Israel.', 'now when jehoram was risen up to the kingdom of his father he strengthened himself and slew all his brethren with the sword and divers also of the princes of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 5, 'Jehoram {was} thirty and two years old when he began to reign, and he reigned eight years in Jerusalem.', 'jehoram was thirty and two years old when he began to reign and he reigned eight years in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 6, 'And he walked in the way of the kings of Israel, like as did the house of Ahab: for he had the daughter of Ahab to wife: and he wrought {that which was} evil in the eyes of the LORD.', 'and he walked in the way of the kings of israel like as did the house of ahab for he had the daughter of ahab to wife and he wrought that which was evil in the eyes of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 7, 'Howbeit the LORD would not destroy the house of David, because of the covenant that he had made with David, and as he promised to give a light to him and to his sons for ever. {light: Heb. lamp, or, candle}', 'howbeit the lord would not destroy the house of david because of the covenant that he had made with david and as he promised to give a light to him and to his sons for ever light heb lamp or candle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 8, 'In his days the Edomites revolted from under the dominion of Judah, and made themselves a king. {dominion: Heb. hand}', 'in his days the edomites revolted from under the dominion of judah and made themselves a king dominion heb hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 9, 'Then Jehoram went forth with his princes, and all his chariots with him: and he rose up by night, and smote the Edomites which compassed him in, and the captains of the chariots.', 'then jehoram went forth with his princes and all his chariots with him and he rose up by night and smote the edomites which compassed him in and the captains of the chariots');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 10, 'So the Edomites revolted from under the hand of Judah unto this day. The same time {also} did Libnah revolt from under his hand; because he had forsaken the LORD God of his fathers.', 'so the edomites revolted from under the hand of judah unto this day the same time also did libnah revolt from under his hand because he had forsaken the lord god of his fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 11, 'Moreover he made high places in the mountains of Judah, and caused the inhabitants of Jerusalem to commit fornication, and compelled Judah {thereto}.', 'moreover he made high places in the mountains of judah and caused the inhabitants of jerusalem to commit fornication and compelled judah thereto');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 12, 'And there came a writing to him from Elijah the prophet, saying, Thus saith the LORD God of David thy father, Because thou hast not walked in the ways of Jehoshaphat thy father, nor in the ways of Asa king of Judah,', 'and there came a writing to him from elijah the prophet saying thus saith the lord god of david thy father because thou hast not walked in the ways of jehoshaphat thy father nor in the ways of asa king of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 13, 'But hast walked in the way of the kings of Israel, and hast made Judah and the inhabitants of Jerusalem to go a whoring, like to the whoredoms of the house of Ahab, and also hast slain thy brethren of thy father''s house, {which were} better than thyself:', 'but hast walked in the way of the kings of israel and hast made judah and the inhabitants of jerusalem to go a whoring like to the whoredoms of the house of ahab and also hast slain thy brethren of thy father s house which were better than thyself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 14, 'Behold, with a great plague will the LORD smite thy people, and thy children, and thy wives, and all thy goods: {a great...: Heb. a great stroke}', 'behold with a great plague will the lord smite thy people and thy children and thy wives and all thy goods a great heb a great stroke');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 15, 'And thou {shalt have} great sickness by disease of thy bowels, until thy bowels fall out by reason of the sickness day by day.', 'and thou shalt have great sickness by disease of thy bowels until thy bowels fall out by reason of the sickness day by day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 16, 'Moreover the LORD stirred up against Jehoram the spirit of the Philistines, and of the Arabians, that {were} near the Ethiopians:', 'moreover the lord stirred up against jehoram the spirit of the philistines and of the arabians that were near the ethiopians');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 17, 'And they came up into Judah, and brake into it, and carried away all the substance that was found in the king''s house, and his sons also, and his wives; so that there was never a son left him, save Jehoahaz, the youngest of his sons. {carried...: Heb. carried captive} {Jehoahaz: also called, Ahaziah, or, Azariah}', 'and they came up into judah and brake into it and carried away all the substance that was found in the king s house and his sons also and his wives so that there was never a son left him save jehoahaz the youngest of his sons carried heb carried captive jehoahaz also called ahaziah or azariah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 18, 'And after all this the LORD smote him in his bowels with an incurable disease.', 'and after all this the lord smote him in his bowels with an incurable disease');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 19, 'And it came to pass, that in process of time, after the end of two years, his bowels fell out by reason of his sickness: so he died of sore diseases. And his people made no burning for him, like the burning of his fathers.', 'and it came to pass that in process of time after the end of two years his bowels fell out by reason of his sickness so he died of sore diseases and his people made no burning for him like the burning of his fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 21, 20, 'Thirty and two years old was he when he began to reign, and he reigned in Jerusalem eight years, and departed without being desired. Howbeit they buried him in the city of David, but not in the sepulchres of the kings. {without...: Heb. without desire}', 'thirty and two years old was he when he began to reign and he reigned in jerusalem eight years and departed without being desired howbeit they buried him in the city of david but not in the sepulchres of the kings without heb without desire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 1, 'And the inhabitants of Jerusalem made Ahaziah his youngest son king in his stead: for the band of men that came with the Arabians to the camp had slain all the eldest. So Ahaziah the son of Jehoram king of Judah reigned.', 'and the inhabitants of jerusalem made ahaziah his youngest son king in his stead for the band of men that came with the arabians to the camp had slain all the eldest so ahaziah the son of jehoram king of judah reigned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 2, 'Forty and two years old {was} Ahaziah when he began to reign, and he reigned one year in Jerusalem. His mother''s name also {was} Athaliah the daughter of Omri.', 'forty and two years old was ahaziah when he began to reign and he reigned one year in jerusalem his mother s name also was athaliah the daughter of omri');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 3, 'He also walked in the ways of the house of Ahab: for his mother was his counsellor to do wickedly.', 'he also walked in the ways of the house of ahab for his mother was his counsellor to do wickedly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 4, 'Wherefore he did evil in the sight of the LORD like the house of Ahab: for they were his counsellors after the death of his father to his destruction.', 'wherefore he did evil in the sight of the lord like the house of ahab for they were his counsellors after the death of his father to his destruction');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 5, 'He walked also after their counsel, and went with Jehoram the son of Ahab king of Israel to war against Hazael king of Syria at Ramothgilead: and the Syrians smote Joram.', 'he walked also after their counsel and went with jehoram the son of ahab king of israel to war against hazael king of syria at ramothgilead and the syrians smote joram');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 6, 'And he returned to be healed in Jezreel because of the wounds which were given him at Ramah, when he fought with Hazael king of Syria. And Azariah the son of Jehoram king of Judah went down to see Jehoram the son of Ahab at Jezreel, because he was sick. {which...: Heb. wherewith they wounded him} {Azariah: also called, Ahaziah, or, Jehoahaz}', 'and he returned to be healed in jezreel because of the wounds which were given him at ramah when he fought with hazael king of syria and azariah the son of jehoram king of judah went down to see jehoram the son of ahab at jezreel because he was sick which heb wherewith they wounded him azariah also called ahaziah or jehoahaz');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 7, 'And the destruction of Ahaziah was of God by coming to Joram: for when he was come, he went out with Jehoram against Jehu the son of Nimshi, whom the LORD had anointed to cut off the house of Ahab. {destruction: Heb. treading down}', 'and the destruction of ahaziah was of god by coming to joram for when he was come he went out with jehoram against jehu the son of nimshi whom the lord had anointed to cut off the house of ahab destruction heb treading down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 8, 'And it came to pass, that, when Jehu was executing judgment upon the house of Ahab, and found the princes of Judah, and the sons of the brethren of Ahaziah, that ministered to Ahaziah, he slew them.', 'and it came to pass that when jehu was executing judgment upon the house of ahab and found the princes of judah and the sons of the brethren of ahaziah that ministered to ahaziah he slew them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 9, 'And he sought Ahaziah: and they caught him, (for he was hid in Samaria,) and brought him to Jehu: and when they had slain him, they buried him: Because, said they, he {is} the son of Jehoshaphat, who sought the LORD with all his heart. So the house of Ahaziah had no power to keep still the kingdom.', 'and he sought ahaziah and they caught him for he was hid in samaria and brought him to jehu and when they had slain him they buried him because said they he is the son of jehoshaphat who sought the lord with all his heart so the house of ahaziah had no power to keep still the kingdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 10, 'But when Athaliah the mother of Ahaziah saw that her son was dead, she arose and destroyed all the seed royal of the house of Judah.', 'but when athaliah the mother of ahaziah saw that her son was dead she arose and destroyed all the seed royal of the house of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 11, 'But Jehoshabeath, the daughter of the king, took Joash the son of Ahaziah, and stole him from among the king''s sons that were slain, and put him and his nurse in a bedchamber. So Jehoshabeath, the daughter of king Jehoram, the wife of Jehoiada the priest, (for she was the sister of Ahaziah,) hid him from Athaliah, so that she slew him not. {Jehoshabeath: also called, Jehosheba}', 'but jehoshabeath the daughter of the king took joash the son of ahaziah and stole him from among the king s sons that were slain and put him and his nurse in a bedchamber so jehoshabeath the daughter of king jehoram the wife of jehoiada the priest for she was the sister of ahaziah hid him from athaliah so that she slew him not jehoshabeath also called jehosheba');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 22, 12, 'And he was with them hid in the house of God six years: and Athaliah reigned over the land.', 'and he was with them hid in the house of god six years and athaliah reigned over the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 1, 'And in the seventh year Jehoiada strengthened himself, and took the captains of hundreds, Azariah the son of Jeroham, and Ishmael the son of Jehohanan, and Azariah the son of Obed, and Maaseiah the son of Adaiah, and Elishaphat the son of Zichri, into covenant with him.', 'and in the seventh year jehoiada strengthened himself and took the captains of hundreds azariah the son of jeroham and ishmael the son of jehohanan and azariah the son of obed and maaseiah the son of adaiah and elishaphat the son of zichri into covenant with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 2, 'And they went about in Judah, and gathered the Levites out of all the cities of Judah, and the chief of the fathers of Israel, and they came to Jerusalem.', 'and they went about in judah and gathered the levites out of all the cities of judah and the chief of the fathers of israel and they came to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 3, 'And all the congregation made a covenant with the king in the house of God. And he said unto them, Behold, the king''s son shall reign, as the LORD hath said of the sons of David.', 'and all the congregation made a covenant with the king in the house of god and he said unto them behold the king s son shall reign as the lord hath said of the sons of david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 4, 'This {is} the thing that ye shall do; A third part of you entering on the sabbath, of the priests and of the Levites, {shall be} porters of the doors; {doors: Heb. thresholds}', 'this is the thing that ye shall do a third part of you entering on the sabbath of the priests and of the levites shall be porters of the doors doors heb thresholds');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 5, 'And a third part {shall be} at the king''s house; and a third part at the gate of the foundation: and all the people {shall be} in the courts of the house of the LORD.', 'and a third part shall be at the king s house and a third part at the gate of the foundation and all the people shall be in the courts of the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 6, 'But let none come into the house of the LORD, save the priests, and they that minister of the Levites; they shall go in, for they {are} holy: but all the people shall keep the watch of the LORD.', 'but let none come into the house of the lord save the priests and they that minister of the levites they shall go in for they are holy but all the people shall keep the watch of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 7, 'And the Levites shall compass the king round about, every man with his weapons in his hand; and whosoever {else} cometh into the house, he shall be put to death: but be ye with the king when he cometh in, and when he goeth out.', 'and the levites shall compass the king round about every man with his weapons in his hand and whosoever else cometh into the house he shall be put to death but be ye with the king when he cometh in and when he goeth out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 8, 'So the Levites and all Judah did according to all things that Jehoiada the priest had commanded, and took every man his men that were to come in on the sabbath, with them that were to go {out} on the sabbath: for Jehoiada the priest dismissed not the courses.', 'so the levites and all judah did according to all things that jehoiada the priest had commanded and took every man his men that were to come in on the sabbath with them that were to go out on the sabbath for jehoiada the priest dismissed not the courses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 9, 'Moreover Jehoiada the priest delivered to the captains of hundreds spears, and bucklers, and shields, that {had been} king David''s, which {were} in the house of God.', 'moreover jehoiada the priest delivered to the captains of hundreds spears and bucklers and shields that had been king david s which were in the house of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 10, 'And he set all the people, every man having his weapon in his hand, from the right side of the temple to the left side of the temple, along by the altar and the temple, by the king round about. {side: Heb. shoulder} {temple: Heb. house}', 'and he set all the people every man having his weapon in his hand from the right side of the temple to the left side of the temple along by the altar and the temple by the king round about side heb shoulder temple heb house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 11, 'Then they brought out the king''s son, and put upon him the crown, and {gave him} the testimony, and made him king. And Jehoiada and his sons anointed him, and said, God save the king. {God...: Heb. Let the king live}', 'then they brought out the king s son and put upon him the crown and gave him the testimony and made him king and jehoiada and his sons anointed him and said god save the king god heb let the king live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 12, 'Now when Athaliah heard the noise of the people running and praising the king, she came to the people into the house of the LORD:', 'now when athaliah heard the noise of the people running and praising the king she came to the people into the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 13, 'And she looked, and, behold, the king stood at his pillar at the entering in, and the princes and the trumpets by the king: and all the people of the land rejoiced, and sounded with trumpets, also the singers with instruments of musick, and such as taught to sing praise. Then Athaliah rent her clothes, and said, Treason, Treason. {Treason: Heb. Conspiracy}', 'and she looked and behold the king stood at his pillar at the entering in and the princes and the trumpets by the king and all the people of the land rejoiced and sounded with trumpets also the singers with instruments of musick and such as taught to sing praise then athaliah rent her clothes and said treason treason treason heb conspiracy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 14, 'Then Jehoiada the priest brought out the captains of hundreds that were set over the host, and said unto them, Have her forth of the ranges: and whoso followeth her, let him be slain with the sword. For the priest said, Slay her not in the house of the LORD.', 'then jehoiada the priest brought out the captains of hundreds that were set over the host and said unto them have her forth of the ranges and whoso followeth her let him be slain with the sword for the priest said slay her not in the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 15, 'So they laid hands on her; and when she was come to the entering of the horse gate by the king''s house, they slew her there.', 'so they laid hands on her and when she was come to the entering of the horse gate by the king s house they slew her there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 16, 'And Jehoiada made a covenant between him, and between all the people, and between the king, that they should be the LORD''S people.', 'and jehoiada made a covenant between him and between all the people and between the king that they should be the lord s people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 17, 'Then all the people went to the house of Baal, and brake it down, and brake his altars and his images in pieces, and slew Mattan the priest of Baal before the altars.', 'then all the people went to the house of baal and brake it down and brake his altars and his images in pieces and slew mattan the priest of baal before the altars');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 18, 'Also Jehoiada appointed the offices of the house of the LORD by the hand of the priests the Levites, whom David had distributed in the house of the LORD, to offer the burnt offerings of the LORD, as {it is} written in the law of Moses, with rejoicing and with singing, {as it was ordained} by David. {as it was...: Heb. by the hands of David}', 'also jehoiada appointed the offices of the house of the lord by the hand of the priests the levites whom david had distributed in the house of the lord to offer the burnt offerings of the lord as it is written in the law of moses with rejoicing and with singing as it was ordained by david as it was heb by the hands of david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 19, 'And he set the porters at the gates of the house of the LORD, that none {which was} unclean in any thing should enter in.', 'and he set the porters at the gates of the house of the lord that none which was unclean in any thing should enter in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 20, 'And he took the captains of hundreds, and the nobles, and the governors of the people, and all the people of the land, and brought down the king from the house of the LORD: and they came through the high gate into the king''s house, and set the king upon the throne of the kingdom.', 'and he took the captains of hundreds and the nobles and the governors of the people and all the people of the land and brought down the king from the house of the lord and they came through the high gate into the king s house and set the king upon the throne of the kingdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 23, 21, 'And all the people of the land rejoiced: and the city was quiet, after that they had slain Athaliah with the sword.', 'and all the people of the land rejoiced and the city was quiet after that they had slain athaliah with the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 1, 'Joash {was} seven years old when he began to reign, and he reigned forty years in Jerusalem. His mother''s name also {was} Zibiah of Beersheba.', 'joash was seven years old when he began to reign and he reigned forty years in jerusalem his mother s name also was zibiah of beersheba');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 2, 'And Joash did {that which was} right in the sight of the LORD all the days of Jehoiada the priest.', 'and joash did that which was right in the sight of the lord all the days of jehoiada the priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 3, 'And Jehoiada took for him two wives; and he begat sons and daughters.', 'and jehoiada took for him two wives and he begat sons and daughters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 4, 'And it came to pass after this, {that} Joash was minded to repair the house of the LORD. {to repair: Heb. to renew}', 'and it came to pass after this that joash was minded to repair the house of the lord to repair heb to renew');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 5, 'And he gathered together the priests and the Levites, and said to them, Go out unto the cities of Judah, and gather of all Israel money to repair the house of your God from year to year, and see that ye hasten the matter. Howbeit the Levites hastened {it} not.', 'and he gathered together the priests and the levites and said to them go out unto the cities of judah and gather of all israel money to repair the house of your god from year to year and see that ye hasten the matter howbeit the levites hastened it not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 6, 'And the king called for Jehoiada the chief, and said unto him, Why hast thou not required of the Levites to bring in out of Judah and out of Jerusalem the collection, {according to the commandment} of Moses the servant of the LORD, and of the congregation of Israel, for the tabernacle of witness?', 'and the king called for jehoiada the chief and said unto him why hast thou not required of the levites to bring in out of judah and out of jerusalem the collection according to the commandment of moses the servant of the lord and of the congregation of israel for the tabernacle of witness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 7, 'For the sons of Athaliah, that wicked woman, had broken up the house of God; and also all the dedicated things of the house of the LORD did they bestow upon Baalim.', 'for the sons of athaliah that wicked woman had broken up the house of god and also all the dedicated things of the house of the lord did they bestow upon baalim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 8, 'And at the king''s commandment they made a chest, and set it without at the gate of the house of the LORD.', 'and at the king s commandment they made a chest and set it without at the gate of the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 9, 'And they made a proclamation through Judah and Jerusalem, to bring in to the LORD the collection {that} Moses the servant of God {laid} upon Israel in the wilderness. {a proclamation: Heb. a voice}', 'and they made a proclamation through judah and jerusalem to bring in to the lord the collection that moses the servant of god laid upon israel in the wilderness a proclamation heb a voice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 10, 'And all the princes and all the people rejoiced, and brought in, and cast into the chest, until they had made an end.', 'and all the princes and all the people rejoiced and brought in and cast into the chest until they had made an end');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 11, 'Now it came to pass, that at what time the chest was brought unto the king''s office by the hand of the Levites, and when they saw that {there was} much money, the king''s scribe and the high priest''s officer came and emptied the chest, and took it, and carried it to his place again. Thus they did day by day, and gathered money in abundance.', 'now it came to pass that at what time the chest was brought unto the king s office by the hand of the levites and when they saw that there was much money the king s scribe and the high priest s officer came and emptied the chest and took it and carried it to his place again thus they did day by day and gathered money in abundance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 12, 'And the king and Jehoiada gave it to such as did the work of the service of the house of the LORD, and hired masons and carpenters to repair the house of the LORD, and also such as wrought iron and brass to mend the house of the LORD.', 'and the king and jehoiada gave it to such as did the work of the service of the house of the lord and hired masons and carpenters to repair the house of the lord and also such as wrought iron and brass to mend the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 13, 'So the workmen wrought, and the work was perfected by them, and they set the house of God in his state, and strengthened it. {the work...: Heb. the healing went up upon the work}', 'so the workmen wrought and the work was perfected by them and they set the house of god in his state and strengthened it the work heb the healing went up upon the work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 14, 'And when they had finished {it}, they brought the rest of the money before the king and Jehoiada, whereof were made vessels for the house of the LORD, {even} vessels to minister, and to offer {withal}, and spoons, and vessels of gold and silver. And they offered burnt offerings in the house of the LORD continually all the days of Jehoiada. {to offer...: or, pestils}', 'and when they had finished it they brought the rest of the money before the king and jehoiada whereof were made vessels for the house of the lord even vessels to minister and to offer withal and spoons and vessels of gold and silver and they offered burnt offerings in the house of the lord continually all the days of jehoiada to offer or pestils');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 15, 'But Jehoiada waxed old, and was full of days when he died; an hundred and thirty years old {was he} when he died.', 'but jehoiada waxed old and was full of days when he died an hundred and thirty years old was he when he died');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 16, 'And they buried him in the city of David among the kings, because he had done good in Israel, both toward God, and toward his house.', 'and they buried him in the city of david among the kings because he had done good in israel both toward god and toward his house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 17, 'Now after the death of Jehoiada came the princes of Judah, and made obeisance to the king. Then the king hearkened unto them.', 'now after the death of jehoiada came the princes of judah and made obeisance to the king then the king hearkened unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 18, 'And they left the house of the LORD God of their fathers, and served groves and idols: and wrath came upon Judah and Jerusalem for this their trespass.', 'and they left the house of the lord god of their fathers and served groves and idols and wrath came upon judah and jerusalem for this their trespass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 19, 'Yet he sent prophets to them, to bring them again unto the LORD; and they testified against them: but they would not give ear.', 'yet he sent prophets to them to bring them again unto the lord and they testified against them but they would not give ear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 20, 'And the Spirit of God came upon Zechariah the son of Jehoiada the priest, which stood above the people, and said unto them, Thus saith God, Why transgress ye the commandments of the LORD, that ye cannot prosper? because ye have forsaken the LORD, he hath also forsaken you. {came...: Heb. clothed}', 'and the spirit of god came upon zechariah the son of jehoiada the priest which stood above the people and said unto them thus saith god why transgress ye the commandments of the lord that ye cannot prosper because ye have forsaken the lord he hath also forsaken you came heb clothed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 21, 'And they conspired against him, and stoned him with stones at the commandment of the king in the court of the house of the LORD.', 'and they conspired against him and stoned him with stones at the commandment of the king in the court of the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 22, 'Thus Joash the king remembered not the kindness which Jehoiada his father had done to him, but slew his son. And when he died, he said, The LORD look upon {it}, and require {it}.', 'thus joash the king remembered not the kindness which jehoiada his father had done to him but slew his son and when he died he said the lord look upon it and require it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 23, 'And it came to pass at the end of the year, {that} the host of Syria came up against him: and they came to Judah and Jerusalem, and destroyed all the princes of the people from among the people, and sent all the spoil of them unto the king of Damascus. {at the...: Heb. in the revolution of the year} {Damascus: Heb. Darmesek}', 'and it came to pass at the end of the year that the host of syria came up against him and they came to judah and jerusalem and destroyed all the princes of the people from among the people and sent all the spoil of them unto the king of damascus at the heb in the revolution of the year damascus heb darmesek');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 24, 'For the army of the Syrians came with a small company of men, and the LORD delivered a very great host into their hand, because they had forsaken the LORD God of their fathers. So they executed judgment against Joash.', 'for the army of the syrians came with a small company of men and the lord delivered a very great host into their hand because they had forsaken the lord god of their fathers so they executed judgment against joash');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 25, 'And when they were departed from him, (for they left him in great diseases,) his own servants conspired against him for the blood of the sons of Jehoiada the priest, and slew him on his bed, and he died: and they buried him in the city of David, but they buried him not in the sepulchres of the kings.', 'and when they were departed from him for they left him in great diseases his own servants conspired against him for the blood of the sons of jehoiada the priest and slew him on his bed and he died and they buried him in the city of david but they buried him not in the sepulchres of the kings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 26, 'And these are they that conspired against him; Zabad the son of Shimeath an Ammonitess, and Jehozabad the son of Shimrith a Moabitess. {Zabad: or, Jozacher} {Shimrith: or, Shomer}', 'and these are they that conspired against him zabad the son of shimeath an ammonitess and jehozabad the son of shimrith a moabitess zabad or jozacher shimrith or shomer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 24, 27, 'Now {concerning} his sons, and the greatness of the burdens {laid} upon him, and the repairing of the house of God, behold, they {are} written in the story of the book of the kings. And Amaziah his son reigned in his stead. {repairing: Heb. founding} {story: or, commentary}', 'now concerning his sons and the greatness of the burdens laid upon him and the repairing of the house of god behold they are written in the story of the book of the kings and amaziah his son reigned in his stead repairing heb founding story or commentary');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 1, 'Amaziah {was} twenty and five years old {when} he began to reign, and he reigned twenty and nine years in Jerusalem. And his mother''s name {was} Jehoaddan of Jerusalem.', 'amaziah was twenty and five years old when he began to reign and he reigned twenty and nine years in jerusalem and his mother s name was jehoaddan of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 2, 'And he did {that which was} right in the sight of the LORD, but not with a perfect heart.', 'and he did that which was right in the sight of the lord but not with a perfect heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 3, 'Now it came to pass, when the kingdom was established to him, that he slew his servants that had killed the king his father. {established...: Heb. confirmed upon him}', 'now it came to pass when the kingdom was established to him that he slew his servants that had killed the king his father established heb confirmed upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 4, 'But he slew not their children, but {did} as {it is} written in the law in the book of Moses, where the LORD commanded, saying, The fathers shall not die for the children, neither shall the children die for the fathers, but every man shall die for his own sin.', 'but he slew not their children but did as it is written in the law in the book of moses where the lord commanded saying the fathers shall not die for the children neither shall the children die for the fathers but every man shall die for his own sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 5, 'Moreover Amaziah gathered Judah together, and made them captains over thousands, and captains over hundreds, according to the houses of {their} fathers, throughout all Judah and Benjamin: and he numbered them from twenty years old and above, and found them three hundred thousand choice {men, able} to go forth to war, that could handle spear and shield.', 'moreover amaziah gathered judah together and made them captains over thousands and captains over hundreds according to the houses of their fathers throughout all judah and benjamin and he numbered them from twenty years old and above and found them three hundred thousand choice men able to go forth to war that could handle spear and shield');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 6, 'He hired also an hundred thousand mighty men of valour out of Israel for an hundred talents of silver.', 'he hired also an hundred thousand mighty men of valour out of israel for an hundred talents of silver');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 7, 'But there came a man of God to him, saying, O king, let not the army of Israel go with thee; for the LORD {is} not with Israel, {to wit, with} all the children of Ephraim.', 'but there came a man of god to him saying o king let not the army of israel go with thee for the lord is not with israel to wit with all the children of ephraim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 8, 'But if thou wilt go, do {it}, be strong for the battle: God shall make thee fall before the enemy: for God hath power to help, and to cast down.', 'but if thou wilt go do it be strong for the battle god shall make thee fall before the enemy for god hath power to help and to cast down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 9, 'And Amaziah said to the man of God, But what shall we do for the hundred talents which I have given to the army of Israel? And the man of God answered, The LORD is able to give thee much more than this. {army: Heb. band}', 'and amaziah said to the man of god but what shall we do for the hundred talents which i have given to the army of israel and the man of god answered the lord is able to give thee much more than this army heb band');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 10, 'Then Amaziah separated them, {to wit}, the army that was come to him out of Ephraim, to go home again: wherefore their anger was greatly kindled against Judah, and they returned home in great anger. {home again: Heb. to their place} {in great...: Heb. in heat of anger}', 'then amaziah separated them to wit the army that was come to him out of ephraim to go home again wherefore their anger was greatly kindled against judah and they returned home in great anger home again heb to their place in great heb in heat of anger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 11, 'And Amaziah strengthened himself, and led forth his people, and went to the valley of salt, and smote of the children of Seir ten thousand.', 'and amaziah strengthened himself and led forth his people and went to the valley of salt and smote of the children of seir ten thousand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 12, 'And {other} ten thousand {left} alive did the children of Judah carry away captive, and brought them unto the top of the rock, and cast them down from the top of the rock, that they all were broken in pieces.', 'and other ten thousand left alive did the children of judah carry away captive and brought them unto the top of the rock and cast them down from the top of the rock that they all were broken in pieces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 13, 'But the soldiers of the army which Amaziah sent back, that they should not go with him to battle, fell upon the cities of Judah, from Samaria even unto Bethhoron, and smote three thousand of them, and took much spoil. {the soldiers...: Heb. the sons of the band}', 'but the soldiers of the army which amaziah sent back that they should not go with him to battle fell upon the cities of judah from samaria even unto bethhoron and smote three thousand of them and took much spoil the soldiers heb the sons of the band');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 14, 'Now it came to pass, after that Amaziah was come from the slaughter of the Edomites, that he brought the gods of the children of Seir, and set them up {to be} his gods, and bowed down himself before them, and burned incense unto them.', 'now it came to pass after that amaziah was come from the slaughter of the edomites that he brought the gods of the children of seir and set them up to be his gods and bowed down himself before them and burned incense unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 15, 'Wherefore the anger of the LORD was kindled against Amaziah, and he sent unto him a prophet, which said unto him, Why hast thou sought after the gods of the people, which could not deliver their own people out of thine hand?', 'wherefore the anger of the lord was kindled against amaziah and he sent unto him a prophet which said unto him why hast thou sought after the gods of the people which could not deliver their own people out of thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 16, 'And it came to pass, as he talked with him, that {the king} said unto him, Art thou made of the king''s counsel? forbear; why shouldest thou be smitten? Then the prophet forbare, and said, I know that God hath determined to destroy thee, because thou hast done this, and hast not hearkened unto my counsel. {determined: Heb. counselled}', 'and it came to pass as he talked with him that the king said unto him art thou made of the king s counsel forbear why shouldest thou be smitten then the prophet forbare and said i know that god hath determined to destroy thee because thou hast done this and hast not hearkened unto my counsel determined heb counselled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 17, 'Then Amaziah king of Judah took advice, and sent to Joash, the son of Jehoahaz, the son of Jehu, king of Israel, saying, Come, let us see one another in the face.', 'then amaziah king of judah took advice and sent to joash the son of jehoahaz the son of jehu king of israel saying come let us see one another in the face');
