INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 19, 'Thou sayest, Lo, thou hast smitten the Edomites; and thine heart lifteth thee up to boast: abide now at home; why shouldest thou meddle to {thine} hurt, that thou shouldest fall, {even} thou, and Judah with thee?', 'thou sayest lo thou hast smitten the edomites and thine heart lifteth thee up to boast abide now at home why shouldest thou meddle to thine hurt that thou shouldest fall even thou and judah with thee');
