INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 21, 'So Joash the king of Israel went up; and they saw one another in the face, {both} he and Amaziah king of Judah, at Bethshemesh, which {belongeth} to Judah.', 'so joash the king of israel went up and they saw one another in the face both he and amaziah king of judah at bethshemesh which belongeth to judah');
