INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 25, 'And Amaziah the son of Joash king of Judah lived after the death of Joash son of Jehoahaz king of Israel fifteen years.', 'and amaziah the son of joash king of judah lived after the death of joash son of jehoahaz king of israel fifteen years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 26, 'Now the rest of the acts of Amaziah, first and last, behold, {are} they not written in the book of the kings of Judah and Israel?', 'now the rest of the acts of amaziah first and last behold are they not written in the book of the kings of judah and israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 27, 'Now after the time that Amaziah did turn away from following the LORD they made a conspiracy against him in Jerusalem; and he fled to Lachish: but they sent to Lachish after him, and slew him there. {from...: Heb. from after} {made...: Heb. conspired a conspiracy}', 'now after the time that amaziah did turn away from following the lord they made a conspiracy against him in jerusalem and he fled to lachish but they sent to lachish after him and slew him there from heb from after made heb conspired a conspiracy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 25, 28, 'And they brought him upon horses, and buried him with his fathers in the city of Judah. {Judah: that is, the city of David}', 'and they brought him upon horses and buried him with his fathers in the city of judah judah that is the city of david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 1, 'Then all the people of Judah took Uzziah, who {was} sixteen years old, and made him king in the room of his father Amaziah. {Uzziah: or, Azariah}', 'then all the people of judah took uzziah who was sixteen years old and made him king in the room of his father amaziah uzziah or azariah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 2, 'He built Eloth, and restored it to Judah, after that the king slept with his fathers.', 'he built eloth and restored it to judah after that the king slept with his fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 3, 'Sixteen years old {was} Uzziah when he began to reign, and he reigned fifty and two years in Jerusalem. His mother''s name also {was} Jecoliah of Jerusalem.', 'sixteen years old was uzziah when he began to reign and he reigned fifty and two years in jerusalem his mother s name also was jecoliah of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 4, 'And he did {that which was} right in the sight of the LORD, according to all that his father Amaziah did.', 'and he did that which was right in the sight of the lord according to all that his father amaziah did');
