INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 15, 'And he made in Jerusalem engines, invented by cunning men, to be on the towers and upon the bulwarks, to shoot arrows and great stones withal. And his name spread far abroad; for he was marvellously helped, till he was strong. {spread: Heb. went forth}', 'and he made in jerusalem engines invented by cunning men to be on the towers and upon the bulwarks to shoot arrows and great stones withal and his name spread far abroad for he was marvellously helped till he was strong spread heb went forth');
