INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 17, 'And Azariah the priest went in after him, and with him fourscore priests of the LORD, {that were} valiant men:', 'and azariah the priest went in after him and with him fourscore priests of the lord that were valiant men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 18, 'And they withstood Uzziah the king, and said unto him, {It appertaineth} not unto thee, Uzziah, to burn incense unto the LORD, but to the priests the sons of Aaron, that are consecrated to burn incense: go out of the sanctuary; for thou hast trespassed; neither {shall it be} for thine honour from the LORD God.', 'and they withstood uzziah the king and said unto him it appertaineth not unto thee uzziah to burn incense unto the lord but to the priests the sons of aaron that are consecrated to burn incense go out of the sanctuary for thou hast trespassed neither shall it be for thine honour from the lord god');
