INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 22, 'Now the rest of the acts of Uzziah, first and last, did Isaiah the prophet, the son of Amoz, write.', 'now the rest of the acts of uzziah first and last did isaiah the prophet the son of amoz write');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 26, 23, 'So Uzziah slept with his fathers, and they buried him with his fathers in the field of the burial which {belonged} to the kings; for they said, He {is} a leper: and Jotham his son reigned in his stead.', 'so uzziah slept with his fathers and they buried him with his fathers in the field of the burial which belonged to the kings for they said he is a leper and jotham his son reigned in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 1, 'Jotham {was} twenty and five years old when he began to reign, and he reigned sixteen years in Jerusalem. His mother''s name also {was} Jerushah, the daughter of Zadok.', 'jotham was twenty and five years old when he began to reign and he reigned sixteen years in jerusalem his mother s name also was jerushah the daughter of zadok');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 2, 'And he did {that which was} right in the sight of the LORD, according to all that his father Uzziah did: howbeit he entered not into the temple of the LORD. And the people did yet corruptly.', 'and he did that which was right in the sight of the lord according to all that his father uzziah did howbeit he entered not into the temple of the lord and the people did yet corruptly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 3, 'He built the high gate of the house of the LORD, and on the wall of Ophel he built much. {Ophel: or, the tower}', 'he built the high gate of the house of the lord and on the wall of ophel he built much ophel or the tower');
