INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 5, 'He fought also with the king of the Ammonites, and prevailed against them. And the children of Ammon gave him the same year an hundred talents of silver, and ten thousand measures of wheat, and ten thousand of barley. So much did the children of Ammon pay unto him, both the second year, and the third. {So...: Heb. This}', 'he fought also with the king of the ammonites and prevailed against them and the children of ammon gave him the same year an hundred talents of silver and ten thousand measures of wheat and ten thousand of barley so much did the children of ammon pay unto him both the second year and the third so heb this');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 6, 'So Jotham became mighty, because he prepared his ways before the LORD his God. {prepared: or, established}', 'so jotham became mighty because he prepared his ways before the lord his god prepared or established');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 7, 'Now the rest of the acts of Jotham, and all his wars, and his ways, lo, they {are} written in the book of the kings of Israel and Judah.', 'now the rest of the acts of jotham and all his wars and his ways lo they are written in the book of the kings of israel and judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 8, 'He was five and twenty years old when he began to reign, and reigned sixteen years in Jerusalem.', 'he was five and twenty years old when he began to reign and reigned sixteen years in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 27, 9, 'And Jotham slept with his fathers, and they buried him in the city of David: and Ahaz his son reigned in his stead.', 'and jotham slept with his fathers and they buried him in the city of david and ahaz his son reigned in his stead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 28, 1, 'Ahaz {was} twenty years old when he began to reign, and he reigned sixteen years in Jerusalem: but he did not {that which was} right in the sight of the LORD, like David his father:', 'ahaz was twenty years old when he began to reign and he reigned sixteen years in jerusalem but he did not that which was right in the sight of the lord like david his father');
