INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 31, 14, 'And Kore the son of Imnah the Levite, the porter toward the east, {was} over the freewill offerings of God, to distribute the oblations of the LORD, and the most holy things.', 'and kore the son of imnah the levite the porter toward the east was over the freewill offerings of god to distribute the oblations of the lord and the most holy things');
