INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 31, 16, 'Beside their genealogy of males, from three years old and upward, {even} unto every one that entereth into the house of the LORD, his daily portion for their service in their charges according to their courses;', 'beside their genealogy of males from three years old and upward even unto every one that entereth into the house of the lord his daily portion for their service in their charges according to their courses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 31, 17, 'Both to the genealogy of the priests by the house of their fathers, and the Levites from twenty years old and upward, in their charges by their courses;', 'both to the genealogy of the priests by the house of their fathers and the levites from twenty years old and upward in their charges by their courses');
