INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 7, 'And Josiah gave to the people, of the flock, lambs and kids, all for the passover offerings, for all that were present, to the number of thirty thousand, and three thousand bullocks: these {were} of the king''s substance. {gave: Heb. offered}', 'and josiah gave to the people of the flock lambs and kids all for the passover offerings for all that were present to the number of thirty thousand and three thousand bullocks these were of the king s substance gave heb offered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 8, 'And his princes gave willingly unto the people, to the priests, and to the Levites: Hilkiah and Zechariah and Jehiel, rulers of the house of God, gave unto the priests for the passover offerings two thousand and six hundred {small cattle}, and three hundred oxen. {gave willingly: Heb. offered, etc}', 'and his princes gave willingly unto the people to the priests and to the levites hilkiah and zechariah and jehiel rulers of the house of god gave unto the priests for the passover offerings two thousand and six hundred small cattle and three hundred oxen gave willingly heb offered etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 9, 'Conaniah also, and Shemaiah and Nethaneel, his brethren, and Hashabiah and Jeiel and Jozabad, chief of the Levites, gave unto the Levites for passover offerings five thousand {small cattle}, and five hundred oxen. {gave: Heb. offered}', 'conaniah also and shemaiah and nethaneel his brethren and hashabiah and jeiel and jozabad chief of the levites gave unto the levites for passover offerings five thousand small cattle and five hundred oxen gave heb offered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 10, 'So the service was prepared, and the priests stood in their place, and the Levites in their courses, according to the king''s commandment.', 'so the service was prepared and the priests stood in their place and the levites in their courses according to the king s commandment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 11, 'And they killed the passover, and the priests sprinkled {the blood} from their hands, and the Levites flayed {them}.', 'and they killed the passover and the priests sprinkled the blood from their hands and the levites flayed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 12, 'And they removed the burnt offerings, that they might give according to the divisions of the families of the people, to offer unto the LORD, as {it is} written in the book of Moses. And so {did they} with the oxen.', 'and they removed the burnt offerings that they might give according to the divisions of the families of the people to offer unto the lord as it is written in the book of moses and so did they with the oxen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 13, 'And they roasted the passover with fire according to the ordinance: but the {other} holy {offerings} sod they in pots, and in caldrons, and in pans, and divided {them} speedily among all the people. {divided...: Heb. made them run}', 'and they roasted the passover with fire according to the ordinance but the other holy offerings sod they in pots and in caldrons and in pans and divided them speedily among all the people divided heb made them run');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 14, 'And afterward they made ready for themselves, and for the priests: because the priests the sons of Aaron {were busied} in offering of burnt offerings and the fat until night; therefore the Levites prepared for themselves, and for the priests the sons of Aaron.', 'and afterward they made ready for themselves and for the priests because the priests the sons of aaron were busied in offering of burnt offerings and the fat until night therefore the levites prepared for themselves and for the priests the sons of aaron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 15, 'And the singers the sons of Asaph {were} in their place, according to the commandment of David, and Asaph, and Heman, and Jeduthun the king''s seer; and the porters {waited} at every gate; they might not depart from their service; for their brethren the Levites prepared for them. {place: Heb. station}', 'and the singers the sons of asaph were in their place according to the commandment of david and asaph and heman and jeduthun the king s seer and the porters waited at every gate they might not depart from their service for their brethren the levites prepared for them place heb station');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 16, 'So all the service of the LORD was prepared the same day, to keep the passover, and to offer burnt offerings upon the altar of the LORD, according to the commandment of king Josiah.', 'so all the service of the lord was prepared the same day to keep the passover and to offer burnt offerings upon the altar of the lord according to the commandment of king josiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 17, 'And the children of Israel that were present kept the passover at that time, and the feast of unleavened bread seven days. {present: Heb. found}', 'and the children of israel that were present kept the passover at that time and the feast of unleavened bread seven days present heb found');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 18, 'And there was no passover like to that kept in Israel from the days of Samuel the prophet; neither did all the kings of Israel keep such a passover as Josiah kept, and the priests, and the Levites, and all Judah and Israel that were present, and the inhabitants of Jerusalem. {present: Heb. found}', 'and there was no passover like to that kept in israel from the days of samuel the prophet neither did all the kings of israel keep such a passover as josiah kept and the priests and the levites and all judah and israel that were present and the inhabitants of jerusalem present heb found');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 19, 'In the eighteenth year of the reign of Josiah was this passover kept.', 'in the eighteenth year of the reign of josiah was this passover kept');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 20, 'After all this, when Josiah had prepared the temple, Necho king of Egypt came up to fight against Carchemish by Euphrates: and Josiah went out against him. {temple: Heb. house}', 'after all this when josiah had prepared the temple necho king of egypt came up to fight against carchemish by euphrates and josiah went out against him temple heb house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 21, 'But he sent ambassadors to him, saying, What have I to do with thee, thou king of Judah? {I come} not against thee this day, but against the house wherewith I have war: for God commanded me to make haste: forbear thee from {meddling with} God, who {is} with me, that he destroy thee not. {the house...: Heb. the house of my war}', 'but he sent ambassadors to him saying what have i to do with thee thou king of judah i come not against thee this day but against the house wherewith i have war for god commanded me to make haste forbear thee from meddling with god who is with me that he destroy thee not the house heb the house of my war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 22, 'Nevertheless Josiah would not turn his face from him, but disguised himself, that he might fight with him, and hearkened not unto the words of Necho from the mouth of God, and came to fight in the valley of Megiddo.', 'nevertheless josiah would not turn his face from him but disguised himself that he might fight with him and hearkened not unto the words of necho from the mouth of god and came to fight in the valley of megiddo');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 23, 'And the archers shot at king Josiah; and the king said to his servants, Have me away; for I am sore wounded. {wounded: Heb. made sick}', 'and the archers shot at king josiah and the king said to his servants have me away for i am sore wounded wounded heb made sick');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 24, 'His servants therefore took him out of that chariot, and put him in the second chariot that he had; and they brought him to Jerusalem, and he died, and was buried in {one of} the sepulchres of his fathers. And all Judah and Jerusalem mourned for Josiah. {in one...: or, among the sepulchres}', 'his servants therefore took him out of that chariot and put him in the second chariot that he had and they brought him to jerusalem and he died and was buried in one of the sepulchres of his fathers and all judah and jerusalem mourned for josiah in one or among the sepulchres');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 25, 'And Jeremiah lamented for Josiah: and all the singing men and the singing women spake of Josiah in their lamentations to this day, and made them an ordinance in Israel: and, behold, they {are} written in the lamentations.', 'and jeremiah lamented for josiah and all the singing men and the singing women spake of josiah in their lamentations to this day and made them an ordinance in israel and behold they are written in the lamentations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 26, 'Now the rest of the acts of Josiah, and his goodness, according to {that which was} written in the law of the LORD, {goodness: Heb. kindnesses}', 'now the rest of the acts of josiah and his goodness according to that which was written in the law of the lord goodness heb kindnesses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 35, 27, 'And his deeds, first and last, behold, they {are} written in the book of the kings of Israel and Judah.', 'and his deeds first and last behold they are written in the book of the kings of israel and judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 1, 'Then the people of the land took Jehoahaz the son of Josiah, and made him king in his father''s stead in Jerusalem.', 'then the people of the land took jehoahaz the son of josiah and made him king in his father s stead in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 2, 'Jehoahaz {was} twenty and three years old when he began to reign, and he reigned three months in Jerusalem.', 'jehoahaz was twenty and three years old when he began to reign and he reigned three months in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 3, 'And the king of Egypt put him down at Jerusalem, and condemned the land in an hundred talents of silver and a talent of gold. {put...: Heb. removed him}', 'and the king of egypt put him down at jerusalem and condemned the land in an hundred talents of silver and a talent of gold put heb removed him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 4, 'And the king of Egypt made Eliakim his brother king over Judah and Jerusalem, and turned his name to Jehoiakim. And Necho took Jehoahaz his brother, and carried him to Egypt.', 'and the king of egypt made eliakim his brother king over judah and jerusalem and turned his name to jehoiakim and necho took jehoahaz his brother and carried him to egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 5, 'Jehoiakim {was} twenty and five years old when he began to reign, and he reigned eleven years in Jerusalem: and he did {that which was} evil in the sight of the LORD his God.', 'jehoiakim was twenty and five years old when he began to reign and he reigned eleven years in jerusalem and he did that which was evil in the sight of the lord his god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 6, 'Against him came up Nebuchadnezzar king of Babylon, and bound him in fetters, to carry him to Babylon. {fetters: or, chains}', 'against him came up nebuchadnezzar king of babylon and bound him in fetters to carry him to babylon fetters or chains');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 7, 'Nebuchadnezzar also carried of the vessels of the house of the LORD to Babylon, and put them in his temple at Babylon.', 'nebuchadnezzar also carried of the vessels of the house of the lord to babylon and put them in his temple at babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 8, 'Now the rest of the acts of Jehoiakim, and his abominations which he did, and that which was found in him, behold, they {are} written in the book of the kings of Israel and Judah: and Jehoiachin his son reigned in his stead. {Jehoiachin: also called, Jeconiah, or, Coniah}', 'now the rest of the acts of jehoiakim and his abominations which he did and that which was found in him behold they are written in the book of the kings of israel and judah and jehoiachin his son reigned in his stead jehoiachin also called jeconiah or coniah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 9, 'Jehoiachin {was} eight years old when he began to reign, and he reigned three months and ten days in Jerusalem: and he did {that which was} evil in the sight of the LORD.', 'jehoiachin was eight years old when he began to reign and he reigned three months and ten days in jerusalem and he did that which was evil in the sight of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 10, 'And when the year was expired, king Nebuchadnezzar sent, and brought him to Babylon, with the goodly vessels of the house of the LORD, and made Zedekiah his brother king over Judah and Jerusalem. {when...: Heb. at the return of the year} {goodly...: Heb. vessels of desire} {Zedekiah...: or, Mattaniah, his father''s brother}', 'and when the year was expired king nebuchadnezzar sent and brought him to babylon with the goodly vessels of the house of the lord and made zedekiah his brother king over judah and jerusalem when heb at the return of the year goodly heb vessels of desire zedekiah or mattaniah his father s brother');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 11, 'Zedekiah {was} one and twenty years old when he began to reign, and reigned eleven years in Jerusalem.', 'zedekiah was one and twenty years old when he began to reign and reigned eleven years in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 12, 'And he did {that which was} evil in the sight of the LORD his God, {and} humbled not himself before Jeremiah the prophet {speaking} from the mouth of the LORD.', 'and he did that which was evil in the sight of the lord his god and humbled not himself before jeremiah the prophet speaking from the mouth of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 13, 'And he also rebelled against king Nebuchadnezzar, who had made him swear by God: but he stiffened his neck, and hardened his heart from turning unto the LORD God of Israel.', 'and he also rebelled against king nebuchadnezzar who had made him swear by god but he stiffened his neck and hardened his heart from turning unto the lord god of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 14, 'Moreover all the chief of the priests, and the people, transgressed very much after all the abominations of the heathen; and polluted the house of the LORD which he had hallowed in Jerusalem.', 'moreover all the chief of the priests and the people transgressed very much after all the abominations of the heathen and polluted the house of the lord which he had hallowed in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 15, 'And the LORD God of their fathers sent to them by his messengers, rising up betimes, and sending; because he had compassion on his people, and on his dwelling place: {by: Heb. by the hand of} {betimes: that is, continually and carefully}', 'and the lord god of their fathers sent to them by his messengers rising up betimes and sending because he had compassion on his people and on his dwelling place by heb by the hand of betimes that is continually and carefully');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 16, 'But they mocked the messengers of God, and despised his words, and misused his prophets, until the wrath of the LORD arose against his people, till {there was} no remedy. {remedy: Heb. healing}', 'but they mocked the messengers of god and despised his words and misused his prophets until the wrath of the lord arose against his people till there was no remedy remedy heb healing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 17, 'Therefore he brought upon them the king of the Chaldees, who slew their young men with the sword in the house of their sanctuary, and had no compassion upon young man or maiden, old man, or him that stooped for age: he gave {them} all into his hand.', 'therefore he brought upon them the king of the chaldees who slew their young men with the sword in the house of their sanctuary and had no compassion upon young man or maiden old man or him that stooped for age he gave them all into his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 18, 'And all the vessels of the house of God, great and small, and the treasures of the house of the LORD, and the treasures of the king, and of his princes; all {these} he brought to Babylon.', 'and all the vessels of the house of god great and small and the treasures of the house of the lord and the treasures of the king and of his princes all these he brought to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 19, 'And they burnt the house of God, and brake down the wall of Jerusalem, and burnt all the palaces thereof with fire, and destroyed all the goodly vessels thereof.', 'and they burnt the house of god and brake down the wall of jerusalem and burnt all the palaces thereof with fire and destroyed all the goodly vessels thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 20, 'And them that had escaped from the sword carried he away to Babylon; where they were servants to him and his sons until the reign of the kingdom of Persia: {them...: Heb. the remainder from the sword}', 'and them that had escaped from the sword carried he away to babylon where they were servants to him and his sons until the reign of the kingdom of persia them heb the remainder from the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 21, 'To fulfil the word of the LORD by the mouth of Jeremiah, until the land had enjoyed her sabbaths: {for} as long as she lay desolate she kept sabbath, to fulfil threescore and ten years.', 'to fulfil the word of the lord by the mouth of jeremiah until the land had enjoyed her sabbaths for as long as she lay desolate she kept sabbath to fulfil threescore and ten years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 22, 'Now in the first year of Cyrus king of Persia, that the word of the LORD {spoken} by the mouth of Jeremiah might be accomplished, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and {put it} also in writing, saying,', 'now in the first year of cyrus king of persia that the word of the lord spoken by the mouth of jeremiah might be accomplished the lord stirred up the spirit of cyrus king of persia that he made a proclamation throughout all his kingdom and put it also in writing saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 14, 'Unknown', 36, 23, 'Thus saith Cyrus king of Persia, All the kingdoms of the earth hath the LORD God of heaven given me; and he hath charged me to build him an house in Jerusalem, which {is} in Judah. Who {is there} among you of all his people? The LORD his God {be} with him, and let him go up.', 'thus saith cyrus king of persia all the kingdoms of the earth hath the lord god of heaven given me and he hath charged me to build him an house in jerusalem which is in judah who is there among you of all his people the lord his god be with him and let him go up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 1, 'Now in the first year of Cyrus king of Persia, that the word of the LORD by the mouth of Jeremiah might be fulfilled, the LORD stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and {put it} also in writing, saying, {made...: Heb. caused a voice to pass}', 'now in the first year of cyrus king of persia that the word of the lord by the mouth of jeremiah might be fulfilled the lord stirred up the spirit of cyrus king of persia that he made a proclamation throughout all his kingdom and put it also in writing saying made heb caused a voice to pass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 2, 'Thus saith Cyrus king of Persia, The LORD God of heaven hath given me all the kingdoms of the earth; and he hath charged me to build him an house at Jerusalem, which {is} in Judah.', 'thus saith cyrus king of persia the lord god of heaven hath given me all the kingdoms of the earth and he hath charged me to build him an house at jerusalem which is in judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 3, 'Who {is there} among you of all his people? his God be with him, and let him go up to Jerusalem, which {is} in Judah, and build the house of the LORD God of Israel, (he {is} the God,) which {is} in Jerusalem.', 'who is there among you of all his people his god be with him and let him go up to jerusalem which is in judah and build the house of the lord god of israel he is the god which is in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 4, 'And whosoever remaineth in any place where he sojourneth, let the men of his place help him with silver, and with gold, and with goods, and with beasts, beside the freewill offering for the house of God that {is} in Jerusalem. {help...: Heb. lift him up}', 'and whosoever remaineth in any place where he sojourneth let the men of his place help him with silver and with gold and with goods and with beasts beside the freewill offering for the house of god that is in jerusalem help heb lift him up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 5, 'Then rose up the chief of the fathers of Judah and Benjamin, and the priests, and the Levites, with all {them} whose spirit God had raised, to go up to build the house of the LORD which {is} in Jerusalem.', 'then rose up the chief of the fathers of judah and benjamin and the priests and the levites with all them whose spirit god had raised to go up to build the house of the lord which is in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 6, 'And all they that {were} about them strengthened their hands with vessels of silver, with gold, with goods, and with beasts, and with precious things, beside all {that} was willingly offered. {strengthened...: that is, helped them}', 'and all they that were about them strengthened their hands with vessels of silver with gold with goods and with beasts and with precious things beside all that was willingly offered strengthened that is helped them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 7, 'Also Cyrus the king brought forth the vessels of the house of the LORD, which Nebuchadnezzar had brought forth out of Jerusalem, and had put them in the house of his gods;', 'also cyrus the king brought forth the vessels of the house of the lord which nebuchadnezzar had brought forth out of jerusalem and had put them in the house of his gods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 8, 'Even those did Cyrus king of Persia bring forth by the hand of Mithredath the treasurer, and numbered them unto Sheshbazzar, the prince of Judah.', 'even those did cyrus king of persia bring forth by the hand of mithredath the treasurer and numbered them unto sheshbazzar the prince of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 9, 'And this {is} the number of them: thirty chargers of gold, a thousand chargers of silver, nine and twenty knives,', 'and this is the number of them thirty chargers of gold a thousand chargers of silver nine and twenty knives');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 10, 'Thirty basons of gold, silver basons of a second {sort} four hundred and ten, {and} other vessels a thousand.', 'thirty basons of gold silver basons of a second sort four hundred and ten and other vessels a thousand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 1, 11, 'All the vessels of gold and of silver {were} five thousand and four hundred. All {these} did Sheshbazzar bring up with {them of} the captivity that were brought up from Babylon unto Jerusalem. {the captivity: Heb. the transportation}', 'all the vessels of gold and of silver were five thousand and four hundred all these did sheshbazzar bring up with them of the captivity that were brought up from babylon unto jerusalem the captivity heb the transportation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 2, 1, 'Now these {are} the children of the province that went up out of the captivity, of those which had been carried away, whom Nebuchadnezzar the king of Babylon had carried away unto Babylon, and came again unto Jerusalem and Judah, every one unto his city;', 'now these are the children of the province that went up out of the captivity of those which had been carried away whom nebuchadnezzar the king of babylon had carried away unto babylon and came again unto jerusalem and judah every one unto his city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 2, 2, 'Which came with Zerubbabel: Jeshua, Nehemiah, Seraiah, Reelaiah, Mordecai, Bilshan, Mispar, Bigvai, Rehum, Baanah. The number of the men of the people of Israel: {Seraiah: also called, Azariah} {Reelaiah: or, Raamiah} {Mispar: or, Mispereth} {Rehum: or, Nehum}', 'which came with zerubbabel jeshua nehemiah seraiah reelaiah mordecai bilshan mispar bigvai rehum baanah the number of the men of the people of israel seraiah also called azariah reelaiah or raamiah mispar or mispereth rehum or nehum');
