INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 2, 62, 'These sought their register {among} those that were reckoned by genealogy, but they were not found: therefore were they, as polluted, put from the priesthood. {were they...: Heb. they were polluted from the priesthood}', 'these sought their register among those that were reckoned by genealogy but they were not found therefore were they as polluted put from the priesthood were they heb they were polluted from the priesthood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 2, 63, 'And the Tirshatha said unto them, that they should not eat of the most holy things, till there stood up a priest with Urim and with Thummim. {Tirshatha: or, governor}', 'and the tirshatha said unto them that they should not eat of the most holy things till there stood up a priest with urim and with thummim tirshatha or governor');
