INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 5, 'The son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest:', 'the son of abishua the son of phinehas the son of eleazar the son of aaron the chief priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 6, 'This Ezra went up from Babylon; and he {was} a ready scribe in the law of Moses, which the LORD God of Israel had given: and the king granted him all his request, according to the hand of the LORD his God upon him.', 'this ezra went up from babylon and he was a ready scribe in the law of moses which the lord god of israel had given and the king granted him all his request according to the hand of the lord his god upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 7, 'And there went up {some} of the children of Israel, and of the priests, and the Levites, and the singers, and the porters, and the Nethinims, unto Jerusalem, in the seventh year of Artaxerxes the king.', 'and there went up some of the children of israel and of the priests and the levites and the singers and the porters and the nethinims unto jerusalem in the seventh year of artaxerxes the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 8, 'And he came to Jerusalem in the fifth month, which {was} in the seventh year of the king.', 'and he came to jerusalem in the fifth month which was in the seventh year of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 9, 'For upon the first {day} of the first month began he to go up from Babylon, and on the first {day} of the fifth month came he to Jerusalem, according to the good hand of his God upon him. {began...: Heb. was the foundation of the going up}', 'for upon the first day of the first month began he to go up from babylon and on the first day of the fifth month came he to jerusalem according to the good hand of his god upon him began heb was the foundation of the going up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 10, 'For Ezra had prepared his heart to seek the law of the LORD, and to do {it}, and to teach in Israel statutes and judgments.', 'for ezra had prepared his heart to seek the law of the lord and to do it and to teach in israel statutes and judgments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 11, 'Now this {is} the copy of the letter that the king Artaxerxes gave unto Ezra the priest, the scribe, {even} a scribe of the words of the commandments of the LORD, and of his statutes to Israel.', 'now this is the copy of the letter that the king artaxerxes gave unto ezra the priest the scribe even a scribe of the words of the commandments of the lord and of his statutes to israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 12, 'Artaxerxes, king of kings, unto Ezra the priest, a scribe of the law of the God of heaven, perfect {peace}, and at such a time. {unto...: or, to Ezra the priest, a perfect scribe of the law of the God of heaven, peace, etc}', 'artaxerxes king of kings unto ezra the priest a scribe of the law of the god of heaven perfect peace and at such a time unto or to ezra the priest a perfect scribe of the law of the god of heaven peace etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 13, 'I make a decree, that all they of the people of Israel, and {of} his priests and Levites, in my realm, which are minded of their own freewill to go up to Jerusalem, go with thee.', 'i make a decree that all they of the people of israel and of his priests and levites in my realm which are minded of their own freewill to go up to jerusalem go with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 14, 'Forasmuch as thou art sent of the king, and of his seven counsellors, to enquire concerning Judah and Jerusalem, according to the law of thy God which {is} in thine hand; {of the king: Chaldee, from before the king}', 'forasmuch as thou art sent of the king and of his seven counsellors to enquire concerning judah and jerusalem according to the law of thy god which is in thine hand of the king chaldee from before the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 15, 'And to carry the silver and gold, which the king and his counsellors have freely offered unto the God of Israel, whose habitation {is} in Jerusalem,', 'and to carry the silver and gold which the king and his counsellors have freely offered unto the god of israel whose habitation is in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 16, 'And all the silver and gold that thou canst find in all the province of Babylon, with the freewill offering of the people, and of the priests, offering willingly for the house of their God which {is} in Jerusalem:', 'and all the silver and gold that thou canst find in all the province of babylon with the freewill offering of the people and of the priests offering willingly for the house of their god which is in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 17, 'That thou mayest buy speedily with this money bullocks, rams, lambs, with their meat offerings and their drink offerings, and offer them upon the altar of the house of your God which {is} in Jerusalem.', 'that thou mayest buy speedily with this money bullocks rams lambs with their meat offerings and their drink offerings and offer them upon the altar of the house of your god which is in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 18, 'And whatsoever shall seem good to thee, and to thy brethren, to do with the rest of the silver and the gold, that do after the will of your God.', 'and whatsoever shall seem good to thee and to thy brethren to do with the rest of the silver and the gold that do after the will of your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 19, 'The vessels also that are given thee for the service of the house of thy God, {those} deliver thou before the God of Jerusalem.', 'the vessels also that are given thee for the service of the house of thy god those deliver thou before the god of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 20, 'And whatsoever more shall be needful for the house of thy God, which thou shalt have occasion to bestow, bestow {it} out of the king''s treasure house.', 'and whatsoever more shall be needful for the house of thy god which thou shalt have occasion to bestow bestow it out of the king s treasure house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 21, 'And I, {even} I Artaxerxes the king, do make a decree to all the treasurers which {are} beyond the river, that whatsoever Ezra the priest, the scribe of the law of the God of heaven, shall require of you, it be done speedily,', 'and i even i artaxerxes the king do make a decree to all the treasurers which are beyond the river that whatsoever ezra the priest the scribe of the law of the god of heaven shall require of you it be done speedily');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 22, 'Unto an hundred talents of silver, and to an hundred measures of wheat, and to an hundred baths of wine, and to an hundred baths of oil, and salt without prescribing {how much}. {measures: Chaldee, cors}', 'unto an hundred talents of silver and to an hundred measures of wheat and to an hundred baths of wine and to an hundred baths of oil and salt without prescribing how much measures chaldee cors');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 23, 'Whatsoever is commanded by the God of heaven, let it be diligently done for the house of the God of heaven: for why should there be wrath against the realm of the king and his sons? {Whatsoever...: Chaldee, Whatsoever is of the decree}', 'whatsoever is commanded by the god of heaven let it be diligently done for the house of the god of heaven for why should there be wrath against the realm of the king and his sons whatsoever chaldee whatsoever is of the decree');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 24, 'Also we certify you, that touching any of the priests and Levites, singers, porters, Nethinims, or ministers of this house of God, it shall not be lawful to impose toll, tribute, or custom, upon them.', 'also we certify you that touching any of the priests and levites singers porters nethinims or ministers of this house of god it shall not be lawful to impose toll tribute or custom upon them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 25, 'And thou, Ezra, after the wisdom of thy God, that {is} in thine hand, set magistrates and judges, which may judge all the people that {are} beyond the river, all such as know the laws of thy God; and teach ye them that know {them} not.', 'and thou ezra after the wisdom of thy god that is in thine hand set magistrates and judges which may judge all the people that are beyond the river all such as know the laws of thy god and teach ye them that know them not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 26, 'And whosoever will not do the law of thy God, and the law of the king, let judgment be executed speedily upon him, whether {it be} unto death, or to banishment, or to confiscation of goods, or to imprisonment. {to banishment: Chaldee, to rooting out}', 'and whosoever will not do the law of thy god and the law of the king let judgment be executed speedily upon him whether it be unto death or to banishment or to confiscation of goods or to imprisonment to banishment chaldee to rooting out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 27, 'Blessed {be} the LORD God of our fathers, which hath put {such a thing} as this in the king''s heart, to beautify the house of the LORD which {is} in Jerusalem:', 'blessed be the lord god of our fathers which hath put such a thing as this in the king s heart to beautify the house of the lord which is in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 7, 28, 'And hath extended mercy unto me before the king, and his counsellors, and before all the king''s mighty princes. And I was strengthened as the hand of the LORD my God {was} upon me, and I gathered together out of Israel chief men to go up with me.', 'and hath extended mercy unto me before the king and his counsellors and before all the king s mighty princes and i was strengthened as the hand of the lord my god was upon me and i gathered together out of israel chief men to go up with me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 8, 1, 'These {are} now the chief of their fathers, and {this is} the genealogy of them that went up with me from Babylon, in the reign of Artaxerxes the king.', 'these are now the chief of their fathers and this is the genealogy of them that went up with me from babylon in the reign of artaxerxes the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 8, 2, 'Of the sons of Phinehas; Gershom: of the sons of Ithamar; Daniel: of the sons of David; Hattush.', 'of the sons of phinehas gershom of the sons of ithamar daniel of the sons of david hattush');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 8, 3, 'Of the sons of Shechaniah, of the sons of Pharosh; Zechariah: and with him were reckoned by genealogy of the males an hundred and fifty.', 'of the sons of shechaniah of the sons of pharosh zechariah and with him were reckoned by genealogy of the males an hundred and fifty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 8, 4, 'Of the sons of Pahathmoab; Elihoenai the son of Zerahiah, and with him two hundred males.', 'of the sons of pahathmoab elihoenai the son of zerahiah and with him two hundred males');
