INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 8, 6, 'Of the sons also of Adin; Ebed the son of Jonathan, and with him fifty males.', 'of the sons also of adin ebed the son of jonathan and with him fifty males');
