INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 8, 12, 'And of the sons of Azgad; Johanan the son of Hakkatan, and with him an hundred and ten males. {the son...: or, the youngest son}', 'and of the sons of azgad johanan the son of hakkatan and with him an hundred and ten males the son or the youngest son');
