INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 15, 'Unknown', 10, 14, 'Let now our rulers of all the congregation stand, and let all them which have taken strange wives in our cities come at appointed times, and with them the elders of every city, and the judges thereof, until the fierce wrath of our God for this matter be turned from us. {for this...: or, till this matter be dispatched}', 'let now our rulers of all the congregation stand and let all them which have taken strange wives in our cities come at appointed times and with them the elders of every city and the judges thereof until the fierce wrath of our god for this matter be turned from us for this or till this matter be dispatched');
