INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 2, 'That Hanani, one of my brethren, came, he and {certain} men of Judah; and I asked them concerning the Jews that had escaped, which were left of the captivity, and concerning Jerusalem.', 'that hanani one of my brethren came he and certain men of judah and i asked them concerning the jews that had escaped which were left of the captivity and concerning jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 3, 'And they said unto me, The remnant that are left of the captivity there in the province {are} in great affliction and reproach: the wall of Jerusalem also {is} broken down, and the gates thereof are burned with fire.', 'and they said unto me the remnant that are left of the captivity there in the province are in great affliction and reproach the wall of jerusalem also is broken down and the gates thereof are burned with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 4, 'And it came to pass, when I heard these words, that I sat down and wept, and mourned {certain} days, and fasted, and prayed before the God of heaven,', 'and it came to pass when i heard these words that i sat down and wept and mourned certain days and fasted and prayed before the god of heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 5, 'And said, I beseech thee, O LORD God of heaven, the great and terrible God, that keepeth covenant and mercy for them that love him and observe his commandments:', 'and said i beseech thee o lord god of heaven the great and terrible god that keepeth covenant and mercy for them that love him and observe his commandments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 6, 'Let thine ear now be attentive, and thine eyes open, that thou mayest hear the prayer of thy servant, which I pray before thee now, day and night, for the children of Israel thy servants, and confess the sins of the children of Israel, which we have sinned against thee: both I and my father''s house have sinned.', 'let thine ear now be attentive and thine eyes open that thou mayest hear the prayer of thy servant which i pray before thee now day and night for the children of israel thy servants and confess the sins of the children of israel which we have sinned against thee both i and my father s house have sinned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 7, 'We have dealt very corruptly against thee, and have not kept the commandments, nor the statutes, nor the judgments, which thou commandedst thy servant Moses.', 'we have dealt very corruptly against thee and have not kept the commandments nor the statutes nor the judgments which thou commandedst thy servant moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 8, 'Remember, I beseech thee, the word that thou commandedst thy servant Moses, saying, {If} ye transgress, I will scatter you abroad among the nations:', 'remember i beseech thee the word that thou commandedst thy servant moses saying if ye transgress i will scatter you abroad among the nations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 9, 'But {if} ye turn unto me, and keep my commandments, and do them; though there were of you cast out unto the uttermost part of the heaven, {yet} will I gather them from thence, and will bring them unto the place that I have chosen to set my name there.', 'but if ye turn unto me and keep my commandments and do them though there were of you cast out unto the uttermost part of the heaven yet will i gather them from thence and will bring them unto the place that i have chosen to set my name there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 10, 'Now these {are} thy servants and thy people, whom thou hast redeemed by thy great power, and by thy strong hand.', 'now these are thy servants and thy people whom thou hast redeemed by thy great power and by thy strong hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 1, 11, 'O Lord, I beseech thee, let now thine ear be attentive to the prayer of thy servant, and to the prayer of thy servants, who desire to fear thy name: and prosper, I pray thee, thy servant this day, and grant him mercy in the sight of this man. For I was the king''s cupbearer.', 'o lord i beseech thee let now thine ear be attentive to the prayer of thy servant and to the prayer of thy servants who desire to fear thy name and prosper i pray thee thy servant this day and grant him mercy in the sight of this man for i was the king s cupbearer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 1, 'And it came to pass in the month Nisan, in the twentieth year of Artaxerxes the king, {that} wine {was} before him: and I took up the wine, and gave {it} unto the king. Now I had not been {beforetime} sad in his presence.', 'and it came to pass in the month nisan in the twentieth year of artaxerxes the king that wine was before him and i took up the wine and gave it unto the king now i had not been beforetime sad in his presence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 2, 'Wherefore the king said unto me, Why {is} thy countenance sad, seeing thou {art} not sick? this {is} nothing {else} but sorrow of heart. Then I was very sore afraid,', 'wherefore the king said unto me why is thy countenance sad seeing thou art not sick this is nothing else but sorrow of heart then i was very sore afraid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 3, 'And said unto the king, Let the king live for ever: why should not my countenance be sad, when the city, the place of my fathers'' sepulchres, {lieth} waste, and the gates thereof are consumed with fire?', 'and said unto the king let the king live for ever why should not my countenance be sad when the city the place of my fathers sepulchres lieth waste and the gates thereof are consumed with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 4, 'Then the king said unto me, For what dost thou make request? So I prayed to the God of heaven.', 'then the king said unto me for what dost thou make request so i prayed to the god of heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 5, 'And I said unto the king, If it please the king, and if thy servant have found favour in thy sight, that thou wouldest send me unto Judah, unto the city of my fathers'' sepulchres, that I may build it.', 'and i said unto the king if it please the king and if thy servant have found favour in thy sight that thou wouldest send me unto judah unto the city of my fathers sepulchres that i may build it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 6, 'And the king said unto me, (the queen also sitting by him,) For how long shall thy journey be? and when wilt thou return? So it pleased the king to send me; and I set him a time. {queen: Heb. wife}', 'and the king said unto me the queen also sitting by him for how long shall thy journey be and when wilt thou return so it pleased the king to send me and i set him a time queen heb wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 7, 'Moreover I said unto the king, If it please the king, let letters be given me to the governors beyond the river, that they may convey me over till I come into Judah;', 'moreover i said unto the king if it please the king let letters be given me to the governors beyond the river that they may convey me over till i come into judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 8, 'And a letter unto Asaph the keeper of the king''s forest, that he may give me timber to make beams for the gates of the palace which {appertained} to the house, and for the wall of the city, and for the house that I shall enter into. And the king granted me, according to the good hand of my God upon me.', 'and a letter unto asaph the keeper of the king s forest that he may give me timber to make beams for the gates of the palace which appertained to the house and for the wall of the city and for the house that i shall enter into and the king granted me according to the good hand of my god upon me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 9, 'Then I came to the governors beyond the river, and gave them the king''s letters. Now the king had sent captains of the army and horsemen with me.', 'then i came to the governors beyond the river and gave them the king s letters now the king had sent captains of the army and horsemen with me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 10, 'When Sanballat the Horonite, and Tobiah the servant, the Ammonite, heard {of it}, it grieved them exceedingly that there was come a man to seek the welfare of the children of Israel.', 'when sanballat the horonite and tobiah the servant the ammonite heard of it it grieved them exceedingly that there was come a man to seek the welfare of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 11, 'So I came to Jerusalem, and was there three days.', 'so i came to jerusalem and was there three days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 12, 'And I arose in the night, I and some few men with me; neither told I {any} man what my God had put in my heart to do at Jerusalem: neither {was there any} beast with me, save the beast that I rode upon.', 'and i arose in the night i and some few men with me neither told i any man what my god had put in my heart to do at jerusalem neither was there any beast with me save the beast that i rode upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 13, 'And I went out by night by the gate of the valley, even before the dragon well, and to the dung port, and viewed the walls of Jerusalem, which were broken down, and the gates thereof were consumed with fire.', 'and i went out by night by the gate of the valley even before the dragon well and to the dung port and viewed the walls of jerusalem which were broken down and the gates thereof were consumed with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 14, 'Then I went on to the gate of the fountain, and to the king''s pool: but {there was} no place for the beast {that was} under me to pass.', 'then i went on to the gate of the fountain and to the king s pool but there was no place for the beast that was under me to pass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 15, 'Then went I up in the night by the brook, and viewed the wall, and turned back, and entered by the gate of the valley, and {so} returned.', 'then went i up in the night by the brook and viewed the wall and turned back and entered by the gate of the valley and so returned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 16, 'And the rulers knew not whither I went, or what I did; neither had I as yet told {it} to the Jews, nor to the priests, nor to the nobles, nor to the rulers, nor to the rest that did the work.', 'and the rulers knew not whither i went or what i did neither had i as yet told it to the jews nor to the priests nor to the nobles nor to the rulers nor to the rest that did the work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 17, 'Then said I unto them, Ye see the distress that we {are} in, how Jerusalem {lieth} waste, and the gates thereof are burned with fire: come, and let us build up the wall of Jerusalem, that we be no more a reproach.', 'then said i unto them ye see the distress that we are in how jerusalem lieth waste and the gates thereof are burned with fire come and let us build up the wall of jerusalem that we be no more a reproach');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 18, 'Then I told them of the hand of my God which was good upon me; as also the king''s words that he had spoken unto me. And they said, Let us rise up and build. So they strengthened their hands for {this} good {work}.', 'then i told them of the hand of my god which was good upon me as also the king s words that he had spoken unto me and they said let us rise up and build so they strengthened their hands for this good work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 19, 'But when Sanballat the Horonite, and Tobiah the servant, the Ammonite, and Geshem the Arabian, heard {it}, they laughed us to scorn, and despised us, and said, What {is} this thing that ye do? will ye rebel against the king?', 'but when sanballat the horonite and tobiah the servant the ammonite and geshem the arabian heard it they laughed us to scorn and despised us and said what is this thing that ye do will ye rebel against the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 2, 20, 'Then answered I them, and said unto them, The God of heaven, he will prosper us; therefore we his servants will arise and build: but ye have no portion, nor right, nor memorial, in Jerusalem.', 'then answered i them and said unto them the god of heaven he will prosper us therefore we his servants will arise and build but ye have no portion nor right nor memorial in jerusalem');
