INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 2, 'And next unto him builded the men of Jericho. And next to them builded Zaccur the son of Imri. {next unto...: Heb. at his hand}', 'and next unto him builded the men of jericho and next to them builded zaccur the son of imri next unto heb at his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 3, 'But the fish gate did the sons of Hassenaah build, who {also} laid the beams thereof, and set up the doors thereof, the locks thereof, and the bars thereof.', 'but the fish gate did the sons of hassenaah build who also laid the beams thereof and set up the doors thereof the locks thereof and the bars thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 4, 'And next unto them repaired Meremoth the son of Urijah, the son of Koz. And next unto them repaired Meshullam the son of Berechiah, the son of Meshezabeel. And next unto them repaired Zadok the son of Baana.', 'and next unto them repaired meremoth the son of urijah the son of koz and next unto them repaired meshullam the son of berechiah the son of meshezabeel and next unto them repaired zadok the son of baana');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 5, 'And next unto them the Tekoites repaired; but their nobles put not their necks to the work of their Lord.', 'and next unto them the tekoites repaired but their nobles put not their necks to the work of their lord');
