INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 7, 'And next unto them repaired Melatiah the Gibeonite, and Jadon the Meronothite, the men of Gibeon, and of Mizpah, unto the throne of the governor on this side the river.', 'and next unto them repaired melatiah the gibeonite and jadon the meronothite the men of gibeon and of mizpah unto the throne of the governor on this side the river');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 8, 'Next unto him repaired Uzziel the son of Harhaiah, of the goldsmiths. Next unto him also repaired Hananiah the son of {one of} the apothecaries, and they fortified Jerusalem unto the broad wall. {fortified...: or, left Jerusalem unto the broad wall}', 'next unto him repaired uzziel the son of harhaiah of the goldsmiths next unto him also repaired hananiah the son of one of the apothecaries and they fortified jerusalem unto the broad wall fortified or left jerusalem unto the broad wall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 9, 'And next unto them repaired Rephaiah the son of Hur, the ruler of the half part of Jerusalem.', 'and next unto them repaired rephaiah the son of hur the ruler of the half part of jerusalem');
