INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 11, 'Malchijah the son of Harim, and Hashub the son of Pahathmoab, repaired the other piece, and the tower of the furnaces. {other...: Heb. second measure}', 'malchijah the son of harim and hashub the son of pahathmoab repaired the other piece and the tower of the furnaces other heb second measure');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 12, 'And next unto him repaired Shallum the son of Halohesh, the ruler of the half part of Jerusalem, he and his daughters.', 'and next unto him repaired shallum the son of halohesh the ruler of the half part of jerusalem he and his daughters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 13, 'The valley gate repaired Hanun, and the inhabitants of Zanoah; they built it, and set up the doors thereof, the locks thereof, and the bars thereof, and a thousand cubits on the wall unto the dung gate.', 'the valley gate repaired hanun and the inhabitants of zanoah they built it and set up the doors thereof the locks thereof and the bars thereof and a thousand cubits on the wall unto the dung gate');
