INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 15, 'But the gate of the fountain repaired Shallun the son of Colhozeh, the ruler of part of Mizpah; he built it, and covered it, and set up the doors thereof, the locks thereof, and the bars thereof, and the wall of the pool of Siloah by the king''s garden, and unto the stairs that go down from the city of David.', 'but the gate of the fountain repaired shallun the son of colhozeh the ruler of part of mizpah he built it and covered it and set up the doors thereof the locks thereof and the bars thereof and the wall of the pool of siloah by the king s garden and unto the stairs that go down from the city of david');
