INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 20, 'After him Baruch the son of Zabbai earnestly repaired the other piece, from the turning {of the wall} unto the door of the house of Eliashib the high priest. {Zabbai: also called, Zaccai}', 'after him baruch the son of zabbai earnestly repaired the other piece from the turning of the wall unto the door of the house of eliashib the high priest zabbai also called zaccai');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 21, 'After him repaired Meremoth the son of Urijah the son of Koz another piece, from the door of the house of Eliashib even to the end of the house of Eliashib.', 'after him repaired meremoth the son of urijah the son of koz another piece from the door of the house of eliashib even to the end of the house of eliashib');
