INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 25, 'Palal the son of Uzai, over against the turning {of the wall}, and the tower which lieth out from the king''s high house, that {was} by the court of the prison. After him Pedaiah the son of Parosh.', 'palal the son of uzai over against the turning of the wall and the tower which lieth out from the king s high house that was by the court of the prison after him pedaiah the son of parosh');
