INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 30, 'After him repaired Hananiah the son of Shelemiah, and Hanun the sixth son of Zalaph, another piece. After him repaired Meshullam the son of Berechiah over against his chamber.', 'after him repaired hananiah the son of shelemiah and hanun the sixth son of zalaph another piece after him repaired meshullam the son of berechiah over against his chamber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 3, 31, 'After him repaired Malchiah the goldsmith''s son unto the place of the Nethinims, and of the merchants, over against the gate Miphkad, and to the going up of the corner. {going...: or, corner chamber}', 'after him repaired malchiah the goldsmith s son unto the place of the nethinims and of the merchants over against the gate miphkad and to the going up of the corner going or corner chamber');
