INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 7, 64, 'These sought their register {among} those that were reckoned by genealogy, but it was not found: therefore were they, as polluted, put from the priesthood.', 'these sought their register among those that were reckoned by genealogy but it was not found therefore were they as polluted put from the priesthood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 7, 65, 'And the Tirshatha said unto them, that they should not eat of the most holy things, till there stood {up} a priest with Urim and Thummim. {the Tirshatha: or, the governor}', 'and the tirshatha said unto them that they should not eat of the most holy things till there stood up a priest with urim and thummim the tirshatha or the governor');
