INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 7, 67, 'Beside their manservants and their maidservants, of whom {there were} seven thousand three hundred thirty and seven: and they had two hundred forty and five singing men and singing women.', 'beside their manservants and their maidservants of whom there were seven thousand three hundred thirty and seven and they had two hundred forty and five singing men and singing women');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 7, 68, 'Their horses, seven hundred thirty and six: their mules, two hundred forty and five:', 'their horses seven hundred thirty and six their mules two hundred forty and five');
