INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 22, 'The Levites in the days of Eliashib, Joiada, and Johanan, and Jaddua, {were} recorded chief of the fathers: also the priests, to the reign of Darius the Persian.', 'the levites in the days of eliashib joiada and johanan and jaddua were recorded chief of the fathers also the priests to the reign of darius the persian');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 23, 'The sons of Levi, the chief of the fathers, {were} written in the book of the chronicles, even until the days of Johanan the son of Eliashib.', 'the sons of levi the chief of the fathers were written in the book of the chronicles even until the days of johanan the son of eliashib');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 24, 'And the chief of the Levites: Hashabiah, Sherebiah, and Jeshua the son of Kadmiel, with their brethren over against them, to praise {and} to give thanks, according to the commandment of David the man of God, ward over against ward.', 'and the chief of the levites hashabiah sherebiah and jeshua the son of kadmiel with their brethren over against them to praise and to give thanks according to the commandment of david the man of god ward over against ward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 25, 'Mattaniah, and Bakbukiah, Obadiah, Meshullam, Talmon, Akkub, {were} porters keeping the ward at the thresholds of the gates. {thresholds: or, treasuries, or, assemblies}', 'mattaniah and bakbukiah obadiah meshullam talmon akkub were porters keeping the ward at the thresholds of the gates thresholds or treasuries or assemblies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 26, 'These {were} in the days of Joiakim the son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor, and of Ezra the priest, the scribe.', 'these were in the days of joiakim the son of jeshua the son of jozadak and in the days of nehemiah the governor and of ezra the priest the scribe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 27, 'And at the dedication of the wall of Jerusalem they sought the Levites out of all their places, to bring them to Jerusalem, to keep the dedication with gladness, both with thanksgivings, and with singing, {with} cymbals, psalteries, and with harps.', 'and at the dedication of the wall of jerusalem they sought the levites out of all their places to bring them to jerusalem to keep the dedication with gladness both with thanksgivings and with singing with cymbals psalteries and with harps');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 28, 'And the sons of the singers gathered themselves together, both out of the plain country round about Jerusalem, and from the villages of Netophathi;', 'and the sons of the singers gathered themselves together both out of the plain country round about jerusalem and from the villages of netophathi');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 29, 'Also from the house of Gilgal, and out of the fields of Geba and Azmaveth: for the singers had builded them villages round about Jerusalem.', 'also from the house of gilgal and out of the fields of geba and azmaveth for the singers had builded them villages round about jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 30, 'And the priests and the Levites purified themselves, and purified the people, and the gates, and the wall.', 'and the priests and the levites purified themselves and purified the people and the gates and the wall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 31, 'Then I brought up the princes of Judah upon the wall, and appointed two great {companies of them that gave} thanks, {whereof one} went on the right hand upon the wall toward the dung gate:', 'then i brought up the princes of judah upon the wall and appointed two great companies of them that gave thanks whereof one went on the right hand upon the wall toward the dung gate');
