INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 35, 'And {certain} of the priests'' sons with trumpets; {namely}, Zechariah the son of Jonathan, the son of Shemaiah, the son of Mattaniah, the son of Michaiah, the son of Zaccur, the son of Asaph:', 'and certain of the priests sons with trumpets namely zechariah the son of jonathan the son of shemaiah the son of mattaniah the son of michaiah the son of zaccur the son of asaph');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 36, 'And his brethren, Shemaiah, and Azarael, Milalai, Gilalai, Maai, Nethaneel, and Judah, Hanani, with the musical instruments of David the man of God, and Ezra the scribe before them.', 'and his brethren shemaiah and azarael milalai gilalai maai nethaneel and judah hanani with the musical instruments of david the man of god and ezra the scribe before them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 37, 'And at the fountain gate, which was over against them, they went up by the stairs of the city of David, at the going up of the wall, above the house of David, even unto the water gate eastward.', 'and at the fountain gate which was over against them they went up by the stairs of the city of david at the going up of the wall above the house of david even unto the water gate eastward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 38, 'And the other {company of them that gave} thanks went over against {them}, and I after them, and the half of the people upon the wall, from beyond the tower of the furnaces even unto the broad wall;', 'and the other company of them that gave thanks went over against them and i after them and the half of the people upon the wall from beyond the tower of the furnaces even unto the broad wall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 39, 'And from above the gate of Ephraim, and above the old gate, and above the fish gate, and the tower of Hananeel, and the tower of Meah, even unto the sheep gate: and they stood still in the prison gate.', 'and from above the gate of ephraim and above the old gate and above the fish gate and the tower of hananeel and the tower of meah even unto the sheep gate and they stood still in the prison gate');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 40, 'So stood the two {companies of them that gave} thanks in the house of God, and I, and the half of the rulers with me:', 'so stood the two companies of them that gave thanks in the house of god and i and the half of the rulers with me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 41, 'And the priests; Eliakim, Maaseiah, Miniamin, Michaiah, Elioenai, Zechariah, {and} Hananiah, with trumpets;', 'and the priests eliakim maaseiah miniamin michaiah elioenai zechariah and hananiah with trumpets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 42, 'And Maaseiah, and Shemaiah, and Eleazar, and Uzzi, and Jehohanan, and Malchijah, and Elam, and Ezer. And the singers sang loud, with Jezrahiah {their} overseer. {sang...: Heb. made their voice to be heard}', 'and maaseiah and shemaiah and eleazar and uzzi and jehohanan and malchijah and elam and ezer and the singers sang loud with jezrahiah their overseer sang heb made their voice to be heard');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 43, 'Also that day they offered great sacrifices, and rejoiced: for God had made them rejoice with great joy: the wives also and the children rejoiced: so that the joy of Jerusalem was heard even afar off.', 'also that day they offered great sacrifices and rejoiced for god had made them rejoice with great joy the wives also and the children rejoiced so that the joy of jerusalem was heard even afar off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 44, 'And at that time were some appointed over the chambers for the treasures, for the offerings, for the firstfruits, and for the tithes, to gather into them out of the fields of the cities the portions of the law for the priests and Levites: for Judah rejoiced for the priests and for the Levites that waited. {of the law: that is, appointed by the law} {for Judah...: Heb. for the joy of Judah} {waited: Heb. stood}', 'and at that time were some appointed over the chambers for the treasures for the offerings for the firstfruits and for the tithes to gather into them out of the fields of the cities the portions of the law for the priests and levites for judah rejoiced for the priests and for the levites that waited of the law that is appointed by the law for judah heb for the joy of judah waited heb stood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 45, 'And both the singers and the porters kept the ward of their God, and the ward of the purification, according to the commandment of David, {and} of Solomon his son.', 'and both the singers and the porters kept the ward of their god and the ward of the purification according to the commandment of david and of solomon his son');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 46, 'For in the days of David and Asaph of old {there were} chief of the singers, and songs of praise and thanksgiving unto God.', 'for in the days of david and asaph of old there were chief of the singers and songs of praise and thanksgiving unto god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 12, 47, 'And all Israel in the days of Zerubbabel, and in the days of Nehemiah, gave the portions of the singers and the porters, every day his portion: and they sanctified {holy things} unto the Levites; and the Levites sanctified {them} unto the children of Aaron. {sanctified: that is, set apart}', 'and all israel in the days of zerubbabel and in the days of nehemiah gave the portions of the singers and the porters every day his portion and they sanctified holy things unto the levites and the levites sanctified them unto the children of aaron sanctified that is set apart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 1, 'On that day they read in the book of Moses in the audience of the people; and therein was found written, that the Ammonite and the Moabite should not come into the congregation of God for ever; {they...: Heb. there was read} {audience: Heb. ears}', 'on that day they read in the book of moses in the audience of the people and therein was found written that the ammonite and the moabite should not come into the congregation of god for ever they heb there was read audience heb ears');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 2, 'Because they met not the children of Israel with bread and with water, but hired Balaam against them, that he should curse them: howbeit our God turned the curse into a blessing.', 'because they met not the children of israel with bread and with water but hired balaam against them that he should curse them howbeit our god turned the curse into a blessing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 3, 'Now it came to pass, when they had heard the law, that they separated from Israel all the mixed multitude.', 'now it came to pass when they had heard the law that they separated from israel all the mixed multitude');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 4, 'And before this, Eliashib the priest, having the oversight of the chamber of the house of our God, {was} allied unto Tobiah: {having...: Heb. being set over}', 'and before this eliashib the priest having the oversight of the chamber of the house of our god was allied unto tobiah having heb being set over');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 5, 'And he had prepared for him a great chamber, where aforetime they laid the meat offerings, the frankincense, and the vessels, and the tithes of the corn, the new wine, and the oil, which was commanded {to be given} to the Levites, and the singers, and the porters; and the offerings of the priests. {which...: Heb. the commandment of the Levites}', 'and he had prepared for him a great chamber where aforetime they laid the meat offerings the frankincense and the vessels and the tithes of the corn the new wine and the oil which was commanded to be given to the levites and the singers and the porters and the offerings of the priests which heb the commandment of the levites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 6, 'But in all this {time} was not I at Jerusalem: for in the two and thirtieth year of Artaxerxes king of Babylon came I unto the king, and after certain days obtained I leave of the king: {after...: Heb. at the end of days} {obtained...: or, I earnestly requested}', 'but in all this time was not i at jerusalem for in the two and thirtieth year of artaxerxes king of babylon came i unto the king and after certain days obtained i leave of the king after heb at the end of days obtained or i earnestly requested');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 7, 'And I came to Jerusalem, and understood of the evil that Eliashib did for Tobiah, in preparing him a chamber in the courts of the house of God.', 'and i came to jerusalem and understood of the evil that eliashib did for tobiah in preparing him a chamber in the courts of the house of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 8, 'And it grieved me sore: therefore I cast forth all the household stuff of Tobiah out of the chamber.', 'and it grieved me sore therefore i cast forth all the household stuff of tobiah out of the chamber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 9, 'Then I commanded, and they cleansed the chambers: and thither brought I again the vessels of the house of God, with the meat offering and the frankincense.', 'then i commanded and they cleansed the chambers and thither brought i again the vessels of the house of god with the meat offering and the frankincense');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 10, 'And I perceived that the portions of the Levites had not been given {them}: for the Levites and the singers, that did the work, were fled every one to his field.', 'and i perceived that the portions of the levites had not been given them for the levites and the singers that did the work were fled every one to his field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 11, 'Then contended I with the rulers, and said, Why is the house of God forsaken? And I gathered them together, and set them in their place. {place: Heb. standing}', 'then contended i with the rulers and said why is the house of god forsaken and i gathered them together and set them in their place place heb standing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 16, 'Unknown', 13, 12, 'Then brought all Judah the tithe of the corn and the new wine and the oil unto the treasuries. {treasuries: or, storehouses}', 'then brought all judah the tithe of the corn and the new wine and the oil unto the treasuries treasuries or storehouses');
