INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 10, 'The ten sons of Haman the son of Hammedatha, the enemy of the Jews, slew they; but on the spoil laid they not their hand.', 'the ten sons of haman the son of hammedatha the enemy of the jews slew they but on the spoil laid they not their hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 11, 'On that day the number of those that were slain in Shushan the palace was brought before the king. {was...: Heb. came}', 'on that day the number of those that were slain in shushan the palace was brought before the king was heb came');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 12, 'And the king said unto Esther the queen, The Jews have slain and destroyed five hundred men in Shushan the palace, and the ten sons of Haman; what have they done in the rest of the king''s provinces? now what {is} thy petition? and it shall be granted thee: or what {is} thy request further? and it shall be done.', 'and the king said unto esther the queen the jews have slain and destroyed five hundred men in shushan the palace and the ten sons of haman what have they done in the rest of the king s provinces now what is thy petition and it shall be granted thee or what is thy request further and it shall be done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 13, 'Then said Esther, If it please the king, let it be granted to the Jews which {are} in Shushan to do to morrow also according unto this day''s decree, and let Haman''s ten sons be hanged upon the gallows. {let Haman''s...: Heb. let men hang, etc}', 'then said esther if it please the king let it be granted to the jews which are in shushan to do to morrow also according unto this day s decree and let haman s ten sons be hanged upon the gallows let haman s heb let men hang etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 14, 'And the king commanded it so to be done: and the decree was given at Shushan; and they hanged Haman''s ten sons.', 'and the king commanded it so to be done and the decree was given at shushan and they hanged haman s ten sons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 15, 'For the Jews that {were} in Shushan gathered themselves together on the fourteenth day also of the month Adar, and slew three hundred men at Shushan; but on the prey they laid not their hand.', 'for the jews that were in shushan gathered themselves together on the fourteenth day also of the month adar and slew three hundred men at shushan but on the prey they laid not their hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 16, 'But the other Jews that {were} in the king''s provinces gathered themselves together, and stood for their lives, and had rest from their enemies, and slew of their foes seventy and five thousand, but they laid not their hands on the prey,', 'but the other jews that were in the king s provinces gathered themselves together and stood for their lives and had rest from their enemies and slew of their foes seventy and five thousand but they laid not their hands on the prey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 17, 'On the thirteenth day of the month Adar; and on the fourteenth day of the same rested they, and made it a day of feasting and gladness. {of the same: Heb. in it}', 'on the thirteenth day of the month adar and on the fourteenth day of the same rested they and made it a day of feasting and gladness of the same heb in it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 18, 'But the Jews that {were} at Shushan assembled together on the thirteenth {day} thereof, and on the fourteenth thereof; and on the fifteenth {day} of the same they rested, and made it a day of feasting and gladness.', 'but the jews that were at shushan assembled together on the thirteenth day thereof and on the fourteenth thereof and on the fifteenth day of the same they rested and made it a day of feasting and gladness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 19, 'Therefore the Jews of the villages, that dwelt in the unwalled towns, made the fourteenth day of the month Adar {a day of} gladness and feasting, and a good day, and of sending portions one to another.', 'therefore the jews of the villages that dwelt in the unwalled towns made the fourteenth day of the month adar a day of gladness and feasting and a good day and of sending portions one to another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 20, 'And Mordecai wrote these things, and sent letters unto all the Jews that {were} in all the provinces of the king Ahasuerus, {both} nigh and far,', 'and mordecai wrote these things and sent letters unto all the jews that were in all the provinces of the king ahasuerus both nigh and far');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 21, 'To stablish {this} among them, that they should keep the fourteenth day of the month Adar, and the fifteenth day of the same, yearly,', 'to stablish this among them that they should keep the fourteenth day of the month adar and the fifteenth day of the same yearly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 22, 'As the days wherein the Jews rested from their enemies, and the month which was turned unto them from sorrow to joy, and from mourning into a good day: that they should make them days of feasting and joy, and of sending portions one to another, and gifts to the poor.', 'as the days wherein the jews rested from their enemies and the month which was turned unto them from sorrow to joy and from mourning into a good day that they should make them days of feasting and joy and of sending portions one to another and gifts to the poor');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 23, 'And the Jews undertook to do as they had begun, and as Mordecai had written unto them;', 'and the jews undertook to do as they had begun and as mordecai had written unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 24, 'Because Haman the son of Hammedatha, the Agagite, the enemy of all the Jews, had devised against the Jews to destroy them, and had cast Pur, that {is}, the lot, to consume them, and to destroy them; {consume: Heb. crush}', 'because haman the son of hammedatha the agagite the enemy of all the jews had devised against the jews to destroy them and had cast pur that is the lot to consume them and to destroy them consume heb crush');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 25, 'But when {Esther} came before the king, he commanded by letters that his wicked device, which he devised against the Jews, should return upon his own head, and that he and his sons should be hanged on the gallows. {when...: Heb. when she came}', 'but when esther came before the king he commanded by letters that his wicked device which he devised against the jews should return upon his own head and that he and his sons should be hanged on the gallows when heb when she came');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 26, 'Wherefore they called these days Purim after the name of Pur. Therefore for all the words of this letter, and {of that} which they had seen concerning this matter, and which had come unto them, {Pur: that is, Lot}', 'wherefore they called these days purim after the name of pur therefore for all the words of this letter and of that which they had seen concerning this matter and which had come unto them pur that is lot');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 27, 'The Jews ordained, and took upon them, and upon their seed, and upon all such as joined themselves unto them, so as it should not fail, that they would keep these two days according to their writing, and according to their {appointed} time every year; {fail: Heb. pass}', 'the jews ordained and took upon them and upon their seed and upon all such as joined themselves unto them so as it should not fail that they would keep these two days according to their writing and according to their appointed time every year fail heb pass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 28, 'And {that} these days {should be} remembered and kept throughout every generation, every family, every province, and every city; and {that} these days of Purim should not fail from among the Jews, nor the memorial of them perish from their seed. {fail: Heb. pass} {perish: Heb. be ended}', 'and that these days should be remembered and kept throughout every generation every family every province and every city and that these days of purim should not fail from among the jews nor the memorial of them perish from their seed fail heb pass perish heb be ended');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 29, 'Then Esther the queen, the daughter of Abihail, and Mordecai the Jew, wrote with all authority, to confirm this second letter of Purim. {authority: Heb. strength}', 'then esther the queen the daughter of abihail and mordecai the jew wrote with all authority to confirm this second letter of purim authority heb strength');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 9, 30, 'And he sent the letters unto all the Jews, to the hundred twenty and seven provinces of the kingdom of Ahasuerus, {with} words of peace and truth,', 'and he sent the letters unto all the jews to the hundred twenty and seven provinces of the kingdom of ahasuerus with words of peace and truth');
