INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 10, 1, 'And the king Ahasuerus laid a tribute upon the land, and {upon} the isles of the sea.', 'and the king ahasuerus laid a tribute upon the land and upon the isles of the sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 17, 'Unknown', 10, 2, 'And all the acts of his power and of his might, and the declaration of the greatness of Mordecai, whereunto the king advanced him, {are} they not written in the book of the chronicles of the kings of Media and Persia? {advanced...: Heb. made him great}', 'and all the acts of his power and of his might and the declaration of the greatness of mordecai whereunto the king advanced him are they not written in the book of the chronicles of the kings of media and persia advanced heb made him great');
