INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 18, 'Unknown', 1, 1, 'There was a man in the land of Uz, whose name {was} Job; and that man was perfect and upright, and one that feared God, and eschewed evil.', 'there was a man in the land of uz whose name was job and that man was perfect and upright and one that feared god and eschewed evil');
