INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 18, 'Unknown', 1, 7, 'And the LORD said unto Satan, Whence comest thou? Then Satan answered the LORD, and said, From going to and fro in the earth, and from walking up and down in it.', 'and the lord said unto satan whence comest thou then satan answered the lord and said from going to and fro in the earth and from walking up and down in it');
