INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 30, 15, 'For thus saith the Lord GOD, the Holy One of Israel; In returning and rest shall ye be saved; in quietness and in confidence shall be your strength: and ye would not.', 'for thus saith the lord god the holy one of israel in returning and rest shall ye be saved in quietness and in confidence shall be your strength and ye would not');
