INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 30, 17, 'One thousand {shall flee} at the rebuke of one; at the rebuke of five shall ye flee: till ye be left as a beacon upon the top of a mountain, and as an ensign on an hill. {a beacon: or, a tree bereft of branches, or, boughs: or, a mast}', 'one thousand shall flee at the rebuke of one at the rebuke of five shall ye flee till ye be left as a beacon upon the top of a mountain and as an ensign on an hill a beacon or a tree bereft of branches or boughs or a mast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 30, 18, 'And therefore will the LORD wait, that he may be gracious unto you, and therefore will he be exalted, that he may have mercy upon you: for the LORD {is} a God of judgment: blessed {are} all they that wait for him.', 'and therefore will the lord wait that he may be gracious unto you and therefore will he be exalted that he may have mercy upon you for the lord is a god of judgment blessed are all they that wait for him');
