INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 1, 'Now it came to pass in the fourteenth year of king Hezekiah, {that} Sennacherib king of Assyria came up against all the defenced cities of Judah, and took them.', 'now it came to pass in the fourteenth year of king hezekiah that sennacherib king of assyria came up against all the defenced cities of judah and took them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 2, 'And the king of Assyria sent Rabshakeh from Lachish to Jerusalem unto king Hezekiah with a great army. And he stood by the conduit of the upper pool in the highway of the fuller''s field.', 'and the king of assyria sent rabshakeh from lachish to jerusalem unto king hezekiah with a great army and he stood by the conduit of the upper pool in the highway of the fuller s field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 3, 'Then came forth unto him Eliakim, Hilkiah''s son, which was over the house, and Shebna the scribe, and Joah, Asaph''s son, the recorder. {scribe: or, secretary}', 'then came forth unto him eliakim hilkiah s son which was over the house and shebna the scribe and joah asaph s son the recorder scribe or secretary');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 4, 'And Rabshakeh said unto them, Say ye now to Hezekiah, Thus saith the great king, the king of Assyria, What confidence {is} this wherein thou trustest?', 'and rabshakeh said unto them say ye now to hezekiah thus saith the great king the king of assyria what confidence is this wherein thou trustest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 5, 'I say, {sayest thou}, (but {they are but} vain words) {I have} counsel and strength for war: now on whom dost thou trust, that thou rebellest against me? {vain...: Heb. a word of lips} {I have...: or, but counsel and strength are for the war}', 'i say sayest thou but they are but vain words i have counsel and strength for war now on whom dost thou trust that thou rebellest against me vain heb a word of lips i have or but counsel and strength are for the war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 6, 'Lo, thou trustest in the staff of this broken reed, on Egypt; whereon if a man lean, it will go into his hand, and pierce it: so {is} Pharaoh king of Egypt to all that trust in him.', 'lo thou trustest in the staff of this broken reed on egypt whereon if a man lean it will go into his hand and pierce it so is pharaoh king of egypt to all that trust in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 7, 'But if thou say to me, We trust in the LORD our God: {is it} not he, whose high places and whose altars Hezekiah hath taken away, and said to Judah and to Jerusalem, Ye shall worship before this altar?', 'but if thou say to me we trust in the lord our god is it not he whose high places and whose altars hezekiah hath taken away and said to judah and to jerusalem ye shall worship before this altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 8, 'Now therefore give pledges, I pray thee, to my master the king of Assyria, and I will give thee two thousand horses, if thou be able on thy part to set riders upon them. {pledges: or, hostages}', 'now therefore give pledges i pray thee to my master the king of assyria and i will give thee two thousand horses if thou be able on thy part to set riders upon them pledges or hostages');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 9, 'How then wilt thou turn away the face of one captain of the least of my master''s servants, and put thy trust on Egypt for chariots and for horsemen?', 'how then wilt thou turn away the face of one captain of the least of my master s servants and put thy trust on egypt for chariots and for horsemen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 10, 'And am I now come up without the LORD against this land to destroy it? the LORD said unto me, Go up against this land, and destroy it.', 'and am i now come up without the lord against this land to destroy it the lord said unto me go up against this land and destroy it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 11, 'Then said Eliakim and Shebna and Joah unto Rabshakeh, Speak, I pray thee, unto thy servants in the Syrian language; for we understand {it}: and speak not to us in the Jews'' language, in the ears of the people that {are} on the wall.', 'then said eliakim and shebna and joah unto rabshakeh speak i pray thee unto thy servants in the syrian language for we understand it and speak not to us in the jews language in the ears of the people that are on the wall');
