INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 13, 'Then Rabshakeh stood, and cried with a loud voice in the Jews'' language, and said, Hear ye the words of the great king, the king of Assyria.', 'then rabshakeh stood and cried with a loud voice in the jews language and said hear ye the words of the great king the king of assyria');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 14, 'Thus saith the king, Let not Hezekiah deceive you: for he shall not be able to deliver you.', 'thus saith the king let not hezekiah deceive you for he shall not be able to deliver you');
