INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 36, 16, 'Hearken not to Hezekiah: for thus saith the king of Assyria, Make {an agreement} with me {by} a present, and come out to me: and eat ye every one of his vine, and every one of his fig tree, and drink ye every one the waters of his own cistern; {Make...: or, Seek my favour by a present: Heb. Make with me a blessing}', 'hearken not to hezekiah for thus saith the king of assyria make an agreement with me by a present and come out to me and eat ye every one of his vine and every one of his fig tree and drink ye every one the waters of his own cistern make or seek my favour by a present heb make with me a blessing');
