INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 52, 7, 'How beautiful upon the mountains are the feet of him that bringeth good tidings, that publisheth peace; that bringeth good tidings of good, that publisheth salvation; that saith unto Zion, Thy God reigneth!', 'how beautiful upon the mountains are the feet of him that bringeth good tidings that publisheth peace that bringeth good tidings of good that publisheth salvation that saith unto zion thy god reigneth');
