INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 53, 2, 'For he shall grow up before him as a tender plant, and as a root out of a dry ground: he hath no form nor comeliness; and when we shall see him, {there is} no beauty that we should desire him.', 'for he shall grow up before him as a tender plant and as a root out of a dry ground he hath no form nor comeliness and when we shall see him there is no beauty that we should desire him');
