INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 54, 1, 'Sing, O barren, thou {that} didst not bear; break forth into singing, and cry aloud, thou {that} didst not travail with child: for more {are} the children of the desolate than the children of the married wife, saith the LORD.', 'sing o barren thou that didst not bear break forth into singing and cry aloud thou that didst not travail with child for more are the children of the desolate than the children of the married wife saith the lord');
