INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 54, 5, 'For thy Maker {is} thine husband; the LORD of hosts {is} his name; and thy Redeemer the Holy One of Israel; The God of the whole earth shall he be called. {Maker: Heb. Makers}', 'for thy maker is thine husband the lord of hosts is his name and thy redeemer the holy one of israel the god of the whole earth shall he be called maker heb makers');
