INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 54, 9, 'For this {is as} the waters of Noah unto me: for {as} I have sworn that the waters of Noah should no more go over the earth; so have I sworn that I would not be wroth with thee, nor rebuke thee.', 'for this is as the waters of noah unto me for as i have sworn that the waters of noah should no more go over the earth so have i sworn that i would not be wroth with thee nor rebuke thee');
