INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 60, 14, 'The sons also of them that afflicted thee shall come bending unto thee; and all they that despised thee shall bow themselves down at the soles of thy feet; and they shall call thee, The city of the LORD, The Zion of the Holy One of Israel.', 'the sons also of them that afflicted thee shall come bending unto thee and all they that despised thee shall bow themselves down at the soles of thy feet and they shall call thee the city of the lord the zion of the holy one of israel');
