INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 60, 17, 'For brass I will bring gold, and for iron I will bring silver, and for wood brass, and for stones iron: I will also make thy officers peace, and thine exactors righteousness.', 'for brass i will bring gold and for iron i will bring silver and for wood brass and for stones iron i will also make thy officers peace and thine exactors righteousness');
