INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 61, 7, 'For your shame {ye shall have} double; and {for} confusion they shall rejoice in their portion: therefore in their land they shall possess the double: everlasting joy shall be unto them.', 'for your shame ye shall have double and for confusion they shall rejoice in their portion therefore in their land they shall possess the double everlasting joy shall be unto them');
