INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 23, 'Unknown', 61, 11, 'For as the earth bringeth forth her bud, and as the garden causeth the things that are sown in it to spring forth; so the Lord GOD will cause righteousness and praise to spring forth before all the nations.', 'for as the earth bringeth forth her bud and as the garden causeth the things that are sown in it to spring forth so the lord god will cause righteousness and praise to spring forth before all the nations');
