INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 7, 20, 'Therefore thus saith the Lord GOD; Behold, mine anger and my fury shall be poured out upon this place, upon man, and upon beast, and upon the trees of the field, and upon the fruit of the ground; and it shall burn, and shall not be quenched.', 'therefore thus saith the lord god behold mine anger and my fury shall be poured out upon this place upon man and upon beast and upon the trees of the field and upon the fruit of the ground and it shall burn and shall not be quenched');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 7, 21, 'Thus saith the LORD of hosts, the God of Israel; Put your burnt offerings unto your sacrifices, and eat flesh.', 'thus saith the lord of hosts the god of israel put your burnt offerings unto your sacrifices and eat flesh');
