INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 7, 25, 'Since the day that your fathers came forth out of the land of Egypt unto this day I have even sent unto you all my servants the prophets, daily rising up early and sending {them}:', 'since the day that your fathers came forth out of the land of egypt unto this day i have even sent unto you all my servants the prophets daily rising up early and sending them');
