INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 15, 'Behold, they say unto me, Where {is} the word of the LORD? let it come now.', 'behold they say unto me where is the word of the lord let it come now');
