INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 19, 'Thus said the LORD unto me; Go and stand in the gate of the children of the people, whereby the kings of Judah come in, and by the which they go out, and in all the gates of Jerusalem;', 'thus said the lord unto me go and stand in the gate of the children of the people whereby the kings of judah come in and by the which they go out and in all the gates of jerusalem');
