INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 21, 'Thus saith the LORD; Take heed to yourselves, and bear no burden on the sabbath day, nor bring {it} in by the gates of Jerusalem;', 'thus saith the lord take heed to yourselves and bear no burden on the sabbath day nor bring it in by the gates of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 22, 'Neither carry forth a burden out of your houses on the sabbath day, neither do ye any work, but hallow ye the sabbath day, as I commanded your fathers.', 'neither carry forth a burden out of your houses on the sabbath day neither do ye any work but hallow ye the sabbath day as i commanded your fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 23, 'But they obeyed not, neither inclined their ear, but made their neck stiff, that they might not hear, nor receive instruction.', 'but they obeyed not neither inclined their ear but made their neck stiff that they might not hear nor receive instruction');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 24, 'And it shall come to pass, if ye diligently hearken unto me, saith the LORD, to bring in no burden through the gates of this city on the sabbath day, but hallow the sabbath day, to do no work therein;', 'and it shall come to pass if ye diligently hearken unto me saith the lord to bring in no burden through the gates of this city on the sabbath day but hallow the sabbath day to do no work therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 25, 'Then shall there enter into the gates of this city kings and princes sitting upon the throne of David, riding in chariots and on horses, they, and their princes, the men of Judah, and the inhabitants of Jerusalem: and this city shall remain for ever.', 'then shall there enter into the gates of this city kings and princes sitting upon the throne of david riding in chariots and on horses they and their princes the men of judah and the inhabitants of jerusalem and this city shall remain for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 26, 'And they shall come from the cities of Judah, and from the places about Jerusalem, and from the land of Benjamin, and from the plain, and from the mountains, and from the south, bringing burnt offerings, and sacrifices, and meat offerings, and incense, and bringing sacrifices of praise, unto the house of the LORD.', 'and they shall come from the cities of judah and from the places about jerusalem and from the land of benjamin and from the plain and from the mountains and from the south bringing burnt offerings and sacrifices and meat offerings and incense and bringing sacrifices of praise unto the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 17, 27, 'But if ye will not hearken unto me to hallow the sabbath day, and not to bear a burden, even entering in at the gates of Jerusalem on the sabbath day; then will I kindle a fire in the gates thereof, and it shall devour the palaces of Jerusalem, and it shall not be quenched.', 'but if ye will not hearken unto me to hallow the sabbath day and not to bear a burden even entering in at the gates of jerusalem on the sabbath day then will i kindle a fire in the gates thereof and it shall devour the palaces of jerusalem and it shall not be quenched');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 18, 1, 'The word which came to Jeremiah from the LORD, saying,', 'the word which came to jeremiah from the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 18, 2, 'Arise, and go down to the potter''s house, and there I will cause thee to hear my words.', 'arise and go down to the potter s house and there i will cause thee to hear my words');
