INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 1, 'Woe be unto the pastors that destroy and scatter the sheep of my pasture! saith the LORD.', 'woe be unto the pastors that destroy and scatter the sheep of my pasture saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 2, 'Therefore thus saith the LORD God of Israel against the pastors that feed my people; Ye have scattered my flock, and driven them away, and have not visited them: behold, I will visit upon you the evil of your doings, saith the LORD.', 'therefore thus saith the lord god of israel against the pastors that feed my people ye have scattered my flock and driven them away and have not visited them behold i will visit upon you the evil of your doings saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 3, 'And I will gather the remnant of my flock out of all countries whither I have driven them, and will bring them again to their folds; and they shall be fruitful and increase.', 'and i will gather the remnant of my flock out of all countries whither i have driven them and will bring them again to their folds and they shall be fruitful and increase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 4, 'And I will set up shepherds over them which shall feed them: and they shall fear no more, nor be dismayed, neither shall they be lacking, saith the LORD.', 'and i will set up shepherds over them which shall feed them and they shall fear no more nor be dismayed neither shall they be lacking saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 5, 'Behold, the days come, saith the LORD, that I will raise unto David a righteous Branch, and a King shall reign and prosper, and shall execute judgment and justice in the earth.', 'behold the days come saith the lord that i will raise unto david a righteous branch and a king shall reign and prosper and shall execute judgment and justice in the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 6, 'In his days Judah shall be saved, and Israel shall dwell safely: and this {is} his name whereby he shall be called, THE LORD OUR RIGHTEOUSNESS. {THE LORD...: Heb. Jehovahtsidkenu}', 'in his days judah shall be saved and israel shall dwell safely and this is his name whereby he shall be called the lord our righteousness the lord heb jehovahtsidkenu');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 7, 'Therefore, behold, the days come, saith the LORD, that they shall no more say, The LORD liveth, which brought up the children of Israel out of the land of Egypt;', 'therefore behold the days come saith the lord that they shall no more say the lord liveth which brought up the children of israel out of the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 8, 'But, The LORD liveth, which brought up and which led the seed of the house of Israel out of the north country, and from all countries whither I had driven them; and they shall dwell in their own land.', 'but the lord liveth which brought up and which led the seed of the house of israel out of the north country and from all countries whither i had driven them and they shall dwell in their own land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 9, 'Mine heart within me is broken because of the prophets; all my bones shake; I am like a drunken man, and like a man whom wine hath overcome, because of the LORD, and because of the words of his holiness.', 'mine heart within me is broken because of the prophets all my bones shake i am like a drunken man and like a man whom wine hath overcome because of the lord and because of the words of his holiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 10, 'For the land is full of adulterers; for because of swearing the land mourneth; the pleasant places of the wilderness are dried up, and their course is evil, and their force {is} not right. {swearing: or, cursing} {course: or, violence}', 'for the land is full of adulterers for because of swearing the land mourneth the pleasant places of the wilderness are dried up and their course is evil and their force is not right swearing or cursing course or violence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 11, 'For both prophet and priest are profane; yea, in my house have I found their wickedness, saith the LORD.', 'for both prophet and priest are profane yea in my house have i found their wickedness saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 12, 'Wherefore their way shall be unto them as slippery {ways} in the darkness: they shall be driven on, and fall therein: for I will bring evil upon them, {even} the year of their visitation, saith the LORD.', 'wherefore their way shall be unto them as slippery ways in the darkness they shall be driven on and fall therein for i will bring evil upon them even the year of their visitation saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 13, 'And I have seen folly in the prophets of Samaria; they prophesied in Baal, and caused my people Israel to err. {folly: or, an absurd thing: Heb. unsavoury}', 'and i have seen folly in the prophets of samaria they prophesied in baal and caused my people israel to err folly or an absurd thing heb unsavoury');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 14, 'I have seen also in the prophets of Jerusalem an horrible thing: they commit adultery, and walk in lies: they strengthen also the hands of evildoers, that none doth return from his wickedness: they are all of them unto me as Sodom, and the inhabitants thereof as Gomorrah. {an...: or, filthiness}', 'i have seen also in the prophets of jerusalem an horrible thing they commit adultery and walk in lies they strengthen also the hands of evildoers that none doth return from his wickedness they are all of them unto me as sodom and the inhabitants thereof as gomorrah an or filthiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 15, 'Therefore thus saith the LORD of hosts concerning the prophets; Behold, I will feed them with wormwood, and make them drink the water of gall: for from the prophets of Jerusalem is profaneness gone forth into all the land. {profaneness: or, hypocrisy}', 'therefore thus saith the lord of hosts concerning the prophets behold i will feed them with wormwood and make them drink the water of gall for from the prophets of jerusalem is profaneness gone forth into all the land profaneness or hypocrisy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 16, 'Thus saith the LORD of hosts, Hearken not unto the words of the prophets that prophesy unto you: they make you vain: they speak a vision of their own heart, {and} not out of the mouth of the LORD.', 'thus saith the lord of hosts hearken not unto the words of the prophets that prophesy unto you they make you vain they speak a vision of their own heart and not out of the mouth of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 17, 'They say still unto them that despise me, The LORD hath said, Ye shall have peace; and they say unto every one that walketh after the imagination of his own heart, No evil shall come upon you. {imagination: or, stubbornness}', 'they say still unto them that despise me the lord hath said ye shall have peace and they say unto every one that walketh after the imagination of his own heart no evil shall come upon you imagination or stubbornness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 18, 'For who hath stood in the counsel of the LORD, and hath perceived and heard his word? who hath marked his word, and heard {it}? {counsel: or, secret}', 'for who hath stood in the counsel of the lord and hath perceived and heard his word who hath marked his word and heard it counsel or secret');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 19, 'Behold, a whirlwind of the LORD is gone forth in fury, even a grievous whirlwind: it shall fall grievously upon the head of the wicked.', 'behold a whirlwind of the lord is gone forth in fury even a grievous whirlwind it shall fall grievously upon the head of the wicked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 20, 'The anger of the LORD shall not return, until he have executed, and till he have performed the thoughts of his heart: in the latter days ye shall consider it perfectly.', 'the anger of the lord shall not return until he have executed and till he have performed the thoughts of his heart in the latter days ye shall consider it perfectly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 21, 'I have not sent these prophets, yet they ran: I have not spoken to them, yet they prophesied.', 'i have not sent these prophets yet they ran i have not spoken to them yet they prophesied');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 22, 'But if they had stood in my counsel, and had caused my people to hear my words, then they should have turned them from their evil way, and from the evil of their doings.', 'but if they had stood in my counsel and had caused my people to hear my words then they should have turned them from their evil way and from the evil of their doings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 23, '{Am} I a God at hand, saith the LORD, and not a God afar off?', 'am i a god at hand saith the lord and not a god afar off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 24, 'Can any hide himself in secret places that I shall not see him? saith the LORD. Do not I fill heaven and earth? saith the LORD.', 'can any hide himself in secret places that i shall not see him saith the lord do not i fill heaven and earth saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 25, 'I have heard what the prophets said, that prophesy lies in my name, saying, I have dreamed, I have dreamed.', 'i have heard what the prophets said that prophesy lies in my name saying i have dreamed i have dreamed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 26, 'How long shall {this} be in the heart of the prophets that prophesy lies? yea, {they are} prophets of the deceit of their own heart;', 'how long shall this be in the heart of the prophets that prophesy lies yea they are prophets of the deceit of their own heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 27, 'Which think to cause my people to forget my name by their dreams which they tell every man to his neighbour, as their fathers have forgotten my name for Baal.', 'which think to cause my people to forget my name by their dreams which they tell every man to his neighbour as their fathers have forgotten my name for baal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 28, 'The prophet that hath a dream, let him tell a dream; and he that hath my word, let him speak my word faithfully. What {is} the chaff to the wheat? saith the LORD. {that hath a dream: Heb. with whom is, etc}', 'the prophet that hath a dream let him tell a dream and he that hath my word let him speak my word faithfully what is the chaff to the wheat saith the lord that hath a dream heb with whom is etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 29, '{Is} not my word like as a fire? saith the LORD; and like a hammer {that} breaketh the rock in pieces?', 'is not my word like as a fire saith the lord and like a hammer that breaketh the rock in pieces');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 30, 'Therefore, behold, I {am} against the prophets, saith the LORD, that steal my words every one from his neighbour.', 'therefore behold i am against the prophets saith the lord that steal my words every one from his neighbour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 31, 'Behold, I {am} against the prophets, saith the LORD, that use their tongues, and say, He saith. {that...: or, that smooth their tongues}', 'behold i am against the prophets saith the lord that use their tongues and say he saith that or that smooth their tongues');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 32, 'Behold, I {am} against them that prophesy false dreams, saith the LORD, and do tell them, and cause my people to err by their lies, and by their lightness; yet I sent them not, nor commanded them: therefore they shall not profit this people at all, saith the LORD.', 'behold i am against them that prophesy false dreams saith the lord and do tell them and cause my people to err by their lies and by their lightness yet i sent them not nor commanded them therefore they shall not profit this people at all saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 33, 'And when this people, or the prophet, or a priest, shall ask thee, saying, What {is} the burden of the LORD? thou shalt then say unto them, What burden? I will even forsake you, saith the LORD.', 'and when this people or the prophet or a priest shall ask thee saying what is the burden of the lord thou shalt then say unto them what burden i will even forsake you saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 34, 'And {as for} the prophet, and the priest, and the people, that shall say, The burden of the LORD, I will even punish that man and his house. {punish: Heb. visit upon}', 'and as for the prophet and the priest and the people that shall say the burden of the lord i will even punish that man and his house punish heb visit upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 35, 'Thus shall ye say every one to his neighbour, and every one to his brother, What hath the LORD answered? and, What hath the LORD spoken?', 'thus shall ye say every one to his neighbour and every one to his brother what hath the lord answered and what hath the lord spoken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 36, 'And the burden of the LORD shall ye mention no more: for every man''s word shall be his burden; for ye have perverted the words of the living God, of the LORD of hosts our God.', 'and the burden of the lord shall ye mention no more for every man s word shall be his burden for ye have perverted the words of the living god of the lord of hosts our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 37, 'Thus shalt thou say to the prophet, What hath the LORD answered thee? and, What hath the LORD spoken?', 'thus shalt thou say to the prophet what hath the lord answered thee and what hath the lord spoken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 38, 'But since ye say, The burden of the LORD; therefore thus saith the LORD; Because ye say this word, The burden of the LORD, and I have sent unto you, saying, Ye shall not say, The burden of the LORD;', 'but since ye say the burden of the lord therefore thus saith the lord because ye say this word the burden of the lord and i have sent unto you saying ye shall not say the burden of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 39, 'Therefore, behold, I, even I, will utterly forget you, and I will forsake you, and the city that I gave you and your fathers, {and cast you} out of my presence:', 'therefore behold i even i will utterly forget you and i will forsake you and the city that i gave you and your fathers and cast you out of my presence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 23, 40, 'And I will bring an everlasting reproach upon you, and a perpetual shame, which shall not be forgotten.', 'and i will bring an everlasting reproach upon you and a perpetual shame which shall not be forgotten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 1, 'The LORD shewed me, and, behold, two baskets of figs {were} set before the temple of the LORD, after that Nebuchadrezzar king of Babylon had carried away captive Jeconiah the son of Jehoiakim king of Judah, and the princes of Judah, with the carpenters and smiths, from Jerusalem, and had brought them to Babylon.', 'the lord shewed me and behold two baskets of figs were set before the temple of the lord after that nebuchadrezzar king of babylon had carried away captive jeconiah the son of jehoiakim king of judah and the princes of judah with the carpenters and smiths from jerusalem and had brought them to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 2, 'One basket {had} very good figs, {even} like the figs {that are} first ripe: and the other basket {had} very naughty figs, which could not be eaten, they were so bad. {they...: Heb. for badness}', 'one basket had very good figs even like the figs that are first ripe and the other basket had very naughty figs which could not be eaten they were so bad they heb for badness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 3, 'Then said the LORD unto me, What seest thou, Jeremiah? And I said, Figs; the good figs, very good; and the evil, very evil, that cannot be eaten, they are so evil.', 'then said the lord unto me what seest thou jeremiah and i said figs the good figs very good and the evil very evil that cannot be eaten they are so evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 4, 'Again the word of the LORD came unto me, saying,', 'again the word of the lord came unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 5, 'Thus saith the LORD, the God of Israel; Like these good figs, so will I acknowledge them that are carried away captive of Judah, whom I have sent out of this place into the land of the Chaldeans for {their} good. {them...: Heb. the captivity}', 'thus saith the lord the god of israel like these good figs so will i acknowledge them that are carried away captive of judah whom i have sent out of this place into the land of the chaldeans for their good them heb the captivity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 6, 'For I will set mine eyes upon them for good, and I will bring them again to this land: and I will build them, and not pull {them} down; and I will plant them, and not pluck {them} up.', 'for i will set mine eyes upon them for good and i will bring them again to this land and i will build them and not pull them down and i will plant them and not pluck them up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 7, 'And I will give them an heart to know me, that I {am} the LORD: and they shall be my people, and I will be their God: for they shall return unto me with their whole heart.', 'and i will give them an heart to know me that i am the lord and they shall be my people and i will be their god for they shall return unto me with their whole heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 8, 'And as the evil figs, which cannot be eaten, they are so evil; surely thus saith the LORD, So will I give Zedekiah the king of Judah, and his princes, and the residue of Jerusalem, that remain in this land, and them that dwell in the land of Egypt:', 'and as the evil figs which cannot be eaten they are so evil surely thus saith the lord so will i give zedekiah the king of judah and his princes and the residue of jerusalem that remain in this land and them that dwell in the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 9, 'And I will deliver them to be removed into all the kingdoms of the earth for {their} hurt, {to be} a reproach and a proverb, a taunt and a curse, in all places whither I shall drive them. {to be removed: Heb. for removing, or, vexation}', 'and i will deliver them to be removed into all the kingdoms of the earth for their hurt to be a reproach and a proverb a taunt and a curse in all places whither i shall drive them to be removed heb for removing or vexation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 24, 10, 'And I will send the sword, the famine, and the pestilence, among them, till they be consumed from off the land that I gave unto them and to their fathers.', 'and i will send the sword the famine and the pestilence among them till they be consumed from off the land that i gave unto them and to their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 1, 'The word that came to Jeremiah concerning all the people of Judah in the fourth year of Jehoiakim the son of Josiah king of Judah, that {was} the first year of Nebuchadrezzar king of Babylon;', 'the word that came to jeremiah concerning all the people of judah in the fourth year of jehoiakim the son of josiah king of judah that was the first year of nebuchadrezzar king of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 2, 'The which Jeremiah the prophet spake unto all the people of Judah, and to all the inhabitants of Jerusalem, saying,', 'the which jeremiah the prophet spake unto all the people of judah and to all the inhabitants of jerusalem saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 3, 'From the thirteenth year of Josiah the son of Amon king of Judah, even unto this day, that {is} the three and twentieth year, the word of the LORD hath come unto me, and I have spoken unto you, rising early and speaking; but ye have not hearkened.', 'from the thirteenth year of josiah the son of amon king of judah even unto this day that is the three and twentieth year the word of the lord hath come unto me and i have spoken unto you rising early and speaking but ye have not hearkened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 4, 'And the LORD hath sent unto you all his servants the prophets, rising early and sending {them}; but ye have not hearkened, nor inclined your ear to hear.', 'and the lord hath sent unto you all his servants the prophets rising early and sending them but ye have not hearkened nor inclined your ear to hear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 5, 'They said, Turn ye again now every one from his evil way, and from the evil of your doings, and dwell in the land that the LORD hath given unto you and to your fathers for ever and ever:', 'they said turn ye again now every one from his evil way and from the evil of your doings and dwell in the land that the lord hath given unto you and to your fathers for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 6, 'And go not after other gods to serve them, and to worship them, and provoke me not to anger with the works of your hands; and I will do you no hurt.', 'and go not after other gods to serve them and to worship them and provoke me not to anger with the works of your hands and i will do you no hurt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 7, 'Yet ye have not hearkened unto me, saith the LORD; that ye might provoke me to anger with the works of your hands to your own hurt.', 'yet ye have not hearkened unto me saith the lord that ye might provoke me to anger with the works of your hands to your own hurt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 8, 'Therefore thus saith the LORD of hosts; Because ye have not heard my words,', 'therefore thus saith the lord of hosts because ye have not heard my words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 9, 'Behold, I will send and take all the families of the north, saith the LORD, and Nebuchadrezzar the king of Babylon, my servant, and will bring them against this land, and against the inhabitants thereof, and against all these nations round about, and will utterly destroy them, and make them an astonishment, and an hissing, and perpetual desolations.', 'behold i will send and take all the families of the north saith the lord and nebuchadrezzar the king of babylon my servant and will bring them against this land and against the inhabitants thereof and against all these nations round about and will utterly destroy them and make them an astonishment and an hissing and perpetual desolations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 10, 'Moreover I will take from them the voice of mirth, and the voice of gladness, the voice of the bridegroom, and the voice of the bride, the sound of the millstones, and the light of the candle. {I will...: Heb. I will cause to perish from them}', 'moreover i will take from them the voice of mirth and the voice of gladness the voice of the bridegroom and the voice of the bride the sound of the millstones and the light of the candle i will heb i will cause to perish from them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 11, 'And this whole land shall be a desolation, {and} an astonishment; and these nations shall serve the king of Babylon seventy years.', 'and this whole land shall be a desolation and an astonishment and these nations shall serve the king of babylon seventy years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 12, 'And it shall come to pass, when seventy years are accomplished, {that} I will punish the king of Babylon, and that nation, saith the LORD, for their iniquity, and the land of the Chaldeans, and will make it perpetual desolations. {punish: Heb. visit upon}', 'and it shall come to pass when seventy years are accomplished that i will punish the king of babylon and that nation saith the lord for their iniquity and the land of the chaldeans and will make it perpetual desolations punish heb visit upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 13, 'And I will bring upon that land all my words which I have pronounced against it, {even} all that is written in this book, which Jeremiah hath prophesied against all the nations.', 'and i will bring upon that land all my words which i have pronounced against it even all that is written in this book which jeremiah hath prophesied against all the nations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 14, 'For many nations and great kings shall serve themselves of them also: and I will recompense them according to their deeds, and according to the works of their own hands.', 'for many nations and great kings shall serve themselves of them also and i will recompense them according to their deeds and according to the works of their own hands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 15, 'For thus saith the LORD God of Israel unto me; Take the wine cup of this fury at my hand, and cause all the nations, to whom I send thee, to drink it.', 'for thus saith the lord god of israel unto me take the wine cup of this fury at my hand and cause all the nations to whom i send thee to drink it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 16, 'And they shall drink, and be moved, and be mad, because of the sword that I will send among them.', 'and they shall drink and be moved and be mad because of the sword that i will send among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 17, 'Then took I the cup at the LORD''S hand, and made all the nations to drink, unto whom the LORD had sent me:', 'then took i the cup at the lord s hand and made all the nations to drink unto whom the lord had sent me');
