INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 21, 'Edom, and Moab, and the children of Ammon,', 'edom and moab and the children of ammon');
