INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 23, 'Dedan, and Tema, and Buz, and all {that are} in the utmost corners, {that...: Heb. cut off into corners, or, having the corners of the hair polled}', 'dedan and tema and buz and all that are in the utmost corners that heb cut off into corners or having the corners of the hair polled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 24, 'And all the kings of Arabia, and all the kings of the mingled people that dwell in the desert,', 'and all the kings of arabia and all the kings of the mingled people that dwell in the desert');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 25, 'And all the kings of Zimri, and all the kings of Elam, and all the kings of the Medes,', 'and all the kings of zimri and all the kings of elam and all the kings of the medes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 26, 'And all the kings of the north, far and near, one with another, and all the kingdoms of the world, which {are} upon the face of the earth: and the king of Sheshach shall drink after them.', 'and all the kings of the north far and near one with another and all the kingdoms of the world which are upon the face of the earth and the king of sheshach shall drink after them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 27, 'Therefore thou shalt say unto them, Thus saith the LORD of hosts, the God of Israel; Drink ye, and be drunken, and spue, and fall, and rise no more, because of the sword which I will send among you.', 'therefore thou shalt say unto them thus saith the lord of hosts the god of israel drink ye and be drunken and spue and fall and rise no more because of the sword which i will send among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 28, 'And it shall be, if they refuse to take the cup at thine hand to drink, then shalt thou say unto them, Thus saith the LORD of hosts; Ye shall certainly drink.', 'and it shall be if they refuse to take the cup at thine hand to drink then shalt thou say unto them thus saith the lord of hosts ye shall certainly drink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 29, 'For, lo, I begin to bring evil on the city which is called by my name, and should ye be utterly unpunished? Ye shall not be unpunished: for I will call for a sword upon all the inhabitants of the earth, saith the LORD of hosts. {which...: Heb. upon which my name is called}', 'for lo i begin to bring evil on the city which is called by my name and should ye be utterly unpunished ye shall not be unpunished for i will call for a sword upon all the inhabitants of the earth saith the lord of hosts which heb upon which my name is called');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 30, 'Therefore prophesy thou against them all these words, and say unto them, The LORD shall roar from on high, and utter his voice from his holy habitation; he shall mightily roar upon his habitation; he shall give a shout, as they that tread {the grapes}, against all the inhabitants of the earth.', 'therefore prophesy thou against them all these words and say unto them the lord shall roar from on high and utter his voice from his holy habitation he shall mightily roar upon his habitation he shall give a shout as they that tread the grapes against all the inhabitants of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 31, 'A noise shall come {even} to the ends of the earth; for the LORD hath a controversy with the nations, he will plead with all flesh; he will give them {that are} wicked to the sword, saith the LORD.', 'a noise shall come even to the ends of the earth for the lord hath a controversy with the nations he will plead with all flesh he will give them that are wicked to the sword saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 32, 'Thus saith the LORD of hosts, Behold, evil shall go forth from nation to nation, and a great whirlwind shall be raised up from the coasts of the earth.', 'thus saith the lord of hosts behold evil shall go forth from nation to nation and a great whirlwind shall be raised up from the coasts of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 33, 'And the slain of the LORD shall be at that day from {one} end of the earth even unto the {other} end of the earth: they shall not be lamented, neither gathered, nor buried; they shall be dung upon the ground.', 'and the slain of the lord shall be at that day from one end of the earth even unto the other end of the earth they shall not be lamented neither gathered nor buried they shall be dung upon the ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 34, 'Howl, ye shepherds, and cry; and wallow yourselves {in the ashes}, ye principal of the flock: for the days of your slaughter and of your dispersions are accomplished; and ye shall fall like a pleasant vessel. {the days...: Heb. your days for slaughter} {a pleasant...: Heb. a vessel of desire}', 'howl ye shepherds and cry and wallow yourselves in the ashes ye principal of the flock for the days of your slaughter and of your dispersions are accomplished and ye shall fall like a pleasant vessel the days heb your days for slaughter a pleasant heb a vessel of desire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 35, 'And the shepherds shall have no way to flee, nor the principal of the flock to escape. {the shepherds...: Heb. flight shall perish from the shepherds, and escaping from, etc}', 'and the shepherds shall have no way to flee nor the principal of the flock to escape the shepherds heb flight shall perish from the shepherds and escaping from etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 36, 'A voice of the cry of the shepherds, and an howling of the principal of the flock, {shall be heard}: for the LORD hath spoiled their pasture.', 'a voice of the cry of the shepherds and an howling of the principal of the flock shall be heard for the lord hath spoiled their pasture');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 37, 'And the peaceable habitations are cut down because of the fierce anger of the LORD.', 'and the peaceable habitations are cut down because of the fierce anger of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 25, 38, 'He hath forsaken his covert, as the lion: for their land is desolate because of the fierceness of the oppressor, and because of his fierce anger. {desolate: Heb. a desolation}', 'he hath forsaken his covert as the lion for their land is desolate because of the fierceness of the oppressor and because of his fierce anger desolate heb a desolation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 1, 'In the beginning of the reign of Jehoiakim the son of Josiah king of Judah came this word from the LORD, saying,', 'in the beginning of the reign of jehoiakim the son of josiah king of judah came this word from the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 2, 'Thus saith the LORD; Stand in the court of the LORD''S house, and speak unto all the cities of Judah, which come to worship in the LORD''S house, all the words that I command thee to speak unto them; diminish not a word:', 'thus saith the lord stand in the court of the lord s house and speak unto all the cities of judah which come to worship in the lord s house all the words that i command thee to speak unto them diminish not a word');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 3, 'If so be they will hearken, and turn every man from his evil way, that I may repent me of the evil, which I purpose to do unto them because of the evil of their doings.', 'if so be they will hearken and turn every man from his evil way that i may repent me of the evil which i purpose to do unto them because of the evil of their doings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 4, 'And thou shalt say unto them, Thus saith the LORD; If ye will not hearken to me, to walk in my law, which I have set before you,', 'and thou shalt say unto them thus saith the lord if ye will not hearken to me to walk in my law which i have set before you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 5, 'To hearken to the words of my servants the prophets, whom I sent unto you, both rising up early, and sending {them}, but ye have not hearkened;', 'to hearken to the words of my servants the prophets whom i sent unto you both rising up early and sending them but ye have not hearkened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 6, 'Then will I make this house like Shiloh, and will make this city a curse to all the nations of the earth.', 'then will i make this house like shiloh and will make this city a curse to all the nations of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 7, 'So the priests and the prophets and all the people heard Jeremiah speaking these words in the house of the LORD.', 'so the priests and the prophets and all the people heard jeremiah speaking these words in the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 8, 'Now it came to pass, when Jeremiah had made an end of speaking all that the LORD had commanded {him} to speak unto all the people, that the priests and the prophets and all the people took him, saying, Thou shalt surely die.', 'now it came to pass when jeremiah had made an end of speaking all that the lord had commanded him to speak unto all the people that the priests and the prophets and all the people took him saying thou shalt surely die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 9, 'Why hast thou prophesied in the name of the LORD, saying, This house shall be like Shiloh, and this city shall be desolate without an inhabitant? And all the people were gathered against Jeremiah in the house of the LORD.', 'why hast thou prophesied in the name of the lord saying this house shall be like shiloh and this city shall be desolate without an inhabitant and all the people were gathered against jeremiah in the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 10, 'When the princes of Judah heard these things, then they came up from the king''s house unto the house of the LORD, and sat down in the entry of the new gate of the LORD''S {house}. {in the...: or, at the door}', 'when the princes of judah heard these things then they came up from the king s house unto the house of the lord and sat down in the entry of the new gate of the lord s house in the or at the door');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 11, 'Then spake the priests and the prophets unto the princes and to all the people, saying, This man {is} worthy to die; for he hath prophesied against this city, as ye have heard with your ears. {This man...: Heb. The judgment of death is for this man}', 'then spake the priests and the prophets unto the princes and to all the people saying this man is worthy to die for he hath prophesied against this city as ye have heard with your ears this man heb the judgment of death is for this man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 12, 'Then spake Jeremiah unto all the princes and to all the people, saying, The LORD sent me to prophesy against this house and against this city all the words that ye have heard.', 'then spake jeremiah unto all the princes and to all the people saying the lord sent me to prophesy against this house and against this city all the words that ye have heard');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 13, 'Therefore now amend your ways and your doings, and obey the voice of the LORD your God; and the LORD will repent him of the evil that he hath pronounced against you.', 'therefore now amend your ways and your doings and obey the voice of the lord your god and the lord will repent him of the evil that he hath pronounced against you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 14, 'As for me, behold, I {am} in your hand: do with me as seemeth good and meet unto you. {as...: Heb. as it is good and right in your eyes}', 'as for me behold i am in your hand do with me as seemeth good and meet unto you as heb as it is good and right in your eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 15, 'But know ye for certain, that if ye put me to death, ye shall surely bring innocent blood upon yourselves, and upon this city, and upon the inhabitants thereof: for of a truth the LORD hath sent me unto you to speak all these words in your ears.', 'but know ye for certain that if ye put me to death ye shall surely bring innocent blood upon yourselves and upon this city and upon the inhabitants thereof for of a truth the lord hath sent me unto you to speak all these words in your ears');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 16, 'Then said the princes and all the people unto the priests and to the prophets; This man {is} not worthy to die: for he hath spoken to us in the name of the LORD our God.', 'then said the princes and all the people unto the priests and to the prophets this man is not worthy to die for he hath spoken to us in the name of the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 17, 'Then rose up certain of the elders of the land, and spake to all the assembly of the people, saying,', 'then rose up certain of the elders of the land and spake to all the assembly of the people saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 18, 'Micah the Morasthite prophesied in the days of Hezekiah king of Judah, and spake to all the people of Judah, saying, Thus saith the LORD of hosts; Zion shall be plowed {like} a field, and Jerusalem shall become heaps, and the mountain of the house as the high places of a forest.', 'micah the morasthite prophesied in the days of hezekiah king of judah and spake to all the people of judah saying thus saith the lord of hosts zion shall be plowed like a field and jerusalem shall become heaps and the mountain of the house as the high places of a forest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 19, 'Did Hezekiah king of Judah and all Judah put him at all to death? did he not fear the LORD, and besought the LORD, and the LORD repented him of the evil which he had pronounced against them? Thus might we procure great evil against our souls. {the LORD, and the: Heb. the face of the LORD, etc}', 'did hezekiah king of judah and all judah put him at all to death did he not fear the lord and besought the lord and the lord repented him of the evil which he had pronounced against them thus might we procure great evil against our souls the lord and the heb the face of the lord etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 20, 'And there was also a man that prophesied in the name of the LORD, Urijah the son of Shemaiah of Kirjathjearim, who prophesied against this city and against this land according to all the words of Jeremiah:', 'and there was also a man that prophesied in the name of the lord urijah the son of shemaiah of kirjathjearim who prophesied against this city and against this land according to all the words of jeremiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 21, 'And when Jehoiakim the king, with all his mighty men, and all the princes, heard his words, the king sought to put him to death: but when Urijah heard it, he was afraid, and fled, and went into Egypt;', 'and when jehoiakim the king with all his mighty men and all the princes heard his words the king sought to put him to death but when urijah heard it he was afraid and fled and went into egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 22, 'And Jehoiakim the king sent men into Egypt, {namely}, Elnathan the son of Achbor, and {certain} men with him into Egypt.', 'and jehoiakim the king sent men into egypt namely elnathan the son of achbor and certain men with him into egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 23, 'And they fetched forth Urijah out of Egypt, and brought him unto Jehoiakim the king; who slew him with the sword, and cast his dead body into the graves of the common people. {common...: Heb. sons of the people}', 'and they fetched forth urijah out of egypt and brought him unto jehoiakim the king who slew him with the sword and cast his dead body into the graves of the common people common heb sons of the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 26, 24, 'Nevertheless the hand of Ahikam the son of Shaphan was with Jeremiah, that they should not give him into the hand of the people to put him to death.', 'nevertheless the hand of ahikam the son of shaphan was with jeremiah that they should not give him into the hand of the people to put him to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 1, 'In the beginning of the reign of Jehoiakim the son of Josiah king of Judah came this word unto Jeremiah from the LORD, saying,', 'in the beginning of the reign of jehoiakim the son of josiah king of judah came this word unto jeremiah from the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 2, 'Thus saith the LORD to me; Make thee bonds and yokes, and put them upon thy neck, {saith...: or, hath the LORD said}', 'thus saith the lord to me make thee bonds and yokes and put them upon thy neck saith or hath the lord said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 3, 'And send them to the king of Edom, and to the king of Moab, and to the king of the Ammonites, and to the king of Tyrus, and to the king of Zidon, by the hand of the messengers which come to Jerusalem unto Zedekiah king of Judah;', 'and send them to the king of edom and to the king of moab and to the king of the ammonites and to the king of tyrus and to the king of zidon by the hand of the messengers which come to jerusalem unto zedekiah king of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 4, 'And command them to say unto their masters, Thus saith the LORD of hosts, the God of Israel; Thus shall ye say unto your masters; {to say...: or, concerning their masters, saying}', 'and command them to say unto their masters thus saith the lord of hosts the god of israel thus shall ye say unto your masters to say or concerning their masters saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 5, 'I have made the earth, the man and the beast that {are} upon the ground, by my great power and by my outstretched arm, and have given it unto whom it seemed meet unto me.', 'i have made the earth the man and the beast that are upon the ground by my great power and by my outstretched arm and have given it unto whom it seemed meet unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 6, 'And now have I given all these lands into the hand of Nebuchadnezzar the king of Babylon, my servant; and the beasts of the field have I given him also to serve him.', 'and now have i given all these lands into the hand of nebuchadnezzar the king of babylon my servant and the beasts of the field have i given him also to serve him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 7, 'And all nations shall serve him, and his son, and his son''s son, until the very time of his land come: and then many nations and great kings shall serve themselves of him.', 'and all nations shall serve him and his son and his son s son until the very time of his land come and then many nations and great kings shall serve themselves of him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 8, 'And it shall come to pass, {that} the nation and kingdom which will not serve the same Nebuchadnezzar the king of Babylon, and that will not put their neck under the yoke of the king of Babylon, that nation will I punish, saith the LORD, with the sword, and with the famine, and with the pestilence, until I have consumed them by his hand.', 'and it shall come to pass that the nation and kingdom which will not serve the same nebuchadnezzar the king of babylon and that will not put their neck under the yoke of the king of babylon that nation will i punish saith the lord with the sword and with the famine and with the pestilence until i have consumed them by his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 9, 'Therefore hearken not ye to your prophets, nor to your diviners, nor to your dreamers, nor to your enchanters, nor to your sorcerers, which speak unto you, saying, Ye shall not serve the king of Babylon: {dreamers: Heb. dreams}', 'therefore hearken not ye to your prophets nor to your diviners nor to your dreamers nor to your enchanters nor to your sorcerers which speak unto you saying ye shall not serve the king of babylon dreamers heb dreams');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 10, 'For they prophesy a lie unto you, to remove you far from your land; and that I should drive you out, and ye should perish.', 'for they prophesy a lie unto you to remove you far from your land and that i should drive you out and ye should perish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 11, 'But the nations that bring their neck under the yoke of the king of Babylon, and serve him, those will I let remain still in their own land, saith the LORD; and they shall till it, and dwell therein.', 'but the nations that bring their neck under the yoke of the king of babylon and serve him those will i let remain still in their own land saith the lord and they shall till it and dwell therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 12, 'I spake also to Zedekiah king of Judah according to all these words, saying, Bring your necks under the yoke of the king of Babylon, and serve him and his people, and live.', 'i spake also to zedekiah king of judah according to all these words saying bring your necks under the yoke of the king of babylon and serve him and his people and live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 13, 'Why will ye die, thou and thy people, by the sword, by the famine, and by the pestilence, as the LORD hath spoken against the nation that will not serve the king of Babylon?', 'why will ye die thou and thy people by the sword by the famine and by the pestilence as the lord hath spoken against the nation that will not serve the king of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 14, 'Therefore hearken not unto the words of the prophets that speak unto you, saying, Ye shall not serve the king of Babylon: for they prophesy a lie unto you.', 'therefore hearken not unto the words of the prophets that speak unto you saying ye shall not serve the king of babylon for they prophesy a lie unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 15, 'For I have not sent them, saith the LORD, yet they prophesy a lie in my name; that I might drive you out, and that ye might perish, ye, and the prophets that prophesy unto you. {a lie: Heb. in a lie, or, lyingly}', 'for i have not sent them saith the lord yet they prophesy a lie in my name that i might drive you out and that ye might perish ye and the prophets that prophesy unto you a lie heb in a lie or lyingly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 16, 'Also I spake to the priests and to all this people, saying, Thus saith the LORD; Hearken not to the words of your prophets that prophesy unto you, saying, Behold, the vessels of the LORD''S house shall now shortly be brought again from Babylon: for they prophesy a lie unto you.', 'also i spake to the priests and to all this people saying thus saith the lord hearken not to the words of your prophets that prophesy unto you saying behold the vessels of the lord s house shall now shortly be brought again from babylon for they prophesy a lie unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 17, 'Hearken not unto them; serve the king of Babylon, and live: wherefore should this city be laid waste?', 'hearken not unto them serve the king of babylon and live wherefore should this city be laid waste');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 18, 'But if they {be} prophets, and if the word of the LORD be with them, let them now make intercession to the LORD of hosts, that the vessels which are left in the house of the LORD, and {in} the house of the king of Judah, and at Jerusalem, go not to Babylon.', 'but if they be prophets and if the word of the lord be with them let them now make intercession to the lord of hosts that the vessels which are left in the house of the lord and in the house of the king of judah and at jerusalem go not to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 19, 'For thus saith the LORD of hosts concerning the pillars, and concerning the sea, and concerning the bases, and concerning the residue of the vessels that remain in this city,', 'for thus saith the lord of hosts concerning the pillars and concerning the sea and concerning the bases and concerning the residue of the vessels that remain in this city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 20, 'Which Nebuchadnezzar king of Babylon took not, when he carried away captive Jeconiah the son of Jehoiakim king of Judah from Jerusalem to Babylon, and all the nobles of Judah and Jerusalem;', 'which nebuchadnezzar king of babylon took not when he carried away captive jeconiah the son of jehoiakim king of judah from jerusalem to babylon and all the nobles of judah and jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 21, 'Yea, thus saith the LORD of hosts, the God of Israel, concerning the vessels that remain {in} the house of the LORD, and {in} the house of the king of Judah and of Jerusalem;', 'yea thus saith the lord of hosts the god of israel concerning the vessels that remain in the house of the lord and in the house of the king of judah and of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 27, 22, 'They shall be carried to Babylon, and there shall they be until the day that I visit them, saith the LORD; then will I bring them up, and restore them to this place.', 'they shall be carried to babylon and there shall they be until the day that i visit them saith the lord then will i bring them up and restore them to this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 1, 'And it came to pass the same year, in the beginning of the reign of Zedekiah king of Judah, in the fourth year, {and} in the fifth month, {that} Hananiah the son of Azur the prophet, which {was} of Gibeon, spake unto me in the house of the LORD, in the presence of the priests and of all the people, saying,', 'and it came to pass the same year in the beginning of the reign of zedekiah king of judah in the fourth year and in the fifth month that hananiah the son of azur the prophet which was of gibeon spake unto me in the house of the lord in the presence of the priests and of all the people saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 2, 'Thus speaketh the LORD of hosts, the God of Israel, saying, I have broken the yoke of the king of Babylon.', 'thus speaketh the lord of hosts the god of israel saying i have broken the yoke of the king of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 3, 'Within two full years will I bring again into this place all the vessels of the LORD''S house, that Nebuchadnezzar king of Babylon took away from this place, and carried them to Babylon: {two...: Heb. two years of days}', 'within two full years will i bring again into this place all the vessels of the lord s house that nebuchadnezzar king of babylon took away from this place and carried them to babylon two heb two years of days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 4, 'And I will bring again to this place Jeconiah the son of Jehoiakim king of Judah, with all the captives of Judah, that went into Babylon, saith the LORD: for I will break the yoke of the king of Babylon. {captives: Heb. captivity}', 'and i will bring again to this place jeconiah the son of jehoiakim king of judah with all the captives of judah that went into babylon saith the lord for i will break the yoke of the king of babylon captives heb captivity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 5, 'Then the prophet Jeremiah said unto the prophet Hananiah in the presence of the priests, and in the presence of all the people that stood in the house of the LORD,', 'then the prophet jeremiah said unto the prophet hananiah in the presence of the priests and in the presence of all the people that stood in the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 6, 'Even the prophet Jeremiah said, Amen: the LORD do so: the LORD perform thy words which thou hast prophesied, to bring again the vessels of the LORD''S house, and all that is carried away captive, from Babylon into this place.', 'even the prophet jeremiah said amen the lord do so the lord perform thy words which thou hast prophesied to bring again the vessels of the lord s house and all that is carried away captive from babylon into this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 7, 'Nevertheless hear thou now this word that I speak in thine ears, and in the ears of all the people;', 'nevertheless hear thou now this word that i speak in thine ears and in the ears of all the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 8, 'The prophets that have been before me and before thee of old prophesied both against many countries, and against great kingdoms, of war, and of evil, and of pestilence.', 'the prophets that have been before me and before thee of old prophesied both against many countries and against great kingdoms of war and of evil and of pestilence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 9, 'The prophet which prophesieth of peace, when the word of the prophet shall come to pass, {then} shall the prophet be known, that the LORD hath truly sent him.', 'the prophet which prophesieth of peace when the word of the prophet shall come to pass then shall the prophet be known that the lord hath truly sent him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 10, 'Then Hananiah the prophet took the yoke from off the prophet Jeremiah''s neck, and brake it.', 'then hananiah the prophet took the yoke from off the prophet jeremiah s neck and brake it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 11, 'And Hananiah spake in the presence of all the people, saying, Thus saith the LORD; Even so will I break the yoke of Nebuchadnezzar king of Babylon from the neck of all nations within the space of two full years. And the prophet Jeremiah went his way.', 'and hananiah spake in the presence of all the people saying thus saith the lord even so will i break the yoke of nebuchadnezzar king of babylon from the neck of all nations within the space of two full years and the prophet jeremiah went his way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 12, 'Then the word of the LORD came unto Jeremiah {the prophet}, after that Hananiah the prophet had broken the yoke from off the neck of the prophet Jeremiah, saying,', 'then the word of the lord came unto jeremiah the prophet after that hananiah the prophet had broken the yoke from off the neck of the prophet jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 13, 'Go and tell Hananiah, saying, Thus saith the LORD; Thou hast broken the yokes of wood; but thou shalt make for them yokes of iron.', 'go and tell hananiah saying thus saith the lord thou hast broken the yokes of wood but thou shalt make for them yokes of iron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 14, 'For thus saith the LORD of hosts, the God of Israel; I have put a yoke of iron upon the neck of all these nations, that they may serve Nebuchadnezzar king of Babylon; and they shall serve him: and I have given him the beasts of the field also.', 'for thus saith the lord of hosts the god of israel i have put a yoke of iron upon the neck of all these nations that they may serve nebuchadnezzar king of babylon and they shall serve him and i have given him the beasts of the field also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 15, 'Then said the prophet Jeremiah unto Hananiah the prophet, Hear now, Hananiah; The LORD hath not sent thee; but thou makest this people to trust in a lie.', 'then said the prophet jeremiah unto hananiah the prophet hear now hananiah the lord hath not sent thee but thou makest this people to trust in a lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 16, 'Therefore thus saith the LORD; Behold, I will cast thee from off the face of the earth: this year thou shalt die, because thou hast taught rebellion against the LORD. {rebellion: Heb. revolt}', 'therefore thus saith the lord behold i will cast thee from off the face of the earth this year thou shalt die because thou hast taught rebellion against the lord rebellion heb revolt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 28, 17, 'So Hananiah the prophet died the same year in the seventh month.', 'so hananiah the prophet died the same year in the seventh month');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 1, 'Now these {are} the words of the letter that Jeremiah the prophet sent from Jerusalem unto the residue of the elders which were carried away captives, and to the priests, and to the prophets, and to all the people whom Nebuchadnezzar had carried away captive from Jerusalem to Babylon;', 'now these are the words of the letter that jeremiah the prophet sent from jerusalem unto the residue of the elders which were carried away captives and to the priests and to the prophets and to all the people whom nebuchadnezzar had carried away captive from jerusalem to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 2, '(After that Jeconiah the king, and the queen, and the eunuchs, the princes of Judah and Jerusalem, and the carpenters, and the smiths, were departed from Jerusalem;) {eunuchs: or, chamberlains}', 'after that jeconiah the king and the queen and the eunuchs the princes of judah and jerusalem and the carpenters and the smiths were departed from jerusalem eunuchs or chamberlains');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 3, 'By the hand of Elasah the son of Shaphan, and Gemariah the son of Hilkiah, (whom Zedekiah king of Judah sent unto Babylon to Nebuchadnezzar king of Babylon) saying,', 'by the hand of elasah the son of shaphan and gemariah the son of hilkiah whom zedekiah king of judah sent unto babylon to nebuchadnezzar king of babylon saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 4, 'Thus saith the LORD of hosts, the God of Israel, unto all that are carried away captives, whom I have caused to be carried away from Jerusalem unto Babylon;', 'thus saith the lord of hosts the god of israel unto all that are carried away captives whom i have caused to be carried away from jerusalem unto babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 5, 'Build ye houses, and dwell {in them}; and plant gardens, and eat the fruit of them;', 'build ye houses and dwell in them and plant gardens and eat the fruit of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 6, 'Take ye wives, and beget sons and daughters; and take wives for your sons, and give your daughters to husbands, that they may bear sons and daughters; that ye may be increased there, and not diminished.', 'take ye wives and beget sons and daughters and take wives for your sons and give your daughters to husbands that they may bear sons and daughters that ye may be increased there and not diminished');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 7, 'And seek the peace of the city whither I have caused you to be carried away captives, and pray unto the LORD for it: for in the peace thereof shall ye have peace.', 'and seek the peace of the city whither i have caused you to be carried away captives and pray unto the lord for it for in the peace thereof shall ye have peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 8, 'For thus saith the LORD of hosts, the God of Israel; Let not your prophets and your diviners, that {be} in the midst of you, deceive you, neither hearken to your dreams which ye cause to be dreamed.', 'for thus saith the lord of hosts the god of israel let not your prophets and your diviners that be in the midst of you deceive you neither hearken to your dreams which ye cause to be dreamed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 9, 'For they prophesy falsely unto you in my name: I have not sent them, saith the LORD. {falsely: Heb. in a lie}', 'for they prophesy falsely unto you in my name i have not sent them saith the lord falsely heb in a lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 10, 'For thus saith the LORD, That after seventy years be accomplished at Babylon I will visit you, and perform my good word toward you, in causing you to return to this place.', 'for thus saith the lord that after seventy years be accomplished at babylon i will visit you and perform my good word toward you in causing you to return to this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 11, 'For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end. {expected...: Heb. end and expectation}', 'for i know the thoughts that i think toward you saith the lord thoughts of peace and not of evil to give you an expected end expected heb end and expectation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 12, 'Then shall ye call upon me, and ye shall go and pray unto me, and I will hearken unto you.', 'then shall ye call upon me and ye shall go and pray unto me and i will hearken unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 13, 'And ye shall seek me, and find {me}, when ye shall search for me with all your heart.', 'and ye shall seek me and find me when ye shall search for me with all your heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 14, 'And I will be found of you, saith the LORD: and I will turn away your captivity, and I will gather you from all the nations, and from all the places whither I have driven you, saith the LORD; and I will bring you again into the place whence I caused you to be carried away captive.', 'and i will be found of you saith the lord and i will turn away your captivity and i will gather you from all the nations and from all the places whither i have driven you saith the lord and i will bring you again into the place whence i caused you to be carried away captive');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 15, 'Because ye have said, The LORD hath raised us up prophets in Babylon;', 'because ye have said the lord hath raised us up prophets in babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 16, '{Know} that thus saith the LORD of the king that sitteth upon the throne of David, and of all the people that dwelleth in this city, {and} of your brethren that are not gone forth with you into captivity;', 'know that thus saith the lord of the king that sitteth upon the throne of david and of all the people that dwelleth in this city and of your brethren that are not gone forth with you into captivity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 17, 'Thus saith the LORD of hosts; Behold, I will send upon them the sword, the famine, and the pestilence, and will make them like vile figs, that cannot be eaten, they are so evil.', 'thus saith the lord of hosts behold i will send upon them the sword the famine and the pestilence and will make them like vile figs that cannot be eaten they are so evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 18, 'And I will persecute them with the sword, with the famine, and with the pestilence, and will deliver them to be removed to all the kingdoms of the earth, to be a curse, and an astonishment, and an hissing, and a reproach, among all the nations whither I have driven them: {to be a curse: Heb. for a curse}', 'and i will persecute them with the sword with the famine and with the pestilence and will deliver them to be removed to all the kingdoms of the earth to be a curse and an astonishment and an hissing and a reproach among all the nations whither i have driven them to be a curse heb for a curse');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 19, 'Because they have not hearkened to my words, saith the LORD, which I sent unto them by my servants the prophets, rising up early and sending {them}; but ye would not hear, saith the LORD.', 'because they have not hearkened to my words saith the lord which i sent unto them by my servants the prophets rising up early and sending them but ye would not hear saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 20, 'Hear ye therefore the word of the LORD, all ye of the captivity, whom I have sent from Jerusalem to Babylon:', 'hear ye therefore the word of the lord all ye of the captivity whom i have sent from jerusalem to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 21, 'Thus saith the LORD of hosts, the God of Israel, of Ahab the son of Kolaiah, and of Zedekiah the son of Maaseiah, which prophesy a lie unto you in my name; Behold, I will deliver them into the hand of Nebuchadrezzar king of Babylon; and he shall slay them before your eyes;', 'thus saith the lord of hosts the god of israel of ahab the son of kolaiah and of zedekiah the son of maaseiah which prophesy a lie unto you in my name behold i will deliver them into the hand of nebuchadrezzar king of babylon and he shall slay them before your eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 22, 'And of them shall be taken up a curse by all the captivity of Judah which {are} in Babylon, saying, The LORD make thee like Zedekiah and like Ahab, whom the king of Babylon roasted in the fire;', 'and of them shall be taken up a curse by all the captivity of judah which are in babylon saying the lord make thee like zedekiah and like ahab whom the king of babylon roasted in the fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 23, 'Because they have committed villany in Israel, and have committed adultery with their neighbours'' wives, and have spoken lying words in my name, which I have not commanded them; even I know, and {am} a witness, saith the LORD.', 'because they have committed villany in israel and have committed adultery with their neighbours wives and have spoken lying words in my name which i have not commanded them even i know and am a witness saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 24, '{Thus} shalt thou also speak to Shemaiah the Nehelamite, saying, {Nehelamite: or, dreamer}', 'thus shalt thou also speak to shemaiah the nehelamite saying nehelamite or dreamer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 25, 'Thus speaketh the LORD of hosts, the God of Israel, saying, Because thou hast sent letters in thy name unto all the people that {are} at Jerusalem, and to Zephaniah the son of Maaseiah the priest, and to all the priests, saying,', 'thus speaketh the lord of hosts the god of israel saying because thou hast sent letters in thy name unto all the people that are at jerusalem and to zephaniah the son of maaseiah the priest and to all the priests saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 26, 'The LORD hath made thee priest in the stead of Jehoiada the priest, that ye should be officers in the house of the LORD, for every man {that is} mad, and maketh himself a prophet, that thou shouldest put him in prison, and in the stocks.', 'the lord hath made thee priest in the stead of jehoiada the priest that ye should be officers in the house of the lord for every man that is mad and maketh himself a prophet that thou shouldest put him in prison and in the stocks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 27, 'Now therefore why hast thou not reproved Jeremiah of Anathoth, which maketh himself a prophet to you?', 'now therefore why hast thou not reproved jeremiah of anathoth which maketh himself a prophet to you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 28, 'For therefore he sent unto us {in} Babylon, saying, This {captivity is} long: build ye houses, and dwell {in them}; and plant gardens, and eat the fruit of them.', 'for therefore he sent unto us in babylon saying this captivity is long build ye houses and dwell in them and plant gardens and eat the fruit of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 29, 'And Zephaniah the priest read this letter in the ears of Jeremiah the prophet.', 'and zephaniah the priest read this letter in the ears of jeremiah the prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 30, 'Then came the word of the LORD unto Jeremiah, saying,', 'then came the word of the lord unto jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 31, 'Send to all them of the captivity, saying, Thus saith the LORD concerning Shemaiah the Nehelamite; Because that Shemaiah hath prophesied unto you, and I sent him not, and he caused you to trust in a lie:', 'send to all them of the captivity saying thus saith the lord concerning shemaiah the nehelamite because that shemaiah hath prophesied unto you and i sent him not and he caused you to trust in a lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 29, 32, 'Therefore thus saith the LORD; Behold, I will punish Shemaiah the Nehelamite, and his seed: he shall not have a man to dwell among this people; neither shall he behold the good that I will do for my people, saith the LORD; because he hath taught rebellion against the LORD. {rebellion: Heb. revolt}', 'therefore thus saith the lord behold i will punish shemaiah the nehelamite and his seed he shall not have a man to dwell among this people neither shall he behold the good that i will do for my people saith the lord because he hath taught rebellion against the lord rebellion heb revolt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 1, 'The word that came to Jeremiah from the LORD, saying,', 'the word that came to jeremiah from the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 2, 'Thus speaketh the LORD God of Israel, saying, Write thee all the words that I have spoken unto thee in a book.', 'thus speaketh the lord god of israel saying write thee all the words that i have spoken unto thee in a book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 3, 'For, lo, the days come, saith the LORD, that I will bring again the captivity of my people Israel and Judah, saith the LORD: and I will cause them to return to the land that I gave to their fathers, and they shall possess it.', 'for lo the days come saith the lord that i will bring again the captivity of my people israel and judah saith the lord and i will cause them to return to the land that i gave to their fathers and they shall possess it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 4, 'And these {are} the words that the LORD spake concerning Israel and concerning Judah.', 'and these are the words that the lord spake concerning israel and concerning judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 5, 'For thus saith the LORD; We have heard a voice of trembling, of fear, and not of peace. {of fear...: or, there is fear, and not peace}', 'for thus saith the lord we have heard a voice of trembling of fear and not of peace of fear or there is fear and not peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 6, 'Ask ye now, and see whether a man doth travail with child? wherefore do I see every man with his hands on his loins, as a woman in travail, and all faces are turned into paleness? {a man: Heb. a male}', 'ask ye now and see whether a man doth travail with child wherefore do i see every man with his hands on his loins as a woman in travail and all faces are turned into paleness a man heb a male');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 7, 'Alas! for that day {is} great, so that none {is} like it: it {is} even the time of Jacob''s trouble; but he shall be saved out of it.', 'alas for that day is great so that none is like it it is even the time of jacob s trouble but he shall be saved out of it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 8, 'For it shall come to pass in that day, saith the LORD of hosts, {that} I will break his yoke from off thy neck, and will burst thy bonds, and strangers shall no more serve themselves of him:', 'for it shall come to pass in that day saith the lord of hosts that i will break his yoke from off thy neck and will burst thy bonds and strangers shall no more serve themselves of him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 9, 'But they shall serve the LORD their God, and David their king, whom I will raise up unto them.', 'but they shall serve the lord their god and david their king whom i will raise up unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 10, 'Therefore fear thou not, O my servant Jacob, saith the LORD; neither be dismayed, O Israel: for, lo, I will save thee from afar, and thy seed from the land of their captivity; and Jacob shall return, and shall be in rest, and be quiet, and none shall make {him} afraid.', 'therefore fear thou not o my servant jacob saith the lord neither be dismayed o israel for lo i will save thee from afar and thy seed from the land of their captivity and jacob shall return and shall be in rest and be quiet and none shall make him afraid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 11, 'For I {am} with thee, saith the LORD, to save thee: though I make a full end of all nations whither I have scattered thee, yet will I not make a full end of thee: but I will correct thee in measure, and will not leave thee altogether unpunished.', 'for i am with thee saith the lord to save thee though i make a full end of all nations whither i have scattered thee yet will i not make a full end of thee but i will correct thee in measure and will not leave thee altogether unpunished');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 12, 'For thus saith the LORD, Thy bruise {is} incurable, {and} thy wound {is} grievous.', 'for thus saith the lord thy bruise is incurable and thy wound is grievous');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 13, '{There is} none to plead thy cause, that thou mayest be bound up: thou hast no healing medicines. {that...: Heb. for binding up, or, pressing}', 'there is none to plead thy cause that thou mayest be bound up thou hast no healing medicines that heb for binding up or pressing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 14, 'All thy lovers have forgotten thee; they seek thee not; for I have wounded thee with the wound of an enemy, with the chastisement of a cruel one, for the multitude of thine iniquity; {because} thy sins were increased.', 'all thy lovers have forgotten thee they seek thee not for i have wounded thee with the wound of an enemy with the chastisement of a cruel one for the multitude of thine iniquity because thy sins were increased');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 15, 'Why criest thou for thine affliction? thy sorrow {is} incurable for the multitude of thine iniquity: {because} thy sins were increased, I have done these things unto thee.', 'why criest thou for thine affliction thy sorrow is incurable for the multitude of thine iniquity because thy sins were increased i have done these things unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 16, 'Therefore all they that devour thee shall be devoured; and all thine adversaries, every one of them, shall go into captivity; and they that spoil thee shall be a spoil, and all that prey upon thee will I give for a prey.', 'therefore all they that devour thee shall be devoured and all thine adversaries every one of them shall go into captivity and they that spoil thee shall be a spoil and all that prey upon thee will i give for a prey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 17, 'For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, {saying}, This {is} Zion, whom no man seeketh after.', 'for i will restore health unto thee and i will heal thee of thy wounds saith the lord because they called thee an outcast saying this is zion whom no man seeketh after');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 18, 'Thus saith the LORD; Behold, I will bring again the captivity of Jacob''s tents, and have mercy on his dwellingplaces; and the city shall be builded upon her own heap, and the palace shall remain after the manner thereof. {heap: or, little hill}', 'thus saith the lord behold i will bring again the captivity of jacob s tents and have mercy on his dwellingplaces and the city shall be builded upon her own heap and the palace shall remain after the manner thereof heap or little hill');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 19, 'And out of them shall proceed thanksgiving and the voice of them that make merry: and I will multiply them, and they shall not be few; I will also glorify them, and they shall not be small.', 'and out of them shall proceed thanksgiving and the voice of them that make merry and i will multiply them and they shall not be few i will also glorify them and they shall not be small');
