INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 21, 'And their nobles shall be of themselves, and their governor shall proceed from the midst of them; and I will cause him to draw near, and he shall approach unto me: for who {is} this that engaged his heart to approach unto me? saith the LORD.', 'and their nobles shall be of themselves and their governor shall proceed from the midst of them and i will cause him to draw near and he shall approach unto me for who is this that engaged his heart to approach unto me saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 22, 'And ye shall be my people, and I will be your God.', 'and ye shall be my people and i will be your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 23, 'Behold, the whirlwind of the LORD goeth forth with fury, a continuing whirlwind: it shall fall with pain upon the head of the wicked. {continuing: Heb. cutting} {fall...: or, remain}', 'behold the whirlwind of the lord goeth forth with fury a continuing whirlwind it shall fall with pain upon the head of the wicked continuing heb cutting fall or remain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 30, 24, 'The fierce anger of the LORD shall not return, until he have done {it}, and until he have performed the intents of his heart: in the latter days ye shall consider it.', 'the fierce anger of the lord shall not return until he have done it and until he have performed the intents of his heart in the latter days ye shall consider it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 1, 'At the same time, saith the LORD, will I be the God of all the families of Israel, and they shall be my people.', 'at the same time saith the lord will i be the god of all the families of israel and they shall be my people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 2, 'Thus saith the LORD, The people {which were} left of the sword found grace in the wilderness; {even} Israel, when I went to cause him to rest.', 'thus saith the lord the people which were left of the sword found grace in the wilderness even israel when i went to cause him to rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 3, 'The LORD hath appeared of old unto me, {saying}, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee. {of...: Heb. from afar} {with lovingkindness...: have I extended lovingkindness unto thee}', 'the lord hath appeared of old unto me saying yea i have loved thee with an everlasting love therefore with lovingkindness have i drawn thee of heb from afar with lovingkindness have i extended lovingkindness unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 4, 'Again I will build thee, and thou shalt be built, O virgin of Israel: thou shalt again be adorned with thy tabrets, and shalt go forth in the dances of them that make merry. {tabrets: or, timbrels}', 'again i will build thee and thou shalt be built o virgin of israel thou shalt again be adorned with thy tabrets and shalt go forth in the dances of them that make merry tabrets or timbrels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 5, 'Thou shalt yet plant vines upon the mountains of Samaria: the planters shall plant, and shall eat {them} as common things. {eat...: Heb. profane them}', 'thou shalt yet plant vines upon the mountains of samaria the planters shall plant and shall eat them as common things eat heb profane them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 6, 'For there shall be a day, {that} the watchmen upon the mount Ephraim shall cry, Arise ye, and let us go up to Zion unto the LORD our God.', 'for there shall be a day that the watchmen upon the mount ephraim shall cry arise ye and let us go up to zion unto the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 7, 'For thus saith the LORD; Sing with gladness for Jacob, and shout among the chief of the nations: publish ye, praise ye, and say, O LORD, save thy people, the remnant of Israel.', 'for thus saith the lord sing with gladness for jacob and shout among the chief of the nations publish ye praise ye and say o lord save thy people the remnant of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 8, 'Behold, I will bring them from the north country, and gather them from the coasts of the earth, {and} with them the blind and the lame, the woman with child and her that travaileth with child together: a great company shall return thither.', 'behold i will bring them from the north country and gather them from the coasts of the earth and with them the blind and the lame the woman with child and her that travaileth with child together a great company shall return thither');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 9, 'They shall come with weeping, and with supplications will I lead them: I will cause them to walk by the rivers of waters in a straight way, wherein they shall not stumble: for I am a father to Israel, and Ephraim {is} my firstborn. {supplications: or, favours}', 'they shall come with weeping and with supplications will i lead them i will cause them to walk by the rivers of waters in a straight way wherein they shall not stumble for i am a father to israel and ephraim is my firstborn supplications or favours');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 10, 'Hear the word of the LORD, O ye nations, and declare {it} in the isles afar off, and say, He that scattered Israel will gather him, and keep him, as a shepherd {doth} his flock.', 'hear the word of the lord o ye nations and declare it in the isles afar off and say he that scattered israel will gather him and keep him as a shepherd doth his flock');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 11, 'For the LORD hath redeemed Jacob, and ransomed him from the hand of {him that was} stronger than he.', 'for the lord hath redeemed jacob and ransomed him from the hand of him that was stronger than he');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 12, 'Therefore they shall come and sing in the height of Zion, and shall flow together to the goodness of the LORD, for wheat, and for wine, and for oil, and for the young of the flock and of the herd: and their soul shall be as a watered garden; and they shall not sorrow any more at all.', 'therefore they shall come and sing in the height of zion and shall flow together to the goodness of the lord for wheat and for wine and for oil and for the young of the flock and of the herd and their soul shall be as a watered garden and they shall not sorrow any more at all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 13, 'Then shall the virgin rejoice in the dance, both young men and old together: for I will turn their mourning into joy, and will comfort them, and make them rejoice from their sorrow.', 'then shall the virgin rejoice in the dance both young men and old together for i will turn their mourning into joy and will comfort them and make them rejoice from their sorrow');
