INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 15, 'Thus saith the LORD; A voice was heard in Ramah, lamentation, {and} bitter weeping; Rahel weeping for her children refused to be comforted for her children, because they {were} not.', 'thus saith the lord a voice was heard in ramah lamentation and bitter weeping rahel weeping for her children refused to be comforted for her children because they were not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 16, 'Thus saith the LORD; Refrain thy voice from weeping, and thine eyes from tears: for thy work shall be rewarded, saith the LORD; and they shall come again from the land of the enemy.', 'thus saith the lord refrain thy voice from weeping and thine eyes from tears for thy work shall be rewarded saith the lord and they shall come again from the land of the enemy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 17, 'And there is hope in thine end, saith the LORD, that thy children shall come again to their own border.', 'and there is hope in thine end saith the lord that thy children shall come again to their own border');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 18, 'I have surely heard Ephraim bemoaning himself {thus}; Thou hast chastised me, and I was chastised, as a bullock unaccustomed {to the yoke}: turn thou me, and I shall be turned; for thou {art} the LORD my God.', 'i have surely heard ephraim bemoaning himself thus thou hast chastised me and i was chastised as a bullock unaccustomed to the yoke turn thou me and i shall be turned for thou art the lord my god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 19, 'Surely after that I was turned, I repented; and after that I was instructed, I smote upon {my} thigh: I was ashamed, yea, even confounded, because I did bear the reproach of my youth.', 'surely after that i was turned i repented and after that i was instructed i smote upon my thigh i was ashamed yea even confounded because i did bear the reproach of my youth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 20, '{Is} Ephraim my dear son? {is he} a pleasant child? for since I spake against him, I do earnestly remember him still: therefore my bowels are troubled for him; I will surely have mercy upon him, saith the LORD. {are...: Heb. sound}', 'is ephraim my dear son is he a pleasant child for since i spake against him i do earnestly remember him still therefore my bowels are troubled for him i will surely have mercy upon him saith the lord are heb sound');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 21, 'Set thee up waymarks, make thee high heaps: set thine heart toward the highway, {even} the way {which} thou wentest: turn again, O virgin of Israel, turn again to these thy cities.', 'set thee up waymarks make thee high heaps set thine heart toward the highway even the way which thou wentest turn again o virgin of israel turn again to these thy cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 22, 'How long wilt thou go about, O thou backsliding daughter? for the LORD hath created a new thing in the earth, A woman shall compass a man.', 'how long wilt thou go about o thou backsliding daughter for the lord hath created a new thing in the earth a woman shall compass a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 23, 'Thus saith the LORD of hosts, the God of Israel; As yet they shall use this speech in the land of Judah and in the cities thereof, when I shall bring again their captivity; The LORD bless thee, O habitation of justice, {and} mountain of holiness.', 'thus saith the lord of hosts the god of israel as yet they shall use this speech in the land of judah and in the cities thereof when i shall bring again their captivity the lord bless thee o habitation of justice and mountain of holiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 24, 'And there shall dwell in Judah itself, and in all the cities thereof together, husbandmen, and they {that} go forth with flocks.', 'and there shall dwell in judah itself and in all the cities thereof together husbandmen and they that go forth with flocks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 25, 'For I have satiated the weary soul, and I have replenished every sorrowful soul.', 'for i have satiated the weary soul and i have replenished every sorrowful soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 26, 'Upon this I awaked, and beheld; and my sleep was sweet unto me.', 'upon this i awaked and beheld and my sleep was sweet unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 27, 'Behold, the days come, saith the LORD, that I will sow the house of Israel and the house of Judah with the seed of man, and with the seed of beast.', 'behold the days come saith the lord that i will sow the house of israel and the house of judah with the seed of man and with the seed of beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 28, 'And it shall come to pass, {that} like as I have watched over them, to pluck up, and to break down, and to throw down, and to destroy, and to afflict; so will I watch over them, to build, and to plant, saith the LORD.', 'and it shall come to pass that like as i have watched over them to pluck up and to break down and to throw down and to destroy and to afflict so will i watch over them to build and to plant saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 29, 'In those days they shall say no more, The fathers have eaten a sour grape, and the children''s teeth are set on edge.', 'in those days they shall say no more the fathers have eaten a sour grape and the children s teeth are set on edge');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 30, 'But every one shall die for his own iniquity: every man that eateth the sour grape, his teeth shall be set on edge.', 'but every one shall die for his own iniquity every man that eateth the sour grape his teeth shall be set on edge');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 31, 'Behold, the days come, saith the LORD, that I will make a new covenant with the house of Israel, and with the house of Judah:', 'behold the days come saith the lord that i will make a new covenant with the house of israel and with the house of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 32, 'Not according to the covenant that I made with their fathers in the day {that} I took them by the hand to bring them out of the land of Egypt; which my covenant they brake, although I was an husband unto them, saith the LORD: {although...: or, should I have continued an husband unto them?}', 'not according to the covenant that i made with their fathers in the day that i took them by the hand to bring them out of the land of egypt which my covenant they brake although i was an husband unto them saith the lord although or should i have continued an husband unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 33, 'But this {shall be} the covenant that I will make with the house of Israel; After those days, saith the LORD, I will put my law in their inward parts, and write it in their hearts; and will be their God, and they shall be my people.', 'but this shall be the covenant that i will make with the house of israel after those days saith the lord i will put my law in their inward parts and write it in their hearts and will be their god and they shall be my people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 34, 'And they shall teach no more every man his neighbour, and every man his brother, saying, Know the LORD: for they shall all know me, from the least of them unto the greatest of them, saith the LORD: for I will forgive their iniquity, and I will remember their sin no more.', 'and they shall teach no more every man his neighbour and every man his brother saying know the lord for they shall all know me from the least of them unto the greatest of them saith the lord for i will forgive their iniquity and i will remember their sin no more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 35, 'Thus saith the LORD, which giveth the sun for a light by day, {and} the ordinances of the moon and of the stars for a light by night, which divideth the sea when the waves thereof roar; The LORD of hosts {is} his name:', 'thus saith the lord which giveth the sun for a light by day and the ordinances of the moon and of the stars for a light by night which divideth the sea when the waves thereof roar the lord of hosts is his name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 36, 'If those ordinances depart from before me, saith the LORD, {then} the seed of Israel also shall cease from being a nation before me for ever.', 'if those ordinances depart from before me saith the lord then the seed of israel also shall cease from being a nation before me for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 37, 'Thus saith the LORD; If heaven above can be measured, and the foundations of the earth searched out beneath, I will also cast off all the seed of Israel for all that they have done, saith the LORD.', 'thus saith the lord if heaven above can be measured and the foundations of the earth searched out beneath i will also cast off all the seed of israel for all that they have done saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 38, 'Behold, the days come, saith the LORD, that the city shall be built to the LORD from the tower of Hananeel unto the gate of the corner.', 'behold the days come saith the lord that the city shall be built to the lord from the tower of hananeel unto the gate of the corner');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 31, 39, 'And the measuring line shall yet go forth over against it upon the hill Gareb, and shall compass about to Goath.', 'and the measuring line shall yet go forth over against it upon the hill gareb and shall compass about to goath');
