INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 1, 'The word that came to Jeremiah from the LORD in the tenth year of Zedekiah king of Judah, which {was} the eighteenth year of Nebuchadrezzar.', 'the word that came to jeremiah from the lord in the tenth year of zedekiah king of judah which was the eighteenth year of nebuchadrezzar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 2, 'For then the king of Babylon''s army besieged Jerusalem: and Jeremiah the prophet was shut up in the court of the prison, which {was} in the king of Judah''s house.', 'for then the king of babylon s army besieged jerusalem and jeremiah the prophet was shut up in the court of the prison which was in the king of judah s house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 3, 'For Zedekiah king of Judah had shut him up, saying, Wherefore dost thou prophesy, and say, Thus saith the LORD, Behold, I will give this city into the hand of the king of Babylon, and he shall take it;', 'for zedekiah king of judah had shut him up saying wherefore dost thou prophesy and say thus saith the lord behold i will give this city into the hand of the king of babylon and he shall take it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 4, 'And Zedekiah king of Judah shall not escape out of the hand of the Chaldeans, but shall surely be delivered into the hand of the king of Babylon, and shall speak with him mouth to mouth, and his eyes shall behold his eyes;', 'and zedekiah king of judah shall not escape out of the hand of the chaldeans but shall surely be delivered into the hand of the king of babylon and shall speak with him mouth to mouth and his eyes shall behold his eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 5, 'And he shall lead Zedekiah to Babylon, and there shall he be until I visit him, saith the LORD: though ye fight with the Chaldeans, ye shall not prosper.', 'and he shall lead zedekiah to babylon and there shall he be until i visit him saith the lord though ye fight with the chaldeans ye shall not prosper');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 6, 'And Jeremiah said, The word of the LORD came unto me, saying,', 'and jeremiah said the word of the lord came unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 7, 'Behold, Hanameel the son of Shallum thine uncle shall come unto thee, saying, Buy thee my field that {is} in Anathoth: for the right of redemption {is} thine to buy {it}.', 'behold hanameel the son of shallum thine uncle shall come unto thee saying buy thee my field that is in anathoth for the right of redemption is thine to buy it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 8, 'So Hanameel mine uncle''s son came to me in the court of the prison according to the word of the LORD, and said unto me, Buy my field, I pray thee, that {is} in Anathoth, which {is} in the country of Benjamin: for the right of inheritance {is} thine, and the redemption {is} thine; buy {it} for thyself. Then I knew that this {was} the word of the LORD.', 'so hanameel mine uncle s son came to me in the court of the prison according to the word of the lord and said unto me buy my field i pray thee that is in anathoth which is in the country of benjamin for the right of inheritance is thine and the redemption is thine buy it for thyself then i knew that this was the word of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 9, 'And I bought the field of Hanameel my uncle''s son, that {was} in Anathoth, and weighed him the money, {even} seventeen shekels of silver. {seventeen...: or, seven shekels and ten pieces of silver}', 'and i bought the field of hanameel my uncle s son that was in anathoth and weighed him the money even seventeen shekels of silver seventeen or seven shekels and ten pieces of silver');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 10, 'And I subscribed the evidence, and sealed {it}, and took witnesses, and weighed {him} the money in the balances. {subscribed...: Heb. wrote in the book}', 'and i subscribed the evidence and sealed it and took witnesses and weighed him the money in the balances subscribed heb wrote in the book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 11, 'So I took the evidence of the purchase, {both} that which was sealed {according} to the law and custom, and that which was open:', 'so i took the evidence of the purchase both that which was sealed according to the law and custom and that which was open');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 12, 'And I gave the evidence of the purchase unto Baruch the son of Neriah, the son of Maaseiah, in the sight of Hanameel mine uncle''s {son}, and in the presence of the witnesses that subscribed the book of the purchase, before all the Jews that sat in the court of the prison.', 'and i gave the evidence of the purchase unto baruch the son of neriah the son of maaseiah in the sight of hanameel mine uncle s son and in the presence of the witnesses that subscribed the book of the purchase before all the jews that sat in the court of the prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 13, 'And I charged Baruch before them, saying,', 'and i charged baruch before them saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 14, 'Thus saith the LORD of hosts, the God of Israel; Take these evidences, this evidence of the purchase, both which is sealed, and this evidence which is open; and put them in an earthen vessel, that they may continue many days.', 'thus saith the lord of hosts the god of israel take these evidences this evidence of the purchase both which is sealed and this evidence which is open and put them in an earthen vessel that they may continue many days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 15, 'For thus saith the LORD of hosts, the God of Israel; Houses and fields and vineyards shall be possessed again in this land.', 'for thus saith the lord of hosts the god of israel houses and fields and vineyards shall be possessed again in this land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 16, 'Now when I had delivered the evidence of the purchase unto Baruch the son of Neriah, I prayed unto the LORD, saying,', 'now when i had delivered the evidence of the purchase unto baruch the son of neriah i prayed unto the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 17, 'Ah Lord GOD! behold, thou hast made the heaven and the earth by thy great power and stretched out arm, {and} there is nothing too hard for thee: {too...: or, hid from thee}', 'ah lord god behold thou hast made the heaven and the earth by thy great power and stretched out arm and there is nothing too hard for thee too or hid from thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 18, 'Thou shewest lovingkindness unto thousands, and recompensest the iniquity of the fathers into the bosom of their children after them: the Great, the Mighty God, the LORD of hosts, {is} his name,', 'thou shewest lovingkindness unto thousands and recompensest the iniquity of the fathers into the bosom of their children after them the great the mighty god the lord of hosts is his name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 19, 'Great in counsel, and mighty in work: for thine eyes {are} open upon all the ways of the sons of men: to give every one according to his ways, and according to the fruit of his doings: {work: Heb. doing}', 'great in counsel and mighty in work for thine eyes are open upon all the ways of the sons of men to give every one according to his ways and according to the fruit of his doings work heb doing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 20, 'Which hast set signs and wonders in the land of Egypt, {even} unto this day, and in Israel, and among {other} men; and hast made thee a name, as at this day;', 'which hast set signs and wonders in the land of egypt even unto this day and in israel and among other men and hast made thee a name as at this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 21, 'And hast brought forth thy people Israel out of the land of Egypt with signs, and with wonders, and with a strong hand, and with a stretched out arm, and with great terror;', 'and hast brought forth thy people israel out of the land of egypt with signs and with wonders and with a strong hand and with a stretched out arm and with great terror');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 22, 'And hast given them this land, which thou didst swear to their fathers to give them, a land flowing with milk and honey;', 'and hast given them this land which thou didst swear to their fathers to give them a land flowing with milk and honey');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 23, 'And they came in, and possessed it; but they obeyed not thy voice, neither walked in thy law; they have done nothing of all that thou commandedst them to do: therefore thou hast caused all this evil to come upon them:', 'and they came in and possessed it but they obeyed not thy voice neither walked in thy law they have done nothing of all that thou commandedst them to do therefore thou hast caused all this evil to come upon them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 24, 'Behold the mounts, they are come unto the city to take it; and the city is given into the hand of the Chaldeans, that fight against it, because of the sword, and of the famine, and of the pestilence: and what thou hast spoken is come to pass; and, behold, thou seest {it}. {mounts: or, engines of shot}', 'behold the mounts they are come unto the city to take it and the city is given into the hand of the chaldeans that fight against it because of the sword and of the famine and of the pestilence and what thou hast spoken is come to pass and behold thou seest it mounts or engines of shot');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 25, 'And thou hast said unto me, O Lord GOD, Buy thee the field for money, and take witnesses; for the city is given into the hand of the Chaldeans. {for the: or, though the}', 'and thou hast said unto me o lord god buy thee the field for money and take witnesses for the city is given into the hand of the chaldeans for the or though the');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 26, 'Then came the word of the LORD unto Jeremiah, saying,', 'then came the word of the lord unto jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 27, 'Behold, I {am} the LORD, the God of all flesh: is there any thing too hard for me?', 'behold i am the lord the god of all flesh is there any thing too hard for me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 28, 'Therefore thus saith the LORD; Behold, I will give this city into the hand of the Chaldeans, and into the hand of Nebuchadrezzar king of Babylon, and he shall take it:', 'therefore thus saith the lord behold i will give this city into the hand of the chaldeans and into the hand of nebuchadrezzar king of babylon and he shall take it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 29, 'And the Chaldeans, that fight against this city, shall come and set fire on this city, and burn it with the houses, upon whose roofs they have offered incense unto Baal, and poured out drink offerings unto other gods, to provoke me to anger.', 'and the chaldeans that fight against this city shall come and set fire on this city and burn it with the houses upon whose roofs they have offered incense unto baal and poured out drink offerings unto other gods to provoke me to anger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 30, 'For the children of Israel and the children of Judah have only done evil before me from their youth: for the children of Israel have only provoked me to anger with the work of their hands, saith the LORD.', 'for the children of israel and the children of judah have only done evil before me from their youth for the children of israel have only provoked me to anger with the work of their hands saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 31, 'For this city hath been to me {as} a provocation of mine anger and of my fury from the day that they built it even unto this day; that I should remove it from before my face, {a provocation...: Heb. for my anger}', 'for this city hath been to me as a provocation of mine anger and of my fury from the day that they built it even unto this day that i should remove it from before my face a provocation heb for my anger');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 32, 'Because of all the evil of the children of Israel and of the children of Judah, which they have done to provoke me to anger, they, their kings, their princes, their priests, and their prophets, and the men of Judah, and the inhabitants of Jerusalem.', 'because of all the evil of the children of israel and of the children of judah which they have done to provoke me to anger they their kings their princes their priests and their prophets and the men of judah and the inhabitants of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 33, 'And they have turned unto me the back, and not the face: though I taught them, rising up early and teaching {them}, yet they have not hearkened to receive instruction. {back: Heb. neck}', 'and they have turned unto me the back and not the face though i taught them rising up early and teaching them yet they have not hearkened to receive instruction back heb neck');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 34, 'But they set their abominations in the house, which is called by my name, to defile it.', 'but they set their abominations in the house which is called by my name to defile it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 35, 'And they built the high places of Baal, which {are} in the valley of the son of Hinnom, to cause their sons and their daughters to pass through {the fire} unto Molech; which I commanded them not, neither came it into my mind, that they should do this abomination, to cause Judah to sin.', 'and they built the high places of baal which are in the valley of the son of hinnom to cause their sons and their daughters to pass through the fire unto molech which i commanded them not neither came it into my mind that they should do this abomination to cause judah to sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 36, 'And now therefore thus saith the LORD, the God of Israel, concerning this city, whereof ye say, It shall be delivered into the hand of the king of Babylon by the sword, and by the famine, and by the pestilence;', 'and now therefore thus saith the lord the god of israel concerning this city whereof ye say it shall be delivered into the hand of the king of babylon by the sword and by the famine and by the pestilence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 37, 'Behold, I will gather them out of all countries, whither I have driven them in mine anger, and in my fury, and in great wrath; and I will bring them again unto this place, and I will cause them to dwell safely:', 'behold i will gather them out of all countries whither i have driven them in mine anger and in my fury and in great wrath and i will bring them again unto this place and i will cause them to dwell safely');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 38, 'And they shall be my people, and I will be their God:', 'and they shall be my people and i will be their god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 39, 'And I will give them one heart, and one way, that they may fear me for ever, for the good of them, and of their children after them: {for ever: Heb. all days}', 'and i will give them one heart and one way that they may fear me for ever for the good of them and of their children after them for ever heb all days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 40, 'And I will make an everlasting covenant with them, that I will not turn away from them, to do them good; but I will put my fear in their hearts, that they shall not depart from me. {from them: Heb. from after them}', 'and i will make an everlasting covenant with them that i will not turn away from them to do them good but i will put my fear in their hearts that they shall not depart from me from them heb from after them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 41, 'Yea, I will rejoice over them to do them good, and I will plant them in this land assuredly with my whole heart and with my whole soul. {assuredly: Heb. in truth, or, stability}', 'yea i will rejoice over them to do them good and i will plant them in this land assuredly with my whole heart and with my whole soul assuredly heb in truth or stability');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 42, 'For thus saith the LORD; Like as I have brought all this great evil upon this people, so will I bring upon them all the good that I have promised them.', 'for thus saith the lord like as i have brought all this great evil upon this people so will i bring upon them all the good that i have promised them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 43, 'And fields shall be bought in this land, whereof ye say, {It is} desolate without man or beast; it is given into the hand of the Chaldeans.', 'and fields shall be bought in this land whereof ye say it is desolate without man or beast it is given into the hand of the chaldeans');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 32, 44, 'Men shall buy fields for money, and subscribe evidences, and seal {them}, and take witnesses in the land of Benjamin, and in the places about Jerusalem, and in the cities of Judah, and in the cities of the mountains, and in the cities of the valley, and in the cities of the south: for I will cause their captivity to return, saith the LORD.', 'men shall buy fields for money and subscribe evidences and seal them and take witnesses in the land of benjamin and in the places about jerusalem and in the cities of judah and in the cities of the mountains and in the cities of the valley and in the cities of the south for i will cause their captivity to return saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 1, 'Moreover the word of the LORD came unto Jeremiah the second time, while he was yet shut up in the court of the prison, saying,', 'moreover the word of the lord came unto jeremiah the second time while he was yet shut up in the court of the prison saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 2, 'Thus saith the LORD the maker thereof, the LORD that formed it, to establish it; the LORD {is} his name; {the LORD is: or, JEHOVAH, etc}', 'thus saith the lord the maker thereof the lord that formed it to establish it the lord is his name the lord is or jehovah etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 3, 'Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not. {mighty: or, hidden}', 'call unto me and i will answer thee and shew thee great and mighty things which thou knowest not mighty or hidden');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 4, 'For thus saith the LORD, the God of Israel, concerning the houses of this city, and concerning the houses of the kings of Judah, which are thrown down by the mounts, and by the sword;', 'for thus saith the lord the god of israel concerning the houses of this city and concerning the houses of the kings of judah which are thrown down by the mounts and by the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 5, 'They come to fight with the Chaldeans, but {it is} to fill them with the dead bodies of men, whom I have slain in mine anger and in my fury, and for all whose wickedness I have hid my face from this city.', 'they come to fight with the chaldeans but it is to fill them with the dead bodies of men whom i have slain in mine anger and in my fury and for all whose wickedness i have hid my face from this city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 6, 'Behold, I will bring it health and cure, and I will cure them, and will reveal unto them the abundance of peace and truth.', 'behold i will bring it health and cure and i will cure them and will reveal unto them the abundance of peace and truth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 7, 'And I will cause the captivity of Judah and the captivity of Israel to return, and will build them, as at the first.', 'and i will cause the captivity of judah and the captivity of israel to return and will build them as at the first');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 8, 'And I will cleanse them from all their iniquity, whereby they have sinned against me; and I will pardon all their iniquities, whereby they have sinned, and whereby they have transgressed against me.', 'and i will cleanse them from all their iniquity whereby they have sinned against me and i will pardon all their iniquities whereby they have sinned and whereby they have transgressed against me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 9, 'And it shall be to me a name of joy, a praise and an honour before all the nations of the earth, which shall hear all the good that I do unto them: and they shall fear and tremble for all the goodness and for all the prosperity that I procure unto it.', 'and it shall be to me a name of joy a praise and an honour before all the nations of the earth which shall hear all the good that i do unto them and they shall fear and tremble for all the goodness and for all the prosperity that i procure unto it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 10, 'Thus saith the LORD; Again there shall be heard in this place, which ye say {shall be} desolate without man and without beast, {even} in the cities of Judah, and in the streets of Jerusalem, that are desolate, without man, and without inhabitant, and without beast,', 'thus saith the lord again there shall be heard in this place which ye say shall be desolate without man and without beast even in the cities of judah and in the streets of jerusalem that are desolate without man and without inhabitant and without beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 11, 'The voice of joy, and the voice of gladness, the voice of the bridegroom, and the voice of the bride, the voice of them that shall say, Praise the LORD of hosts: for the LORD {is} good; for his mercy {endureth} for ever: {and} of them that shall bring the sacrifice of praise into the house of the LORD. For I will cause to return the captivity of the land, as at the first, saith the LORD.', 'the voice of joy and the voice of gladness the voice of the bridegroom and the voice of the bride the voice of them that shall say praise the lord of hosts for the lord is good for his mercy endureth for ever and of them that shall bring the sacrifice of praise into the house of the lord for i will cause to return the captivity of the land as at the first saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 12, 'Thus saith the LORD of hosts; Again in this place, which is desolate without man and without beast, and in all the cities thereof, shall be an habitation of shepherds causing {their} flocks to lie down.', 'thus saith the lord of hosts again in this place which is desolate without man and without beast and in all the cities thereof shall be an habitation of shepherds causing their flocks to lie down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 13, 'In the cities of the mountains, in the cities of the vale, and in the cities of the south, and in the land of Benjamin, and in the places about Jerusalem, and in the cities of Judah, shall the flocks pass again under the hands of him that telleth {them}, saith the LORD.', 'in the cities of the mountains in the cities of the vale and in the cities of the south and in the land of benjamin and in the places about jerusalem and in the cities of judah shall the flocks pass again under the hands of him that telleth them saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 14, 'Behold, the days come, saith the LORD, that I will perform that good thing which I have promised unto the house of Israel and to the house of Judah.', 'behold the days come saith the lord that i will perform that good thing which i have promised unto the house of israel and to the house of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 15, 'In those days, and at that time, will I cause the Branch of righteousness to grow up unto David; and he shall execute judgment and righteousness in the land.', 'in those days and at that time will i cause the branch of righteousness to grow up unto david and he shall execute judgment and righteousness in the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 16, 'In those days shall Judah be saved, and Jerusalem shall dwell safely: and this {is the name} wherewith she shall be called, The LORD our righteousness. {The LORD...: Heb. Jehovahtsidkenu}', 'in those days shall judah be saved and jerusalem shall dwell safely and this is the name wherewith she shall be called the lord our righteousness the lord heb jehovahtsidkenu');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 17, 'For thus saith the LORD; David shall never want a man to sit upon the throne of the house of Israel; {David...: Heb. There shall not be cut off from David}', 'for thus saith the lord david shall never want a man to sit upon the throne of the house of israel david heb there shall not be cut off from david');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 18, 'Neither shall the priests the Levites want a man before me to offer burnt offerings, and to kindle meat offerings, and to do sacrifice continually.', 'neither shall the priests the levites want a man before me to offer burnt offerings and to kindle meat offerings and to do sacrifice continually');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 19, 'And the word of the LORD came unto Jeremiah, saying,', 'and the word of the lord came unto jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 20, 'Thus saith the LORD; If ye can break my covenant of the day, and my covenant of the night, and that there should not be day and night in their season;', 'thus saith the lord if ye can break my covenant of the day and my covenant of the night and that there should not be day and night in their season');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 21, '{Then} may also my covenant be broken with David my servant, that he should not have a son to reign upon his throne; and with the Levites the priests, my ministers.', 'then may also my covenant be broken with david my servant that he should not have a son to reign upon his throne and with the levites the priests my ministers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 22, 'As the host of heaven cannot be numbered, neither the sand of the sea measured: so will I multiply the seed of David my servant, and the Levites that minister unto me.', 'as the host of heaven cannot be numbered neither the sand of the sea measured so will i multiply the seed of david my servant and the levites that minister unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 23, 'Moreover the word of the LORD came to Jeremiah, saying,', 'moreover the word of the lord came to jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 24, 'Considerest thou not what this people have spoken, saying, The two families which the LORD hath chosen, he hath even cast them off? thus they have despised my people, that they should be no more a nation before them.', 'considerest thou not what this people have spoken saying the two families which the lord hath chosen he hath even cast them off thus they have despised my people that they should be no more a nation before them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 25, 'Thus saith the LORD; If my covenant {be} not with day and night, {and if} I have not appointed the ordinances of heaven and earth;', 'thus saith the lord if my covenant be not with day and night and if i have not appointed the ordinances of heaven and earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 33, 26, 'Then will I cast away the seed of Jacob, and David my servant, {so} that I will not take {any} of his seed {to be} rulers over the seed of Abraham, Isaac, and Jacob: for I will cause their captivity to return, and have mercy on them.', 'then will i cast away the seed of jacob and david my servant so that i will not take any of his seed to be rulers over the seed of abraham isaac and jacob for i will cause their captivity to return and have mercy on them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 1, 'The word which came unto Jeremiah from the LORD, when Nebuchadnezzar king of Babylon, and all his army, and all the kingdoms of the earth of his dominion, and all the people, fought against Jerusalem, and against all the cities thereof, saying, {of his...: Heb. the dominion of his hand}', 'the word which came unto jeremiah from the lord when nebuchadnezzar king of babylon and all his army and all the kingdoms of the earth of his dominion and all the people fought against jerusalem and against all the cities thereof saying of his heb the dominion of his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 2, 'Thus saith the LORD, the God of Israel; Go and speak to Zedekiah king of Judah, and tell him, Thus saith the LORD; Behold, I will give this city into the hand of the king of Babylon, and he shall burn it with fire:', 'thus saith the lord the god of israel go and speak to zedekiah king of judah and tell him thus saith the lord behold i will give this city into the hand of the king of babylon and he shall burn it with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 3, 'And thou shalt not escape out of his hand, but shalt surely be taken, and delivered into his hand; and thine eyes shall behold the eyes of the king of Babylon, and he shall speak with thee mouth to mouth, and thou shalt go to Babylon. {he shall...: Heb. his mouth shall speak to thy mouth}', 'and thou shalt not escape out of his hand but shalt surely be taken and delivered into his hand and thine eyes shall behold the eyes of the king of babylon and he shall speak with thee mouth to mouth and thou shalt go to babylon he shall heb his mouth shall speak to thy mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 4, 'Yet hear the word of the LORD, O Zedekiah king of Judah; Thus saith the LORD of thee, Thou shalt not die by the sword:', 'yet hear the word of the lord o zedekiah king of judah thus saith the lord of thee thou shalt not die by the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 5, '{But} thou shalt die in peace: and with the burnings of thy fathers, the former kings which were before thee, so shall they burn {odours} for thee; and they will lament thee, {saying}, Ah lord! for I have pronounced the word, saith the LORD.', 'but thou shalt die in peace and with the burnings of thy fathers the former kings which were before thee so shall they burn odours for thee and they will lament thee saying ah lord for i have pronounced the word saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 6, 'Then Jeremiah the prophet spake all these words unto Zedekiah king of Judah in Jerusalem,', 'then jeremiah the prophet spake all these words unto zedekiah king of judah in jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 7, 'When the king of Babylon''s army fought against Jerusalem, and against all the cities of Judah that were left, against Lachish, and against Azekah: for these defenced cities remained of the cities of Judah.', 'when the king of babylon s army fought against jerusalem and against all the cities of judah that were left against lachish and against azekah for these defenced cities remained of the cities of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 8, '{This is} the word that came unto Jeremiah from the LORD, after that the king Zedekiah had made a covenant with all the people which {were} at Jerusalem, to proclaim liberty unto them;', 'this is the word that came unto jeremiah from the lord after that the king zedekiah had made a covenant with all the people which were at jerusalem to proclaim liberty unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 9, 'That every man should let his manservant, and every man his maidservant, {being} an Hebrew or an Hebrewess, go free; that none should serve himself of them, {to wit}, of a Jew his brother.', 'that every man should let his manservant and every man his maidservant being an hebrew or an hebrewess go free that none should serve himself of them to wit of a jew his brother');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 10, 'Now when all the princes, and all the people, which had entered into the covenant, heard that every one should let his manservant, and every one his maidservant, go free, that none should serve themselves of them any more, then they obeyed, and let {them} go.', 'now when all the princes and all the people which had entered into the covenant heard that every one should let his manservant and every one his maidservant go free that none should serve themselves of them any more then they obeyed and let them go');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 11, 'But afterward they turned, and caused the servants and the handmaids, whom they had let go free, to return, and brought them into subjection for servants and for handmaids.', 'but afterward they turned and caused the servants and the handmaids whom they had let go free to return and brought them into subjection for servants and for handmaids');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 12, 'Therefore the word of the LORD came to Jeremiah from the LORD, saying,', 'therefore the word of the lord came to jeremiah from the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 13, 'Thus saith the LORD, the God of Israel; I made a covenant with your fathers in the day that I brought them forth out of the land of Egypt, out of the house of bondmen, saying,', 'thus saith the lord the god of israel i made a covenant with your fathers in the day that i brought them forth out of the land of egypt out of the house of bondmen saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 14, 'At the end of seven years let ye go every man his brother an Hebrew, which hath been sold unto thee; and when he hath served thee six years, thou shalt let him go free from thee: but your fathers hearkened not unto me, neither inclined their ear. {hath been...: or, hath sold himself}', 'at the end of seven years let ye go every man his brother an hebrew which hath been sold unto thee and when he hath served thee six years thou shalt let him go free from thee but your fathers hearkened not unto me neither inclined their ear hath been or hath sold himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 15, 'And ye were now turned, and had done right in my sight, in proclaiming liberty every man to his neighbour; and ye had made a covenant before me in the house which is called by my name: {now: Heb. to day} {which...: Heb. whereupon my name is called}', 'and ye were now turned and had done right in my sight in proclaiming liberty every man to his neighbour and ye had made a covenant before me in the house which is called by my name now heb to day which heb whereupon my name is called');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 16, 'But ye turned and polluted my name, and caused every man his servant, and every man his handmaid, whom ye had set at liberty at their pleasure, to return, and brought them into subjection, to be unto you for servants and for handmaids.', 'but ye turned and polluted my name and caused every man his servant and every man his handmaid whom ye had set at liberty at their pleasure to return and brought them into subjection to be unto you for servants and for handmaids');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 17, 'Therefore thus saith the LORD; Ye have not hearkened unto me, in proclaiming liberty, every one to his brother, and every man to his neighbour: behold, I proclaim a liberty for you, saith the LORD, to the sword, to the pestilence, and to the famine; and I will make you to be removed into all the kingdoms of the earth. {to be...: Heb. for a removing}', 'therefore thus saith the lord ye have not hearkened unto me in proclaiming liberty every one to his brother and every man to his neighbour behold i proclaim a liberty for you saith the lord to the sword to the pestilence and to the famine and i will make you to be removed into all the kingdoms of the earth to be heb for a removing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 18, 'And I will give the men that have transgressed my covenant, which have not performed the words of the covenant which they had made before me, when they cut the calf in twain, and passed between the parts thereof,', 'and i will give the men that have transgressed my covenant which have not performed the words of the covenant which they had made before me when they cut the calf in twain and passed between the parts thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 19, 'The princes of Judah, and the princes of Jerusalem, the eunuchs, and the priests, and all the people of the land, which passed between the parts of the calf;', 'the princes of judah and the princes of jerusalem the eunuchs and the priests and all the people of the land which passed between the parts of the calf');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 20, 'I will even give them into the hand of their enemies, and into the hand of them that seek their life: and their dead bodies shall be for meat unto the fowls of the heaven, and to the beasts of the earth.', 'i will even give them into the hand of their enemies and into the hand of them that seek their life and their dead bodies shall be for meat unto the fowls of the heaven and to the beasts of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 21, 'And Zedekiah king of Judah and his princes will I give into the hand of their enemies, and into the hand of them that seek their life, and into the hand of the king of Babylon''s army, which are gone up from you.', 'and zedekiah king of judah and his princes will i give into the hand of their enemies and into the hand of them that seek their life and into the hand of the king of babylon s army which are gone up from you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 34, 22, 'Behold, I will command, saith the LORD, and cause them to return to this city; and they shall fight against it, and take it, and burn it with fire: and I will make the cities of Judah a desolation without an inhabitant.', 'behold i will command saith the lord and cause them to return to this city and they shall fight against it and take it and burn it with fire and i will make the cities of judah a desolation without an inhabitant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 1, 'The word which came unto Jeremiah from the LORD in the days of Jehoiakim the son of Josiah king of Judah, saying,', 'the word which came unto jeremiah from the lord in the days of jehoiakim the son of josiah king of judah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 2, 'Go unto the house of the Rechabites, and speak unto them, and bring them into the house of the LORD, into one of the chambers, and give them wine to drink.', 'go unto the house of the rechabites and speak unto them and bring them into the house of the lord into one of the chambers and give them wine to drink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 3, 'Then I took Jaazaniah the son of Jeremiah, the son of Habaziniah, and his brethren, and all his sons, and the whole house of the Rechabites;', 'then i took jaazaniah the son of jeremiah the son of habaziniah and his brethren and all his sons and the whole house of the rechabites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 4, 'And I brought them into the house of the LORD, into the chamber of the sons of Hanan, the son of Igdaliah, a man of God, which {was} by the chamber of the princes, which {was} above the chamber of Maaseiah the son of Shallum, the keeper of the door: {door: Heb. threshold, or, vessel}', 'and i brought them into the house of the lord into the chamber of the sons of hanan the son of igdaliah a man of god which was by the chamber of the princes which was above the chamber of maaseiah the son of shallum the keeper of the door door heb threshold or vessel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 5, 'And I set before the sons of the house of the Rechabites pots full of wine, and cups, and I said unto them, Drink ye wine.', 'and i set before the sons of the house of the rechabites pots full of wine and cups and i said unto them drink ye wine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 6, 'But they said, We will drink no wine: for Jonadab the son of Rechab our father commanded us, saying, Ye shall drink no wine, {neither ye}, nor your sons for ever:', 'but they said we will drink no wine for jonadab the son of rechab our father commanded us saying ye shall drink no wine neither ye nor your sons for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 7, 'Neither shall ye build house, nor sow seed, nor plant vineyard, nor have {any}: but all your days ye shall dwell in tents; that ye may live many days in the land where ye {be} strangers.', 'neither shall ye build house nor sow seed nor plant vineyard nor have any but all your days ye shall dwell in tents that ye may live many days in the land where ye be strangers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 8, 'Thus have we obeyed the voice of Jonadab the son of Rechab our father in all that he hath charged us, to drink no wine all our days, we, our wives, our sons, nor our daughters;', 'thus have we obeyed the voice of jonadab the son of rechab our father in all that he hath charged us to drink no wine all our days we our wives our sons nor our daughters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 9, 'Nor to build houses for us to dwell in: neither have we vineyard, nor field, nor seed:', 'nor to build houses for us to dwell in neither have we vineyard nor field nor seed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 10, 'But we have dwelt in tents, and have obeyed, and done according to all that Jonadab our father commanded us.', 'but we have dwelt in tents and have obeyed and done according to all that jonadab our father commanded us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 11, 'But it came to pass, when Nebuchadrezzar king of Babylon came up into the land, that we said, Come, and let us go to Jerusalem for fear of the army of the Chaldeans, and for fear of the army of the Syrians: so we dwell at Jerusalem.', 'but it came to pass when nebuchadrezzar king of babylon came up into the land that we said come and let us go to jerusalem for fear of the army of the chaldeans and for fear of the army of the syrians so we dwell at jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 12, 'Then came the word of the LORD unto Jeremiah, saying,', 'then came the word of the lord unto jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 13, 'Thus saith the LORD of hosts, the God of Israel; Go and tell the men of Judah and the inhabitants of Jerusalem, Will ye not receive instruction to hearken to my words? saith the LORD.', 'thus saith the lord of hosts the god of israel go and tell the men of judah and the inhabitants of jerusalem will ye not receive instruction to hearken to my words saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 14, 'The words of Jonadab the son of Rechab, that he commanded his sons not to drink wine, are performed; for unto this day they drink none, but obey their father''s commandment: notwithstanding I have spoken unto you, rising early and speaking; but ye hearkened not unto me.', 'the words of jonadab the son of rechab that he commanded his sons not to drink wine are performed for unto this day they drink none but obey their father s commandment notwithstanding i have spoken unto you rising early and speaking but ye hearkened not unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 15, 'I have sent also unto you all my servants the prophets, rising up early and sending {them}, saying, Return ye now every man from his evil way, and amend your doings, and go not after other gods to serve them, and ye shall dwell in the land which I have given to you and to your fathers: but ye have not inclined your ear, nor hearkened unto me.', 'i have sent also unto you all my servants the prophets rising up early and sending them saying return ye now every man from his evil way and amend your doings and go not after other gods to serve them and ye shall dwell in the land which i have given to you and to your fathers but ye have not inclined your ear nor hearkened unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 16, 'Because the sons of Jonadab the son of Rechab have performed the commandment of their father, which he commanded them; but this people hath not hearkened unto me:', 'because the sons of jonadab the son of rechab have performed the commandment of their father which he commanded them but this people hath not hearkened unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 17, 'Therefore thus saith the LORD God of hosts, the God of Israel; Behold, I will bring upon Judah and upon all the inhabitants of Jerusalem all the evil that I have pronounced against them: because I have spoken unto them, but they have not heard; and I have called unto them, but they have not answered.', 'therefore thus saith the lord god of hosts the god of israel behold i will bring upon judah and upon all the inhabitants of jerusalem all the evil that i have pronounced against them because i have spoken unto them but they have not heard and i have called unto them but they have not answered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 18, 'And Jeremiah said unto the house of the Rechabites, Thus saith the LORD of hosts, the God of Israel; Because ye have obeyed the commandment of Jonadab your father, and kept all his precepts, and done according unto all that he hath commanded you:', 'and jeremiah said unto the house of the rechabites thus saith the lord of hosts the god of israel because ye have obeyed the commandment of jonadab your father and kept all his precepts and done according unto all that he hath commanded you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 35, 19, 'Therefore thus saith the LORD of hosts, the God of Israel; Jonadab the son of Rechab shall not want a man to stand before me for ever. {Jonadab...: Heb. There shall not a man be cut off from Jonadab the son of Rechab to stand, etc}', 'therefore thus saith the lord of hosts the god of israel jonadab the son of rechab shall not want a man to stand before me for ever jonadab heb there shall not a man be cut off from jonadab the son of rechab to stand etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 1, 'And it came to pass in the fourth year of Jehoiakim the son of Josiah king of Judah, {that} this word came unto Jeremiah from the LORD, saying,', 'and it came to pass in the fourth year of jehoiakim the son of josiah king of judah that this word came unto jeremiah from the lord saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 2, 'Take thee a roll of a book, and write therein all the words that I have spoken unto thee against Israel, and against Judah, and against all the nations, from the day I spake unto thee, from the days of Josiah, even unto this day.', 'take thee a roll of a book and write therein all the words that i have spoken unto thee against israel and against judah and against all the nations from the day i spake unto thee from the days of josiah even unto this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 3, 'It may be that the house of Judah will hear all the evil which I purpose to do unto them; that they may return every man from his evil way; that I may forgive their iniquity and their sin.', 'it may be that the house of judah will hear all the evil which i purpose to do unto them that they may return every man from his evil way that i may forgive their iniquity and their sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 4, 'Then Jeremiah called Baruch the son of Neriah: and Baruch wrote from the mouth of Jeremiah all the words of the LORD, which he had spoken unto him, upon a roll of a book.', 'then jeremiah called baruch the son of neriah and baruch wrote from the mouth of jeremiah all the words of the lord which he had spoken unto him upon a roll of a book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 5, 'And Jeremiah commanded Baruch, saying, I {am} shut up; I cannot go into the house of the LORD:', 'and jeremiah commanded baruch saying i am shut up i cannot go into the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 6, 'Therefore go thou, and read in the roll, which thou hast written from my mouth, the words of the LORD in the ears of the people in the LORD''S house upon the fasting day: and also thou shalt read them in the ears of all Judah that come out of their cities.', 'therefore go thou and read in the roll which thou hast written from my mouth the words of the lord in the ears of the people in the lord s house upon the fasting day and also thou shalt read them in the ears of all judah that come out of their cities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 7, 'It may be they will present their supplication before the LORD, and will return every one from his evil way: for great {is} the anger and the fury that the LORD hath pronounced against this people. {they...: Heb. their supplication shall fail}', 'it may be they will present their supplication before the lord and will return every one from his evil way for great is the anger and the fury that the lord hath pronounced against this people they heb their supplication shall fail');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 8, 'And Baruch the son of Neriah did according to all that Jeremiah the prophet commanded him, reading in the book the words of the LORD in the LORD''S house.', 'and baruch the son of neriah did according to all that jeremiah the prophet commanded him reading in the book the words of the lord in the lord s house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 9, 'And it came to pass in the fifth year of Jehoiakim the son of Josiah king of Judah, in the ninth month, {that} they proclaimed a fast before the LORD to all the people in Jerusalem, and to all the people that came from the cities of Judah unto Jerusalem.', 'and it came to pass in the fifth year of jehoiakim the son of josiah king of judah in the ninth month that they proclaimed a fast before the lord to all the people in jerusalem and to all the people that came from the cities of judah unto jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 10, 'Then read Baruch in the book the words of Jeremiah in the house of the LORD, in the chamber of Gemariah the son of Shaphan the scribe, in the higher court, at the entry of the new gate of the LORD''S house, in the ears of all the people. {entry: or, door}', 'then read baruch in the book the words of jeremiah in the house of the lord in the chamber of gemariah the son of shaphan the scribe in the higher court at the entry of the new gate of the lord s house in the ears of all the people entry or door');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 11, 'When Michaiah the son of Gemariah, the son of Shaphan, had heard out of the book all the words of the LORD,', 'when michaiah the son of gemariah the son of shaphan had heard out of the book all the words of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 12, 'Then he went down into the king''s house, into the scribe''s chamber: and, lo, all the princes sat there, {even} Elishama the scribe, and Delaiah the son of Shemaiah, and Elnathan the son of Achbor, and Gemariah the son of Shaphan, and Zedekiah the son of Hananiah, and all the princes.', 'then he went down into the king s house into the scribe s chamber and lo all the princes sat there even elishama the scribe and delaiah the son of shemaiah and elnathan the son of achbor and gemariah the son of shaphan and zedekiah the son of hananiah and all the princes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 13, 'Then Michaiah declared unto them all the words that he had heard, when Baruch read the book in the ears of the people.', 'then michaiah declared unto them all the words that he had heard when baruch read the book in the ears of the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 14, 'Therefore all the princes sent Jehudi the son of Nethaniah, the son of Shelemiah, the son of Cushi, unto Baruch, saying, Take in thine hand the roll wherein thou hast read in the ears of the people, and come. So Baruch the son of Neriah took the roll in his hand, and came unto them.', 'therefore all the princes sent jehudi the son of nethaniah the son of shelemiah the son of cushi unto baruch saying take in thine hand the roll wherein thou hast read in the ears of the people and come so baruch the son of neriah took the roll in his hand and came unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 15, 'And they said unto him, Sit down now, and read it in our ears. So Baruch read {it} in their ears.', 'and they said unto him sit down now and read it in our ears so baruch read it in their ears');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 16, 'Now it came to pass, when they had heard all the words, they were afraid both one and other, and said unto Baruch, We will surely tell the king of all these words.', 'now it came to pass when they had heard all the words they were afraid both one and other and said unto baruch we will surely tell the king of all these words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 17, 'And they asked Baruch, saying, Tell us now, How didst thou write all these words at his mouth?', 'and they asked baruch saying tell us now how didst thou write all these words at his mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 18, 'Then Baruch answered them, He pronounced all these words unto me with his mouth, and I wrote {them} with ink in the book.', 'then baruch answered them he pronounced all these words unto me with his mouth and i wrote them with ink in the book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 19, 'Then said the princes unto Baruch, Go, hide thee, thou and Jeremiah; and let no man know where ye be.', 'then said the princes unto baruch go hide thee thou and jeremiah and let no man know where ye be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 20, 'And they went in to the king into the court, but they laid up the roll in the chamber of Elishama the scribe, and told all the words in the ears of the king.', 'and they went in to the king into the court but they laid up the roll in the chamber of elishama the scribe and told all the words in the ears of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 21, 'So the king sent Jehudi to fetch the roll: and he took it out of Elishama the scribe''s chamber. And Jehudi read it in the ears of the king, and in the ears of all the princes which stood beside the king.', 'so the king sent jehudi to fetch the roll and he took it out of elishama the scribe s chamber and jehudi read it in the ears of the king and in the ears of all the princes which stood beside the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 22, 'Now the king sat in the winterhouse in the ninth month: and {there was a fire} on the hearth burning before him.', 'now the king sat in the winterhouse in the ninth month and there was a fire on the hearth burning before him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 23, 'And it came to pass, {that} when Jehudi had read three or four leaves, he cut it with the penknife, and cast {it} into the fire that {was} on the hearth, until all the roll was consumed in the fire that {was} on the hearth.', 'and it came to pass that when jehudi had read three or four leaves he cut it with the penknife and cast it into the fire that was on the hearth until all the roll was consumed in the fire that was on the hearth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 24, 'Yet they were not afraid, nor rent their garments, {neither} the king, nor any of his servants that heard all these words.', 'yet they were not afraid nor rent their garments neither the king nor any of his servants that heard all these words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 25, 'Nevertheless Elnathan and Delaiah and Gemariah had made intercession to the king that he would not burn the roll: but he would not hear them.', 'nevertheless elnathan and delaiah and gemariah had made intercession to the king that he would not burn the roll but he would not hear them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 26, 'But the king commanded Jerahmeel the son of Hammelech, and Seraiah the son of Azriel, and Shelemiah the son of Abdeel, to take Baruch the scribe and Jeremiah the prophet: but the LORD hid them. {of Hammelech: or, of the king}', 'but the king commanded jerahmeel the son of hammelech and seraiah the son of azriel and shelemiah the son of abdeel to take baruch the scribe and jeremiah the prophet but the lord hid them of hammelech or of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 27, 'Then the word of the LORD came to Jeremiah, after that the king had burned the roll, and the words which Baruch wrote at the mouth of Jeremiah, saying,', 'then the word of the lord came to jeremiah after that the king had burned the roll and the words which baruch wrote at the mouth of jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 28, 'Take thee again another roll, and write in it all the former words that were in the first roll, which Jehoiakim the king of Judah hath burned.', 'take thee again another roll and write in it all the former words that were in the first roll which jehoiakim the king of judah hath burned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 29, 'And thou shalt say to Jehoiakim king of Judah, Thus saith the LORD; Thou hast burned this roll, saying, Why hast thou written therein, saying, The king of Babylon shall certainly come and destroy this land, and shall cause to cease from thence man and beast?', 'and thou shalt say to jehoiakim king of judah thus saith the lord thou hast burned this roll saying why hast thou written therein saying the king of babylon shall certainly come and destroy this land and shall cause to cease from thence man and beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 30, 'Therefore thus saith the LORD of Jehoiakim king of Judah; He shall have none to sit upon the throne of David: and his dead body shall be cast out in the day to the heat, and in the night to the frost.', 'therefore thus saith the lord of jehoiakim king of judah he shall have none to sit upon the throne of david and his dead body shall be cast out in the day to the heat and in the night to the frost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 31, 'And I will punish him and his seed and his servants for their iniquity; and I will bring upon them, and upon the inhabitants of Jerusalem, and upon the men of Judah, all the evil that I have pronounced against them; but they hearkened not. {punish: Heb. visit upon}', 'and i will punish him and his seed and his servants for their iniquity and i will bring upon them and upon the inhabitants of jerusalem and upon the men of judah all the evil that i have pronounced against them but they hearkened not punish heb visit upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 36, 32, 'Then took Jeremiah another roll, and gave it to Baruch the scribe, the son of Neriah; who wrote therein from the mouth of Jeremiah all the words of the book which Jehoiakim king of Judah had burned in the fire: and there were added besides unto them many like words. {like: Heb. as they}', 'then took jeremiah another roll and gave it to baruch the scribe the son of neriah who wrote therein from the mouth of jeremiah all the words of the book which jehoiakim king of judah had burned in the fire and there were added besides unto them many like words like heb as they');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 1, 'And king Zedekiah the son of Josiah reigned instead of Coniah the son of Jehoiakim, whom Nebuchadrezzar king of Babylon made king in the land of Judah.', 'and king zedekiah the son of josiah reigned instead of coniah the son of jehoiakim whom nebuchadrezzar king of babylon made king in the land of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 2, 'But neither he, nor his servants, nor the people of the land, did hearken unto the words of the LORD, which he spake by the prophet Jeremiah. {by...: Heb. by the hand of the prophet}', 'but neither he nor his servants nor the people of the land did hearken unto the words of the lord which he spake by the prophet jeremiah by heb by the hand of the prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 3, 'And Zedekiah the king sent Jehucal the son of Shelemiah and Zephaniah the son of Maaseiah the priest to the prophet Jeremiah, saying, Pray now unto the LORD our God for us.', 'and zedekiah the king sent jehucal the son of shelemiah and zephaniah the son of maaseiah the priest to the prophet jeremiah saying pray now unto the lord our god for us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 4, 'Now Jeremiah came in and went out among the people: for they had not put him into prison.', 'now jeremiah came in and went out among the people for they had not put him into prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 5, 'Then Pharaoh''s army was come forth out of Egypt: and when the Chaldeans that besieged Jerusalem heard tidings of them, they departed from Jerusalem.', 'then pharaoh s army was come forth out of egypt and when the chaldeans that besieged jerusalem heard tidings of them they departed from jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 6, 'Then came the word of the LORD unto the prophet Jeremiah, saying,', 'then came the word of the lord unto the prophet jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 7, 'Thus saith the LORD, the God of Israel; Thus shall ye say to the king of Judah, that sent you unto me to enquire of me; Behold, Pharaoh''s army, which is come forth to help you, shall return to Egypt into their own land.', 'thus saith the lord the god of israel thus shall ye say to the king of judah that sent you unto me to enquire of me behold pharaoh s army which is come forth to help you shall return to egypt into their own land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 8, 'And the Chaldeans shall come again, and fight against this city, and take it, and burn it with fire.', 'and the chaldeans shall come again and fight against this city and take it and burn it with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 9, 'Thus saith the LORD; Deceive not yourselves, saying, The Chaldeans shall surely depart from us: for they shall not depart. {yourselves: Heb. your souls}', 'thus saith the lord deceive not yourselves saying the chaldeans shall surely depart from us for they shall not depart yourselves heb your souls');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 10, 'For though ye had smitten the whole army of the Chaldeans that fight against you, and there remained {but} wounded men among them, {yet} should they rise up every man in his tent, and burn this city with fire. {wounded: Heb. thrust through}', 'for though ye had smitten the whole army of the chaldeans that fight against you and there remained but wounded men among them yet should they rise up every man in his tent and burn this city with fire wounded heb thrust through');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 11, 'And it came to pass, that when the army of the Chaldeans was broken up from Jerusalem for fear of Pharaoh''s army, {broken...: Heb. made to ascend}', 'and it came to pass that when the army of the chaldeans was broken up from jerusalem for fear of pharaoh s army broken heb made to ascend');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 12, 'Then Jeremiah went forth out of Jerusalem to go into the land of Benjamin, to separate himself thence in the midst of the people. {separate...: or, to slip away from thence in the midst of the people}', 'then jeremiah went forth out of jerusalem to go into the land of benjamin to separate himself thence in the midst of the people separate or to slip away from thence in the midst of the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 13, 'And when he was in the gate of Benjamin, a captain of the ward {was} there, whose name {was} Irijah, the son of Shelemiah, the son of Hananiah; and he took Jeremiah the prophet, saying, Thou fallest away to the Chaldeans.', 'and when he was in the gate of benjamin a captain of the ward was there whose name was irijah the son of shelemiah the son of hananiah and he took jeremiah the prophet saying thou fallest away to the chaldeans');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 14, 'Then said Jeremiah, {It is} false; I fall not away to the Chaldeans. But he hearkened not to him: so Irijah took Jeremiah, and brought him to the princes. {false: Heb. falsehood, or, a lie}', 'then said jeremiah it is false i fall not away to the chaldeans but he hearkened not to him so irijah took jeremiah and brought him to the princes false heb falsehood or a lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 15, 'Wherefore the princes were wroth with Jeremiah, and smote him, and put him in prison in the house of Jonathan the scribe: for they had made that the prison.', 'wherefore the princes were wroth with jeremiah and smote him and put him in prison in the house of jonathan the scribe for they had made that the prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 16, 'When Jeremiah was entered into the dungeon, and into the cabins, and Jeremiah had remained there many days; {cabins: or, cells}', 'when jeremiah was entered into the dungeon and into the cabins and jeremiah had remained there many days cabins or cells');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 17, 'Then Zedekiah the king sent, and took him out: and the king asked him secretly in his house, and said, Is there {any} word from the LORD? And Jeremiah said, There is: for, said he, thou shalt be delivered into the hand of the king of Babylon.', 'then zedekiah the king sent and took him out and the king asked him secretly in his house and said is there any word from the lord and jeremiah said there is for said he thou shalt be delivered into the hand of the king of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 18, 'Moreover Jeremiah said unto king Zedekiah, What have I offended against thee, or against thy servants, or against this people, that ye have put me in prison?', 'moreover jeremiah said unto king zedekiah what have i offended against thee or against thy servants or against this people that ye have put me in prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 19, 'Where {are} now your prophets which prophesied unto you, saying, The king of Babylon shall not come against you, nor against this land?', 'where are now your prophets which prophesied unto you saying the king of babylon shall not come against you nor against this land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 20, 'Therefore hear now, I pray thee, O my lord the king: let my supplication, I pray thee, be accepted before thee; that thou cause me not to return to the house of Jonathan the scribe, lest I die there. {let...: Heb. let my supplication fall}', 'therefore hear now i pray thee o my lord the king let my supplication i pray thee be accepted before thee that thou cause me not to return to the house of jonathan the scribe lest i die there let heb let my supplication fall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 37, 21, 'Then Zedekiah the king commanded that they should commit Jeremiah into the court of the prison, and that they should give him daily a piece of bread out of the bakers'' street, until all the bread in the city were spent. Thus Jeremiah remained in the court of the prison.', 'then zedekiah the king commanded that they should commit jeremiah into the court of the prison and that they should give him daily a piece of bread out of the bakers street until all the bread in the city were spent thus jeremiah remained in the court of the prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 1, 'Then Shephatiah the son of Mattan, and Gedaliah the son of Pashur, and Jucal the son of Shelemiah, and Pashur the son of Malchiah, heard the words that Jeremiah had spoken unto all the people, saying,', 'then shephatiah the son of mattan and gedaliah the son of pashur and jucal the son of shelemiah and pashur the son of malchiah heard the words that jeremiah had spoken unto all the people saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 2, 'Thus saith the LORD, He that remaineth in this city shall die by the sword, by the famine, and by the pestilence: but he that goeth forth to the Chaldeans shall live; for he shall have his life for a prey, and shall live.', 'thus saith the lord he that remaineth in this city shall die by the sword by the famine and by the pestilence but he that goeth forth to the chaldeans shall live for he shall have his life for a prey and shall live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 3, 'Thus saith the LORD, This city shall surely be given into the hand of the king of Babylon''s army, which shall take it.', 'thus saith the lord this city shall surely be given into the hand of the king of babylon s army which shall take it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 4, 'Therefore the princes said unto the king, We beseech thee, let this man be put to death: for thus he weakeneth the hands of the men of war that remain in this city, and the hands of all the people, in speaking such words unto them: for this man seeketh not the welfare of this people, but the hurt. {welfare: Heb. peace}', 'therefore the princes said unto the king we beseech thee let this man be put to death for thus he weakeneth the hands of the men of war that remain in this city and the hands of all the people in speaking such words unto them for this man seeketh not the welfare of this people but the hurt welfare heb peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 5, 'Then Zedekiah the king said, Behold, he {is} in your hand: for the king {is} not {he that} can do {any} thing against you.', 'then zedekiah the king said behold he is in your hand for the king is not he that can do any thing against you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 6, 'Then took they Jeremiah, and cast him into the dungeon of Malchiah the son of Hammelech, that {was} in the court of the prison: and they let down Jeremiah with cords. And in the dungeon {there was} no water, but mire: so Jeremiah sunk in the mire. {of Hammelech: or, of the king}', 'then took they jeremiah and cast him into the dungeon of malchiah the son of hammelech that was in the court of the prison and they let down jeremiah with cords and in the dungeon there was no water but mire so jeremiah sunk in the mire of hammelech or of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 7, 'Now when Ebedmelech the Ethiopian, one of the eunuchs which was in the king''s house, heard that they had put Jeremiah in the dungeon; the king then sitting in the gate of Benjamin;', 'now when ebedmelech the ethiopian one of the eunuchs which was in the king s house heard that they had put jeremiah in the dungeon the king then sitting in the gate of benjamin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 8, 'Ebedmelech went forth out of the king''s house, and spake to the king, saying,', 'ebedmelech went forth out of the king s house and spake to the king saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 9, 'My lord the king, these men have done evil in all that they have done to Jeremiah the prophet, whom they have cast into the dungeon; and he is like to die for hunger in the place where he is: for {there is} no more bread in the city. {he is like...: Heb. he will die}', 'my lord the king these men have done evil in all that they have done to jeremiah the prophet whom they have cast into the dungeon and he is like to die for hunger in the place where he is for there is no more bread in the city he is like heb he will die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 10, 'Then the king commanded Ebedmelech the Ethiopian, saying, Take from hence thirty men with thee, and take up Jeremiah the prophet out of the dungeon, before he die. {with thee: Heb. in thine hand}', 'then the king commanded ebedmelech the ethiopian saying take from hence thirty men with thee and take up jeremiah the prophet out of the dungeon before he die with thee heb in thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 11, 'So Ebedmelech took the men with him, and went into the house of the king under the treasury, and took thence old cast clouts and old rotten rags, and let them down by cords into the dungeon to Jeremiah.', 'so ebedmelech took the men with him and went into the house of the king under the treasury and took thence old cast clouts and old rotten rags and let them down by cords into the dungeon to jeremiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 12, 'And Ebedmelech the Ethiopian said unto Jeremiah, Put now {these} old cast clouts and rotten rags under thine armholes under the cords. And Jeremiah did so.', 'and ebedmelech the ethiopian said unto jeremiah put now these old cast clouts and rotten rags under thine armholes under the cords and jeremiah did so');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 13, 'So they drew up Jeremiah with cords, and took him up out of the dungeon: and Jeremiah remained in the court of the prison.', 'so they drew up jeremiah with cords and took him up out of the dungeon and jeremiah remained in the court of the prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 14, 'Then Zedekiah the king sent, and took Jeremiah the prophet unto him into the third entry that {is} in the house of the LORD: and the king said unto Jeremiah, I will ask thee a thing; hide nothing from me. {third: or, principal}', 'then zedekiah the king sent and took jeremiah the prophet unto him into the third entry that is in the house of the lord and the king said unto jeremiah i will ask thee a thing hide nothing from me third or principal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 15, 'Then Jeremiah said unto Zedekiah, If I declare {it} unto thee, wilt thou not surely put me to death? and if I give thee counsel, wilt thou not hearken unto me?', 'then jeremiah said unto zedekiah if i declare it unto thee wilt thou not surely put me to death and if i give thee counsel wilt thou not hearken unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 16, 'So Zedekiah the king sware secretly unto Jeremiah, saying, {As} the LORD liveth, that made us this soul, I will not put thee to death, neither will I give thee into the hand of these men that seek thy life.', 'so zedekiah the king sware secretly unto jeremiah saying as the lord liveth that made us this soul i will not put thee to death neither will i give thee into the hand of these men that seek thy life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 17, 'Then said Jeremiah unto Zedekiah, Thus saith the LORD, the God of hosts, the God of Israel; If thou wilt assuredly go forth unto the king of Babylon''s princes, then thy soul shall live, and this city shall not be burned with fire; and thou shalt live, and thine house:', 'then said jeremiah unto zedekiah thus saith the lord the god of hosts the god of israel if thou wilt assuredly go forth unto the king of babylon s princes then thy soul shall live and this city shall not be burned with fire and thou shalt live and thine house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 18, 'But if thou wilt not go forth to the king of Babylon''s princes, then shall this city be given into the hand of the Chaldeans, and they shall burn it with fire, and thou shalt not escape out of their hand.', 'but if thou wilt not go forth to the king of babylon s princes then shall this city be given into the hand of the chaldeans and they shall burn it with fire and thou shalt not escape out of their hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 19, 'And Zedekiah the king said unto Jeremiah, I am afraid of the Jews that are fallen to the Chaldeans, lest they deliver me into their hand, and they mock me.', 'and zedekiah the king said unto jeremiah i am afraid of the jews that are fallen to the chaldeans lest they deliver me into their hand and they mock me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 20, 'But Jeremiah said, They shall not deliver {thee}. Obey, I beseech thee, the voice of the LORD, which I speak unto thee: so it shall be well unto thee, and thy soul shall live.', 'but jeremiah said they shall not deliver thee obey i beseech thee the voice of the lord which i speak unto thee so it shall be well unto thee and thy soul shall live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 21, 'But if thou refuse to go forth, this {is} the word that the LORD hath shewed me:', 'but if thou refuse to go forth this is the word that the lord hath shewed me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 22, 'And, behold, all the women that are left in the king of Judah''s house {shall be} brought forth to the king of Babylon''s princes, and those {women} shall say, Thy friends have set thee on, and have prevailed against thee: thy feet are sunk in the mire, {and} they are turned away back. {Thy friends: Heb. Men of thy peace}', 'and behold all the women that are left in the king of judah s house shall be brought forth to the king of babylon s princes and those women shall say thy friends have set thee on and have prevailed against thee thy feet are sunk in the mire and they are turned away back thy friends heb men of thy peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 23, 'So they shall bring out all thy wives and thy children to the Chaldeans: and thou shalt not escape out of their hand, but shalt be taken by the hand of the king of Babylon: and thou shalt cause this city to be burned with fire. {thou shalt cause...: Heb. thou shalt burn, etc}', 'so they shall bring out all thy wives and thy children to the chaldeans and thou shalt not escape out of their hand but shalt be taken by the hand of the king of babylon and thou shalt cause this city to be burned with fire thou shalt cause heb thou shalt burn etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 24, 'Then said Zedekiah unto Jeremiah, Let no man know of these words, and thou shalt not die.', 'then said zedekiah unto jeremiah let no man know of these words and thou shalt not die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 25, 'But if the princes hear that I have talked with thee, and they come unto thee, and say unto thee, Declare unto us now what thou hast said unto the king, hide it not from us, and we will not put thee to death; also what the king said unto thee:', 'but if the princes hear that i have talked with thee and they come unto thee and say unto thee declare unto us now what thou hast said unto the king hide it not from us and we will not put thee to death also what the king said unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 26, 'Then thou shalt say unto them, I presented my supplication before the king, that he would not cause me to return to Jonathan''s house, to die there.', 'then thou shalt say unto them i presented my supplication before the king that he would not cause me to return to jonathan s house to die there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 27, 'Then came all the princes unto Jeremiah, and asked him: and he told them according to all these words that the king had commanded. So they left off speaking with him; for the matter was not perceived. {they...: Heb. they were silent from him}', 'then came all the princes unto jeremiah and asked him and he told them according to all these words that the king had commanded so they left off speaking with him for the matter was not perceived they heb they were silent from him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 38, 28, 'So Jeremiah abode in the court of the prison until the day that Jerusalem was taken: and he was {there} when Jerusalem was taken.', 'so jeremiah abode in the court of the prison until the day that jerusalem was taken and he was there when jerusalem was taken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 1, 'In the ninth year of Zedekiah king of Judah, in the tenth month, came Nebuchadrezzar king of Babylon and all his army against Jerusalem, and they besieged it.', 'in the ninth year of zedekiah king of judah in the tenth month came nebuchadrezzar king of babylon and all his army against jerusalem and they besieged it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 2, '{And} in the eleventh year of Zedekiah, in the fourth month, the ninth {day} of the month, the city was broken up.', 'and in the eleventh year of zedekiah in the fourth month the ninth day of the month the city was broken up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 3, 'And all the princes of the king of Babylon came in, and sat in the middle gate, {even} Nergalsharezer, Samgarnebo, Sarsechim, Rabsaris, Nergalsharezer, Rabmag, with all the residue of the princes of the king of Babylon.', 'and all the princes of the king of babylon came in and sat in the middle gate even nergalsharezer samgarnebo sarsechim rabsaris nergalsharezer rabmag with all the residue of the princes of the king of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 4, 'And it came to pass, {that} when Zedekiah the king of Judah saw them, and all the men of war, then they fled, and went forth out of the city by night, by the way of the king''s garden, by the gate betwixt the two walls: and he went out the way of the plain.', 'and it came to pass that when zedekiah the king of judah saw them and all the men of war then they fled and went forth out of the city by night by the way of the king s garden by the gate betwixt the two walls and he went out the way of the plain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 5, 'But the Chaldeans'' army pursued after them, and overtook Zedekiah in the plains of Jericho: and when they had taken him, they brought him up to Nebuchadnezzar king of Babylon to Riblah in the land of Hamath, where he gave judgment upon him. {gave...: Heb. spake with him judgments}', 'but the chaldeans army pursued after them and overtook zedekiah in the plains of jericho and when they had taken him they brought him up to nebuchadnezzar king of babylon to riblah in the land of hamath where he gave judgment upon him gave heb spake with him judgments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 6, 'Then the king of Babylon slew the sons of Zedekiah in Riblah before his eyes: also the king of Babylon slew all the nobles of Judah.', 'then the king of babylon slew the sons of zedekiah in riblah before his eyes also the king of babylon slew all the nobles of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 7, 'Moreover he put out Zedekiah''s eyes, and bound him with chains, to carry him to Babylon. {with...: Heb. with two brasen chains, or, fetters}', 'moreover he put out zedekiah s eyes and bound him with chains to carry him to babylon with heb with two brasen chains or fetters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 8, 'And the Chaldeans burned the king''s house, and the houses of the people, with fire, and brake down the walls of Jerusalem.', 'and the chaldeans burned the king s house and the houses of the people with fire and brake down the walls of jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 9, 'Then Nebuzaradan the captain of the guard carried away captive into Babylon the remnant of the people that remained in the city, and those that fell away, that fell to him, with the rest of the people that remained. {captain...: or, chief marshal: Heb. chief of the executioners, or, slaughtermen}', 'then nebuzaradan the captain of the guard carried away captive into babylon the remnant of the people that remained in the city and those that fell away that fell to him with the rest of the people that remained captain or chief marshal heb chief of the executioners or slaughtermen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 10, 'But Nebuzaradan the captain of the guard left of the poor of the people, which had nothing, in the land of Judah, and gave them vineyards and fields at the same time. {captain...: or, chief marshal: Heb. chief of the executioners, or, slaughtermen} {at the...: Heb. in that day}', 'but nebuzaradan the captain of the guard left of the poor of the people which had nothing in the land of judah and gave them vineyards and fields at the same time captain or chief marshal heb chief of the executioners or slaughtermen at the heb in that day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 11, 'Now Nebuchadrezzar king of Babylon gave charge concerning Jeremiah to Nebuzaradan the captain of the guard, saying, {to: Heb. by the hand of} {captain...: or, chief marshal: Heb. chief of the executioners, or, slaughtermen}', 'now nebuchadrezzar king of babylon gave charge concerning jeremiah to nebuzaradan the captain of the guard saying to heb by the hand of captain or chief marshal heb chief of the executioners or slaughtermen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 12, 'Take him, and look well to him, and do him no harm; but do unto him even as he shall say unto thee. {look...: Heb. set thine eyes upon him}', 'take him and look well to him and do him no harm but do unto him even as he shall say unto thee look heb set thine eyes upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 13, 'So Nebuzaradan the captain of the guard sent, and Nebushasban, Rabsaris, and Nergalsharezer, Rabmag, and all the king of Babylon''s princes; {captain...: or, chief marshal: Heb. chief of the executioners, or, slaughtermen}', 'so nebuzaradan the captain of the guard sent and nebushasban rabsaris and nergalsharezer rabmag and all the king of babylon s princes captain or chief marshal heb chief of the executioners or slaughtermen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 14, 'Even they sent, and took Jeremiah out of the court of the prison, and committed him unto Gedaliah the son of Ahikam the son of Shaphan, that he should carry him home: so he dwelt among the people.', 'even they sent and took jeremiah out of the court of the prison and committed him unto gedaliah the son of ahikam the son of shaphan that he should carry him home so he dwelt among the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 15, 'Now the word of the LORD came unto Jeremiah, while he was shut up in the court of the prison, saying,', 'now the word of the lord came unto jeremiah while he was shut up in the court of the prison saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 16, 'Go and speak to Ebedmelech the Ethiopian, saying, Thus saith the LORD of hosts, the God of Israel; Behold, I will bring my words upon this city for evil, and not for good; and they shall be {accomplished} in that day before thee.', 'go and speak to ebedmelech the ethiopian saying thus saith the lord of hosts the god of israel behold i will bring my words upon this city for evil and not for good and they shall be accomplished in that day before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 17, 'But I will deliver thee in that day, saith the LORD: and thou shalt not be given into the hand of the men of whom thou {art} afraid.', 'but i will deliver thee in that day saith the lord and thou shalt not be given into the hand of the men of whom thou art afraid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 39, 18, 'For I will surely deliver thee, and thou shalt not fall by the sword, but thy life shall be for a prey unto thee: because thou hast put thy trust in me, saith the LORD.', 'for i will surely deliver thee and thou shalt not fall by the sword but thy life shall be for a prey unto thee because thou hast put thy trust in me saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 1, 'The word that came to Jeremiah from the LORD, after that Nebuzaradan the captain of the guard had let him go from Ramah, when he had taken him being bound in chains among all that were carried away captive of Jerusalem and Judah, which were carried away captive unto Babylon. {chains: or, manicles}', 'the word that came to jeremiah from the lord after that nebuzaradan the captain of the guard had let him go from ramah when he had taken him being bound in chains among all that were carried away captive of jerusalem and judah which were carried away captive unto babylon chains or manicles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 2, 'And the captain of the guard took Jeremiah, and said unto him, The LORD thy God hath pronounced this evil upon this place.', 'and the captain of the guard took jeremiah and said unto him the lord thy god hath pronounced this evil upon this place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 3, 'Now the LORD hath brought {it}, and done according as he hath said: because ye have sinned against the LORD, and have not obeyed his voice, therefore this thing is come upon you.', 'now the lord hath brought it and done according as he hath said because ye have sinned against the lord and have not obeyed his voice therefore this thing is come upon you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 4, 'And now, behold, I loose thee this day from the chains which {were} upon thine hand. If it seem good unto thee to come with me into Babylon, come; and I will look well unto thee: but if it seem ill unto thee to come with me into Babylon, forbear: behold, all the land {is} before thee: whither it seemeth good and convenient for thee to go, thither go. {were...: or, are upon thine hand} {I will...: Heb. I will set mine eye upon thee}', 'and now behold i loose thee this day from the chains which were upon thine hand if it seem good unto thee to come with me into babylon come and i will look well unto thee but if it seem ill unto thee to come with me into babylon forbear behold all the land is before thee whither it seemeth good and convenient for thee to go thither go were or are upon thine hand i will heb i will set mine eye upon thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 5, 'Now while he was not yet gone back, {he said}, Go back also to Gedaliah the son of Ahikam the son of Shaphan, whom the king of Babylon hath made governor over the cities of Judah, and dwell with him among the people: or go wheresoever it seemeth convenient unto thee to go. So the captain of the guard gave him victuals and a reward, and let him go.', 'now while he was not yet gone back he said go back also to gedaliah the son of ahikam the son of shaphan whom the king of babylon hath made governor over the cities of judah and dwell with him among the people or go wheresoever it seemeth convenient unto thee to go so the captain of the guard gave him victuals and a reward and let him go');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 6, 'Then went Jeremiah unto Gedaliah the son of Ahikam to Mizpah; and dwelt with him among the people that were left in the land.', 'then went jeremiah unto gedaliah the son of ahikam to mizpah and dwelt with him among the people that were left in the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 7, 'Now when all the captains of the forces which {were} in the fields, {even} they and their men, heard that the king of Babylon had made Gedaliah the son of Ahikam governor in the land, and had committed unto him men, and women, and children, and of the poor of the land, of them that were not carried away captive to Babylon;', 'now when all the captains of the forces which were in the fields even they and their men heard that the king of babylon had made gedaliah the son of ahikam governor in the land and had committed unto him men and women and children and of the poor of the land of them that were not carried away captive to babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 8, 'Then they came to Gedaliah to Mizpah, even Ishmael the son of Nethaniah, and Johanan and Jonathan the sons of Kareah, and Seraiah the son of Tanhumeth, and the sons of Ephai the Netophathite, and Jezaniah the son of a Maachathite, they and their men.', 'then they came to gedaliah to mizpah even ishmael the son of nethaniah and johanan and jonathan the sons of kareah and seraiah the son of tanhumeth and the sons of ephai the netophathite and jezaniah the son of a maachathite they and their men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 9, 'And Gedaliah the son of Ahikam the son of Shaphan sware unto them and to their men, saying, Fear not to serve the Chaldeans: dwell in the land, and serve the king of Babylon, and it shall be well with you.', 'and gedaliah the son of ahikam the son of shaphan sware unto them and to their men saying fear not to serve the chaldeans dwell in the land and serve the king of babylon and it shall be well with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 10, 'As for me, behold, I will dwell at Mizpah to serve the Chaldeans, which will come unto us: but ye, gather ye wine, and summer fruits, and oil, and put {them} in your vessels, and dwell in your cities that ye have taken. {to serve: Heb. to stand before}', 'as for me behold i will dwell at mizpah to serve the chaldeans which will come unto us but ye gather ye wine and summer fruits and oil and put them in your vessels and dwell in your cities that ye have taken to serve heb to stand before');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 11, 'Likewise when all the Jews that {were} in Moab, and among the Ammonites, and in Edom, and that {were} in all the countries, heard that the king of Babylon had left a remnant of Judah, and that he had set over them Gedaliah the son of Ahikam the son of Shaphan;', 'likewise when all the jews that were in moab and among the ammonites and in edom and that were in all the countries heard that the king of babylon had left a remnant of judah and that he had set over them gedaliah the son of ahikam the son of shaphan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 12, 'Even all the Jews returned out of all places whither they were driven, and came to the land of Judah, to Gedaliah, unto Mizpah, and gathered wine and summer fruits very much.', 'even all the jews returned out of all places whither they were driven and came to the land of judah to gedaliah unto mizpah and gathered wine and summer fruits very much');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 13, 'Moreover Johanan the son of Kareah, and all the captains of the forces that {were} in the fields, came to Gedaliah to Mizpah,', 'moreover johanan the son of kareah and all the captains of the forces that were in the fields came to gedaliah to mizpah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 14, 'And said unto him, Dost thou certainly know that Baalis the king of the Ammonites hath sent Ishmael the son of Nethaniah to slay thee? But Gedaliah the son of Ahikam believed them not. {to slay...: Heb. to strike thee in soul?}', 'and said unto him dost thou certainly know that baalis the king of the ammonites hath sent ishmael the son of nethaniah to slay thee but gedaliah the son of ahikam believed them not to slay heb to strike thee in soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 15, 'Then Johanan the son of Kareah spake to Gedaliah in Mizpah secretly, saying, Let me go, I pray thee, and I will slay Ishmael the son of Nethaniah, and no man shall know {it}: wherefore should he slay thee, that all the Jews which are gathered unto thee should be scattered, and the remnant in Judah perish?', 'then johanan the son of kareah spake to gedaliah in mizpah secretly saying let me go i pray thee and i will slay ishmael the son of nethaniah and no man shall know it wherefore should he slay thee that all the jews which are gathered unto thee should be scattered and the remnant in judah perish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 40, 16, 'But Gedaliah the son of Ahikam said unto Johanan the son of Kareah, Thou shalt not do this thing: for thou speakest falsely of Ishmael.', 'but gedaliah the son of ahikam said unto johanan the son of kareah thou shalt not do this thing for thou speakest falsely of ishmael');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 1, 'Now it came to pass in the seventh month, {that} Ishmael the son of Nethaniah the son of Elishama, of the seed royal, and the princes of the king, even ten men with him, came unto Gedaliah the son of Ahikam to Mizpah; and there they did eat bread together in Mizpah.', 'now it came to pass in the seventh month that ishmael the son of nethaniah the son of elishama of the seed royal and the princes of the king even ten men with him came unto gedaliah the son of ahikam to mizpah and there they did eat bread together in mizpah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 2, 'Then arose Ishmael the son of Nethaniah, and the ten men that were with him, and smote Gedaliah the son of Ahikam the son of Shaphan with the sword, and slew him, whom the king of Babylon had made governor over the land.', 'then arose ishmael the son of nethaniah and the ten men that were with him and smote gedaliah the son of ahikam the son of shaphan with the sword and slew him whom the king of babylon had made governor over the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 3, 'Ishmael also slew all the Jews that were with him, {even} with Gedaliah, at Mizpah, and the Chaldeans that were found there, {and} the men of war.', 'ishmael also slew all the jews that were with him even with gedaliah at mizpah and the chaldeans that were found there and the men of war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 4, 'And it came to pass the second day after he had slain Gedaliah, and no man knew {it},', 'and it came to pass the second day after he had slain gedaliah and no man knew it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 5, 'That there came certain from Shechem, from Shiloh, and from Samaria, {even} fourscore men, having their beards shaven, and their clothes rent, and having cut themselves, with offerings and incense in their hand, to bring {them} to the house of the LORD.', 'that there came certain from shechem from shiloh and from samaria even fourscore men having their beards shaven and their clothes rent and having cut themselves with offerings and incense in their hand to bring them to the house of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 6, 'And Ishmael the son of Nethaniah went forth from Mizpah to meet them, weeping all along as he went: and it came to pass, as he met them, he said unto them, Come to Gedaliah the son of Ahikam. {weeping...: Heb. in going and weeping}', 'and ishmael the son of nethaniah went forth from mizpah to meet them weeping all along as he went and it came to pass as he met them he said unto them come to gedaliah the son of ahikam weeping heb in going and weeping');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 7, 'And it was {so}, when they came into the midst of the city, that Ishmael the son of Nethaniah slew them, {and cast them} into the midst of the pit, he, and the men that {were} with him.', 'and it was so when they came into the midst of the city that ishmael the son of nethaniah slew them and cast them into the midst of the pit he and the men that were with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 8, 'But ten men were found among them that said unto Ishmael, Slay us not: for we have treasures in the field, of wheat, and of barley, and of oil, and of honey. So he forbare, and slew them not among their brethren.', 'but ten men were found among them that said unto ishmael slay us not for we have treasures in the field of wheat and of barley and of oil and of honey so he forbare and slew them not among their brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 9, 'Now the pit wherein Ishmael had cast all the dead bodies of the men, whom he had slain because of Gedaliah, {was} it which Asa the king had made for fear of Baasha king of Israel: {and} Ishmael the son of Nethaniah filled it with {them that were} slain. {because...: or, near Gedaliah: Heb. by the hand, or, by the side of Gedaliah}', 'now the pit wherein ishmael had cast all the dead bodies of the men whom he had slain because of gedaliah was it which asa the king had made for fear of baasha king of israel and ishmael the son of nethaniah filled it with them that were slain because or near gedaliah heb by the hand or by the side of gedaliah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 10, 'Then Ishmael carried away captive all the residue of the people that {were} in Mizpah, {even} the king''s daughters, and all the people that remained in Mizpah, whom Nebuzaradan the captain of the guard had committed to Gedaliah the son of Ahikam: and Ishmael the son of Nethaniah carried them away captive, and departed to go over to the Ammonites.', 'then ishmael carried away captive all the residue of the people that were in mizpah even the king s daughters and all the people that remained in mizpah whom nebuzaradan the captain of the guard had committed to gedaliah the son of ahikam and ishmael the son of nethaniah carried them away captive and departed to go over to the ammonites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 11, 'But when Johanan the son of Kareah, and all the captains of the forces that {were} with him, heard of all the evil that Ishmael the son of Nethaniah had done,', 'but when johanan the son of kareah and all the captains of the forces that were with him heard of all the evil that ishmael the son of nethaniah had done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 12, 'Then they took all the men, and went to fight with Ishmael the son of Nethaniah, and found him by the great waters that {are} in Gibeon.', 'then they took all the men and went to fight with ishmael the son of nethaniah and found him by the great waters that are in gibeon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 13, 'Now it came to pass, {that} when all the people which {were} with Ishmael saw Johanan the son of Kareah, and all the captains of the forces that {were} with him, then they were glad.', 'now it came to pass that when all the people which were with ishmael saw johanan the son of kareah and all the captains of the forces that were with him then they were glad');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 14, 'So all the people that Ishmael had carried away captive from Mizpah cast about and returned, and went unto Johanan the son of Kareah.', 'so all the people that ishmael had carried away captive from mizpah cast about and returned and went unto johanan the son of kareah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 15, 'But Ishmael the son of Nethaniah escaped from Johanan with eight men, and went to the Ammonites.', 'but ishmael the son of nethaniah escaped from johanan with eight men and went to the ammonites');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 16, 'Then took Johanan the son of Kareah, and all the captains of the forces that {were} with him, all the remnant of the people whom he had recovered from Ishmael the son of Nethaniah, from Mizpah, after {that} he had slain Gedaliah the son of Ahikam, {even} mighty men of war, and the women, and the children, and the eunuchs, whom he had brought again from Gibeon:', 'then took johanan the son of kareah and all the captains of the forces that were with him all the remnant of the people whom he had recovered from ishmael the son of nethaniah from mizpah after that he had slain gedaliah the son of ahikam even mighty men of war and the women and the children and the eunuchs whom he had brought again from gibeon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 17, 'And they departed, and dwelt in the habitation of Chimham, which is by Bethlehem, to go to enter into Egypt,', 'and they departed and dwelt in the habitation of chimham which is by bethlehem to go to enter into egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 41, 18, 'Because of the Chaldeans: for they were afraid of them, because Ishmael the son of Nethaniah had slain Gedaliah the son of Ahikam, whom the king of Babylon made governor in the land.', 'because of the chaldeans for they were afraid of them because ishmael the son of nethaniah had slain gedaliah the son of ahikam whom the king of babylon made governor in the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 1, 'Then all the captains of the forces, and Johanan the son of Kareah, and Jezaniah the son of Hoshaiah, and all the people from the least even unto the greatest, came near,', 'then all the captains of the forces and johanan the son of kareah and jezaniah the son of hoshaiah and all the people from the least even unto the greatest came near');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 2, 'And said unto Jeremiah the prophet, Let, we beseech thee, our supplication be accepted before thee, and pray for us unto the LORD thy God, {even} for all this remnant; (for we are left {but} a few of many, as thine eyes do behold us:) {Let...: or, Let our supplication fall before thee}', 'and said unto jeremiah the prophet let we beseech thee our supplication be accepted before thee and pray for us unto the lord thy god even for all this remnant for we are left but a few of many as thine eyes do behold us let or let our supplication fall before thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 3, 'That the LORD thy God may shew us the way wherein we may walk, and the thing that we may do.', 'that the lord thy god may shew us the way wherein we may walk and the thing that we may do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 4, 'Then Jeremiah the prophet said unto them, I have heard {you}; behold, I will pray unto the LORD your God according to your words; and it shall come to pass, {that} whatsoever thing the LORD shall answer you, I will declare {it} unto you; I will keep nothing back from you.', 'then jeremiah the prophet said unto them i have heard you behold i will pray unto the lord your god according to your words and it shall come to pass that whatsoever thing the lord shall answer you i will declare it unto you i will keep nothing back from you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 5, 'Then they said to Jeremiah, The LORD be a true and faithful witness between us, if we do not even according to all things for the which the LORD thy God shall send thee to us.', 'then they said to jeremiah the lord be a true and faithful witness between us if we do not even according to all things for the which the lord thy god shall send thee to us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 6, 'Whether {it be} good, or whether {it be} evil, we will obey the voice of the LORD our God, to whom we send thee; that it may be well with us, when we obey the voice of the LORD our God.', 'whether it be good or whether it be evil we will obey the voice of the lord our god to whom we send thee that it may be well with us when we obey the voice of the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 7, 'And it came to pass after ten days, that the word of the LORD came unto Jeremiah.', 'and it came to pass after ten days that the word of the lord came unto jeremiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 8, 'Then called he Johanan the son of Kareah, and all the captains of the forces which {were} with him, and all the people from the least even to the greatest,', 'then called he johanan the son of kareah and all the captains of the forces which were with him and all the people from the least even to the greatest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 9, 'And said unto them, Thus saith the LORD, the God of Israel, unto whom ye sent me to present your supplication before him;', 'and said unto them thus saith the lord the god of israel unto whom ye sent me to present your supplication before him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 10, 'If ye will still abide in this land, then will I build you, and not pull {you} down, and I will plant you, and not pluck {you} up: for I repent me of the evil that I have done unto you.', 'if ye will still abide in this land then will i build you and not pull you down and i will plant you and not pluck you up for i repent me of the evil that i have done unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 11, 'Be not afraid of the king of Babylon, of whom ye are afraid; be not afraid of him, saith the LORD: for I {am} with you to save you, and to deliver you from his hand.', 'be not afraid of the king of babylon of whom ye are afraid be not afraid of him saith the lord for i am with you to save you and to deliver you from his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 12, 'And I will shew mercies unto you, that he may have mercy upon you, and cause you to return to your own land.', 'and i will shew mercies unto you that he may have mercy upon you and cause you to return to your own land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 13, 'But if ye say, We will not dwell in this land, neither obey the voice of the LORD your God,', 'but if ye say we will not dwell in this land neither obey the voice of the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 14, 'Saying, No; but we will go into the land of Egypt, where we shall see no war, nor hear the sound of the trumpet, nor have hunger of bread; and there will we dwell:', 'saying no but we will go into the land of egypt where we shall see no war nor hear the sound of the trumpet nor have hunger of bread and there will we dwell');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 15, 'And now therefore hear the word of the LORD, ye remnant of Judah; Thus saith the LORD of hosts, the God of Israel; If ye wholly set your faces to enter into Egypt, and go to sojourn there;', 'and now therefore hear the word of the lord ye remnant of judah thus saith the lord of hosts the god of israel if ye wholly set your faces to enter into egypt and go to sojourn there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 16, 'Then it shall come to pass, {that} the sword, which ye feared, shall overtake you there in the land of Egypt, and the famine, whereof ye were afraid, shall follow close after you there in Egypt; and there ye shall die. {shall follow...: Heb. shall cleave after you}', 'then it shall come to pass that the sword which ye feared shall overtake you there in the land of egypt and the famine whereof ye were afraid shall follow close after you there in egypt and there ye shall die shall follow heb shall cleave after you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 17, 'So shall it be with all the men that set their faces to go into Egypt to sojourn there; they shall die by the sword, by the famine, and by the pestilence: and none of them shall remain or escape from the evil that I will bring upon them. {So...: Heb. So shall all the men be}', 'so shall it be with all the men that set their faces to go into egypt to sojourn there they shall die by the sword by the famine and by the pestilence and none of them shall remain or escape from the evil that i will bring upon them so heb so shall all the men be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 18, 'For thus saith the LORD of hosts, the God of Israel; As mine anger and my fury hath been poured forth upon the inhabitants of Jerusalem; so shall my fury be poured forth upon you, when ye shall enter into Egypt: and ye shall be an execration, and an astonishment, and a curse, and a reproach; and ye shall see this place no more.', 'for thus saith the lord of hosts the god of israel as mine anger and my fury hath been poured forth upon the inhabitants of jerusalem so shall my fury be poured forth upon you when ye shall enter into egypt and ye shall be an execration and an astonishment and a curse and a reproach and ye shall see this place no more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 19, 'The LORD hath said concerning you, O ye remnant of Judah; Go ye not into Egypt: know certainly that I have admonished you this day. {admonished...: Heb. testified against you}', 'the lord hath said concerning you o ye remnant of judah go ye not into egypt know certainly that i have admonished you this day admonished heb testified against you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 20, 'For ye dissembled in your hearts, when ye sent me unto the LORD your God, saying, Pray for us unto the LORD our God; and according unto all that the LORD our God shall say, so declare unto us, and we will do {it}. {ye dissembled...: or, ye have used deceit against your souls}', 'for ye dissembled in your hearts when ye sent me unto the lord your god saying pray for us unto the lord our god and according unto all that the lord our god shall say so declare unto us and we will do it ye dissembled or ye have used deceit against your souls');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 21, 'And {now} I have this day declared {it} to you; but ye have not obeyed the voice of the LORD your God, nor any {thing} for the which he hath sent me unto you.', 'and now i have this day declared it to you but ye have not obeyed the voice of the lord your god nor any thing for the which he hath sent me unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 42, 22, 'Now therefore know certainly that ye shall die by the sword, by the famine, and by the pestilence, in the place whither ye desire to go {and} to sojourn. {to go...: or, to go to sojourn}', 'now therefore know certainly that ye shall die by the sword by the famine and by the pestilence in the place whither ye desire to go and to sojourn to go or to go to sojourn');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 1, 'And it came to pass, {that} when Jeremiah had made an end of speaking unto all the people all the words of the LORD their God, for which the LORD their God had sent him to them, {even} all these words,', 'and it came to pass that when jeremiah had made an end of speaking unto all the people all the words of the lord their god for which the lord their god had sent him to them even all these words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 2, 'Then spake Azariah the son of Hoshaiah, and Johanan the son of Kareah, and all the proud men, saying unto Jeremiah, Thou speakest falsely: the LORD our God hath not sent thee to say, Go not into Egypt to sojourn there:', 'then spake azariah the son of hoshaiah and johanan the son of kareah and all the proud men saying unto jeremiah thou speakest falsely the lord our god hath not sent thee to say go not into egypt to sojourn there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 3, 'But Baruch the son of Neriah setteth thee on against us, for to deliver us into the hand of the Chaldeans, that they might put us to death, and carry us away captives into Babylon.', 'but baruch the son of neriah setteth thee on against us for to deliver us into the hand of the chaldeans that they might put us to death and carry us away captives into babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 4, 'So Johanan the son of Kareah, and all the captains of the forces, and all the people, obeyed not the voice of the LORD, to dwell in the land of Judah.', 'so johanan the son of kareah and all the captains of the forces and all the people obeyed not the voice of the lord to dwell in the land of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 5, 'But Johanan the son of Kareah, and all the captains of the forces, took all the remnant of Judah, that were returned from all nations, whither they had been driven, to dwell in the land of Judah;', 'but johanan the son of kareah and all the captains of the forces took all the remnant of judah that were returned from all nations whither they had been driven to dwell in the land of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 6, '{Even} men, and women, and children, and the king''s daughters, and every person that Nebuzaradan the captain of the guard had left with Gedaliah the son of Ahikam the son of Shaphan, and Jeremiah the prophet, and Baruch the son of Neriah.', 'even men and women and children and the king s daughters and every person that nebuzaradan the captain of the guard had left with gedaliah the son of ahikam the son of shaphan and jeremiah the prophet and baruch the son of neriah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 7, 'So they came into the land of Egypt: for they obeyed not the voice of the LORD: thus came they {even} to Tahpanhes.', 'so they came into the land of egypt for they obeyed not the voice of the lord thus came they even to tahpanhes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 8, 'Then came the word of the LORD unto Jeremiah in Tahpanhes, saying,', 'then came the word of the lord unto jeremiah in tahpanhes saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 9, 'Take great stones in thine hand, and hide them in the clay in the brickkiln, which {is} at the entry of Pharaoh''s house in Tahpanhes, in the sight of the men of Judah;', 'take great stones in thine hand and hide them in the clay in the brickkiln which is at the entry of pharaoh s house in tahpanhes in the sight of the men of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 10, 'And say unto them, Thus saith the LORD of hosts, the God of Israel; Behold, I will send and take Nebuchadrezzar the king of Babylon, my servant, and will set his throne upon these stones that I have hid; and he shall spread his royal pavilion over them.', 'and say unto them thus saith the lord of hosts the god of israel behold i will send and take nebuchadrezzar the king of babylon my servant and will set his throne upon these stones that i have hid and he shall spread his royal pavilion over them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 11, 'And when he cometh, he shall smite the land of Egypt, {and deliver} such {as are} for death to death; and such {as are} for captivity to captivity; and such {as are} for the sword to the sword.', 'and when he cometh he shall smite the land of egypt and deliver such as are for death to death and such as are for captivity to captivity and such as are for the sword to the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 12, 'And I will kindle a fire in the houses of the gods of Egypt; and he shall burn them, and carry them away captives: and he shall array himself with the land of Egypt, as a shepherd putteth on his garment; and he shall go forth from thence in peace.', 'and i will kindle a fire in the houses of the gods of egypt and he shall burn them and carry them away captives and he shall array himself with the land of egypt as a shepherd putteth on his garment and he shall go forth from thence in peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 43, 13, 'He shall break also the images of Bethshemesh, that {is} in the land of Egypt; and the houses of the gods of the Egyptians shall he burn with fire. {images: Heb. statues, or, standing images} {Bethshemesh: or, The house of the sun}', 'he shall break also the images of bethshemesh that is in the land of egypt and the houses of the gods of the egyptians shall he burn with fire images heb statues or standing images bethshemesh or the house of the sun');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 1, 'The word that came to Jeremiah concerning all the Jews which dwell in the land of Egypt, which dwell at Migdol, and at Tahpanhes, and at Noph, and in the country of Pathros, saying,', 'the word that came to jeremiah concerning all the jews which dwell in the land of egypt which dwell at migdol and at tahpanhes and at noph and in the country of pathros saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 2, 'Thus saith the LORD of hosts, the God of Israel; Ye have seen all the evil that I have brought upon Jerusalem, and upon all the cities of Judah; and, behold, this day they {are} a desolation, and no man dwelleth therein,', 'thus saith the lord of hosts the god of israel ye have seen all the evil that i have brought upon jerusalem and upon all the cities of judah and behold this day they are a desolation and no man dwelleth therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 3, 'Because of their wickedness which they have committed to provoke me to anger, in that they went to burn incense, {and} to serve other gods, whom they knew not, {neither} they, ye, nor your fathers.', 'because of their wickedness which they have committed to provoke me to anger in that they went to burn incense and to serve other gods whom they knew not neither they ye nor your fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 4, 'Howbeit I sent unto you all my servants the prophets, rising early and sending {them}, saying, Oh, do not this abominable thing that I hate.', 'howbeit i sent unto you all my servants the prophets rising early and sending them saying oh do not this abominable thing that i hate');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 5, 'But they hearkened not, nor inclined their ear to turn from their wickedness, to burn no incense unto other gods.', 'but they hearkened not nor inclined their ear to turn from their wickedness to burn no incense unto other gods');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 6, 'Wherefore my fury and mine anger was poured forth, and was kindled in the cities of Judah and in the streets of Jerusalem; and they are wasted {and} desolate, as at this day.', 'wherefore my fury and mine anger was poured forth and was kindled in the cities of judah and in the streets of jerusalem and they are wasted and desolate as at this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 7, 'Therefore now thus saith the LORD, the God of hosts, the God of Israel; Wherefore commit ye {this} great evil against your souls, to cut off from you man and woman, child and suckling, out of Judah, to leave you none to remain; {out...: Heb. out of the midst of Judah}', 'therefore now thus saith the lord the god of hosts the god of israel wherefore commit ye this great evil against your souls to cut off from you man and woman child and suckling out of judah to leave you none to remain out heb out of the midst of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 8, 'In that ye provoke me unto wrath with the works of your hands, burning incense unto other gods in the land of Egypt, whither ye be gone to dwell, that ye might cut yourselves off, and that ye might be a curse and a reproach among all the nations of the earth?', 'in that ye provoke me unto wrath with the works of your hands burning incense unto other gods in the land of egypt whither ye be gone to dwell that ye might cut yourselves off and that ye might be a curse and a reproach among all the nations of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 9, 'Have ye forgotten the wickedness of your fathers, and the wickedness of the kings of Judah, and the wickedness of their wives, and your own wickedness, and the wickedness of your wives, which they have committed in the land of Judah, and in the streets of Jerusalem? {wickedness...: Heb. wickednesses, or, punishments, etc}', 'have ye forgotten the wickedness of your fathers and the wickedness of the kings of judah and the wickedness of their wives and your own wickedness and the wickedness of your wives which they have committed in the land of judah and in the streets of jerusalem wickedness heb wickednesses or punishments etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 10, 'They are not humbled {even} unto this day, neither have they feared, nor walked in my law, nor in my statutes, that I set before you and before your fathers. {humbled: Heb. contrite}', 'they are not humbled even unto this day neither have they feared nor walked in my law nor in my statutes that i set before you and before your fathers humbled heb contrite');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 11, 'Therefore thus saith the LORD of hosts, the God of Israel; Behold, I will set my face against you for evil, and to cut off all Judah.', 'therefore thus saith the lord of hosts the god of israel behold i will set my face against you for evil and to cut off all judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 12, 'And I will take the remnant of Judah, that have set their faces to go into the land of Egypt to sojourn there, and they shall all be consumed, {and} fall in the land of Egypt; they shall {even} be consumed by the sword {and} by the famine: they shall die, from the least even unto the greatest, by the sword and by the famine: and they shall be an execration, {and} an astonishment, and a curse, and a reproach.', 'and i will take the remnant of judah that have set their faces to go into the land of egypt to sojourn there and they shall all be consumed and fall in the land of egypt they shall even be consumed by the sword and by the famine they shall die from the least even unto the greatest by the sword and by the famine and they shall be an execration and an astonishment and a curse and a reproach');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 13, 'For I will punish them that dwell in the land of Egypt, as I have punished Jerusalem, by the sword, by the famine, and by the pestilence:', 'for i will punish them that dwell in the land of egypt as i have punished jerusalem by the sword by the famine and by the pestilence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 14, 'So that none of the remnant of Judah, which are gone into the land of Egypt to sojourn there, shall escape or remain, that they should return into the land of Judah, to the which they have a desire to return to dwell there: for none shall return but such as shall escape. {have...: Heb. lift up their soul}', 'so that none of the remnant of judah which are gone into the land of egypt to sojourn there shall escape or remain that they should return into the land of judah to the which they have a desire to return to dwell there for none shall return but such as shall escape have heb lift up their soul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 15, 'Then all the men which knew that their wives had burned incense unto other gods, and all the women that stood by, a great multitude, even all the people that dwelt in the land of Egypt, in Pathros, answered Jeremiah, saying,', 'then all the men which knew that their wives had burned incense unto other gods and all the women that stood by a great multitude even all the people that dwelt in the land of egypt in pathros answered jeremiah saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 16, '{As for} the word that thou hast spoken unto us in the name of the LORD, we will not hearken unto thee.', 'as for the word that thou hast spoken unto us in the name of the lord we will not hearken unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 17, 'But we will certainly do whatsoever thing goeth forth out of our own mouth, to burn incense unto the queen of heaven, and to pour out drink offerings unto her, as we have done, we, and our fathers, our kings, and our princes, in the cities of Judah, and in the streets of Jerusalem: for {then} had we plenty of victuals, and were well, and saw no evil. {queen...: or, frame of heaven} {victuals: Heb. bread}', 'but we will certainly do whatsoever thing goeth forth out of our own mouth to burn incense unto the queen of heaven and to pour out drink offerings unto her as we have done we and our fathers our kings and our princes in the cities of judah and in the streets of jerusalem for then had we plenty of victuals and were well and saw no evil queen or frame of heaven victuals heb bread');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 18, 'But since we left off to burn incense to the queen of heaven, and to pour out drink offerings unto her, we have wanted all {things}, and have been consumed by the sword and by the famine.', 'but since we left off to burn incense to the queen of heaven and to pour out drink offerings unto her we have wanted all things and have been consumed by the sword and by the famine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 19, 'And when we burned incense to the queen of heaven, and poured out drink offerings unto her, did we make her cakes to worship her, and pour out drink offerings unto her, without our men? {men: or, husbands?}', 'and when we burned incense to the queen of heaven and poured out drink offerings unto her did we make her cakes to worship her and pour out drink offerings unto her without our men men or husbands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 20, 'Then Jeremiah said unto all the people, to the men, and to the women, and to all the people which had given him {that} answer, saying,', 'then jeremiah said unto all the people to the men and to the women and to all the people which had given him that answer saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 21, 'The incense that ye burned in the cities of Judah, and in the streets of Jerusalem, ye, and your fathers, your kings, and your princes, and the people of the land, did not the LORD remember them, and came it {not} into his mind?', 'the incense that ye burned in the cities of judah and in the streets of jerusalem ye and your fathers your kings and your princes and the people of the land did not the lord remember them and came it not into his mind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 22, 'So that the LORD could no longer bear, because of the evil of your doings, {and} because of the abominations which ye have committed; therefore is your land a desolation, and an astonishment, and a curse, without an inhabitant, as at this day.', 'so that the lord could no longer bear because of the evil of your doings and because of the abominations which ye have committed therefore is your land a desolation and an astonishment and a curse without an inhabitant as at this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 23, 'Because ye have burned incense, and because ye have sinned against the LORD, and have not obeyed the voice of the LORD, nor walked in his law, nor in his statutes, nor in his testimonies; therefore this evil is happened unto you, as at this day.', 'because ye have burned incense and because ye have sinned against the lord and have not obeyed the voice of the lord nor walked in his law nor in his statutes nor in his testimonies therefore this evil is happened unto you as at this day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 24, 'Moreover Jeremiah said unto all the people, and to all the women, Hear the word of the LORD, all Judah that {are} in the land of Egypt:', 'moreover jeremiah said unto all the people and to all the women hear the word of the lord all judah that are in the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 25, 'Thus saith the LORD of hosts, the God of Israel, saying; Ye and your wives have both spoken with your mouths, and fulfilled with your hand, saying, We will surely perform our vows that we have vowed, to burn incense to the queen of heaven, and to pour out drink offerings unto her: ye will surely accomplish your vows, and surely perform your vows.', 'thus saith the lord of hosts the god of israel saying ye and your wives have both spoken with your mouths and fulfilled with your hand saying we will surely perform our vows that we have vowed to burn incense to the queen of heaven and to pour out drink offerings unto her ye will surely accomplish your vows and surely perform your vows');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 26, 'Therefore hear ye the word of the LORD, all Judah that dwell in the land of Egypt; Behold, I have sworn by my great name, saith the LORD, that my name shall no more be named in the mouth of any man of Judah in all the land of Egypt, saying, The Lord GOD liveth.', 'therefore hear ye the word of the lord all judah that dwell in the land of egypt behold i have sworn by my great name saith the lord that my name shall no more be named in the mouth of any man of judah in all the land of egypt saying the lord god liveth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 27, 'Behold, I will watch over them for evil, and not for good: and all the men of Judah that {are} in the land of Egypt shall be consumed by the sword and by the famine, until there be an end of them.', 'behold i will watch over them for evil and not for good and all the men of judah that are in the land of egypt shall be consumed by the sword and by the famine until there be an end of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 28, 'Yet a small number that escape the sword shall return out of the land of Egypt into the land of Judah, and all the remnant of Judah, that are gone into the land of Egypt to sojourn there, shall know whose words shall stand, mine, or theirs. {mine...: Heb. from me, or, from them}', 'yet a small number that escape the sword shall return out of the land of egypt into the land of judah and all the remnant of judah that are gone into the land of egypt to sojourn there shall know whose words shall stand mine or theirs mine heb from me or from them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 29, 'And this {shall be} a sign unto you, saith the LORD, that I will punish you in this place, that ye may know that my words shall surely stand against you for evil:', 'and this shall be a sign unto you saith the lord that i will punish you in this place that ye may know that my words shall surely stand against you for evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 44, 30, 'Thus saith the LORD; Behold, I will give Pharaohhophra king of Egypt into the hand of his enemies, and into the hand of them that seek his life; as I gave Zedekiah king of Judah into the hand of Nebuchadrezzar king of Babylon, his enemy, and that sought his life.', 'thus saith the lord behold i will give pharaohhophra king of egypt into the hand of his enemies and into the hand of them that seek his life as i gave zedekiah king of judah into the hand of nebuchadrezzar king of babylon his enemy and that sought his life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 45, 1, 'The word that Jeremiah the prophet spake unto Baruch the son of Neriah, when he had written these words in a book at the mouth of Jeremiah, in the fourth year of Jehoiakim the son of Josiah king of Judah, saying,', 'the word that jeremiah the prophet spake unto baruch the son of neriah when he had written these words in a book at the mouth of jeremiah in the fourth year of jehoiakim the son of josiah king of judah saying');
