INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 45, 5, 'And seekest thou great things for thyself? seek {them} not: for, behold, I will bring evil upon all flesh, saith the LORD: but thy life will I give unto thee for a prey in all places whither thou goest.', 'and seekest thou great things for thyself seek them not for behold i will bring evil upon all flesh saith the lord but thy life will i give unto thee for a prey in all places whither thou goest');
