INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 3, 'Order ye the buckler and shield, and draw near to battle.', 'order ye the buckler and shield and draw near to battle');
