INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 5, 'Wherefore have I seen them dismayed {and} turned away back? and their mighty ones are beaten down, and are fled apace, and look not back: {for} fear {was} round about, saith the LORD. {beaten...: Heb. broken in pieces} {fled...: Heb. fled a flight}', 'wherefore have i seen them dismayed and turned away back and their mighty ones are beaten down and are fled apace and look not back for fear was round about saith the lord beaten heb broken in pieces fled heb fled a flight');
