INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 9, 'Come up, ye horses; and rage, ye chariots; and let the mighty men come forth; the Ethiopians and the Libyans, that handle the shield; and the Lydians, that handle {and} bend the bow. {the Ethiopians: Heb. Cush} {the Libyans: Heb. Put}', 'come up ye horses and rage ye chariots and let the mighty men come forth the ethiopians and the libyans that handle the shield and the lydians that handle and bend the bow the ethiopians heb cush the libyans heb put');
