INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 11, 'Go up into Gilead, and take balm, O virgin, the daughter of Egypt: in vain shalt thou use many medicines; {for} thou shalt not be cured. {thou shalt...: Heb. no cure shall be unto thee}', 'go up into gilead and take balm o virgin the daughter of egypt in vain shalt thou use many medicines for thou shalt not be cured thou shalt heb no cure shall be unto thee');
