INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 13, 'The word that the LORD spake to Jeremiah the prophet, how Nebuchadrezzar king of Babylon should come {and} smite the land of Egypt.', 'the word that the lord spake to jeremiah the prophet how nebuchadrezzar king of babylon should come and smite the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 14, 'Declare ye in Egypt, and publish in Migdol, and publish in Noph and in Tahpanhes: say ye, Stand fast, and prepare thee; for the sword shall devour round about thee.', 'declare ye in egypt and publish in migdol and publish in noph and in tahpanhes say ye stand fast and prepare thee for the sword shall devour round about thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 15, 'Why are thy valiant {men} swept away? they stood not, because the LORD did drive them.', 'why are thy valiant men swept away they stood not because the lord did drive them');
