INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 18, '{As} I live, saith the King, whose name {is} the LORD of hosts, Surely as Tabor {is} among the mountains, and as Carmel by the sea, {so} shall he come.', 'as i live saith the king whose name is the lord of hosts surely as tabor is among the mountains and as carmel by the sea so shall he come');
