INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 20, 'Egypt {is like} a very fair heifer, {but} destruction cometh; it cometh out of the north.', 'egypt is like a very fair heifer but destruction cometh it cometh out of the north');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 46, 21, 'Also her hired men {are} in the midst of her like fatted bullocks; for they also are turned back, {and} are fled away together: they did not stand, because the day of their calamity was come upon them, {and} the time of their visitation. {fatted...: Heb. bullocks of the stall}', 'also her hired men are in the midst of her like fatted bullocks for they also are turned back and are fled away together they did not stand because the day of their calamity was come upon them and the time of their visitation fatted heb bullocks of the stall');
