INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 49, 21, 'The earth is moved at the noise of their fall, at the cry the noise thereof was heard in the Red sea. {Red sea: Heb. Weedy sea}', 'the earth is moved at the noise of their fall at the cry the noise thereof was heard in the red sea red sea heb weedy sea');
