INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 49, 24, 'Damascus is waxed feeble, {and} turneth herself to flee, and fear hath seized on {her}: anguish and sorrows have taken her, as a woman in travail.', 'damascus is waxed feeble and turneth herself to flee and fear hath seized on her anguish and sorrows have taken her as a woman in travail');
