INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 49, 29, 'Their tents and their flocks shall they take away: they shall take to themselves their curtains, and all their vessels, and their camels; and they shall cry unto them, Fear {is} on every side.', 'their tents and their flocks shall they take away they shall take to themselves their curtains and all their vessels and their camels and they shall cry unto them fear is on every side');
