INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 49, 34, 'The word of the LORD that came to Jeremiah the prophet against Elam in the beginning of the reign of Zedekiah king of Judah, saying,', 'the word of the lord that came to jeremiah the prophet against elam in the beginning of the reign of zedekiah king of judah saying');
