INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 49, 36, 'And upon Elam will I bring the four winds from the four quarters of heaven, and will scatter them toward all those winds; and there shall be no nation whither the outcasts of Elam shall not come.', 'and upon elam will i bring the four winds from the four quarters of heaven and will scatter them toward all those winds and there shall be no nation whither the outcasts of elam shall not come');
