INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 1, 'The word that the LORD spake against Babylon {and} against the land of the Chaldeans by Jeremiah the prophet. {by...: Heb. by the hand of Jeremiah}', 'the word that the lord spake against babylon and against the land of the chaldeans by jeremiah the prophet by heb by the hand of jeremiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 2, 'Declare ye among the nations, and publish, and set up a standard; publish, {and} conceal not: say, Babylon is taken, Bel is confounded, Merodach is broken in pieces; her idols are confounded, her images are broken in pieces. {set up: Heb. lift up}', 'declare ye among the nations and publish and set up a standard publish and conceal not say babylon is taken bel is confounded merodach is broken in pieces her idols are confounded her images are broken in pieces set up heb lift up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 3, 'For out of the north there cometh up a nation against her, which shall make her land desolate, and none shall dwell therein: they shall remove, they shall depart, both man and beast.', 'for out of the north there cometh up a nation against her which shall make her land desolate and none shall dwell therein they shall remove they shall depart both man and beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 4, 'In those days, and in that time, saith the LORD, the children of Israel shall come, they and the children of Judah together, going and weeping: they shall go, and seek the LORD their God.', 'in those days and in that time saith the lord the children of israel shall come they and the children of judah together going and weeping they shall go and seek the lord their god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 5, 'They shall ask the way to Zion with their faces thitherward, {saying}, Come, and let us join ourselves to the LORD in a perpetual covenant {that} shall not be forgotten.', 'they shall ask the way to zion with their faces thitherward saying come and let us join ourselves to the lord in a perpetual covenant that shall not be forgotten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 6, 'My people hath been lost sheep: their shepherds have caused them to go astray, they have turned them away {on} the mountains: they have gone from mountain to hill, they have forgotten their restingplace. {restingplace: Heb. place to lie down in}', 'my people hath been lost sheep their shepherds have caused them to go astray they have turned them away on the mountains they have gone from mountain to hill they have forgotten their restingplace restingplace heb place to lie down in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 7, 'All that found them have devoured them: and their adversaries said, We offend not, because they have sinned against the LORD, the habitation of justice, even the LORD, the hope of their fathers.', 'all that found them have devoured them and their adversaries said we offend not because they have sinned against the lord the habitation of justice even the lord the hope of their fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 8, 'Remove out of the midst of Babylon, and go forth out of the land of the Chaldeans, and be as the he goats before the flocks.', 'remove out of the midst of babylon and go forth out of the land of the chaldeans and be as the he goats before the flocks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 9, 'For, lo, I will raise and cause to come up against Babylon an assembly of great nations from the north country: and they shall set themselves in array against her; from thence she shall be taken: their arrows {shall be} as of a mighty expert man; none shall return in vain. {expert...: or, destroyer}', 'for lo i will raise and cause to come up against babylon an assembly of great nations from the north country and they shall set themselves in array against her from thence she shall be taken their arrows shall be as of a mighty expert man none shall return in vain expert or destroyer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 10, 'And Chaldea shall be a spoil: all that spoil her shall be satisfied, saith the LORD.', 'and chaldea shall be a spoil all that spoil her shall be satisfied saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 11, 'Because ye were glad, because ye rejoiced, O ye destroyers of mine heritage, because ye are grown fat as the heifer at grass, and bellow as bulls; {fat: Heb. big, or, corpulent} {bellow...: or, neigh as steeds}', 'because ye were glad because ye rejoiced o ye destroyers of mine heritage because ye are grown fat as the heifer at grass and bellow as bulls fat heb big or corpulent bellow or neigh as steeds');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 12, 'Your mother shall be sore confounded; she that bare you shall be ashamed: behold, the hindermost of the nations {shall be} a wilderness, a dry land, and a desert.', 'your mother shall be sore confounded she that bare you shall be ashamed behold the hindermost of the nations shall be a wilderness a dry land and a desert');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 50, 13, 'Because of the wrath of the LORD it shall not be inhabited, but it shall be wholly desolate: every one that goeth by Babylon shall be astonished, and hiss at all her plagues.', 'because of the wrath of the lord it shall not be inhabited but it shall be wholly desolate every one that goeth by babylon shall be astonished and hiss at all her plagues');
