INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 27, 'Set ye up a standard in the land, blow the trumpet among the nations, prepare the nations against her, call together against her the kingdoms of Ararat, Minni, and Ashchenaz; appoint a captain against her; cause the horses to come up as the rough caterpillers.', 'set ye up a standard in the land blow the trumpet among the nations prepare the nations against her call together against her the kingdoms of ararat minni and ashchenaz appoint a captain against her cause the horses to come up as the rough caterpillers');
