INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 34, 'Nebuchadrezzar the king of Babylon hath devoured me, he hath crushed me, he hath made me an empty vessel, he hath swallowed me up like a dragon, he hath filled his belly with my delicates, he hath cast me out.', 'nebuchadrezzar the king of babylon hath devoured me he hath crushed me he hath made me an empty vessel he hath swallowed me up like a dragon he hath filled his belly with my delicates he hath cast me out');
