INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 39, 'In their heat I will make their feasts, and I will make them drunken, that they may rejoice, and sleep a perpetual sleep, and not wake, saith the LORD.', 'in their heat i will make their feasts and i will make them drunken that they may rejoice and sleep a perpetual sleep and not wake saith the lord');
