INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 41, 'How is Sheshach taken! and how is the praise of the whole earth surprised! how is Babylon become an astonishment among the nations!', 'how is sheshach taken and how is the praise of the whole earth surprised how is babylon become an astonishment among the nations');
