INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 43, 'Her cities are a desolation, a dry land, and a wilderness, a land wherein no man dwelleth, neither doth {any} son of man pass thereby.', 'her cities are a desolation a dry land and a wilderness a land wherein no man dwelleth neither doth any son of man pass thereby');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 44, 'And I will punish Bel in Babylon, and I will bring forth out of his mouth that which he hath swallowed up: and the nations shall not flow together any more unto him: yea, the wall of Babylon shall fall.', 'and i will punish bel in babylon and i will bring forth out of his mouth that which he hath swallowed up and the nations shall not flow together any more unto him yea the wall of babylon shall fall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 45, 'My people, go ye out of the midst of her, and deliver ye every man his soul from the fierce anger of the LORD.', 'my people go ye out of the midst of her and deliver ye every man his soul from the fierce anger of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 46, 'And lest your heart faint, and ye fear for the rumour that shall be heard in the land; a rumour shall both come {one} year, and after that in {another} year {shall come} a rumour, and violence in the land, ruler against ruler. {lest: or, let not}', 'and lest your heart faint and ye fear for the rumour that shall be heard in the land a rumour shall both come one year and after that in another year shall come a rumour and violence in the land ruler against ruler lest or let not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 47, 'Therefore, behold, the days come, that I will do judgment upon the graven images of Babylon: and her whole land shall be confounded, and all her slain shall fall in the midst of her. {do...: Heb. visit upon}', 'therefore behold the days come that i will do judgment upon the graven images of babylon and her whole land shall be confounded and all her slain shall fall in the midst of her do heb visit upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 48, 'Then the heaven and the earth, and all that {is} therein, shall sing for Babylon: for the spoilers shall come unto her from the north, saith the LORD.', 'then the heaven and the earth and all that is therein shall sing for babylon for the spoilers shall come unto her from the north saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 49, 'As Babylon {hath caused} the slain of Israel to fall, so at Babylon shall fall the slain of all the earth. {As...: or, Both Babylon is to fall, O ye slain of Israel, and with Babylon, etc} {the earth: or, the country}', 'as babylon hath caused the slain of israel to fall so at babylon shall fall the slain of all the earth as or both babylon is to fall o ye slain of israel and with babylon etc the earth or the country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 50, 'Ye that have escaped the sword, go away, stand not still: remember the LORD afar off, and let Jerusalem come into your mind.', 'ye that have escaped the sword go away stand not still remember the lord afar off and let jerusalem come into your mind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 51, 'We are confounded, because we have heard reproach: shame hath covered our faces: for strangers are come into the sanctuaries of the LORD''S house.', 'we are confounded because we have heard reproach shame hath covered our faces for strangers are come into the sanctuaries of the lord s house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 52, 'Wherefore, behold, the days come, saith the LORD, that I will do judgment upon her graven images: and through all her land the wounded shall groan.', 'wherefore behold the days come saith the lord that i will do judgment upon her graven images and through all her land the wounded shall groan');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 53, 'Though Babylon should mount up to heaven, and though she should fortify the height of her strength, {yet} from me shall spoilers come unto her, saith the LORD.', 'though babylon should mount up to heaven and though she should fortify the height of her strength yet from me shall spoilers come unto her saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 54, 'A sound of a cry {cometh} from Babylon, and great destruction from the land of the Chaldeans:', 'a sound of a cry cometh from babylon and great destruction from the land of the chaldeans');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 55, 'Because the LORD hath spoiled Babylon, and destroyed out of her the great voice; when her waves do roar like great waters, a noise of their voice is uttered:', 'because the lord hath spoiled babylon and destroyed out of her the great voice when her waves do roar like great waters a noise of their voice is uttered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 56, 'Because the spoiler is come upon her, {even} upon Babylon, and her mighty men are taken, every one of their bows is broken: for the LORD God of recompences shall surely requite.', 'because the spoiler is come upon her even upon babylon and her mighty men are taken every one of their bows is broken for the lord god of recompences shall surely requite');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 57, 'And I will make drunk her princes, and her wise {men}, her captains, and her rulers, and her mighty men: and they shall sleep a perpetual sleep, and not wake, saith the King, whose name {is} the LORD of hosts.', 'and i will make drunk her princes and her wise men her captains and her rulers and her mighty men and they shall sleep a perpetual sleep and not wake saith the king whose name is the lord of hosts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 58, 'Thus saith the LORD of hosts; The broad walls of Babylon shall be utterly broken, and her high gates shall be burned with fire; and the people shall labour in vain, and the folk in the fire, and they shall be weary. {The broad...: or, The walls of broad Babylon} {broken: or, made naked}', 'thus saith the lord of hosts the broad walls of babylon shall be utterly broken and her high gates shall be burned with fire and the people shall labour in vain and the folk in the fire and they shall be weary the broad or the walls of broad babylon broken or made naked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 59, 'The word which Jeremiah the prophet commanded Seraiah the son of Neriah, the son of Maaseiah, when he went with Zedekiah the king of Judah into Babylon in the fourth year of his reign. And {this} Seraiah {was} a quiet prince. {with: or, on the behalf of} {quiet...: or, prince of Menucha, or, chief chamberlain}', 'the word which jeremiah the prophet commanded seraiah the son of neriah the son of maaseiah when he went with zedekiah the king of judah into babylon in the fourth year of his reign and this seraiah was a quiet prince with or on the behalf of quiet or prince of menucha or chief chamberlain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 60, 'So Jeremiah wrote in a book all the evil that should come upon Babylon, {even} all these words that are written against Babylon.', 'so jeremiah wrote in a book all the evil that should come upon babylon even all these words that are written against babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 61, 'And Jeremiah said to Seraiah, When thou comest to Babylon, and shalt see, and shalt read all these words;', 'and jeremiah said to seraiah when thou comest to babylon and shalt see and shalt read all these words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 62, 'Then shalt thou say, O LORD, thou hast spoken against this place, to cut it off, that none shall remain in it, neither man nor beast, but that it shall be desolate for ever. {desolate: Heb. desolations}', 'then shalt thou say o lord thou hast spoken against this place to cut it off that none shall remain in it neither man nor beast but that it shall be desolate for ever desolate heb desolations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 63, 'And it shall be, when thou hast made an end of reading this book, {that} thou shalt bind a stone to it, and cast it into the midst of Euphrates:', 'and it shall be when thou hast made an end of reading this book that thou shalt bind a stone to it and cast it into the midst of euphrates');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 51, 64, 'And thou shalt say, Thus shall Babylon sink, and shall not rise from the evil that I will bring upon her: and they shall be weary. Thus far {are} the words of Jeremiah.', 'and thou shalt say thus shall babylon sink and shall not rise from the evil that i will bring upon her and they shall be weary thus far are the words of jeremiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 1, 'Zedekiah {was} one and twenty years old when he began to reign, and he reigned eleven years in Jerusalem. And his mother''s name {was} Hamutal the daughter of Jeremiah of Libnah. {began...: Heb. reigned}', 'zedekiah was one and twenty years old when he began to reign and he reigned eleven years in jerusalem and his mother s name was hamutal the daughter of jeremiah of libnah began heb reigned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 2, 'And he did {that which was} evil in the eyes of the LORD, according to all that Jehoiakim had done.', 'and he did that which was evil in the eyes of the lord according to all that jehoiakim had done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 3, 'For through the anger of the LORD it came to pass in Jerusalem and Judah, till he had cast them out from his presence, that Zedekiah rebelled against the king of Babylon.', 'for through the anger of the lord it came to pass in jerusalem and judah till he had cast them out from his presence that zedekiah rebelled against the king of babylon');
