INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 5, 'So the city was besieged unto the eleventh year of king Zedekiah.', 'so the city was besieged unto the eleventh year of king zedekiah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 6, 'And in the fourth month, in the ninth {day} of the month, the famine was sore in the city, so that there was no bread for the people of the land.', 'and in the fourth month in the ninth day of the month the famine was sore in the city so that there was no bread for the people of the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 7, 'Then the city was broken up, and all the men of war fled, and went forth out of the city by night by the way of the gate between the two walls, which {was} by the king''s garden; (now the Chaldeans {were} by the city round about:) and they went by the way of the plain.', 'then the city was broken up and all the men of war fled and went forth out of the city by night by the way of the gate between the two walls which was by the king s garden now the chaldeans were by the city round about and they went by the way of the plain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 8, 'But the army of the Chaldeans pursued after the king, and overtook Zedekiah in the plains of Jericho; and all his army was scattered from him.', 'but the army of the chaldeans pursued after the king and overtook zedekiah in the plains of jericho and all his army was scattered from him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 9, 'Then they took the king, and carried him up unto the king of Babylon to Riblah in the land of Hamath; where he gave judgment upon him.', 'then they took the king and carried him up unto the king of babylon to riblah in the land of hamath where he gave judgment upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 10, 'And the king of Babylon slew the sons of Zedekiah before his eyes: he slew also all the princes of Judah in Riblah.', 'and the king of babylon slew the sons of zedekiah before his eyes he slew also all the princes of judah in riblah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 11, 'Then he put out the eyes of Zedekiah; and the king of Babylon bound him in chains, and carried him to Babylon, and put him in prison till the day of his death. {put out: Heb. blinded} {chains: or, fetters} {prison: Heb. house of the wards}', 'then he put out the eyes of zedekiah and the king of babylon bound him in chains and carried him to babylon and put him in prison till the day of his death put out heb blinded chains or fetters prison heb house of the wards');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 12, 'Now in the fifth month, in the tenth {day} of the month, which {was} the nineteenth year of Nebuchadrezzar king of Babylon, came Nebuzaradan, captain of the guard, {which} served the king of Babylon, into Jerusalem, {captain...: or, chief marshal: Heb. chief of the executioners, or, slaughtermen} {served: Heb. stood before}', 'now in the fifth month in the tenth day of the month which was the nineteenth year of nebuchadrezzar king of babylon came nebuzaradan captain of the guard which served the king of babylon into jerusalem captain or chief marshal heb chief of the executioners or slaughtermen served heb stood before');
