INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 24, 'Unknown', 52, 15, 'Then Nebuzaradan the captain of the guard carried away captive {certain} of the poor of the people, and the residue of the people that remained in the city, and those that fell away, that fell to the king of Babylon, and the rest of the multitude.', 'then nebuzaradan the captain of the guard carried away captive certain of the poor of the people and the residue of the people that remained in the city and those that fell away that fell to the king of babylon and the rest of the multitude');
