INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 3, 16, 'And it came to pass at the end of seven days, that the word of the LORD came unto me, saying,', 'and it came to pass at the end of seven days that the word of the lord came unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 3, 17, 'Son of man, I have made thee a watchman unto the house of Israel: therefore hear the word at my mouth, and give them warning from me.', 'son of man i have made thee a watchman unto the house of israel therefore hear the word at my mouth and give them warning from me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 3, 18, 'When I say unto the wicked, Thou shalt surely die; and thou givest him not warning, nor speakest to warn the wicked from his wicked way, to save his life; the same wicked {man} shall die in his iniquity; but his blood will I require at thine hand.', 'when i say unto the wicked thou shalt surely die and thou givest him not warning nor speakest to warn the wicked from his wicked way to save his life the same wicked man shall die in his iniquity but his blood will i require at thine hand');
