INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 3, 21, 'Nevertheless if thou warn the righteous {man}, that the righteous sin not, and he doth not sin, he shall surely live, because he is warned; also thou hast delivered thy soul.', 'nevertheless if thou warn the righteous man that the righteous sin not and he doth not sin he shall surely live because he is warned also thou hast delivered thy soul');
