INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 4, 1, 'Thou also, son of man, take thee a tile, and lay it before thee, and pourtray upon it the city, {even} Jerusalem:', 'thou also son of man take thee a tile and lay it before thee and pourtray upon it the city even jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 4, 2, 'And lay siege against it, and build a fort against it, and cast a mount against it; set the camp also against it, and set {battering} rams against it round about. {battering...: chief leaders}', 'and lay siege against it and build a fort against it and cast a mount against it set the camp also against it and set battering rams against it round about battering chief leaders');
