INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 4, 4, 'Lie thou also upon thy left side, and lay the iniquity of the house of Israel upon it: {according} to the number of the days that thou shalt lie upon it thou shalt bear their iniquity.', 'lie thou also upon thy left side and lay the iniquity of the house of israel upon it according to the number of the days that thou shalt lie upon it thou shalt bear their iniquity');
