INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 4, 6, 'And when thou hast accomplished them, lie again on thy right side, and thou shalt bear the iniquity of the house of Judah forty days: I have appointed thee each day for a year. {each...: Heb. a day for a year, a day for a year}', 'and when thou hast accomplished them lie again on thy right side and thou shalt bear the iniquity of the house of judah forty days i have appointed thee each day for a year each heb a day for a year a day for a year');
