INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 4, 9, 'Take thou also unto thee wheat, and barley, and beans, and lentiles, and millet, and fitches, and put them in one vessel, and make thee bread thereof, {according} to the number of the days that thou shalt lie upon thy side, three hundred and ninety days shalt thou eat thereof. {fitches: or, spelt}', 'take thou also unto thee wheat and barley and beans and lentiles and millet and fitches and put them in one vessel and make thee bread thereof according to the number of the days that thou shalt lie upon thy side three hundred and ninety days shalt thou eat thereof fitches or spelt');
