INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 3, 'And he put forth the form of an hand, and took me by a lock of mine head; and the spirit lifted me up between the earth and the heaven, and brought me in the visions of God to Jerusalem, to the door of the inner gate that looketh toward the north; where {was} the seat of the image of jealousy, which provoketh to jealousy.', 'and he put forth the form of an hand and took me by a lock of mine head and the spirit lifted me up between the earth and the heaven and brought me in the visions of god to jerusalem to the door of the inner gate that looketh toward the north where was the seat of the image of jealousy which provoketh to jealousy');
