INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 6, 'He said furthermore unto me, Son of man, seest thou what they do? {even} the great abominations that the house of Israel committeth here, that I should go far off from my sanctuary? but turn thee yet again, {and} thou shalt see greater abominations.', 'he said furthermore unto me son of man seest thou what they do even the great abominations that the house of israel committeth here that i should go far off from my sanctuary but turn thee yet again and thou shalt see greater abominations');
