INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 11, 'And there stood before them seventy men of the ancients of the house of Israel, and in the midst of them stood Jaazaniah the son of Shaphan, with every man his censer in his hand; and a thick cloud of incense went up.', 'and there stood before them seventy men of the ancients of the house of israel and in the midst of them stood jaazaniah the son of shaphan with every man his censer in his hand and a thick cloud of incense went up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 12, 'Then said he unto me, Son of man, hast thou seen what the ancients of the house of Israel do in the dark, every man in the chambers of his imagery? for they say, The LORD seeth us not; the LORD hath forsaken the earth.', 'then said he unto me son of man hast thou seen what the ancients of the house of israel do in the dark every man in the chambers of his imagery for they say the lord seeth us not the lord hath forsaken the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 13, 'He said also unto me, Turn thee yet again, {and} thou shalt see greater abominations that they do.', 'he said also unto me turn thee yet again and thou shalt see greater abominations that they do');
