INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 16, 'And he brought me into the inner court of the LORD''S house, and, behold, at the door of the temple of the LORD, between the porch and the altar, {were} about five and twenty men, with their backs toward the temple of the LORD, and their faces toward the east; and they worshipped the sun toward the east.', 'and he brought me into the inner court of the lord s house and behold at the door of the temple of the lord between the porch and the altar were about five and twenty men with their backs toward the temple of the lord and their faces toward the east and they worshipped the sun toward the east');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 8, 17, 'Then he said unto me, Hast thou seen {this}, O son of man? Is it a light thing to the house of Judah that they commit the abominations which they commit here? for they have filled the land with violence, and have returned to provoke me to anger: and, lo, they put the branch to their nose. {Is it...: or, Is there any thing lighter than to commit}', 'then he said unto me hast thou seen this o son of man is it a light thing to the house of judah that they commit the abominations which they commit here for they have filled the land with violence and have returned to provoke me to anger and lo they put the branch to their nose is it or is there any thing lighter than to commit');
