INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 9, 6, 'Slay utterly old {and} young, both maids, and little children, and women: but come not near any man upon whom {is} the mark; and begin at my sanctuary. Then they began at the ancient men which {were} before the house. {utterly: Heb. to destruction}', 'slay utterly old and young both maids and little children and women but come not near any man upon whom is the mark and begin at my sanctuary then they began at the ancient men which were before the house utterly heb to destruction');
