INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 11, 13, 'And it came to pass, when I prophesied, that Pelatiah the son of Benaiah died. Then fell I down upon my face, and cried with a loud voice, and said, Ah Lord GOD! wilt thou make a full end of the remnant of Israel?', 'and it came to pass when i prophesied that pelatiah the son of benaiah died then fell i down upon my face and cried with a loud voice and said ah lord god wilt thou make a full end of the remnant of israel');
