INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 11, 16, 'Therefore say, Thus saith the Lord GOD; Although I have cast them far off among the heathen, and although I have scattered them among the countries, yet will I be to them as a little sanctuary in the countries where they shall come.', 'therefore say thus saith the lord god although i have cast them far off among the heathen and although i have scattered them among the countries yet will i be to them as a little sanctuary in the countries where they shall come');
