INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 11, 18, 'And they shall come thither, and they shall take away all the detestable things thereof and all the abominations thereof from thence.', 'and they shall come thither and they shall take away all the detestable things thereof and all the abominations thereof from thence');
