INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 12, 2, 'Son of man, thou dwellest in the midst of a rebellious house, which have eyes to see, and see not; they have ears to hear, and hear not: for they {are} a rebellious house.', 'son of man thou dwellest in the midst of a rebellious house which have eyes to see and see not they have ears to hear and hear not for they are a rebellious house');
