INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 12, 7, 'And I did so as I was commanded: I brought forth my stuff by day, as stuff for captivity, and in the even I digged through the wall with mine hand; I brought {it} forth in the twilight, {and} I bare {it} upon {my} shoulder in their sight. {digged: Heb. digged for me}', 'and i did so as i was commanded i brought forth my stuff by day as stuff for captivity and in the even i digged through the wall with mine hand i brought it forth in the twilight and i bare it upon my shoulder in their sight digged heb digged for me');
