INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 13, 6, 'They have seen vanity and lying divination, saying, The LORD saith: and the LORD hath not sent them: and they have made {others} to hope that they would confirm the word.', 'they have seen vanity and lying divination saying the lord saith and the lord hath not sent them and they have made others to hope that they would confirm the word');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 13, 7, 'Have ye not seen a vain vision, and have ye not spoken a lying divination, whereas ye say, The LORD saith {it}; albeit I have not spoken?', 'have ye not seen a vain vision and have ye not spoken a lying divination whereas ye say the lord saith it albeit i have not spoken');
