INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 13, 10, 'Because, even because they have seduced my people, saying, Peace; and {there was} no peace; and one built up a wall, and, lo, others daubed it with untempered {morter}: {a wall: or, a slight wall}', 'because even because they have seduced my people saying peace and there was no peace and one built up a wall and lo others daubed it with untempered morter a wall or a slight wall');
