INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 13, 16, '{To wit}, the prophets of Israel which prophesy concerning Jerusalem, and which see visions of peace for her, and {there is} no peace, saith the Lord GOD.', 'to wit the prophets of israel which prophesy concerning jerusalem and which see visions of peace for her and there is no peace saith the lord god');
