INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 13, 22, 'Because with lies ye have made the heart of the righteous sad, whom I have not made sad; and strengthened the hands of the wicked, that he should not return from his wicked way, by promising him life: {by...: or, that I should save his life: Heb. by quickening him}', 'because with lies ye have made the heart of the righteous sad whom i have not made sad and strengthened the hands of the wicked that he should not return from his wicked way by promising him life by or that i should save his life heb by quickening him');
