INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 14, 11, 'That the house of Israel may go no more astray from me, neither be polluted any more with all their transgressions; but that they may be my people, and I may be their God, saith the Lord GOD.', 'that the house of israel may go no more astray from me neither be polluted any more with all their transgressions but that they may be my people and i may be their god saith the lord god');
