INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 17, 16, '{As} I live, saith the Lord GOD, surely in the place {where} the king {dwelleth} that made him king, whose oath he despised, and whose covenant he brake, {even} with him in the midst of Babylon he shall die.', 'as i live saith the lord god surely in the place where the king dwelleth that made him king whose oath he despised and whose covenant he brake even with him in the midst of babylon he shall die');
