INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 18, 19, 'Yet say ye, Why? doth not the son bear the iniquity of the father? When the son hath done that which is lawful and right, {and} hath kept all my statutes, and hath done them, he shall surely live.', 'yet say ye why doth not the son bear the iniquity of the father when the son hath done that which is lawful and right and hath kept all my statutes and hath done them he shall surely live');
