INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 18, 27, 'Again, when the wicked {man} turneth away from his wickedness that he hath committed, and doeth that which is lawful and right, he shall save his soul alive.', 'again when the wicked man turneth away from his wickedness that he hath committed and doeth that which is lawful and right he shall save his soul alive');
