INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 18, 29, 'Yet saith the house of Israel, The way of the Lord is not equal. O house of Israel, are not my ways equal? are not your ways unequal?', 'yet saith the house of israel the way of the lord is not equal o house of israel are not my ways equal are not your ways unequal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 18, 30, 'Therefore I will judge you, O house of Israel, every one according to his ways, saith the Lord GOD. Repent, and turn {yourselves} from all your transgressions; so iniquity shall not be your ruin. {yourselves: or, others}', 'therefore i will judge you o house of israel every one according to his ways saith the lord god repent and turn yourselves from all your transgressions so iniquity shall not be your ruin yourselves or others');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 18, 31, 'Cast away from you all your transgressions, whereby ye have transgressed; and make you a new heart and a new spirit: for why will ye die, O house of Israel?', 'cast away from you all your transgressions whereby ye have transgressed and make you a new heart and a new spirit for why will ye die o house of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 18, 32, 'For I have no pleasure in the death of him that dieth, saith the Lord GOD: wherefore turn {yourselves}, and live ye. {yourselves: or, others}', 'for i have no pleasure in the death of him that dieth saith the lord god wherefore turn yourselves and live ye yourselves or others');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 1, 'Moreover take thou up a lamentation for the princes of Israel,', 'moreover take thou up a lamentation for the princes of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 2, 'And say, What {is} thy mother? A lioness: she lay down among lions, she nourished her whelps among young lions.', 'and say what is thy mother a lioness she lay down among lions she nourished her whelps among young lions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 3, 'And she brought up one of her whelps: it became a young lion, and it learned to catch the prey; it devoured men.', 'and she brought up one of her whelps it became a young lion and it learned to catch the prey it devoured men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 4, 'The nations also heard of him; he was taken in their pit, and they brought him with chains unto the land of Egypt.', 'the nations also heard of him he was taken in their pit and they brought him with chains unto the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 5, 'Now when she saw that she had waited, {and} her hope was lost, then she took another of her whelps, {and} made him a young lion.', 'now when she saw that she had waited and her hope was lost then she took another of her whelps and made him a young lion');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 6, 'And he went up and down among the lions, he became a young lion, and learned to catch the prey, {and} devoured men.', 'and he went up and down among the lions he became a young lion and learned to catch the prey and devoured men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 7, 'And he knew their desolate palaces, and he laid waste their cities; and the land was desolate, and the fulness thereof, by the noise of his roaring. {their desolate...: or, their widows} {the fulness...: or, all it containeth}', 'and he knew their desolate palaces and he laid waste their cities and the land was desolate and the fulness thereof by the noise of his roaring their desolate or their widows the fulness or all it containeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 8, 'Then the nations set against him on every side from the provinces, and spread their net over him: he was taken in their pit.', 'then the nations set against him on every side from the provinces and spread their net over him he was taken in their pit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 9, 'And they put him in ward in chains, and brought him to the king of Babylon: they brought him into holds, that his voice should no more be heard upon the mountains of Israel. {in chains: or, in hooks}', 'and they put him in ward in chains and brought him to the king of babylon they brought him into holds that his voice should no more be heard upon the mountains of israel in chains or in hooks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 10, 'Thy mother {is} like a vine in thy blood, planted by the waters: she was fruitful and full of branches by reason of many waters. {in...: or, in thy quietness, or, in thy likeness}', 'thy mother is like a vine in thy blood planted by the waters she was fruitful and full of branches by reason of many waters in or in thy quietness or in thy likeness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 11, 'And she had strong rods for the sceptres of them that bare rule, and her stature was exalted among the thick branches, and she appeared in her height with the multitude of her branches.', 'and she had strong rods for the sceptres of them that bare rule and her stature was exalted among the thick branches and she appeared in her height with the multitude of her branches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 12, 'But she was plucked up in fury, she was cast down to the ground, and the east wind dried up her fruit: her strong rods were broken and withered; the fire consumed them.', 'but she was plucked up in fury she was cast down to the ground and the east wind dried up her fruit her strong rods were broken and withered the fire consumed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 13, 'And now she {is} planted in the wilderness, in a dry and thirsty ground.', 'and now she is planted in the wilderness in a dry and thirsty ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 19, 14, 'And fire is gone out of a rod of her branches, {which} hath devoured her fruit, so that she hath no strong rod {to be} a sceptre to rule. This {is} a lamentation, and shall be for a lamentation.', 'and fire is gone out of a rod of her branches which hath devoured her fruit so that she hath no strong rod to be a sceptre to rule this is a lamentation and shall be for a lamentation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 1, 'And it came to pass in the seventh year, in the fifth {month}, the tenth {day} of the month, {that} certain of the elders of Israel came to enquire of the LORD, and sat before me.', 'and it came to pass in the seventh year in the fifth month the tenth day of the month that certain of the elders of israel came to enquire of the lord and sat before me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 2, 'Then came the word of the LORD unto me, saying,', 'then came the word of the lord unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 3, 'Son of man, speak unto the elders of Israel, and say unto them, Thus saith the Lord GOD; Are ye come to enquire of me? {As} I live, saith the Lord GOD, I will not be enquired of by you.', 'son of man speak unto the elders of israel and say unto them thus saith the lord god are ye come to enquire of me as i live saith the lord god i will not be enquired of by you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 4, 'Wilt thou judge them, son of man, wilt thou judge {them}? cause them to know the abominations of their fathers: {Wilt...: or, Wilt thou plead for them}', 'wilt thou judge them son of man wilt thou judge them cause them to know the abominations of their fathers wilt or wilt thou plead for them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 5, 'And say unto them, Thus saith the Lord GOD; In the day when I chose Israel, and lifted up mine hand unto the seed of the house of Jacob, and made myself known unto them in the land of Egypt, when I lifted up mine hand unto them, saying, I {am} the LORD your God; {lifted...: or, sware}', 'and say unto them thus saith the lord god in the day when i chose israel and lifted up mine hand unto the seed of the house of jacob and made myself known unto them in the land of egypt when i lifted up mine hand unto them saying i am the lord your god lifted or sware');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 6, 'In the day {that} I lifted up mine hand unto them, to bring them forth of the land of Egypt into a land that I had espied for them, flowing with milk and honey, which {is} the glory of all lands:', 'in the day that i lifted up mine hand unto them to bring them forth of the land of egypt into a land that i had espied for them flowing with milk and honey which is the glory of all lands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 7, 'Then said I unto them, Cast ye away every man the abominations of his eyes, and defile not yourselves with the idols of Egypt: I {am} the LORD your God.', 'then said i unto them cast ye away every man the abominations of his eyes and defile not yourselves with the idols of egypt i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 8, 'But they rebelled against me, and would not hearken unto me: they did not every man cast away the abominations of their eyes, neither did they forsake the idols of Egypt: then I said, I will pour out my fury upon them, to accomplish my anger against them in the midst of the land of Egypt.', 'but they rebelled against me and would not hearken unto me they did not every man cast away the abominations of their eyes neither did they forsake the idols of egypt then i said i will pour out my fury upon them to accomplish my anger against them in the midst of the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 9, 'But I wrought for my name''s sake, that it should not be polluted before the heathen, among whom they {were}, in whose sight I made myself known unto them, in bringing them forth out of the land of Egypt.', 'but i wrought for my name s sake that it should not be polluted before the heathen among whom they were in whose sight i made myself known unto them in bringing them forth out of the land of egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 10, 'Wherefore I caused them to go forth out of the land of Egypt, and brought them into the wilderness.', 'wherefore i caused them to go forth out of the land of egypt and brought them into the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 11, 'And I gave them my statutes, and shewed them my judgments, which {if} a man do, he shall even live in them. {shewed...: Heb. made them to know}', 'and i gave them my statutes and shewed them my judgments which if a man do he shall even live in them shewed heb made them to know');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 12, 'Moreover also I gave them my sabbaths, to be a sign between me and them, that they might know that I {am} the LORD that sanctify them.', 'moreover also i gave them my sabbaths to be a sign between me and them that they might know that i am the lord that sanctify them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 13, 'But the house of Israel rebelled against me in the wilderness: they walked not in my statutes, and they despised my judgments, which {if} a man do, he shall even live in them; and my sabbaths they greatly polluted: then I said, I would pour out my fury upon them in the wilderness, to consume them.', 'but the house of israel rebelled against me in the wilderness they walked not in my statutes and they despised my judgments which if a man do he shall even live in them and my sabbaths they greatly polluted then i said i would pour out my fury upon them in the wilderness to consume them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 14, 'But I wrought for my name''s sake, that it should not be polluted before the heathen, in whose sight I brought them out.', 'but i wrought for my name s sake that it should not be polluted before the heathen in whose sight i brought them out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 15, 'Yet also I lifted up my hand unto them in the wilderness, that I would not bring them into the land which I had given {them}, flowing with milk and honey, which {is} the glory of all lands;', 'yet also i lifted up my hand unto them in the wilderness that i would not bring them into the land which i had given them flowing with milk and honey which is the glory of all lands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 16, 'Because they despised my judgments, and walked not in my statutes, but polluted my sabbaths: for their heart went after their idols.', 'because they despised my judgments and walked not in my statutes but polluted my sabbaths for their heart went after their idols');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 17, 'Nevertheless mine eye spared them from destroying them, neither did I make an end of them in the wilderness.', 'nevertheless mine eye spared them from destroying them neither did i make an end of them in the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 18, 'But I said unto their children in the wilderness, Walk ye not in the statutes of your fathers, neither observe their judgments, nor defile yourselves with their idols:', 'but i said unto their children in the wilderness walk ye not in the statutes of your fathers neither observe their judgments nor defile yourselves with their idols');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 19, 'I {am} the LORD your God; walk in my statutes, and keep my judgments, and do them;', 'i am the lord your god walk in my statutes and keep my judgments and do them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 20, 'And hallow my sabbaths; and they shall be a sign between me and you, that ye may know that I {am} the LORD your God.', 'and hallow my sabbaths and they shall be a sign between me and you that ye may know that i am the lord your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 21, 'Notwithstanding the children rebelled against me: they walked not in my statutes, neither kept my judgments to do them, which {if} a man do, he shall even live in them; they polluted my sabbaths: then I said, I would pour out my fury upon them, to accomplish my anger against them in the wilderness.', 'notwithstanding the children rebelled against me they walked not in my statutes neither kept my judgments to do them which if a man do he shall even live in them they polluted my sabbaths then i said i would pour out my fury upon them to accomplish my anger against them in the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 22, 'Nevertheless I withdrew mine hand, and wrought for my name''s sake, that it should not be polluted in the sight of the heathen, in whose sight I brought them forth.', 'nevertheless i withdrew mine hand and wrought for my name s sake that it should not be polluted in the sight of the heathen in whose sight i brought them forth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 23, 'I lifted up mine hand unto them also in the wilderness, that I would scatter them among the heathen, and disperse them through the countries;', 'i lifted up mine hand unto them also in the wilderness that i would scatter them among the heathen and disperse them through the countries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 24, 'Because they had not executed my judgments, but had despised my statutes, and had polluted my sabbaths, and their eyes were after their fathers'' idols.', 'because they had not executed my judgments but had despised my statutes and had polluted my sabbaths and their eyes were after their fathers idols');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 25, 'Wherefore I gave them also statutes {that were} not good, and judgments whereby they should not live;', 'wherefore i gave them also statutes that were not good and judgments whereby they should not live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 26, 'And I polluted them in their own gifts, in that they caused to pass through {the fire} all that openeth the womb, that I might make them desolate, to the end that they might know that I {am} the LORD.', 'and i polluted them in their own gifts in that they caused to pass through the fire all that openeth the womb that i might make them desolate to the end that they might know that i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 27, 'Therefore, son of man, speak unto the house of Israel, and say unto them, Thus saith the Lord GOD; Yet in this your fathers have blasphemed me, in that they have committed a trespass against me. {committed...: Heb. trespassed a trespass}', 'therefore son of man speak unto the house of israel and say unto them thus saith the lord god yet in this your fathers have blasphemed me in that they have committed a trespass against me committed heb trespassed a trespass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 28, '{For} when I had brought them into the land, {for} the which I lifted up mine hand to give it to them, then they saw every high hill, and all the thick trees, and they offered there their sacrifices, and there they presented the provocation of their offering: there also they made their sweet savour, and poured out there their drink offerings.', 'for when i had brought them into the land for the which i lifted up mine hand to give it to them then they saw every high hill and all the thick trees and they offered there their sacrifices and there they presented the provocation of their offering there also they made their sweet savour and poured out there their drink offerings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 29, 'Then I said unto them, What {is} the high place whereunto ye go? And the name thereof is called Bamah unto this day. {I said...: or, I told them what the high place was, or, Bamah}', 'then i said unto them what is the high place whereunto ye go and the name thereof is called bamah unto this day i said or i told them what the high place was or bamah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 30, 'Wherefore say unto the house of Israel, Thus saith the Lord GOD; Are ye polluted after the manner of your fathers? and commit ye whoredom after their abominations?', 'wherefore say unto the house of israel thus saith the lord god are ye polluted after the manner of your fathers and commit ye whoredom after their abominations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 31, 'For when ye offer your gifts, when ye make your sons to pass through the fire, ye pollute yourselves with all your idols, even unto this day: and shall I be enquired of by you, O house of Israel? {As} I live, saith the Lord GOD, I will not be enquired of by you.', 'for when ye offer your gifts when ye make your sons to pass through the fire ye pollute yourselves with all your idols even unto this day and shall i be enquired of by you o house of israel as i live saith the lord god i will not be enquired of by you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 32, 'And that which cometh into your mind shall not be at all, that ye say, We will be as the heathen, as the families of the countries, to serve wood and stone.', 'and that which cometh into your mind shall not be at all that ye say we will be as the heathen as the families of the countries to serve wood and stone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 33, '{As} I live, saith the Lord GOD, surely with a mighty hand, and with a stretched out arm, and with fury poured out, will I rule over you:', 'as i live saith the lord god surely with a mighty hand and with a stretched out arm and with fury poured out will i rule over you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 34, 'And I will bring you out from the people, and will gather you out of the countries wherein ye are scattered, with a mighty hand, and with a stretched out arm, and with fury poured out.', 'and i will bring you out from the people and will gather you out of the countries wherein ye are scattered with a mighty hand and with a stretched out arm and with fury poured out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 35, 'And I will bring you into the wilderness of the people, and there will I plead with you face to face.', 'and i will bring you into the wilderness of the people and there will i plead with you face to face');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 36, 'Like as I pleaded with your fathers in the wilderness of the land of Egypt, so will I plead with you, saith the Lord GOD.', 'like as i pleaded with your fathers in the wilderness of the land of egypt so will i plead with you saith the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 37, 'And I will cause you to pass under the rod, and I will bring you into the bond of the covenant: {bond: or, delivering}', 'and i will cause you to pass under the rod and i will bring you into the bond of the covenant bond or delivering');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 38, 'And I will purge out from among you the rebels, and them that transgress against me: I will bring them forth out of the country where they sojourn, and they shall not enter into the land of Israel: and ye shall know that I {am} the LORD.', 'and i will purge out from among you the rebels and them that transgress against me i will bring them forth out of the country where they sojourn and they shall not enter into the land of israel and ye shall know that i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 39, 'As for you, O house of Israel, thus saith the Lord GOD; Go ye, serve ye every one his idols, and hereafter {also}, if ye will not hearken unto me: but pollute ye my holy name no more with your gifts, and with your idols.', 'as for you o house of israel thus saith the lord god go ye serve ye every one his idols and hereafter also if ye will not hearken unto me but pollute ye my holy name no more with your gifts and with your idols');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 20, 40, 'For in mine holy mountain, in the mountain of the height of Israel, saith the Lord GOD, there shall all the house of Israel, all of them in the land, serve me: there will I accept them, and there will I require your offerings, and the firstfruits of your oblations, with all your holy things. {firstfruits: or, chief}', 'for in mine holy mountain in the mountain of the height of israel saith the lord god there shall all the house of israel all of them in the land serve me there will i accept them and there will i require your offerings and the firstfruits of your oblations with all your holy things firstfruits or chief');
