INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 23, 17, 'And the Babylonians came to her into the bed of love, and they defiled her with their whoredom, and she was polluted with them, and her mind was alienated from them. {Babylonians: Heb. children of Babel} {alienated: Heb. loosed, or, disjointed}', 'and the babylonians came to her into the bed of love and they defiled her with their whoredom and she was polluted with them and her mind was alienated from them babylonians heb children of babel alienated heb loosed or disjointed');
