INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 27, 16, 'Syria {was} thy merchant by reason of the multitude of the wares of thy making: they occupied in thy fairs with emeralds, purple, and broidered work, and fine linen, and coral, and agate. {the wares...: Heb. thy works} {agate: or, chrysoprase}', 'syria was thy merchant by reason of the multitude of the wares of thy making they occupied in thy fairs with emeralds purple and broidered work and fine linen and coral and agate the wares heb thy works agate or chrysoprase');
