INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 7, 'Behold, therefore I will bring strangers upon thee, the terrible of the nations: and they shall draw their swords against the beauty of thy wisdom, and they shall defile thy brightness.', 'behold therefore i will bring strangers upon thee the terrible of the nations and they shall draw their swords against the beauty of thy wisdom and they shall defile thy brightness');
