INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 12, 'Son of man, take up a lamentation upon the king of Tyrus, and say unto him, Thus saith the Lord GOD; Thou sealest up the sum, full of wisdom, and perfect in beauty.', 'son of man take up a lamentation upon the king of tyrus and say unto him thus saith the lord god thou sealest up the sum full of wisdom and perfect in beauty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 13, 'Thou hast been in Eden the garden of God; every precious stone {was} thy covering, the sardius, topaz, and the diamond, the beryl, the onyx, and the jasper, the sapphire, the emerald, and the carbuncle, and gold: the workmanship of thy tabrets and of thy pipes was prepared in thee in the day that thou wast created. {sardius: or, ruby} {beryl: or, chrysolite} {emerald: or, chrysoprase}', 'thou hast been in eden the garden of god every precious stone was thy covering the sardius topaz and the diamond the beryl the onyx and the jasper the sapphire the emerald and the carbuncle and gold the workmanship of thy tabrets and of thy pipes was prepared in thee in the day that thou wast created sardius or ruby beryl or chrysolite emerald or chrysoprase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 14, 'Thou {art} the anointed cherub that covereth; and I have set thee {so}: thou wast upon the holy mountain of God; thou hast walked up and down in the midst of the stones of fire.', 'thou art the anointed cherub that covereth and i have set thee so thou wast upon the holy mountain of god thou hast walked up and down in the midst of the stones of fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 15, 'Thou {wast} perfect in thy ways from the day that thou wast created, till iniquity was found in thee.', 'thou wast perfect in thy ways from the day that thou wast created till iniquity was found in thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 16, 'By the multitude of thy merchandise they have filled the midst of thee with violence, and thou hast sinned: therefore I will cast thee as profane out of the mountain of God: and I will destroy thee, O covering cherub, from the midst of the stones of fire.', 'by the multitude of thy merchandise they have filled the midst of thee with violence and thou hast sinned therefore i will cast thee as profane out of the mountain of god and i will destroy thee o covering cherub from the midst of the stones of fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 17, 'Thine heart was lifted up because of thy beauty, thou hast corrupted thy wisdom by reason of thy brightness: I will cast thee to the ground, I will lay thee before kings, that they may behold thee.', 'thine heart was lifted up because of thy beauty thou hast corrupted thy wisdom by reason of thy brightness i will cast thee to the ground i will lay thee before kings that they may behold thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 18, 'Thou hast defiled thy sanctuaries by the multitude of thine iniquities, by the iniquity of thy traffick; therefore will I bring forth a fire from the midst of thee, it shall devour thee, and I will bring thee to ashes upon the earth in the sight of all them that behold thee.', 'thou hast defiled thy sanctuaries by the multitude of thine iniquities by the iniquity of thy traffick therefore will i bring forth a fire from the midst of thee it shall devour thee and i will bring thee to ashes upon the earth in the sight of all them that behold thee');
