INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 24, 'And there shall be no more a pricking brier unto the house of Israel, nor {any} grieving thorn of all {that are} round about them, that despised them; and they shall know that I {am} the Lord GOD.', 'and there shall be no more a pricking brier unto the house of israel nor any grieving thorn of all that are round about them that despised them and they shall know that i am the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 28, 25, 'Thus saith the Lord GOD; When I shall have gathered the house of Israel from the people among whom they are scattered, and shall be sanctified in them in the sight of the heathen, then shall they dwell in their land that I have given to my servant Jacob.', 'thus saith the lord god when i shall have gathered the house of israel from the people among whom they are scattered and shall be sanctified in them in the sight of the heathen then shall they dwell in their land that i have given to my servant jacob');
