INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 2, 'Son of man, set thy face against Pharaoh king of Egypt, and prophesy against him, and against all Egypt:', 'son of man set thy face against pharaoh king of egypt and prophesy against him and against all egypt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 3, 'Speak, and say, Thus saith the Lord GOD; Behold, I {am} against thee, Pharaoh king of Egypt, the great dragon that lieth in the midst of his rivers, which hath said, My river {is} mine own, and I have made {it} for myself.', 'speak and say thus saith the lord god behold i am against thee pharaoh king of egypt the great dragon that lieth in the midst of his rivers which hath said my river is mine own and i have made it for myself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 4, 'But I will put hooks in thy jaws, and I will cause the fish of thy rivers to stick unto thy scales, and I will bring thee up out of the midst of thy rivers, and all the fish of thy rivers shall stick unto thy scales.', 'but i will put hooks in thy jaws and i will cause the fish of thy rivers to stick unto thy scales and i will bring thee up out of the midst of thy rivers and all the fish of thy rivers shall stick unto thy scales');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 5, 'And I will leave thee {thrown} into the wilderness, thee and all the fish of thy rivers: thou shalt fall upon the open fields; thou shalt not be brought together, nor gathered: I have given thee for meat to the beasts of the field and to the fowls of the heaven. {open...: Heb. face of the field}', 'and i will leave thee thrown into the wilderness thee and all the fish of thy rivers thou shalt fall upon the open fields thou shalt not be brought together nor gathered i have given thee for meat to the beasts of the field and to the fowls of the heaven open heb face of the field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 6, 'And all the inhabitants of Egypt shall know that I {am} the LORD, because they have been a staff of reed to the house of Israel.', 'and all the inhabitants of egypt shall know that i am the lord because they have been a staff of reed to the house of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 7, 'When they took hold of thee by thy hand, thou didst break, and rend all their shoulder: and when they leaned upon thee, thou brakest, and madest all their loins to be at a stand.', 'when they took hold of thee by thy hand thou didst break and rend all their shoulder and when they leaned upon thee thou brakest and madest all their loins to be at a stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 8, 'Therefore thus saith the Lord GOD; Behold, I will bring a sword upon thee, and cut off man and beast out of thee.', 'therefore thus saith the lord god behold i will bring a sword upon thee and cut off man and beast out of thee');
