INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 10, 'Behold, therefore I {am} against thee, and against thy rivers, and I will make the land of Egypt utterly waste {and} desolate, from the tower of Syene even unto the border of Ethiopia. {utterly...: Heb. wastes of waste} {from...: or, from Migdol to Syene} {Syene: Heb. Seveneh}', 'behold therefore i am against thee and against thy rivers and i will make the land of egypt utterly waste and desolate from the tower of syene even unto the border of ethiopia utterly heb wastes of waste from or from migdol to syene syene heb seveneh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 11, 'No foot of man shall pass through it, nor foot of beast shall pass through it, neither shall it be inhabited forty years.', 'no foot of man shall pass through it nor foot of beast shall pass through it neither shall it be inhabited forty years');
