INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 17, 'And it came to pass in the seven and twentieth year, in the first {month}, in the first {day} of the month, the word of the LORD came unto me, saying,', 'and it came to pass in the seven and twentieth year in the first month in the first day of the month the word of the lord came unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 29, 18, 'Son of man, Nebuchadrezzar king of Babylon caused his army to serve a great service against Tyrus: every head {was} made bald, and every shoulder {was} peeled: yet had he no wages, nor his army, for Tyrus, for the service that he had served against it:', 'son of man nebuchadrezzar king of babylon caused his army to serve a great service against tyrus every head was made bald and every shoulder was peeled yet had he no wages nor his army for tyrus for the service that he had served against it');
