INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 30, 3, 'For the day {is} near, even the day of the LORD {is} near, a cloudy day; it shall be the time of the heathen.', 'for the day is near even the day of the lord is near a cloudy day it shall be the time of the heathen');
