INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 30, 8, 'And they shall know that I {am} the LORD, when I have set a fire in Egypt, and {when} all her helpers shall be destroyed. {destroyed: Heb. broken}', 'and they shall know that i am the lord when i have set a fire in egypt and when all her helpers shall be destroyed destroyed heb broken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 30, 9, 'In that day shall messengers go forth from me in ships to make the careless Ethiopians afraid, and great pain shall come upon them, as in the day of Egypt: for, lo, it cometh.', 'in that day shall messengers go forth from me in ships to make the careless ethiopians afraid and great pain shall come upon them as in the day of egypt for lo it cometh');
