INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 30, 11, 'He and his people with him, the terrible of the nations, shall be brought to destroy the land: and they shall draw their swords against Egypt, and fill the land with the slain.', 'he and his people with him the terrible of the nations shall be brought to destroy the land and they shall draw their swords against egypt and fill the land with the slain');
