INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 2, 'Son of man, speak unto Pharaoh king of Egypt, and to his multitude; Whom art thou like in thy greatness?', 'son of man speak unto pharaoh king of egypt and to his multitude whom art thou like in thy greatness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 3, 'Behold, the Assyrian {was} a cedar in Lebanon with fair branches, and with a shadowing shroud, and of an high stature; and his top was among the thick boughs. {with fair branches: Heb. fair of branches}', 'behold the assyrian was a cedar in lebanon with fair branches and with a shadowing shroud and of an high stature and his top was among the thick boughs with fair branches heb fair of branches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 4, 'The waters made him great, the deep set him up on high with her rivers running round about his plants, and sent out her little rivers unto all the trees of the field. {made...: or, nourished him} {set...: or, brought him up} {little rivers: or, conduits}', 'the waters made him great the deep set him up on high with her rivers running round about his plants and sent out her little rivers unto all the trees of the field made or nourished him set or brought him up little rivers or conduits');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 5, 'Therefore his height was exalted above all the trees of the field, and his boughs were multiplied, and his branches became long because of the multitude of waters, when he shot forth. {when...: or, when it sent them forth}', 'therefore his height was exalted above all the trees of the field and his boughs were multiplied and his branches became long because of the multitude of waters when he shot forth when or when it sent them forth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 6, 'All the fowls of heaven made their nests in his boughs, and under his branches did all the beasts of the field bring forth their young, and under his shadow dwelt all great nations.', 'all the fowls of heaven made their nests in his boughs and under his branches did all the beasts of the field bring forth their young and under his shadow dwelt all great nations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 7, 'Thus was he fair in his greatness, in the length of his branches: for his root was by great waters.', 'thus was he fair in his greatness in the length of his branches for his root was by great waters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 8, 'The cedars in the garden of God could not hide him: the fir trees were not like his boughs, and the chesnut trees were not like his branches; nor any tree in the garden of God was like unto him in his beauty.', 'the cedars in the garden of god could not hide him the fir trees were not like his boughs and the chesnut trees were not like his branches nor any tree in the garden of god was like unto him in his beauty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 9, 'I have made him fair by the multitude of his branches: so that all the trees of Eden, that {were} in the garden of God, envied him.', 'i have made him fair by the multitude of his branches so that all the trees of eden that were in the garden of god envied him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 10, 'Therefore thus saith the Lord GOD; Because thou hast lifted up thyself in height, and he hath shot up his top among the thick boughs, and his heart is lifted up in his height;', 'therefore thus saith the lord god because thou hast lifted up thyself in height and he hath shot up his top among the thick boughs and his heart is lifted up in his height');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 11, 'I have therefore delivered him into the hand of the mighty one of the heathen; he shall surely deal with him: I have driven him out for his wickedness. {he...: Heb. in doing he shall do unto him}', 'i have therefore delivered him into the hand of the mighty one of the heathen he shall surely deal with him i have driven him out for his wickedness he heb in doing he shall do unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 12, 'And strangers, the terrible of the nations, have cut him off, and have left him: upon the mountains and in all the valleys his branches are fallen, and his boughs are broken by all the rivers of the land; and all the people of the earth are gone down from his shadow, and have left him.', 'and strangers the terrible of the nations have cut him off and have left him upon the mountains and in all the valleys his branches are fallen and his boughs are broken by all the rivers of the land and all the people of the earth are gone down from his shadow and have left him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 13, 'Upon his ruin shall all the fowls of the heaven remain, and all the beasts of the field shall be upon his branches:', 'upon his ruin shall all the fowls of the heaven remain and all the beasts of the field shall be upon his branches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 14, 'To the end that none of all the trees by the waters exalt themselves for their height, neither shoot up their top among the thick boughs, neither their trees stand up in their height, all that drink water: for they are all delivered unto death, to the nether parts of the earth, in the midst of the children of men, with them that go down to the pit. {their trees...: or, stand upon themselves for their height}', 'to the end that none of all the trees by the waters exalt themselves for their height neither shoot up their top among the thick boughs neither their trees stand up in their height all that drink water for they are all delivered unto death to the nether parts of the earth in the midst of the children of men with them that go down to the pit their trees or stand upon themselves for their height');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 15, 'Thus saith the Lord GOD; In the day when he went down to the grave I caused a mourning: I covered the deep for him, and I restrained the floods thereof, and the great waters were stayed: and I caused Lebanon to mourn for him, and all the trees of the field fainted for him. {to mourn: Heb. to be black}', 'thus saith the lord god in the day when he went down to the grave i caused a mourning i covered the deep for him and i restrained the floods thereof and the great waters were stayed and i caused lebanon to mourn for him and all the trees of the field fainted for him to mourn heb to be black');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 16, 'I made the nations to shake at the sound of his fall, when I cast him down to hell with them that descend into the pit: and all the trees of Eden, the choice and best of Lebanon, all that drink water, shall be comforted in the nether parts of the earth.', 'i made the nations to shake at the sound of his fall when i cast him down to hell with them that descend into the pit and all the trees of eden the choice and best of lebanon all that drink water shall be comforted in the nether parts of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 17, 'They also went down into hell with him unto {them that be} slain with the sword; and {they that were} his arm, {that} dwelt under his shadow in the midst of the heathen.', 'they also went down into hell with him unto them that be slain with the sword and they that were his arm that dwelt under his shadow in the midst of the heathen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 31, 18, 'To whom art thou thus like in glory and in greatness among the trees of Eden? yet shalt thou be brought down with the trees of Eden unto the nether parts of the earth: thou shalt lie in the midst of the uncircumcised with {them that be} slain by the sword. This {is} Pharaoh and all his multitude, saith the Lord GOD.', 'to whom art thou thus like in glory and in greatness among the trees of eden yet shalt thou be brought down with the trees of eden unto the nether parts of the earth thou shalt lie in the midst of the uncircumcised with them that be slain by the sword this is pharaoh and all his multitude saith the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 1, 'And it came to pass in the twelfth year, in the twelfth month, in the first {day} of the month, {that} the word of the LORD came unto me, saying,', 'and it came to pass in the twelfth year in the twelfth month in the first day of the month that the word of the lord came unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 2, 'Son of man, take up a lamentation for Pharaoh king of Egypt, and say unto him, Thou art like a young lion of the nations, and thou {art} as a whale in the seas: and thou camest forth with thy rivers, and troubledst the waters with thy feet, and fouledst their rivers. {whale: or, dragon}', 'son of man take up a lamentation for pharaoh king of egypt and say unto him thou art like a young lion of the nations and thou art as a whale in the seas and thou camest forth with thy rivers and troubledst the waters with thy feet and fouledst their rivers whale or dragon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 3, 'Thus saith the Lord GOD; I will therefore spread out my net over thee with a company of many people; and they shall bring thee up in my net.', 'thus saith the lord god i will therefore spread out my net over thee with a company of many people and they shall bring thee up in my net');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 4, 'Then will I leave thee upon the land, I will cast thee forth upon the open field, and will cause all the fowls of the heaven to remain upon thee, and I will fill the beasts of the whole earth with thee.', 'then will i leave thee upon the land i will cast thee forth upon the open field and will cause all the fowls of the heaven to remain upon thee and i will fill the beasts of the whole earth with thee');
