INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 7, 'And when I shall put thee out, I will cover the heaven, and make the stars thereof dark; I will cover the sun with a cloud, and the moon shall not give her light. {put...: or, extinguish thee}', 'and when i shall put thee out i will cover the heaven and make the stars thereof dark i will cover the sun with a cloud and the moon shall not give her light put or extinguish thee');
