INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 9, 'I will also vex the hearts of many people, when I shall bring thy destruction among the nations, into the countries which thou hast not known. {vex: Heb. provoke to anger, or, grief}', 'i will also vex the hearts of many people when i shall bring thy destruction among the nations into the countries which thou hast not known vex heb provoke to anger or grief');
