INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 12, 'By the swords of the mighty will I cause thy multitude to fall, the terrible of the nations, all of them: and they shall spoil the pomp of Egypt, and all the multitude thereof shall be destroyed.', 'by the swords of the mighty will i cause thy multitude to fall the terrible of the nations all of them and they shall spoil the pomp of egypt and all the multitude thereof shall be destroyed');
