INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 14, 'Then will I make their waters deep, and cause their rivers to run like oil, saith the Lord GOD.', 'then will i make their waters deep and cause their rivers to run like oil saith the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 15, 'When I shall make the land of Egypt desolate, and the country shall be destitute of that whereof it was full, when I shall smite all them that dwell therein, then shall they know that I {am} the LORD. {destitute...: Heb. desolate from the fulness thereof}', 'when i shall make the land of egypt desolate and the country shall be destitute of that whereof it was full when i shall smite all them that dwell therein then shall they know that i am the lord destitute heb desolate from the fulness thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 16, 'This {is} the lamentation wherewith they shall lament her: the daughters of the nations shall lament her: they shall lament for her, {even} for Egypt, and for all her multitude, saith the Lord GOD.', 'this is the lamentation wherewith they shall lament her the daughters of the nations shall lament her they shall lament for her even for egypt and for all her multitude saith the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 32, 17, 'It came to pass also in the twelfth year, in the fifteenth {day} of the month, {that} the word of the LORD came unto me, saying,', 'it came to pass also in the twelfth year in the fifteenth day of the month that the word of the lord came unto me saying');
