INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 24, 'For I will take you from among the heathen, and gather you out of all countries, and will bring you into your own land.', 'for i will take you from among the heathen and gather you out of all countries and will bring you into your own land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 25, 'Then will I sprinkle clean water upon you, and ye shall be clean: from all your filthiness, and from all your idols, will I cleanse you.', 'then will i sprinkle clean water upon you and ye shall be clean from all your filthiness and from all your idols will i cleanse you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 26, 'A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.', 'a new heart also will i give you and a new spirit will i put within you and i will take away the stony heart out of your flesh and i will give you an heart of flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 27, 'And I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do {them}.', 'and i will put my spirit within you and cause you to walk in my statutes and ye shall keep my judgments and do them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 28, 'And ye shall dwell in the land that I gave to your fathers; and ye shall be my people, and I will be your God.', 'and ye shall dwell in the land that i gave to your fathers and ye shall be my people and i will be your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 29, 'I will also save you from all your uncleannesses: and I will call for the corn, and will increase it, and lay no famine upon you.', 'i will also save you from all your uncleannesses and i will call for the corn and will increase it and lay no famine upon you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 30, 'And I will multiply the fruit of the tree, and the increase of the field, that ye shall receive no more reproach of famine among the heathen.', 'and i will multiply the fruit of the tree and the increase of the field that ye shall receive no more reproach of famine among the heathen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 31, 'Then shall ye remember your own evil ways, and your doings that {were} not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.', 'then shall ye remember your own evil ways and your doings that were not good and shall lothe yourselves in your own sight for your iniquities and for your abominations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 32, 'Not for your sakes do I {this}, saith the Lord GOD, be it known unto you: be ashamed and confounded for your own ways, O house of Israel.', 'not for your sakes do i this saith the lord god be it known unto you be ashamed and confounded for your own ways o house of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 33, 'Thus saith the Lord GOD; In the day that I shall have cleansed you from all your iniquities I will also cause {you} to dwell in the cities, and the wastes shall be builded.', 'thus saith the lord god in the day that i shall have cleansed you from all your iniquities i will also cause you to dwell in the cities and the wastes shall be builded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 34, 'And the desolate land shall be tilled, whereas it lay desolate in the sight of all that passed by.', 'and the desolate land shall be tilled whereas it lay desolate in the sight of all that passed by');
