INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 36, 'Then the heathen that are left round about you shall know that I the LORD build the ruined {places, and} plant that that was desolate: I the LORD have spoken {it}, and I will do {it}.', 'then the heathen that are left round about you shall know that i the lord build the ruined places and plant that that was desolate i the lord have spoken it and i will do it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 37, 'Thus saith the Lord GOD; I will yet {for} this be enquired of by the house of Israel, to do {it} for them; I will increase them with men like a flock.', 'thus saith the lord god i will yet for this be enquired of by the house of israel to do it for them i will increase them with men like a flock');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 36, 38, 'As the holy flock, as the flock of Jerusalem in her solemn feasts; so shall the waste cities be filled with flocks of men: and they shall know that I {am} the LORD. {holy...: Heb. flock of holy things}', 'as the holy flock as the flock of jerusalem in her solemn feasts so shall the waste cities be filled with flocks of men and they shall know that i am the lord holy heb flock of holy things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 1, 'The hand of the LORD was upon me, and carried me out in the spirit of the LORD, and set me down in the midst of the valley which {was} full of bones,', 'the hand of the lord was upon me and carried me out in the spirit of the lord and set me down in the midst of the valley which was full of bones');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 2, 'And caused me to pass by them round about: and, behold, {there were} very many in the open valley; and, lo, {they were} very dry. {valley: or, champaign}', 'and caused me to pass by them round about and behold there were very many in the open valley and lo they were very dry valley or champaign');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 3, 'And he said unto me, Son of man, can these bones live? And I answered, O Lord GOD, thou knowest.', 'and he said unto me son of man can these bones live and i answered o lord god thou knowest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 4, 'Again he said unto me, Prophesy upon these bones, and say unto them, O ye dry bones, hear the word of the LORD.', 'again he said unto me prophesy upon these bones and say unto them o ye dry bones hear the word of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 5, 'Thus saith the Lord GOD unto these bones; Behold, I will cause breath to enter into you, and ye shall live:', 'thus saith the lord god unto these bones behold i will cause breath to enter into you and ye shall live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 6, 'And I will lay sinews upon you, and will bring up flesh upon you, and cover you with skin, and put breath in you, and ye shall live; and ye shall know that I {am} the LORD.', 'and i will lay sinews upon you and will bring up flesh upon you and cover you with skin and put breath in you and ye shall live and ye shall know that i am the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 7, 'So I prophesied as I was commanded: and as I prophesied, there was a noise, and behold a shaking, and the bones came together, bone to his bone.', 'so i prophesied as i was commanded and as i prophesied there was a noise and behold a shaking and the bones came together bone to his bone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 8, 'And when I beheld, lo, the sinews and the flesh came up upon them, and the skin covered them above: but {there was} no breath in them.', 'and when i beheld lo the sinews and the flesh came up upon them and the skin covered them above but there was no breath in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 9, 'Then said he unto me, Prophesy unto the wind, prophesy, son of man, and say to the wind, Thus saith the Lord GOD; Come from the four winds, O breath, and breathe upon these slain, that they may live. {wind: or, breath}', 'then said he unto me prophesy unto the wind prophesy son of man and say to the wind thus saith the lord god come from the four winds o breath and breathe upon these slain that they may live wind or breath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 10, 'So I prophesied as he commanded me, and the breath came into them, and they lived, and stood up upon their feet, an exceeding great army.', 'so i prophesied as he commanded me and the breath came into them and they lived and stood up upon their feet an exceeding great army');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 11, 'Then he said unto me, Son of man, these bones are the whole house of Israel: behold, they say, Our bones are dried, and our hope is lost: we are cut off for our parts.', 'then he said unto me son of man these bones are the whole house of israel behold they say our bones are dried and our hope is lost we are cut off for our parts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 12, 'Therefore prophesy and say unto them, Thus saith the Lord GOD; Behold, O my people, I will open your graves, and cause you to come up out of your graves, and bring you into the land of Israel.', 'therefore prophesy and say unto them thus saith the lord god behold o my people i will open your graves and cause you to come up out of your graves and bring you into the land of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 13, 'And ye shall know that I {am} the LORD, when I have opened your graves, O my people, and brought you up out of your graves,', 'and ye shall know that i am the lord when i have opened your graves o my people and brought you up out of your graves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 14, 'And shall put my spirit in you, and ye shall live, and I shall place you in your own land: then shall ye know that I the LORD have spoken {it}, and performed {it}, saith the LORD.', 'and shall put my spirit in you and ye shall live and i shall place you in your own land then shall ye know that i the lord have spoken it and performed it saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 15, 'The word of the LORD came again unto me, saying,', 'the word of the lord came again unto me saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 16, 'Moreover, thou son of man, take thee one stick, and write upon it, For Judah, and for the children of Israel his companions: then take another stick, and write upon it, For Joseph, the stick of Ephraim, and {for} all the house of Israel his companions:', 'moreover thou son of man take thee one stick and write upon it for judah and for the children of israel his companions then take another stick and write upon it for joseph the stick of ephraim and for all the house of israel his companions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 17, 'And join them one to another into one stick; and they shall become one in thine hand.', 'and join them one to another into one stick and they shall become one in thine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 18, 'And when the children of thy people shall speak unto thee, saying, Wilt thou not shew us what thou {meanest} by these?', 'and when the children of thy people shall speak unto thee saying wilt thou not shew us what thou meanest by these');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 19, 'Say unto them, Thus saith the Lord GOD; Behold, I will take the stick of Joseph, which {is} in the hand of Ephraim, and the tribes of Israel his fellows, and will put them with him, {even} with the stick of Judah, and make them one stick, and they shall be one in mine hand.', 'say unto them thus saith the lord god behold i will take the stick of joseph which is in the hand of ephraim and the tribes of israel his fellows and will put them with him even with the stick of judah and make them one stick and they shall be one in mine hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 20, 'And the sticks whereon thou writest shall be in thine hand before their eyes.', 'and the sticks whereon thou writest shall be in thine hand before their eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 21, 'And say unto them, Thus saith the Lord GOD; Behold, I will take the children of Israel from among the heathen, whither they be gone, and will gather them on every side, and bring them into their own land:', 'and say unto them thus saith the lord god behold i will take the children of israel from among the heathen whither they be gone and will gather them on every side and bring them into their own land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 22, 'And I will make them one nation in the land upon the mountains of Israel; and one king shall be king to them all: and they shall be no more two nations, neither shall they be divided into two kingdoms any more at all:', 'and i will make them one nation in the land upon the mountains of israel and one king shall be king to them all and they shall be no more two nations neither shall they be divided into two kingdoms any more at all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 23, 'Neither shall they defile themselves any more with their idols, nor with their detestable things, nor with any of their transgressions: but I will save them out of all their dwellingplaces, wherein they have sinned, and will cleanse them: so shall they be my people, and I will be their God.', 'neither shall they defile themselves any more with their idols nor with their detestable things nor with any of their transgressions but i will save them out of all their dwellingplaces wherein they have sinned and will cleanse them so shall they be my people and i will be their god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 24, 'And David my servant {shall be} king over them; and they all shall have one shepherd: they shall also walk in my judgments, and observe my statutes, and do them.', 'and david my servant shall be king over them and they all shall have one shepherd they shall also walk in my judgments and observe my statutes and do them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 25, 'And they shall dwell in the land that I have given unto Jacob my servant, wherein your fathers have dwelt; and they shall dwell therein, {even} they, and their children, and their children''s children for ever: and my servant David {shall be} their prince for ever.', 'and they shall dwell in the land that i have given unto jacob my servant wherein your fathers have dwelt and they shall dwell therein even they and their children and their children s children for ever and my servant david shall be their prince for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 26, 'Moreover I will make a covenant of peace with them; it shall be an everlasting covenant with them: and I will place them, and multiply them, and will set my sanctuary in the midst of them for evermore.', 'moreover i will make a covenant of peace with them it shall be an everlasting covenant with them and i will place them and multiply them and will set my sanctuary in the midst of them for evermore');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 27, 'My tabernacle also shall be with them: yea, I will be their God, and they shall be my people.', 'my tabernacle also shall be with them yea i will be their god and they shall be my people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 37, 28, 'And the heathen shall know that I the LORD do sanctify Israel, when my sanctuary shall be in the midst of them for evermore.', 'and the heathen shall know that i the lord do sanctify israel when my sanctuary shall be in the midst of them for evermore');
