INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 4, 'And I will turn thee back, and put hooks into thy jaws, and I will bring thee forth, and all thine army, horses and horsemen, all of them clothed with all sorts {of armour, even} a great company {with} bucklers and shields, all of them handling swords:', 'and i will turn thee back and put hooks into thy jaws and i will bring thee forth and all thine army horses and horsemen all of them clothed with all sorts of armour even a great company with bucklers and shields all of them handling swords');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 5, 'Persia, Ethiopia, and Libya with them; all of them with shield and helmet: {Libya: or, Phut}', 'persia ethiopia and libya with them all of them with shield and helmet libya or phut');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 6, 'Gomer, and all his bands; the house of Togarmah of the north quarters, and all his bands: {and} many people with thee.', 'gomer and all his bands the house of togarmah of the north quarters and all his bands and many people with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 7, 'Be thou prepared, and prepare for thyself, thou, and all thy company that are assembled unto thee, and be thou a guard unto them.', 'be thou prepared and prepare for thyself thou and all thy company that are assembled unto thee and be thou a guard unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 8, 'After many days thou shalt be visited: in the latter years thou shalt come into the land {that is} brought back from the sword, {and is} gathered out of many people, against the mountains of Israel, which have been always waste: but it is brought forth out of the nations, and they shall dwell safely all of them.', 'after many days thou shalt be visited in the latter years thou shalt come into the land that is brought back from the sword and is gathered out of many people against the mountains of israel which have been always waste but it is brought forth out of the nations and they shall dwell safely all of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 9, 'Thou shalt ascend and come like a storm, thou shalt be like a cloud to cover the land, thou, and all thy bands, and many people with thee.', 'thou shalt ascend and come like a storm thou shalt be like a cloud to cover the land thou and all thy bands and many people with thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 10, 'Thus saith the Lord GOD; It shall also come to pass, {that} at the same time shall things come into thy mind, and thou shalt think an evil thought: {think...: or, conceive a mischievous purpose}', 'thus saith the lord god it shall also come to pass that at the same time shall things come into thy mind and thou shalt think an evil thought think or conceive a mischievous purpose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 11, 'And thou shalt say, I will go up to the land of unwalled villages; I will go to them that are at rest, that dwell safely, all of them dwelling without walls, and having neither bars nor gates, {safely: or, confidently}', 'and thou shalt say i will go up to the land of unwalled villages i will go to them that are at rest that dwell safely all of them dwelling without walls and having neither bars nor gates safely or confidently');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 12, 'To take a spoil, and to take a prey; to turn thine hand upon the desolate places {that are now} inhabited, and upon the people {that are} gathered out of the nations, which have gotten cattle and goods, that dwell in the midst of the land. {To take...: Heb. To spoil the spoil, and to prey the prey} {midst: Heb. navel}', 'to take a spoil and to take a prey to turn thine hand upon the desolate places that are now inhabited and upon the people that are gathered out of the nations which have gotten cattle and goods that dwell in the midst of the land to take heb to spoil the spoil and to prey the prey midst heb navel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 13, 'Sheba, and Dedan, and the merchants of Tarshish, with all the young lions thereof, shall say unto thee, Art thou come to take a spoil? hast thou gathered thy company to take a prey? to carry away silver and gold, to take away cattle and goods, to take a great spoil?', 'sheba and dedan and the merchants of tarshish with all the young lions thereof shall say unto thee art thou come to take a spoil hast thou gathered thy company to take a prey to carry away silver and gold to take away cattle and goods to take a great spoil');
