INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 38, 15, 'And thou shalt come from thy place out of the north parts, thou, and many people with thee, all of them riding upon horses, a great company, and a mighty army:', 'and thou shalt come from thy place out of the north parts thou and many people with thee all of them riding upon horses a great company and a mighty army');
