INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 39, 10, 'So that they shall take no wood out of the field, neither cut down {any} out of the forests; for they shall burn the weapons with fire: and they shall spoil those that spoiled them, and rob those that robbed them, saith the Lord GOD.', 'so that they shall take no wood out of the field neither cut down any out of the forests for they shall burn the weapons with fire and they shall spoil those that spoiled them and rob those that robbed them saith the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 39, 11, 'And it shall come to pass in that day, {that} I will give unto Gog a place there of graves in Israel, the valley of the passengers on the east of the sea: and it shall stop the {noses} of the passengers: and there shall they bury Gog and all his multitude: and they shall call {it} The valley of Hamongog. {noses: or, mouths} {Hamongog: that is, The multitude of Gog}', 'and it shall come to pass in that day that i will give unto gog a place there of graves in israel the valley of the passengers on the east of the sea and it shall stop the noses of the passengers and there shall they bury gog and all his multitude and they shall call it the valley of hamongog noses or mouths hamongog that is the multitude of gog');
