INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 39, 15, 'And the passengers {that} pass through the land, when {any} seeth a man''s bone, then shall he set up a sign by it, till the buriers have buried it in the valley of Hamongog. {set up: Heb. build}', 'and the passengers that pass through the land when any seeth a man s bone then shall he set up a sign by it till the buriers have buried it in the valley of hamongog set up heb build');
