INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 39, 21, 'And I will set my glory among the heathen, and all the heathen shall see my judgment that I have executed, and my hand that I have laid upon them.', 'and i will set my glory among the heathen and all the heathen shall see my judgment that i have executed and my hand that i have laid upon them');
