INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 39, 23, 'And the heathen shall know that the house of Israel went into captivity for their iniquity: because they trespassed against me, therefore hid I my face from them, and gave them into the hand of their enemies: so fell they all by the sword.', 'and the heathen shall know that the house of israel went into captivity for their iniquity because they trespassed against me therefore hid i my face from them and gave them into the hand of their enemies so fell they all by the sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 39, 24, 'According to their uncleanness and according to their transgressions have I done unto them, and hid my face from them.', 'according to their uncleanness and according to their transgressions have i done unto them and hid my face from them');
