INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 40, 1, 'In the five and twentieth year of our captivity, in the beginning of the year, in the tenth {day} of the month, in the fourteenth year after that the city was smitten, in the selfsame day the hand of the LORD was upon me, and brought me thither.', 'in the five and twentieth year of our captivity in the beginning of the year in the tenth day of the month in the fourteenth year after that the city was smitten in the selfsame day the hand of the lord was upon me and brought me thither');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 40, 2, 'In the visions of God brought he me into the land of Israel, and set me upon a very high mountain, by which {was} as the frame of a city on the south. {by which: or, upon which}', 'in the visions of god brought he me into the land of israel and set me upon a very high mountain by which was as the frame of a city on the south by which or upon which');
