INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 40, 5, 'And behold a wall on the outside of the house round about, and in the man''s hand a measuring reed of six cubits {long} by the cubit and an hand breadth: so he measured the breadth of the building, one reed; and the height, one reed.', 'and behold a wall on the outside of the house round about and in the man s hand a measuring reed of six cubits long by the cubit and an hand breadth so he measured the breadth of the building one reed and the height one reed');
