INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 40, 7, 'And {every} little chamber {was} one reed long, and one reed broad; and between the little chambers {were} five cubits; and the threshold of the gate by the porch of the gate within {was} one reed.', 'and every little chamber was one reed long and one reed broad and between the little chambers were five cubits and the threshold of the gate by the porch of the gate within was one reed');
