INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 40, 10, 'And the little chambers of the gate eastward {were} three on this side, and three on that side; they three {were} of one measure: and the posts had one measure on this side and on that side.', 'and the little chambers of the gate eastward were three on this side and three on that side they three were of one measure and the posts had one measure on this side and on that side');
