INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 2, 'Of this there shall be for the sanctuary five hundred {in length}, with five hundred {in breadth}, square round about; and fifty cubits round about for the suburbs thereof. {suburbs: or, void places}', 'of this there shall be for the sanctuary five hundred in length with five hundred in breadth square round about and fifty cubits round about for the suburbs thereof suburbs or void places');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 3, 'And of this measure shalt thou measure the length of five and twenty thousand, and the breadth of ten thousand: and in it shall be the sanctuary {and} the most holy {place}.', 'and of this measure shalt thou measure the length of five and twenty thousand and the breadth of ten thousand and in it shall be the sanctuary and the most holy place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 4, 'The holy {portion} of the land shall be for the priests the ministers of the sanctuary, which shall come near to minister unto the LORD: and it shall be a place for their houses, and an holy place for the sanctuary.', 'the holy portion of the land shall be for the priests the ministers of the sanctuary which shall come near to minister unto the lord and it shall be a place for their houses and an holy place for the sanctuary');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 5, 'And the five and twenty thousand of length, and the ten thousand of breadth, shall also the Levites, the ministers of the house, have for themselves, for a possession for twenty chambers.', 'and the five and twenty thousand of length and the ten thousand of breadth shall also the levites the ministers of the house have for themselves for a possession for twenty chambers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 6, 'And ye shall appoint the possession of the city five thousand broad, and five and twenty thousand long, over against the oblation of the holy {portion}: it shall be for the whole house of Israel.', 'and ye shall appoint the possession of the city five thousand broad and five and twenty thousand long over against the oblation of the holy portion it shall be for the whole house of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 7, 'And a {portion shall be} for the prince on the one side and on the other side of the oblation of the holy {portion}, and of the possession of the city, before the oblation of the holy {portion}, and before the possession of the city, from the west side westward, and from the east side eastward: and the length {shall be} over against one of the portions, from the west border unto the east border.', 'and a portion shall be for the prince on the one side and on the other side of the oblation of the holy portion and of the possession of the city before the oblation of the holy portion and before the possession of the city from the west side westward and from the east side eastward and the length shall be over against one of the portions from the west border unto the east border');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 8, 'In the land shall be his possession in Israel: and my princes shall no more oppress my people; and {the rest of} the land shall they give to the house of Israel according to their tribes.', 'in the land shall be his possession in israel and my princes shall no more oppress my people and the rest of the land shall they give to the house of israel according to their tribes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 9, 'Thus saith the Lord GOD; Let it suffice you, O princes of Israel: remove violence and spoil, and execute judgment and justice, take away your exactions from my people, saith the Lord GOD. {exactions: Heb. expulsions}', 'thus saith the lord god let it suffice you o princes of israel remove violence and spoil and execute judgment and justice take away your exactions from my people saith the lord god exactions heb expulsions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 10, 'Ye shall have just balances, and a just ephah, and a just bath.', 'ye shall have just balances and a just ephah and a just bath');
