INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 12, 'And the shekel {shall be} twenty gerahs: twenty shekels, five and twenty shekels, fifteen shekels, shall be your maneh.', 'and the shekel shall be twenty gerahs twenty shekels five and twenty shekels fifteen shekels shall be your maneh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 13, 'This {is} the oblation that ye shall offer; the sixth part of an ephah of an homer of wheat, and ye shall give the sixth part of an ephah of an homer of barley:', 'this is the oblation that ye shall offer the sixth part of an ephah of an homer of wheat and ye shall give the sixth part of an ephah of an homer of barley');
