INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 15, 'And one lamb out of the flock, out of two hundred, out of the fat pastures of Israel; for a meat offering, and for a burnt offering, and for peace offerings, to make reconciliation for them, saith the Lord GOD. {lamb: or, kid} {peace...: or, thank offerings}', 'and one lamb out of the flock out of two hundred out of the fat pastures of israel for a meat offering and for a burnt offering and for peace offerings to make reconciliation for them saith the lord god lamb or kid peace or thank offerings');
