INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 18, 'Thus saith the Lord GOD; In the first {month}, in the first {day} of the month, thou shalt take a young bullock without blemish, and cleanse the sanctuary:', 'thus saith the lord god in the first month in the first day of the month thou shalt take a young bullock without blemish and cleanse the sanctuary');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 19, 'And the priest shall take of the blood of the sin offering, and put {it} upon the posts of the house, and upon the four corners of the settle of the altar, and upon the posts of the gate of the inner court.', 'and the priest shall take of the blood of the sin offering and put it upon the posts of the house and upon the four corners of the settle of the altar and upon the posts of the gate of the inner court');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 20, 'And so thou shalt do the seventh {day} of the month for every one that erreth, and for {him that is} simple: so shall ye reconcile the house.', 'and so thou shalt do the seventh day of the month for every one that erreth and for him that is simple so shall ye reconcile the house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 21, 'In the first {month}, in the fourteenth day of the month, ye shall have the passover, a feast of seven days; unleavened bread shall be eaten.', 'in the first month in the fourteenth day of the month ye shall have the passover a feast of seven days unleavened bread shall be eaten');
