INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 24, 'And he shall prepare a meat offering of an ephah for a bullock, and an ephah for a ram, and an hin of oil for an ephah.', 'and he shall prepare a meat offering of an ephah for a bullock and an ephah for a ram and an hin of oil for an ephah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 45, 25, 'In the seventh {month}, in the fifteenth day of the month, shall he do the like in the feast of the seven days, according to the sin offering, according to the burnt offering, and according to the meat offering, and according to the oil.', 'in the seventh month in the fifteenth day of the month shall he do the like in the feast of the seven days according to the sin offering according to the burnt offering and according to the meat offering and according to the oil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 1, 'Thus saith the Lord GOD; The gate of the inner court that looketh toward the east shall be shut the six working days; but on the sabbath it shall be opened, and in the day of the new moon it shall be opened.', 'thus saith the lord god the gate of the inner court that looketh toward the east shall be shut the six working days but on the sabbath it shall be opened and in the day of the new moon it shall be opened');
