INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 3, 'Likewise the people of the land shall worship at the door of this gate before the LORD in the sabbaths and in the new moons.', 'likewise the people of the land shall worship at the door of this gate before the lord in the sabbaths and in the new moons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 4, 'And the burnt offering that the prince shall offer unto the LORD in the sabbath day {shall be} six lambs without blemish, and a ram without blemish.', 'and the burnt offering that the prince shall offer unto the lord in the sabbath day shall be six lambs without blemish and a ram without blemish');
