INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 6, 'And in the day of the new moon {it shall be} a young bullock without blemish, and six lambs, and a ram: they shall be without blemish.', 'and in the day of the new moon it shall be a young bullock without blemish and six lambs and a ram they shall be without blemish');
