INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 9, 'But when the people of the land shall come before the LORD in the solemn feasts, he that entereth in by the way of the north gate to worship shall go out by the way of the south gate; and he that entereth by the way of the south gate shall go forth by the way of the north gate: he shall not return by the way of the gate whereby he came in, but shall go forth over against it.', 'but when the people of the land shall come before the lord in the solemn feasts he that entereth in by the way of the north gate to worship shall go out by the way of the south gate and he that entereth by the way of the south gate shall go forth by the way of the north gate he shall not return by the way of the gate whereby he came in but shall go forth over against it');
