INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 12, 'Now when the prince shall prepare a voluntary burnt offering or peace offerings voluntarily unto the LORD, {one} shall then open him the gate that looketh toward the east, and he shall prepare his burnt offering and his peace offerings, as he did on the sabbath day: then he shall go forth; and after his going forth {one} shall shut the gate.', 'now when the prince shall prepare a voluntary burnt offering or peace offerings voluntarily unto the lord one shall then open him the gate that looketh toward the east and he shall prepare his burnt offering and his peace offerings as he did on the sabbath day then he shall go forth and after his going forth one shall shut the gate');
