INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 14, 'And thou shalt prepare a meat offering for it every morning, the sixth part of an ephah, and the third part of an hin of oil, to temper with the fine flour; a meat offering continually by a perpetual ordinance unto the LORD.', 'and thou shalt prepare a meat offering for it every morning the sixth part of an ephah and the third part of an hin of oil to temper with the fine flour a meat offering continually by a perpetual ordinance unto the lord');
