INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 16, 'Thus saith the Lord GOD; If the prince give a gift unto any of his sons, the inheritance thereof shall be his sons''; it {shall be} their possession by inheritance.', 'thus saith the lord god if the prince give a gift unto any of his sons the inheritance thereof shall be his sons it shall be their possession by inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 17, 'But if he give a gift of his inheritance to one of his servants, then it shall be his to the year of liberty; after it shall return to the prince: but his inheritance shall be his sons'' for them.', 'but if he give a gift of his inheritance to one of his servants then it shall be his to the year of liberty after it shall return to the prince but his inheritance shall be his sons for them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 18, 'Moreover the prince shall not take of the people''s inheritance by oppression, to thrust them out of their possession; {but} he shall give his sons inheritance out of his own possession: that my people be not scattered every man from his possession.', 'moreover the prince shall not take of the people s inheritance by oppression to thrust them out of their possession but he shall give his sons inheritance out of his own possession that my people be not scattered every man from his possession');
