INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 22, 'In the four corners of the court {there were} courts joined of forty {cubits} long and thirty broad: these four corners {were} of one measure. {joined: or, made with chimneys} {corners were...: Heb. cornered, etc}', 'in the four corners of the court there were courts joined of forty cubits long and thirty broad these four corners were of one measure joined or made with chimneys corners were heb cornered etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 46, 23, 'And {there was} a row {of building} round about in them, round about them four, and {it was} made with boiling places under the rows round about.', 'and there was a row of building round about in them round about them four and it was made with boiling places under the rows round about');
