INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 1, 'Afterward he brought me again unto the door of the house; and, behold, waters issued out from under the threshold of the house eastward: for the forefront of the house {stood toward} the east, and the waters came down from under from the right side of the house, at the south {side} of the altar.', 'afterward he brought me again unto the door of the house and behold waters issued out from under the threshold of the house eastward for the forefront of the house stood toward the east and the waters came down from under from the right side of the house at the south side of the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 2, 'Then brought he me out of the way of the gate northward, and led me about the way without unto the utter gate by the way that looketh eastward; and, behold, there ran out waters on the right side.', 'then brought he me out of the way of the gate northward and led me about the way without unto the utter gate by the way that looketh eastward and behold there ran out waters on the right side');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 3, 'And when the man that had the line in his hand went forth eastward, he measured a thousand cubits, and he brought me through the waters; the waters {were} to the ankles. {the waters were...: Heb. waters of the ankles}', 'and when the man that had the line in his hand went forth eastward he measured a thousand cubits and he brought me through the waters the waters were to the ankles the waters were heb waters of the ankles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 4, 'Again he measured a thousand, and brought me through the waters; the waters {were} to the knees. Again he measured a thousand, and brought me through; the waters {were} to the loins.', 'again he measured a thousand and brought me through the waters the waters were to the knees again he measured a thousand and brought me through the waters were to the loins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 5, 'Afterward he measured a thousand; {and it was} a river that I could not pass over: for the waters were risen, waters to swim in, a river that could not be passed over. {waters to...: Heb. waters of swimming}', 'afterward he measured a thousand and it was a river that i could not pass over for the waters were risen waters to swim in a river that could not be passed over waters to heb waters of swimming');
