INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 9, 'And it shall come to pass, {that} every thing that liveth, which moveth, whithersoever the rivers shall come, shall live: and there shall be a very great multitude of fish, because these waters shall come thither: for they shall be healed; and every thing shall live whither the river cometh. {rivers: Heb. two rivers}', 'and it shall come to pass that every thing that liveth which moveth whithersoever the rivers shall come shall live and there shall be a very great multitude of fish because these waters shall come thither for they shall be healed and every thing shall live whither the river cometh rivers heb two rivers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 10, 'And it shall come to pass, {that} the fishers shall stand upon it from Engedi even unto Eneglaim; they shall be a {place} to spread forth nets; their fish shall be according to their kinds, as the fish of the great sea, exceeding many.', 'and it shall come to pass that the fishers shall stand upon it from engedi even unto eneglaim they shall be a place to spread forth nets their fish shall be according to their kinds as the fish of the great sea exceeding many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 11, 'But the miry places thereof and the marishes thereof shall not be healed; they shall be given to salt. {shall not...: or, and that which shall not be healed}', 'but the miry places thereof and the marishes thereof shall not be healed they shall be given to salt shall not or and that which shall not be healed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 12, 'And by the river upon the bank thereof, on this side and on that side, shall grow all trees for meat, whose leaf shall not fade, neither shall the fruit thereof be consumed: it shall bring forth new fruit according to his months, because their waters they issued out of the sanctuary: and the fruit thereof shall be for meat, and the leaf thereof for medicine. {shall grow: Heb. shall come up} {new: or, principal} {for medicine: or, for bruises and sores}', 'and by the river upon the bank thereof on this side and on that side shall grow all trees for meat whose leaf shall not fade neither shall the fruit thereof be consumed it shall bring forth new fruit according to his months because their waters they issued out of the sanctuary and the fruit thereof shall be for meat and the leaf thereof for medicine shall grow heb shall come up new or principal for medicine or for bruises and sores');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 13, 'Thus saith the Lord GOD; This {shall be} the border, whereby ye shall inherit the land according to the twelve tribes of Israel: Joseph {shall have two} portions.', 'thus saith the lord god this shall be the border whereby ye shall inherit the land according to the twelve tribes of israel joseph shall have two portions');
