INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 15, 'And this {shall be} the border of the land toward the north side, from the great sea, the way of Hethlon, as men go to Zedad;', 'and this shall be the border of the land toward the north side from the great sea the way of hethlon as men go to zedad');
