INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 18, 'And the east side ye shall measure from Hauran, and from Damascus, and from Gilead, and from the land of Israel {by} Jordan, from the border unto the east sea. And {this is} the east side. {from (Hauran, Damascus, Gilead, the land): Heb. from between}', 'and the east side ye shall measure from hauran and from damascus and from gilead and from the land of israel by jordan from the border unto the east sea and this is the east side from hauran damascus gilead the land heb from between');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 19, 'And the south side southward, from Tamar {even} to the waters of strife {in} Kadesh, the river to the great sea. And {this is} the south side southward. {strife: or, Meribah} {river: or, valley} {is the south side southward: or, is the south side toward Teman}', 'and the south side southward from tamar even to the waters of strife in kadesh the river to the great sea and this is the south side southward strife or meribah river or valley is the south side southward or is the south side toward teman');
