INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 47, 21, 'So shall ye divide this land unto you according to the tribes of Israel.', 'so shall ye divide this land unto you according to the tribes of israel');
