INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 48, 1, 'Now these {are} the names of the tribes. From the north end to the coast of the way of Hethlon, as one goeth to Hamath, Hazarenan, the border of Damascus northward, to the coast of Hamath; for these are his sides east {and} west; a {portion for} Dan. {a portion: Heb. one portion}', 'now these are the names of the tribes from the north end to the coast of the way of hethlon as one goeth to hamath hazarenan the border of damascus northward to the coast of hamath for these are his sides east and west a portion for dan a portion heb one portion');
