INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 48, 29, 'This {is} the land which ye shall divide by lot unto the tribes of Israel for inheritance, and these {are} their portions, saith the Lord GOD.', 'this is the land which ye shall divide by lot unto the tribes of israel for inheritance and these are their portions saith the lord god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 48, 30, 'And these {are} the goings out of the city on the north side, four thousand and five hundred measures.', 'and these are the goings out of the city on the north side four thousand and five hundred measures');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 26, 'Unknown', 48, 31, 'And the gates of the city {shall be} after the names of the tribes of Israel: three gates northward; one gate of Reuben, one gate of Judah, one gate of Levi.', 'and the gates of the city shall be after the names of the tribes of israel three gates northward one gate of reuben one gate of judah one gate of levi');
