INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 15, 'He answered and said to Arioch the king''s captain, Why {is} the decree {so} hasty from the king? Then Arioch made the thing known to Daniel.', 'he answered and said to arioch the king s captain why is the decree so hasty from the king then arioch made the thing known to daniel');
