INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 18, 'That they would desire mercies of the God of heaven concerning this secret; that Daniel and his fellows should not perish with the rest of the wise {men} of Babylon. {of the God: Chaldee, from before God} {that Daniel...: or, that they should not destroy Daniel, etc}', 'that they would desire mercies of the god of heaven concerning this secret that daniel and his fellows should not perish with the rest of the wise men of babylon of the god chaldee from before god that daniel or that they should not destroy daniel etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 19, 'Then was the secret revealed unto Daniel in a night vision. Then Daniel blessed the God of heaven.', 'then was the secret revealed unto daniel in a night vision then daniel blessed the god of heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 20, 'Daniel answered and said, Blessed be the name of God for ever and ever: for wisdom and might are his:', 'daniel answered and said blessed be the name of god for ever and ever for wisdom and might are his');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 21, 'And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding:', 'and he changeth the times and the seasons he removeth kings and setteth up kings he giveth wisdom unto the wise and knowledge to them that know understanding');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 22, 'He revealeth the deep and secret things: he knoweth what {is} in the darkness, and the light dwelleth with him.', 'he revealeth the deep and secret things he knoweth what is in the darkness and the light dwelleth with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 23, 'I thank thee, and praise thee, O thou God of my fathers, who hast given me wisdom and might, and hast made known unto me now what we desired of thee: for thou hast {now} made known unto us the king''s matter.', 'i thank thee and praise thee o thou god of my fathers who hast given me wisdom and might and hast made known unto me now what we desired of thee for thou hast now made known unto us the king s matter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 24, 'Therefore Daniel went in unto Arioch, whom the king had ordained to destroy the wise {men} of Babylon: he went and said thus unto him; Destroy not the wise {men} of Babylon: bring me in before the king, and I will shew unto the king the interpretation.', 'therefore daniel went in unto arioch whom the king had ordained to destroy the wise men of babylon he went and said thus unto him destroy not the wise men of babylon bring me in before the king and i will shew unto the king the interpretation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 25, 'Then Arioch brought in Daniel before the king in haste, and said thus unto him, I have found a man of the captives of Judah, that will make known unto the king the interpretation. {I have...: Chaldee, That I have found} {captives...: Chaldee, children of the captivity of Judah}', 'then arioch brought in daniel before the king in haste and said thus unto him i have found a man of the captives of judah that will make known unto the king the interpretation i have chaldee that i have found captives chaldee children of the captivity of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 26, 'The king answered and said to Daniel, whose name {was} Belteshazzar, Art thou able to make known unto me the dream which I have seen, and the interpretation thereof?', 'the king answered and said to daniel whose name was belteshazzar art thou able to make known unto me the dream which i have seen and the interpretation thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 27, 'Daniel answered in the presence of the king, and said, The secret which the king hath demanded cannot the wise {men}, the astrologers, the magicians, the soothsayers, shew unto the king;', 'daniel answered in the presence of the king and said the secret which the king hath demanded cannot the wise men the astrologers the magicians the soothsayers shew unto the king');
