INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 29, 'As for thee, O king, thy thoughts came {into thy mind} upon thy bed, what should come to pass hereafter: and he that revealeth secrets maketh known to thee what shall come to pass. {came: Chaldee, came up}', 'as for thee o king thy thoughts came into thy mind upon thy bed what should come to pass hereafter and he that revealeth secrets maketh known to thee what shall come to pass came chaldee came up');
