INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 31, 'Thou, O king, sawest, and behold a great image. This great image, whose brightness {was} excellent, stood before thee; and the form thereof {was} terrible. {sawest: Chaldee, wast seeing}', 'thou o king sawest and behold a great image this great image whose brightness was excellent stood before thee and the form thereof was terrible sawest chaldee wast seeing');
