INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 35, 'Then was the iron, the clay, the brass, the silver, and the gold, broken to pieces together, and became like the chaff of the summer threshingfloors; and the wind carried them away, that no place was found for them: and the stone that smote the image became a great mountain, and filled the whole earth.', 'then was the iron the clay the brass the silver and the gold broken to pieces together and became like the chaff of the summer threshingfloors and the wind carried them away that no place was found for them and the stone that smote the image became a great mountain and filled the whole earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 36, 'This {is} the dream; and we will tell the interpretation thereof before the king.', 'this is the dream and we will tell the interpretation thereof before the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 37, 'Thou, O king, {art} a king of kings: for the God of heaven hath given thee a kingdom, power, and strength, and glory.', 'thou o king art a king of kings for the god of heaven hath given thee a kingdom power and strength and glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 38, 'And wheresoever the children of men dwell, the beasts of the field and the fowls of the heaven hath he given into thine hand, and hath made thee ruler over them all. Thou {art} this head of gold.', 'and wheresoever the children of men dwell the beasts of the field and the fowls of the heaven hath he given into thine hand and hath made thee ruler over them all thou art this head of gold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 39, 'And after thee shall arise another kingdom inferior to thee, and another third kingdom of brass, which shall bear rule over all the earth.', 'and after thee shall arise another kingdom inferior to thee and another third kingdom of brass which shall bear rule over all the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 40, 'And the fourth kingdom shall be strong as iron: forasmuch as iron breaketh in pieces and subdueth all {things}: and as iron that breaketh all these, shall it break in pieces and bruise.', 'and the fourth kingdom shall be strong as iron forasmuch as iron breaketh in pieces and subdueth all things and as iron that breaketh all these shall it break in pieces and bruise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 41, 'And whereas thou sawest the feet and toes, part of potters'' clay, and part of iron, the kingdom shall be divided; but there shall be in it of the strength of the iron, forasmuch as thou sawest the iron mixed with miry clay.', 'and whereas thou sawest the feet and toes part of potters clay and part of iron the kingdom shall be divided but there shall be in it of the strength of the iron forasmuch as thou sawest the iron mixed with miry clay');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 42, 'And {as} the toes of the feet {were} part of iron, and part of clay, {so} the kingdom shall be partly strong, and partly broken. {broken: or, brittle}', 'and as the toes of the feet were part of iron and part of clay so the kingdom shall be partly strong and partly broken broken or brittle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 43, 'And whereas thou sawest iron mixed with miry clay, they shall mingle themselves with the seed of men: but they shall not cleave one to another, even as iron is not mixed with clay. {one...: Chaldee, this with this}', 'and whereas thou sawest iron mixed with miry clay they shall mingle themselves with the seed of men but they shall not cleave one to another even as iron is not mixed with clay one chaldee this with this');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 44, 'And in the days of these kings shall the God of heaven set up a kingdom, which shall never be destroyed: and the kingdom shall not be left to other people, {but} it shall break in pieces and consume all these kingdoms, and it shall stand for ever. {the days: Chaldee, their days} {the kingdom: Chaldee, the kingdom thereof}', 'and in the days of these kings shall the god of heaven set up a kingdom which shall never be destroyed and the kingdom shall not be left to other people but it shall break in pieces and consume all these kingdoms and it shall stand for ever the days chaldee their days the kingdom chaldee the kingdom thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 45, 'Forasmuch as thou sawest that the stone was cut out of the mountain without hands, and that it brake in pieces the iron, the brass, the clay, the silver, and the gold; the great God hath made known to the king what shall come to pass hereafter: and the dream {is} certain, and the interpretation thereof sure. {without...: or, which was not in hands} {hereafter: Chaldee, after this}', 'forasmuch as thou sawest that the stone was cut out of the mountain without hands and that it brake in pieces the iron the brass the clay the silver and the gold the great god hath made known to the king what shall come to pass hereafter and the dream is certain and the interpretation thereof sure without or which was not in hands hereafter chaldee after this');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 46, 'Then the king Nebuchadnezzar fell upon his face, and worshipped Daniel, and commanded that they should offer an oblation and sweet odours unto him.', 'then the king nebuchadnezzar fell upon his face and worshipped daniel and commanded that they should offer an oblation and sweet odours unto him');
