INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 48, 'Then the king made Daniel a great man, and gave him many great gifts, and made him ruler over the whole province of Babylon, and chief of the governors over all the wise {men} of Babylon.', 'then the king made daniel a great man and gave him many great gifts and made him ruler over the whole province of babylon and chief of the governors over all the wise men of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 2, 49, 'Then Daniel requested of the king, and he set Shadrach, Meshach, and Abednego, over the affairs of the province of Babylon: but Daniel {sat} in the gate of the king.', 'then daniel requested of the king and he set shadrach meshach and abednego over the affairs of the province of babylon but daniel sat in the gate of the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 1, 'Nebuchadnezzar the king made an image of gold, whose height {was} threescore cubits, {and} the breadth thereof six cubits: he set it up in the plain of Dura, in the province of Babylon.', 'nebuchadnezzar the king made an image of gold whose height was threescore cubits and the breadth thereof six cubits he set it up in the plain of dura in the province of babylon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 2, 'Then Nebuchadnezzar the king sent to gather together the princes, the governors, and the captains, the judges, the treasurers, the counsellors, the sheriffs, and all the rulers of the provinces, to come to the dedication of the image which Nebuchadnezzar the king had set up.', 'then nebuchadnezzar the king sent to gather together the princes the governors and the captains the judges the treasurers the counsellors the sheriffs and all the rulers of the provinces to come to the dedication of the image which nebuchadnezzar the king had set up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 3, 'Then the princes, the governors, and captains, the judges, the treasurers, the counsellors, the sheriffs, and all the rulers of the provinces, were gathered together unto the dedication of the image that Nebuchadnezzar the king had set up; and they stood before the image that Nebuchadnezzar had set up.', 'then the princes the governors and captains the judges the treasurers the counsellors the sheriffs and all the rulers of the provinces were gathered together unto the dedication of the image that nebuchadnezzar the king had set up and they stood before the image that nebuchadnezzar had set up');
