INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 13, 'Then Nebuchadnezzar in {his} rage and fury commanded to bring Shadrach, Meshach, and Abednego. Then they brought these men before the king.', 'then nebuchadnezzar in his rage and fury commanded to bring shadrach meshach and abednego then they brought these men before the king');
