INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 15, 'Now if ye be ready that at what time ye hear the sound of the cornet, flute, harp, sackbut, psaltery, and dulcimer, and all kinds of musick, ye fall down and worship the image which I have made; {well}: but if ye worship not, ye shall be cast the same hour into the midst of a burning fiery furnace; and who {is} that God that shall deliver you out of my hands? {dulcimer: or, singing: Chaldee, symphony}', 'now if ye be ready that at what time ye hear the sound of the cornet flute harp sackbut psaltery and dulcimer and all kinds of musick ye fall down and worship the image which i have made well but if ye worship not ye shall be cast the same hour into the midst of a burning fiery furnace and who is that god that shall deliver you out of my hands dulcimer or singing chaldee symphony');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 16, 'Shadrach, Meshach, and Abednego, answered and said to the king, O Nebuchadnezzar, we {are} not careful to answer thee in this matter.', 'shadrach meshach and abednego answered and said to the king o nebuchadnezzar we are not careful to answer thee in this matter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 17, 'If it be {so}, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver {us} out of thine hand, O king.', 'if it be so our god whom we serve is able to deliver us from the burning fiery furnace and he will deliver us out of thine hand o king');
