INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 19, 'Then was Nebuchadnezzar full of fury, and the form of his visage was changed against Shadrach, Meshach, and Abednego: {therefore} he spake, and commanded that they should heat the furnace one seven times more than it was wont to be heated. {full: Chaldee, filled}', 'then was nebuchadnezzar full of fury and the form of his visage was changed against shadrach meshach and abednego therefore he spake and commanded that they should heat the furnace one seven times more than it was wont to be heated full chaldee filled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 20, 'And he commanded the most mighty men that {were} in his army to bind Shadrach, Meshach, and Abednego, {and} to cast {them} into the burning fiery furnace. {most...: Chaldee, mighty of strength}', 'and he commanded the most mighty men that were in his army to bind shadrach meshach and abednego and to cast them into the burning fiery furnace most chaldee mighty of strength');
