INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 22, 'Therefore because the king''s commandment was urgent, and the furnace exceeding hot, the flame of the fire slew those men that took up Shadrach, Meshach, and Abednego. {commandment: Chaldee, word} {flame: or, spark}', 'therefore because the king s commandment was urgent and the furnace exceeding hot the flame of the fire slew those men that took up shadrach meshach and abednego commandment chaldee word flame or spark');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 23, 'And these three men, Shadrach, Meshach, and Abednego, fell down bound into the midst of the burning fiery furnace.', 'and these three men shadrach meshach and abednego fell down bound into the midst of the burning fiery furnace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 24, 'Then Nebuchadnezzar the king was astonied, and rose up in haste, {and} spake, and said unto his counsellors, Did not we cast three men bound into the midst of the fire? They answered and said unto the king, True, O king. {counsellors: or, governors}', 'then nebuchadnezzar the king was astonied and rose up in haste and spake and said unto his counsellors did not we cast three men bound into the midst of the fire they answered and said unto the king true o king counsellors or governors');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 25, 'He answered and said, Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God. {they...: Chaldee, there is no hurt in them}', 'he answered and said lo i see four men loose walking in the midst of the fire and they have no hurt and the form of the fourth is like the son of god they chaldee there is no hurt in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 26, 'Then Nebuchadnezzar came near to the mouth of the burning fiery furnace, {and} spake, and said, Shadrach, Meshach, and Abednego, ye servants of the most high God, come forth, and come {hither}. Then Shadrach, Meshach, and Abednego, came forth of the midst of the fire. {mouth: Chaldee, door}', 'then nebuchadnezzar came near to the mouth of the burning fiery furnace and spake and said shadrach meshach and abednego ye servants of the most high god come forth and come hither then shadrach meshach and abednego came forth of the midst of the fire mouth chaldee door');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 27, 'And the princes, governors, and captains, and the king''s counsellors, being gathered together, saw these men, upon whose bodies the fire had no power, nor was an hair of their head singed, neither were their coats changed, nor the smell of fire had passed on them.', 'and the princes governors and captains and the king s counsellors being gathered together saw these men upon whose bodies the fire had no power nor was an hair of their head singed neither were their coats changed nor the smell of fire had passed on them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 28, '{Then} Nebuchadnezzar spake, and said, Blessed {be} the God of Shadrach, Meshach, and Abednego, who hath sent his angel, and delivered his servants that trusted in him, and have changed the king''s word, and yielded their bodies, that they might not serve nor worship any god, except their own God.', 'then nebuchadnezzar spake and said blessed be the god of shadrach meshach and abednego who hath sent his angel and delivered his servants that trusted in him and have changed the king s word and yielded their bodies that they might not serve nor worship any god except their own god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 3, 29, 'Therefore I make a decree, That every people, nation, and language, which speak any thing amiss against the God of Shadrach, Meshach, and Abednego, shall be cut in pieces, and their houses shall be made a dunghill: because there is no other God that can deliver after this sort. {I make...: Chaldee, a decree is made by me} {any...: Chaldee, error} {cut...: Chaldee, made pieces}', 'therefore i make a decree that every people nation and language which speak any thing amiss against the god of shadrach meshach and abednego shall be cut in pieces and their houses shall be made a dunghill because there is no other god that can deliver after this sort i make chaldee a decree is made by me any chaldee error cut chaldee made pieces');
