INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 1, 'Nebuchadnezzar the king, unto all people, nations, and languages, that dwell in all the earth; Peace be multiplied unto you.', 'nebuchadnezzar the king unto all people nations and languages that dwell in all the earth peace be multiplied unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 2, 'I thought it good to shew the signs and wonders that the high God hath wrought toward me. {I thought...: Chaldee, It was seemly before me}', 'i thought it good to shew the signs and wonders that the high god hath wrought toward me i thought chaldee it was seemly before me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 3, 'How great {are} his signs! and how mighty {are} his wonders! his kingdom {is} an everlasting kingdom, and his dominion {is} from generation to generation.', 'how great are his signs and how mighty are his wonders his kingdom is an everlasting kingdom and his dominion is from generation to generation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 4, 'I Nebuchadnezzar was at rest in mine house, and flourishing in my palace:', 'i nebuchadnezzar was at rest in mine house and flourishing in my palace');
