INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 6, 'Therefore made I a decree to bring in all the wise {men} of Babylon before me, that they might make known unto me the interpretation of the dream.', 'therefore made i a decree to bring in all the wise men of babylon before me that they might make known unto me the interpretation of the dream');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 7, 'Then came in the magicians, the astrologers, the Chaldeans, and the soothsayers: and I told the dream before them; but they did not make known unto me the interpretation thereof.', 'then came in the magicians the astrologers the chaldeans and the soothsayers and i told the dream before them but they did not make known unto me the interpretation thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 8, 'But at the last Daniel came in before me, whose name {was} Belteshazzar, according to the name of my god, and in whom {is} the spirit of the holy gods: and before him I told the dream, {saying},', 'but at the last daniel came in before me whose name was belteshazzar according to the name of my god and in whom is the spirit of the holy gods and before him i told the dream saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 9, 'O Belteshazzar, master of the magicians, because I know that the spirit of the holy gods {is} in thee, and no secret troubleth thee, tell me the visions of my dream that I have seen, and the interpretation thereof.', 'o belteshazzar master of the magicians because i know that the spirit of the holy gods is in thee and no secret troubleth thee tell me the visions of my dream that i have seen and the interpretation thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 10, 'Thus {were} the visions of mine head in my bed; I saw, and behold a tree in the midst of the earth, and the height thereof {was} great. {I saw: Chaldee, I was seeing}', 'thus were the visions of mine head in my bed i saw and behold a tree in the midst of the earth and the height thereof was great i saw chaldee i was seeing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 11, 'The tree grew, and was strong, and the height thereof reached unto heaven, and the sight thereof to the end of all the earth:', 'the tree grew and was strong and the height thereof reached unto heaven and the sight thereof to the end of all the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 12, 'The leaves thereof {were} fair, and the fruit thereof much, and in it {was} meat for all: the beasts of the field had shadow under it, and the fowls of the heaven dwelt in the boughs thereof, and all flesh was fed of it.', 'the leaves thereof were fair and the fruit thereof much and in it was meat for all the beasts of the field had shadow under it and the fowls of the heaven dwelt in the boughs thereof and all flesh was fed of it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 13, 'I saw in the visions of my head upon my bed, and, behold, a watcher and an holy one came down from heaven;', 'i saw in the visions of my head upon my bed and behold a watcher and an holy one came down from heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 14, 'He cried aloud, and said thus, Hew down the tree, and cut off his branches, shake off his leaves, and scatter his fruit: let the beasts get away from under it, and the fowls from his branches: {aloud: Chaldee, with might}', 'he cried aloud and said thus hew down the tree and cut off his branches shake off his leaves and scatter his fruit let the beasts get away from under it and the fowls from his branches aloud chaldee with might');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 15, 'Nevertheless leave the stump of his roots in the earth, even with a band of iron and brass, in the tender grass of the field; and let it be wet with the dew of heaven, and {let} his portion {be} with the beasts in the grass of the earth:', 'nevertheless leave the stump of his roots in the earth even with a band of iron and brass in the tender grass of the field and let it be wet with the dew of heaven and let his portion be with the beasts in the grass of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 16, 'Let his heart be changed from man''s, and let a beast''s heart be given unto him; and let seven times pass over him.', 'let his heart be changed from man s and let a beast s heart be given unto him and let seven times pass over him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 17, 'This matter {is} by the decree of the watchers, and the demand by the word of the holy ones: to the intent that the living may know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will, and setteth up over it the basest of men.', 'this matter is by the decree of the watchers and the demand by the word of the holy ones to the intent that the living may know that the most high ruleth in the kingdom of men and giveth it to whomsoever he will and setteth up over it the basest of men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 18, 'This dream I king Nebuchadnezzar have seen. Now thou, O Belteshazzar, declare the interpretation thereof, forasmuch as all the wise {men} of my kingdom are not able to make known unto me the interpretation: but thou {art} able; for the spirit of the holy gods {is} in thee.', 'this dream i king nebuchadnezzar have seen now thou o belteshazzar declare the interpretation thereof forasmuch as all the wise men of my kingdom are not able to make known unto me the interpretation but thou art able for the spirit of the holy gods is in thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 19, 'Then Daniel, whose name {was} Belteshazzar, was astonied for one hour, and his thoughts troubled him. The king spake, and said, Belteshazzar, let not the dream, or the interpretation thereof, trouble thee. Belteshazzar answered and said, My lord, the dream {be} to them that hate thee, and the interpretation thereof to thine enemies.', 'then daniel whose name was belteshazzar was astonied for one hour and his thoughts troubled him the king spake and said belteshazzar let not the dream or the interpretation thereof trouble thee belteshazzar answered and said my lord the dream be to them that hate thee and the interpretation thereof to thine enemies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 20, 'The tree that thou sawest, which grew, and was strong, whose height reached unto the heaven, and the sight thereof to all the earth;', 'the tree that thou sawest which grew and was strong whose height reached unto the heaven and the sight thereof to all the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 21, 'Whose leaves {were} fair, and the fruit thereof much, and in it {was} meat for all; under which the beasts of the field dwelt, and upon whose branches the fowls of the heaven had their habitation:', 'whose leaves were fair and the fruit thereof much and in it was meat for all under which the beasts of the field dwelt and upon whose branches the fowls of the heaven had their habitation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 22, 'It {is} thou, O king, that art grown and become strong: for thy greatness is grown, and reacheth unto heaven, and thy dominion to the end of the earth.', 'it is thou o king that art grown and become strong for thy greatness is grown and reacheth unto heaven and thy dominion to the end of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 23, 'And whereas the king saw a watcher and an holy one coming down from heaven, and saying, Hew the tree down, and destroy it; yet leave the stump of the roots thereof in the earth, even with a band of iron and brass, in the tender grass of the field; and let it be wet with the dew of heaven, and {let} his portion {be} with the beasts of the field, till seven times pass over him;', 'and whereas the king saw a watcher and an holy one coming down from heaven and saying hew the tree down and destroy it yet leave the stump of the roots thereof in the earth even with a band of iron and brass in the tender grass of the field and let it be wet with the dew of heaven and let his portion be with the beasts of the field till seven times pass over him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 24, 'This {is} the interpretation, O king, and this {is} the decree of the most High, which is come upon my lord the king:', 'this is the interpretation o king and this is the decree of the most high which is come upon my lord the king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 25, 'That they shall drive thee from men, and thy dwelling shall be with the beasts of the field, and they shall make thee to eat grass as oxen, and they shall wet thee with the dew of heaven, and seven times shall pass over thee, till thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will.', 'that they shall drive thee from men and thy dwelling shall be with the beasts of the field and they shall make thee to eat grass as oxen and they shall wet thee with the dew of heaven and seven times shall pass over thee till thou know that the most high ruleth in the kingdom of men and giveth it to whomsoever he will');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 26, 'And whereas they commanded to leave the stump of the tree roots; thy kingdom shall be sure unto thee, after that thou shalt have known that the heavens do rule.', 'and whereas they commanded to leave the stump of the tree roots thy kingdom shall be sure unto thee after that thou shalt have known that the heavens do rule');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 27, 'Wherefore, O king, let my counsel be acceptable unto thee, and break off thy sins by righteousness, and thine iniquities by shewing mercy to the poor; if it may be a lengthening of thy tranquillity. {a lengthening...: or, an healing of thine error}', 'wherefore o king let my counsel be acceptable unto thee and break off thy sins by righteousness and thine iniquities by shewing mercy to the poor if it may be a lengthening of thy tranquillity a lengthening or an healing of thine error');
