INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 29, 'At the end of twelve months he walked in the palace of the kingdom of Babylon. {in: or, upon}', 'at the end of twelve months he walked in the palace of the kingdom of babylon in or upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 30, 'The king spake, and said, Is not this great Babylon, that I have built for the house of the kingdom by the might of my power, and for the honour of my majesty?', 'the king spake and said is not this great babylon that i have built for the house of the kingdom by the might of my power and for the honour of my majesty');
