INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 32, 'And they shall drive thee from men, and thy dwelling {shall be} with the beasts of the field: they shall make thee to eat grass as oxen, and seven times shall pass over thee, until thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will.', 'and they shall drive thee from men and thy dwelling shall be with the beasts of the field they shall make thee to eat grass as oxen and seven times shall pass over thee until thou know that the most high ruleth in the kingdom of men and giveth it to whomsoever he will');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 33, 'The same hour was the thing fulfilled upon Nebuchadnezzar: and he was driven from men, and did eat grass as oxen, and his body was wet with the dew of heaven, till his hairs were grown like eagles'' {feathers}, and his nails like birds'' {claws}.', 'the same hour was the thing fulfilled upon nebuchadnezzar and he was driven from men and did eat grass as oxen and his body was wet with the dew of heaven till his hairs were grown like eagles feathers and his nails like birds claws');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 34, 'And at the end of the days I Nebuchadnezzar lifted up mine eyes unto heaven, and mine understanding returned unto me, and I blessed the most High, and I praised and honoured him that liveth for ever, whose dominion {is} an everlasting dominion, and his kingdom {is} from generation to generation:', 'and at the end of the days i nebuchadnezzar lifted up mine eyes unto heaven and mine understanding returned unto me and i blessed the most high and i praised and honoured him that liveth for ever whose dominion is an everlasting dominion and his kingdom is from generation to generation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 35, 'And all the inhabitants of the earth {are} reputed as nothing: and he doeth according to his will in the army of heaven, and {among} the inhabitants of the earth: and none can stay his hand, or say unto him, What doest thou?', 'and all the inhabitants of the earth are reputed as nothing and he doeth according to his will in the army of heaven and among the inhabitants of the earth and none can stay his hand or say unto him what doest thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 36, 'At the same time my reason returned unto me; and for the glory of my kingdom, mine honour and brightness returned unto me; and my counsellors and my lords sought unto me; and I was established in my kingdom, and excellent majesty was added unto me.', 'at the same time my reason returned unto me and for the glory of my kingdom mine honour and brightness returned unto me and my counsellors and my lords sought unto me and i was established in my kingdom and excellent majesty was added unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 4, 37, 'Now I Nebuchadnezzar praise and extol and honour the King of heaven, all whose works {are} truth, and his ways judgment: and those that walk in pride he is able to abase.', 'now i nebuchadnezzar praise and extol and honour the king of heaven all whose works are truth and his ways judgment and those that walk in pride he is able to abase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 1, 'Belshazzar the king made a great feast to a thousand of his lords, and drank wine before the thousand.', 'belshazzar the king made a great feast to a thousand of his lords and drank wine before the thousand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 2, 'Belshazzar, whiles he tasted the wine, commanded to bring the golden and silver vessels which his father Nebuchadnezzar had taken out of the temple which {was} in Jerusalem; that the king, and his princes, his wives, and his concubines, might drink therein. {father: or, grandfather} {taken: Chaldee, brought forth}', 'belshazzar whiles he tasted the wine commanded to bring the golden and silver vessels which his father nebuchadnezzar had taken out of the temple which was in jerusalem that the king and his princes his wives and his concubines might drink therein father or grandfather taken chaldee brought forth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 3, 'Then they brought the golden vessels that were taken out of the temple of the house of God which {was} at Jerusalem; and the king, and his princes, his wives, and his concubines, drank in them.', 'then they brought the golden vessels that were taken out of the temple of the house of god which was at jerusalem and the king and his princes his wives and his concubines drank in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 4, 'They drank wine, and praised the gods of gold, and of silver, of brass, of iron, of wood, and of stone.', 'they drank wine and praised the gods of gold and of silver of brass of iron of wood and of stone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 5, 'In the same hour came forth fingers of a man''s hand, and wrote over against the candlestick upon the plaister of the wall of the king''s palace: and the king saw the part of the hand that wrote.', 'in the same hour came forth fingers of a man s hand and wrote over against the candlestick upon the plaister of the wall of the king s palace and the king saw the part of the hand that wrote');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 6, 'Then the king''s countenance was changed, and his thoughts troubled him, so that the joints of his loins were loosed, and his knees smote one against another. {countenance: Chaldee, brightnesses} {was changed: Chaldee, changed it} {joints: or, girdles: Chaldee, bindings, or, knots}', 'then the king s countenance was changed and his thoughts troubled him so that the joints of his loins were loosed and his knees smote one against another countenance chaldee brightnesses was changed chaldee changed it joints or girdles chaldee bindings or knots');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 7, 'The king cried aloud to bring in the astrologers, the Chaldeans, and the soothsayers. {And} the king spake, and said to the wise {men} of Babylon, Whosoever shall read this writing, and shew me the interpretation thereof, shall be clothed with scarlet, and {have} a chain of gold about his neck, and shall be the third ruler in the kingdom. {aloud: Chaldee, with might} {scarlet: or, purple}', 'the king cried aloud to bring in the astrologers the chaldeans and the soothsayers and the king spake and said to the wise men of babylon whosoever shall read this writing and shew me the interpretation thereof shall be clothed with scarlet and have a chain of gold about his neck and shall be the third ruler in the kingdom aloud chaldee with might scarlet or purple');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 8, 'Then came in all the king''s wise {men}: but they could not read the writing, nor make known to the king the interpretation thereof.', 'then came in all the king s wise men but they could not read the writing nor make known to the king the interpretation thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 9, 'Then was king Belshazzar greatly troubled, and his countenance was changed in him, and his lords were astonied. {countenance: Chaldee, brightnesses}', 'then was king belshazzar greatly troubled and his countenance was changed in him and his lords were astonied countenance chaldee brightnesses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 10, '{Now} the queen, by reason of the words of the king and his lords, came into the banquet house: {and} the queen spake and said, O king, live for ever: let not thy thoughts trouble thee, nor let thy countenance be changed:', 'now the queen by reason of the words of the king and his lords came into the banquet house and the queen spake and said o king live for ever let not thy thoughts trouble thee nor let thy countenance be changed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 11, 'There is a man in thy kingdom, in whom {is} the spirit of the holy gods; and in the days of thy father light and understanding and wisdom, like the wisdom of the gods, was found in him; whom the king Nebuchadnezzar thy father, the king, {I say}, thy father, made master of the magicians, astrologers, Chaldeans, {and} soothsayers; {father: or, grandfather}', 'there is a man in thy kingdom in whom is the spirit of the holy gods and in the days of thy father light and understanding and wisdom like the wisdom of the gods was found in him whom the king nebuchadnezzar thy father the king i say thy father made master of the magicians astrologers chaldeans and soothsayers father or grandfather');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 12, 'Forasmuch as an excellent spirit, and knowledge, and understanding, interpreting of dreams, and shewing of hard sentences, and dissolving of doubts, were found in the same Daniel, whom the king named Belteshazzar: now let Daniel be called, and he will shew the interpretation. {interpreting: or, of an interpreter} {dissolving: or, of a dissolver} {doubts: Chaldee, knots}', 'forasmuch as an excellent spirit and knowledge and understanding interpreting of dreams and shewing of hard sentences and dissolving of doubts were found in the same daniel whom the king named belteshazzar now let daniel be called and he will shew the interpretation interpreting or of an interpreter dissolving or of a dissolver doubts chaldee knots');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 13, 'Then was Daniel brought in before the king. {And} the king spake and said unto Daniel, {Art} thou that Daniel, which {art} of the children of the captivity of Judah, whom the king my father brought out of Jewry? {father: or, grandfather}', 'then was daniel brought in before the king and the king spake and said unto daniel art thou that daniel which art of the children of the captivity of judah whom the king my father brought out of jewry father or grandfather');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 14, 'I have even heard of thee, that the spirit of the gods {is} in thee, and {that} light and understanding and excellent wisdom is found in thee.', 'i have even heard of thee that the spirit of the gods is in thee and that light and understanding and excellent wisdom is found in thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 15, 'And now the wise {men}, the astrologers, have been brought in before me, that they should read this writing, and make known unto me the interpretation thereof: but they could not shew the interpretation of the thing:', 'and now the wise men the astrologers have been brought in before me that they should read this writing and make known unto me the interpretation thereof but they could not shew the interpretation of the thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 16, 'And I have heard of thee, that thou canst make interpretations, and dissolve doubts: now if thou canst read the writing, and make known to me the interpretation thereof, thou shalt be clothed with scarlet, and {have} a chain of gold about thy neck, and shalt be the third ruler in the kingdom. {make interpretations: Chaldee, interpret, etc}', 'and i have heard of thee that thou canst make interpretations and dissolve doubts now if thou canst read the writing and make known to me the interpretation thereof thou shalt be clothed with scarlet and have a chain of gold about thy neck and shalt be the third ruler in the kingdom make interpretations chaldee interpret etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 17, 'Then Daniel answered and said before the king, Let thy gifts be to thyself, and give thy rewards to another; yet I will read the writing unto the king, and make known to him the interpretation. {rewards: or, fee}', 'then daniel answered and said before the king let thy gifts be to thyself and give thy rewards to another yet i will read the writing unto the king and make known to him the interpretation rewards or fee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 18, 'O thou king, the most high God gave Nebuchadnezzar thy father a kingdom, and majesty, and glory, and honour:', 'o thou king the most high god gave nebuchadnezzar thy father a kingdom and majesty and glory and honour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 19, 'And for the majesty that he gave him, all people, nations, and languages, trembled and feared before him: whom he would he slew; and whom he would he kept alive; and whom he would he set up; and whom he would he put down.', 'and for the majesty that he gave him all people nations and languages trembled and feared before him whom he would he slew and whom he would he kept alive and whom he would he set up and whom he would he put down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 20, 'But when his heart was lifted up, and his mind hardened in pride, he was deposed from his kingly throne, and they took his glory from him: {in pride: or, to deal proudly} {deposed: Chaldee, made to come down}', 'but when his heart was lifted up and his mind hardened in pride he was deposed from his kingly throne and they took his glory from him in pride or to deal proudly deposed chaldee made to come down');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 21, 'And he was driven from the sons of men; and his heart was made like the beasts, and his dwelling {was} with the wild asses: they fed him with grass like oxen, and his body was wet with the dew of heaven; till he knew that the most high God ruled in the kingdom of men, and {that} he appointeth over it whomsoever he will. {his heart...: or, he made his heart equal, etc}', 'and he was driven from the sons of men and his heart was made like the beasts and his dwelling was with the wild asses they fed him with grass like oxen and his body was wet with the dew of heaven till he knew that the most high god ruled in the kingdom of men and that he appointeth over it whomsoever he will his heart or he made his heart equal etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 22, 'And thou his son, O Belshazzar, hast not humbled thine heart, though thou knewest all this;', 'and thou his son o belshazzar hast not humbled thine heart though thou knewest all this');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 23, 'But hast lifted up thyself against the Lord of heaven; and they have brought the vessels of his house before thee, and thou, and thy lords, thy wives, and thy concubines, have drunk wine in them; and thou hast praised the gods of silver, and gold, of brass, iron, wood, and stone, which see not, nor hear, nor know: and the God in whose hand thy breath {is}, and whose {are} all thy ways, hast thou not glorified:', 'but hast lifted up thyself against the lord of heaven and they have brought the vessels of his house before thee and thou and thy lords thy wives and thy concubines have drunk wine in them and thou hast praised the gods of silver and gold of brass iron wood and stone which see not nor hear nor know and the god in whose hand thy breath is and whose are all thy ways hast thou not glorified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 24, 'Then was the part of the hand sent from him; and this writing was written.', 'then was the part of the hand sent from him and this writing was written');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 25, 'And this {is} the writing that was written, MENE, MENE, TEKEL, UPHARSIN.', 'and this is the writing that was written mene mene tekel upharsin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 26, 'This {is} the interpretation of the thing: MENE; God hath numbered thy kingdom, and finished it.', 'this is the interpretation of the thing mene god hath numbered thy kingdom and finished it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 27, 'TEKEL; Thou art weighed in the balances, and art found wanting.', 'tekel thou art weighed in the balances and art found wanting');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 28, 'PERES; Thy kingdom is divided, and given to the Medes and Persians.', 'peres thy kingdom is divided and given to the medes and persians');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 29, 'Then commanded Belshazzar, and they clothed Daniel with scarlet, and {put} a chain of gold about his neck, and made a proclamation concerning him, that he should be the third ruler in the kingdom.', 'then commanded belshazzar and they clothed daniel with scarlet and put a chain of gold about his neck and made a proclamation concerning him that he should be the third ruler in the kingdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 30, 'In that night was Belshazzar the king of the Chaldeans slain.', 'in that night was belshazzar the king of the chaldeans slain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 5, 31, 'And Darius the Median took the kingdom, {being} about threescore and two years old. {being...: Chaldee, he as the son of, etc} {about: or, now}', 'and darius the median took the kingdom being about threescore and two years old being chaldee he as the son of etc about or now');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 1, 'It pleased Darius to set over the kingdom an hundred and twenty princes, which should be over the whole kingdom;', 'it pleased darius to set over the kingdom an hundred and twenty princes which should be over the whole kingdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 2, 'And over these three presidents; of whom Daniel {was} first: that the princes might give accounts unto them, and the king should have no damage.', 'and over these three presidents of whom daniel was first that the princes might give accounts unto them and the king should have no damage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 3, 'Then this Daniel was preferred above the presidents and princes, because an excellent spirit {was} in him; and the king thought to set him over the whole realm.', 'then this daniel was preferred above the presidents and princes because an excellent spirit was in him and the king thought to set him over the whole realm');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 4, 'Then the presidents and princes sought to find occasion against Daniel concerning the kingdom; but they could find none occasion nor fault; forasmuch as he {was} faithful, neither was there any error or fault found in him.', 'then the presidents and princes sought to find occasion against daniel concerning the kingdom but they could find none occasion nor fault forasmuch as he was faithful neither was there any error or fault found in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 5, 'Then said these men, We shall not find any occasion against this Daniel, except we find {it} against him concerning the law of his God.', 'then said these men we shall not find any occasion against this daniel except we find it against him concerning the law of his god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 6, 'Then these presidents and princes assembled together to the king, and said thus unto him, King Darius, live for ever. {assembled...: or, came tumultuously}', 'then these presidents and princes assembled together to the king and said thus unto him king darius live for ever assembled or came tumultuously');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 7, 'All the presidents of the kingdom, the governors, and the princes, the counsellors, and the captains, have consulted together to establish a royal statute, and to make a firm decree, that whosoever shall ask a petition of any God or man for thirty days, save of thee, O king, he shall be cast into the den of lions. {decree: or, interdict}', 'all the presidents of the kingdom the governors and the princes the counsellors and the captains have consulted together to establish a royal statute and to make a firm decree that whosoever shall ask a petition of any god or man for thirty days save of thee o king he shall be cast into the den of lions decree or interdict');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 8, 'Now, O king, establish the decree, and sign the writing, that it be not changed, according to the law of the Medes and Persians, which altereth not. {altereth not: Chaldee, passeth not}', 'now o king establish the decree and sign the writing that it be not changed according to the law of the medes and persians which altereth not altereth not chaldee passeth not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 9, 'Wherefore king Darius signed the writing and the decree.', 'wherefore king darius signed the writing and the decree');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 10, 'Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime.', 'now when daniel knew that the writing was signed he went into his house and his windows being open in his chamber toward jerusalem he kneeled upon his knees three times a day and prayed and gave thanks before his god as he did aforetime');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 11, 'Then these men assembled, and found Daniel praying and making supplication before his God.', 'then these men assembled and found daniel praying and making supplication before his god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 12, 'Then they came near, and spake before the king concerning the king''s decree; Hast thou not signed a decree, that every man that shall ask {a petition} of any God or man within thirty days, save of thee, O king, shall be cast into the den of lions? The king answered and said, The thing {is} true, according to the law of the Medes and Persians, which altereth not.', 'then they came near and spake before the king concerning the king s decree hast thou not signed a decree that every man that shall ask a petition of any god or man within thirty days save of thee o king shall be cast into the den of lions the king answered and said the thing is true according to the law of the medes and persians which altereth not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 13, 'Then answered they and said before the king, That Daniel, which {is} of the children of the captivity of Judah, regardeth not thee, O king, nor the decree that thou hast signed, but maketh his petition three times a day.', 'then answered they and said before the king that daniel which is of the children of the captivity of judah regardeth not thee o king nor the decree that thou hast signed but maketh his petition three times a day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 14, 'Then the king, when he heard {these} words, was sore displeased with himself, and set {his} heart on Daniel to deliver him: and he laboured till the going down of the sun to deliver him.', 'then the king when he heard these words was sore displeased with himself and set his heart on daniel to deliver him and he laboured till the going down of the sun to deliver him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 15, 'Then these men assembled unto the king, and said unto the king, Know, O king, that the law of the Medes and Persians {is}, That no decree nor statute which the king establisheth may be changed.', 'then these men assembled unto the king and said unto the king know o king that the law of the medes and persians is that no decree nor statute which the king establisheth may be changed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 16, 'Then the king commanded, and they brought Daniel, and cast {him} into the den of lions. {Now} the king spake and said unto Daniel, Thy God whom thou servest continually, he will deliver thee.', 'then the king commanded and they brought daniel and cast him into the den of lions now the king spake and said unto daniel thy god whom thou servest continually he will deliver thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 17, 'And a stone was brought, and laid upon the mouth of the den; and the king sealed it with his own signet, and with the signet of his lords; that the purpose might not be changed concerning Daniel.', 'and a stone was brought and laid upon the mouth of the den and the king sealed it with his own signet and with the signet of his lords that the purpose might not be changed concerning daniel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 18, 'Then the king went to his palace, and passed the night fasting: neither were instruments of musick brought before him: and his sleep went from him. {instruments...: or, table}', 'then the king went to his palace and passed the night fasting neither were instruments of musick brought before him and his sleep went from him instruments or table');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 19, 'Then the king arose very early in the morning, and went in haste unto the den of lions.', 'then the king arose very early in the morning and went in haste unto the den of lions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 20, 'And when he came to the den, he cried with a lamentable voice unto Daniel: {and} the king spake and said to Daniel, O Daniel, servant of the living God, is thy God, whom thou servest continually, able to deliver thee from the lions?', 'and when he came to the den he cried with a lamentable voice unto daniel and the king spake and said to daniel o daniel servant of the living god is thy god whom thou servest continually able to deliver thee from the lions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 6, 21, 'Then said Daniel unto the king, O king, live for ever.', 'then said daniel unto the king o king live for ever');
