INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 27, 'Unknown', 7, 10, 'A fiery stream issued and came forth from before him: thousand thousands ministered unto him, and ten thousand times ten thousand stood before him: the judgment was set, and the books were opened.', 'a fiery stream issued and came forth from before him thousand thousands ministered unto him and ten thousand times ten thousand stood before him the judgment was set and the books were opened');
