INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 33, 'Unknown', 4, 3, 'And he shall judge among many people, and rebuke strong nations afar off; and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up a sword against nation, neither shall they learn war any more. {pruninghooks: or, scythes}', 'and he shall judge among many people and rebuke strong nations afar off and they shall beat their swords into plowshares and their spears into pruninghooks nation shall not lift up a sword against nation neither shall they learn war any more pruninghooks or scythes');
