INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 37, 'Unknown', 1, 5, 'Now therefore thus saith the LORD of hosts; Consider your ways. {Consider...: Heb. Set your heart on your ways}', 'now therefore thus saith the lord of hosts consider your ways consider heb set your heart on your ways');
