INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 37, 'Unknown', 1, 8, 'Go up to the mountain, and bring wood, and build the house; and I will take pleasure in it, and I will be glorified, saith the LORD.', 'go up to the mountain and bring wood and build the house and i will take pleasure in it and i will be glorified saith the lord');
