INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 37, 'Unknown', 2, 3, 'Who {is} left among you that saw this house in her first glory? and how do ye see it now? {is it} not in your eyes in comparison of it as nothing?', 'who is left among you that saw this house in her first glory and how do ye see it now is it not in your eyes in comparison of it as nothing');
