INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 1, 3, 'Therefore say thou unto them, Thus saith the LORD of hosts; Turn ye unto me, saith the LORD of hosts, and I will turn unto you, saith the LORD of hosts.', 'therefore say thou unto them thus saith the lord of hosts turn ye unto me saith the lord of hosts and i will turn unto you saith the lord of hosts');
