INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 1, 13, 'And the LORD answered the angel that talked with me {with} good words {and} comfortable words.', 'and the lord answered the angel that talked with me with good words and comfortable words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 1, 14, 'So the angel that communed with me said unto me, Cry thou, saying, Thus saith the LORD of hosts; I am jealous for Jerusalem and for Zion with a great jealousy.', 'so the angel that communed with me said unto me cry thou saying thus saith the lord of hosts i am jealous for jerusalem and for zion with a great jealousy');
