INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 2, 8, 'For thus saith the LORD of hosts; After the glory hath he sent me unto the nations which spoiled you: for he that toucheth you toucheth the apple of his eye.', 'for thus saith the lord of hosts after the glory hath he sent me unto the nations which spoiled you for he that toucheth you toucheth the apple of his eye');
