INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 3, 8, 'Hear now, O Joshua the high priest, thou, and thy fellows that sit before thee: for they {are} men wondered at: for, behold, I will bring forth my servant the BRANCH. {wondered...: Heb. of wonder, or, sign}', 'hear now o joshua the high priest thou and thy fellows that sit before thee for they are men wondered at for behold i will bring forth my servant the branch wondered heb of wonder or sign');
