INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 3, 10, 'In that day, saith the LORD of hosts, shall ye call every man his neighbour under the vine and under the fig tree.', 'in that day saith the lord of hosts shall ye call every man his neighbour under the vine and under the fig tree');
