INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 4, 2, 'And said unto me, What seest thou? And I said, I have looked, and behold a candlestick all {of} gold, with a bowl upon the top of it, and his seven lamps thereon, and seven pipes to the seven lamps, which {are} upon the top thereof: {a bowl: Heb. her bowl} {seven pipes...: or, seven several pipes to the lamps}', 'and said unto me what seest thou and i said i have looked and behold a candlestick all of gold with a bowl upon the top of it and his seven lamps thereon and seven pipes to the seven lamps which are upon the top thereof a bowl heb her bowl seven pipes or seven several pipes to the lamps');
