INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 7, 9, 'Thus speaketh the LORD of hosts, saying, Execute true judgment, and shew mercy and compassions every man to his brother: {Execute...: Heb. Judge judgment of truth}', 'thus speaketh the lord of hosts saying execute true judgment and shew mercy and compassions every man to his brother execute heb judge judgment of truth');
