INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 8, 4, 'Thus saith the LORD of hosts; There shall yet old men and old women dwell in the streets of Jerusalem, and every man with his staff in his hand for very age. {very...: Heb. multitude of days}', 'thus saith the lord of hosts there shall yet old men and old women dwell in the streets of jerusalem and every man with his staff in his hand for very age very heb multitude of days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 8, 5, 'And the streets of the city shall be full of boys and girls playing in the streets thereof.', 'and the streets of the city shall be full of boys and girls playing in the streets thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 8, 6, 'Thus saith the LORD of hosts; If it be marvellous in the eyes of the remnant of this people in these days, should it also be marvellous in mine eyes? saith the LORD of hosts. {marvellous: or, hard, or, difficult}', 'thus saith the lord of hosts if it be marvellous in the eyes of the remnant of this people in these days should it also be marvellous in mine eyes saith the lord of hosts marvellous or hard or difficult');
