INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 8, 10, 'For before these days there was no hire for man, nor any hire for beast; neither {was there any} peace to him that went out or came in because of the affliction: for I set all men every one against his neighbour. {there was...: or, the hire of man became nothing}', 'for before these days there was no hire for man nor any hire for beast neither was there any peace to him that went out or came in because of the affliction for i set all men every one against his neighbour there was or the hire of man became nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 8, 11, 'But now I {will} not {be} unto the residue of this people as in the former days, saith the LORD of hosts.', 'but now i will not be unto the residue of this people as in the former days saith the lord of hosts');
