INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 8, 13, 'And it shall come to pass, {that} as ye were a curse among the heathen, O house of Judah, and house of Israel; so will I save you, and ye shall be a blessing: fear not, {but} let your hands be strong.', 'and it shall come to pass that as ye were a curse among the heathen o house of judah and house of israel so will i save you and ye shall be a blessing fear not but let your hands be strong');
