INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 12, 3, 'And in that day will I make Jerusalem a burdensome stone for all people: all that burden themselves with it shall be cut in pieces, though all the people of the earth be gathered together against it.', 'and in that day will i make jerusalem a burdensome stone for all people all that burden themselves with it shall be cut in pieces though all the people of the earth be gathered together against it');
