INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 12, 9, 'And it shall come to pass in that day, {that} I will seek to destroy all the nations that come against Jerusalem.', 'and it shall come to pass in that day that i will seek to destroy all the nations that come against jerusalem');
