INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 1, 'In that day there shall be a fountain opened to the house of David and to the inhabitants of Jerusalem for sin and for uncleanness. {uncleanness: Heb. separation for uncleanness}', 'in that day there shall be a fountain opened to the house of david and to the inhabitants of jerusalem for sin and for uncleanness uncleanness heb separation for uncleanness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 2, 'And it shall come to pass in that day, saith the LORD of hosts, {that} I will cut off the names of the idols out of the land, and they shall no more be remembered: and also I will cause the prophets and the unclean spirit to pass out of the land.', 'and it shall come to pass in that day saith the lord of hosts that i will cut off the names of the idols out of the land and they shall no more be remembered and also i will cause the prophets and the unclean spirit to pass out of the land');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 3, 'And it shall come to pass, {that} when any shall yet prophesy, then his father and his mother that begat him shall say unto him, Thou shalt not live; for thou speakest lies in the name of the LORD: and his father and his mother that begat him shall thrust him through when he prophesieth.', 'and it shall come to pass that when any shall yet prophesy then his father and his mother that begat him shall say unto him thou shalt not live for thou speakest lies in the name of the lord and his father and his mother that begat him shall thrust him through when he prophesieth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 4, 'And it shall come to pass in that day, {that} the prophets shall be ashamed every one of his vision, when he hath prophesied; neither shall they wear a rough garment to deceive: {a rough...: Heb. a garment of hair} {deceive: Heb. lie}', 'and it shall come to pass in that day that the prophets shall be ashamed every one of his vision when he hath prophesied neither shall they wear a rough garment to deceive a rough heb a garment of hair deceive heb lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 5, 'But he shall say, I {am} no prophet, I {am} an husbandman; for man taught me to keep cattle from my youth.', 'but he shall say i am no prophet i am an husbandman for man taught me to keep cattle from my youth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 6, 'And {one} shall say unto him, What {are} these wounds in thine hands? Then he shall answer, {Those} with which I was wounded {in} the house of my friends.', 'and one shall say unto him what are these wounds in thine hands then he shall answer those with which i was wounded in the house of my friends');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 7, 'Awake, O sword, against my shepherd, and against the man {that is} my fellow, saith the LORD of hosts: smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones.', 'awake o sword against my shepherd and against the man that is my fellow saith the lord of hosts smite the shepherd and the sheep shall be scattered and i will turn mine hand upon the little ones');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 8, 'And it shall come to pass, {that} in all the land, saith the LORD, two parts therein shall be cut off {and} die; but the third shall be left therein.', 'and it shall come to pass that in all the land saith the lord two parts therein shall be cut off and die but the third shall be left therein');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 13, 9, 'And I will bring the third part through the fire, and will refine them as silver is refined, and will try them as gold is tried: they shall call on my name, and I will hear them: I will say, It {is} my people: and they shall say, The LORD {is} my God.', 'and i will bring the third part through the fire and will refine them as silver is refined and will try them as gold is tried they shall call on my name and i will hear them i will say it is my people and they shall say the lord is my god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 14, 1, 'Behold, the day of the LORD cometh, and thy spoil shall be divided in the midst of thee.', 'behold the day of the lord cometh and thy spoil shall be divided in the midst of thee');
