INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 14, 4, 'And his feet shall stand in that day upon the mount of Olives, which {is} before Jerusalem on the east, and the mount of Olives shall cleave in the midst thereof toward the east and toward the west, {and there shall be} a very great valley; and half of the mountain shall remove toward the north, and half of it toward the south.', 'and his feet shall stand in that day upon the mount of olives which is before jerusalem on the east and the mount of olives shall cleave in the midst thereof toward the east and toward the west and there shall be a very great valley and half of the mountain shall remove toward the north and half of it toward the south');
