INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 14, 6, 'And it shall come to pass in that day, {that} the light shall not be clear, {nor} dark: {that the...: that is, it shall not be clear in some places, and dark in other places of the world} {clear: Heb. precious} {dark: Heb. thickness}', 'and it shall come to pass in that day that the light shall not be clear nor dark that the that is it shall not be clear in some places and dark in other places of the world clear heb precious dark heb thickness');
