INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 38, 'Unknown', 14, 9, 'And the LORD shall be king over all the earth: in that day shall there be one LORD, and his name one.', 'and the lord shall be king over all the earth in that day shall there be one lord and his name one');
