INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 39, 'Unknown', 1, 1, 'The burden of the word of the LORD to Israel by Malachi. {by...: Heb. by the hand of}', 'the burden of the word of the lord to israel by malachi by heb by the hand of');
