INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 5, 16, 'Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven.', 'let your light so shine before men that they may see your good works and glorify your father which is in heaven');
