INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 5, 18, 'For verily I say unto you, Till heaven and earth pass, one jot or one tittle shall in no wise pass from the law, till all be fulfilled.', 'for verily i say unto you till heaven and earth pass one jot or one tittle shall in no wise pass from the law till all be fulfilled');
