INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 12, 25, 'And Jesus knew their thoughts, and said unto them, Every kingdom divided against itself is brought to desolation; and every city or house divided against itself shall not stand:', 'and jesus knew their thoughts and said unto them every kingdom divided against itself is brought to desolation and every city or house divided against itself shall not stand');
