INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 5, 'Some fell upon stony places, where they had not much earth: and forthwith they sprung up, because they had no deepness of earth:', 'some fell upon stony places where they had not much earth and forthwith they sprung up because they had no deepness of earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 6, 'And when the sun was up, they were scorched; and because they had no root, they withered away.', 'and when the sun was up they were scorched and because they had no root they withered away');
