INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 8, 'But other fell into good ground, and brought forth fruit, some an hundredfold, some sixtyfold, some thirtyfold.', 'but other fell into good ground and brought forth fruit some an hundredfold some sixtyfold some thirtyfold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 9, 'Who hath ears to hear, let him hear.', 'who hath ears to hear let him hear');
