INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 11, 'He answered and said unto them, Because it is given unto you to know the mysteries of the kingdom of heaven, but to them it is not given.', 'he answered and said unto them because it is given unto you to know the mysteries of the kingdom of heaven but to them it is not given');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 12, 'For whosoever hath, to him shall be given, and he shall have more abundance: but whosoever hath not, from him shall be taken away even that he hath.', 'for whosoever hath to him shall be given and he shall have more abundance but whosoever hath not from him shall be taken away even that he hath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 13, 'Therefore speak I to them in parables: because they seeing see not; and hearing they hear not, neither do they understand.', 'therefore speak i to them in parables because they seeing see not and hearing they hear not neither do they understand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 14, 'And in them is fulfilled the prophecy of Esaias, which saith, By hearing ye shall hear, and shall not understand; and seeing ye shall see, and shall not perceive:', 'and in them is fulfilled the prophecy of esaias which saith by hearing ye shall hear and shall not understand and seeing ye shall see and shall not perceive');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 15, 'For this people''s heart is waxed gross, and {their} ears are dull of hearing, and their eyes they have closed; lest at any time they should see with {their} eyes, and hear with {their} ears, and should understand with {their} heart, and should be converted, and I should heal them.', 'for this people s heart is waxed gross and their ears are dull of hearing and their eyes they have closed lest at any time they should see with their eyes and hear with their ears and should understand with their heart and should be converted and i should heal them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 16, 'But blessed {are} your eyes, for they see: and your ears, for they hear.', 'but blessed are your eyes for they see and your ears for they hear');
