INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 18, 'Hear ye therefore the parable of the sower.', 'hear ye therefore the parable of the sower');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 19, 'When any one heareth the word of the kingdom, and understandeth {it} not, then cometh the wicked {one}, and catcheth away that which was sown in his heart. This is he which received seed by the way side.', 'when any one heareth the word of the kingdom and understandeth it not then cometh the wicked one and catcheth away that which was sown in his heart this is he which received seed by the way side');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 20, 'But he that received the seed into stony places, the same is he that heareth the word, and anon with joy receiveth it;', 'but he that received the seed into stony places the same is he that heareth the word and anon with joy receiveth it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 21, 'Yet hath he not root in himself, but dureth for a while: for when tribulation or persecution ariseth because of the word, by and by he is offended. {offended: he relapseth, or, falleth into sin}', 'yet hath he not root in himself but dureth for a while for when tribulation or persecution ariseth because of the word by and by he is offended offended he relapseth or falleth into sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 22, 'He also that received seed among the thorns is he that heareth the word; and the care of this world, and the deceitfulness of riches, choke the word, and he becometh unfruitful.', 'he also that received seed among the thorns is he that heareth the word and the care of this world and the deceitfulness of riches choke the word and he becometh unfruitful');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 23, 'But he that received seed into the good ground is he that heareth the word, and understandeth {it}; which also beareth fruit, and bringeth forth, some an hundredfold, some sixty, some thirty.', 'but he that received seed into the good ground is he that heareth the word and understandeth it which also beareth fruit and bringeth forth some an hundredfold some sixty some thirty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 24, 'Another parable put he forth unto them, saying, The kingdom of heaven is likened unto a man which sowed good seed in his field:', 'another parable put he forth unto them saying the kingdom of heaven is likened unto a man which sowed good seed in his field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 25, 'But while men slept, his enemy came and sowed tares among the wheat, and went his way.', 'but while men slept his enemy came and sowed tares among the wheat and went his way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 26, 'But when the blade was sprung up, and brought forth fruit, then appeared the tares also.', 'but when the blade was sprung up and brought forth fruit then appeared the tares also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 27, 'So the servants of the householder came and said unto him, Sir, didst not thou sow good seed in thy field? from whence then hath it tares?', 'so the servants of the householder came and said unto him sir didst not thou sow good seed in thy field from whence then hath it tares');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 28, 'He said unto them, An enemy hath done this. The servants said unto him, Wilt thou then that we go and gather them up?', 'he said unto them an enemy hath done this the servants said unto him wilt thou then that we go and gather them up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 29, 'But he said, Nay; lest while ye gather up the tares, ye root up also the wheat with them.', 'but he said nay lest while ye gather up the tares ye root up also the wheat with them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 30, 'Let both grow together until the harvest: and in the time of harvest I will say to the reapers, Gather ye together first the tares, and bind them in bundles to burn them: but gather the wheat into my barn.', 'let both grow together until the harvest and in the time of harvest i will say to the reapers gather ye together first the tares and bind them in bundles to burn them but gather the wheat into my barn');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 31, 'Another parable put he forth unto them, saying, The kingdom of heaven is like to a grain of mustard seed, which a man took, and sowed in his field:', 'another parable put he forth unto them saying the kingdom of heaven is like to a grain of mustard seed which a man took and sowed in his field');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 32, 'Which indeed is the least of all seeds: but when it is grown, it is the greatest among herbs, and becometh a tree, so that the birds of the air come and lodge in the branches thereof.', 'which indeed is the least of all seeds but when it is grown it is the greatest among herbs and becometh a tree so that the birds of the air come and lodge in the branches thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 33, 'Another parable spake he unto them; The kingdom of heaven is like unto leaven, which a woman took, and hid in three measures of meal, till the whole was leavened. {measures: the word in the Greek is a measure containing about a peck and a half, wanting a little more than a pint}', 'another parable spake he unto them the kingdom of heaven is like unto leaven which a woman took and hid in three measures of meal till the whole was leavened measures the word in the greek is a measure containing about a peck and a half wanting a little more than a pint');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 34, 'All these things spake Jesus unto the multitude in parables; and without a parable spake he not unto them:', 'all these things spake jesus unto the multitude in parables and without a parable spake he not unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 35, 'That it might be fulfilled which was spoken by the prophet, saying, I will open my mouth in parables; I will utter things which have been kept secret from the foundation of the world.', 'that it might be fulfilled which was spoken by the prophet saying i will open my mouth in parables i will utter things which have been kept secret from the foundation of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 36, 'Then Jesus sent the multitude away, and went into the house: and his disciples came unto him, saying, Declare unto us the parable of the tares of the field.', 'then jesus sent the multitude away and went into the house and his disciples came unto him saying declare unto us the parable of the tares of the field');
