INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 13, 41, 'The Son of man shall send forth his angels, and they shall gather out of his kingdom all things that offend, and them which do iniquity; {things...: or, scandals}', 'the son of man shall send forth his angels and they shall gather out of his kingdom all things that offend and them which do iniquity things or scandals');
