INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 14, 36, 'And besought him that they might only touch the hem of his garment: and as many as touched were made perfectly whole.', 'and besought him that they might only touch the hem of his garment and as many as touched were made perfectly whole');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 1, 'Then came to Jesus scribes and Pharisees, which were of Jerusalem, saying,', 'then came to jesus scribes and pharisees which were of jerusalem saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 2, 'Why do thy disciples transgress the tradition of the elders? for they wash not their hands when they eat bread.', 'why do thy disciples transgress the tradition of the elders for they wash not their hands when they eat bread');
