INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 4, 'For God commanded, saying, Honour thy father and mother: and, He that curseth father or mother, let him die the death.', 'for god commanded saying honour thy father and mother and he that curseth father or mother let him die the death');
