INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 18, 'But those things which proceed out of the mouth come forth from the heart; and they defile the man.', 'but those things which proceed out of the mouth come forth from the heart and they defile the man');
