INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 20, 'These are {the things} which defile a man: but to eat with unwashen hands defileth not a man.', 'these are the things which defile a man but to eat with unwashen hands defileth not a man');
