INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 23, 'But he answered her not a word. And his disciples came and besought him, saying, Send her away; for she crieth after us.', 'but he answered her not a word and his disciples came and besought him saying send her away for she crieth after us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 24, 'But he answered and said, I am not sent but unto the lost sheep of the house of Israel.', 'but he answered and said i am not sent but unto the lost sheep of the house of israel');
