INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 26, 'But he answered and said, It is not meet to take the children''s bread, and to cast {it} to dogs.', 'but he answered and said it is not meet to take the children s bread and to cast it to dogs');
