INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 30, 'And great multitudes came unto him, having with them {those that were} lame, blind, dumb, maimed, and many others, and cast them down at Jesus'' feet; and he healed them:', 'and great multitudes came unto him having with them those that were lame blind dumb maimed and many others and cast them down at jesus feet and he healed them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 15, 31, 'Insomuch that the multitude wondered, when they saw the dumb to speak, the maimed to be whole, the lame to walk, and the blind to see: and they glorified the God of Israel.', 'insomuch that the multitude wondered when they saw the dumb to speak the maimed to be whole the lame to walk and the blind to see and they glorified the god of israel');
