INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 16, 4, 'A wicked and adulterous generation seeketh after a sign; and there shall no sign be given unto it, but the sign of the prophet Jonas. And he left them, and departed.', 'a wicked and adulterous generation seeketh after a sign and there shall no sign be given unto it but the sign of the prophet jonas and he left them and departed');
