INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 16, 17, 'And Jesus answered and said unto him, Blessed art thou, Simon Barjona: for flesh and blood hath not revealed {it} unto thee, but my Father which is in heaven.', 'and jesus answered and said unto him blessed art thou simon barjona for flesh and blood hath not revealed it unto thee but my father which is in heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 16, 18, 'And I say also unto thee, That thou art Peter, and upon this rock I will build my church; and the gates of hell shall not prevail against it. {Peter: this name signifies a rock}', 'and i say also unto thee that thou art peter and upon this rock i will build my church and the gates of hell shall not prevail against it peter this name signifies a rock');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 16, 19, 'And I will give unto thee the keys of the kingdom of heaven: and whatsoever thou shalt bind on earth shall be bound in heaven: and whatsoever thou shalt loose on earth shall be loosed in heaven.', 'and i will give unto thee the keys of the kingdom of heaven and whatsoever thou shalt bind on earth shall be bound in heaven and whatsoever thou shalt loose on earth shall be loosed in heaven');
