INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 6, 'But whoso shall offend one of these little ones which believe in me, it were better for him that a millstone were hanged about his neck, and {that} he were drowned in the depth of the sea.', 'but whoso shall offend one of these little ones which believe in me it were better for him that a millstone were hanged about his neck and that he were drowned in the depth of the sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 7, 'Woe unto the world because of offences! for it must needs be that offences come; but woe to that man by whom the offence cometh!', 'woe unto the world because of offences for it must needs be that offences come but woe to that man by whom the offence cometh');
