INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 9, 'And if thine eye offend thee, pluck it out, and cast {it} from thee: it is better for thee to enter into life with one eye, rather than having two eyes to be cast into hell fire.', 'and if thine eye offend thee pluck it out and cast it from thee it is better for thee to enter into life with one eye rather than having two eyes to be cast into hell fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 10, 'Take heed that ye despise not one of these little ones; for I say unto you, That in heaven their angels do always behold the face of my Father which is in heaven.', 'take heed that ye despise not one of these little ones for i say unto you that in heaven their angels do always behold the face of my father which is in heaven');
