INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 24, 'And when he had begun to reckon, one was brought unto him, which owed him ten thousand talents. {talents: a talent is seven hundred and fifty ounces of silver, which after five shillings the ounce is pounds shillings}', 'and when he had begun to reckon one was brought unto him which owed him ten thousand talents talents a talent is seven hundred and fifty ounces of silver which after five shillings the ounce is pounds shillings');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 25, 'But forasmuch as he had not to pay, his lord commanded him to be sold, and his wife, and children, and all that he had, and payment to be made.', 'but forasmuch as he had not to pay his lord commanded him to be sold and his wife and children and all that he had and payment to be made');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 26, 'The servant therefore fell down, and worshipped him, saying, Lord, have patience with me, and I will pay thee all. {worshipped him: or, besought him}', 'the servant therefore fell down and worshipped him saying lord have patience with me and i will pay thee all worshipped him or besought him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 27, 'Then the lord of that servant was moved with compassion, and loosed him, and forgave him the debt.', 'then the lord of that servant was moved with compassion and loosed him and forgave him the debt');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 28, 'But the same servant went out, and found one of his fellowservants, which owed him an hundred pence: and he laid hands on him, and took {him} by the throat, saying, Pay me that thou owest. {pence: the Roman penny is the eighth part of an ounce, which after five shillings the ounce is seven pence halfpenny; about fourteen cents}', 'but the same servant went out and found one of his fellowservants which owed him an hundred pence and he laid hands on him and took him by the throat saying pay me that thou owest pence the roman penny is the eighth part of an ounce which after five shillings the ounce is seven pence halfpenny about fourteen cents');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 18, 29, 'And his fellowservant fell down at his feet, and besought him, saying, Have patience with me, and I will pay thee all.', 'and his fellowservant fell down at his feet and besought him saying have patience with me and i will pay thee all');
