INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 23, 12, 'And whosoever shall exalt himself shall be abased; and he that shall humble himself shall be exalted.', 'and whosoever shall exalt himself shall be abased and he that shall humble himself shall be exalted');
