INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 23, 14, 'Woe unto you, scribes and Pharisees, hypocrites! for ye devour widows'' houses, and for a pretence make long prayer: therefore ye shall receive the greater damnation.', 'woe unto you scribes and pharisees hypocrites for ye devour widows houses and for a pretence make long prayer therefore ye shall receive the greater damnation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 23, 15, 'Woe unto you, scribes and Pharisees, hypocrites! for ye compass sea and land to make one proselyte, and when he is made, ye make him twofold more the child of hell than yourselves.', 'woe unto you scribes and pharisees hypocrites for ye compass sea and land to make one proselyte and when he is made ye make him twofold more the child of hell than yourselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 40, 'Unknown', 23, 16, 'Woe unto you, {ye} blind guides, which say, Whosoever shall swear by the temple, it is nothing; but whosoever shall swear by the gold of the temple, he is a debtor!', 'woe unto you ye blind guides which say whosoever shall swear by the temple it is nothing but whosoever shall swear by the gold of the temple he is a debtor');
