INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 4, 9, 'And he said unto them, He that hath ears to hear, let him hear.', 'and he said unto them he that hath ears to hear let him hear');
