INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 4, 11, 'And he said unto them, Unto you it is given to know the mystery of the kingdom of God: but unto them that are without, all {these} things are done in parables:', 'and he said unto them unto you it is given to know the mystery of the kingdom of god but unto them that are without all these things are done in parables');
