INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 4, 17, 'And have no root in themselves, and so endure but for a time: afterward, when affliction or persecution ariseth for the word''s sake, immediately they are offended. {offended: or, stumbled, or, caused to fall into sin}', 'and have no root in themselves and so endure but for a time afterward when affliction or persecution ariseth for the word s sake immediately they are offended offended or stumbled or caused to fall into sin');
