INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 6, 8, 'And commanded them that they should take nothing for {their} journey, save a staff only; no scrip, no bread, no money in {their} purse: {money: the word signifieth a piece of brass money, in value somewhat less than a farthing, but here it is taken in general for money}', 'and commanded them that they should take nothing for their journey save a staff only no scrip no bread no money in their purse money the word signifieth a piece of brass money in value somewhat less than a farthing but here it is taken in general for money');
