INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 6, 16, 'But when Herod heard {thereof}, he said, It is John, whom I beheaded: he is risen from the dead.', 'but when herod heard thereof he said it is john whom i beheaded he is risen from the dead');
