INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 17, 'And he saith unto them, Are ye so without understanding also? Do ye not perceive, that whatsoever thing from without entereth into the man, {it} cannot defile him;', 'and he saith unto them are ye so without understanding also do ye not perceive that whatsoever thing from without entereth into the man it cannot defile him');
