INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 19, 'And he said, That which cometh out of the man, that defileth the man.', 'and he said that which cometh out of the man that defileth the man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 20, 'For from within, out of the heart of men, proceed evil thoughts, adulteries, fornications, murders,', 'for from within out of the heart of men proceed evil thoughts adulteries fornications murders');
