INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 22, 'All these evil things come from within, and defile the man.', 'all these evil things come from within and defile the man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 23, 'And from thence he arose, and went into the borders of Tyre and Sidon, and entered into an house, and would have no man know {it}: but he could not be hid.', 'and from thence he arose and went into the borders of tyre and sidon and entered into an house and would have no man know it but he could not be hid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 24, 'For a {certain} woman, whose young daughter had an unclean spirit, heard of him, and came and fell at his feet:', 'for a certain woman whose young daughter had an unclean spirit heard of him and came and fell at his feet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 25, 'The woman was a Greek, a Syrophenician by nation; and she besought him that he would cast forth the devil out of her daughter. {Greek: or, Gentile}', 'the woman was a greek a syrophenician by nation and she besought him that he would cast forth the devil out of her daughter greek or gentile');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 26, 'But Jesus said unto her, Let the children first be filled: for it is not meet to take the children''s bread, and to cast {it} unto the dogs.', 'but jesus said unto her let the children first be filled for it is not meet to take the children s bread and to cast it unto the dogs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 27, 'And she answered and said unto him, Yes, Lord: yet the dogs under the table eat of the children''s crumbs.', 'and she answered and said unto him yes lord yet the dogs under the table eat of the children s crumbs');
