INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 29, 'And when she was come to her house, she found the devil gone out, and her daughter laid upon the bed.', 'and when she was come to her house she found the devil gone out and her daughter laid upon the bed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 7, 30, 'And again, departing from the coasts of Tyre and Sidon, he came unto the sea of Galilee, through the midst of the coasts of Decapolis.', 'and again departing from the coasts of tyre and sidon he came unto the sea of galilee through the midst of the coasts of decapolis');
