INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 1, 'In those days the multitude being very great, and having nothing to eat, Jesus called his disciples {unto him}, and saith unto them,', 'in those days the multitude being very great and having nothing to eat jesus called his disciples unto him and saith unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 2, 'I have compassion on the multitude, because they have now been with me three days, and have nothing to eat:', 'i have compassion on the multitude because they have now been with me three days and have nothing to eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 3, 'And if I send them away fasting to their own houses, they will faint by the way: for divers of them came from far.', 'and if i send them away fasting to their own houses they will faint by the way for divers of them came from far');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 4, 'And his disciples answered him, From whence can a man satisfy these {men} with bread here in the wilderness?', 'and his disciples answered him from whence can a man satisfy these men with bread here in the wilderness');
