INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 7, 'And they had a few small fishes: and he blessed, and commanded to set them also before {them}.', 'and they had a few small fishes and he blessed and commanded to set them also before them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 8, 'And they that had eaten were about four thousand: and he sent them away.', 'and they that had eaten were about four thousand and he sent them away');
