INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 25, 'And he sent him away to his house, saying, Neither go into the town, nor tell {it} to any in the town.', 'and he sent him away to his house saying neither go into the town nor tell it to any in the town');
