INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 8, 29, 'And he charged them that they should tell no man of him.', 'and he charged them that they should tell no man of him');
