INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 57, 'And there arose certain, and bare false witness against him, saying,', 'and there arose certain and bare false witness against him saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 58, 'We heard him say, I will destroy this temple that is made with hands, and within three days I will build another made without hands.', 'we heard him say i will destroy this temple that is made with hands and within three days i will build another made without hands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 59, 'But neither so did their witness agree together.', 'but neither so did their witness agree together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 60, 'And the high priest stood up in the midst, and asked Jesus, saying, Answerest thou nothing? what {is it which} these witness against thee?', 'and the high priest stood up in the midst and asked jesus saying answerest thou nothing what is it which these witness against thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 61, 'But he held his peace, and answered nothing. Again the high priest asked him, and said unto him, Art thou the Christ, the Son of the Blessed?', 'but he held his peace and answered nothing again the high priest asked him and said unto him art thou the christ the son of the blessed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 62, 'And Jesus said, I am: and ye shall see the Son of man sitting on the right hand of power, and coming in the clouds of heaven.', 'and jesus said i am and ye shall see the son of man sitting on the right hand of power and coming in the clouds of heaven');
