INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 64, 'Ye have heard the blasphemy: what think ye? And they all condemned him to be guilty of death.', 'ye have heard the blasphemy what think ye and they all condemned him to be guilty of death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 65, 'And some began to spit on him, and to cover his face, and to buffet him, and to say unto him, Prophesy: and the servants did strike him with the palms of their hands.', 'and some began to spit on him and to cover his face and to buffet him and to say unto him prophesy and the servants did strike him with the palms of their hands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 66, 'And as Peter was beneath in the palace, there cometh one of the maids of the high priest:', 'and as peter was beneath in the palace there cometh one of the maids of the high priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 67, 'And when she saw Peter warming himself, she looked upon him, and said, And thou also wast with Jesus of Nazareth.', 'and when she saw peter warming himself she looked upon him and said and thou also wast with jesus of nazareth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 68, 'But he denied, saying, I know not, neither understand I what thou sayest. And he went out into the porch; and the cock crew.', 'but he denied saying i know not neither understand i what thou sayest and he went out into the porch and the cock crew');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 69, 'And a maid saw him again, and began to say to them that stood by, This is {one} of them.', 'and a maid saw him again and began to say to them that stood by this is one of them');
