INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 14, 71, 'But he began to curse and to swear, {saying}, I know not this man of whom ye speak.', 'but he began to curse and to swear saying i know not this man of whom ye speak');
