INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 1, 'And straightway in the morning the chief priests held a consultation with the elders and scribes and the whole council, and bound Jesus, and carried {him} away, and delivered {him} to Pilate.', 'and straightway in the morning the chief priests held a consultation with the elders and scribes and the whole council and bound jesus and carried him away and delivered him to pilate');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 2, 'And Pilate asked him, Art thou the King of the Jews? And he answering said unto him, Thou sayest {it}.', 'and pilate asked him art thou the king of the jews and he answering said unto him thou sayest it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 3, 'And the chief priests accused him of many things: but he answered nothing.', 'and the chief priests accused him of many things but he answered nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 4, 'And Pilate asked him again, saying, Answerest thou nothing? behold how many things they witness against thee.', 'and pilate asked him again saying answerest thou nothing behold how many things they witness against thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 5, 'But Jesus yet answered nothing; so that Pilate marvelled.', 'but jesus yet answered nothing so that pilate marvelled');
