INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 7, 'And there was {one} named Barabbas, {which lay} bound with them that had made insurrection with him, who had committed murder in the insurrection.', 'and there was one named barabbas which lay bound with them that had made insurrection with him who had committed murder in the insurrection');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 8, 'And the multitude crying aloud began to desire {him to do} as he had ever done unto them.', 'and the multitude crying aloud began to desire him to do as he had ever done unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 9, 'But Pilate answered them, saying, Will ye that I release unto you the King of the Jews?', 'but pilate answered them saying will ye that i release unto you the king of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 10, 'For he knew that the chief priests had delivered him for envy.', 'for he knew that the chief priests had delivered him for envy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 11, 'But the chief priests moved the people, that he should rather release Barabbas unto them.', 'but the chief priests moved the people that he should rather release barabbas unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 12, 'And Pilate answered and said again unto them, What will ye then that I shall do {unto him} whom ye call the King of the Jews?', 'and pilate answered and said again unto them what will ye then that i shall do unto him whom ye call the king of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 13, 'And they cried out again, Crucify him.', 'and they cried out again crucify him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 14, 'Then Pilate said unto them, Why, what evil hath he done? And they cried out the more exceedingly, Crucify him.', 'then pilate said unto them why what evil hath he done and they cried out the more exceedingly crucify him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 15, 'And {so} Pilate, willing to content the people, released Barabbas unto them, and delivered Jesus, when he had scourged {him}, to be crucified.', 'and so pilate willing to content the people released barabbas unto them and delivered jesus when he had scourged him to be crucified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 16, 'And the soldiers led him away into the hall, called Praetorium; and they call together the whole band. {Praetorium: or, the palace, or, hall of audience}', 'and the soldiers led him away into the hall called praetorium and they call together the whole band praetorium or the palace or hall of audience');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 17, 'And they clothed him with purple, and platted a crown of thorns, and put it about his {head},', 'and they clothed him with purple and platted a crown of thorns and put it about his head');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 18, 'And began to salute him, Hail, King of the Jews!', 'and began to salute him hail king of the jews');
