INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 20, 'And when they had mocked him, they took off the purple from him, and put his own clothes on him, and led him out to crucify him.', 'and when they had mocked him they took off the purple from him and put his own clothes on him and led him out to crucify him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 21, 'And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross.', 'and they compel one simon a cyrenian who passed by coming out of the country the father of alexander and rufus to bear his cross');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 22, 'And they bring him unto the place Golgotha, which is, being interpreted, The place of a skull.', 'and they bring him unto the place golgotha which is being interpreted the place of a skull');
