INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 27, 'And with him they crucify two thieves; the one on his right hand, and the other on his left.', 'and with him they crucify two thieves the one on his right hand and the other on his left');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 28, 'And the scripture was fulfilled, which saith, And he was numbered with the transgressors.', 'and the scripture was fulfilled which saith and he was numbered with the transgressors');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 29, 'And they that passed by railed on him, wagging their heads, and saying, Ah, thou that destroyest the temple, and buildest {it} in three days,', 'and they that passed by railed on him wagging their heads and saying ah thou that destroyest the temple and buildest it in three days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 30, 'Save thyself, and come down from the cross.', 'save thyself and come down from the cross');
