INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 32, 'Let Christ the King of Israel descend now from the cross, that we may see and believe. And they that were crucified with him reviled him.', 'let christ the king of israel descend now from the cross that we may see and believe and they that were crucified with him reviled him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 33, 'And when the sixth hour was come, there was darkness over the whole land until the ninth hour.', 'and when the sixth hour was come there was darkness over the whole land until the ninth hour');
