INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 35, 'And some of them that stood by, when they heard {it}, said, Behold, he calleth Elias.', 'and some of them that stood by when they heard it said behold he calleth elias');
