INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 37, 'And Jesus cried with a loud voice, and gave up the ghost.', 'and jesus cried with a loud voice and gave up the ghost');
