INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 41, '(Who also, when he was in Galilee, followed him, and ministered unto him;) and many other women which came up with him unto Jerusalem.', 'who also when he was in galilee followed him and ministered unto him and many other women which came up with him unto jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 42, 'And now when the even was come, because it was the preparation, that is, the day before the sabbath,', 'and now when the even was come because it was the preparation that is the day before the sabbath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 43, 'Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus.', 'joseph of arimathaea an honourable counsellor which also waited for the kingdom of god came and went in boldly unto pilate and craved the body of jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 44, 'And Pilate marvelled if he were already dead: and calling {unto him} the centurion, he asked him whether he had been any while dead.', 'and pilate marvelled if he were already dead and calling unto him the centurion he asked him whether he had been any while dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 45, 'And when he knew {it} of the centurion, he gave the body to Joseph.', 'and when he knew it of the centurion he gave the body to joseph');
