INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 15, 47, 'And Mary Magdalene and Mary {the mother} of Joses beheld where he was laid.', 'and mary magdalene and mary the mother of joses beheld where he was laid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 16, 1, 'And when the sabbath was past, Mary Magdalene, and Mary the {mother} of James, and Salome, had bought sweet spices, that they might come and anoint him.', 'and when the sabbath was past mary magdalene and mary the mother of james and salome had bought sweet spices that they might come and anoint him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 16, 2, 'And very early in the morning the first {day} of the week, they came unto the sepulchre at the rising of the sun.', 'and very early in the morning the first day of the week they came unto the sepulchre at the rising of the sun');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 16, 3, 'And they said among themselves, Who shall roll us away the stone from the door of the sepulchre?', 'and they said among themselves who shall roll us away the stone from the door of the sepulchre');
