INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 16, 5, 'And entering into the sepulchre, they saw a young man sitting on the right side, clothed in a long white garment; and they were affrighted.', 'and entering into the sepulchre they saw a young man sitting on the right side clothed in a long white garment and they were affrighted');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 41, 'Unknown', 16, 6, 'And he saith unto them, Be not affrighted: Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here: behold the place where they laid him.', 'and he saith unto them be not affrighted ye seek jesus of nazareth which was crucified he is risen he is not here behold the place where they laid him');
