INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 4, 27, 'And many lepers were in Israel in the time of Eliseus the prophet; and none of them was cleansed, saving Naaman the Syrian.', 'and many lepers were in israel in the time of eliseus the prophet and none of them was cleansed saving naaman the syrian');
