INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 4, 34, 'Saying, Let {us} alone; what have we to do with thee, {thou} Jesus of Nazareth? art thou come to destroy us? I know thee who thou art; the Holy One of God. {Let...: or, Away}', 'saying let us alone what have we to do with thee thou jesus of nazareth art thou come to destroy us i know thee who thou art the holy one of god let or away');
