INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 4, 37, 'And the fame of him went out into every place of the country round about.', 'and the fame of him went out into every place of the country round about');
