INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 4, 39, 'And he stood over her, and rebuked the fever; and it left her: and immediately she arose and ministered unto them.', 'and he stood over her and rebuked the fever and it left her and immediately she arose and ministered unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 4, 40, 'Now when the sun was setting, all they that had any sick with divers diseases brought them unto him; and he laid his hands on every one of them, and healed them.', 'now when the sun was setting all they that had any sick with divers diseases brought them unto him and he laid his hands on every one of them and healed them');
