INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 2, 'And saw two ships standing by the lake: but the fishermen were gone out of them, and were washing {their} nets.', 'and saw two ships standing by the lake but the fishermen were gone out of them and were washing their nets');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 3, 'And he entered into one of the ships, which was Simon''s, and prayed him that he would thrust out a little from the land. And he sat down, and taught the people out of the ship.', 'and he entered into one of the ships which was simon s and prayed him that he would thrust out a little from the land and he sat down and taught the people out of the ship');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 4, 'Now when he had left speaking, he said unto Simon, Launch out into the deep, and let down your nets for a draught.', 'now when he had left speaking he said unto simon launch out into the deep and let down your nets for a draught');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 5, 'And Simon answering said unto him, Master, we have toiled all the night, and have taken nothing: nevertheless at thy word I will let down the net.', 'and simon answering said unto him master we have toiled all the night and have taken nothing nevertheless at thy word i will let down the net');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 6, 'And when they had this done, they inclosed a great multitude of fishes: and their net brake.', 'and when they had this done they inclosed a great multitude of fishes and their net brake');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 7, 'And they beckoned unto {their} partners, which were in the other ship, that they should come and help them. And they came, and filled both the ships, so that they began to sink.', 'and they beckoned unto their partners which were in the other ship that they should come and help them and they came and filled both the ships so that they began to sink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 8, 'When Simon Peter saw {it}, he fell down at Jesus'' knees, saying, Depart from me; for I am a sinful man, O Lord.', 'when simon peter saw it he fell down at jesus knees saying depart from me for i am a sinful man o lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 9, 'For he was astonished, and all that were with him, at the draught of the fishes which they had taken:', 'for he was astonished and all that were with him at the draught of the fishes which they had taken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 10, 'And so {was} also James, and John, the sons of Zebedee, which were partners with Simon. And Jesus said unto Simon, Fear not; from henceforth thou shalt catch men.', 'and so was also james and john the sons of zebedee which were partners with simon and jesus said unto simon fear not from henceforth thou shalt catch men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 11, 'And when they had brought their ships to land, they forsook all, and followed him.', 'and when they had brought their ships to land they forsook all and followed him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 12, 'And it came to pass, when he was in a certain city, behold a man full of leprosy: who seeing Jesus fell on {his} face, and besought him, saying, Lord, if thou wilt, thou canst make me clean.', 'and it came to pass when he was in a certain city behold a man full of leprosy who seeing jesus fell on his face and besought him saying lord if thou wilt thou canst make me clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 13, 'And he put forth {his} hand, and touched him, saying, I will: be thou clean. And immediately the leprosy departed from him.', 'and he put forth his hand and touched him saying i will be thou clean and immediately the leprosy departed from him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 14, 'And he charged him to tell no man: but go, and shew thyself to the priest, and offer for thy cleansing, according as Moses commanded, for a testimony unto them.', 'and he charged him to tell no man but go and shew thyself to the priest and offer for thy cleansing according as moses commanded for a testimony unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 5, 15, 'But so much the more went there a fame abroad of him: and great multitudes came together to hear, and to be healed by him of their infirmities.', 'but so much the more went there a fame abroad of him and great multitudes came together to hear and to be healed by him of their infirmities');
