INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 6, 30, 'Give to every man that asketh of thee; and of him that taketh away thy goods ask {them} not again.', 'give to every man that asketh of thee and of him that taketh away thy goods ask them not again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 6, 31, 'And as ye would that men should do to you, do ye also to them likewise.', 'and as ye would that men should do to you do ye also to them likewise');
