INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 6, 41, 'And why beholdest thou the mote that is in thy brother''s eye, but perceivest not the beam that is in thine own eye?', 'and why beholdest thou the mote that is in thy brother s eye but perceivest not the beam that is in thine own eye');
