INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 6, 43, 'For a good tree bringeth not forth corrupt fruit; neither doth a corrupt tree bring forth good fruit.', 'for a good tree bringeth not forth corrupt fruit neither doth a corrupt tree bring forth good fruit');
