INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 13, 'They on the rock {are they}, which, when they hear, receive the word with joy; and these have no root, which for a while believe, and in time of temptation fall away.', 'they on the rock are they which when they hear receive the word with joy and these have no root which for a while believe and in time of temptation fall away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 14, 'And that which fell among thorns are they, which, when they have heard, go forth, and are choked with cares and riches and pleasures of {this} life, and bring no fruit to perfection.', 'and that which fell among thorns are they which when they have heard go forth and are choked with cares and riches and pleasures of this life and bring no fruit to perfection');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 15, 'But that on the good ground are they, which in an honest and good heart, having heard the word, keep {it}, and bring forth fruit with patience.', 'but that on the good ground are they which in an honest and good heart having heard the word keep it and bring forth fruit with patience');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 16, 'No man, when he hath lighted a candle, covereth it with a vessel, or putteth {it} under a bed; but setteth {it} on a candlestick, that they which enter in may see the light.', 'no man when he hath lighted a candle covereth it with a vessel or putteth it under a bed but setteth it on a candlestick that they which enter in may see the light');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 17, 'For nothing is secret, that shall not be made manifest; neither {any thing} hid, that shall not be known and come abroad.', 'for nothing is secret that shall not be made manifest neither any thing hid that shall not be known and come abroad');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 18, 'Take heed therefore how ye hear: for whosoever hath, to him shall be given; and whosoever hath not, from him shall be taken even that which he seemeth to have. {seemeth...: or, thinketh that he hath}', 'take heed therefore how ye hear for whosoever hath to him shall be given and whosoever hath not from him shall be taken even that which he seemeth to have seemeth or thinketh that he hath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 19, 'Then came to him {his} mother and his brethren, and could not come at him for the press.', 'then came to him his mother and his brethren and could not come at him for the press');
