INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 26, 'And they arrived at the country of the Gadarenes, which is over against Galilee.', 'and they arrived at the country of the gadarenes which is over against galilee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 27, 'And when he went forth to land, there met him out of the city a certain man, which had devils long time, and ware no clothes, neither abode in {any} house, but in the tombs.', 'and when he went forth to land there met him out of the city a certain man which had devils long time and ware no clothes neither abode in any house but in the tombs');
