INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 29, '(For he had commanded the unclean spirit to come out of the man. For oftentimes it had caught him: and he was kept bound with chains and in fetters; and he brake the bands, and was driven of the devil into the wilderness.)', 'for he had commanded the unclean spirit to come out of the man for oftentimes it had caught him and he was kept bound with chains and in fetters and he brake the bands and was driven of the devil into the wilderness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 30, 'And Jesus asked him, saying, What is thy name? And he said, Legion: because many devils were entered into him.', 'and jesus asked him saying what is thy name and he said legion because many devils were entered into him');
