INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 32, 'And there was there an herd of many swine feeding on the mountain: and they besought him that he would suffer them to enter into them. And he suffered them.', 'and there was there an herd of many swine feeding on the mountain and they besought him that he would suffer them to enter into them and he suffered them');
