INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 34, 'When they that fed {them} saw what was done, they fled, and went and told {it} in the city and in the country.', 'when they that fed them saw what was done they fled and went and told it in the city and in the country');
