INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 8, 36, 'They also which saw {it} told them by what means he that was possessed of the devils was healed.', 'they also which saw it told them by what means he that was possessed of the devils was healed');
