INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 14, 8, 'When thou art bidden of any {man} to a wedding, sit not down in the highest room; lest a more honourable man than thou be bidden of him;', 'when thou art bidden of any man to a wedding sit not down in the highest room lest a more honourable man than thou be bidden of him');
