INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 14, 10, 'But when thou art bidden, go and sit down in the lowest room; that when he that bade thee cometh, he may say unto thee, Friend, go up higher: then shalt thou have worship in the presence of them that sit at meat with thee.', 'but when thou art bidden go and sit down in the lowest room that when he that bade thee cometh he may say unto thee friend go up higher then shalt thou have worship in the presence of them that sit at meat with thee');
