INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 14, 14, 'And thou shalt be blessed; for they cannot recompense thee: for thou shalt be recompensed at the resurrection of the just.', 'and thou shalt be blessed for they cannot recompense thee for thou shalt be recompensed at the resurrection of the just');
