INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 15, 9, 'And when she hath found {it}, she calleth {her} friends and {her} neighbours together, saying, Rejoice with me; for I have found the piece which I had lost.', 'and when she hath found it she calleth her friends and her neighbours together saying rejoice with me for i have found the piece which i had lost');
