INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 15, 13, 'And not many days after the younger son gathered all together, and took his journey into a far country, and there wasted his substance with riotous living.', 'and not many days after the younger son gathered all together and took his journey into a far country and there wasted his substance with riotous living');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 15, 14, 'And when he had spent all, there arose a mighty famine in that land; and he began to be in want.', 'and when he had spent all there arose a mighty famine in that land and he began to be in want');
