INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 15, 19, 'And am no more worthy to be called thy son: make me as one of thy hired servants.', 'and am no more worthy to be called thy son make me as one of thy hired servants');
