INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 15, 22, 'But the father said to his servants, Bring forth the best robe, and put {it} on him; and put a ring on his hand, and shoes on {his} feet:', 'but the father said to his servants bring forth the best robe and put it on him and put a ring on his hand and shoes on his feet');
