INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 20, 9, 'Then began he to speak to the people this parable; A certain man planted a vineyard, and let it forth to husbandmen, and went into a far country for a long time.', 'then began he to speak to the people this parable a certain man planted a vineyard and let it forth to husbandmen and went into a far country for a long time');
