INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 20, 11, 'And again he sent another servant: and they beat him also, and entreated {him} shamefully, and sent {him} away empty.', 'and again he sent another servant and they beat him also and entreated him shamefully and sent him away empty');
