INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 20, 13, 'Then said the lord of the vineyard, What shall I do? I will send my beloved son: it may be they will reverence {him} when they see him.', 'then said the lord of the vineyard what shall i do i will send my beloved son it may be they will reverence him when they see him');
