INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 42, 'Unknown', 20, 17, 'And he beheld them, and said, What is this then that is written, The stone which the builders rejected, the same is become the head of the corner?', 'and he beheld them and said what is this then that is written the stone which the builders rejected the same is become the head of the corner');
