INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 16, 'And of his fulness have all we received, and grace for grace.', 'and of his fulness have all we received and grace for grace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 17, 'For the law was given by Moses, {but} grace and truth came by Jesus Christ.', 'for the law was given by moses but grace and truth came by jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 18, 'No man hath seen God at any time; the only begotten Son, which is in the bosom of the Father, he hath declared {him}.', 'no man hath seen god at any time the only begotten son which is in the bosom of the father he hath declared him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 19, 'And this is the record of John, when the Jews sent priests and Levites from Jerusalem to ask him, Who art thou?', 'and this is the record of john when the jews sent priests and levites from jerusalem to ask him who art thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 20, 'And he confessed, and denied not; but confessed, I am not the Christ.', 'and he confessed and denied not but confessed i am not the christ');
