INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 22, 'Then said they unto him, Who art thou? that we may give an answer to them that sent us. What sayest thou of thyself?', 'then said they unto him who art thou that we may give an answer to them that sent us what sayest thou of thyself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 23, 'He said, I {am} the voice of one crying in the wilderness, Make straight the way of the Lord, as said the prophet Esaias.', 'he said i am the voice of one crying in the wilderness make straight the way of the lord as said the prophet esaias');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 24, 'And they which were sent were of the Pharisees.', 'and they which were sent were of the pharisees');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 25, 'And they asked him, and said unto him, Why baptizest thou then, if thou be not that Christ, nor Elias, neither that prophet?', 'and they asked him and said unto him why baptizest thou then if thou be not that christ nor elias neither that prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 26, 'John answered them, saying, I baptize with water: but there standeth one among you, whom ye know not;', 'john answered them saying i baptize with water but there standeth one among you whom ye know not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 27, 'He it is, who coming after me is preferred before me, whose shoe''s latchet I am not worthy to unloose.', 'he it is who coming after me is preferred before me whose shoe s latchet i am not worthy to unloose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 28, 'These things were done in Bethabara beyond Jordan, where John was baptizing.', 'these things were done in bethabara beyond jordan where john was baptizing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 29, 'The next day John seeth Jesus coming unto him, and saith, Behold the Lamb of God, which taketh away the sin of the world. {taketh away: or, beareth}', 'the next day john seeth jesus coming unto him and saith behold the lamb of god which taketh away the sin of the world taketh away or beareth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 30, 'This is he of whom I said, After me cometh a man which is preferred before me: for he was before me.', 'this is he of whom i said after me cometh a man which is preferred before me for he was before me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 31, 'And I knew him not: but that he should be made manifest to Israel, therefore am I come baptizing with water.', 'and i knew him not but that he should be made manifest to israel therefore am i come baptizing with water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 32, 'And John bare record, saying, I saw the Spirit descending from heaven like a dove, and it abode upon him.', 'and john bare record saying i saw the spirit descending from heaven like a dove and it abode upon him');
