INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 34, 'And I saw, and bare record that this is the Son of God.', 'and i saw and bare record that this is the son of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 35, 'Again the next day after John stood, and two of his disciples;', 'again the next day after john stood and two of his disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 36, 'And looking upon Jesus as he walked, he saith, Behold the Lamb of God!', 'and looking upon jesus as he walked he saith behold the lamb of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 37, 'And the two disciples heard him speak, and they followed Jesus.', 'and the two disciples heard him speak and they followed jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 38, 'Then Jesus turned, and saw them following, and saith unto them, What seek ye? They said unto him, Rabbi, (which is to say, being interpreted, Master,) where dwellest thou? {dwellest: or, abidest}', 'then jesus turned and saw them following and saith unto them what seek ye they said unto him rabbi which is to say being interpreted master where dwellest thou dwellest or abidest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 39, 'He saith unto them, Come and see. They came and saw where he dwelt, and abode with him that day: for it was about the tenth hour. {about...: that was two hours before night}', 'he saith unto them come and see they came and saw where he dwelt and abode with him that day for it was about the tenth hour about that was two hours before night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 40, 'One of the two which heard John {speak}, and followed him, was Andrew, Simon Peter''s brother.', 'one of the two which heard john speak and followed him was andrew simon peter s brother');
