INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 42, 'And he brought him to Jesus. And when Jesus beheld him, he said, Thou art Simon the son of Jona: thou shalt be called Cephas, which is by interpretation, A stone.', 'and he brought him to jesus and when jesus beheld him he said thou art simon the son of jona thou shalt be called cephas which is by interpretation a stone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 43, 'The day following Jesus would go forth into Galilee, and findeth Philip, and saith unto him, Follow me.', 'the day following jesus would go forth into galilee and findeth philip and saith unto him follow me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 44, 'Now Philip was of Bethsaida, the city of Andrew and Peter.', 'now philip was of bethsaida the city of andrew and peter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 45, 'Philip findeth Nathanael, and saith unto him, We have found him, of whom Moses in the law, and the prophets, did write, Jesus of Nazareth, the son of Joseph.', 'philip findeth nathanael and saith unto him we have found him of whom moses in the law and the prophets did write jesus of nazareth the son of joseph');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 46, 'And Nathanael said unto him, Can there any good thing come out of Nazareth? Philip saith unto him, Come and see.', 'and nathanael said unto him can there any good thing come out of nazareth philip saith unto him come and see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 47, 'Jesus saw Nathanael coming to him, and saith of him, Behold an Israelite indeed, in whom is no guile!', 'jesus saw nathanael coming to him and saith of him behold an israelite indeed in whom is no guile');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 48, 'Nathanael saith unto him, Whence knowest thou me? Jesus answered and said unto him, Before that Philip called thee, when thou wast under the fig tree, I saw thee.', 'nathanael saith unto him whence knowest thou me jesus answered and said unto him before that philip called thee when thou wast under the fig tree i saw thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 49, 'Nathanael answered and saith unto him, Rabbi, thou art the Son of God; thou art the King of Israel.', 'nathanael answered and saith unto him rabbi thou art the son of god thou art the king of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 50, 'Jesus answered and said unto him, Because I said unto thee, I saw thee under the fig tree, believest thou? thou shalt see greater things than these.', 'jesus answered and said unto him because i said unto thee i saw thee under the fig tree believest thou thou shalt see greater things than these');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 1, 51, 'And he saith unto him, Verily, verily, I say unto you, Hereafter ye shall see heaven open, and the angels of God ascending and descending upon the Son of man.', 'and he saith unto him verily verily i say unto you hereafter ye shall see heaven open and the angels of god ascending and descending upon the son of man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 1, 'And the third day there was a marriage in Cana of Galilee; and the mother of Jesus was there:', 'and the third day there was a marriage in cana of galilee and the mother of jesus was there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 2, 'And both Jesus was called, and his disciples, to the marriage.', 'and both jesus was called and his disciples to the marriage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 3, 'And when they wanted wine, the mother of Jesus saith unto him, They have no wine.', 'and when they wanted wine the mother of jesus saith unto him they have no wine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 4, 'Jesus saith unto her, Woman, what have I to do with thee? mine hour is not yet come.', 'jesus saith unto her woman what have i to do with thee mine hour is not yet come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 5, 'His mother saith unto the servants, Whatsoever he saith unto you, do {it}.', 'his mother saith unto the servants whatsoever he saith unto you do it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 6, 'And there were set there six waterpots of stone, after the manner of the purifying of the Jews, containing two or three firkins apiece.', 'and there were set there six waterpots of stone after the manner of the purifying of the jews containing two or three firkins apiece');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 7, 'Jesus saith unto them, Fill the waterpots with water. And they filled them up to the brim.', 'jesus saith unto them fill the waterpots with water and they filled them up to the brim');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 8, 'And he saith unto them, Draw out now, and bear unto the governor of the feast. And they bare {it}.', 'and he saith unto them draw out now and bear unto the governor of the feast and they bare it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 9, 'When the ruler of the feast had tasted the water that was made wine, and knew not whence it was: (but the servants which drew the water knew;) the governor of the feast called the bridegroom,', 'when the ruler of the feast had tasted the water that was made wine and knew not whence it was but the servants which drew the water knew the governor of the feast called the bridegroom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 10, 'And saith unto him, Every man at the beginning doth set forth good wine; and when men have well drunk, then that which is worse: {but} thou hast kept the good wine until now.', 'and saith unto him every man at the beginning doth set forth good wine and when men have well drunk then that which is worse but thou hast kept the good wine until now');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 11, 'This beginning of miracles did Jesus in Cana of Galilee, and manifested forth his glory; and his disciples believed on him.', 'this beginning of miracles did jesus in cana of galilee and manifested forth his glory and his disciples believed on him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 12, 'After this he went down to Capernaum, he, and his mother, and his brethren, and his disciples: and they continued there not many days.', 'after this he went down to capernaum he and his mother and his brethren and his disciples and they continued there not many days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 13, 'And the Jews'' passover was at hand, and Jesus went up to Jerusalem,', 'and the jews passover was at hand and jesus went up to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 14, 'And found in the temple those that sold oxen and sheep and doves, and the changers of money sitting:', 'and found in the temple those that sold oxen and sheep and doves and the changers of money sitting');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 15, 'And when he had made a scourge of small cords, he drove them all out of the temple, and the sheep, and the oxen; and poured out the changers'' money, and overthrew the tables;', 'and when he had made a scourge of small cords he drove them all out of the temple and the sheep and the oxen and poured out the changers money and overthrew the tables');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 16, 'And said unto them that sold doves, Take these things hence; make not my Father''s house an house of merchandise.', 'and said unto them that sold doves take these things hence make not my father s house an house of merchandise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 17, 'And his disciples remembered that it was written, The zeal of thine house hath eaten me up.', 'and his disciples remembered that it was written the zeal of thine house hath eaten me up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 18, 'Then answered the Jews and said unto him, What sign shewest thou unto us, seeing that thou doest these things?', 'then answered the jews and said unto him what sign shewest thou unto us seeing that thou doest these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 19, 'Jesus answered and said unto them, Destroy this temple, and in three days I will raise it up.', 'jesus answered and said unto them destroy this temple and in three days i will raise it up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 20, 'Then said the Jews, Forty and six years was this temple in building, and wilt thou rear it up in three days?', 'then said the jews forty and six years was this temple in building and wilt thou rear it up in three days');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 21, 'But he spake of the temple of his body.', 'but he spake of the temple of his body');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 22, 'When therefore he was risen from the dead, his disciples remembered that he had said this unto them; and they believed the scripture, and the word which Jesus had said.', 'when therefore he was risen from the dead his disciples remembered that he had said this unto them and they believed the scripture and the word which jesus had said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 23, 'Now when he was in Jerusalem at the passover, in the feast {day}, many believed in his name, when they saw the miracles which he did.', 'now when he was in jerusalem at the passover in the feast day many believed in his name when they saw the miracles which he did');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 24, 'But Jesus did not commit himself unto them, because he knew all {men},', 'but jesus did not commit himself unto them because he knew all men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 2, 25, 'And needed not that any should testify of man: for he knew what was in man.', 'and needed not that any should testify of man for he knew what was in man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 1, 'There was a man of the Pharisees, named Nicodemus, a ruler of the Jews:', 'there was a man of the pharisees named nicodemus a ruler of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 2, 'The same came to Jesus by night, and said unto him, Rabbi, we know that thou art a teacher come from God: for no man can do these miracles that thou doest, except God be with him.', 'the same came to jesus by night and said unto him rabbi we know that thou art a teacher come from god for no man can do these miracles that thou doest except god be with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 3, 'Jesus answered and said unto him, Verily, verily, I say unto thee, Except a man be born again, he cannot see the kingdom of God. {again: or, from above}', 'jesus answered and said unto him verily verily i say unto thee except a man be born again he cannot see the kingdom of god again or from above');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 4, 'Nicodemus saith unto him, How can a man be born when he is old? can he enter the second time into his mother''s womb, and be born?', 'nicodemus saith unto him how can a man be born when he is old can he enter the second time into his mother s womb and be born');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 5, 'Jesus answered, Verily, verily, I say unto thee, Except a man be born of water and {of} the Spirit, he cannot enter into the kingdom of God.', 'jesus answered verily verily i say unto thee except a man be born of water and of the spirit he cannot enter into the kingdom of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 6, 'That which is born of the flesh is flesh; and that which is born of the Spirit is spirit.', 'that which is born of the flesh is flesh and that which is born of the spirit is spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 7, 'Marvel not that I said unto thee, Ye must be born again. {again: or, from above}', 'marvel not that i said unto thee ye must be born again again or from above');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 8, 'The wind bloweth where it listeth, and thou hearest the sound thereof, but canst not tell whence it cometh, and whither it goeth: so is every one that is born of the Spirit.', 'the wind bloweth where it listeth and thou hearest the sound thereof but canst not tell whence it cometh and whither it goeth so is every one that is born of the spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 9, 'Nicodemus answered and said unto him, How can these things be?', 'nicodemus answered and said unto him how can these things be');
