INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 13, 'And no man hath ascended up to heaven, but he that came down from heaven, {even} the Son of man which is in heaven.', 'and no man hath ascended up to heaven but he that came down from heaven even the son of man which is in heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 14, 'And as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up:', 'and as moses lifted up the serpent in the wilderness even so must the son of man be lifted up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 15, 'That whosoever believeth in him should not perish, but have eternal life.', 'that whosoever believeth in him should not perish but have eternal life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 16, 'For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life.', 'for god so loved the world that he gave his only begotten son that whosoever believeth in him should not perish but have everlasting life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 17, 'For God sent not his Son into the world to condemn the world; but that the world through him might be saved.', 'for god sent not his son into the world to condemn the world but that the world through him might be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 18, 'He that believeth on him is not condemned: but he that believeth not is condemned already, because he hath not believed in the name of the only begotten Son of God.', 'he that believeth on him is not condemned but he that believeth not is condemned already because he hath not believed in the name of the only begotten son of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 19, 'And this is the condemnation, that light is come into the world, and men loved darkness rather than light, because their deeds were evil.', 'and this is the condemnation that light is come into the world and men loved darkness rather than light because their deeds were evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 20, 'For every one that doeth evil hateth the light, neither cometh to the light, lest his deeds should be reproved. {reproved: or, discovered}', 'for every one that doeth evil hateth the light neither cometh to the light lest his deeds should be reproved reproved or discovered');
