INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 22, 'After these things came Jesus and his disciples into the land of Judaea; and there he tarried with them, and baptized.', 'after these things came jesus and his disciples into the land of judaea and there he tarried with them and baptized');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 3, 23, 'And John also was baptizing in Aenon near to Salim, because there was much water there: and they came, and were baptized.', 'and john also was baptizing in aenon near to salim because there was much water there and they came and were baptized');
