INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 7, 'There cometh a woman of Samaria to draw water: Jesus saith unto her, Give me to drink.', 'there cometh a woman of samaria to draw water jesus saith unto her give me to drink');
