INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 9, 'Then saith the woman of Samaria unto him, How is it that thou, being a Jew, askest drink of me, which am a woman of Samaria? for the Jews have no dealings with the Samaritans.', 'then saith the woman of samaria unto him how is it that thou being a jew askest drink of me which am a woman of samaria for the jews have no dealings with the samaritans');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 10, 'Jesus answered and said unto her, If thou knewest the gift of God, and who it is that saith to thee, Give me to drink; thou wouldest have asked of him, and he would have given thee living water.', 'jesus answered and said unto her if thou knewest the gift of god and who it is that saith to thee give me to drink thou wouldest have asked of him and he would have given thee living water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 11, 'The woman saith unto him, Sir, thou hast nothing to draw with, and the well is deep: from whence then hast thou that living water?', 'the woman saith unto him sir thou hast nothing to draw with and the well is deep from whence then hast thou that living water');
