INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 19, 'The woman saith unto him, Sir, I perceive that thou art a prophet.', 'the woman saith unto him sir i perceive that thou art a prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 20, 'Our fathers worshipped in this mountain; and ye say, that in Jerusalem is the place where men ought to worship.', 'our fathers worshipped in this mountain and ye say that in jerusalem is the place where men ought to worship');
