INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 44, 'For Jesus himself testified, that a prophet hath no honour in his own country.', 'for jesus himself testified that a prophet hath no honour in his own country');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 45, 'Then when he was come into Galilee, the Galilaeans received him, having seen all the things that he did at Jerusalem at the feast: for they also went unto the feast.', 'then when he was come into galilee the galilaeans received him having seen all the things that he did at jerusalem at the feast for they also went unto the feast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 46, 'So Jesus came again into Cana of Galilee, where he made the water wine. And there was a certain nobleman, whose son was sick at Capernaum. {nobleman: or, courtier, or, ruler}', 'so jesus came again into cana of galilee where he made the water wine and there was a certain nobleman whose son was sick at capernaum nobleman or courtier or ruler');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 47, 'When he heard that Jesus was come out of Judaea into Galilee, he went unto him, and besought him that he would come down, and heal his son: for he was at the point of death.', 'when he heard that jesus was come out of judaea into galilee he went unto him and besought him that he would come down and heal his son for he was at the point of death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 48, 'Then said Jesus unto him, Except ye see signs and wonders, ye will not believe.', 'then said jesus unto him except ye see signs and wonders ye will not believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 49, 'The nobleman saith unto him, Sir, come down ere my child die.', 'the nobleman saith unto him sir come down ere my child die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 50, 'Jesus saith unto him, Go thy way; thy son liveth. And the man believed the word that Jesus had spoken unto him, and he went his way.', 'jesus saith unto him go thy way thy son liveth and the man believed the word that jesus had spoken unto him and he went his way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 51, 'And as he was now going down, his servants met him, and told {him}, saying, Thy son liveth.', 'and as he was now going down his servants met him and told him saying thy son liveth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 52, 'Then enquired he of them the hour when he began to amend. And they said unto him, Yesterday at the seventh hour the fever left him.', 'then enquired he of them the hour when he began to amend and they said unto him yesterday at the seventh hour the fever left him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 53, 'So the father knew that {it was} at the same hour, in the which Jesus said unto him, Thy son liveth: and himself believed, and his whole house.', 'so the father knew that it was at the same hour in the which jesus said unto him thy son liveth and himself believed and his whole house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 4, 54, 'This {is} again the second miracle {that} Jesus did, when he was come out of Judaea into Galilee.', 'this is again the second miracle that jesus did when he was come out of judaea into galilee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 1, 'After this there was a feast of the Jews; and Jesus went up to Jerusalem.', 'after this there was a feast of the jews and jesus went up to jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 2, 'Now there is at Jerusalem by the sheep {market} a pool, which is called in the Hebrew tongue Bethesda, having five porches. {market: or, gate}', 'now there is at jerusalem by the sheep market a pool which is called in the hebrew tongue bethesda having five porches market or gate');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 3, 'In these lay a great multitude of impotent folk, of blind, halt, withered, waiting for the moving of the water.', 'in these lay a great multitude of impotent folk of blind halt withered waiting for the moving of the water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 4, 'For an angel went down at a certain season into the pool, and troubled the water: whosoever then first after the troubling of the water stepped in was made whole of whatsoever disease he had.', 'for an angel went down at a certain season into the pool and troubled the water whosoever then first after the troubling of the water stepped in was made whole of whatsoever disease he had');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 5, 'And a certain man was there, which had an infirmity thirty and eight years.', 'and a certain man was there which had an infirmity thirty and eight years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 6, 'When Jesus saw him lie, and knew that he had been now a long time {in that case}, he saith unto him, Wilt thou be made whole?', 'when jesus saw him lie and knew that he had been now a long time in that case he saith unto him wilt thou be made whole');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 7, 'The impotent man answered him, Sir, I have no man, when the water is troubled, to put me into the pool: but while I am coming, another steppeth down before me.', 'the impotent man answered him sir i have no man when the water is troubled to put me into the pool but while i am coming another steppeth down before me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 8, 'Jesus saith unto him, Rise, take up thy bed, and walk.', 'jesus saith unto him rise take up thy bed and walk');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 9, 'And immediately the man was made whole, and took up his bed, and walked: and on the same day was the sabbath.', 'and immediately the man was made whole and took up his bed and walked and on the same day was the sabbath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 10, 'The Jews therefore said unto him that was cured, It is the sabbath day: it is not lawful for thee to carry {thy} bed.', 'the jews therefore said unto him that was cured it is the sabbath day it is not lawful for thee to carry thy bed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 11, 'He answered them, He that made me whole, the same said unto me, Take up thy bed, and walk.', 'he answered them he that made me whole the same said unto me take up thy bed and walk');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 12, 'Then asked they him, What man is that which said unto thee, Take up thy bed, and walk?', 'then asked they him what man is that which said unto thee take up thy bed and walk');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 13, 'And he that was healed wist not who it was: for Jesus had conveyed himself away, a multitude being in {that} place. {a multitude...: or, from the multitude that was}', 'and he that was healed wist not who it was for jesus had conveyed himself away a multitude being in that place a multitude or from the multitude that was');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 14, 'Afterward Jesus findeth him in the temple, and said unto him, Behold, thou art made whole: sin no more, lest a worse thing come unto thee.', 'afterward jesus findeth him in the temple and said unto him behold thou art made whole sin no more lest a worse thing come unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 15, 'The man departed, and told the Jews that it was Jesus, which had made him whole.', 'the man departed and told the jews that it was jesus which had made him whole');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 16, 'And therefore did the Jews persecute Jesus, and sought to slay him, because he had done these things on the sabbath day.', 'and therefore did the jews persecute jesus and sought to slay him because he had done these things on the sabbath day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 17, 'But Jesus answered them, My Father worketh hitherto, and I work.', 'but jesus answered them my father worketh hitherto and i work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 18, 'Therefore the Jews sought the more to kill him, because he not only had broken the sabbath, but said also that God was his Father, making himself equal with God.', 'therefore the jews sought the more to kill him because he not only had broken the sabbath but said also that god was his father making himself equal with god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 19, 'Then answered Jesus and said unto them, Verily, verily, I say unto you, The Son can do nothing of himself, but what he seeth the Father do: for what things soever he doeth, these also doeth the Son likewise.', 'then answered jesus and said unto them verily verily i say unto you the son can do nothing of himself but what he seeth the father do for what things soever he doeth these also doeth the son likewise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 20, 'For the Father loveth the Son, and sheweth him all things that himself doeth: and he will shew him greater works than these, that ye may marvel.', 'for the father loveth the son and sheweth him all things that himself doeth and he will shew him greater works than these that ye may marvel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 21, 'For as the Father raiseth up the dead, and quickeneth {them}; even so the Son quickeneth whom he will.', 'for as the father raiseth up the dead and quickeneth them even so the son quickeneth whom he will');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 22, 'For the Father judgeth no man, but hath committed all judgment unto the Son:', 'for the father judgeth no man but hath committed all judgment unto the son');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 23, 'That all {men} should honour the Son, even as they honour the Father. He that honoureth not the Son honoureth not the Father which hath sent him.', 'that all men should honour the son even as they honour the father he that honoureth not the son honoureth not the father which hath sent him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 24, 'Verily, verily, I say unto you, He that heareth my word, and believeth on him that sent me, hath everlasting life, and shall not come into condemnation; but is passed from death unto life.', 'verily verily i say unto you he that heareth my word and believeth on him that sent me hath everlasting life and shall not come into condemnation but is passed from death unto life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 25, 'Verily, verily, I say unto you, The hour is coming, and now is, when the dead shall hear the voice of the Son of God: and they that hear shall live.', 'verily verily i say unto you the hour is coming and now is when the dead shall hear the voice of the son of god and they that hear shall live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 26, 'For as the Father hath life in himself; so hath he given to the Son to have life in himself;', 'for as the father hath life in himself so hath he given to the son to have life in himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 27, 'And hath given him authority to execute judgment also, because he is the Son of man.', 'and hath given him authority to execute judgment also because he is the son of man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 28, 'Marvel not at this: for the hour is coming, in the which all that are in the graves shall hear his voice,', 'marvel not at this for the hour is coming in the which all that are in the graves shall hear his voice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 29, 'And shall come forth; they that have done good, unto the resurrection of life; and they that have done evil, unto the resurrection of damnation.', 'and shall come forth they that have done good unto the resurrection of life and they that have done evil unto the resurrection of damnation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 30, 'I can of mine own self do nothing: as I hear, I judge: and my judgment is just; because I seek not mine own will, but the will of the Father which hath sent me.', 'i can of mine own self do nothing as i hear i judge and my judgment is just because i seek not mine own will but the will of the father which hath sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 31, 'If I bear witness of myself, my witness is not true.', 'if i bear witness of myself my witness is not true');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 32, 'There is another that beareth witness of me; and I know that the witness which he witnesseth of me is true.', 'there is another that beareth witness of me and i know that the witness which he witnesseth of me is true');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 33, 'Ye sent unto John, and he bare witness unto the truth.', 'ye sent unto john and he bare witness unto the truth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 34, 'But I receive not testimony from man: but these things I say, that ye might be saved.', 'but i receive not testimony from man but these things i say that ye might be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 35, 'He was a burning and a shining light: and ye were willing for a season to rejoice in his light.', 'he was a burning and a shining light and ye were willing for a season to rejoice in his light');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 36, 'But I have greater witness than {that} of John: for the works which the Father hath given me to finish, the same works that I do, bear witness of me, that the Father hath sent me.', 'but i have greater witness than that of john for the works which the father hath given me to finish the same works that i do bear witness of me that the father hath sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 37, 'And the Father himself, which hath sent me, hath borne witness of me. Ye have neither heard his voice at any time, nor seen his shape.', 'and the father himself which hath sent me hath borne witness of me ye have neither heard his voice at any time nor seen his shape');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 38, 'And ye have not his word abiding in you: for whom he hath sent, him ye believe not.', 'and ye have not his word abiding in you for whom he hath sent him ye believe not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 39, 'Search the scriptures; for in them ye think ye have eternal life: and they are they which testify of me.', 'search the scriptures for in them ye think ye have eternal life and they are they which testify of me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 40, 'And ye will not come to me, that ye might have life.', 'and ye will not come to me that ye might have life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 41, 'I receive not honour from men.', 'i receive not honour from men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 42, 'But I know you, that ye have not the love of God in you.', 'but i know you that ye have not the love of god in you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 43, 'I am come in my Father''s name, and ye receive me not: if another shall come in his own name, him ye will receive.', 'i am come in my father s name and ye receive me not if another shall come in his own name him ye will receive');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 44, 'How can ye believe, which receive honour one of another, and seek not the honour that {cometh} from God only?', 'how can ye believe which receive honour one of another and seek not the honour that cometh from god only');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 45, 'Do not think that I will accuse you to the Father: there is {one} that accuseth you, {even} Moses, in whom ye trust.', 'do not think that i will accuse you to the father there is one that accuseth you even moses in whom ye trust');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 46, 'For had ye believed Moses, ye would have believed me: for he wrote of me.', 'for had ye believed moses ye would have believed me for he wrote of me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 5, 47, 'But if ye believe not his writings, how shall ye believe my words?', 'but if ye believe not his writings how shall ye believe my words');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 1, 'After these things Jesus went over the sea of Galilee, which is {the sea} of Tiberias.', 'after these things jesus went over the sea of galilee which is the sea of tiberias');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 2, 'And a great multitude followed him, because they saw his miracles which he did on them that were diseased.', 'and a great multitude followed him because they saw his miracles which he did on them that were diseased');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 3, 'And Jesus went up into a mountain, and there he sat with his disciples.', 'and jesus went up into a mountain and there he sat with his disciples');
