INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 5, 'When Jesus then lifted up {his} eyes, and saw a great company come unto him, he saith unto Philip, Whence shall we buy bread, that these may eat?', 'when jesus then lifted up his eyes and saw a great company come unto him he saith unto philip whence shall we buy bread that these may eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 6, 'And this he said to prove him: for he himself knew what he would do.', 'and this he said to prove him for he himself knew what he would do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 7, 'Philip answered him, Two hundred pennyworth of bread is not sufficient for them, that every one of them may take a little.', 'philip answered him two hundred pennyworth of bread is not sufficient for them that every one of them may take a little');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 8, 'One of his disciples, Andrew, Simon Peter''s brother, saith unto him,', 'one of his disciples andrew simon peter s brother saith unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 9, 'There is a lad here, which hath five barley loaves, and two small fishes: but what are they among so many?', 'there is a lad here which hath five barley loaves and two small fishes but what are they among so many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 10, 'And Jesus said, Make the men sit down. Now there was much grass in the place. So the men sat down, in number about five thousand.', 'and jesus said make the men sit down now there was much grass in the place so the men sat down in number about five thousand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 11, 'And Jesus took the loaves; and when he had given thanks, he distributed to the disciples, and the disciples to them that were set down; and likewise of the fishes as much as they would.', 'and jesus took the loaves and when he had given thanks he distributed to the disciples and the disciples to them that were set down and likewise of the fishes as much as they would');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 12, 'When they were filled, he said unto his disciples, Gather up the fragments that remain, that nothing be lost.', 'when they were filled he said unto his disciples gather up the fragments that remain that nothing be lost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 13, 'Therefore they gathered {them} together, and filled twelve baskets with the fragments of the five barley loaves, which remained over and above unto them that had eaten.', 'therefore they gathered them together and filled twelve baskets with the fragments of the five barley loaves which remained over and above unto them that had eaten');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 14, 'Then those men, when they had seen the miracle that Jesus did, said, This is of a truth that prophet that should come into the world.', 'then those men when they had seen the miracle that jesus did said this is of a truth that prophet that should come into the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 15, 'When Jesus therefore perceived that they would come and take him by force, to make him a king, he departed again into a mountain himself alone.', 'when jesus therefore perceived that they would come and take him by force to make him a king he departed again into a mountain himself alone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 16, 'And when even was {now} come, his disciples went down unto the sea,', 'and when even was now come his disciples went down unto the sea');
