INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 30, 'They said therefore unto him, What sign shewest thou then, that we may see, and believe thee? what dost thou work?', 'they said therefore unto him what sign shewest thou then that we may see and believe thee what dost thou work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 31, 'Our fathers did eat manna in the desert; as it is written, He gave them bread from heaven to eat.', 'our fathers did eat manna in the desert as it is written he gave them bread from heaven to eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 32, 'Then Jesus said unto them, Verily, verily, I say unto you, Moses gave you not that bread from heaven; but my Father giveth you the true bread from heaven.', 'then jesus said unto them verily verily i say unto you moses gave you not that bread from heaven but my father giveth you the true bread from heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 33, 'For the bread of God is he which cometh down from heaven, and giveth life unto the world.', 'for the bread of god is he which cometh down from heaven and giveth life unto the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 34, 'Then said they unto him, Lord, evermore give us this bread.', 'then said they unto him lord evermore give us this bread');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 35, 'And Jesus said unto them, I am the bread of life: he that cometh to me shall never hunger; and he that believeth on me shall never thirst.', 'and jesus said unto them i am the bread of life he that cometh to me shall never hunger and he that believeth on me shall never thirst');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 36, 'But I said unto you, That ye also have seen me, and believe not.', 'but i said unto you that ye also have seen me and believe not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 37, 'All that the Father giveth me shall come to me; and him that cometh to me I will in no wise cast out.', 'all that the father giveth me shall come to me and him that cometh to me i will in no wise cast out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 38, 'For I came down from heaven, not to do mine own will, but the will of him that sent me.', 'for i came down from heaven not to do mine own will but the will of him that sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 39, 'And this is the Father''s will which hath sent me, that of all which he hath given me I should lose nothing, but should raise it up again at the last day.', 'and this is the father s will which hath sent me that of all which he hath given me i should lose nothing but should raise it up again at the last day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 40, 'And this is the will of him that sent me, that every one which seeth the Son, and believeth on him, may have everlasting life: and I will raise him up at the last day.', 'and this is the will of him that sent me that every one which seeth the son and believeth on him may have everlasting life and i will raise him up at the last day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 41, 'The Jews then murmured at him, because he said, I am the bread which came down from heaven.', 'the jews then murmured at him because he said i am the bread which came down from heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 42, 'And they said, Is not this Jesus, the son of Joseph, whose father and mother we know? how is it then that he saith, I came down from heaven?', 'and they said is not this jesus the son of joseph whose father and mother we know how is it then that he saith i came down from heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 43, 'Jesus therefore answered and said unto them, Murmur not among yourselves.', 'jesus therefore answered and said unto them murmur not among yourselves');
