INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 6, 58, 'This is that bread which came down from heaven: not as your fathers did eat manna, and are dead: he that eateth of this bread shall live for ever.', 'this is that bread which came down from heaven not as your fathers did eat manna and are dead he that eateth of this bread shall live for ever');
