INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 1, 'After these things Jesus walked in Galilee: for he would not walk in Jewry, because the Jews sought to kill him.', 'after these things jesus walked in galilee for he would not walk in jewry because the jews sought to kill him');
