INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 4, 'For {there is} no man {that} doeth any thing in secret, and he himself seeketh to be known openly. If thou do these things, shew thyself to the world.', 'for there is no man that doeth any thing in secret and he himself seeketh to be known openly if thou do these things shew thyself to the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 5, 'For neither did his brethren believe in him.', 'for neither did his brethren believe in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 6, 'Then Jesus said unto them, My time is not yet come: but your time is alway ready.', 'then jesus said unto them my time is not yet come but your time is alway ready');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 7, 'The world cannot hate you; but me it hateth, because I testify of it, that the works thereof are evil.', 'the world cannot hate you but me it hateth because i testify of it that the works thereof are evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 8, 'Go ye up unto this feast: I go not up yet unto this feast; for my time is not yet full come.', 'go ye up unto this feast i go not up yet unto this feast for my time is not yet full come');
