INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 13, 'Howbeit no man spake openly of him for fear of the Jews.', 'howbeit no man spake openly of him for fear of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 14, 'Now about the midst of the feast Jesus went up into the temple, and taught.', 'now about the midst of the feast jesus went up into the temple and taught');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 15, 'And the Jews marvelled, saying, How knoweth this man letters, having never learned? {letters: or, learning}', 'and the jews marvelled saying how knoweth this man letters having never learned letters or learning');
