INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 17, 'If any man will do his will, he shall know of the doctrine, whether it be of God, or {whether} I speak of myself.', 'if any man will do his will he shall know of the doctrine whether it be of god or whether i speak of myself');
