INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 19, 'Did not Moses give you the law, and {yet} none of you keepeth the law? Why go ye about to kill me?', 'did not moses give you the law and yet none of you keepeth the law why go ye about to kill me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 20, 'The people answered and said, Thou hast a devil: who goeth about to kill thee?', 'the people answered and said thou hast a devil who goeth about to kill thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 21, 'Jesus answered and said unto them, I have done one work, and ye all marvel.', 'jesus answered and said unto them i have done one work and ye all marvel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 22, 'Moses therefore gave unto you circumcision; (not because it is of Moses, but of the fathers;) and ye on the sabbath day circumcise a man.', 'moses therefore gave unto you circumcision not because it is of moses but of the fathers and ye on the sabbath day circumcise a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 23, 'If a man on the sabbath day receive circumcision, that the law of Moses should not be broken; are ye angry at me, because I have made a man every whit whole on the sabbath day? {that...: or, without breaking the law of Moses}', 'if a man on the sabbath day receive circumcision that the law of moses should not be broken are ye angry at me because i have made a man every whit whole on the sabbath day that or without breaking the law of moses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 24, 'Judge not according to the appearance, but judge righteous judgment.', 'judge not according to the appearance but judge righteous judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 25, 'Then said some of them of Jerusalem, Is not this he, whom they seek to kill?', 'then said some of them of jerusalem is not this he whom they seek to kill');
