INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 32, 'The Pharisees heard that the people murmured such things concerning him; and the Pharisees and the chief priests sent officers to take him.', 'the pharisees heard that the people murmured such things concerning him and the pharisees and the chief priests sent officers to take him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 33, 'Then said Jesus unto them, Yet a little while am I with you, and {then} I go unto him that sent me.', 'then said jesus unto them yet a little while am i with you and then i go unto him that sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 34, 'Ye shall seek me, and shall not find {me}: and where I am, {thither} ye cannot come.', 'ye shall seek me and shall not find me and where i am thither ye cannot come');
