INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 7, 37, 'In the last day, that great {day} of the feast, Jesus stood and cried, saying, If any man thirst, let him come unto me, and drink.', 'in the last day that great day of the feast jesus stood and cried saying if any man thirst let him come unto me and drink');
