INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 4, 'They say unto him, Master, this woman was taken in adultery, in the very act.', 'they say unto him master this woman was taken in adultery in the very act');
