INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 6, 'This they said, tempting him, that they might have to accuse him. But Jesus stooped down, and with {his} finger wrote on the ground, {as though he heard them not}.', 'this they said tempting him that they might have to accuse him but jesus stooped down and with his finger wrote on the ground as though he heard them not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 7, 'So when they continued asking him, he lifted up himself, and said unto them, He that is without sin among you, let him first cast a stone at her.', 'so when they continued asking him he lifted up himself and said unto them he that is without sin among you let him first cast a stone at her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 8, 'And again he stooped down, and wrote on the ground.', 'and again he stooped down and wrote on the ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 9, 'And they which heard {it}, being convicted by {their own} conscience, went out one by one, beginning at the eldest, {even} unto the last: and Jesus was left alone, and the woman standing in the midst.', 'and they which heard it being convicted by their own conscience went out one by one beginning at the eldest even unto the last and jesus was left alone and the woman standing in the midst');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 10, 'When Jesus had lifted up himself, and saw none but the woman, he said unto her, Woman, where are those thine accusers? hath no man condemned thee?', 'when jesus had lifted up himself and saw none but the woman he said unto her woman where are those thine accusers hath no man condemned thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 11, 'She said, No man, Lord. And Jesus said unto her, Neither do I condemn thee: go, and sin no more.', 'she said no man lord and jesus said unto her neither do i condemn thee go and sin no more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 12, 'Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.', 'then spake jesus again unto them saying i am the light of the world he that followeth me shall not walk in darkness but shall have the light of life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 13, 'The Pharisees therefore said unto him, Thou bearest record of thyself; thy record is not true.', 'the pharisees therefore said unto him thou bearest record of thyself thy record is not true');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 14, 'Jesus answered and said unto them, Though I bear record of myself, {yet} my record is true: for I know whence I came, and whither I go; but ye cannot tell whence I come, and whither I go.', 'jesus answered and said unto them though i bear record of myself yet my record is true for i know whence i came and whither i go but ye cannot tell whence i come and whither i go');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 15, 'Ye judge after the flesh; I judge no man.', 'ye judge after the flesh i judge no man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 16, 'And yet if I judge, my judgment is true: for I am not alone, but I and the Father that sent me.', 'and yet if i judge my judgment is true for i am not alone but i and the father that sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 17, 'It is also written in your law, that the testimony of two men is true.', 'it is also written in your law that the testimony of two men is true');
