INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 19, 'Then said they unto him, Where is thy Father? Jesus answered, Ye neither know me, nor my Father: if ye had known me, ye should have known my Father also.', 'then said they unto him where is thy father jesus answered ye neither know me nor my father if ye had known me ye should have known my father also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 20, 'These words spake Jesus in the treasury, as he taught in the temple: and no man laid hands on him; for his hour was not yet come.', 'these words spake jesus in the treasury as he taught in the temple and no man laid hands on him for his hour was not yet come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 21, 'Then said Jesus again unto them, I go my way, and ye shall seek me, and shall die in your sins: whither I go, ye cannot come.', 'then said jesus again unto them i go my way and ye shall seek me and shall die in your sins whither i go ye cannot come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 22, 'Then said the Jews, Will he kill himself? because he saith, Whither I go, ye cannot come.', 'then said the jews will he kill himself because he saith whither i go ye cannot come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 23, 'And he said unto them, Ye are from beneath; I am from above: ye are of this world; I am not of this world.', 'and he said unto them ye are from beneath i am from above ye are of this world i am not of this world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 24, 'I said therefore unto you, that ye shall die in your sins: for if ye believe not that I am {he}, ye shall die in your sins.', 'i said therefore unto you that ye shall die in your sins for if ye believe not that i am he ye shall die in your sins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 25, 'Then said they unto him, Who art thou? And Jesus saith unto them, Even {the same} that I said unto you from the beginning.', 'then said they unto him who art thou and jesus saith unto them even the same that i said unto you from the beginning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 26, 'I have many things to say and to judge of you: but he that sent me is true; and I speak to the world those things which I have heard of him.', 'i have many things to say and to judge of you but he that sent me is true and i speak to the world those things which i have heard of him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 27, 'They understood not that he spake to them of the Father.', 'they understood not that he spake to them of the father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 28, 'Then said Jesus unto them, When ye have lifted up the Son of man, then shall ye know that I am {he}, and {that} I do nothing of myself; but as my Father hath taught me, I speak these things.', 'then said jesus unto them when ye have lifted up the son of man then shall ye know that i am he and that i do nothing of myself but as my father hath taught me i speak these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 29, 'And he that sent me is with me: the Father hath not left me alone; for I do always those things that please him.', 'and he that sent me is with me the father hath not left me alone for i do always those things that please him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 30, 'As he spake these words, many believed on him.', 'as he spake these words many believed on him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 31, 'Then said Jesus to those Jews which believed on him, If ye continue in my word, {then} are ye my disciples indeed;', 'then said jesus to those jews which believed on him if ye continue in my word then are ye my disciples indeed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 32, 'And ye shall know the truth, and the truth shall make you free.', 'and ye shall know the truth and the truth shall make you free');
