INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 34, 'Jesus answered them, Verily, verily, I say unto you, Whosoever committeth sin is the servant of sin.', 'jesus answered them verily verily i say unto you whosoever committeth sin is the servant of sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 35, 'And the servant abideth not in the house for ever: {but} the Son abideth ever.', 'and the servant abideth not in the house for ever but the son abideth ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 36, 'If the Son therefore shall make you free, ye shall be free indeed.', 'if the son therefore shall make you free ye shall be free indeed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 37, 'I know that ye are Abraham''s seed; but ye seek to kill me, because my word hath no place in you.', 'i know that ye are abraham s seed but ye seek to kill me because my word hath no place in you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 38, 'I speak that which I have seen with my Father: and ye do that which ye have seen with your father.', 'i speak that which i have seen with my father and ye do that which ye have seen with your father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 39, 'They answered and said unto him, Abraham is our father. Jesus saith unto them, If ye were Abraham''s children, ye would do the works of Abraham.', 'they answered and said unto him abraham is our father jesus saith unto them if ye were abraham s children ye would do the works of abraham');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 40, 'But now ye seek to kill me, a man that hath told you the truth, which I have heard of God: this did not Abraham.', 'but now ye seek to kill me a man that hath told you the truth which i have heard of god this did not abraham');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 41, 'Ye do the deeds of your father. Then said they to him, We be not born of fornication; we have one Father, {even} God.', 'ye do the deeds of your father then said they to him we be not born of fornication we have one father even god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 42, 'Jesus said unto them, If God were your Father, ye would love me: for I proceeded forth and came from God; neither came I of myself, but he sent me.', 'jesus said unto them if god were your father ye would love me for i proceeded forth and came from god neither came i of myself but he sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 43, 'Why do ye not understand my speech? {even} because ye cannot hear my word.', 'why do ye not understand my speech even because ye cannot hear my word');
