INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 47, 'He that is of God heareth God''s words: ye therefore hear {them} not, because ye are not of God.', 'he that is of god heareth god s words ye therefore hear them not because ye are not of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 48, 'Then answered the Jews, and said unto him, Say we not well that thou art a Samaritan, and hast a devil?', 'then answered the jews and said unto him say we not well that thou art a samaritan and hast a devil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 49, 'Jesus answered, I have not a devil; but I honour my Father, and ye do dishonour me.', 'jesus answered i have not a devil but i honour my father and ye do dishonour me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 50, 'And I seek not mine own glory: there is one that seeketh and judgeth.', 'and i seek not mine own glory there is one that seeketh and judgeth');
