INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 52, 'Then said the Jews unto him, Now we know that thou hast a devil. Abraham is dead, and the prophets; and thou sayest, If a man keep my saying, he shall never taste of death.', 'then said the jews unto him now we know that thou hast a devil abraham is dead and the prophets and thou sayest if a man keep my saying he shall never taste of death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 53, 'Art thou greater than our father Abraham, which is dead? and the prophets are dead: whom makest thou thyself?', 'art thou greater than our father abraham which is dead and the prophets are dead whom makest thou thyself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 54, 'Jesus answered, If I honour myself, my honour is nothing: it is my Father that honoureth me; of whom ye say, that he is your God:', 'jesus answered if i honour myself my honour is nothing it is my father that honoureth me of whom ye say that he is your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 55, 'Yet ye have not known him; but I know him: and if I should say, I know him not, I shall be a liar like unto you: but I know him, and keep his saying.', 'yet ye have not known him but i know him and if i should say i know him not i shall be a liar like unto you but i know him and keep his saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 56, 'Your father Abraham rejoiced to see my day: and he saw {it}, and was glad.', 'your father abraham rejoiced to see my day and he saw it and was glad');
