INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 8, 59, 'Then took they up stones to cast at him: but Jesus hid himself, and went out of the temple, going through the midst of them, and so passed by.', 'then took they up stones to cast at him but jesus hid himself and went out of the temple going through the midst of them and so passed by');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 1, 'And as {Jesus} passed by, he saw a man which was blind from {his} birth.', 'and as jesus passed by he saw a man which was blind from his birth');
