INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 3, 'Jesus answered, Neither hath this man sinned, nor his parents: but that the works of God should be made manifest in him.', 'jesus answered neither hath this man sinned nor his parents but that the works of god should be made manifest in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 4, 'I must work the works of him that sent me, while it is day: the night cometh, when no man can work.', 'i must work the works of him that sent me while it is day the night cometh when no man can work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 5, 'As long as I am in the world, I am the light of the world.', 'as long as i am in the world i am the light of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 6, 'When he had thus spoken, he spat on the ground, and made clay of the spittle, and he anointed the eyes of the blind man with the clay, {anointed...: or, spread the clay upon the eyes of the blind man}', 'when he had thus spoken he spat on the ground and made clay of the spittle and he anointed the eyes of the blind man with the clay anointed or spread the clay upon the eyes of the blind man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 7, 'And said unto him, Go, wash in the pool of Siloam, (which is by interpretation, Sent.) He went his way therefore, and washed, and came seeing.', 'and said unto him go wash in the pool of siloam which is by interpretation sent he went his way therefore and washed and came seeing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 8, 'The neighbours therefore, and they which before had seen him that he was blind, said, Is not this he that sat and begged?', 'the neighbours therefore and they which before had seen him that he was blind said is not this he that sat and begged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 9, 'Some said, This is he: others {said}, He is like him: {but} he said, I am {he}.', 'some said this is he others said he is like him but he said i am he');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 10, 'Therefore said they unto him, How were thine eyes opened?', 'therefore said they unto him how were thine eyes opened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 11, 'He answered and said, A man that is called Jesus made clay, and anointed mine eyes, and said unto me, Go to the pool of Siloam, and wash: and I went and washed, and I received sight.', 'he answered and said a man that is called jesus made clay and anointed mine eyes and said unto me go to the pool of siloam and wash and i went and washed and i received sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 12, 'Then said they unto him, Where is he? He said, I know not.', 'then said they unto him where is he he said i know not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 13, 'They brought to the Pharisees him that aforetime was blind.', 'they brought to the pharisees him that aforetime was blind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 14, 'And it was the sabbath day when Jesus made the clay, and opened his eyes.', 'and it was the sabbath day when jesus made the clay and opened his eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 15, 'Then again the Pharisees also asked him how he had received his sight. He said unto them, He put clay upon mine eyes, and I washed, and do see.', 'then again the pharisees also asked him how he had received his sight he said unto them he put clay upon mine eyes and i washed and do see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 16, 'Therefore said some of the Pharisees, This man is not of God, because he keepeth not the sabbath day. Others said, How can a man that is a sinner do such miracles? And there was a division among them.', 'therefore said some of the pharisees this man is not of god because he keepeth not the sabbath day others said how can a man that is a sinner do such miracles and there was a division among them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 17, 'They say unto the blind man again, What sayest thou of him, that he hath opened thine eyes? He said, He is a prophet.', 'they say unto the blind man again what sayest thou of him that he hath opened thine eyes he said he is a prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 18, 'But the Jews did not believe concerning him, that he had been blind, and received his sight, until they called the parents of him that had received his sight.', 'but the jews did not believe concerning him that he had been blind and received his sight until they called the parents of him that had received his sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 19, 'And they asked them, saying, Is this your son, who ye say was born blind? how then doth he now see?', 'and they asked them saying is this your son who ye say was born blind how then doth he now see');
