INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 21, 'But by what means he now seeth, we know not; or who hath opened his eyes, we know not: he is of age; ask him: he shall speak for himself.', 'but by what means he now seeth we know not or who hath opened his eyes we know not he is of age ask him he shall speak for himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 22, 'These {words} spake his parents, because they feared the Jews: for the Jews had agreed already, that if any man did confess that he was Christ, he should be put out of the synagogue.', 'these words spake his parents because they feared the jews for the jews had agreed already that if any man did confess that he was christ he should be put out of the synagogue');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 23, 'Therefore said his parents, He is of age; ask him.', 'therefore said his parents he is of age ask him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 24, 'Then again called they the man that was blind, and said unto him, Give God the praise: we know that this man is a sinner.', 'then again called they the man that was blind and said unto him give god the praise we know that this man is a sinner');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 25, 'He answered and said, Whether he be a sinner {or no}, I know not: one thing I know, that, whereas I was blind, now I see.', 'he answered and said whether he be a sinner or no i know not one thing i know that whereas i was blind now i see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 26, 'Then said they to him again, What did he to thee? how opened he thine eyes?', 'then said they to him again what did he to thee how opened he thine eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 27, 'He answered them, I have told you already, and ye did not hear: wherefore would ye hear {it} again? will ye also be his disciples?', 'he answered them i have told you already and ye did not hear wherefore would ye hear it again will ye also be his disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 28, 'Then they reviled him, and said, Thou art his disciple; but we are Moses'' disciples.', 'then they reviled him and said thou art his disciple but we are moses disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 29, 'We know that God spake unto Moses: {as for} this {fellow}, we know not from whence he is.', 'we know that god spake unto moses as for this fellow we know not from whence he is');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 30, 'The man answered and said unto them, Why herein is a marvellous thing, that ye know not from whence he is, and {yet} he hath opened mine eyes.', 'the man answered and said unto them why herein is a marvellous thing that ye know not from whence he is and yet he hath opened mine eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 31, 'Now we know that God heareth not sinners: but if any man be a worshipper of God, and doeth his will, him he heareth.', 'now we know that god heareth not sinners but if any man be a worshipper of god and doeth his will him he heareth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 32, 'Since the world began was it not heard that any man opened the eyes of one that was born blind.', 'since the world began was it not heard that any man opened the eyes of one that was born blind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 33, 'If this man were not of God, he could do nothing.', 'if this man were not of god he could do nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 34, 'They answered and said unto him, Thou wast altogether born in sins, and dost thou teach us? And they cast him out. {cast...: or, excommunicated him}', 'they answered and said unto him thou wast altogether born in sins and dost thou teach us and they cast him out cast or excommunicated him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 35, 'Jesus heard that they had cast him out; and when he had found him, he said unto him, Dost thou believe on the Son of God?', 'jesus heard that they had cast him out and when he had found him he said unto him dost thou believe on the son of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 36, 'He answered and said, Who is he, Lord, that I might believe on him?', 'he answered and said who is he lord that i might believe on him');
