INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 38, 'And he said, Lord, I believe. And he worshipped him.', 'and he said lord i believe and he worshipped him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 39, 'And Jesus said, For judgment I am come into this world, that they which see not might see; and that they which see might be made blind.', 'and jesus said for judgment i am come into this world that they which see not might see and that they which see might be made blind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 40, 'And {some} of the Pharisees which were with him heard these words, and said unto him, Are we blind also?', 'and some of the pharisees which were with him heard these words and said unto him are we blind also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 9, 41, 'Jesus said unto them, If ye were blind, ye should have no sin: but now ye say, We see; therefore your sin remaineth.', 'jesus said unto them if ye were blind ye should have no sin but now ye say we see therefore your sin remaineth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 1, 'Verily, verily, I say unto you, He that entereth not by the door into the sheepfold, but climbeth up some other way, the same is a thief and a robber.', 'verily verily i say unto you he that entereth not by the door into the sheepfold but climbeth up some other way the same is a thief and a robber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 2, 'But he that entereth in by the door is the shepherd of the sheep.', 'but he that entereth in by the door is the shepherd of the sheep');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 3, 'To him the porter openeth; and the sheep hear his voice: and he calleth his own sheep by name, and leadeth them out.', 'to him the porter openeth and the sheep hear his voice and he calleth his own sheep by name and leadeth them out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 4, 'And when he putteth forth his own sheep, he goeth before them, and the sheep follow him: for they know his voice.', 'and when he putteth forth his own sheep he goeth before them and the sheep follow him for they know his voice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 5, 'And a stranger will they not follow, but will flee from him: for they know not the voice of strangers.', 'and a stranger will they not follow but will flee from him for they know not the voice of strangers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 6, 'This parable spake Jesus unto them: but they understood not what things they were which he spake unto them.', 'this parable spake jesus unto them but they understood not what things they were which he spake unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 7, 'Then said Jesus unto them again, Verily, verily, I say unto you, I am the door of the sheep.', 'then said jesus unto them again verily verily i say unto you i am the door of the sheep');
