INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 9, 'I am the door: by me if any man enter in, he shall be saved, and shall go in and out, and find pasture.', 'i am the door by me if any man enter in he shall be saved and shall go in and out and find pasture');
