INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 10, 11, 'I am the good shepherd: the good shepherd giveth his life for the sheep.', 'i am the good shepherd the good shepherd giveth his life for the sheep');
