INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 11, 9, 'Jesus answered, Are there not twelve hours in the day? If any man walk in the day, he stumbleth not, because he seeth the light of this world.', 'jesus answered are there not twelve hours in the day if any man walk in the day he stumbleth not because he seeth the light of this world');
