INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 5, 'I am the vine, ye {are} the branches: He that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing. {without me: or, severed from me}', 'i am the vine ye are the branches he that abideth in me and i in him the same bringeth forth much fruit for without me ye can do nothing without me or severed from me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 6, 'If a man abide not in me, he is cast forth as a branch, and is withered; and men gather them, and cast {them} into the fire, and they are burned.', 'if a man abide not in me he is cast forth as a branch and is withered and men gather them and cast them into the fire and they are burned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 7, 'If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you.', 'if ye abide in me and my words abide in you ye shall ask what ye will and it shall be done unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 8, 'Herein is my Father glorified, that ye bear much fruit; so shall ye be my disciples.', 'herein is my father glorified that ye bear much fruit so shall ye be my disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 9, 'As the Father hath loved me, so have I loved you: continue ye in my love.', 'as the father hath loved me so have i loved you continue ye in my love');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 10, 'If ye keep my commandments, ye shall abide in my love; even as I have kept my Father''s commandments, and abide in his love.', 'if ye keep my commandments ye shall abide in my love even as i have kept my father s commandments and abide in his love');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 11, 'These things have I spoken unto you, that my joy might remain in you, and {that} your joy might be full.', 'these things have i spoken unto you that my joy might remain in you and that your joy might be full');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 12, 'This is my commandment, That ye love one another, as I have loved you.', 'this is my commandment that ye love one another as i have loved you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 13, 'Greater love hath no man than this, that a man lay down his life for his friends.', 'greater love hath no man than this that a man lay down his life for his friends');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 14, 'Ye are my friends, if ye do whatsoever I command you.', 'ye are my friends if ye do whatsoever i command you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 15, 'Henceforth I call you not servants; for the servant knoweth not what his lord doeth: but I have called you friends; for all things that I have heard of my Father I have made known unto you.', 'henceforth i call you not servants for the servant knoweth not what his lord doeth but i have called you friends for all things that i have heard of my father i have made known unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 16, 'Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and {that} your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.', 'ye have not chosen me but i have chosen you and ordained you that ye should go and bring forth fruit and that your fruit should remain that whatsoever ye shall ask of the father in my name he may give it you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 17, 'These things I command you, that ye love one another.', 'these things i command you that ye love one another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 18, 'If the world hate you, ye know that it hated me before {it hated} you.', 'if the world hate you ye know that it hated me before it hated you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 19, 'If ye were of the world, the world would love his own: but because ye are not of the world, but I have chosen you out of the world, therefore the world hateth you.', 'if ye were of the world the world would love his own but because ye are not of the world but i have chosen you out of the world therefore the world hateth you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 20, 'Remember the word that I said unto you, The servant is not greater than his lord. If they have persecuted me, they will also persecute you; if they have kept my saying, they will keep yours also.', 'remember the word that i said unto you the servant is not greater than his lord if they have persecuted me they will also persecute you if they have kept my saying they will keep yours also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 21, 'But all these things will they do unto you for my name''s sake, because they know not him that sent me.', 'but all these things will they do unto you for my name s sake because they know not him that sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 22, 'If I had not come and spoken unto them, they had not had sin: but now they have no cloke for their sin. {cloke: or, excuse}', 'if i had not come and spoken unto them they had not had sin but now they have no cloke for their sin cloke or excuse');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 23, 'He that hateth me hateth my Father also.', 'he that hateth me hateth my father also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 24, 'If I had not done among them the works which none other man did, they had not had sin: but now have they both seen and hated both me and my Father.', 'if i had not done among them the works which none other man did they had not had sin but now have they both seen and hated both me and my father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 25, 'But {this cometh to pass}, that the word might be fulfilled that is written in their law, They hated me without a cause.', 'but this cometh to pass that the word might be fulfilled that is written in their law they hated me without a cause');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 26, 'But when the Comforter is come, whom I will send unto you from the Father, {even} the Spirit of truth, which proceedeth from the Father, he shall testify of me:', 'but when the comforter is come whom i will send unto you from the father even the spirit of truth which proceedeth from the father he shall testify of me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 15, 27, 'And ye also shall bear witness, because ye have been with me from the beginning.', 'and ye also shall bear witness because ye have been with me from the beginning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 1, 'These things have I spoken unto you, that ye should not be offended. {offended: scandalized or, made to stumble}', 'these things have i spoken unto you that ye should not be offended offended scandalized or made to stumble');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 2, 'They shall put you out of the synagogues: yea, the time cometh, that whosoever killeth you will think that he doeth God service.', 'they shall put you out of the synagogues yea the time cometh that whosoever killeth you will think that he doeth god service');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 3, 'And these things will they do unto you, because they have not known the Father, nor me.', 'and these things will they do unto you because they have not known the father nor me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 4, 'But these things have I told you, that when the time shall come, ye may remember that I told you of them. And these things I said not unto you at the beginning, because I was with you.', 'but these things have i told you that when the time shall come ye may remember that i told you of them and these things i said not unto you at the beginning because i was with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 5, 'But now I go my way to him that sent me; and none of you asketh me, Whither goest thou?', 'but now i go my way to him that sent me and none of you asketh me whither goest thou');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 6, 'But because I have said these things unto you, sorrow hath filled your heart.', 'but because i have said these things unto you sorrow hath filled your heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 7, 'Nevertheless I tell you the truth; It is expedient for you that I go away: for if I go not away, the Comforter will not come unto you; but if I depart, I will send him unto you.', 'nevertheless i tell you the truth it is expedient for you that i go away for if i go not away the comforter will not come unto you but if i depart i will send him unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 8, 'And when he is come, he will reprove the world of sin, and of righteousness, and of judgment: {reprove: or, convince}', 'and when he is come he will reprove the world of sin and of righteousness and of judgment reprove or convince');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 9, 'Of sin, because they believe not on me;', 'of sin because they believe not on me');
