INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 12, 'I have yet many things to say unto you, but ye cannot bear them now.', 'i have yet many things to say unto you but ye cannot bear them now');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 13, 'Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, {that} shall he speak: and he will shew you things to come.', 'howbeit when he the spirit of truth is come he will guide you into all truth for he shall not speak of himself but whatsoever he shall hear that shall he speak and he will shew you things to come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 14, 'He shall glorify me: for he shall receive of mine, and shall shew {it} unto you.', 'he shall glorify me for he shall receive of mine and shall shew it unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 15, 'All things that the Father hath are mine: therefore said I, that he shall take of mine, and shall shew {it} unto you.', 'all things that the father hath are mine therefore said i that he shall take of mine and shall shew it unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 16, 'A little while, and ye shall not see me: and again, a little while, and ye shall see me, because I go to the Father.', 'a little while and ye shall not see me and again a little while and ye shall see me because i go to the father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 17, 'Then said {some} of his disciples among themselves, What is this that he saith unto us, A little while, and ye shall not see me: and again, a little while, and ye shall see me: and, Because I go to the Father?', 'then said some of his disciples among themselves what is this that he saith unto us a little while and ye shall not see me and again a little while and ye shall see me and because i go to the father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 18, 'They said therefore, What is this that he saith, A little while? we cannot tell what he saith.', 'they said therefore what is this that he saith a little while we cannot tell what he saith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 19, 'Now Jesus knew that they were desirous to ask him, and said unto them, Do ye enquire among yourselves of that I said, A little while, and ye shall not see me: and again, a little while, and ye shall see me?', 'now jesus knew that they were desirous to ask him and said unto them do ye enquire among yourselves of that i said a little while and ye shall not see me and again a little while and ye shall see me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 20, 'Verily, verily, I say unto you, That ye shall weep and lament, but the world shall rejoice: and ye shall be sorrowful, but your sorrow shall be turned into joy.', 'verily verily i say unto you that ye shall weep and lament but the world shall rejoice and ye shall be sorrowful but your sorrow shall be turned into joy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 21, 'A woman when she is in travail hath sorrow, because her hour is come: but as soon as she is delivered of the child, she remembereth no more the anguish, for joy that a man is born into the world.', 'a woman when she is in travail hath sorrow because her hour is come but as soon as she is delivered of the child she remembereth no more the anguish for joy that a man is born into the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 22, 'And ye now therefore have sorrow: but I will see you again, and your heart shall rejoice, and your joy no man taketh from you.', 'and ye now therefore have sorrow but i will see you again and your heart shall rejoice and your joy no man taketh from you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 23, 'And in that day ye shall ask me nothing. Verily, verily, I say unto you, Whatsoever ye shall ask the Father in my name, he will give {it} you.', 'and in that day ye shall ask me nothing verily verily i say unto you whatsoever ye shall ask the father in my name he will give it you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 24, 'Hitherto have ye asked nothing in my name: ask, and ye shall receive, that your joy may be full.', 'hitherto have ye asked nothing in my name ask and ye shall receive that your joy may be full');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 25, 'These things have I spoken unto you in proverbs: but the time cometh, when I shall no more speak unto you in proverbs, but I shall shew you plainly of the Father. {proverbs: or, parables}', 'these things have i spoken unto you in proverbs but the time cometh when i shall no more speak unto you in proverbs but i shall shew you plainly of the father proverbs or parables');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 26, 'At that day ye shall ask in my name: and I say not unto you, that I will pray the Father for you:', 'at that day ye shall ask in my name and i say not unto you that i will pray the father for you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 27, 'For the Father himself loveth you, because ye have loved me, and have believed that I came out from God.', 'for the father himself loveth you because ye have loved me and have believed that i came out from god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 28, 'I came forth from the Father, and am come into the world: again, I leave the world, and go to the Father.', 'i came forth from the father and am come into the world again i leave the world and go to the father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 29, 'His disciples said unto him, Lo, now speakest thou plainly, and speakest no proverb. {proverb: or, parable}', 'his disciples said unto him lo now speakest thou plainly and speakest no proverb proverb or parable');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 30, 'Now are we sure that thou knowest all things, and needest not that any man should ask thee: by this we believe that thou camest forth from God.', 'now are we sure that thou knowest all things and needest not that any man should ask thee by this we believe that thou camest forth from god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 31, 'Jesus answered them, Do ye now believe?', 'jesus answered them do ye now believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 32, 'Behold, the hour cometh, yea, is now come, that ye shall be scattered, every man to his own, and shall leave me alone: and yet I am not alone, because the Father is with me. {his own: or, his own home}', 'behold the hour cometh yea is now come that ye shall be scattered every man to his own and shall leave me alone and yet i am not alone because the father is with me his own or his own home');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 16, 33, 'These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.', 'these things i have spoken unto you that in me ye might have peace in the world ye shall have tribulation but be of good cheer i have overcome the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 1, 'These words spake Jesus, and lifted up his eyes to heaven, and said, Father, the hour is come; glorify thy Son, that thy Son also may glorify thee:', 'these words spake jesus and lifted up his eyes to heaven and said father the hour is come glorify thy son that thy son also may glorify thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 2, 'As thou hast given him power over all flesh, that he should give eternal life to as many as thou hast given him.', 'as thou hast given him power over all flesh that he should give eternal life to as many as thou hast given him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 3, 'And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent.', 'and this is life eternal that they might know thee the only true god and jesus christ whom thou hast sent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 4, 'I have glorified thee on the earth: I have finished the work which thou gavest me to do.', 'i have glorified thee on the earth i have finished the work which thou gavest me to do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 5, 'And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was.', 'and now o father glorify thou me with thine own self with the glory which i had with thee before the world was');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 6, 'I have manifested thy name unto the men which thou gavest me out of the world: thine they were, and thou gavest them me; and they have kept thy word.', 'i have manifested thy name unto the men which thou gavest me out of the world thine they were and thou gavest them me and they have kept thy word');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 7, 'Now they have known that all things whatsoever thou hast given me are of thee.', 'now they have known that all things whatsoever thou hast given me are of thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 8, 'For I have given unto them the words which thou gavest me; and they have received {them}, and have known surely that I came out from thee, and they have believed that thou didst send me.', 'for i have given unto them the words which thou gavest me and they have received them and have known surely that i came out from thee and they have believed that thou didst send me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 9, 'I pray for them: I pray not for the world, but for them which thou hast given me; for they are thine.', 'i pray for them i pray not for the world but for them which thou hast given me for they are thine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 10, 'And all mine are thine, and thine are mine; and I am glorified in them.', 'and all mine are thine and thine are mine and i am glorified in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 11, 'And now I am no more in the world, but these are in the world, and I come to thee. Holy Father, keep through thine own name those whom thou hast given me, that they may be one, as we {are}.', 'and now i am no more in the world but these are in the world and i come to thee holy father keep through thine own name those whom thou hast given me that they may be one as we are');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 12, 'While I was with them in the world, I kept them in thy name: those that thou gavest me I have kept, and none of them is lost, but the son of perdition; that the scripture might be fulfilled.', 'while i was with them in the world i kept them in thy name those that thou gavest me i have kept and none of them is lost but the son of perdition that the scripture might be fulfilled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 13, 'And now come I to thee; and these things I speak in the world, that they might have my joy fulfilled in themselves.', 'and now come i to thee and these things i speak in the world that they might have my joy fulfilled in themselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 14, 'I have given them thy word; and the world hath hated them, because they are not of the world, even as I am not of the world.', 'i have given them thy word and the world hath hated them because they are not of the world even as i am not of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 15, 'I pray not that thou shouldest take them out of the world, but that thou shouldest keep them from the evil.', 'i pray not that thou shouldest take them out of the world but that thou shouldest keep them from the evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 16, 'They are not of the world, even as I am not of the world.', 'they are not of the world even as i am not of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 17, 'Sanctify them through thy truth: thy word is truth.', 'sanctify them through thy truth thy word is truth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 18, 'As thou hast sent me into the world, even so have I also sent them into the world.', 'as thou hast sent me into the world even so have i also sent them into the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 19, 'And for their sakes I sanctify myself, that they also might be sanctified through the truth. {sanctified...: or, truly sanctified}', 'and for their sakes i sanctify myself that they also might be sanctified through the truth sanctified or truly sanctified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 20, 'Neither pray I for these alone, but for them also which shall believe on me through their word;', 'neither pray i for these alone but for them also which shall believe on me through their word');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 21, 'That they all may be one; as thou, Father, {art} in me, and I in thee, that they also may be one in us: that the world may believe that thou hast sent me.', 'that they all may be one as thou father art in me and i in thee that they also may be one in us that the world may believe that thou hast sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 22, 'And the glory which thou gavest me I have given them; that they may be one, even as we are one:', 'and the glory which thou gavest me i have given them that they may be one even as we are one');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 23, 'I in them, and thou in me, that they may be made perfect in one; and that the world may know that thou hast sent me, and hast loved them, as thou hast loved me.', 'i in them and thou in me that they may be made perfect in one and that the world may know that thou hast sent me and hast loved them as thou hast loved me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 24, 'Father, I will that they also, whom thou hast given me, be with me where I am; that they may behold my glory, which thou hast given me: for thou lovedst me before the foundation of the world.', 'father i will that they also whom thou hast given me be with me where i am that they may behold my glory which thou hast given me for thou lovedst me before the foundation of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 25, 'O righteous Father, the world hath not known thee: but I have known thee, and these have known that thou hast sent me.', 'o righteous father the world hath not known thee but i have known thee and these have known that thou hast sent me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 17, 26, 'And I have declared unto them thy name, and will declare {it}: that the love wherewith thou hast loved me may be in them, and I in them.', 'and i have declared unto them thy name and will declare it that the love wherewith thou hast loved me may be in them and i in them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 1, 'When Jesus had spoken these words, he went forth with his disciples over the brook Cedron, where was a garden, into the which he entered, and his disciples.', 'when jesus had spoken these words he went forth with his disciples over the brook cedron where was a garden into the which he entered and his disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 2, 'And Judas also, which betrayed him, knew the place: for Jesus ofttimes resorted thither with his disciples.', 'and judas also which betrayed him knew the place for jesus ofttimes resorted thither with his disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 3, 'Judas then, having received a band {of men} and officers from the chief priests and Pharisees, cometh thither with lanterns and torches and weapons.', 'judas then having received a band of men and officers from the chief priests and pharisees cometh thither with lanterns and torches and weapons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 4, 'Jesus therefore, knowing all things that should come upon him, went forth, and said unto them, Whom seek ye?', 'jesus therefore knowing all things that should come upon him went forth and said unto them whom seek ye');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 5, 'They answered him, Jesus of Nazareth. Jesus saith unto them, I am {he}. And Judas also, which betrayed him, stood with them.', 'they answered him jesus of nazareth jesus saith unto them i am he and judas also which betrayed him stood with them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 6, 'As soon then as he had said unto them, I am {he}, they went backward, and fell to the ground.', 'as soon then as he had said unto them i am he they went backward and fell to the ground');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 7, 'Then asked he them again, Whom seek ye? And they said, Jesus of Nazareth.', 'then asked he them again whom seek ye and they said jesus of nazareth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 8, 'Jesus answered, I have told you that I am {he}: if therefore ye seek me, let these go their way:', 'jesus answered i have told you that i am he if therefore ye seek me let these go their way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 9, 'That the saying might be fulfilled, which he spake, Of them which thou gavest me have I lost none.', 'that the saying might be fulfilled which he spake of them which thou gavest me have i lost none');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 10, 'Then Simon Peter having a sword drew it, and smote the high priest''s servant, and cut off his right ear. The servant''s name was Malchus.', 'then simon peter having a sword drew it and smote the high priest s servant and cut off his right ear the servant s name was malchus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 11, 'Then said Jesus unto Peter, Put up thy sword into the sheath: the cup which my Father hath given me, shall I not drink it?', 'then said jesus unto peter put up thy sword into the sheath the cup which my father hath given me shall i not drink it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 12, 'Then the band and the captain and officers of the Jews took Jesus, and bound him,', 'then the band and the captain and officers of the jews took jesus and bound him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 13, 'And led him away to Annas first; for he was father in law to Caiaphas, which was the high priest that same year. {year: year. And Annas sent Christ bound unto Caiaphas the high priest}', 'and led him away to annas first for he was father in law to caiaphas which was the high priest that same year year year and annas sent christ bound unto caiaphas the high priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 14, 'Now Caiaphas was he, which gave counsel to the Jews, that it was expedient that one man should die for the people.', 'now caiaphas was he which gave counsel to the jews that it was expedient that one man should die for the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 15, 'And Simon Peter followed Jesus, and {so did} another disciple: that disciple was known unto the high priest, and went in with Jesus into the palace of the high priest.', 'and simon peter followed jesus and so did another disciple that disciple was known unto the high priest and went in with jesus into the palace of the high priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 16, 'But Peter stood at the door without. Then went out that other disciple, which was known unto the high priest, and spake unto her that kept the door, and brought in Peter.', 'but peter stood at the door without then went out that other disciple which was known unto the high priest and spake unto her that kept the door and brought in peter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 17, 'Then saith the damsel that kept the door unto Peter, Art not thou also {one} of this man''s disciples? He saith, I am not.', 'then saith the damsel that kept the door unto peter art not thou also one of this man s disciples he saith i am not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 18, 'And the servants and officers stood there, who had made a fire of coals; for it was cold: and they warmed themselves: and Peter stood with them, and warmed himself.', 'and the servants and officers stood there who had made a fire of coals for it was cold and they warmed themselves and peter stood with them and warmed himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 19, 'The high priest then asked Jesus of his disciples, and of his doctrine.', 'the high priest then asked jesus of his disciples and of his doctrine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 20, 'Jesus answered him, I spake openly to the world; I ever taught in the synagogue, and in the temple, whither the Jews always resort; and in secret have I said nothing.', 'jesus answered him i spake openly to the world i ever taught in the synagogue and in the temple whither the jews always resort and in secret have i said nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 21, 'Why askest thou me? ask them which heard me, what I have said unto them: behold, they know what I said.', 'why askest thou me ask them which heard me what i have said unto them behold they know what i said');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 22, 'And when he had thus spoken, one of the officers which stood by struck Jesus with the palm of his hand, saying, Answerest thou the high priest so? {with...: or, with a rod}', 'and when he had thus spoken one of the officers which stood by struck jesus with the palm of his hand saying answerest thou the high priest so with or with a rod');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 23, 'Jesus answered him, If I have spoken evil, bear witness of the evil: but if well, why smitest thou me?', 'jesus answered him if i have spoken evil bear witness of the evil but if well why smitest thou me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 24, 'Now Annas had sent him bound unto Caiaphas the high priest.', 'now annas had sent him bound unto caiaphas the high priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 25, 'And Simon Peter stood and warmed himself. They said therefore unto him, Art not thou also {one} of his disciples? He denied {it}, and said, I am not.', 'and simon peter stood and warmed himself they said therefore unto him art not thou also one of his disciples he denied it and said i am not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 26, 'One of the servants of the high priest, being {his} kinsman whose ear Peter cut off, saith, Did not I see thee in the garden with him?', 'one of the servants of the high priest being his kinsman whose ear peter cut off saith did not i see thee in the garden with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 27, 'Peter then denied again: and immediately the cock crew.', 'peter then denied again and immediately the cock crew');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 28, 'Then led they Jesus from Caiaphas unto the hall of judgment: and it was early; and they themselves went not into the judgment hall, lest they should be defiled; but that they might eat the passover. {the hall...: or, Pilate''s house}', 'then led they jesus from caiaphas unto the hall of judgment and it was early and they themselves went not into the judgment hall lest they should be defiled but that they might eat the passover the hall or pilate s house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 29, 'Pilate then went out unto them, and said, What accusation bring ye against this man?', 'pilate then went out unto them and said what accusation bring ye against this man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 30, 'They answered and said unto him, If he were not a malefactor, we would not have delivered him up unto thee.', 'they answered and said unto him if he were not a malefactor we would not have delivered him up unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 31, 'Then said Pilate unto them, Take ye him, and judge him according to your law. The Jews therefore said unto him, It is not lawful for us to put any man to death:', 'then said pilate unto them take ye him and judge him according to your law the jews therefore said unto him it is not lawful for us to put any man to death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 32, 'That the saying of Jesus might be fulfilled, which he spake, signifying what death he should die.', 'that the saying of jesus might be fulfilled which he spake signifying what death he should die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 33, 'Then Pilate entered into the judgment hall again, and called Jesus, and said unto him, Art thou the King of the Jews?', 'then pilate entered into the judgment hall again and called jesus and said unto him art thou the king of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 34, 'Jesus answered him, Sayest thou this thing of thyself, or did others tell it thee of me?', 'jesus answered him sayest thou this thing of thyself or did others tell it thee of me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 35, 'Pilate answered, Am I a Jew? Thine own nation and the chief priests have delivered thee unto me: what hast thou done?', 'pilate answered am i a jew thine own nation and the chief priests have delivered thee unto me what hast thou done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 36, 'Jesus answered, My kingdom is not of this world: if my kingdom were of this world, then would my servants fight, that I should not be delivered to the Jews: but now is my kingdom not from hence.', 'jesus answered my kingdom is not of this world if my kingdom were of this world then would my servants fight that i should not be delivered to the jews but now is my kingdom not from hence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 37, 'Pilate therefore said unto him, Art thou a king then? Jesus answered, Thou sayest that I am a king. To this end was I born, and for this cause came I into the world, that I should bear witness unto the truth. Every one that is of the truth heareth my voice.', 'pilate therefore said unto him art thou a king then jesus answered thou sayest that i am a king to this end was i born and for this cause came i into the world that i should bear witness unto the truth every one that is of the truth heareth my voice');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 38, 'Pilate saith unto him, What is truth? And when he had said this, he went out again unto the Jews, and saith unto them, I find in him no fault {at all}.', 'pilate saith unto him what is truth and when he had said this he went out again unto the jews and saith unto them i find in him no fault at all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 39, 'But ye have a custom, that I should release unto you one at the passover: will ye therefore that I release unto you the King of the Jews?', 'but ye have a custom that i should release unto you one at the passover will ye therefore that i release unto you the king of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 18, 40, 'Then cried they all again, saying, Not this man, but Barabbas. Now Barabbas was a robber.', 'then cried they all again saying not this man but barabbas now barabbas was a robber');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 1, 'Then Pilate therefore took Jesus, and scourged {him}.', 'then pilate therefore took jesus and scourged him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 2, 'And the soldiers platted a crown of thorns, and put {it} on his head, and they put on him a purple robe,', 'and the soldiers platted a crown of thorns and put it on his head and they put on him a purple robe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 3, 'And said, Hail, King of the Jews! and they smote him with their hands.', 'and said hail king of the jews and they smote him with their hands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 4, 'Pilate therefore went forth again, and saith unto them, Behold, I bring him forth to you, that ye may know that I find no fault in him.', 'pilate therefore went forth again and saith unto them behold i bring him forth to you that ye may know that i find no fault in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 5, 'Then came Jesus forth, wearing the crown of thorns, and the purple robe. And {Pilate} saith unto them, Behold the man!', 'then came jesus forth wearing the crown of thorns and the purple robe and pilate saith unto them behold the man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 6, 'When the chief priests therefore and officers saw him, they cried out, saying, Crucify {him}, crucify {him}. Pilate saith unto them, Take ye him, and crucify {him}: for I find no fault in him.', 'when the chief priests therefore and officers saw him they cried out saying crucify him crucify him pilate saith unto them take ye him and crucify him for i find no fault in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 7, 'The Jews answered him, We have a law, and by our law he ought to die, because he made himself the Son of God.', 'the jews answered him we have a law and by our law he ought to die because he made himself the son of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 8, 'When Pilate therefore heard that saying, he was the more afraid;', 'when pilate therefore heard that saying he was the more afraid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 9, 'And went again into the judgment hall, and saith unto Jesus, Whence art thou? But Jesus gave him no answer.', 'and went again into the judgment hall and saith unto jesus whence art thou but jesus gave him no answer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 10, 'Then saith Pilate unto him, Speakest thou not unto me? knowest thou not that I have power to crucify thee, and have power to release thee?', 'then saith pilate unto him speakest thou not unto me knowest thou not that i have power to crucify thee and have power to release thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 11, 'Jesus answered, Thou couldest have no power {at all} against me, except it were given thee from above: therefore he that delivered me unto thee hath the greater sin.', 'jesus answered thou couldest have no power at all against me except it were given thee from above therefore he that delivered me unto thee hath the greater sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 12, 'And from thenceforth Pilate sought to release him: but the Jews cried out, saying, If thou let this man go, thou art not Caesar''s friend: whosoever maketh himself a king speaketh against Caesar.', 'and from thenceforth pilate sought to release him but the jews cried out saying if thou let this man go thou art not caesar s friend whosoever maketh himself a king speaketh against caesar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 13, 'When Pilate therefore heard that saying, he brought Jesus forth, and sat down in the judgment seat in a place that is called the Pavement, but in the Hebrew, Gabbatha.', 'when pilate therefore heard that saying he brought jesus forth and sat down in the judgment seat in a place that is called the pavement but in the hebrew gabbatha');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 14, 'And it was the preparation of the passover, and about the sixth hour: and he saith unto the Jews, Behold your King!', 'and it was the preparation of the passover and about the sixth hour and he saith unto the jews behold your king');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 15, 'But they cried out, Away with {him}, away with {him}, crucify him. Pilate saith unto them, Shall I crucify your King? The chief priests answered, We have no king but Caesar.', 'but they cried out away with him away with him crucify him pilate saith unto them shall i crucify your king the chief priests answered we have no king but caesar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 16, 'Then delivered he him therefore unto them to be crucified. And they took Jesus, and led {him} away.', 'then delivered he him therefore unto them to be crucified and they took jesus and led him away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 17, 'And he bearing his cross went forth into a place called {the place} of a skull, which is called in the Hebrew Golgotha:', 'and he bearing his cross went forth into a place called the place of a skull which is called in the hebrew golgotha');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 18, 'Where they crucified him, and two other with him, on either side one, and Jesus in the midst.', 'where they crucified him and two other with him on either side one and jesus in the midst');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 19, 'And Pilate wrote a title, and put {it} on the cross. And the writing was, JESUS OF NAZARETH THE KING OF THE JEWS.', 'and pilate wrote a title and put it on the cross and the writing was jesus of nazareth the king of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 20, 'This title then read many of the Jews: for the place where Jesus was crucified was nigh to the city: and it was written in Hebrew, {and} Greek, {and} Latin.', 'this title then read many of the jews for the place where jesus was crucified was nigh to the city and it was written in hebrew and greek and latin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 21, 'Then said the chief priests of the Jews to Pilate, Write not, The King of the Jews; but that he said, I am King of the Jews.', 'then said the chief priests of the jews to pilate write not the king of the jews but that he said i am king of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 22, 'Pilate answered, What I have written I have written.', 'pilate answered what i have written i have written');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 23, 'Then the soldiers, when they had crucified Jesus, took his garments, and made four parts, to every soldier a part; and also {his} coat: now the coat was without seam, woven from the top throughout. {woven: or, wrought}', 'then the soldiers when they had crucified jesus took his garments and made four parts to every soldier a part and also his coat now the coat was without seam woven from the top throughout woven or wrought');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 24, 'They said therefore among themselves, Let us not rend it, but cast lots for it, whose it shall be: that the scripture might be fulfilled, which saith, They parted my raiment among them, and for my vesture they did cast lots. These things therefore the soldiers did.', 'they said therefore among themselves let us not rend it but cast lots for it whose it shall be that the scripture might be fulfilled which saith they parted my raiment among them and for my vesture they did cast lots these things therefore the soldiers did');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 25, 'Now there stood by the cross of Jesus his mother, and his mother''s sister, Mary the {wife} of Cleophas, and Mary Magdalene. {Cleophas: or, Clopas}', 'now there stood by the cross of jesus his mother and his mother s sister mary the wife of cleophas and mary magdalene cleophas or clopas');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 26, 'When Jesus therefore saw his mother, and the disciple standing by, whom he loved, he saith unto his mother, Woman, behold thy son!', 'when jesus therefore saw his mother and the disciple standing by whom he loved he saith unto his mother woman behold thy son');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 27, 'Then saith he to the disciple, Behold thy mother! And from that hour that disciple took her unto his own {home}.', 'then saith he to the disciple behold thy mother and from that hour that disciple took her unto his own home');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 28, 'After this, Jesus knowing that all things were now accomplished, that the scripture might be fulfilled, saith, I thirst.', 'after this jesus knowing that all things were now accomplished that the scripture might be fulfilled saith i thirst');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 29, 'Now there was set a vessel full of vinegar: and they filled a spunge with vinegar, and put {it} upon hyssop, and put {it} to his mouth.', 'now there was set a vessel full of vinegar and they filled a spunge with vinegar and put it upon hyssop and put it to his mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 30, 'When Jesus therefore had received the vinegar, he said, It is finished: and he bowed his head, and gave up the ghost.', 'when jesus therefore had received the vinegar he said it is finished and he bowed his head and gave up the ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 31, 'The Jews therefore, because it was the preparation, that the bodies should not remain upon the cross on the sabbath day, (for that sabbath day was an high day,) besought Pilate that their legs might be broken, and {that} they might be taken away.', 'the jews therefore because it was the preparation that the bodies should not remain upon the cross on the sabbath day for that sabbath day was an high day besought pilate that their legs might be broken and that they might be taken away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 32, 'Then came the soldiers, and brake the legs of the first, and of the other which was crucified with him.', 'then came the soldiers and brake the legs of the first and of the other which was crucified with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 33, 'But when they came to Jesus, and saw that he was dead already, they brake not his legs:', 'but when they came to jesus and saw that he was dead already they brake not his legs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 34, 'But one of the soldiers with a spear pierced his side, and forthwith came there out blood and water.', 'but one of the soldiers with a spear pierced his side and forthwith came there out blood and water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 35, 'And he that saw {it} bare record, and his record is true: and he knoweth that he saith true, that ye might believe.', 'and he that saw it bare record and his record is true and he knoweth that he saith true that ye might believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 36, 'For these things were done, that the scripture should be fulfilled, A bone of him shall not be broken.', 'for these things were done that the scripture should be fulfilled a bone of him shall not be broken');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 37, 'And again another scripture saith, They shall look on him whom they pierced.', 'and again another scripture saith they shall look on him whom they pierced');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 38, 'And after this Joseph of Arimathaea, being a disciple of Jesus, but secretly for fear of the Jews, besought Pilate that he might take away the body of Jesus: and Pilate gave {him} leave. He came therefore, and took the body of Jesus.', 'and after this joseph of arimathaea being a disciple of jesus but secretly for fear of the jews besought pilate that he might take away the body of jesus and pilate gave him leave he came therefore and took the body of jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 39, 'And there came also Nicodemus, which at the first came to Jesus by night, and brought a mixture of myrrh and aloes, about an hundred pound {weight}.', 'and there came also nicodemus which at the first came to jesus by night and brought a mixture of myrrh and aloes about an hundred pound weight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 40, 'Then took they the body of Jesus, and wound it in linen clothes with the spices, as the manner of the Jews is to bury.', 'then took they the body of jesus and wound it in linen clothes with the spices as the manner of the jews is to bury');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 41, 'Now in the place where he was crucified there was a garden; and in the garden a new sepulchre, wherein was never man yet laid.', 'now in the place where he was crucified there was a garden and in the garden a new sepulchre wherein was never man yet laid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 19, 42, 'There laid they Jesus therefore because of the Jews'' preparation {day}; for the sepulchre was nigh at hand.', 'there laid they jesus therefore because of the jews preparation day for the sepulchre was nigh at hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 1, 'The first {day} of the week cometh Mary Magdalene early, when it was yet dark, unto the sepulchre, and seeth the stone taken away from the sepulchre.', 'the first day of the week cometh mary magdalene early when it was yet dark unto the sepulchre and seeth the stone taken away from the sepulchre');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 2, 'Then she runneth, and cometh to Simon Peter, and to the other disciple, whom Jesus loved, and saith unto them, They have taken away the Lord out of the sepulchre, and we know not where they have laid him.', 'then she runneth and cometh to simon peter and to the other disciple whom jesus loved and saith unto them they have taken away the lord out of the sepulchre and we know not where they have laid him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 3, 'Peter therefore went forth, and that other disciple, and came to the sepulchre.', 'peter therefore went forth and that other disciple and came to the sepulchre');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 4, 'So they ran both together: and the other disciple did outrun Peter, and came first to the sepulchre.', 'so they ran both together and the other disciple did outrun peter and came first to the sepulchre');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 5, 'And he stooping down, {and looking in}, saw the linen clothes lying; yet went he not in.', 'and he stooping down and looking in saw the linen clothes lying yet went he not in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 6, 'Then cometh Simon Peter following him, and went into the sepulchre, and seeth the linen clothes lie,', 'then cometh simon peter following him and went into the sepulchre and seeth the linen clothes lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 7, 'And the napkin, that was about his head, not lying with the linen clothes, but wrapped together in a place by itself.', 'and the napkin that was about his head not lying with the linen clothes but wrapped together in a place by itself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 8, 'Then went in also that other disciple, which came first to the sepulchre, and he saw, and believed.', 'then went in also that other disciple which came first to the sepulchre and he saw and believed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 9, 'For as yet they knew not the scripture, that he must rise again from the dead.', 'for as yet they knew not the scripture that he must rise again from the dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 10, 'Then the disciples went away again unto their own home.', 'then the disciples went away again unto their own home');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 11, 'But Mary stood without at the sepulchre weeping: and as she wept, she stooped down, {and looked} into the sepulchre,', 'but mary stood without at the sepulchre weeping and as she wept she stooped down and looked into the sepulchre');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 12, 'And seeth two angels in white sitting, the one at the head, and the other at the feet, where the body of Jesus had lain.', 'and seeth two angels in white sitting the one at the head and the other at the feet where the body of jesus had lain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 13, 'And they say unto her, Woman, why weepest thou? She saith unto them, Because they have taken away my Lord, and I know not where they have laid him.', 'and they say unto her woman why weepest thou she saith unto them because they have taken away my lord and i know not where they have laid him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 14, 'And when she had thus said, she turned herself back, and saw Jesus standing, and knew not that it was Jesus.', 'and when she had thus said she turned herself back and saw jesus standing and knew not that it was jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 15, 'Jesus saith unto her, Woman, why weepest thou? whom seekest thou? She, supposing him to be the gardener, saith unto him, Sir, if thou have borne him hence, tell me where thou hast laid him, and I will take him away.', 'jesus saith unto her woman why weepest thou whom seekest thou she supposing him to be the gardener saith unto him sir if thou have borne him hence tell me where thou hast laid him and i will take him away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 16, 'Jesus saith unto her, Mary. She turned herself, and saith unto him, Rabboni; which is to say, Master.', 'jesus saith unto her mary she turned herself and saith unto him rabboni which is to say master');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 17, 'Jesus saith unto her, Touch me not; for I am not yet ascended to my Father: but go to my brethren, and say unto them, I ascend unto my Father, and your Father; and {to} my God, and your God.', 'jesus saith unto her touch me not for i am not yet ascended to my father but go to my brethren and say unto them i ascend unto my father and your father and to my god and your god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 18, 'Mary Magdalene came and told the disciples that she had seen the Lord, and {that} he had spoken these things unto her.', 'mary magdalene came and told the disciples that she had seen the lord and that he had spoken these things unto her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 19, 'Then the same day at evening, being the first {day} of the week, when the doors were shut where the disciples were assembled for fear of the Jews, came Jesus and stood in the midst, and saith unto them, Peace {be} unto you.', 'then the same day at evening being the first day of the week when the doors were shut where the disciples were assembled for fear of the jews came jesus and stood in the midst and saith unto them peace be unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 20, 'And when he had so said, he shewed unto them {his} hands and his side. Then were the disciples glad, when they saw the Lord.', 'and when he had so said he shewed unto them his hands and his side then were the disciples glad when they saw the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 21, 'Then said Jesus to them again, Peace {be} unto you: as {my} Father hath sent me, even so send I you.', 'then said jesus to them again peace be unto you as my father hath sent me even so send i you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 22, 'And when he had said this, he breathed on {them}, and saith unto them, Receive ye the Holy Ghost:', 'and when he had said this he breathed on them and saith unto them receive ye the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 23, 'Whose soever sins ye remit, they are remitted unto them; {and} whose soever {sins} ye retain, they are retained.', 'whose soever sins ye remit they are remitted unto them and whose soever sins ye retain they are retained');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 24, 'But Thomas, one of the twelve, called Didymus, was not with them when Jesus came.', 'but thomas one of the twelve called didymus was not with them when jesus came');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 25, 'The other disciples therefore said unto him, We have seen the Lord. But he said unto them, Except I shall see in his hands the print of the nails, and put my finger into the print of the nails, and thrust my hand into his side, I will not believe.', 'the other disciples therefore said unto him we have seen the lord but he said unto them except i shall see in his hands the print of the nails and put my finger into the print of the nails and thrust my hand into his side i will not believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 26, 'And after eight days again his disciples were within, and Thomas with them: {then} came Jesus, the doors being shut, and stood in the midst, and said, Peace {be} unto you.', 'and after eight days again his disciples were within and thomas with them then came jesus the doors being shut and stood in the midst and said peace be unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 27, 'Then saith he to Thomas, Reach hither thy finger, and behold my hands; and reach hither thy hand, and thrust {it} into my side: and be not faithless, but believing.', 'then saith he to thomas reach hither thy finger and behold my hands and reach hither thy hand and thrust it into my side and be not faithless but believing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 28, 'And Thomas answered and said unto him, My Lord and my God.', 'and thomas answered and said unto him my lord and my god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 29, 'Jesus saith unto him, Thomas, because thou hast seen me, thou hast believed: blessed {are} they that have not seen, and {yet} have believed.', 'jesus saith unto him thomas because thou hast seen me thou hast believed blessed are they that have not seen and yet have believed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 30, 'And many other signs truly did Jesus in the presence of his disciples, which are not written in this book:', 'and many other signs truly did jesus in the presence of his disciples which are not written in this book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 20, 31, 'But these are written, that ye might believe that Jesus is the Christ, the Son of God; and that believing ye might have life through his name.', 'but these are written that ye might believe that jesus is the christ the son of god and that believing ye might have life through his name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 21, 1, 'After these things Jesus shewed himself again to the disciples at the sea of Tiberias; and on this wise shewed he {himself}.', 'after these things jesus shewed himself again to the disciples at the sea of tiberias and on this wise shewed he himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 21, 2, 'There were together Simon Peter, and Thomas called Didymus, and Nathanael of Cana in Galilee, and the {sons} of Zebedee, and two other of his disciples.', 'there were together simon peter and thomas called didymus and nathanael of cana in galilee and the sons of zebedee and two other of his disciples');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 21, 3, 'Simon Peter saith unto them, I go a fishing. They say unto him, We also go with thee. They went forth, and entered into a ship immediately; and that night they caught nothing.', 'simon peter saith unto them i go a fishing they say unto him we also go with thee they went forth and entered into a ship immediately and that night they caught nothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 21, 4, 'But when the morning was now come, Jesus stood on the shore: but the disciples knew not that it was Jesus.', 'but when the morning was now come jesus stood on the shore but the disciples knew not that it was jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 21, 5, 'Then Jesus saith unto them, Children, have ye any meat? They answered him, No. {Children: or, Sirs}', 'then jesus saith unto them children have ye any meat they answered him no children or sirs');
