INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 43, 'Unknown', 21, 8, 'And the other disciples came in a little ship; (for they were not far from land, but as it were two hundred cubits,) dragging the net with fishes.', 'and the other disciples came in a little ship for they were not far from land but as it were two hundred cubits dragging the net with fishes');
