INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 16, 'Saying, What shall we do to these men? for that indeed a notable miracle hath been done by them {is} manifest to all them that dwell in Jerusalem; and we cannot deny {it}.', 'saying what shall we do to these men for that indeed a notable miracle hath been done by them is manifest to all them that dwell in jerusalem and we cannot deny it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 17, 'But that it spread no further among the people, let us straitly threaten them, that they speak henceforth to no man in this name.', 'but that it spread no further among the people let us straitly threaten them that they speak henceforth to no man in this name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 18, 'And they called them, and commanded them not to speak at all nor teach in the name of Jesus.', 'and they called them and commanded them not to speak at all nor teach in the name of jesus');
