INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 20, 'For we cannot but speak the things which we have seen and heard.', 'for we cannot but speak the things which we have seen and heard');
