INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 24, 'And when they heard that, they lifted up their voice to God with one accord, and said, Lord, thou {art} God, which hast made heaven, and earth, and the sea, and all that in them is:', 'and when they heard that they lifted up their voice to god with one accord and said lord thou art god which hast made heaven and earth and the sea and all that in them is');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 25, 'Who by the mouth of thy servant David hast said, Why did the heathen rage, and the people imagine vain things?', 'who by the mouth of thy servant david hast said why did the heathen rage and the people imagine vain things');
