INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 28, 'For to do whatsoever thy hand and thy counsel determined before to be done.', 'for to do whatsoever thy hand and thy counsel determined before to be done');
