INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 30, 'By stretching forth thine hand to heal; and that signs and wonders may be done by the name of thy holy child Jesus.', 'by stretching forth thine hand to heal and that signs and wonders may be done by the name of thy holy child jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 31, 'And when they had prayed, the place was shaken where they were assembled together; and they were all filled with the Holy Ghost, and they spake the word of God with boldness.', 'and when they had prayed the place was shaken where they were assembled together and they were all filled with the holy ghost and they spake the word of god with boldness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 32, 'And the multitude of them that believed were of one heart and of one soul: neither said any {of them} that ought of the things which he possessed was his own; but they had all things common.', 'and the multitude of them that believed were of one heart and of one soul neither said any of them that ought of the things which he possessed was his own but they had all things common');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 33, 'And with great power gave the apostles witness of the resurrection of the Lord Jesus: and great grace was upon them all.', 'and with great power gave the apostles witness of the resurrection of the lord jesus and great grace was upon them all');
