INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 36, 'And Joses, who by the apostles was surnamed Barnabas, (which is, being interpreted, The son of consolation,) a Levite, {and} of the country of Cyprus,', 'and joses who by the apostles was surnamed barnabas which is being interpreted the son of consolation a levite and of the country of cyprus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 4, 37, 'Having land, sold {it}, and brought the money, and laid {it} at the apostles'' feet.', 'having land sold it and brought the money and laid it at the apostles feet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 1, 'But a certain man named Ananias, with Sapphira his wife, sold a possession,', 'but a certain man named ananias with sapphira his wife sold a possession');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 2, 'And kept back {part} of the price, his wife also being privy {to it}, and brought a certain part, and laid {it} at the apostles'' feet.', 'and kept back part of the price his wife also being privy to it and brought a certain part and laid it at the apostles feet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 3, 'But Peter said, Ananias, why hath Satan filled thine heart to lie to the Holy Ghost, and to keep back {part} of the price of the land? {to lie to: or, to deceive}', 'but peter said ananias why hath satan filled thine heart to lie to the holy ghost and to keep back part of the price of the land to lie to or to deceive');
