INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 5, 'And Ananias hearing these words fell down, and gave up the ghost: and great fear came on all them that heard these things.', 'and ananias hearing these words fell down and gave up the ghost and great fear came on all them that heard these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 6, 'And the young men arose, wound him up, and carried {him} out, and buried {him}.', 'and the young men arose wound him up and carried him out and buried him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 7, 'And it was about the space of three hours after, when his wife, not knowing what was done, came in.', 'and it was about the space of three hours after when his wife not knowing what was done came in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 8, 'And Peter answered unto her, Tell me whether ye sold the land for so much? And she said, Yea, for so much.', 'and peter answered unto her tell me whether ye sold the land for so much and she said yea for so much');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 9, 'Then Peter said unto her, How is it that ye have agreed together to tempt the Spirit of the Lord? behold, the feet of them which have buried thy husband {are} at the door, and shall carry thee out.', 'then peter said unto her how is it that ye have agreed together to tempt the spirit of the lord behold the feet of them which have buried thy husband are at the door and shall carry thee out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 10, 'Then fell she down straightway at his feet, and yielded up the ghost: and the young men came in, and found her dead, and, carrying {her} forth, buried {her} by her husband.', 'then fell she down straightway at his feet and yielded up the ghost and the young men came in and found her dead and carrying her forth buried her by her husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 11, 'And great fear came upon all the church, and upon as many as heard these things.', 'and great fear came upon all the church and upon as many as heard these things');
