INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 5, 16, 'There came also a multitude {out} of the cities round about unto Jerusalem, bringing sick folks, and them which were vexed with unclean spirits: and they were healed every one.', 'there came also a multitude out of the cities round about unto jerusalem bringing sick folks and them which were vexed with unclean spirits and they were healed every one');
