INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 47, 'But Solomon built him an house.', 'but solomon built him an house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 48, 'Howbeit the most High dwelleth not in temples made with hands; as saith the prophet,', 'howbeit the most high dwelleth not in temples made with hands as saith the prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 49, 'Heaven {is} my throne, and earth {is} my footstool: what house will ye build me? saith the Lord: or what {is} the place of my rest?', 'heaven is my throne and earth is my footstool what house will ye build me saith the lord or what is the place of my rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 50, 'Hath not my hand made all these things?', 'hath not my hand made all these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 51, 'Ye stiffnecked and uncircumcised in heart and ears, ye do always resist the Holy Ghost: as your fathers {did}, so {do} ye.', 'ye stiffnecked and uncircumcised in heart and ears ye do always resist the holy ghost as your fathers did so do ye');
