INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 59, 'And they stoned Stephen, calling upon {God}, and saying, Lord Jesus, receive my spirit.', 'and they stoned stephen calling upon god and saying lord jesus receive my spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 7, 60, 'And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep.', 'and he kneeled down and cried with a loud voice lord lay not this sin to their charge and when he had said this he fell asleep');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 1, 'And Saul was consenting unto his death. And at that time there was a great persecution against the church which was at Jerusalem; and they were all scattered abroad throughout the regions of Judaea and Samaria, except the apostles.', 'and saul was consenting unto his death and at that time there was a great persecution against the church which was at jerusalem and they were all scattered abroad throughout the regions of judaea and samaria except the apostles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 2, 'And devout men carried Stephen {to his burial}, and made great lamentation over him.', 'and devout men carried stephen to his burial and made great lamentation over him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 3, 'As for Saul, he made havock of the church, entering into every house, and haling men and women committed {them} to prison.', 'as for saul he made havock of the church entering into every house and haling men and women committed them to prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 4, 'Therefore they that were scattered abroad went every where preaching the word.', 'therefore they that were scattered abroad went every where preaching the word');
