INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 6, 'And the people with one accord gave heed unto those things which Philip spake, hearing and seeing the miracles which he did.', 'and the people with one accord gave heed unto those things which philip spake hearing and seeing the miracles which he did');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 7, 'For unclean spirits, crying with loud voice, came out of many that were possessed {with them}: and many taken with palsies, and that were lame, were healed.', 'for unclean spirits crying with loud voice came out of many that were possessed with them and many taken with palsies and that were lame were healed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 8, 'And there was great joy in that city.', 'and there was great joy in that city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 9, 'But there was a certain man, called Simon, which beforetime in the same city used sorcery, and bewitched the people of Samaria, giving out that himself was some great one:', 'but there was a certain man called simon which beforetime in the same city used sorcery and bewitched the people of samaria giving out that himself was some great one');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 10, 'To whom they all gave heed, from the least to the greatest, saying, This man is the great power of God.', 'to whom they all gave heed from the least to the greatest saying this man is the great power of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 11, 'And to him they had regard, because that of long time he had bewitched them with sorceries.', 'and to him they had regard because that of long time he had bewitched them with sorceries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 12, 'But when they believed Philip preaching the things concerning the kingdom of God, and the name of Jesus Christ, they were baptized, both men and women.', 'but when they believed philip preaching the things concerning the kingdom of god and the name of jesus christ they were baptized both men and women');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 13, 'Then Simon himself believed also: and when he was baptized, he continued with Philip, and wondered, beholding the miracles and signs which were done. {miracles...: Gr. signs and great miracles}', 'then simon himself believed also and when he was baptized he continued with philip and wondered beholding the miracles and signs which were done miracles gr signs and great miracles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 14, 'Now when the apostles which were at Jerusalem heard that Samaria had received the word of God, they sent unto them Peter and John:', 'now when the apostles which were at jerusalem heard that samaria had received the word of god they sent unto them peter and john');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 15, 'Who, when they were come down, prayed for them, that they might receive the Holy Ghost:', 'who when they were come down prayed for them that they might receive the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 16, '(For as yet he was fallen upon none of them: only they were baptized in the name of the Lord Jesus.)', 'for as yet he was fallen upon none of them only they were baptized in the name of the lord jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 17, 'Then laid they {their} hands on them, and they received the Holy Ghost.', 'then laid they their hands on them and they received the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 18, 'And when Simon saw that through laying on of the apostles'' hands the Holy Ghost was given, he offered them money,', 'and when simon saw that through laying on of the apostles hands the holy ghost was given he offered them money');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 19, 'Saying, Give me also this power, that on whomsoever I lay hands, he may receive the Holy Ghost.', 'saying give me also this power that on whomsoever i lay hands he may receive the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 20, 'But Peter said unto him, Thy money perish with thee, because thou hast thought that the gift of God may be purchased with money.', 'but peter said unto him thy money perish with thee because thou hast thought that the gift of god may be purchased with money');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 21, 'Thou hast neither part nor lot in this matter: for thy heart is not right in the sight of God.', 'thou hast neither part nor lot in this matter for thy heart is not right in the sight of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 22, 'Repent therefore of this thy wickedness, and pray God, if perhaps the thought of thine heart may be forgiven thee.', 'repent therefore of this thy wickedness and pray god if perhaps the thought of thine heart may be forgiven thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 23, 'For I perceive that thou art in the gall of bitterness, and {in} the bond of iniquity.', 'for i perceive that thou art in the gall of bitterness and in the bond of iniquity');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 24, 'Then answered Simon, and said, Pray ye to the Lord for me, that none of these things which ye have spoken come upon me.', 'then answered simon and said pray ye to the lord for me that none of these things which ye have spoken come upon me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 25, 'And they, when they had testified and preached the word of the Lord, returned to Jerusalem, and preached the gospel in many villages of the Samaritans.', 'and they when they had testified and preached the word of the lord returned to jerusalem and preached the gospel in many villages of the samaritans');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 26, 'And the angel of the Lord spake unto Philip, saying, Arise, and go toward the south unto the way that goeth down from Jerusalem unto Gaza, which is desert.', 'and the angel of the lord spake unto philip saying arise and go toward the south unto the way that goeth down from jerusalem unto gaza which is desert');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 27, 'And he arose and went: and, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship,', 'and he arose and went and behold a man of ethiopia an eunuch of great authority under candace queen of the ethiopians who had the charge of all her treasure and had come to jerusalem for to worship');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 28, 'Was returning, and sitting in his chariot read Esaias the prophet.', 'was returning and sitting in his chariot read esaias the prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 29, 'Then the Spirit said unto Philip, Go near, and join thyself to this chariot.', 'then the spirit said unto philip go near and join thyself to this chariot');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 30, 'And Philip ran thither to {him}, and heard him read the prophet Esaias, and said, Understandest thou what thou readest?', 'and philip ran thither to him and heard him read the prophet esaias and said understandest thou what thou readest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 31, 'And he said, How can I, except some man should guide me? And he desired Philip that he would come up and sit with him.', 'and he said how can i except some man should guide me and he desired philip that he would come up and sit with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 32, 'The place of the scripture which he read was this, He was led as a sheep to the slaughter; and like a lamb dumb before his shearer, so opened he not his mouth:', 'the place of the scripture which he read was this he was led as a sheep to the slaughter and like a lamb dumb before his shearer so opened he not his mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 33, 'In his humiliation his judgment was taken away: and who shall declare his generation? for his life is taken from the earth.', 'in his humiliation his judgment was taken away and who shall declare his generation for his life is taken from the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 34, 'And the eunuch answered Philip, and said, I pray thee, of whom speaketh the prophet this? of himself, or of some other man?', 'and the eunuch answered philip and said i pray thee of whom speaketh the prophet this of himself or of some other man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 35, 'Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus.', 'then philip opened his mouth and began at the same scripture and preached unto him jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 36, 'And as they went on {their} way, they came unto a certain water: and the eunuch said, See, {here is} water; what doth hinder me to be baptized?', 'and as they went on their way they came unto a certain water and the eunuch said see here is water what doth hinder me to be baptized');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 37, 'And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God.', 'and philip said if thou believest with all thine heart thou mayest and he answered and said i believe that jesus christ is the son of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 38, 'And he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him.', 'and he commanded the chariot to stand still and they went down both into the water both philip and the eunuch and he baptized him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 39, 'And when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing.', 'and when they were come up out of the water the spirit of the lord caught away philip that the eunuch saw him no more and he went on his way rejoicing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 8, 40, 'But Philip was found at Azotus: and passing through he preached in all the cities, till he came to Caesarea.', 'but philip was found at azotus and passing through he preached in all the cities till he came to caesarea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 1, 'And Saul, yet breathing out threatenings and slaughter against the disciples of the Lord, went unto the high priest,', 'and saul yet breathing out threatenings and slaughter against the disciples of the lord went unto the high priest');
