INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 3, 'And as he journeyed, he came near Damascus: and suddenly there shined round about him a light from heaven:', 'and as he journeyed he came near damascus and suddenly there shined round about him a light from heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 4, 'And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?', 'and he fell to the earth and heard a voice saying unto him saul saul why persecutest thou me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 5, 'And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: {it is} hard for thee to kick against the pricks.', 'and he said who art thou lord and the lord said i am jesus whom thou persecutest it is hard for thee to kick against the pricks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 6, 'And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord {said} unto him, Arise, and go into the city, and it shall be told thee what thou must do.', 'and he trembling and astonished said lord what wilt thou have me to do and the lord said unto him arise and go into the city and it shall be told thee what thou must do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 7, 'And the men which journeyed with him stood speechless, hearing a voice, but seeing no man.', 'and the men which journeyed with him stood speechless hearing a voice but seeing no man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 8, 'And Saul arose from the earth; and when his eyes were opened, he saw no man: but they led him by the hand, and brought {him} into Damascus.', 'and saul arose from the earth and when his eyes were opened he saw no man but they led him by the hand and brought him into damascus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 9, 'And he was three days without sight, and neither did eat nor drink.', 'and he was three days without sight and neither did eat nor drink');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 10, 'And there was a certain disciple at Damascus, named Ananias; and to him said the Lord in a vision, Ananias. And he said, Behold, I {am here}, Lord.', 'and there was a certain disciple at damascus named ananias and to him said the lord in a vision ananias and he said behold i am here lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 11, 'And the Lord {said} unto him, Arise, and go into the street which is called Straight, and enquire in the house of Judas for {one} called Saul, of Tarsus: for, behold, he prayeth,', 'and the lord said unto him arise and go into the street which is called straight and enquire in the house of judas for one called saul of tarsus for behold he prayeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 12, 'And hath seen in a vision a man named Ananias coming in, and putting {his} hand on him, that he might receive his sight.', 'and hath seen in a vision a man named ananias coming in and putting his hand on him that he might receive his sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 13, 'Then Ananias answered, Lord, I have heard by many of this man, how much evil he hath done to thy saints at Jerusalem:', 'then ananias answered lord i have heard by many of this man how much evil he hath done to thy saints at jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 14, 'And here he hath authority from the chief priests to bind all that call on thy name.', 'and here he hath authority from the chief priests to bind all that call on thy name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 15, 'But the Lord said unto him, Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel:', 'but the lord said unto him go thy way for he is a chosen vessel unto me to bear my name before the gentiles and kings and the children of israel');
