INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 17, 'And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, {even} Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost.', 'and ananias went his way and entered into the house and putting his hands on him said brother saul the lord even jesus that appeared unto thee in the way as thou camest hath sent me that thou mightest receive thy sight and be filled with the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 18, 'And immediately there fell from his eyes as it had been scales: and he received sight forthwith, and arose, and was baptized.', 'and immediately there fell from his eyes as it had been scales and he received sight forthwith and arose and was baptized');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 19, 'And when he had received meat, he was strengthened. Then was Saul certain days with the disciples which were at Damascus.', 'and when he had received meat he was strengthened then was saul certain days with the disciples which were at damascus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 9, 20, 'And straightway he preached Christ in the synagogues, that he is the Son of God.', 'and straightway he preached christ in the synagogues that he is the son of god');
