INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 2, '{A} devout {man}, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway.', 'a devout man and one that feared god with all his house which gave much alms to the people and prayed to god alway');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 3, 'He saw in a vision evidently about the ninth hour of the day an angel of God coming in to him, and saying unto him, Cornelius.', 'he saw in a vision evidently about the ninth hour of the day an angel of god coming in to him and saying unto him cornelius');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 4, 'And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God.', 'and when he looked on him he was afraid and said what is it lord and he said unto him thy prayers and thine alms are come up for a memorial before god');
