INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 7, 'And when the angel which spake unto Cornelius was departed, he called two of his household servants, and a devout soldier of them that waited on him continually;', 'and when the angel which spake unto cornelius was departed he called two of his household servants and a devout soldier of them that waited on him continually');
