INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 12, 'Wherein were all manner of fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air.', 'wherein were all manner of fourfooted beasts of the earth and wild beasts and creeping things and fowls of the air');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 13, 'And there came a voice to him, Rise, Peter; kill, and eat.', 'and there came a voice to him rise peter kill and eat');
