INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 15, 'And the voice {spake} unto him again the second time, What God hath cleansed, {that} call not thou common.', 'and the voice spake unto him again the second time what god hath cleansed that call not thou common');
