INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 17, 'Now while Peter doubted in himself what this vision which he had seen should mean, behold, the men which were sent from Cornelius had made enquiry for Simon''s house, and stood before the gate,', 'now while peter doubted in himself what this vision which he had seen should mean behold the men which were sent from cornelius had made enquiry for simon s house and stood before the gate');
