INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 24, 'And the morrow after they entered into Caesarea. And Cornelius waited for them, and had called together his kinsmen and near friends.', 'and the morrow after they entered into caesarea and cornelius waited for them and had called together his kinsmen and near friends');
