INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 27, 'And as he talked with him, he went in, and found many that were come together.', 'and as he talked with him he went in and found many that were come together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 28, 'And he said unto them, Ye know how that it is an unlawful thing for a man that is a Jew to keep company, or come unto one of another nation; but God hath shewed me that I should not call any man common or unclean.', 'and he said unto them ye know how that it is an unlawful thing for a man that is a jew to keep company or come unto one of another nation but god hath shewed me that i should not call any man common or unclean');
