INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 30, 'And Cornelius said, Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house, and, behold, a man stood before me in bright clothing,', 'and cornelius said four days ago i was fasting until this hour and at the ninth hour i prayed in my house and behold a man stood before me in bright clothing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 31, 'And said, Cornelius, thy prayer is heard, and thine alms are had in remembrance in the sight of God.', 'and said cornelius thy prayer is heard and thine alms are had in remembrance in the sight of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 32, 'Send therefore to Joppa, and call hither Simon, whose surname is Peter; he is lodged in the house of {one} Simon a tanner by the sea side: who, when he cometh, shall speak unto thee.', 'send therefore to joppa and call hither simon whose surname is peter he is lodged in the house of one simon a tanner by the sea side who when he cometh shall speak unto thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 33, 'Immediately therefore I sent to thee; and thou hast well done that thou art come. Now therefore are we all here present before God, to hear all things that are commanded thee of God.', 'immediately therefore i sent to thee and thou hast well done that thou art come now therefore are we all here present before god to hear all things that are commanded thee of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 34, 'Then Peter opened {his} mouth, and said, Of a truth I perceive that God is no respecter of persons:', 'then peter opened his mouth and said of a truth i perceive that god is no respecter of persons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 35, 'But in every nation he that feareth him, and worketh righteousness, is accepted with him.', 'but in every nation he that feareth him and worketh righteousness is accepted with him');
