INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 38, 'How God anointed Jesus of Nazareth with the Holy Ghost and with power: who went about doing good, and healing all that were oppressed of the devil; for God was with him.', 'how god anointed jesus of nazareth with the holy ghost and with power who went about doing good and healing all that were oppressed of the devil for god was with him');
