INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 43, 'To him give all the prophets witness, that through his name whosoever believeth in him shall receive remission of sins.', 'to him give all the prophets witness that through his name whosoever believeth in him shall receive remission of sins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 44, 'While Peter yet spake these words, the Holy Ghost fell on all them which heard the word.', 'while peter yet spake these words the holy ghost fell on all them which heard the word');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 10, 45, 'And they of the circumcision which believed were astonished, as many as came with Peter, because that on the Gentiles also was poured out the gift of the Holy Ghost.', 'and they of the circumcision which believed were astonished as many as came with peter because that on the gentiles also was poured out the gift of the holy ghost');
