INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 1, 'And the apostles and brethren that were in Judaea heard that the Gentiles had also received the word of God.', 'and the apostles and brethren that were in judaea heard that the gentiles had also received the word of god');
