INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 3, 'Saying, Thou wentest in to men uncircumcised, and didst eat with them.', 'saying thou wentest in to men uncircumcised and didst eat with them');
