INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 5, 'I was in the city of Joppa praying: and in a trance I saw a vision, A certain vessel descend, as it had been a great sheet, let down from heaven by four corners; and it came even to me:', 'i was in the city of joppa praying and in a trance i saw a vision a certain vessel descend as it had been a great sheet let down from heaven by four corners and it came even to me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 6, 'Upon the which when I had fastened mine eyes, I considered, and saw fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air.', 'upon the which when i had fastened mine eyes i considered and saw fourfooted beasts of the earth and wild beasts and creeping things and fowls of the air');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 7, 'And I heard a voice saying unto me, Arise, Peter; slay and eat.', 'and i heard a voice saying unto me arise peter slay and eat');
