INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 10, 'And this was done three times: and all were drawn up again into heaven.', 'and this was done three times and all were drawn up again into heaven');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 11, 'And, behold, immediately there were three men already come unto the house where I was, sent from Caesarea unto me.', 'and behold immediately there were three men already come unto the house where i was sent from caesarea unto me');
