INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 13, 'And he shewed us how he had seen an angel in his house, which stood and said unto him, Send men to Joppa, and call for Simon, whose surname is Peter;', 'and he shewed us how he had seen an angel in his house which stood and said unto him send men to joppa and call for simon whose surname is peter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 14, 'Who shall tell thee words, whereby thou and all thy house shall be saved.', 'who shall tell thee words whereby thou and all thy house shall be saved');
