INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 16, 'Then remembered I the word of the Lord, how that he said, John indeed baptized with water; but ye shall be baptized with the Holy Ghost.', 'then remembered i the word of the lord how that he said john indeed baptized with water but ye shall be baptized with the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 17, 'Forasmuch then as God gave them the like gift as {he did} unto us, who believed on the Lord Jesus Christ; what was I, that I could withstand God?', 'forasmuch then as god gave them the like gift as he did unto us who believed on the lord jesus christ what was i that i could withstand god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 18, 'When they heard these things, they held their peace, and glorified God, saying, Then hath God also to the Gentiles granted repentance unto life.', 'when they heard these things they held their peace and glorified god saying then hath god also to the gentiles granted repentance unto life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 19, 'Now they which were scattered abroad upon the persecution that arose about Stephen travelled as far as Phenice, and Cyprus, and Antioch, preaching the word to none but unto the Jews only.', 'now they which were scattered abroad upon the persecution that arose about stephen travelled as far as phenice and cyprus and antioch preaching the word to none but unto the jews only');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 20, 'And some of them were men of Cyprus and Cyrene, which, when they were come to Antioch, spake unto the Grecians, preaching the Lord Jesus.', 'and some of them were men of cyprus and cyrene which when they were come to antioch spake unto the grecians preaching the lord jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 21, 'And the hand of the Lord was with them: and a great number believed, and turned unto the Lord.', 'and the hand of the lord was with them and a great number believed and turned unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 22, 'Then tidings of these things came unto the ears of the church which was in Jerusalem: and they sent forth Barnabas, that he should go as far as Antioch.', 'then tidings of these things came unto the ears of the church which was in jerusalem and they sent forth barnabas that he should go as far as antioch');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 23, 'Who, when he came, and had seen the grace of God, was glad, and exhorted them all, that with purpose of heart they would cleave unto the Lord.', 'who when he came and had seen the grace of god was glad and exhorted them all that with purpose of heart they would cleave unto the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 44, 'Unknown', 11, 24, 'For he was a good man, and full of the Holy Ghost and of faith: and much people was added unto the Lord.', 'for he was a good man and full of the holy ghost and of faith and much people was added unto the lord');
