INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 7, 'To all that be in Rome, beloved of God, called {to be} saints: Grace to you and peace from God our Father, and the Lord Jesus Christ.', 'to all that be in rome beloved of god called to be saints grace to you and peace from god our father and the lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 8, 'First, I thank my God through Jesus Christ for you all, that your faith is spoken of throughout the whole world.', 'first i thank my god through jesus christ for you all that your faith is spoken of throughout the whole world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 9, 'For God is my witness, whom I serve with my spirit in the gospel of his Son, that without ceasing I make mention of you always in my prayers; {with: or, in}', 'for god is my witness whom i serve with my spirit in the gospel of his son that without ceasing i make mention of you always in my prayers with or in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 10, 'Making request, if by any means now at length I might have a prosperous journey by the will of God to come unto you.', 'making request if by any means now at length i might have a prosperous journey by the will of god to come unto you');
