INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 13, 'Now I would not have you ignorant, brethren, that oftentimes I purposed to come unto you, (but was let hitherto,) that I might have some fruit among you also, even as among other Gentiles. {among: or, in}', 'now i would not have you ignorant brethren that oftentimes i purposed to come unto you but was let hitherto that i might have some fruit among you also even as among other gentiles among or in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 14, 'I am debtor both to the Greeks, and to the Barbarians; both to the wise, and to the unwise.', 'i am debtor both to the greeks and to the barbarians both to the wise and to the unwise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 15, 'So, as much as in me is, I am ready to preach the gospel to you that are at Rome also.', 'so as much as in me is i am ready to preach the gospel to you that are at rome also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 16, 'For I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth; to the Jew first, and also to the Greek.', 'for i am not ashamed of the gospel of christ for it is the power of god unto salvation to every one that believeth to the jew first and also to the greek');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 17, 'For therein is the righteousness of God revealed from faith to faith: as it is written, The just shall live by faith.', 'for therein is the righteousness of god revealed from faith to faith as it is written the just shall live by faith');
