INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 20, 'For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, {even} his eternal power and Godhead; so that they are without excuse: {so...: or, that they may be}', 'for the invisible things of him from the creation of the world are clearly seen being understood by the things that are made even his eternal power and godhead so that they are without excuse so or that they may be');
