INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 23, 'And changed the glory of the uncorruptible God into an image made like to corruptible man, and to birds, and fourfooted beasts, and creeping things.', 'and changed the glory of the uncorruptible god into an image made like to corruptible man and to birds and fourfooted beasts and creeping things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 24, 'Wherefore God also gave them up to uncleanness through the lusts of their own hearts, to dishonour their own bodies between themselves:', 'wherefore god also gave them up to uncleanness through the lusts of their own hearts to dishonour their own bodies between themselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 25, 'Who changed the truth of God into a lie, and worshipped and served the creature more than the Creator, who is blessed for ever. Amen. {more: or, rather}', 'who changed the truth of god into a lie and worshipped and served the creature more than the creator who is blessed for ever amen more or rather');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 1, 26, 'For this cause God gave them up unto vile affections: for even their women did change the natural use into that which is against nature:', 'for this cause god gave them up unto vile affections for even their women did change the natural use into that which is against nature');
