INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 2, 1, 'Therefore thou art inexcusable, O man, whosoever thou art that judgest: for wherein thou judgest another, thou condemnest thyself; for thou that judgest doest the same things.', 'therefore thou art inexcusable o man whosoever thou art that judgest for wherein thou judgest another thou condemnest thyself for thou that judgest doest the same things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 2, 2, 'But we are sure that the judgment of God is according to truth against them which commit such things.', 'but we are sure that the judgment of god is according to truth against them which commit such things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 2, 3, 'And thinkest thou this, O man, that judgest them which do such things, and doest the same, that thou shalt escape the judgment of God?', 'and thinkest thou this o man that judgest them which do such things and doest the same that thou shalt escape the judgment of god');
