INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 3, 'For what if some did not believe? shall their unbelief make the faith of God without effect?', 'for what if some did not believe shall their unbelief make the faith of god without effect');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 4, 'God forbid: yea, let God be true, but every man a liar; as it is written, That thou mightest be justified in thy sayings, and mightest overcome when thou art judged.', 'god forbid yea let god be true but every man a liar as it is written that thou mightest be justified in thy sayings and mightest overcome when thou art judged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 5, 'But if our unrighteousness commend the righteousness of God, what shall we say? {Is} God unrighteous who taketh vengeance? (I speak as a man)', 'but if our unrighteousness commend the righteousness of god what shall we say is god unrighteous who taketh vengeance i speak as a man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 6, 'God forbid: for then how shall God judge the world?', 'god forbid for then how shall god judge the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 7, 'For if the truth of God hath more abounded through my lie unto his glory; why yet am I also judged as a sinner?', 'for if the truth of god hath more abounded through my lie unto his glory why yet am i also judged as a sinner');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 8, 'And not {rather}, (as we be slanderously reported, and as some affirm that we say,) Let us do evil, that good may come? whose damnation is just.', 'and not rather as we be slanderously reported and as some affirm that we say let us do evil that good may come whose damnation is just');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 9, 'What then? are we better {than they}? No, in no wise: for we have before proved both Jews and Gentiles, that they are all under sin; {proved: Gr. charged}', 'what then are we better than they no in no wise for we have before proved both jews and gentiles that they are all under sin proved gr charged');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 10, 'As it is written, There is none righteous, no, not one:', 'as it is written there is none righteous no not one');
