INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 13, 'Their throat {is} an open sepulchre; with their tongues they have used deceit; the poison of asps {is} under their lips:', 'their throat is an open sepulchre with their tongues they have used deceit the poison of asps is under their lips');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 14, 'Whose mouth {is} full of cursing and bitterness:', 'whose mouth is full of cursing and bitterness');
