INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 19, 'Now we know that what things soever the law saith, it saith to them who are under the law: that every mouth may be stopped, and all the world may become guilty before God. {guilty...: or, subject to the judgment of God}', 'now we know that what things soever the law saith it saith to them who are under the law that every mouth may be stopped and all the world may become guilty before god guilty or subject to the judgment of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 3, 20, 'Therefore by the deeds of the law there shall no flesh be justified in his sight: for by the law {is} the knowledge of sin.', 'therefore by the deeds of the law there shall no flesh be justified in his sight for by the law is the knowledge of sin');
