INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 6, 'Even as David also describeth the blessedness of the man, unto whom God imputeth righteousness without works,', 'even as david also describeth the blessedness of the man unto whom god imputeth righteousness without works');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 7, '{Saying}, Blessed {are} they whose iniquities are forgiven, and whose sins are covered.', 'saying blessed are they whose iniquities are forgiven and whose sins are covered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 8, 'Blessed {is} the man to whom the Lord will not impute sin.', 'blessed is the man to whom the lord will not impute sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 9, '{Cometh} this blessedness then upon the circumcision {only}, or upon the uncircumcision also? for we say that faith was reckoned to Abraham for righteousness.', 'cometh this blessedness then upon the circumcision only or upon the uncircumcision also for we say that faith was reckoned to abraham for righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 10, 'How was it then reckoned? when he was in circumcision, or in uncircumcision? Not in circumcision, but in uncircumcision.', 'how was it then reckoned when he was in circumcision or in uncircumcision not in circumcision but in uncircumcision');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 11, 'And he received the sign of circumcision, a seal of the righteousness of the faith which {he had yet} being uncircumcised: that he might be the father of all them that believe, though they be not circumcised; that righteousness might be imputed unto them also:', 'and he received the sign of circumcision a seal of the righteousness of the faith which he had yet being uncircumcised that he might be the father of all them that believe though they be not circumcised that righteousness might be imputed unto them also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 12, 'And the father of circumcision to them who are not of the circumcision only, but who also walk in the steps of that faith of our father Abraham, which {he had} being {yet} uncircumcised.', 'and the father of circumcision to them who are not of the circumcision only but who also walk in the steps of that faith of our father abraham which he had being yet uncircumcised');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 13, 'For the promise, that he should be the heir of the world, {was} not to Abraham, or to his seed, through the law, but through the righteousness of faith.', 'for the promise that he should be the heir of the world was not to abraham or to his seed through the law but through the righteousness of faith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 14, 'For if they which are of the law {be} heirs, faith is made void, and the promise made of none effect:', 'for if they which are of the law be heirs faith is made void and the promise made of none effect');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 15, 'Because the law worketh wrath: for where no law is, {there is} no transgression.', 'because the law worketh wrath for where no law is there is no transgression');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 16, 'Therefore {it is} of faith, that {it might be} by grace; to the end the promise might be sure to all the seed; not to that only which is of the law, but to that also which is of the faith of Abraham; who is the father of us all,', 'therefore it is of faith that it might be by grace to the end the promise might be sure to all the seed not to that only which is of the law but to that also which is of the faith of abraham who is the father of us all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 17, '(As it is written, I have made thee a father of many nations,) before him whom he believed, {even} God, who quickeneth the dead, and calleth those things which be not as though they were. {before him: or, like unto him}', 'as it is written i have made thee a father of many nations before him whom he believed even god who quickeneth the dead and calleth those things which be not as though they were before him or like unto him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 18, 'Who against hope believed in hope, that he might become the father of many nations, according to that which was spoken, So shall thy seed be.', 'who against hope believed in hope that he might become the father of many nations according to that which was spoken so shall thy seed be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 19, 'And being not weak in faith, he considered not his own body now dead, when he was about an hundred years old, neither yet the deadness of Sara''s womb:', 'and being not weak in faith he considered not his own body now dead when he was about an hundred years old neither yet the deadness of sara s womb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 20, 'He staggered not at the promise of God through unbelief; but was strong in faith, giving glory to God;', 'he staggered not at the promise of god through unbelief but was strong in faith giving glory to god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 21, 'And being fully persuaded that, what he had promised, he was able also to perform.', 'and being fully persuaded that what he had promised he was able also to perform');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 22, 'And therefore it was imputed to him for righteousness.', 'and therefore it was imputed to him for righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 23, 'Now it was not written for his sake alone, that it was imputed to him;', 'now it was not written for his sake alone that it was imputed to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 24, 'But for us also, to whom it shall be imputed, if we believe on him that raised up Jesus our Lord from the dead;', 'but for us also to whom it shall be imputed if we believe on him that raised up jesus our lord from the dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 4, 25, 'Who was delivered for our offences, and was raised again for our justification.', 'who was delivered for our offences and was raised again for our justification');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 1, 'Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:', 'therefore being justified by faith we have peace with god through our lord jesus christ');
