INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 3, 'And not only {so}, but we glory in tribulations also: knowing that tribulation worketh patience;', 'and not only so but we glory in tribulations also knowing that tribulation worketh patience');
