INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 5, 'And hope maketh not ashamed; because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us.', 'and hope maketh not ashamed because the love of god is shed abroad in our hearts by the holy ghost which is given unto us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 6, 'For when we were yet without strength, in due time Christ died for the ungodly. {in due time: or, according to the time}', 'for when we were yet without strength in due time christ died for the ungodly in due time or according to the time');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 7, 'For scarcely for a righteous man will one die: yet peradventure for a good man some would even dare to die.', 'for scarcely for a righteous man will one die yet peradventure for a good man some would even dare to die');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 8, 'But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.', 'but god commendeth his love toward us in that while we were yet sinners christ died for us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 9, 'Much more then, being now justified by his blood, we shall be saved from wrath through him.', 'much more then being now justified by his blood we shall be saved from wrath through him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 10, 'For if, when we were enemies, we were reconciled to God by the death of his Son, much more, being reconciled, we shall be saved by his life.', 'for if when we were enemies we were reconciled to god by the death of his son much more being reconciled we shall be saved by his life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 11, 'And not only {so}, but we also joy in God through our Lord Jesus Christ, by whom we have now received the atonement. {atonement: or, reconciliation}', 'and not only so but we also joy in god through our lord jesus christ by whom we have now received the atonement atonement or reconciliation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 12, 'Wherefore, as by one man sin entered into the world, and death by sin; and so death passed upon all men, for that all have sinned: {for that: or, in whom}', 'wherefore as by one man sin entered into the world and death by sin and so death passed upon all men for that all have sinned for that or in whom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 13, '(For until the law sin was in the world: but sin is not imputed when there is no law.', 'for until the law sin was in the world but sin is not imputed when there is no law');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 14, 'Nevertheless death reigned from Adam to Moses, even over them that had not sinned after the similitude of Adam''s transgression, who is the figure of him that was to come.', 'nevertheless death reigned from adam to moses even over them that had not sinned after the similitude of adam s transgression who is the figure of him that was to come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 15, 'But not as the offence, so also {is} the free gift. For if through the offence of one many be dead, much more the grace of God, and the gift by grace, {which is} by one man, Jesus Christ, hath abounded unto many.', 'but not as the offence so also is the free gift for if through the offence of one many be dead much more the grace of god and the gift by grace which is by one man jesus christ hath abounded unto many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 16, 'And not as {it was} by one that sinned, {so is} the gift: for the judgment {was} by one to condemnation, but the free gift {is} of many offences unto justification.', 'and not as it was by one that sinned so is the gift for the judgment was by one to condemnation but the free gift is of many offences unto justification');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 17, 'For if by one man''s offence death reigned by one; much more they which receive abundance of grace and of the gift of righteousness shall reign in life by one, Jesus Christ.) {by one man''s...: or, by one offence}', 'for if by one man s offence death reigned by one much more they which receive abundance of grace and of the gift of righteousness shall reign in life by one jesus christ by one man s or by one offence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 18, 'Therefore as by the offence of one {judgment came} upon all men to condemnation; even so by the righteousness of one {the free gift came} upon all men unto justification of life. {by the offence...: or, by one offence} {by the righteousness...: or, by one righteousness}', 'therefore as by the offence of one judgment came upon all men to condemnation even so by the righteousness of one the free gift came upon all men unto justification of life by the offence or by one offence by the righteousness or by one righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 19, 'For as by one man''s disobedience many were made sinners, so by the obedience of one shall many be made righteous.', 'for as by one man s disobedience many were made sinners so by the obedience of one shall many be made righteous');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 20, 'Moreover the law entered, that the offence might abound. But where sin abounded, grace did much more abound:', 'moreover the law entered that the offence might abound but where sin abounded grace did much more abound');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 5, 21, 'That as sin hath reigned unto death, even so might grace reign through righteousness unto eternal life by Jesus Christ our Lord.', 'that as sin hath reigned unto death even so might grace reign through righteousness unto eternal life by jesus christ our lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 1, 'What shall we say then? Shall we continue in sin, that grace may abound?', 'what shall we say then shall we continue in sin that grace may abound');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 2, 'God forbid. How shall we, that are dead to sin, live any longer therein?', 'god forbid how shall we that are dead to sin live any longer therein');
