INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 4, 'Therefore we are buried with him by baptism into death: that like as Christ was raised up from the dead by the glory of the Father, even so we also should walk in newness of life.', 'therefore we are buried with him by baptism into death that like as christ was raised up from the dead by the glory of the father even so we also should walk in newness of life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 5, 'For if we have been planted together in the likeness of his death, we shall be also {in the likeness} of {his} resurrection:', 'for if we have been planted together in the likeness of his death we shall be also in the likeness of his resurrection');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 6, 'Knowing this, that our old man is crucified with {him}, that the body of sin might be destroyed, that henceforth we should not serve sin.', 'knowing this that our old man is crucified with him that the body of sin might be destroyed that henceforth we should not serve sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 7, 'For he that is dead is freed from sin. {freed: Gr. justified}', 'for he that is dead is freed from sin freed gr justified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 8, 'Now if we be dead with Christ, we believe that we shall also live with him:', 'now if we be dead with christ we believe that we shall also live with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 9, 'Knowing that Christ being raised from the dead dieth no more; death hath no more dominion over him.', 'knowing that christ being raised from the dead dieth no more death hath no more dominion over him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 10, 'For in that he died, he died unto sin once: but in that he liveth, he liveth unto God.', 'for in that he died he died unto sin once but in that he liveth he liveth unto god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 11, 'Likewise reckon ye also yourselves to be dead indeed unto sin, but alive unto God through Jesus Christ our Lord.', 'likewise reckon ye also yourselves to be dead indeed unto sin but alive unto god through jesus christ our lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 12, 'Let not sin therefore reign in your mortal body, that ye should obey it in the lusts thereof.', 'let not sin therefore reign in your mortal body that ye should obey it in the lusts thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 13, 'Neither yield ye your members {as} instruments of unrighteousness unto sin: but yield yourselves unto God, as those that are alive from the dead, and your members {as} instruments of righteousness unto God. {instruments: Gr. arms, or, weapons}', 'neither yield ye your members as instruments of unrighteousness unto sin but yield yourselves unto god as those that are alive from the dead and your members as instruments of righteousness unto god instruments gr arms or weapons');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 14, 'For sin shall not have dominion over you: for ye are not under the law, but under grace.', 'for sin shall not have dominion over you for ye are not under the law but under grace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 15, 'What then? shall we sin, because we are not under the law, but under grace? God forbid.', 'what then shall we sin because we are not under the law but under grace god forbid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 16, 'Know ye not, that to whom ye yield yourselves servants to obey, his servants ye are to whom ye obey; whether of sin unto death, or of obedience unto righteousness?', 'know ye not that to whom ye yield yourselves servants to obey his servants ye are to whom ye obey whether of sin unto death or of obedience unto righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 17, 'But God be thanked, that ye were the servants of sin, but ye have obeyed from the heart that form of doctrine which was delivered you. {which...: Gr. whereto ye were delivered}', 'but god be thanked that ye were the servants of sin but ye have obeyed from the heart that form of doctrine which was delivered you which gr whereto ye were delivered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 18, 'Being then made free from sin, ye became the servants of righteousness.', 'being then made free from sin ye became the servants of righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 19, 'I speak after the manner of men because of the infirmity of your flesh: for as ye have yielded your members servants to uncleanness and to iniquity unto iniquity; even so now yield your members servants to righteousness unto holiness.', 'i speak after the manner of men because of the infirmity of your flesh for as ye have yielded your members servants to uncleanness and to iniquity unto iniquity even so now yield your members servants to righteousness unto holiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 20, 'For when ye were the servants of sin, ye were free from righteousness. {from...: Gr. to righteousness}', 'for when ye were the servants of sin ye were free from righteousness from gr to righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 21, 'What fruit had ye then in those things whereof ye are now ashamed? for the end of those things {is} death.', 'what fruit had ye then in those things whereof ye are now ashamed for the end of those things is death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 22, 'But now being made free from sin, and become servants to God, ye have your fruit unto holiness, and the end everlasting life.', 'but now being made free from sin and become servants to god ye have your fruit unto holiness and the end everlasting life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 6, 23, 'For the wages of sin {is} death; but the gift of God {is} eternal life through Jesus Christ our Lord.', 'for the wages of sin is death but the gift of god is eternal life through jesus christ our lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 1, 'Know ye not, brethren, (for I speak to them that know the law,) how that the law hath dominion over a man as long as he liveth?', 'know ye not brethren for i speak to them that know the law how that the law hath dominion over a man as long as he liveth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 2, 'For the woman which hath an husband is bound by the law to {her} husband so long as he liveth; but if the husband be dead, she is loosed from the law of {her} husband.', 'for the woman which hath an husband is bound by the law to her husband so long as he liveth but if the husband be dead she is loosed from the law of her husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 3, 'So then if, while {her} husband liveth, she be married to another man, she shall be called an adulteress: but if her husband be dead, she is free from that law; so that she is no adulteress, though she be married to another man.', 'so then if while her husband liveth she be married to another man she shall be called an adulteress but if her husband be dead she is free from that law so that she is no adulteress though she be married to another man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 4, 'Wherefore, my brethren, ye also are become dead to the law by the body of Christ; that ye should be married to another, {even} to him who is raised from the dead, that we should bring forth fruit unto God.', 'wherefore my brethren ye also are become dead to the law by the body of christ that ye should be married to another even to him who is raised from the dead that we should bring forth fruit unto god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 5, 'For when we were in the flesh, the motions of sins, which were by the law, did work in our members to bring forth fruit unto death. {motions: Gr. passions}', 'for when we were in the flesh the motions of sins which were by the law did work in our members to bring forth fruit unto death motions gr passions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 6, 'But now we are delivered from the law, that being dead wherein we were held; that we should serve in newness of spirit, and not {in} the oldness of the letter. {that being...: or, being dead to that}', 'but now we are delivered from the law that being dead wherein we were held that we should serve in newness of spirit and not in the oldness of the letter that being or being dead to that');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 7, 'What shall we say then? {Is} the law sin? God forbid. Nay, I had not known sin, but by the law: for I had not known lust, except the law had said, Thou shalt not covet. {lust: or, concupiscence}', 'what shall we say then is the law sin god forbid nay i had not known sin but by the law for i had not known lust except the law had said thou shalt not covet lust or concupiscence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 8, 'But sin, taking occasion by the commandment, wrought in me all manner of concupiscence. For without the law sin {was} dead.', 'but sin taking occasion by the commandment wrought in me all manner of concupiscence for without the law sin was dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 9, 'For I was alive without the law once: but when the commandment came, sin revived, and I died.', 'for i was alive without the law once but when the commandment came sin revived and i died');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 10, 'And the commandment, which {was ordained} to life, I found {to be} unto death.', 'and the commandment which was ordained to life i found to be unto death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 11, 'For sin, taking occasion by the commandment, deceived me, and by it slew {me}.', 'for sin taking occasion by the commandment deceived me and by it slew me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 12, 'Wherefore the law {is} holy, and the commandment holy, and just, and good.', 'wherefore the law is holy and the commandment holy and just and good');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 13, 'Was then that which is good made death unto me? God forbid. But sin, that it might appear sin, working death in me by that which is good; that sin by the commandment might become exceeding sinful.', 'was then that which is good made death unto me god forbid but sin that it might appear sin working death in me by that which is good that sin by the commandment might become exceeding sinful');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 14, 'For we know that the law is spiritual: but I am carnal, sold under sin.', 'for we know that the law is spiritual but i am carnal sold under sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 15, 'For that which I do I allow not: for what I would, that do I not; but what I hate, that do I. {allow: Gr. know}', 'for that which i do i allow not for what i would that do i not but what i hate that do i allow gr know');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 16, 'If then I do that which I would not, I consent unto the law that {it is} good.', 'if then i do that which i would not i consent unto the law that it is good');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 17, 'Now then it is no more I that do it, but sin that dwelleth in me.', 'now then it is no more i that do it but sin that dwelleth in me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 18, 'For I know that in me (that is, in my flesh,) dwelleth no good thing: for to will is present with me; but {how} to perform that which is good I find not.', 'for i know that in me that is in my flesh dwelleth no good thing for to will is present with me but how to perform that which is good i find not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 19, 'For the good that I would I do not: but the evil which I would not, that I do.', 'for the good that i would i do not but the evil which i would not that i do');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 20, 'Now if I do that I would not, it is no more I that do it, but sin that dwelleth in me.', 'now if i do that i would not it is no more i that do it but sin that dwelleth in me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 21, 'I find then a law, that, when I would do good, evil is present with me.', 'i find then a law that when i would do good evil is present with me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 22, 'For I delight in the law of God after the inward man:', 'for i delight in the law of god after the inward man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 23, 'But I see another law in my members, warring against the law of my mind, and bringing me into captivity to the law of sin which is in my members.', 'but i see another law in my members warring against the law of my mind and bringing me into captivity to the law of sin which is in my members');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 24, 'O wretched man that I am! who shall deliver me from the body of this death? {the body...: or, this body of death}', 'o wretched man that i am who shall deliver me from the body of this death the body or this body of death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 7, 25, 'I thank God through Jesus Christ our Lord. So then with the mind I myself serve the law of God; but with the flesh the law of sin.', 'i thank god through jesus christ our lord so then with the mind i myself serve the law of god but with the flesh the law of sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 1, '{There is} therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.', 'there is therefore now no condemnation to them which are in christ jesus who walk not after the flesh but after the spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 2, 'For the law of the Spirit of life in Christ Jesus hath made me free from the law of sin and death.', 'for the law of the spirit of life in christ jesus hath made me free from the law of sin and death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 3, 'For what the law could not do, in that it was weak through the flesh, God sending his own Son in the likeness of sinful flesh, and for sin, condemned sin in the flesh: {for sin: or, by a sacrifice for sin}', 'for what the law could not do in that it was weak through the flesh god sending his own son in the likeness of sinful flesh and for sin condemned sin in the flesh for sin or by a sacrifice for sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 4, 'That the righteousness of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit.', 'that the righteousness of the law might be fulfilled in us who walk not after the flesh but after the spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 5, 'For they that are after the flesh do mind the things of the flesh; but they that are after the Spirit the things of the Spirit.', 'for they that are after the flesh do mind the things of the flesh but they that are after the spirit the things of the spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 6, 'For to be carnally minded {is} death; but to be spiritually minded {is} life and peace. {to be carnally...: Gr. the minding of the flesh} {to be spiritually...: Gr. the minding of the Spirit}', 'for to be carnally minded is death but to be spiritually minded is life and peace to be carnally gr the minding of the flesh to be spiritually gr the minding of the spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 7, 'Because the carnal mind {is} enmity against God: for it is not subject to the law of God, neither indeed can be. {the carnal...: Gr. the minding of the flesh}', 'because the carnal mind is enmity against god for it is not subject to the law of god neither indeed can be the carnal gr the minding of the flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 8, 'So then they that are in the flesh cannot please God.', 'so then they that are in the flesh cannot please god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 9, 'But ye are not in the flesh, but in the Spirit, if so be that the Spirit of God dwell in you. Now if any man have not the Spirit of Christ, he is none of his.', 'but ye are not in the flesh but in the spirit if so be that the spirit of god dwell in you now if any man have not the spirit of christ he is none of his');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 10, 'And if Christ {be} in you, the body {is} dead because of sin; but the Spirit {is} life because of righteousness.', 'and if christ be in you the body is dead because of sin but the spirit is life because of righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 11, 'But if the Spirit of him that raised up Jesus from the dead dwell in you, he that raised up Christ from the dead shall also quicken your mortal bodies by his Spirit that dwelleth in you. {by: or, because of}', 'but if the spirit of him that raised up jesus from the dead dwell in you he that raised up christ from the dead shall also quicken your mortal bodies by his spirit that dwelleth in you by or because of');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 12, 'Therefore, brethren, we are debtors, not to the flesh, to live after the flesh.', 'therefore brethren we are debtors not to the flesh to live after the flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 13, 'For if ye live after the flesh, ye shall die: but if ye through the Spirit do mortify the deeds of the body, ye shall live.', 'for if ye live after the flesh ye shall die but if ye through the spirit do mortify the deeds of the body ye shall live');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 14, 'For as many as are led by the Spirit of God, they are the sons of God.', 'for as many as are led by the spirit of god they are the sons of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 15, 'For ye have not received the spirit of bondage again to fear; but ye have received the Spirit of adoption, whereby we cry, Abba, Father.', 'for ye have not received the spirit of bondage again to fear but ye have received the spirit of adoption whereby we cry abba father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 16, 'The Spirit itself beareth witness with our spirit, that we are the children of God:', 'the spirit itself beareth witness with our spirit that we are the children of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 17, 'And if children, then heirs; heirs of God, and joint-heirs with Christ; if so be that we suffer with {him}, that we may be also glorified together.', 'and if children then heirs heirs of god and joint heirs with christ if so be that we suffer with him that we may be also glorified together');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 18, 'For I reckon that the sufferings of this present time {are} not worthy {to be compared} with the glory which shall be revealed in us.', 'for i reckon that the sufferings of this present time are not worthy to be compared with the glory which shall be revealed in us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 19, 'For the earnest expectation of the creature waiteth for the manifestation of the sons of God.', 'for the earnest expectation of the creature waiteth for the manifestation of the sons of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 20, 'For the creature was made subject to vanity, not willingly, but by reason of him who hath subjected {the same} in hope,', 'for the creature was made subject to vanity not willingly but by reason of him who hath subjected the same in hope');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 21, 'Because the creature itself also shall be delivered from the bondage of corruption into the glorious liberty of the children of God.', 'because the creature itself also shall be delivered from the bondage of corruption into the glorious liberty of the children of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 22, 'For we know that the whole creation groaneth and travaileth in pain together until now. {the...: or, every creature}', 'for we know that the whole creation groaneth and travaileth in pain together until now the or every creature');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 23, 'And not only {they}, but ourselves also, which have the firstfruits of the Spirit, even we ourselves groan within ourselves, waiting for the adoption, {to wit}, the redemption of our body.', 'and not only they but ourselves also which have the firstfruits of the spirit even we ourselves groan within ourselves waiting for the adoption to wit the redemption of our body');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 24, 'For we are saved by hope: but hope that is seen is not hope: for what a man seeth, why doth he yet hope for?', 'for we are saved by hope but hope that is seen is not hope for what a man seeth why doth he yet hope for');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 25, 'But if we hope for that we see not, {then} do we with patience wait for {it}.', 'but if we hope for that we see not then do we with patience wait for it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 26, 'Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.', 'likewise the spirit also helpeth our infirmities for we know not what we should pray for as we ought but the spirit itself maketh intercession for us with groanings which cannot be uttered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 27, 'And he that searcheth the hearts knoweth what {is} the mind of the Spirit, because he maketh intercession for the saints according to {the will of} God. {because: or, that}', 'and he that searcheth the hearts knoweth what is the mind of the spirit because he maketh intercession for the saints according to the will of god because or that');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 28, 'And we know that all things work together for good to them that love God, to them who are the called according to {his} purpose.', 'and we know that all things work together for good to them that love god to them who are the called according to his purpose');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 29, 'For whom he did foreknow, he also did predestinate {to be} conformed to the image of his Son, that he might be the firstborn among many brethren.', 'for whom he did foreknow he also did predestinate to be conformed to the image of his son that he might be the firstborn among many brethren');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 30, 'Moreover whom he did predestinate, them he also called: and whom he called, them he also justified: and whom he justified, them he also glorified.', 'moreover whom he did predestinate them he also called and whom he called them he also justified and whom he justified them he also glorified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 31, 'What shall we then say to these things? If God {be} for us, who {can be} against us?', 'what shall we then say to these things if god be for us who can be against us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 32, 'He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?', 'he that spared not his own son but delivered him up for us all how shall he not with him also freely give us all things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 33, 'Who shall lay any thing to the charge of God''s elect? {It is} God that justifieth.', 'who shall lay any thing to the charge of god s elect it is god that justifieth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 34, 'Who {is} he that condemneth? {It is} Christ that died, yea rather, that is risen again, who is even at the right hand of God, who also maketh intercession for us.', 'who is he that condemneth it is christ that died yea rather that is risen again who is even at the right hand of god who also maketh intercession for us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 35, 'Who shall separate us from the love of Christ? {shall} tribulation, or distress, or persecution, or famine, or nakedness, or peril, or sword?', 'who shall separate us from the love of christ shall tribulation or distress or persecution or famine or nakedness or peril or sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 36, 'As it is written, For thy sake we are killed all the day long; we are accounted as sheep for the slaughter.', 'as it is written for thy sake we are killed all the day long we are accounted as sheep for the slaughter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 37, 'Nay, in all these things we are more than conquerors through him that loved us.', 'nay in all these things we are more than conquerors through him that loved us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 38, 'For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come,', 'for i am persuaded that neither death nor life nor angels nor principalities nor powers nor things present nor things to come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 8, 39, 'Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.', 'nor height nor depth nor any other creature shall be able to separate us from the love of god which is in christ jesus our lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 1, 'I say the truth in Christ, I lie not, my conscience also bearing me witness in the Holy Ghost,', 'i say the truth in christ i lie not my conscience also bearing me witness in the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 2, 'That I have great heaviness and continual sorrow in my heart.', 'that i have great heaviness and continual sorrow in my heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 3, 'For I could wish that myself were accursed from Christ for my brethren, my kinsmen according to the flesh: {accursed: or, separated}', 'for i could wish that myself were accursed from christ for my brethren my kinsmen according to the flesh accursed or separated');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 4, 'Who are Israelites; to whom {pertaineth} the adoption, and the glory, and the covenants, and the giving of the law, and the service {of God}, and the promises; {covenants: or, testaments}', 'who are israelites to whom pertaineth the adoption and the glory and the covenants and the giving of the law and the service of god and the promises covenants or testaments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 5, 'Whose {are} the fathers, and of whom as concerning the flesh Christ {came}, who is over all, God blessed for ever. Amen.', 'whose are the fathers and of whom as concerning the flesh christ came who is over all god blessed for ever amen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 6, 'Not as though the word of God hath taken none effect. For they {are} not all Israel, which are of Israel:', 'not as though the word of god hath taken none effect for they are not all israel which are of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 7, 'Neither, because they are the seed of Abraham, {are they} all children: but, In Isaac shall thy seed be called.', 'neither because they are the seed of abraham are they all children but in isaac shall thy seed be called');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 8, 'That is, They which are the children of the flesh, these {are} not the children of God: but the children of the promise are counted for the seed.', 'that is they which are the children of the flesh these are not the children of god but the children of the promise are counted for the seed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 9, 'For this {is} the word of promise, At this time will I come, and Sara shall have a son.', 'for this is the word of promise at this time will i come and sara shall have a son');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 10, 'And not only {this}; but when Rebecca also had conceived by one, {even} by our father Isaac;', 'and not only this but when rebecca also had conceived by one even by our father isaac');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 11, '(For {the children} being not yet born, neither having done any good or evil, that the purpose of God according to election might stand, not of works, but of him that calleth;)', 'for the children being not yet born neither having done any good or evil that the purpose of god according to election might stand not of works but of him that calleth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 12, 'It was said unto her, The elder shall serve the younger. {elder: or, greater} {younger: or, lesser}', 'it was said unto her the elder shall serve the younger elder or greater younger or lesser');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 13, 'As it is written, Jacob have I loved, but Esau have I hated.', 'as it is written jacob have i loved but esau have i hated');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 14, 'What shall we say then? {Is there} unrighteousness with God? God forbid.', 'what shall we say then is there unrighteousness with god god forbid');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 15, 'For he saith to Moses, I will have mercy on whom I will have mercy, and I will have compassion on whom I will have compassion.', 'for he saith to moses i will have mercy on whom i will have mercy and i will have compassion on whom i will have compassion');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 16, 'So then {it is} not of him that willeth, nor of him that runneth, but of God that sheweth mercy.', 'so then it is not of him that willeth nor of him that runneth but of god that sheweth mercy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 17, 'For the scripture saith unto Pharaoh, Even for this same purpose have I raised thee up, that I might shew my power in thee, and that my name might be declared throughout all the earth.', 'for the scripture saith unto pharaoh even for this same purpose have i raised thee up that i might shew my power in thee and that my name might be declared throughout all the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 18, 'Therefore hath he mercy on whom he will {have mercy}, and whom he will he hardeneth.', 'therefore hath he mercy on whom he will have mercy and whom he will he hardeneth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 19, 'Thou wilt say then unto me, Why doth he yet find fault? For who hath resisted his will?', 'thou wilt say then unto me why doth he yet find fault for who hath resisted his will');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 20, 'Nay but, O man, who art thou that repliest against God? Shall the thing formed say to him that formed {it}, Why hast thou made me thus? {repliest...: or, answerest again, or, disputest with God?}', 'nay but o man who art thou that repliest against god shall the thing formed say to him that formed it why hast thou made me thus repliest or answerest again or disputest with god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 21, 'Hath not the potter power over the clay, of the same lump to make one vessel unto honour, and another unto dishonour?', 'hath not the potter power over the clay of the same lump to make one vessel unto honour and another unto dishonour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 22, '{What} if God, willing to shew {his} wrath, and to make his power known, endured with much longsuffering the vessels of wrath fitted to destruction: {fitted: or, made up}', 'what if god willing to shew his wrath and to make his power known endured with much longsuffering the vessels of wrath fitted to destruction fitted or made up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 23, 'And that he might make known the riches of his glory on the vessels of mercy, which he had afore prepared unto glory,', 'and that he might make known the riches of his glory on the vessels of mercy which he had afore prepared unto glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 24, 'Even us, whom he hath called, not of the Jews only, but also of the Gentiles?', 'even us whom he hath called not of the jews only but also of the gentiles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 25, 'As he saith also in Osee, I will call them my people, which were not my people; and her beloved, which was not beloved.', 'as he saith also in osee i will call them my people which were not my people and her beloved which was not beloved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 26, 'And it shall come to pass, {that} in the place where it was said unto them, Ye {are} not my people; there shall they be called the children of the living God.', 'and it shall come to pass that in the place where it was said unto them ye are not my people there shall they be called the children of the living god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 27, 'Esaias also crieth concerning Israel, Though the number of the children of Israel be as the sand of the sea, a remnant shall be saved:', 'esaias also crieth concerning israel though the number of the children of israel be as the sand of the sea a remnant shall be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 28, 'For he will finish the work, and cut {it} short in righteousness: because a short work will the Lord make upon the earth. {the work: or, the account}', 'for he will finish the work and cut it short in righteousness because a short work will the lord make upon the earth the work or the account');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 29, 'And as Esaias said before, Except the Lord of Sabaoth had left us a seed, we had been as Sodoma, and been made like unto Gomorrha. {Sabaoth: Heb. hosts}', 'and as esaias said before except the lord of sabaoth had left us a seed we had been as sodoma and been made like unto gomorrha sabaoth heb hosts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 30, 'What shall we say then? That the Gentiles, which followed not after righteousness, have attained to righteousness, even the righteousness which is of faith.', 'what shall we say then that the gentiles which followed not after righteousness have attained to righteousness even the righteousness which is of faith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 31, 'But Israel, which followed after the law of righteousness, hath not attained to the law of righteousness.', 'but israel which followed after the law of righteousness hath not attained to the law of righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 32, 'Wherefore? Because {they sought it} not by faith, but as it were by the works of the law. For they stumbled at that stumblingstone;', 'wherefore because they sought it not by faith but as it were by the works of the law for they stumbled at that stumblingstone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 9, 33, 'As it is written, Behold, I lay in Sion a stumblingstone and rock of offence: and whosoever believeth on him shall not be ashamed. {ashamed: or confounded}', 'as it is written behold i lay in sion a stumblingstone and rock of offence and whosoever believeth on him shall not be ashamed ashamed or confounded');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 1, 'Brethren, my heart''s desire and prayer to God for Israel is, that they might be saved.', 'brethren my heart s desire and prayer to god for israel is that they might be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 2, 'For I bear them record that they have a zeal of God, but not according to knowledge.', 'for i bear them record that they have a zeal of god but not according to knowledge');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 3, 'For they being ignorant of God''s righteousness, and going about to establish their own righteousness, have not submitted themselves unto the righteousness of God.', 'for they being ignorant of god s righteousness and going about to establish their own righteousness have not submitted themselves unto the righteousness of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 4, 'For Christ {is} the end of the law for righteousness to every one that believeth.', 'for christ is the end of the law for righteousness to every one that believeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 5, 'For Moses describeth the righteousness which is of the law, That the man which doeth those things shall live by them.', 'for moses describeth the righteousness which is of the law that the man which doeth those things shall live by them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 6, 'But the righteousness which is of faith speaketh on this wise, Say not in thine heart, Who shall ascend into heaven? (that is, to bring Christ down {from above}:)', 'but the righteousness which is of faith speaketh on this wise say not in thine heart who shall ascend into heaven that is to bring christ down from above');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 7, 'Or, Who shall descend into the deep? (that is, to bring up Christ again from the dead.)', 'or who shall descend into the deep that is to bring up christ again from the dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 8, 'But what saith it? The word is nigh thee, {even} in thy mouth, and in thy heart: that is, the word of faith, which we preach;', 'but what saith it the word is nigh thee even in thy mouth and in thy heart that is the word of faith which we preach');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 9, 'That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved.', 'that if thou shalt confess with thy mouth the lord jesus and shalt believe in thine heart that god hath raised him from the dead thou shalt be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 10, 'For with the heart man believeth unto righteousness; and with the mouth confession is made unto salvation.', 'for with the heart man believeth unto righteousness and with the mouth confession is made unto salvation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 11, 'For the scripture saith, Whosoever believeth on him shall not be ashamed.', 'for the scripture saith whosoever believeth on him shall not be ashamed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 12, 'For there is no difference between the Jew and the Greek: for the same Lord over all is rich unto all that call upon him.', 'for there is no difference between the jew and the greek for the same lord over all is rich unto all that call upon him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 13, 'For whosoever shall call upon the name of the Lord shall be saved.', 'for whosoever shall call upon the name of the lord shall be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 14, 'How then shall they call on him in whom they have not believed? and how shall they believe in him of whom they have not heard? and how shall they hear without a preacher?', 'how then shall they call on him in whom they have not believed and how shall they believe in him of whom they have not heard and how shall they hear without a preacher');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 15, 'And how shall they preach, except they be sent? as it is written, How beautiful are the feet of them that preach the gospel of peace, and bring glad tidings of good things!', 'and how shall they preach except they be sent as it is written how beautiful are the feet of them that preach the gospel of peace and bring glad tidings of good things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 16, 'But they have not all obeyed the gospel. For Esaias saith, Lord, who hath believed our report? {our report: Gr. the hearing of us?} {report: or, preaching?}', 'but they have not all obeyed the gospel for esaias saith lord who hath believed our report our report gr the hearing of us report or preaching');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 17, 'So then faith {cometh} by hearing, and hearing by the word of God.', 'so then faith cometh by hearing and hearing by the word of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 18, 'But I say, Have they not heard? Yes verily, their sound went into all the earth, and their words unto the ends of the world.', 'but i say have they not heard yes verily their sound went into all the earth and their words unto the ends of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 19, 'But I say, Did not Israel know? First Moses saith, I will provoke you to jealousy by {them that are} no people, {and} by a foolish nation I will anger you.', 'but i say did not israel know first moses saith i will provoke you to jealousy by them that are no people and by a foolish nation i will anger you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 20, 'But Esaias is very bold, and saith, I was found of them that sought me not; I was made manifest unto them that asked not after me.', 'but esaias is very bold and saith i was found of them that sought me not i was made manifest unto them that asked not after me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 10, 21, 'But to Israel he saith, All day long I have stretched forth my hands unto a disobedient and gainsaying people.', 'but to israel he saith all day long i have stretched forth my hands unto a disobedient and gainsaying people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 1, 'I say then, Hath God cast away his people? God forbid. For I also am an Israelite, of the seed of Abraham, {of} the tribe of Benjamin.', 'i say then hath god cast away his people god forbid for i also am an israelite of the seed of abraham of the tribe of benjamin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 2, 'God hath not cast away his people which he foreknew. Wot ye not what the scripture saith of Elias? how he maketh intercession to God against Israel, saying, {of Elias: Gr. in Elias?}', 'god hath not cast away his people which he foreknew wot ye not what the scripture saith of elias how he maketh intercession to god against israel saying of elias gr in elias');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 3, 'Lord, they have killed thy prophets, and digged down thine altars; and I am left alone, and they seek my life.', 'lord they have killed thy prophets and digged down thine altars and i am left alone and they seek my life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 4, 'But what saith the answer of God unto him? I have reserved to myself seven thousand men, who have not bowed the knee to {the image of} Baal.', 'but what saith the answer of god unto him i have reserved to myself seven thousand men who have not bowed the knee to the image of baal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 5, 'Even so then at this present time also there is a remnant according to the election of grace.', 'even so then at this present time also there is a remnant according to the election of grace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 6, 'And if by grace, then {is it} no more of works: otherwise grace is no more grace. But if {it be} of works, then is it no more grace: otherwise work is no more work.', 'and if by grace then is it no more of works otherwise grace is no more grace but if it be of works then is it no more grace otherwise work is no more work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 7, 'What then? Israel hath not obtained that which he seeketh for; but the election hath obtained it, and the rest were blinded {blinded: or, hardened}', 'what then israel hath not obtained that which he seeketh for but the election hath obtained it and the rest were blinded blinded or hardened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 8, '(According as it is written, God hath given them the spirit of slumber, eyes that they should not see, and ears that they should not hear;) unto this day. {slumber: or, remorse}', 'according as it is written god hath given them the spirit of slumber eyes that they should not see and ears that they should not hear unto this day slumber or remorse');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 9, 'And David saith, Let their table be made a snare, and a trap, and a stumblingblock, and a recompence unto them:', 'and david saith let their table be made a snare and a trap and a stumblingblock and a recompence unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 10, 'Let their eyes be darkened, that they may not see, and bow down their back alway.', 'let their eyes be darkened that they may not see and bow down their back alway');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 11, 'I say then, Have they stumbled that they should fall? God forbid: but {rather} through their fall salvation {is come} unto the Gentiles, for to provoke them to jealousy.', 'i say then have they stumbled that they should fall god forbid but rather through their fall salvation is come unto the gentiles for to provoke them to jealousy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 12, 'Now if the fall of them {be} the riches of the world, and the diminishing of them the riches of the Gentiles; how much more their fulness? {diminishing: or, decay, or, loss}', 'now if the fall of them be the riches of the world and the diminishing of them the riches of the gentiles how much more their fulness diminishing or decay or loss');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 13, 'For I speak to you Gentiles, inasmuch as I am the apostle of the Gentiles, I magnify mine office:', 'for i speak to you gentiles inasmuch as i am the apostle of the gentiles i magnify mine office');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 14, 'If by any means I may provoke to emulation {them which are} my flesh, and might save some of them.', 'if by any means i may provoke to emulation them which are my flesh and might save some of them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 15, 'For if the casting away of them {be} the reconciling of the world, what {shall} the receiving {of them be}, but life from the dead?', 'for if the casting away of them be the reconciling of the world what shall the receiving of them be but life from the dead');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 16, 'For if the firstfruit {be} holy, the lump {is} also {holy}: and if the root {be} holy, so {are} the branches.', 'for if the firstfruit be holy the lump is also holy and if the root be holy so are the branches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 17, 'And if some of the branches be broken off, and thou, being a wild olive tree, wert graffed in among them, and with them partakest of the root and fatness of the olive tree; {among them: or, for them}', 'and if some of the branches be broken off and thou being a wild olive tree wert graffed in among them and with them partakest of the root and fatness of the olive tree among them or for them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 18, 'Boast not against the branches. But if thou boast, thou bearest not the root, but the root thee.', 'boast not against the branches but if thou boast thou bearest not the root but the root thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 19, 'Thou wilt say then, The branches were broken off, that I might be graffed in.', 'thou wilt say then the branches were broken off that i might be graffed in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 20, 'Well; because of unbelief they were broken off, and thou standest by faith. Be not highminded, but fear:', 'well because of unbelief they were broken off and thou standest by faith be not highminded but fear');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 21, 'For if God spared not the natural branches, {take heed} lest he also spare not thee.', 'for if god spared not the natural branches take heed lest he also spare not thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 22, 'Behold therefore the goodness and severity of God: on them which fell, severity; but toward thee, goodness, if thou continue in {his} goodness: otherwise thou also shalt be cut off.', 'behold therefore the goodness and severity of god on them which fell severity but toward thee goodness if thou continue in his goodness otherwise thou also shalt be cut off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 23, 'And they also, if they abide not still in unbelief, shall be graffed in: for God is able to graff them in again.', 'and they also if they abide not still in unbelief shall be graffed in for god is able to graff them in again');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 24, 'For if thou wert cut out of the olive tree which is wild by nature, and wert graffed contrary to nature into a good olive tree: how much more shall these, which be the natural {branches}, be graffed into their own olive tree?', 'for if thou wert cut out of the olive tree which is wild by nature and wert graffed contrary to nature into a good olive tree how much more shall these which be the natural branches be graffed into their own olive tree');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 25, 'For I would not, brethren, that ye should be ignorant of this mystery, lest ye should be wise in your own conceits; that blindness in part is happened to Israel, until the fulness of the Gentiles be come in. {blindness: or, hardness}', 'for i would not brethren that ye should be ignorant of this mystery lest ye should be wise in your own conceits that blindness in part is happened to israel until the fulness of the gentiles be come in blindness or hardness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 11, 26, 'And so all Israel shall be saved: as it is written, There shall come out of Sion the Deliverer, and shall turn away ungodliness from Jacob:', 'and so all israel shall be saved as it is written there shall come out of sion the deliverer and shall turn away ungodliness from jacob');
