INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 14, 23, 'And he that doubteth is damned if he eat, because {he eateth} not of faith: for whatsoever {is} not of faith is sin. {doubteth: or, discerneth and putteth a difference between meats} {damned: or, condemned, or liable to punishment}', 'and he that doubteth is damned if he eat because he eateth not of faith for whatsoever is not of faith is sin doubteth or discerneth and putteth a difference between meats damned or condemned or liable to punishment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 1, 'We then that are strong ought to bear the infirmities of the weak, and not to please ourselves.', 'we then that are strong ought to bear the infirmities of the weak and not to please ourselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 2, 'Let every one of us please {his} neighbour for {his} good to edification.', 'let every one of us please his neighbour for his good to edification');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 3, 'For even Christ pleased not himself; but, as it is written, The reproaches of them that reproached thee fell on me.', 'for even christ pleased not himself but as it is written the reproaches of them that reproached thee fell on me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 4, 'For whatsoever things were written aforetime were written for our learning, that we through patience and comfort of the scriptures might have hope.', 'for whatsoever things were written aforetime were written for our learning that we through patience and comfort of the scriptures might have hope');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 5, 'Now the God of patience and consolation grant you to be likeminded one toward another according to Christ Jesus: {according to: or, after the example of}', 'now the god of patience and consolation grant you to be likeminded one toward another according to christ jesus according to or after the example of');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 6, 'That ye may with one mind {and} one mouth glorify God, even the Father of our Lord Jesus Christ.', 'that ye may with one mind and one mouth glorify god even the father of our lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 7, 'Wherefore receive ye one another, as Christ also received us to the glory of God.', 'wherefore receive ye one another as christ also received us to the glory of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 8, 'Now I say that Jesus Christ was a minister of the circumcision for the truth of God, to confirm the promises {made} unto the fathers:', 'now i say that jesus christ was a minister of the circumcision for the truth of god to confirm the promises made unto the fathers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 9, 'And that the Gentiles might glorify God for {his} mercy; as it is written, For this cause I will confess to thee among the Gentiles, and sing unto thy name.', 'and that the gentiles might glorify god for his mercy as it is written for this cause i will confess to thee among the gentiles and sing unto thy name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 10, 'And again he saith, Rejoice, ye Gentiles, with his people.', 'and again he saith rejoice ye gentiles with his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 11, 'And again, Praise the Lord, all ye Gentiles; and laud him, all ye people.', 'and again praise the lord all ye gentiles and laud him all ye people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 12, 'And again, Esaias saith, There shall be a root of Jesse, and he that shall rise to reign over the Gentiles; in him shall the Gentiles trust.', 'and again esaias saith there shall be a root of jesse and he that shall rise to reign over the gentiles in him shall the gentiles trust');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 13, 'Now the God of hope fill you with all joy and peace in believing, that ye may abound in hope, through the power of the Holy Ghost.', 'now the god of hope fill you with all joy and peace in believing that ye may abound in hope through the power of the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 14, 'And I myself also am persuaded of you, my brethren, that ye also are full of goodness, filled with all knowledge, able also to admonish one another.', 'and i myself also am persuaded of you my brethren that ye also are full of goodness filled with all knowledge able also to admonish one another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 15, 'Nevertheless, brethren, I have written the more boldly unto you in some sort, as putting you in mind, because of the grace that is given to me of God,', 'nevertheless brethren i have written the more boldly unto you in some sort as putting you in mind because of the grace that is given to me of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 16, 'That I should be the minister of Jesus Christ to the Gentiles, ministering the gospel of God, that the offering up of the Gentiles might be acceptable, being sanctified by the Holy Ghost. {offering up: or, sacrificing}', 'that i should be the minister of jesus christ to the gentiles ministering the gospel of god that the offering up of the gentiles might be acceptable being sanctified by the holy ghost offering up or sacrificing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 17, 'I have therefore whereof I may glory through Jesus Christ in those things which pertain to God.', 'i have therefore whereof i may glory through jesus christ in those things which pertain to god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 18, 'For I will not dare to speak of any of those things which Christ hath not wrought by me, to make the Gentiles obedient, by word and deed,', 'for i will not dare to speak of any of those things which christ hath not wrought by me to make the gentiles obedient by word and deed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 19, 'Through mighty signs and wonders, by the power of the Spirit of God; so that from Jerusalem, and round about unto Illyricum, I have fully preached the gospel of Christ.', 'through mighty signs and wonders by the power of the spirit of god so that from jerusalem and round about unto illyricum i have fully preached the gospel of christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 20, 'Yea, so have I strived to preach the gospel, not where Christ was named, lest I should build upon another man''s foundation:', 'yea so have i strived to preach the gospel not where christ was named lest i should build upon another man s foundation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 21, 'But as it is written, To whom he was not spoken of, they shall see: and they that have not heard shall understand.', 'but as it is written to whom he was not spoken of they shall see and they that have not heard shall understand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 22, 'For which cause also I have been much hindered from coming to you. {much: or, many ways, or oftentimes}', 'for which cause also i have been much hindered from coming to you much or many ways or oftentimes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 23, 'But now having no more place in these parts, and having a great desire these many years to come unto you;', 'but now having no more place in these parts and having a great desire these many years to come unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 24, 'Whensoever I take my journey into Spain, I will come to you: for I trust to see you in my journey, and to be brought on my way thitherward by you, if first I be somewhat filled with your {company}. {with...: Gr. with you}', 'whensoever i take my journey into spain i will come to you for i trust to see you in my journey and to be brought on my way thitherward by you if first i be somewhat filled with your company with gr with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 25, 'But now I go unto Jerusalem to minister unto the saints.', 'but now i go unto jerusalem to minister unto the saints');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 26, 'For it hath pleased them of Macedonia and Achaia to make a certain contribution for the poor saints which are at Jerusalem.', 'for it hath pleased them of macedonia and achaia to make a certain contribution for the poor saints which are at jerusalem');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 27, 'It hath pleased them verily; and their debtors they are. For if the Gentiles have been made partakers of their spiritual things, their duty is also to minister unto them in carnal things.', 'it hath pleased them verily and their debtors they are for if the gentiles have been made partakers of their spiritual things their duty is also to minister unto them in carnal things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 28, 'When therefore I have performed this, and have sealed to them this fruit, I will come by you into Spain.', 'when therefore i have performed this and have sealed to them this fruit i will come by you into spain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 29, 'And I am sure that, when I come unto you, I shall come in the fulness of the blessing of the gospel of Christ.', 'and i am sure that when i come unto you i shall come in the fulness of the blessing of the gospel of christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 30, 'Now I beseech you, brethren, for the Lord Jesus Christ''s sake, and for the love of the Spirit, that ye strive together with me in {your} prayers to God for me;', 'now i beseech you brethren for the lord jesus christ s sake and for the love of the spirit that ye strive together with me in your prayers to god for me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 31, 'That I may be delivered from them that do not believe in Judaea; and that my service which {I have} for Jerusalem may be accepted of the saints; {do not...: or, are disobedient}', 'that i may be delivered from them that do not believe in judaea and that my service which i have for jerusalem may be accepted of the saints do not or are disobedient');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 32, 'That I may come unto you with joy by the will of God, and may with you be refreshed.', 'that i may come unto you with joy by the will of god and may with you be refreshed');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 15, 33, 'Now the God of peace {be} with you all. Amen.', 'now the god of peace be with you all amen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 1, 'I commend unto you Phebe our sister, which is a servant of the church which is at Cenchrea:', 'i commend unto you phebe our sister which is a servant of the church which is at cenchrea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 2, 'That ye receive her in the Lord, as becometh saints, and that ye assist her in whatsoever business she hath need of you: for she hath been a succourer of many, and of myself also.', 'that ye receive her in the lord as becometh saints and that ye assist her in whatsoever business she hath need of you for she hath been a succourer of many and of myself also');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 3, 'Greet Priscilla and Aquila my helpers in Christ Jesus:', 'greet priscilla and aquila my helpers in christ jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 4, 'Who have for my life laid down their own necks: unto whom not only I give thanks, but also all the churches of the Gentiles.', 'who have for my life laid down their own necks unto whom not only i give thanks but also all the churches of the gentiles');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 5, 'Likewise {greet} the church that is in their house. Salute my wellbeloved Epaenetus, who is the firstfruits of Achaia unto Christ.', 'likewise greet the church that is in their house salute my wellbeloved epaenetus who is the firstfruits of achaia unto christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 6, 'Greet Mary, who bestowed much labour on us.', 'greet mary who bestowed much labour on us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 7, 'Salute Andronicus and Junia, my kinsmen, and my fellowprisoners, who are of note among the apostles, who also were in Christ before me.', 'salute andronicus and junia my kinsmen and my fellowprisoners who are of note among the apostles who also were in christ before me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 8, 'Greet Amplias my beloved in the Lord.', 'greet amplias my beloved in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 9, 'Salute Urbane, our helper in Christ, and Stachys my beloved.', 'salute urbane our helper in christ and stachys my beloved');
