INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 11, 'Salute Herodion my kinsman. Greet them that be of the {household} of Narcissus, which are in the Lord. {household: or, friends}', 'salute herodion my kinsman greet them that be of the household of narcissus which are in the lord household or friends');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 12, 'Salute Tryphena and Tryphosa, who labour in the Lord. Salute the beloved Persis, which laboured much in the Lord.', 'salute tryphena and tryphosa who labour in the lord salute the beloved persis which laboured much in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 13, 'Salute Rufus chosen in the Lord, and his mother and mine.', 'salute rufus chosen in the lord and his mother and mine');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 14, 'Salute Asyncritus, Phlegon, Hermas, Patrobas, Hermes, and the brethren which are with them.', 'salute asyncritus phlegon hermas patrobas hermes and the brethren which are with them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 15, 'Salute Philologus, and Julia, Nereus, and his sister, and Olympas, and all the saints which are with them.', 'salute philologus and julia nereus and his sister and olympas and all the saints which are with them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 16, 'Salute one another with an holy kiss. The churches of Christ salute you.', 'salute one another with an holy kiss the churches of christ salute you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 17, 'Now I beseech you, brethren, mark them which cause divisions and offences contrary to the doctrine which ye have learned; and avoid them.', 'now i beseech you brethren mark them which cause divisions and offences contrary to the doctrine which ye have learned and avoid them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 18, 'For they that are such serve not our Lord Jesus Christ, but their own belly; and by good words and fair speeches deceive the hearts of the simple.', 'for they that are such serve not our lord jesus christ but their own belly and by good words and fair speeches deceive the hearts of the simple');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 19, 'For your obedience is come abroad unto all {men}. I am glad therefore on your behalf: but yet I would have you wise unto that which is good, and simple concerning evil. {simple: or, harmless}', 'for your obedience is come abroad unto all men i am glad therefore on your behalf but yet i would have you wise unto that which is good and simple concerning evil simple or harmless');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 20, 'And the God of peace shall bruise Satan under your feet shortly. The grace of our Lord Jesus Christ {be} with you. Amen. {bruise: or, tread}', 'and the god of peace shall bruise satan under your feet shortly the grace of our lord jesus christ be with you amen bruise or tread');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 21, 'Timotheus my workfellow, and Lucius, and Jason, and Sosipater, my kinsmen, salute you.', 'timotheus my workfellow and lucius and jason and sosipater my kinsmen salute you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 22, 'I Tertius, who wrote {this} epistle, salute you in the Lord.', 'i tertius who wrote this epistle salute you in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 23, 'Gaius mine host, and of the whole church, saluteth you. Erastus the chamberlain of the city saluteth you, and Quartus a brother.', 'gaius mine host and of the whole church saluteth you erastus the chamberlain of the city saluteth you and quartus a brother');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 24, 'The grace of our Lord Jesus Christ {be} with you all. Amen.', 'the grace of our lord jesus christ be with you all amen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 25, 'Now to him that is of power to stablish you according to my gospel, and the preaching of Jesus Christ, according to the revelation of the mystery, which was kept secret since the world began,', 'now to him that is of power to stablish you according to my gospel and the preaching of jesus christ according to the revelation of the mystery which was kept secret since the world began');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 26, 'But now is made manifest, and by the scriptures of the prophets, according to the commandment of the everlasting God, made known to all nations for the obedience of faith:', 'but now is made manifest and by the scriptures of the prophets according to the commandment of the everlasting god made known to all nations for the obedience of faith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 45, 'Unknown', 16, 27, 'To God only wise, {be} glory through Jesus Christ for ever. Amen. «{Written to the Romans from Corinthus, and sent} by Phebe servant of the church at Cenchrea.}»', 'to god only wise be glory through jesus christ for ever amen written to the romans from corinthus and sent by phebe servant of the church at cenchrea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 1, 'Paul, called {to be} an apostle of Jesus Christ through the will of God, and Sosthenes {our} brother,', 'paul called to be an apostle of jesus christ through the will of god and sosthenes our brother');
