INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 3, 'Grace {be} unto you, and peace, from God our Father, and {from} the Lord Jesus Christ.', 'grace be unto you and peace from god our father and from the lord jesus christ');
