INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 9, 'God {is} faithful, by whom ye were called unto the fellowship of his Son Jesus Christ our Lord.', 'god is faithful by whom ye were called unto the fellowship of his son jesus christ our lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 10, 'Now I beseech you, brethren, by the name of our Lord Jesus Christ, that ye all speak the same thing, and {that} there be no divisions among you; but {that} ye be perfectly joined together in the same mind and in the same judgment. {divisions: Gr. schisms}', 'now i beseech you brethren by the name of our lord jesus christ that ye all speak the same thing and that there be no divisions among you but that ye be perfectly joined together in the same mind and in the same judgment divisions gr schisms');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 11, 'For it hath been declared unto me of you, my brethren, by them {which are of the house} of Chloe, that there are contentions among you.', 'for it hath been declared unto me of you my brethren by them which are of the house of chloe that there are contentions among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 12, 'Now this I say, that every one of you saith, I am of Paul; and I of Apollos; and I of Cephas; and I of Christ.', 'now this i say that every one of you saith i am of paul and i of apollos and i of cephas and i of christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 13, 'Is Christ divided? was Paul crucified for you? or were ye baptized in the name of Paul?', 'is christ divided was paul crucified for you or were ye baptized in the name of paul');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 14, 'I thank God that I baptized none of you, but Crispus and Gaius;', 'i thank god that i baptized none of you but crispus and gaius');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 15, 'Lest any should say that I had baptized in mine own name.', 'lest any should say that i had baptized in mine own name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 16, 'And I baptized also the household of Stephanas: besides, I know not whether I baptized any other.', 'and i baptized also the household of stephanas besides i know not whether i baptized any other');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 17, 'For Christ sent me not to baptize, but to preach the gospel: not with wisdom of words, lest the cross of Christ should be made of none effect. {words: or, speech}', 'for christ sent me not to baptize but to preach the gospel not with wisdom of words lest the cross of christ should be made of none effect words or speech');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 18, 'For the preaching of the cross is to them that perish foolishness; but unto us which are saved it is the power of God.', 'for the preaching of the cross is to them that perish foolishness but unto us which are saved it is the power of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 19, 'For it is written, I will destroy the wisdom of the wise, and will bring to nothing the understanding of the prudent.', 'for it is written i will destroy the wisdom of the wise and will bring to nothing the understanding of the prudent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 20, 'Where {is} the wise? where {is} the scribe? where {is} the disputer of this world? hath not God made foolish the wisdom of this world?', 'where is the wise where is the scribe where is the disputer of this world hath not god made foolish the wisdom of this world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 21, 'For after that in the wisdom of God the world by wisdom knew not God, it pleased God by the foolishness of preaching to save them that believe.', 'for after that in the wisdom of god the world by wisdom knew not god it pleased god by the foolishness of preaching to save them that believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 22, 'For the Jews require a sign, and the Greeks seek after wisdom:', 'for the jews require a sign and the greeks seek after wisdom');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 23, 'But we preach Christ crucified, unto the Jews a stumblingblock, and unto the Greeks foolishness;', 'but we preach christ crucified unto the jews a stumblingblock and unto the greeks foolishness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 24, 'But unto them which are called, both Jews and Greeks, Christ the power of God, and the wisdom of God.', 'but unto them which are called both jews and greeks christ the power of god and the wisdom of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 25, 'Because the foolishness of God is wiser than men; and the weakness of God is stronger than men.', 'because the foolishness of god is wiser than men and the weakness of god is stronger than men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 26, 'For ye see your calling, brethren, how that not many wise men after the flesh, not many mighty, not many noble, {are called}:', 'for ye see your calling brethren how that not many wise men after the flesh not many mighty not many noble are called');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 27, 'But God hath chosen the foolish things of the world to confound the wise; and God hath chosen the weak things of the world to confound the things which are mighty;', 'but god hath chosen the foolish things of the world to confound the wise and god hath chosen the weak things of the world to confound the things which are mighty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 28, 'And base things of the world, and things which are despised, hath God chosen, {yea}, and things which are not, to bring to nought things that are:', 'and base things of the world and things which are despised hath god chosen yea and things which are not to bring to nought things that are');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 29, 'That no flesh should glory in his presence.', 'that no flesh should glory in his presence');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 30, 'But of him are ye in Christ Jesus, who of God is made unto us wisdom, and righteousness, and sanctification, and redemption:', 'but of him are ye in christ jesus who of god is made unto us wisdom and righteousness and sanctification and redemption');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 1, 31, 'That, according as it is written, He that glorieth, let him glory in the Lord.', 'that according as it is written he that glorieth let him glory in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 1, 'And I, brethren, when I came to you, came not with excellency of speech or of wisdom, declaring unto you the testimony of God.', 'and i brethren when i came to you came not with excellency of speech or of wisdom declaring unto you the testimony of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 2, 'For I determined not to know any thing among you, save Jesus Christ, and him crucified.', 'for i determined not to know any thing among you save jesus christ and him crucified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 3, 'And I was with you in weakness, and in fear, and in much trembling.', 'and i was with you in weakness and in fear and in much trembling');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 4, 'And my speech and my preaching {was} not with enticing words of man''s wisdom, but in demonstration of the Spirit and of power: {enticing: or, persuasible}', 'and my speech and my preaching was not with enticing words of man s wisdom but in demonstration of the spirit and of power enticing or persuasible');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 5, 'That your faith should not stand in the wisdom of men, but in the power of God. {stand: Gr. be}', 'that your faith should not stand in the wisdom of men but in the power of god stand gr be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 6, 'Howbeit we speak wisdom among them that are perfect: yet not the wisdom of this world, nor of the princes of this world, that come to nought:', 'howbeit we speak wisdom among them that are perfect yet not the wisdom of this world nor of the princes of this world that come to nought');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 7, 'But we speak the wisdom of God in a mystery, {even} the hidden {wisdom}, which God ordained before the world unto our glory:', 'but we speak the wisdom of god in a mystery even the hidden wisdom which god ordained before the world unto our glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 8, 'Which none of the princes of this world knew: for had they known {it}, they would not have crucified the Lord of glory.', 'which none of the princes of this world knew for had they known it they would not have crucified the lord of glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 9, 'But as it is written, Eye hath not seen, nor ear heard, neither have entered into the heart of man, the things which God hath prepared for them that love him.', 'but as it is written eye hath not seen nor ear heard neither have entered into the heart of man the things which god hath prepared for them that love him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 10, 'But God hath revealed {them} unto us by his Spirit: for the Spirit searcheth all things, yea, the deep things of God.', 'but god hath revealed them unto us by his spirit for the spirit searcheth all things yea the deep things of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 11, 'For what man knoweth the things of a man, save the spirit of man which is in him? even so the things of God knoweth no man, but the Spirit of God.', 'for what man knoweth the things of a man save the spirit of man which is in him even so the things of god knoweth no man but the spirit of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 12, 'Now we have received, not the spirit of the world, but the spirit which is of God; that we might know the things that are freely given to us of God.', 'now we have received not the spirit of the world but the spirit which is of god that we might know the things that are freely given to us of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 13, 'Which things also we speak, not in the words which man''s wisdom teacheth, but which the Holy Ghost teacheth; comparing spiritual things with spiritual.', 'which things also we speak not in the words which man s wisdom teacheth but which the holy ghost teacheth comparing spiritual things with spiritual');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 14, 'But the natural man receiveth not the things of the Spirit of God: for they are foolishness unto him: neither can he know {them}, because they are spiritually discerned.', 'but the natural man receiveth not the things of the spirit of god for they are foolishness unto him neither can he know them because they are spiritually discerned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 15, 'But he that is spiritual judgeth all things, yet he himself is judged of no man. {judgeth: or, discerneth} {judged: or, discerned}', 'but he that is spiritual judgeth all things yet he himself is judged of no man judgeth or discerneth judged or discerned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 2, 16, 'For who hath known the mind of the Lord, that he may instruct him? But we have the mind of Christ. {may: Gr. shall}', 'for who hath known the mind of the lord that he may instruct him but we have the mind of christ may gr shall');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 1, 'And I, brethren, could not speak unto you as unto spiritual, but as unto carnal, {even} as unto babes in Christ.', 'and i brethren could not speak unto you as unto spiritual but as unto carnal even as unto babes in christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 2, 'I have fed you with milk, and not with meat: for hitherto ye were not able {to bear it}, neither yet now are ye able.', 'i have fed you with milk and not with meat for hitherto ye were not able to bear it neither yet now are ye able');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 3, 'For ye are yet carnal: for whereas {there is} among you envying, and strife, and divisions, are ye not carnal, and walk as men? {divisions: or, factions} {as men: Gr. according to man?}', 'for ye are yet carnal for whereas there is among you envying and strife and divisions are ye not carnal and walk as men divisions or factions as men gr according to man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 4, 'For while one saith, I am of Paul; and another, I {am} of Apollos; are ye not carnal?', 'for while one saith i am of paul and another i am of apollos are ye not carnal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 5, 'Who then is Paul, and who {is} Apollos, but ministers by whom ye believed, even as the Lord gave to every man?', 'who then is paul and who is apollos but ministers by whom ye believed even as the lord gave to every man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 6, 'I have planted, Apollos watered; but God gave the increase.', 'i have planted apollos watered but god gave the increase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 7, 'So then neither is he that planteth any thing, neither he that watereth; but God that giveth the increase.', 'so then neither is he that planteth any thing neither he that watereth but god that giveth the increase');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 8, 'Now he that planteth and he that watereth are one: and every man shall receive his own reward according to his own labour.', 'now he that planteth and he that watereth are one and every man shall receive his own reward according to his own labour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 9, 'For we are labourers together with God: ye are God''s husbandry, {ye are} God''s building. {husbandry: or, tillage}', 'for we are labourers together with god ye are god s husbandry ye are god s building husbandry or tillage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 10, 'According to the grace of God which is given unto me, as a wise masterbuilder, I have laid the foundation, and another buildeth thereon. But let every man take heed how he buildeth thereupon.', 'according to the grace of god which is given unto me as a wise masterbuilder i have laid the foundation and another buildeth thereon but let every man take heed how he buildeth thereupon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 11, 'For other foundation can no man lay than that is laid, which is Jesus Christ.', 'for other foundation can no man lay than that is laid which is jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 12, 'Now if any man build upon this foundation gold, silver, precious stones, wood, hay, stubble;', 'now if any man build upon this foundation gold silver precious stones wood hay stubble');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 13, 'Every man''s work shall be made manifest: for the day shall declare it, because it shall be revealed by fire; and the fire shall try every man''s work of what sort it is. {it shall be: Gr. it is}', 'every man s work shall be made manifest for the day shall declare it because it shall be revealed by fire and the fire shall try every man s work of what sort it is it shall be gr it is');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 14, 'If any man''s work abide which he hath built thereupon, he shall receive a reward.', 'if any man s work abide which he hath built thereupon he shall receive a reward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 15, 'If any man''s work shall be burned, he shall suffer loss: but he himself shall be saved; yet so as by fire.', 'if any man s work shall be burned he shall suffer loss but he himself shall be saved yet so as by fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 16, 'Know ye not that ye are the temple of God, and {that} the Spirit of God dwelleth in you?', 'know ye not that ye are the temple of god and that the spirit of god dwelleth in you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 17, 'If any man defile the temple of God, him shall God destroy; for the temple of God is holy, which {temple} ye are. {defile: or, destroy}', 'if any man defile the temple of god him shall god destroy for the temple of god is holy which temple ye are defile or destroy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 18, 'Let no man deceive himself. If any man among you seemeth to be wise in this world, let him become a fool, that he may be wise.', 'let no man deceive himself if any man among you seemeth to be wise in this world let him become a fool that he may be wise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 19, 'For the wisdom of this world is foolishness with God. For it is written, He taketh the wise in their own craftiness.', 'for the wisdom of this world is foolishness with god for it is written he taketh the wise in their own craftiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 20, 'And again, The Lord knoweth the thoughts of the wise, that they are vain.', 'and again the lord knoweth the thoughts of the wise that they are vain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 21, 'Therefore let no man glory in men. For all things are yours;', 'therefore let no man glory in men for all things are yours');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 22, 'Whether Paul, or Apollos, or Cephas, or the world, or life, or death, or things present, or things to come; all are yours;', 'whether paul or apollos or cephas or the world or life or death or things present or things to come all are yours');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 3, 23, 'And ye are Christ''s; and Christ {is} God''s.', 'and ye are christ s and christ is god s');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 1, 'Let a man so account of us, as of the ministers of Christ, and stewards of the mysteries of God.', 'let a man so account of us as of the ministers of christ and stewards of the mysteries of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 2, 'Moreover it is required in stewards, that a man be found faithful.', 'moreover it is required in stewards that a man be found faithful');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 3, 'But with me it is a very small thing that I should be judged of you, or of man''s judgment: yea, I judge not mine own self. {judgment: Gr. day}', 'but with me it is a very small thing that i should be judged of you or of man s judgment yea i judge not mine own self judgment gr day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 4, 'For I know nothing by myself; yet am I not hereby justified: but he that judgeth me is the Lord. {know: or, I am not conscious of any fault}', 'for i know nothing by myself yet am i not hereby justified but he that judgeth me is the lord know or i am not conscious of any fault');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 5, 'Therefore judge nothing before the time, until the Lord come, who both will bring to light the hidden things of darkness, and will make manifest the counsels of the hearts: and then shall every man have praise of God.', 'therefore judge nothing before the time until the lord come who both will bring to light the hidden things of darkness and will make manifest the counsels of the hearts and then shall every man have praise of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 6, 'And these things, brethren, I have in a figure transferred to myself and {to} Apollos for your sakes; that ye might learn in us not to think {of men} above that which is written, that no one of you be puffed up for one against another.', 'and these things brethren i have in a figure transferred to myself and to apollos for your sakes that ye might learn in us not to think of men above that which is written that no one of you be puffed up for one against another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 7, 'For who maketh thee to differ {from another}? and what hast thou that thou didst not receive? now if thou didst receive {it}, why dost thou glory, as if thou hadst not received {it}? {maketh...: Gr. distinguisheth thee}', 'for who maketh thee to differ from another and what hast thou that thou didst not receive now if thou didst receive it why dost thou glory as if thou hadst not received it maketh gr distinguisheth thee');
