INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 4, 11, 'Even unto this present hour we both hunger, and thirst, and are naked, and are buffeted, and have no certain dwellingplace;', 'even unto this present hour we both hunger and thirst and are naked and are buffeted and have no certain dwellingplace');
