INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 5, 'To deliver such an one unto Satan for the destruction of the flesh, that the spirit may be saved in the day of the Lord Jesus.', 'to deliver such an one unto satan for the destruction of the flesh that the spirit may be saved in the day of the lord jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 6, 'Your glorying {is} not good. Know ye not that a little leaven leaveneth the whole lump?', 'your glorying is not good know ye not that a little leaven leaveneth the whole lump');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 7, 'Purge out therefore the old leaven, that ye may be a new lump, as ye are unleavened. For even Christ our passover is sacrificed for us: {is sacrificed; or, is slain}', 'purge out therefore the old leaven that ye may be a new lump as ye are unleavened for even christ our passover is sacrificed for us is sacrificed or is slain');
