INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 9, 'I wrote unto you in an epistle not to company with fornicators:', 'i wrote unto you in an epistle not to company with fornicators');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 10, 'Yet not altogether with the fornicators of this world, or with the covetous, or extortioners, or with idolaters; for then must ye needs go out of the world.', 'yet not altogether with the fornicators of this world or with the covetous or extortioners or with idolaters for then must ye needs go out of the world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 11, 'But now I have written unto you not to keep company, if any man that is called a brother be a fornicator, or covetous, or an idolater, or a railer, or a drunkard, or an extortioner; with such an one no not to eat.', 'but now i have written unto you not to keep company if any man that is called a brother be a fornicator or covetous or an idolater or a railer or a drunkard or an extortioner with such an one no not to eat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 12, 'For what have I to do to judge them also that are without? do not ye judge them that are within?', 'for what have i to do to judge them also that are without do not ye judge them that are within');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 5, 13, 'But them that are without God judgeth. Therefore put away from among yourselves that wicked person.', 'but them that are without god judgeth therefore put away from among yourselves that wicked person');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 1, 'Dare any of you, having a matter against another, go to law before the unjust, and not before the saints?', 'dare any of you having a matter against another go to law before the unjust and not before the saints');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 2, 'Do ye not know that the saints shall judge the world? and if the world shall be judged by you, are ye unworthy to judge the smallest matters?', 'do ye not know that the saints shall judge the world and if the world shall be judged by you are ye unworthy to judge the smallest matters');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 3, 'Know ye not that we shall judge angels? how much more things that pertain to this life?', 'know ye not that we shall judge angels how much more things that pertain to this life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 4, 'If then ye have judgments of things pertaining to this life, set them to judge who are least esteemed in the church.', 'if then ye have judgments of things pertaining to this life set them to judge who are least esteemed in the church');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 5, 'I speak to your shame. Is it so, that there is not a wise man among you? no, not one that shall be able to judge between his brethren?', 'i speak to your shame is it so that there is not a wise man among you no not one that shall be able to judge between his brethren');
