INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 17, 'But he that is joined unto the Lord is one spirit.', 'but he that is joined unto the lord is one spirit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 18, 'Flee fornication. Every sin that a man doeth is without the body; but he that committeth fornication sinneth against his own body.', 'flee fornication every sin that a man doeth is without the body but he that committeth fornication sinneth against his own body');
