INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 6, 20, 'For ye are bought with a price: therefore glorify God in your body, and in your spirit, which are God''s.', 'for ye are bought with a price therefore glorify god in your body and in your spirit which are god s');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 1, 'Now concerning the things whereof ye wrote unto me: {It is} good for a man not to touch a woman.', 'now concerning the things whereof ye wrote unto me it is good for a man not to touch a woman');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 2, 'Nevertheless, {to avoid} fornication, let every man have his own wife, and let every woman have her own husband.', 'nevertheless to avoid fornication let every man have his own wife and let every woman have her own husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 3, 'Let the husband render unto the wife due benevolence: and likewise also the wife unto the husband.', 'let the husband render unto the wife due benevolence and likewise also the wife unto the husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 4, 'The wife hath not power of her own body, but the husband: and likewise also the husband hath not power of his own body, but the wife.', 'the wife hath not power of her own body but the husband and likewise also the husband hath not power of his own body but the wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 5, 'Defraud ye not one the other, except {it be} with consent for a time, that ye may give yourselves to fasting and prayer; and come together again, that Satan tempt you not for your incontinency.', 'defraud ye not one the other except it be with consent for a time that ye may give yourselves to fasting and prayer and come together again that satan tempt you not for your incontinency');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 6, 'But I speak this by permission, {and} not of commandment.', 'but i speak this by permission and not of commandment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 7, 'For I would that all men were even as I myself. But every man hath his proper gift of God, one after this manner, and another after that.', 'for i would that all men were even as i myself but every man hath his proper gift of god one after this manner and another after that');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 8, 'I say therefore to the unmarried and widows, It is good for them if they abide even as I.', 'i say therefore to the unmarried and widows it is good for them if they abide even as i');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 9, 'But if they cannot contain, let them marry: for it is better to marry than to burn.', 'but if they cannot contain let them marry for it is better to marry than to burn');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 10, 'And unto the married I command, {yet} not I, but the Lord, Let not the wife depart from {her} husband:', 'and unto the married i command yet not i but the lord let not the wife depart from her husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 11, 'But and if she depart, let her remain unmarried, or be reconciled to {her} husband: and let not the husband put away {his} wife.', 'but and if she depart let her remain unmarried or be reconciled to her husband and let not the husband put away his wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 12, 'But to the rest speak I, not the Lord: If any brother hath a wife that believeth not, and she be pleased to dwell with him, let him not put her away.', 'but to the rest speak i not the lord if any brother hath a wife that believeth not and she be pleased to dwell with him let him not put her away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 13, 'And the woman which hath an husband that believeth not, and if he be pleased to dwell with her, let her not leave him.', 'and the woman which hath an husband that believeth not and if he be pleased to dwell with her let her not leave him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 14, 'For the unbelieving husband is sanctified by the wife, and the unbelieving wife is sanctified by the husband: else were your children unclean; but now are they holy.', 'for the unbelieving husband is sanctified by the wife and the unbelieving wife is sanctified by the husband else were your children unclean but now are they holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 15, 'But if the unbelieving depart, let him depart. A brother or a sister is not under bondage in such {cases}: but God hath called us to peace. {to peace: Gr. in peace}', 'but if the unbelieving depart let him depart a brother or a sister is not under bondage in such cases but god hath called us to peace to peace gr in peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 16, 'For what knowest thou, O wife, whether thou shalt save {thy} husband? or how knowest thou, O man, whether thou shalt save {thy} wife? {how: Gr. what}', 'for what knowest thou o wife whether thou shalt save thy husband or how knowest thou o man whether thou shalt save thy wife how gr what');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 17, 'But as God hath distributed to every man, as the Lord hath called every one, so let him walk. And so ordain I in all churches.', 'but as god hath distributed to every man as the lord hath called every one so let him walk and so ordain i in all churches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 18, 'Is any man called being circumcised? let him not become uncircumcised. Is any called in uncircumcision? let him not be circumcised.', 'is any man called being circumcised let him not become uncircumcised is any called in uncircumcision let him not be circumcised');
