INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 23, 'Ye are bought with a price; be not ye the servants of men.', 'ye are bought with a price be not ye the servants of men');
