INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 27, 'Art thou bound unto a wife? seek not to be loosed. Art thou loosed from a wife? seek not a wife.', 'art thou bound unto a wife seek not to be loosed art thou loosed from a wife seek not a wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 28, 'But and if thou marry, thou hast not sinned; and if a virgin marry, she hath not sinned. Nevertheless such shall have trouble in the flesh: but I spare you.', 'but and if thou marry thou hast not sinned and if a virgin marry she hath not sinned nevertheless such shall have trouble in the flesh but i spare you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 29, 'But this I say, brethren, the time {is} short: it remaineth, that both they that have wives be as though they had none;', 'but this i say brethren the time is short it remaineth that both they that have wives be as though they had none');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 30, 'And they that weep, as though they wept not; and they that rejoice, as though they rejoiced not; and they that buy, as though they possessed not;', 'and they that weep as though they wept not and they that rejoice as though they rejoiced not and they that buy as though they possessed not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 31, 'And they that use this world, as not abusing {it}: for the fashion of this world passeth away.', 'and they that use this world as not abusing it for the fashion of this world passeth away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 32, 'But I would have you without carefulness. He that is unmarried careth for the things that belong to the Lord, how he may please the Lord: {that belong...: Gr. of the Lord}', 'but i would have you without carefulness he that is unmarried careth for the things that belong to the lord how he may please the lord that belong gr of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 33, 'But he that is married careth for the things that are of the world, how he may please {his} wife.', 'but he that is married careth for the things that are of the world how he may please his wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 34, 'There is difference {also} between a wife and a virgin. The unmarried woman careth for the things of the Lord, that she may be holy both in body and in spirit: but she that is married careth for the things of the world, how she may please {her} husband.', 'there is difference also between a wife and a virgin the unmarried woman careth for the things of the lord that she may be holy both in body and in spirit but she that is married careth for the things of the world how she may please her husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 35, 'And this I speak for your own profit; not that I may cast a snare upon you, but for that which is comely, and that ye may attend upon the Lord without distraction.', 'and this i speak for your own profit not that i may cast a snare upon you but for that which is comely and that ye may attend upon the lord without distraction');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 36, 'But if any man think that he behaveth himself uncomely toward his virgin, if she pass the flower of {her} age, and need so require, let him do what he will, he sinneth not: let them marry.', 'but if any man think that he behaveth himself uncomely toward his virgin if she pass the flower of her age and need so require let him do what he will he sinneth not let them marry');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 37, 'Nevertheless he that standeth stedfast in his heart, having no necessity, but hath power over his own will, and hath so decreed in his heart that he will keep his virgin, doeth well.', 'nevertheless he that standeth stedfast in his heart having no necessity but hath power over his own will and hath so decreed in his heart that he will keep his virgin doeth well');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 38, 'So then he that giveth {her} in marriage doeth well; but he that giveth {her} not in marriage doeth better.', 'so then he that giveth her in marriage doeth well but he that giveth her not in marriage doeth better');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 39, 'The wife is bound by the law as long as her husband liveth; but if her husband be dead, she is at liberty to be married to whom she will; only in the Lord.', 'the wife is bound by the law as long as her husband liveth but if her husband be dead she is at liberty to be married to whom she will only in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 7, 40, 'But she is happier if she so abide, after my judgment: and I think also that I have the Spirit of God.', 'but she is happier if she so abide after my judgment and i think also that i have the spirit of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 1, 'Now as touching things offered unto idols, we know that we all have knowledge. Knowledge puffeth up, but charity edifieth.', 'now as touching things offered unto idols we know that we all have knowledge knowledge puffeth up but charity edifieth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 2, 'And if any man think that he knoweth any thing, he knoweth nothing yet as he ought to know.', 'and if any man think that he knoweth any thing he knoweth nothing yet as he ought to know');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 3, 'But if any man love God, the same is known of him.', 'but if any man love god the same is known of him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 4, 'As concerning therefore the eating of those things that are offered in sacrifice unto idols, we know that an idol {is} nothing in the world, and that {there is} none other God but one.', 'as concerning therefore the eating of those things that are offered in sacrifice unto idols we know that an idol is nothing in the world and that there is none other god but one');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 5, 'For though there be that are called gods, whether in heaven or in earth, (as there be gods many, and lords many,)', 'for though there be that are called gods whether in heaven or in earth as there be gods many and lords many');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 6, 'But to us {there is but} one God, the Father, of whom {are} all things, and we in him; and one Lord Jesus Christ, by whom {are} all things, and we by him. {in: or, for}', 'but to us there is but one god the father of whom are all things and we in him and one lord jesus christ by whom are all things and we by him in or for');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 7, 'Howbeit {there is} not in every man that knowledge: for some with conscience of the idol unto this hour eat {it} as a thing offered unto an idol; and their conscience being weak is defiled.', 'howbeit there is not in every man that knowledge for some with conscience of the idol unto this hour eat it as a thing offered unto an idol and their conscience being weak is defiled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 8, 'But meat commendeth us not to God: for neither, if we eat, are we the better; neither, if we eat not, are we the worse. {are we the better: or, have we the more} {are we the worse: or, have we the less}', 'but meat commendeth us not to god for neither if we eat are we the better neither if we eat not are we the worse are we the better or have we the more are we the worse or have we the less');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 9, 'But take heed lest by any means this liberty of yours become a stumblingblock to them that are weak. {liberty: or, power}', 'but take heed lest by any means this liberty of yours become a stumblingblock to them that are weak liberty or power');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 10, 'For if any man see thee which hast knowledge sit at meat in the idol''s temple, shall not the conscience of him which is weak be emboldened to eat those things which are offered to idols; {emboldened: Gr. edified}', 'for if any man see thee which hast knowledge sit at meat in the idol s temple shall not the conscience of him which is weak be emboldened to eat those things which are offered to idols emboldened gr edified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 11, 'And through thy knowledge shall the weak brother perish, for whom Christ died?', 'and through thy knowledge shall the weak brother perish for whom christ died');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 12, 'But when ye sin so against the brethren, and wound their weak conscience, ye sin against Christ.', 'but when ye sin so against the brethren and wound their weak conscience ye sin against christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 8, 13, 'Wherefore, if meat make my brother to offend, I will eat no flesh while the world standeth, lest I make my brother to offend.', 'wherefore if meat make my brother to offend i will eat no flesh while the world standeth lest i make my brother to offend');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 9, 1, 'Am I not an apostle? am I not free? have I not seen Jesus Christ our Lord? are not ye my work in the Lord?', 'am i not an apostle am i not free have i not seen jesus christ our lord are not ye my work in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 9, 2, 'If I be not an apostle unto others, yet doubtless I am to you: for the seal of mine apostleship are ye in the Lord.', 'if i be not an apostle unto others yet doubtless i am to you for the seal of mine apostleship are ye in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 9, 3, 'Mine answer to them that do examine me is this,', 'mine answer to them that do examine me is this');
