INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 10, 5, 'But with many of them God was not well pleased: for they were overthrown in the wilderness.', 'but with many of them god was not well pleased for they were overthrown in the wilderness');
