INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 12, 12, 'For as the body is one, and hath many members, and all the members of that one body, being many, are one body: so also {is} Christ.', 'for as the body is one and hath many members and all the members of that one body being many are one body so also is christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 12, 13, 'For by one Spirit are we all baptized into one body, whether {we be} Jews or Gentiles, whether {we be} bond or free; and have been all made to drink into one Spirit. {Gentiles: Gr. Greeks}', 'for by one spirit are we all baptized into one body whether we be jews or gentiles whether we be bond or free and have been all made to drink into one spirit gentiles gr greeks');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 12, 14, 'For the body is not one member, but many.', 'for the body is not one member but many');
