INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 15, 55, 'O death, where {is} thy sting? O grave, where {is} thy victory? {grave: or, hell}', 'o death where is thy sting o grave where is thy victory grave or hell');
