INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 3, 'And when I come, whomsoever ye shall approve by {your} letters, them will I send to bring your liberality unto Jerusalem. {liberality: Gr. gift}', 'and when i come whomsoever ye shall approve by your letters them will i send to bring your liberality unto jerusalem liberality gr gift');
