INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 16, 'That ye submit yourselves unto such, and to every one that helpeth with {us}, and laboureth.', 'that ye submit yourselves unto such and to every one that helpeth with us and laboureth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 17, 'I am glad of the coming of Stephanas and Fortunatus and Achaicus: for that which was lacking on your part they have supplied.', 'i am glad of the coming of stephanas and fortunatus and achaicus for that which was lacking on your part they have supplied');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 18, 'For they have refreshed my spirit and yours: therefore acknowledge ye them that are such.', 'for they have refreshed my spirit and yours therefore acknowledge ye them that are such');
