INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 20, 'All the brethren greet you. Greet ye one another with an holy kiss.', 'all the brethren greet you greet ye one another with an holy kiss');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 21, 'The salutation of {me} Paul with mine own hand.', 'the salutation of me paul with mine own hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 22, 'If any man love not the Lord Jesus Christ, let him be Anathema Maranatha.', 'if any man love not the lord jesus christ let him be anathema maranatha');
