INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 46, 'Unknown', 16, 24, 'My love {be} with you all in Christ Jesus. Amen. «{The first epistle} to the Corinthians was written from Philippi by Stephanas and Fortunatus and Achaicus and Timotheus.}»', 'my love be with you all in christ jesus amen the first epistle to the corinthians was written from philippi by stephanas and fortunatus and achaicus and timotheus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 1, 'Paul, an apostle of Jesus Christ by the will of God, and Timothy {our} brother, unto the church of God which is at Corinth, with all the saints which are in all Achaia:', 'paul an apostle of jesus christ by the will of god and timothy our brother unto the church of god which is at corinth with all the saints which are in all achaia');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 2, 'Grace {be} to you and peace from God our Father, and {from} the Lord Jesus Christ.', 'grace be to you and peace from god our father and from the lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 3, 'Blessed {be} God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort;', 'blessed be god even the father of our lord jesus christ the father of mercies and the god of all comfort');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 4, 'Who comforteth us in all our tribulation, that we may be able to comfort them which are in any trouble, by the comfort wherewith we ourselves are comforted of God.', 'who comforteth us in all our tribulation that we may be able to comfort them which are in any trouble by the comfort wherewith we ourselves are comforted of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 5, 'For as the sufferings of Christ abound in us, so our consolation also aboundeth by Christ.', 'for as the sufferings of christ abound in us so our consolation also aboundeth by christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 6, 'And whether we be afflicted, {it is} for your consolation and salvation, which is effectual in the enduring of the same sufferings which we also suffer: or whether we be comforted, {it is} for your consolation and salvation. {is effectual: or, is wrought}', 'and whether we be afflicted it is for your consolation and salvation which is effectual in the enduring of the same sufferings which we also suffer or whether we be comforted it is for your consolation and salvation is effectual or is wrought');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 7, 'And our hope of you {is} stedfast, knowing, that as ye are partakers of the sufferings, so {shall ye be} also of the consolation.', 'and our hope of you is stedfast knowing that as ye are partakers of the sufferings so shall ye be also of the consolation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 8, 'For we would not, brethren, have you ignorant of our trouble which came to us in Asia, that we were pressed out of measure, above strength, insomuch that we despaired even of life:', 'for we would not brethren have you ignorant of our trouble which came to us in asia that we were pressed out of measure above strength insomuch that we despaired even of life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 9, 'But we had the sentence of death in ourselves, that we should not trust in ourselves, but in God which raiseth the dead: {sentence: or, answer}', 'but we had the sentence of death in ourselves that we should not trust in ourselves but in god which raiseth the dead sentence or answer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 10, 'Who delivered us from so great a death, and doth deliver: in whom we trust that he will yet deliver {us};', 'who delivered us from so great a death and doth deliver in whom we trust that he will yet deliver us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 11, 'Ye also helping together by prayer for us, that for the gift {bestowed} upon us by the means of many persons thanks may be given by many on our behalf.', 'ye also helping together by prayer for us that for the gift bestowed upon us by the means of many persons thanks may be given by many on our behalf');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 12, 'For our rejoicing is this, the testimony of our conscience, that in simplicity and godly sincerity, not with fleshly wisdom, but by the grace of God, we have had our conversation in the world, and more abundantly to you-ward.', 'for our rejoicing is this the testimony of our conscience that in simplicity and godly sincerity not with fleshly wisdom but by the grace of god we have had our conversation in the world and more abundantly to you ward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 13, 'For we write none other things unto you, than what ye read or acknowledge; and I trust ye shall acknowledge even to the end;', 'for we write none other things unto you than what ye read or acknowledge and i trust ye shall acknowledge even to the end');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 14, 'As also ye have acknowledged us in part, that we are your rejoicing, even as ye also {are} ours in the day of the Lord Jesus.', 'as also ye have acknowledged us in part that we are your rejoicing even as ye also are ours in the day of the lord jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 15, 'And in this confidence I was minded to come unto you before, that ye might have a second benefit; {benefit: or, grace}', 'and in this confidence i was minded to come unto you before that ye might have a second benefit benefit or grace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 16, 'And to pass by you into Macedonia, and to come again out of Macedonia unto you, and of you to be brought on my way toward Judaea.', 'and to pass by you into macedonia and to come again out of macedonia unto you and of you to be brought on my way toward judaea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 17, 'When I therefore was thus minded, did I use lightness? or the things that I purpose, do I purpose according to the flesh, that with me there should be yea yea, and nay nay?', 'when i therefore was thus minded did i use lightness or the things that i purpose do i purpose according to the flesh that with me there should be yea yea and nay nay');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 18, 'But {as} God {is} true, our word toward you was not yea and nay. {word: or, preaching}', 'but as god is true our word toward you was not yea and nay word or preaching');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 19, 'For the Son of God, Jesus Christ, who was preached among you by us, {even} by me and Silvanus and Timotheus, was not yea and nay, but in him was yea.', 'for the son of god jesus christ who was preached among you by us even by me and silvanus and timotheus was not yea and nay but in him was yea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 20, 'For all the promises of God in him {are} yea, and in him Amen, unto the glory of God by us.', 'for all the promises of god in him are yea and in him amen unto the glory of god by us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 21, 'Now he which stablisheth us with you in Christ, and hath anointed us, {is} God;', 'now he which stablisheth us with you in christ and hath anointed us is god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 22, 'Who hath also sealed us, and given the earnest of the Spirit in our hearts.', 'who hath also sealed us and given the earnest of the spirit in our hearts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 23, 'Moreover I call God for a record upon my soul, that to spare you I came not as yet unto Corinth.', 'moreover i call god for a record upon my soul that to spare you i came not as yet unto corinth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 1, 24, 'Not for that we have dominion over your faith, but are helpers of your joy: for by faith ye stand.', 'not for that we have dominion over your faith but are helpers of your joy for by faith ye stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 1, 'But I determined this with myself, that I would not come again to you in heaviness.', 'but i determined this with myself that i would not come again to you in heaviness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 2, 'For if I make you sorry, who is he then that maketh me glad, but the same which is made sorry by me?', 'for if i make you sorry who is he then that maketh me glad but the same which is made sorry by me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 3, 'And I wrote this same unto you, lest, when I came, I should have sorrow from them of whom I ought to rejoice; having confidence in you all, that my joy is {the joy} of you all.', 'and i wrote this same unto you lest when i came i should have sorrow from them of whom i ought to rejoice having confidence in you all that my joy is the joy of you all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 4, 'For out of much affliction and anguish of heart I wrote unto you with many tears; not that ye should be grieved, but that ye might know the love which I have more abundantly unto you.', 'for out of much affliction and anguish of heart i wrote unto you with many tears not that ye should be grieved but that ye might know the love which i have more abundantly unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 5, 'But if any have caused grief, he hath not grieved me, but in part: that I may not overcharge you all.', 'but if any have caused grief he hath not grieved me but in part that i may not overcharge you all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 6, 'Sufficient to such a man {is} this punishment, which {was inflicted} of many. {punishment: or, censure}', 'sufficient to such a man is this punishment which was inflicted of many punishment or censure');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 7, 'So that contrariwise ye {ought} rather to forgive {him}, and comfort {him}, lest perhaps such a one should be swallowed up with overmuch sorrow.', 'so that contrariwise ye ought rather to forgive him and comfort him lest perhaps such a one should be swallowed up with overmuch sorrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 8, 'Wherefore I beseech you that ye would confirm {your} love toward him.', 'wherefore i beseech you that ye would confirm your love toward him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 9, 'For to this end also did I write, that I might know the proof of you, whether ye be obedient in all things.', 'for to this end also did i write that i might know the proof of you whether ye be obedient in all things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 10, 'To whom ye forgive any thing, I {forgive} also: for if I forgave any thing, to whom I forgave {it}, for your sakes {forgave I it} in the person of Christ; {person: or, sight}', 'to whom ye forgive any thing i forgive also for if i forgave any thing to whom i forgave it for your sakes forgave i it in the person of christ person or sight');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 11, 'Lest Satan should get an advantage of us: for we are not ignorant of his devices.', 'lest satan should get an advantage of us for we are not ignorant of his devices');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 12, 'Furthermore, when I came to Troas to {preach} Christ''s gospel, and a door was opened unto me of the Lord,', 'furthermore when i came to troas to preach christ s gospel and a door was opened unto me of the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 13, 'I had no rest in my spirit, because I found not Titus my brother: but taking my leave of them, I went from thence into Macedonia.', 'i had no rest in my spirit because i found not titus my brother but taking my leave of them i went from thence into macedonia');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 14, 'Now thanks {be} unto God, which always causeth us to triumph in Christ, and maketh manifest the savour of his knowledge by us in every place.', 'now thanks be unto god which always causeth us to triumph in christ and maketh manifest the savour of his knowledge by us in every place');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 15, 'For we are unto God a sweet savour of Christ, in them that are saved, and in them that perish:', 'for we are unto god a sweet savour of christ in them that are saved and in them that perish');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 16, 'To the one {we are} the savour of death unto death; and to the other the savour of life unto life. And who {is} sufficient for these things?', 'to the one we are the savour of death unto death and to the other the savour of life unto life and who is sufficient for these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 2, 17, 'For we are not as many, which corrupt the word of God: but as of sincerity, but as of God, in the sight of God speak we in Christ. {corrupt: or, deal deceitfully with} {in Christ: or, of Christ}', 'for we are not as many which corrupt the word of god but as of sincerity but as of god in the sight of god speak we in christ corrupt or deal deceitfully with in christ or of christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 1, 'Do we begin again to commend ourselves? or need we, as some {others}, epistles of commendation to you, or {letters} of commendation from you?', 'do we begin again to commend ourselves or need we as some others epistles of commendation to you or letters of commendation from you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 2, 'Ye are our epistle written in our hearts, known and read of all men:', 'ye are our epistle written in our hearts known and read of all men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 3, '{Forasmuch as ye are} manifestly declared to be the epistle of Christ ministered by us, written not with ink, but with the Spirit of the living God; not in tables of stone, but in fleshy tables of the heart.', 'forasmuch as ye are manifestly declared to be the epistle of christ ministered by us written not with ink but with the spirit of the living god not in tables of stone but in fleshy tables of the heart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 4, 'And such trust have we through Christ to God-ward:', 'and such trust have we through christ to god ward');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 5, 'Not that we are sufficient of ourselves to think any thing as of ourselves; but our sufficiency {is} of God;', 'not that we are sufficient of ourselves to think any thing as of ourselves but our sufficiency is of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 6, 'Who also hath made us able ministers of the new testament; not of the letter, but of the spirit: for the letter killeth, but the spirit giveth life. {giveth life: or, quickeneth}', 'who also hath made us able ministers of the new testament not of the letter but of the spirit for the letter killeth but the spirit giveth life giveth life or quickeneth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 7, 'But if the ministration of death, written {and} engraven in stones, was glorious, so that the children of Israel could not stedfastly behold the face of Moses for the glory of his countenance; which {glory} was to be done away:', 'but if the ministration of death written and engraven in stones was glorious so that the children of israel could not stedfastly behold the face of moses for the glory of his countenance which glory was to be done away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 8, 'How shall not the ministration of the spirit be rather glorious?', 'how shall not the ministration of the spirit be rather glorious');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 9, 'For if the ministration of condemnation {be} glory, much more doth the ministration of righteousness exceed in glory.', 'for if the ministration of condemnation be glory much more doth the ministration of righteousness exceed in glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 10, 'For even that which was made glorious had no glory in this respect, by reason of the glory that excelleth.', 'for even that which was made glorious had no glory in this respect by reason of the glory that excelleth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 3, 11, 'For if that which is done away {was} glorious, much more that which remaineth {is} glorious.', 'for if that which is done away was glorious much more that which remaineth is glorious');
