INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 7, 'And not by his coming only, but by the consolation wherewith he was comforted in you, when he told us your earnest desire, your mourning, your fervent mind toward me; so that I rejoiced the more.', 'and not by his coming only but by the consolation wherewith he was comforted in you when he told us your earnest desire your mourning your fervent mind toward me so that i rejoiced the more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 8, 'For though I made you sorry with a letter, I do not repent, though I did repent: for I perceive that the same epistle hath made you sorry, though {it were} but for a season.', 'for though i made you sorry with a letter i do not repent though i did repent for i perceive that the same epistle hath made you sorry though it were but for a season');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 9, 'Now I rejoice, not that ye were made sorry, but that ye sorrowed to repentance: for ye were made sorry after a godly manner, that ye might receive damage by us in nothing. {after...: or, according to God}', 'now i rejoice not that ye were made sorry but that ye sorrowed to repentance for ye were made sorry after a godly manner that ye might receive damage by us in nothing after or according to god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 10, 'For godly sorrow worketh repentance to salvation not to be repented of: but the sorrow of the world worketh death.', 'for godly sorrow worketh repentance to salvation not to be repented of but the sorrow of the world worketh death');
