INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 12, 'Wherefore, though I wrote unto you, {I did it} not for his cause that had done the wrong, nor for his cause that suffered wrong, but that our care for you in the sight of God might appear unto you.', 'wherefore though i wrote unto you i did it not for his cause that had done the wrong nor for his cause that suffered wrong but that our care for you in the sight of god might appear unto you');
