INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 15, 'And his inward affection is more abundant toward you, whilst he remembereth the obedience of you all, how with fear and trembling ye received him. {inward...: Gr. bowels}', 'and his inward affection is more abundant toward you whilst he remembereth the obedience of you all how with fear and trembling ye received him inward gr bowels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 7, 16, 'I rejoice therefore that I have confidence in you in all {things}.', 'i rejoice therefore that i have confidence in you in all things');
