INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 3, 'For to {their} power, I bear record, yea, and beyond {their} power {they were} willing of themselves;', 'for to their power i bear record yea and beyond their power they were willing of themselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 4, 'Praying us with much intreaty that we would receive the gift, and {take upon us} the fellowship of the ministering to the saints.', 'praying us with much intreaty that we would receive the gift and take upon us the fellowship of the ministering to the saints');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 5, 'And {this they did}, not as we hoped, but first gave their own selves to the Lord, and unto us by the will of God.', 'and this they did not as we hoped but first gave their own selves to the lord and unto us by the will of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 6, 'Insomuch that we desired Titus, that as he had begun, so he would also finish in you the same grace also. {grace: or, gift}', 'insomuch that we desired titus that as he had begun so he would also finish in you the same grace also grace or gift');
