INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 8, 'I speak not by commandment, but by occasion of the forwardness of others, and to prove the sincerity of your love.', 'i speak not by commandment but by occasion of the forwardness of others and to prove the sincerity of your love');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 9, 'For ye know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that ye through his poverty might be rich.', 'for ye know the grace of our lord jesus christ that though he was rich yet for your sakes he became poor that ye through his poverty might be rich');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 10, 'And herein I give {my} advice: for this is expedient for you, who have begun before, not only to do, but also to be forward a year ago. {forward: Gr. willing}', 'and herein i give my advice for this is expedient for you who have begun before not only to do but also to be forward a year ago forward gr willing');
