INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 14, 'But by an equality, {that} now at this time your abundance {may be a supply} for their want, that their abundance also may be {a supply} for your want: that there may be equality:', 'but by an equality that now at this time your abundance may be a supply for their want that their abundance also may be a supply for your want that there may be equality');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 15, 'As it is written, He that {had gathered} much had nothing over; and he that {had gathered} little had no lack.', 'as it is written he that had gathered much had nothing over and he that had gathered little had no lack');
