INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 8, 20, 'Avoiding this, that no man should blame us in this abundance which is administered by us:', 'avoiding this that no man should blame us in this abundance which is administered by us');
