INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 9, 4, 'Lest haply if they of Macedonia come with me, and find you unprepared, we (that we say not, ye) should be ashamed in this same confident boasting.', 'lest haply if they of macedonia come with me and find you unprepared we that we say not ye should be ashamed in this same confident boasting');
