INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 9, 6, 'But this {I say}, He which soweth sparingly shall reap also sparingly; and he which soweth bountifully shall reap also bountifully.', 'but this i say he which soweth sparingly shall reap also sparingly and he which soweth bountifully shall reap also bountifully');
