INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 9, 8, 'And God {is} able to make all grace abound toward you; that ye, always having all sufficiency in all {things}, may abound to every good work:', 'and god is able to make all grace abound toward you that ye always having all sufficiency in all things may abound to every good work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 9, 9, '(As it is written, He hath dispersed abroad; he hath given to the poor: his righteousness remaineth for ever.', 'as it is written he hath dispersed abroad he hath given to the poor his righteousness remaineth for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 9, 10, 'Now he that ministereth seed to the sower both minister bread for {your} food, and multiply your seed sown, and increase the fruits of your righteousness;)', 'now he that ministereth seed to the sower both minister bread for your food and multiply your seed sown and increase the fruits of your righteousness');
