INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 10, 6, 'And having in a readiness to revenge all disobedience, when your obedience is fulfilled.', 'and having in a readiness to revenge all disobedience when your obedience is fulfilled');
