INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 10, 9, 'That I may not seem as if I would terrify you by letters.', 'that i may not seem as if i would terrify you by letters');
