INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 47, 'Unknown', 10, 11, 'Let such an one think this, that, such as we are in word by letters when we are absent, such {will we be} also in deed when we are present.', 'let such an one think this that such as we are in word by letters when we are absent such will we be also in deed when we are present');
