INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 50, 'Unknown', 2, 26, 'For he longed after you all, and was full of heaviness, because that ye had heard that he had been sick.', 'for he longed after you all and was full of heaviness because that ye had heard that he had been sick');
