INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 50, 'Unknown', 3, 9, 'And be found in him, not having mine own righteousness, which is of the law, but that which is through the faith of Christ, the righteousness which is of God by faith:', 'and be found in him not having mine own righteousness which is of the law but that which is through the faith of christ the righteousness which is of god by faith');
