INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 50, 'Unknown', 3, 11, 'If by any means I might attain unto the resurrection of the dead.', 'if by any means i might attain unto the resurrection of the dead');
