INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 50, 'Unknown', 3, 13, 'Brethren, I count not myself to have apprehended: but {this} one thing {I do}, forgetting those things which are behind, and reaching forth unto those things which are before,', 'brethren i count not myself to have apprehended but this one thing i do forgetting those things which are behind and reaching forth unto those things which are before');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 50, 'Unknown', 3, 14, 'I press toward the mark for the prize of the high calling of God in Christ Jesus.', 'i press toward the mark for the prize of the high calling of god in christ jesus');
