INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 9, 'With Onesimus, a faithful and beloved brother, who is {one} of you. They shall make known unto you all things which {are done} here.', 'with onesimus a faithful and beloved brother who is one of you they shall make known unto you all things which are done here');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 10, 'Aristarchus my fellowprisoner saluteth you, and Marcus, sister''s son to Barnabas, (touching whom ye received commandments: if he come unto you, receive him;)', 'aristarchus my fellowprisoner saluteth you and marcus sister s son to barnabas touching whom ye received commandments if he come unto you receive him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 11, 'And Jesus, which is called Justus, who are of the circumcision. These only {are my} fellowworkers unto the kingdom of God, which have been a comfort unto me.', 'and jesus which is called justus who are of the circumcision these only are my fellowworkers unto the kingdom of god which have been a comfort unto me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 12, 'Epaphras, who is {one} of you, a servant of Christ, saluteth you, always labouring fervently for you in prayers, that ye may stand perfect and complete in all the will of God. {labouring...: or, striving} {complete: or, filled}', 'epaphras who is one of you a servant of christ saluteth you always labouring fervently for you in prayers that ye may stand perfect and complete in all the will of god labouring or striving complete or filled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 13, 'For I bear him record, that he hath a great zeal for you, and them {that are} in Laodicea, and them in Hierapolis.', 'for i bear him record that he hath a great zeal for you and them that are in laodicea and them in hierapolis');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 14, 'Luke, the beloved physician, and Demas, greet you.', 'luke the beloved physician and demas greet you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 15, 'Salute the brethren which are in Laodicea, and Nymphas, and the church which is in his house.', 'salute the brethren which are in laodicea and nymphas and the church which is in his house');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 16, 'And when this epistle is read among you, cause that it be read also in the church of the Laodiceans; and that ye likewise read the {epistle} from Laodicea.', 'and when this epistle is read among you cause that it be read also in the church of the laodiceans and that ye likewise read the epistle from laodicea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 17, 'And say to Archippus, Take heed to the ministry which thou hast received in the Lord, that thou fulfil it.', 'and say to archippus take heed to the ministry which thou hast received in the lord that thou fulfil it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 51, 'Unknown', 4, 18, 'The salutation by the hand of me Paul. Remember my bonds. Grace {be} with you. Amen. «{Written from Rome to Colossians by Tychicus and Onesimus.}»', 'the salutation by the hand of me paul remember my bonds grace be with you amen written from rome to colossians by tychicus and onesimus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 1, 'Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians {which is} in God the Father and {in} the Lord Jesus Christ: Grace {be} unto you, and peace, from God our Father, and the Lord Jesus Christ.', 'paul and silvanus and timotheus unto the church of the thessalonians which is in god the father and in the lord jesus christ grace be unto you and peace from god our father and the lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 2, 'We give thanks to God always for you all, making mention of you in our prayers;', 'we give thanks to god always for you all making mention of you in our prayers');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 3, 'Remembering without ceasing your work of faith, and labour of love, and patience of hope in our Lord Jesus Christ, in the sight of God and our Father;', 'remembering without ceasing your work of faith and labour of love and patience of hope in our lord jesus christ in the sight of god and our father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 4, 'Knowing, brethren beloved, your election of God. {beloved...: or, beloved of God, your election}', 'knowing brethren beloved your election of god beloved or beloved of god your election');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 5, 'For our gospel came not unto you in word only, but also in power, and in the Holy Ghost, and in much assurance; as ye know what manner of men we were among you for your sake.', 'for our gospel came not unto you in word only but also in power and in the holy ghost and in much assurance as ye know what manner of men we were among you for your sake');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 6, 'And ye became followers of us, and of the Lord, having received the word in much affliction, with joy of the Holy Ghost:', 'and ye became followers of us and of the lord having received the word in much affliction with joy of the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 7, 'So that ye were ensamples to all that believe in Macedonia and Achaia.', 'so that ye were ensamples to all that believe in macedonia and achaia');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 8, 'For from you sounded out the word of the Lord not only in Macedonia and Achaia, but also in every place your faith to God-ward is spread abroad; so that we need not to speak any thing.', 'for from you sounded out the word of the lord not only in macedonia and achaia but also in every place your faith to god ward is spread abroad so that we need not to speak any thing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 9, 'For they themselves shew of us what manner of entering in we had unto you, and how ye turned to God from idols to serve the living and true God;', 'for they themselves shew of us what manner of entering in we had unto you and how ye turned to god from idols to serve the living and true god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 1, 10, 'And to wait for his Son from heaven, whom he raised from the dead, {even} Jesus, which delivered us from the wrath to come.', 'and to wait for his son from heaven whom he raised from the dead even jesus which delivered us from the wrath to come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 1, 'For yourselves, brethren, know our entrance in unto you, that it was not in vain:', 'for yourselves brethren know our entrance in unto you that it was not in vain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 2, 'But even after that we had suffered before, and were shamefully entreated, as ye know, at Philippi, we were bold in our God to speak unto you the gospel of God with much contention.', 'but even after that we had suffered before and were shamefully entreated as ye know at philippi we were bold in our god to speak unto you the gospel of god with much contention');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 3, 'For our exhortation {was} not of deceit, nor of uncleanness, nor in guile:', 'for our exhortation was not of deceit nor of uncleanness nor in guile');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 4, 'But as we were allowed of God to be put in trust with the gospel, even so we speak; not as pleasing men, but God, which trieth our hearts.', 'but as we were allowed of god to be put in trust with the gospel even so we speak not as pleasing men but god which trieth our hearts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 5, 'For neither at any time used we flattering words, as ye know, nor a cloke of covetousness; God {is} witness:', 'for neither at any time used we flattering words as ye know nor a cloke of covetousness god is witness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 6, 'Nor of men sought we glory, neither of you, nor {yet} of others, when we might have been burdensome, as the apostles of Christ. {been...: or, used authority}', 'nor of men sought we glory neither of you nor yet of others when we might have been burdensome as the apostles of christ been or used authority');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 7, 'But we were gentle among you, even as a nurse cherisheth her children:', 'but we were gentle among you even as a nurse cherisheth her children');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 8, 'So being affectionately desirous of you, we were willing to have imparted unto you, not the gospel of God only, but also our own souls, because ye were dear unto us.', 'so being affectionately desirous of you we were willing to have imparted unto you not the gospel of god only but also our own souls because ye were dear unto us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 9, 'For ye remember, brethren, our labour and travail: for labouring night and day, because we would not be chargeable unto any of you, we preached unto you the gospel of God.', 'for ye remember brethren our labour and travail for labouring night and day because we would not be chargeable unto any of you we preached unto you the gospel of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 10, 'Ye {are} witnesses, and God {also}, how holily and justly and unblameably we behaved ourselves among you that believe:', 'ye are witnesses and god also how holily and justly and unblameably we behaved ourselves among you that believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 11, 'As ye know how we exhorted and comforted and charged every one of you, as a father {doth} his children,', 'as ye know how we exhorted and comforted and charged every one of you as a father doth his children');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 12, 'That ye would walk worthy of God, who hath called you unto his kingdom and glory.', 'that ye would walk worthy of god who hath called you unto his kingdom and glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 13, 'For this cause also thank we God without ceasing, because, when ye received the word of God which ye heard of us, ye received {it} not {as} the word of men, but as it is in truth, the word of God, which effectually worketh also in you that believe.', 'for this cause also thank we god without ceasing because when ye received the word of god which ye heard of us ye received it not as the word of men but as it is in truth the word of god which effectually worketh also in you that believe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 14, 'For ye, brethren, became followers of the churches of God which in Judaea are in Christ Jesus: for ye also have suffered like things of your own countrymen, even as they {have} of the Jews:', 'for ye brethren became followers of the churches of god which in judaea are in christ jesus for ye also have suffered like things of your own countrymen even as they have of the jews');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 15, 'Who both killed the Lord Jesus, and their own prophets, and have persecuted us; and they please not God, and are contrary to all men: {persecuted us: or, chased us out}', 'who both killed the lord jesus and their own prophets and have persecuted us and they please not god and are contrary to all men persecuted us or chased us out');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 16, 'Forbidding us to speak to the Gentiles that they might be saved, to fill up their sins alway: for the wrath is come upon them to the uttermost.', 'forbidding us to speak to the gentiles that they might be saved to fill up their sins alway for the wrath is come upon them to the uttermost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 17, 'But we, brethren, being taken from you for a short time in presence, not in heart, endeavoured the more abundantly to see your face with great desire.', 'but we brethren being taken from you for a short time in presence not in heart endeavoured the more abundantly to see your face with great desire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 18, 'Wherefore we would have come unto you, even I Paul, once and again; but Satan hindered us.', 'wherefore we would have come unto you even i paul once and again but satan hindered us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 19, 'For what {is} our hope, or joy, or crown of rejoicing? {Are} not even ye in the presence of our Lord Jesus Christ at his coming? {rejoicing: or, glorying?}', 'for what is our hope or joy or crown of rejoicing are not even ye in the presence of our lord jesus christ at his coming rejoicing or glorying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 2, 20, 'For ye are our glory and joy.', 'for ye are our glory and joy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 1, 'Wherefore when we could no longer forbear, we thought it good to be left at Athens alone;', 'wherefore when we could no longer forbear we thought it good to be left at athens alone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 2, 'And sent Timotheus, our brother, and minister of God, and our fellowlabourer in the gospel of Christ, to establish you, and to comfort you concerning your faith:', 'and sent timotheus our brother and minister of god and our fellowlabourer in the gospel of christ to establish you and to comfort you concerning your faith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 3, 'That no man should be moved by these afflictions: for yourselves know that we are appointed thereunto. {there unto: or, to sufferings, or, to persecution}', 'that no man should be moved by these afflictions for yourselves know that we are appointed thereunto there unto or to sufferings or to persecution');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 4, 'For verily, when we were with you, we told you before that we should suffer tribulation; even as it came to pass, and ye know.', 'for verily when we were with you we told you before that we should suffer tribulation even as it came to pass and ye know');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 5, 'For this cause, when I could no longer forbear, I sent to know your faith, lest by some means the tempter have tempted you, and our labour be in vain.', 'for this cause when i could no longer forbear i sent to know your faith lest by some means the tempter have tempted you and our labour be in vain');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 6, 'But now when Timotheus came from you unto us, and brought us good tidings of your faith and charity, and that ye have good remembrance of us always, desiring greatly to see us, as we also {to see} you:', 'but now when timotheus came from you unto us and brought us good tidings of your faith and charity and that ye have good remembrance of us always desiring greatly to see us as we also to see you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 7, 'Therefore, brethren, we were comforted over you in all our affliction and distress by your faith:', 'therefore brethren we were comforted over you in all our affliction and distress by your faith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 8, 'For now we live, if ye stand fast in the Lord.', 'for now we live if ye stand fast in the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 9, 'For what thanks can we render to God again for you, for all the joy wherewith we joy for your sakes before our God;', 'for what thanks can we render to god again for you for all the joy wherewith we joy for your sakes before our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 10, 'Night and day praying exceedingly that we might see your face, and might perfect that which is lacking in your faith?', 'night and day praying exceedingly that we might see your face and might perfect that which is lacking in your faith');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 11, 'Now God himself and our Father, and our Lord Jesus Christ, direct our way unto you. {direct: or, guide}', 'now god himself and our father and our lord jesus christ direct our way unto you direct or guide');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 12, 'And the Lord make you to increase and abound in love one toward another, and toward all {men}, even as we {do} toward you:', 'and the lord make you to increase and abound in love one toward another and toward all men even as we do toward you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 3, 13, 'To the end he may stablish your hearts unblameable in holiness before God, even our Father, at the coming of our Lord Jesus Christ with all his saints. {saints: or, holy ones, or, angels}', 'to the end he may stablish your hearts unblameable in holiness before god even our father at the coming of our lord jesus christ with all his saints saints or holy ones or angels');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 1, 'Furthermore then we beseech you, brethren, and exhort {you} by the Lord Jesus, that as ye have received of us how ye ought to walk and to please God, {so} ye would abound more and more. {beseech: or, request} {exhort: or, beseech}', 'furthermore then we beseech you brethren and exhort you by the lord jesus that as ye have received of us how ye ought to walk and to please god so ye would abound more and more beseech or request exhort or beseech');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 2, 'For ye know what commandments we gave you by the Lord Jesus.', 'for ye know what commandments we gave you by the lord jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 3, 'For this is the will of God, {even} your sanctification, that ye should abstain from fornication:', 'for this is the will of god even your sanctification that ye should abstain from fornication');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 4, 'That every one of you should know how to possess his vessel in sanctification and honour;', 'that every one of you should know how to possess his vessel in sanctification and honour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 5, 'Not in the lust of concupiscence, even as the Gentiles which know not God:', 'not in the lust of concupiscence even as the gentiles which know not god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 6, 'That no {man} go beyond and defraud his brother in {any} matter: because that the Lord {is} the avenger of all such, as we also have forewarned you and testified. {defraud: or, oppress, or, overreach} {in...: or, in the matter}', 'that no man go beyond and defraud his brother in any matter because that the lord is the avenger of all such as we also have forewarned you and testified defraud or oppress or overreach in or in the matter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 7, 'For God hath not called us unto uncleanness, but unto holiness.', 'for god hath not called us unto uncleanness but unto holiness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 8, 'He therefore that despiseth, despiseth not man, but God, who hath also given unto us his holy Spirit. {despiseth: or, rejecteth}', 'he therefore that despiseth despiseth not man but god who hath also given unto us his holy spirit despiseth or rejecteth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 9, 'But as touching brotherly love ye need not that I write unto you: for ye yourselves are taught of God to love one another.', 'but as touching brotherly love ye need not that i write unto you for ye yourselves are taught of god to love one another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 10, 'And indeed ye do it toward all the brethren which are in all Macedonia: but we beseech you, brethren, that ye increase more and more;', 'and indeed ye do it toward all the brethren which are in all macedonia but we beseech you brethren that ye increase more and more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 11, 'And that ye study to be quiet, and to do your own business, and to work with your own hands, as we commanded you;', 'and that ye study to be quiet and to do your own business and to work with your own hands as we commanded you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 12, 'That ye may walk honestly toward them that are without, and {that} ye may have lack of nothing. {of...: or, of no man}', 'that ye may walk honestly toward them that are without and that ye may have lack of nothing of or of no man');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 13, 'But I would not have you to be ignorant, brethren, concerning them which are asleep, that ye sorrow not, even as others which have no hope.', 'but i would not have you to be ignorant brethren concerning them which are asleep that ye sorrow not even as others which have no hope');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 14, 'For if we believe that Jesus died and rose again, even so them also which sleep in Jesus will God bring with him.', 'for if we believe that jesus died and rose again even so them also which sleep in jesus will god bring with him');
