INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 16, 'For the Lord himself shall descend from heaven with a shout, with the voice of the archangel, and with the trump of God: and the dead in Christ shall rise first:', 'for the lord himself shall descend from heaven with a shout with the voice of the archangel and with the trump of god and the dead in christ shall rise first');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 17, 'Then we which are alive {and} remain shall be caught up together with them in the clouds, to meet the Lord in the air: and so shall we ever be with the Lord.', 'then we which are alive and remain shall be caught up together with them in the clouds to meet the lord in the air and so shall we ever be with the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 4, 18, 'Wherefore comfort one another with these words. {comfort: or, exhort}', 'wherefore comfort one another with these words comfort or exhort');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 1, 'But of the times and the seasons, brethren, ye have no need that I write unto you.', 'but of the times and the seasons brethren ye have no need that i write unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 2, 'For yourselves know perfectly that the day of the Lord so cometh as a thief in the night.', 'for yourselves know perfectly that the day of the lord so cometh as a thief in the night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 3, 'For when they shall say, Peace and safety; then sudden destruction cometh upon them, as travail upon a woman with child; and they shall not escape.', 'for when they shall say peace and safety then sudden destruction cometh upon them as travail upon a woman with child and they shall not escape');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 4, 'But ye, brethren, are not in darkness, that that day should overtake you as a thief.', 'but ye brethren are not in darkness that that day should overtake you as a thief');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 5, 'Ye are all the children of light, and the children of the day: we are not of the night, nor of darkness.', 'ye are all the children of light and the children of the day we are not of the night nor of darkness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 6, 'Therefore let us not sleep, as {do} others; but let us watch and be sober.', 'therefore let us not sleep as do others but let us watch and be sober');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 7, 'For they that sleep sleep in the night; and they that be drunken are drunken in the night.', 'for they that sleep sleep in the night and they that be drunken are drunken in the night');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 8, 'But let us, who are of the day, be sober, putting on the breastplate of faith and love; and for an helmet, the hope of salvation.', 'but let us who are of the day be sober putting on the breastplate of faith and love and for an helmet the hope of salvation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 9, 'For God hath not appointed us to wrath, but to obtain salvation by our Lord Jesus Christ,', 'for god hath not appointed us to wrath but to obtain salvation by our lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 10, 'Who died for us, that, whether we wake or sleep, we should live together with him.', 'who died for us that whether we wake or sleep we should live together with him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 11, 'Wherefore comfort yourselves together, and edify one another, even as also ye do. {comfort: or, exhort}', 'wherefore comfort yourselves together and edify one another even as also ye do comfort or exhort');
