INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 13, 'And to esteem them very highly in love for their work''s sake. {And} be at peace among yourselves.', 'and to esteem them very highly in love for their work s sake and be at peace among yourselves');
