INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 15, 'See that none render evil for evil unto any {man}; but ever follow that which is good, both among yourselves, and to all {men}.', 'see that none render evil for evil unto any man but ever follow that which is good both among yourselves and to all men');
