INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 52, 'Unknown', 5, 28, 'The grace of our Lord Jesus Christ {be} with you. Amen. «{The first epistle} to the Thessalonians was written from Athens.»', 'the grace of our lord jesus christ be with you amen the first epistle to the thessalonians was written from athens');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 1, 'Paul, and Silvanus, and Timotheus, unto the church of the Thessalonians in God our Father and the Lord Jesus Christ:', 'paul and silvanus and timotheus unto the church of the thessalonians in god our father and the lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 2, 'Grace unto you, and peace, from God our Father and the Lord Jesus Christ.', 'grace unto you and peace from god our father and the lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 3, 'We are bound to thank God always for you, brethren, as it is meet, because that your faith groweth exceedingly, and the charity of every one of you all toward each other aboundeth;', 'we are bound to thank god always for you brethren as it is meet because that your faith groweth exceedingly and the charity of every one of you all toward each other aboundeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 4, 'So that we ourselves glory in you in the churches of God for your patience and faith in all your persecutions and tribulations that ye endure:', 'so that we ourselves glory in you in the churches of god for your patience and faith in all your persecutions and tribulations that ye endure');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 5, '{Which is} a manifest token of the righteous judgment of God, that ye may be counted worthy of the kingdom of God, for which ye also suffer:', 'which is a manifest token of the righteous judgment of god that ye may be counted worthy of the kingdom of god for which ye also suffer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 6, 'Seeing {it is} a righteous thing with God to recompense tribulation to them that trouble you;', 'seeing it is a righteous thing with god to recompense tribulation to them that trouble you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 7, 'And to you who are troubled rest with us, when the Lord Jesus shall be revealed from heaven with his mighty angels, {his...: Gr. the angels of his power}', 'and to you who are troubled rest with us when the lord jesus shall be revealed from heaven with his mighty angels his gr the angels of his power');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 8, 'In flaming fire taking vengeance on them that know not God, and that obey not the gospel of our Lord Jesus Christ: {taking: or, yielding}', 'in flaming fire taking vengeance on them that know not god and that obey not the gospel of our lord jesus christ taking or yielding');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 9, 'Who shall be punished with everlasting destruction from the presence of the Lord, and from the glory of his power;', 'who shall be punished with everlasting destruction from the presence of the lord and from the glory of his power');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 10, 'When he shall come to be glorified in his saints, and to be admired in all them that believe (because our testimony among you was believed) in that day.', 'when he shall come to be glorified in his saints and to be admired in all them that believe because our testimony among you was believed in that day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 11, 'Wherefore also we pray always for you, that our God would count you worthy of {this} calling, and fulfil all the good pleasure of {his} goodness, and the work of faith with power: {count: or, vouchsafe}', 'wherefore also we pray always for you that our god would count you worthy of this calling and fulfil all the good pleasure of his goodness and the work of faith with power count or vouchsafe');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 1, 12, 'That the name of our Lord Jesus Christ may be glorified in you, and ye in him, according to the grace of our God and the Lord Jesus Christ.', 'that the name of our lord jesus christ may be glorified in you and ye in him according to the grace of our god and the lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 1, 'Now we beseech you, brethren, by the coming of our Lord Jesus Christ, and {by} our gathering together unto him, {unto him: or, around him}', 'now we beseech you brethren by the coming of our lord jesus christ and by our gathering together unto him unto him or around him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 2, 'That ye be not soon shaken in mind, or be troubled, neither by spirit, nor by word, nor by letter as from us, as that the day of Christ is at hand.', 'that ye be not soon shaken in mind or be troubled neither by spirit nor by word nor by letter as from us as that the day of christ is at hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 3, 'Let no man deceive you by any means: for {that day shall not come}, except there come a falling away first, and that man of sin be revealed, the son of perdition;', 'let no man deceive you by any means for that day shall not come except there come a falling away first and that man of sin be revealed the son of perdition');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 4, 'Who opposeth and exalteth himself above all that is called God, or that is worshipped; so that he as God sitteth in the temple of God, shewing himself that he is God.', 'who opposeth and exalteth himself above all that is called god or that is worshipped so that he as god sitteth in the temple of god shewing himself that he is god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 5, 'Remember ye not, that, when I was yet with you, I told you these things?', 'remember ye not that when i was yet with you i told you these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 6, 'And now ye know what withholdeth that he might be revealed in his time. {withholdeth: or, holdeth}', 'and now ye know what withholdeth that he might be revealed in his time withholdeth or holdeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 7, 'For the mystery of iniquity doth already work: only he who now letteth {will let}, until he be taken out of the way.', 'for the mystery of iniquity doth already work only he who now letteth will let until he be taken out of the way');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 8, 'And then shall that Wicked be revealed, whom the Lord shall consume with the spirit of his mouth, and shall destroy with the brightness of his coming:', 'and then shall that wicked be revealed whom the lord shall consume with the spirit of his mouth and shall destroy with the brightness of his coming');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 9, '{Even him}, whose coming is after the working of Satan with all power and signs and lying wonders,', 'even him whose coming is after the working of satan with all power and signs and lying wonders');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 10, 'And with all deceivableness of unrighteousness in them that perish; because they received not the love of the truth, that they might be saved.', 'and with all deceivableness of unrighteousness in them that perish because they received not the love of the truth that they might be saved');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 11, 'And for this cause God shall send them strong delusion, that they should believe a lie:', 'and for this cause god shall send them strong delusion that they should believe a lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 12, 'That they all might be damned who believed not the truth, but had pleasure in unrighteousness.', 'that they all might be damned who believed not the truth but had pleasure in unrighteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 13, 'But we are bound to give thanks alway to God for you, brethren beloved of the Lord, because God hath from the beginning chosen you to salvation through sanctification of the Spirit and belief of the truth:', 'but we are bound to give thanks alway to god for you brethren beloved of the lord because god hath from the beginning chosen you to salvation through sanctification of the spirit and belief of the truth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 14, 'Whereunto he called you by our gospel, to the obtaining of the glory of our Lord Jesus Christ.', 'whereunto he called you by our gospel to the obtaining of the glory of our lord jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 15, 'Therefore, brethren, stand fast, and hold the traditions which ye have been taught, whether by word, or our epistle.', 'therefore brethren stand fast and hold the traditions which ye have been taught whether by word or our epistle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 16, 'Now our Lord Jesus Christ himself, and God, even our Father, which hath loved us, and hath given {us} everlasting consolation and good hope through grace,', 'now our lord jesus christ himself and god even our father which hath loved us and hath given us everlasting consolation and good hope through grace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 2, 17, 'Comfort your hearts, and stablish you in every good word and work.', 'comfort your hearts and stablish you in every good word and work');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 1, 'Finally, brethren, pray for us, that the word of the Lord may have {free} course, and be glorified, even as {it is} with you: {have...: Gr. run}', 'finally brethren pray for us that the word of the lord may have free course and be glorified even as it is with you have gr run');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 2, 'And that we may be delivered from unreasonable and wicked men: for all {men} have not faith. {unreasonable: Gr. absurd}', 'and that we may be delivered from unreasonable and wicked men for all men have not faith unreasonable gr absurd');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 3, 'But the Lord is faithful, who shall stablish you, and keep {you} from evil.', 'but the lord is faithful who shall stablish you and keep you from evil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 4, 'And we have confidence in the Lord touching you, that ye both do and will do the things which we command you.', 'and we have confidence in the lord touching you that ye both do and will do the things which we command you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 5, 'And the Lord direct your hearts into the love of God, and into the patient waiting for Christ. {patient...: or, patience of Christ}', 'and the lord direct your hearts into the love of god and into the patient waiting for christ patient or patience of christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 6, 'Now we command you, brethren, in the name of our Lord Jesus Christ, that ye withdraw yourselves from every brother that walketh disorderly, and not after the tradition which he received of us.', 'now we command you brethren in the name of our lord jesus christ that ye withdraw yourselves from every brother that walketh disorderly and not after the tradition which he received of us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 7, 'For yourselves know how ye ought to follow us: for we behaved not ourselves disorderly among you;', 'for yourselves know how ye ought to follow us for we behaved not ourselves disorderly among you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 53, 'Unknown', 3, 8, 'Neither did we eat any man''s bread for nought; but wrought with labour and travail night and day, that we might not be chargeable to any of you:', 'neither did we eat any man s bread for nought but wrought with labour and travail night and day that we might not be chargeable to any of you');
