INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 4, 'And no man taketh this honour unto himself, but he that is called of God, as {was} Aaron.', 'and no man taketh this honour unto himself but he that is called of god as was aaron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 5, 'So also Christ glorified not himself to be made an high priest; but he that said unto him, Thou art my Son, to day have I begotten thee.', 'so also christ glorified not himself to be made an high priest but he that said unto him thou art my son to day have i begotten thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 6, 'As he saith also in another {place}, Thou {art} a priest for ever after the order of Melchisedec.', 'as he saith also in another place thou art a priest for ever after the order of melchisedec');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 7, 'Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears unto him that was able to save him from death, and was heard in that he feared; {in that...: or, for his piety}', 'who in the days of his flesh when he had offered up prayers and supplications with strong crying and tears unto him that was able to save him from death and was heard in that he feared in that or for his piety');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 8, 'Though he were a Son, yet learned he obedience by the things which he suffered;', 'though he were a son yet learned he obedience by the things which he suffered');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 9, 'And being made perfect, he became the author of eternal salvation unto all them that obey him;', 'and being made perfect he became the author of eternal salvation unto all them that obey him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 10, 'Called of God an high priest after the order of Melchisedec.', 'called of god an high priest after the order of melchisedec');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 11, 'Of whom we have many things to say, and hard to be uttered, seeing ye are dull of hearing.', 'of whom we have many things to say and hard to be uttered seeing ye are dull of hearing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 12, 'For when for the time ye ought to be teachers, ye have need that one teach you again which {be} the first principles of the oracles of God; and are become such as have need of milk, and not of strong meat.', 'for when for the time ye ought to be teachers ye have need that one teach you again which be the first principles of the oracles of god and are become such as have need of milk and not of strong meat');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 13, 'For every one that useth milk {is} unskilful in the word of righteousness: for he is a babe. {is unskillful: Gr. hath no experience}', 'for every one that useth milk is unskilful in the word of righteousness for he is a babe is unskillful gr hath no experience');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 5, 14, 'But strong meat belongeth to them that are of full age, {even} those who by reason of use have their senses exercised to discern both good and evil. {of full age: or, perfect} {use: or, an habit, or, perfection}', 'but strong meat belongeth to them that are of full age even those who by reason of use have their senses exercised to discern both good and evil of full age or perfect use or an habit or perfection');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 1, 'Therefore leaving the principles of the doctrine of Christ, let us go on unto perfection; not laying again the foundation of repentance from dead works, and of faith toward God, {principles...: or, word of the beginning of}', 'therefore leaving the principles of the doctrine of christ let us go on unto perfection not laying again the foundation of repentance from dead works and of faith toward god principles or word of the beginning of');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 2, 'Of the doctrine of baptisms, and of laying on of hands, and of resurrection of the dead, and of eternal judgment.', 'of the doctrine of baptisms and of laying on of hands and of resurrection of the dead and of eternal judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 3, 'And this will we do, if God permit.', 'and this will we do if god permit');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 4, 'For {it is} impossible for those who were once enlightened, and have tasted of the heavenly gift, and were made partakers of the Holy Ghost,', 'for it is impossible for those who were once enlightened and have tasted of the heavenly gift and were made partakers of the holy ghost');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 5, 'And have tasted the good word of God, and the powers of the world to come,', 'and have tasted the good word of god and the powers of the world to come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 6, 'If they shall fall away, to renew them again unto repentance; seeing they crucify to themselves the Son of God afresh, and put {him} to an open shame.', 'if they shall fall away to renew them again unto repentance seeing they crucify to themselves the son of god afresh and put him to an open shame');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 7, 'For the earth which drinketh in the rain that cometh oft upon it, and bringeth forth herbs meet for them by whom it is dressed, receiveth blessing from God: {by: or, for}', 'for the earth which drinketh in the rain that cometh oft upon it and bringeth forth herbs meet for them by whom it is dressed receiveth blessing from god by or for');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 8, 'But that which beareth thorns and briers {is} rejected, and {is} nigh unto cursing; whose end {is} to be burned.', 'but that which beareth thorns and briers is rejected and is nigh unto cursing whose end is to be burned');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 9, 'But, beloved, we are persuaded better things of you, and things that accompany salvation, though we thus speak.', 'but beloved we are persuaded better things of you and things that accompany salvation though we thus speak');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 10, 'For God {is} not unrighteous to forget your work and labour of love, which ye have shewed toward his name, in that ye have ministered to the saints, and do minister.', 'for god is not unrighteous to forget your work and labour of love which ye have shewed toward his name in that ye have ministered to the saints and do minister');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 11, 'And we desire that every one of you do shew the same diligence to the full assurance of hope unto the end:', 'and we desire that every one of you do shew the same diligence to the full assurance of hope unto the end');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 12, 'That ye be not slothful, but followers of them who through faith and patience inherit the promises.', 'that ye be not slothful but followers of them who through faith and patience inherit the promises');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 13, 'For when God made promise to Abraham, because he could swear by no greater, he sware by himself,', 'for when god made promise to abraham because he could swear by no greater he sware by himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 14, 'Saying, Surely blessing I will bless thee, and multiplying I will multiply thee.', 'saying surely blessing i will bless thee and multiplying i will multiply thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 15, 'And so, after he had patiently endured, he obtained the promise.', 'and so after he had patiently endured he obtained the promise');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 16, 'For men verily swear by the greater: and an oath for confirmation {is} to them an end of all strife.', 'for men verily swear by the greater and an oath for confirmation is to them an end of all strife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 17, 'Wherein God, willing more abundantly to shew unto the heirs of promise the immutability of his counsel, confirmed {it} by an oath: {confirmed...: Gr. interposed himself by}', 'wherein god willing more abundantly to shew unto the heirs of promise the immutability of his counsel confirmed it by an oath confirmed gr interposed himself by');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 18, 'That by two immutable things, in which {it was} impossible for God to lie, we might have a strong consolation, who have fled for refuge to lay hold upon the hope set before us:', 'that by two immutable things in which it was impossible for god to lie we might have a strong consolation who have fled for refuge to lay hold upon the hope set before us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 19, 'Which {hope} we have as an anchor of the soul, both sure and stedfast, and which entereth into that within the veil;', 'which hope we have as an anchor of the soul both sure and stedfast and which entereth into that within the veil');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 6, 20, 'Whither the forerunner is for us entered, {even} Jesus, made an high priest for ever after the order of Melchisedec.', 'whither the forerunner is for us entered even jesus made an high priest for ever after the order of melchisedec');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 1, 'For this Melchisedec, king of Salem, priest of the most high God, who met Abraham returning from the slaughter of the kings, and blessed him;', 'for this melchisedec king of salem priest of the most high god who met abraham returning from the slaughter of the kings and blessed him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 2, 'To whom also Abraham gave a tenth part of all; first being by interpretation King of righteousness, and after that also King of Salem, which is, King of peace;', 'to whom also abraham gave a tenth part of all first being by interpretation king of righteousness and after that also king of salem which is king of peace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 3, 'Without father, without mother, without descent, having neither beginning of days, nor end of life; but made like unto the Son of God; abideth a priest continually. {without descent: Gr. without pedigree}', 'without father without mother without descent having neither beginning of days nor end of life but made like unto the son of god abideth a priest continually without descent gr without pedigree');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 4, 'Now consider how great this man {was}, unto whom even the patriarch Abraham gave the tenth of the spoils.', 'now consider how great this man was unto whom even the patriarch abraham gave the tenth of the spoils');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 5, 'And verily they that are of the sons of Levi, who receive the office of the priesthood, have a commandment to take tithes of the people according to the law, that is, of their brethren, though they come out of the loins of Abraham:', 'and verily they that are of the sons of levi who receive the office of the priesthood have a commandment to take tithes of the people according to the law that is of their brethren though they come out of the loins of abraham');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 6, 'But he whose descent is not counted from them received tithes of Abraham, and blessed him that had the promises. {descent: or, pedigree}', 'but he whose descent is not counted from them received tithes of abraham and blessed him that had the promises descent or pedigree');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 7, 'And without all contradiction the less is blessed of the better.', 'and without all contradiction the less is blessed of the better');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 8, 'And here men that die receive tithes; but there he {receiveth them}, of whom it is witnessed that he liveth.', 'and here men that die receive tithes but there he receiveth them of whom it is witnessed that he liveth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 9, 'And as I may so say, Levi also, who receiveth tithes, payed tithes in Abraham.', 'and as i may so say levi also who receiveth tithes payed tithes in abraham');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 10, 'For he was yet in the loins of his father, when Melchisedec met him.', 'for he was yet in the loins of his father when melchisedec met him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 11, 'If therefore perfection were by the Levitical priesthood, (for under it the people received the law,) what further need {was there} that another priest should rise after the order of Melchisedec, and not be called after the order of Aaron?', 'if therefore perfection were by the levitical priesthood for under it the people received the law what further need was there that another priest should rise after the order of melchisedec and not be called after the order of aaron');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 12, 'For the priesthood being changed, there is made of necessity a change also of the law.', 'for the priesthood being changed there is made of necessity a change also of the law');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 13, 'For he of whom these things are spoken pertaineth to another tribe, of which no man gave attendance at the altar.', 'for he of whom these things are spoken pertaineth to another tribe of which no man gave attendance at the altar');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 14, 'For {it is} evident that our Lord sprang out of Juda; of which tribe Moses spake nothing concerning priesthood.', 'for it is evident that our lord sprang out of juda of which tribe moses spake nothing concerning priesthood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 15, 'And it is yet far more evident: for that after the similitude of Melchisedec there ariseth another priest,', 'and it is yet far more evident for that after the similitude of melchisedec there ariseth another priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 16, 'Who is made, not after the law of a carnal commandment, but after the power of an endless life.', 'who is made not after the law of a carnal commandment but after the power of an endless life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 17, 'For he testifieth, Thou {art} a priest for ever after the order of Melchisedec.', 'for he testifieth thou art a priest for ever after the order of melchisedec');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 18, 'For there is verily a disannulling of the commandment going before for the weakness and unprofitableness thereof.', 'for there is verily a disannulling of the commandment going before for the weakness and unprofitableness thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 19, 'For the law made nothing perfect, but the bringing in of a better hope {did}; by the which we draw nigh unto God. {the bringing...: or, it was the bringing in}', 'for the law made nothing perfect but the bringing in of a better hope did by the which we draw nigh unto god the bringing or it was the bringing in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 20, 'And inasmuch as not without an oath {he was made priest}:', 'and inasmuch as not without an oath he was made priest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 21, '(For those priests were made without an oath; but this with an oath by him that said unto him, The Lord sware and will not repent, Thou {art} a priest for ever after the order of Melchisedec:) {without...: or, without swearing of an oath}', 'for those priests were made without an oath but this with an oath by him that said unto him the lord sware and will not repent thou art a priest for ever after the order of melchisedec without or without swearing of an oath');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 22, 'By so much was Jesus made a surety of a better testament.', 'by so much was jesus made a surety of a better testament');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 23, 'And they truly were many priests, because they were not suffered to continue by reason of death:', 'and they truly were many priests because they were not suffered to continue by reason of death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 24, 'But this {man}, because he continueth ever, hath an unchangeable priesthood. {an...: or, which passeth not from one to another}', 'but this man because he continueth ever hath an unchangeable priesthood an or which passeth not from one to another');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 25, 'Wherefore he is able also to save them to the uttermost that come unto God by him, seeing he ever liveth to make intercession for them. {to the...: or, evermore}', 'wherefore he is able also to save them to the uttermost that come unto god by him seeing he ever liveth to make intercession for them to the or evermore');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 26, 'For such an high priest became us, {who is} holy, harmless, undefiled, separate from sinners, and made higher than the heavens;', 'for such an high priest became us who is holy harmless undefiled separate from sinners and made higher than the heavens');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 27, 'Who needeth not daily, as those high priests, to offer up sacrifice, first for his own sins, and then for the people''s: for this he did once, when he offered up himself.', 'who needeth not daily as those high priests to offer up sacrifice first for his own sins and then for the people s for this he did once when he offered up himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 7, 28, 'For the law maketh men high priests which have infirmity; but the word of the oath, which was since the law, {maketh} the Son, who is consecrated for evermore. {consecrated: Gr. perfected}', 'for the law maketh men high priests which have infirmity but the word of the oath which was since the law maketh the son who is consecrated for evermore consecrated gr perfected');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 1, 'Now of the things which we have spoken {this is} the sum: We have such an high priest, who is set on the right hand of the throne of the Majesty in the heavens;', 'now of the things which we have spoken this is the sum we have such an high priest who is set on the right hand of the throne of the majesty in the heavens');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 2, 'A minister of the sanctuary, and of the true tabernacle, which the Lord pitched, and not man. {of the sanctuary: or, of holy things}', 'a minister of the sanctuary and of the true tabernacle which the lord pitched and not man of the sanctuary or of holy things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 3, 'For every high priest is ordained to offer gifts and sacrifices: wherefore {it is} of necessity that this man have somewhat also to offer.', 'for every high priest is ordained to offer gifts and sacrifices wherefore it is of necessity that this man have somewhat also to offer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 4, 'For if he were on earth, he should not be a priest, seeing that there are priests that offer gifts according to the law: {there...: or, they are priests}', 'for if he were on earth he should not be a priest seeing that there are priests that offer gifts according to the law there or they are priests');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 5, 'Who serve unto the example and shadow of heavenly things, as Moses was admonished of God when he was about to make the tabernacle: for, See, saith he, {that} thou make all things according to the pattern shewed to thee in the mount.', 'who serve unto the example and shadow of heavenly things as moses was admonished of god when he was about to make the tabernacle for see saith he that thou make all things according to the pattern shewed to thee in the mount');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 6, 'But now hath he obtained a more excellent ministry, by how much also he is the mediator of a better covenant, which was established upon better promises. {covenant: or, testament}', 'but now hath he obtained a more excellent ministry by how much also he is the mediator of a better covenant which was established upon better promises covenant or testament');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 7, 'For if that first {covenant} had been faultless, then should no place have been sought for the second.', 'for if that first covenant had been faultless then should no place have been sought for the second');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 8, 'For finding fault with them, he saith, Behold, the days come, saith the Lord, when I will make a new covenant with the house of Israel and with the house of Judah:', 'for finding fault with them he saith behold the days come saith the lord when i will make a new covenant with the house of israel and with the house of judah');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 9, 'Not according to the covenant that I made with their fathers in the day when I took them by the hand to lead them out of the land of Egypt; because they continued not in my covenant, and I regarded them not, saith the Lord.', 'not according to the covenant that i made with their fathers in the day when i took them by the hand to lead them out of the land of egypt because they continued not in my covenant and i regarded them not saith the lord');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 10, 'For this {is} the covenant that I will make with the house of Israel after those days, saith the Lord; I will put my laws into their mind, and write them in their hearts: and I will be to them a God, and they shall be to me a people: {put: Gr. give} {in: or, upon}', 'for this is the covenant that i will make with the house of israel after those days saith the lord i will put my laws into their mind and write them in their hearts and i will be to them a god and they shall be to me a people put gr give in or upon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 11, 'And they shall not teach every man his neighbour, and every man his brother, saying, Know the Lord: for all shall know me, from the least to the greatest.', 'and they shall not teach every man his neighbour and every man his brother saying know the lord for all shall know me from the least to the greatest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 12, 'For I will be merciful to their unrighteousness, and their sins and their iniquities will I remember no more.', 'for i will be merciful to their unrighteousness and their sins and their iniquities will i remember no more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 8, 13, 'In that he saith, A new {covenant}, he hath made the first old. Now that which decayeth and waxeth old {is} ready to vanish away.', 'in that he saith a new covenant he hath made the first old now that which decayeth and waxeth old is ready to vanish away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 1, 'Then verily the first {covenant} had also ordinances of divine service, and a worldly sanctuary. {ordinances: or, ceremonies}', 'then verily the first covenant had also ordinances of divine service and a worldly sanctuary ordinances or ceremonies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 2, 'For there was a tabernacle made; the first, wherein {was} the candlestick, and the table, and the shewbread; which is called the sanctuary. {the sanctuary: or, holy}', 'for there was a tabernacle made the first wherein was the candlestick and the table and the shewbread which is called the sanctuary the sanctuary or holy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 3, 'And after the second veil, the tabernacle which is called the Holiest of all;', 'and after the second veil the tabernacle which is called the holiest of all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 4, 'Which had the golden censer, and the ark of the covenant overlaid round about with gold, wherein {was} the golden pot that had manna, and Aaron''s rod that budded, and the tables of the covenant;', 'which had the golden censer and the ark of the covenant overlaid round about with gold wherein was the golden pot that had manna and aaron s rod that budded and the tables of the covenant');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 5, 'And over it the cherubims of glory shadowing the mercyseat; of which we cannot now speak particularly.', 'and over it the cherubims of glory shadowing the mercyseat of which we cannot now speak particularly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 6, 'Now when these things were thus ordained, the priests went always into the first tabernacle, accomplishing the service {of God}.', 'now when these things were thus ordained the priests went always into the first tabernacle accomplishing the service of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 7, 'But into the second {went} the high priest alone once every year, not without blood, which he offered for himself, and {for} the errors of the people:', 'but into the second went the high priest alone once every year not without blood which he offered for himself and for the errors of the people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 8, 'The Holy Ghost this signifying, that the way into the holiest of all was not yet made manifest, while as the first tabernacle was yet standing:', 'the holy ghost this signifying that the way into the holiest of all was not yet made manifest while as the first tabernacle was yet standing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 9, 'Which {was} a figure for the time then present, in which were offered both gifts and sacrifices, that could not make him that did the service perfect, as pertaining to the conscience;', 'which was a figure for the time then present in which were offered both gifts and sacrifices that could not make him that did the service perfect as pertaining to the conscience');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 10, '{Which stood} only in meats and drinks, and divers washings, and carnal ordinances, imposed {on them} until the time of reformation. {ordinances: or, rites, or, ceremonies}', 'which stood only in meats and drinks and divers washings and carnal ordinances imposed on them until the time of reformation ordinances or rites or ceremonies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 11, 'But Christ being come an high priest of good things to come, by a greater and more perfect tabernacle, not made with hands, that is to say, not of this building;', 'but christ being come an high priest of good things to come by a greater and more perfect tabernacle not made with hands that is to say not of this building');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 12, 'Neither by the blood of goats and calves, but by his own blood he entered in once into the holy place, having obtained eternal redemption {for us}.', 'neither by the blood of goats and calves but by his own blood he entered in once into the holy place having obtained eternal redemption for us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 13, 'For if the blood of bulls and of goats, and the ashes of an heifer sprinkling the unclean, sanctifieth to the purifying of the flesh:', 'for if the blood of bulls and of goats and the ashes of an heifer sprinkling the unclean sanctifieth to the purifying of the flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 14, 'How much more shall the blood of Christ, who through the eternal Spirit offered himself without spot to God, purge your conscience from dead works to serve the living God? {spot: or, fault}', 'how much more shall the blood of christ who through the eternal spirit offered himself without spot to god purge your conscience from dead works to serve the living god spot or fault');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 15, 'And for this cause he is the mediator of the new testament, that by means of death, for the redemption of the transgressions {that were} under the first testament, they which are called might receive the promise of eternal inheritance.', 'and for this cause he is the mediator of the new testament that by means of death for the redemption of the transgressions that were under the first testament they which are called might receive the promise of eternal inheritance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 16, 'For where a testament {is}, there must also of necessity be the death of the testator. {be: or, be brought in}', 'for where a testament is there must also of necessity be the death of the testator be or be brought in');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 17, 'For a testament {is} of force after men are dead: otherwise it is of no strength at all while the testator liveth.', 'for a testament is of force after men are dead otherwise it is of no strength at all while the testator liveth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 18, 'Whereupon neither the first {testament} was dedicated without blood. {dedicated: or, purified}', 'whereupon neither the first testament was dedicated without blood dedicated or purified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 19, 'For when Moses had spoken every precept to all the people according to the law, he took the blood of calves and of goats, with water, and scarlet wool, and hyssop, and sprinkled both the book, and all the people, {scarlet: or, purple}', 'for when moses had spoken every precept to all the people according to the law he took the blood of calves and of goats with water and scarlet wool and hyssop and sprinkled both the book and all the people scarlet or purple');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 20, 'Saying, This {is} the blood of the testament which God hath enjoined unto you.', 'saying this is the blood of the testament which god hath enjoined unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 21, 'Moreover he sprinkled with blood both the tabernacle, and all the vessels of the ministry.', 'moreover he sprinkled with blood both the tabernacle and all the vessels of the ministry');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 22, 'And almost all things are by the law purged with blood; and without shedding of blood is no remission.', 'and almost all things are by the law purged with blood and without shedding of blood is no remission');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 23, '{It was} therefore necessary that the patterns of things in the heavens should be purified with these; but the heavenly things themselves with better sacrifices than these.', 'it was therefore necessary that the patterns of things in the heavens should be purified with these but the heavenly things themselves with better sacrifices than these');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 24, 'For Christ is not entered into the holy places made with hands, {which are} the figures of the true; but into heaven itself, now to appear in the presence of God for us:', 'for christ is not entered into the holy places made with hands which are the figures of the true but into heaven itself now to appear in the presence of god for us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 25, 'Nor yet that he should offer himself often, as the high priest entereth into the holy place every year with blood of others;', 'nor yet that he should offer himself often as the high priest entereth into the holy place every year with blood of others');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 26, 'For then must he often have suffered since the foundation of the world: but now once in the end of the world hath he appeared to put away sin by the sacrifice of himself.', 'for then must he often have suffered since the foundation of the world but now once in the end of the world hath he appeared to put away sin by the sacrifice of himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 27, 'And as it is appointed unto men once to die, but after this the judgment:', 'and as it is appointed unto men once to die but after this the judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 9, 28, 'So Christ was once offered to bear the sins of many; and unto them that look for him shall he appear the second time without sin unto salvation.', 'so christ was once offered to bear the sins of many and unto them that look for him shall he appear the second time without sin unto salvation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 1, 'For the law having a shadow of good things to come, {and} not the very image of the things, can never with those sacrifices which they offered year by year continually make the comers thereunto perfect.', 'for the law having a shadow of good things to come and not the very image of the things can never with those sacrifices which they offered year by year continually make the comers thereunto perfect');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 2, 'For then would they not have ceased to be offered? because that the worshippers once purged should have had no more conscience of sins. {would...: or, they would have ceased to be offered, because, etc.}', 'for then would they not have ceased to be offered because that the worshippers once purged should have had no more conscience of sins would or they would have ceased to be offered because etc');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 3, 'But in those {sacrifices there is} a remembrance again {made} of sins every year.', 'but in those sacrifices there is a remembrance again made of sins every year');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 4, 'For {it is} not possible that the blood of bulls and of goats should take away sins.', 'for it is not possible that the blood of bulls and of goats should take away sins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 5, 'Wherefore when he cometh into the world, he saith, Sacrifice and offering thou wouldest not, but a body hast thou prepared me: {hast...: or, thou hast fitted me}', 'wherefore when he cometh into the world he saith sacrifice and offering thou wouldest not but a body hast thou prepared me hast or thou hast fitted me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 6, 'In burnt offerings and {sacrifices} for sin thou hast had no pleasure.', 'in burnt offerings and sacrifices for sin thou hast had no pleasure');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 7, 'Then said I, Lo, I come (in the volume of the book it is written of me,) to do thy will, O God.', 'then said i lo i come in the volume of the book it is written of me to do thy will o god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 8, 'Above when he said, Sacrifice and offering and burnt offerings and {offering} for sin thou wouldest not, neither hadst pleasure {therein}; which are offered by the law;', 'above when he said sacrifice and offering and burnt offerings and offering for sin thou wouldest not neither hadst pleasure therein which are offered by the law');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 9, 'Then said he, Lo, I come to do thy will, O God. He taketh away the first, that he may establish the second.', 'then said he lo i come to do thy will o god he taketh away the first that he may establish the second');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 10, 'By the which will we are sanctified through the offering of the body of Jesus Christ once {for all}.', 'by the which will we are sanctified through the offering of the body of jesus christ once for all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 11, 'And every priest standeth daily ministering and offering oftentimes the same sacrifices, which can never take away sins:', 'and every priest standeth daily ministering and offering oftentimes the same sacrifices which can never take away sins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 12, 'But this man, after he had offered one sacrifice for sins for ever, sat down on the right hand of God;', 'but this man after he had offered one sacrifice for sins for ever sat down on the right hand of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 13, 'From henceforth expecting till his enemies be made his footstool.', 'from henceforth expecting till his enemies be made his footstool');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 14, 'For by one offering he hath perfected for ever them that are sanctified.', 'for by one offering he hath perfected for ever them that are sanctified');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 15, '{Whereof} the Holy Ghost also is a witness to us: for after that he had said before,', 'whereof the holy ghost also is a witness to us for after that he had said before');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 16, 'This {is} the covenant that I will make with them after those days, saith the Lord, I will put my laws into their hearts, and in their minds will I write them;', 'this is the covenant that i will make with them after those days saith the lord i will put my laws into their hearts and in their minds will i write them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 17, 'And their sins and iniquities will I remember no more. {And their: some copies have, Then he said, And their}', 'and their sins and iniquities will i remember no more and their some copies have then he said and their');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 18, 'Now where remission of these {is, there is} no more offering for sin.', 'now where remission of these is there is no more offering for sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 19, 'Having therefore, brethren, boldness to enter into the holiest by the blood of Jesus, {boldness: or, liberty}', 'having therefore brethren boldness to enter into the holiest by the blood of jesus boldness or liberty');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 20, 'By a new and living way, which he hath consecrated for us, through the veil, that is to say, his flesh; {consecrated: or, new made}', 'by a new and living way which he hath consecrated for us through the veil that is to say his flesh consecrated or new made');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 21, 'And {having} an high priest over the house of God;', 'and having an high priest over the house of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 22, 'Let us draw near with a true heart in full assurance of faith, having our hearts sprinkled from an evil conscience, and our bodies washed with pure water.', 'let us draw near with a true heart in full assurance of faith having our hearts sprinkled from an evil conscience and our bodies washed with pure water');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 23, 'Let us hold fast the profession of {our} faith without wavering; (for he {is} faithful that promised;)', 'let us hold fast the profession of our faith without wavering for he is faithful that promised');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 24, 'And let us consider one another to provoke unto love and to good works:', 'and let us consider one another to provoke unto love and to good works');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 25, 'Not forsaking the assembling of ourselves together, as the manner of some {is}; but exhorting {one another}: and so much the more, as ye see the day approaching.', 'not forsaking the assembling of ourselves together as the manner of some is but exhorting one another and so much the more as ye see the day approaching');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 26, 'For if we sin wilfully after that we have received the knowledge of the truth, there remaineth no more sacrifice for sins,', 'for if we sin wilfully after that we have received the knowledge of the truth there remaineth no more sacrifice for sins');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 27, 'But a certain fearful looking for of judgment and fiery indignation, which shall devour the adversaries.', 'but a certain fearful looking for of judgment and fiery indignation which shall devour the adversaries');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 28, 'He that despised Moses'' law died without mercy under two or three witnesses:', 'he that despised moses law died without mercy under two or three witnesses');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 29, 'Of how much sorer punishment, suppose ye, shall he be thought worthy, who hath trodden under foot the Son of God, and hath counted the blood of the covenant, wherewith he was sanctified, an unholy thing, and hath done despite unto the Spirit of grace?', 'of how much sorer punishment suppose ye shall he be thought worthy who hath trodden under foot the son of god and hath counted the blood of the covenant wherewith he was sanctified an unholy thing and hath done despite unto the spirit of grace');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 30, 'For we know him that hath said, Vengeance {belongeth} unto me, I will recompense, saith the Lord. And again, The Lord shall judge his people.', 'for we know him that hath said vengeance belongeth unto me i will recompense saith the lord and again the lord shall judge his people');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 31, '{It is} a fearful thing to fall into the hands of the living God.', 'it is a fearful thing to fall into the hands of the living god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 32, 'But call to remembrance the former days, in which, after ye were illuminated, ye endured a great fight of afflictions;', 'but call to remembrance the former days in which after ye were illuminated ye endured a great fight of afflictions');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 10, 33, 'Partly, whilst ye were made a gazingstock both by reproaches and afflictions; and partly, whilst ye became companions of them that were so used.', 'partly whilst ye were made a gazingstock both by reproaches and afflictions and partly whilst ye became companions of them that were so used');
