INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 12, 3, 'For consider him that endured such contradiction of sinners against himself, lest ye be wearied and faint in your minds.', 'for consider him that endured such contradiction of sinners against himself lest ye be wearied and faint in your minds');
