INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 58, 'Unknown', 12, 11, 'Now no chastening for the present seemeth to be joyous, but grievous: nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby.', 'now no chastening for the present seemeth to be joyous but grievous nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby');
