INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 59, 'Unknown', 5, 4, 'Behold, the hire of the labourers who have reaped down your fields, which is of you kept back by fraud, crieth: and the cries of them which have reaped are entered into the ears of the Lord of sabaoth. {sabaoth: Heb. hosts}', 'behold the hire of the labourers who have reaped down your fields which is of you kept back by fraud crieth and the cries of them which have reaped are entered into the ears of the lord of sabaoth sabaoth heb hosts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 59, 'Unknown', 5, 5, 'Ye have lived in pleasure on the earth, and been wanton; ye have nourished your hearts, as in a day of slaughter.', 'ye have lived in pleasure on the earth and been wanton ye have nourished your hearts as in a day of slaughter');
