INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 59, 'Unknown', 5, 8, 'Be ye also patient; stablish your hearts: for the coming of the Lord draweth nigh.', 'be ye also patient stablish your hearts for the coming of the lord draweth nigh');
