INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 59, 'Unknown', 5, 12, 'But above all things, my brethren, swear not, neither by heaven, neither by the earth, neither by any other oath: but let your yea be yea; and {your} nay, nay; lest ye fall into condemnation.', 'but above all things my brethren swear not neither by heaven neither by the earth neither by any other oath but let your yea be yea and your nay nay lest ye fall into condemnation');
