INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 2, 'And many shall follow their pernicious ways; by reason of whom the way of truth shall be evil spoken of. {pernicious ways: or, lascivious ways, as some copies read}', 'and many shall follow their pernicious ways by reason of whom the way of truth shall be evil spoken of pernicious ways or lascivious ways as some copies read');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 3, 'And through covetousness shall they with feigned words make merchandise of you: whose judgment now of a long time lingereth not, and their damnation slumbereth not.', 'and through covetousness shall they with feigned words make merchandise of you whose judgment now of a long time lingereth not and their damnation slumbereth not');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 4, 'For if God spared not the angels that sinned, but cast {them} down to hell, and delivered {them} into chains of darkness, to be reserved unto judgment;', 'for if god spared not the angels that sinned but cast them down to hell and delivered them into chains of darkness to be reserved unto judgment');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 5, 'And spared not the old world, but saved Noah the eighth {person}, a preacher of righteousness, bringing in the flood upon the world of the ungodly;', 'and spared not the old world but saved noah the eighth person a preacher of righteousness bringing in the flood upon the world of the ungodly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 6, 'And turning the cities of Sodom and Gomorrha into ashes condemned {them} with an overthrow, making {them} an ensample unto those that after should live ungodly;', 'and turning the cities of sodom and gomorrha into ashes condemned them with an overthrow making them an ensample unto those that after should live ungodly');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 7, 'And delivered just Lot, vexed with the filthy conversation of the wicked:', 'and delivered just lot vexed with the filthy conversation of the wicked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 8, '(For that righteous man dwelling among them, in seeing and hearing, vexed {his} righteous soul from day to day with {their} unlawful deeds;)', 'for that righteous man dwelling among them in seeing and hearing vexed his righteous soul from day to day with their unlawful deeds');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 9, 'The Lord knoweth how to deliver the godly out of temptations, and to reserve the unjust unto the day of judgment to be punished:', 'the lord knoweth how to deliver the godly out of temptations and to reserve the unjust unto the day of judgment to be punished');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 10, 'But chiefly them that walk after the flesh in the lust of uncleanness, and despise government. Presumptuous {are they}, selfwilled, they are not afraid to speak evil of dignities. {government: or, dominion}', 'but chiefly them that walk after the flesh in the lust of uncleanness and despise government presumptuous are they selfwilled they are not afraid to speak evil of dignities government or dominion');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 11, 'Whereas angels, which are greater in power and might, bring not railing accusation against them before the Lord. {them: some read, themselves}', 'whereas angels which are greater in power and might bring not railing accusation against them before the lord them some read themselves');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 12, 'But these, as natural brute beasts, made to be taken and destroyed, speak evil of the things that they understand not; and shall utterly perish in their own corruption;', 'but these as natural brute beasts made to be taken and destroyed speak evil of the things that they understand not and shall utterly perish in their own corruption');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 13, 'And shall receive the reward of unrighteousness, {as} they that count it pleasure to riot in the day time. Spots {they are} and blemishes, sporting themselves with their own deceivings while they feast with you;', 'and shall receive the reward of unrighteousness as they that count it pleasure to riot in the day time spots they are and blemishes sporting themselves with their own deceivings while they feast with you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 14, 'Having eyes full of adultery, and that cannot cease from sin; beguiling unstable souls: an heart they have exercised with covetous practices; cursed children: {adultery: Gr. an adulteress}', 'having eyes full of adultery and that cannot cease from sin beguiling unstable souls an heart they have exercised with covetous practices cursed children adultery gr an adulteress');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 15, 'Which have forsaken the right way, and are gone astray, following the way of Balaam {the son} of Bosor, who loved the wages of unrighteousness;', 'which have forsaken the right way and are gone astray following the way of balaam the son of bosor who loved the wages of unrighteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 16, 'But was rebuked for his iniquity: the dumb ass speaking with man''s voice forbad the madness of the prophet.', 'but was rebuked for his iniquity the dumb ass speaking with man s voice forbad the madness of the prophet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 17, 'These are wells without water, clouds that are carried with a tempest; to whom the mist of darkness is reserved for ever.', 'these are wells without water clouds that are carried with a tempest to whom the mist of darkness is reserved for ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 18, 'For when they speak great swelling {words} of vanity, they allure through the lusts of the flesh, {through much} wantonness, those that were clean escaped from them who live in error. {clean: or, for a little, or, a while, as some read}', 'for when they speak great swelling words of vanity they allure through the lusts of the flesh through much wantonness those that were clean escaped from them who live in error clean or for a little or a while as some read');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 19, 'While they promise them liberty, they themselves are the servants of corruption: for of whom a man is overcome, of the same is he brought in bondage.', 'while they promise them liberty they themselves are the servants of corruption for of whom a man is overcome of the same is he brought in bondage');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 20, 'For if after they have escaped the pollutions of the world through the knowledge of the Lord and Saviour Jesus Christ, they are again entangled therein, and overcome, the latter end is worse with them than the beginning.', 'for if after they have escaped the pollutions of the world through the knowledge of the lord and saviour jesus christ they are again entangled therein and overcome the latter end is worse with them than the beginning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 21, 'For it had been better for them not to have known the way of righteousness, than, after they have known {it}, to turn from the holy commandment delivered unto them.', 'for it had been better for them not to have known the way of righteousness than after they have known it to turn from the holy commandment delivered unto them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 2, 22, 'But it is happened unto them according to the true proverb, The dog {is} turned to his own vomit again; and the sow that was washed to her wallowing in the mire.', 'but it is happened unto them according to the true proverb the dog is turned to his own vomit again and the sow that was washed to her wallowing in the mire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 1, 'This second epistle, beloved, I now write unto you; in {both} which I stir up your pure minds by way of remembrance:', 'this second epistle beloved i now write unto you in both which i stir up your pure minds by way of remembrance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 2, 'That ye may be mindful of the words which were spoken before by the holy prophets, and of the commandment of us the apostles of the Lord and Saviour:', 'that ye may be mindful of the words which were spoken before by the holy prophets and of the commandment of us the apostles of the lord and saviour');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 3, 'Knowing this first, that there shall come in the last days scoffers, walking after their own lusts,', 'knowing this first that there shall come in the last days scoffers walking after their own lusts');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 4, 'And saying, Where is the promise of his coming? for since the fathers fell asleep, all things continue as {they were} from the beginning of the creation.', 'and saying where is the promise of his coming for since the fathers fell asleep all things continue as they were from the beginning of the creation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 5, 'For this they willingly are ignorant of, that by the word of God the heavens were of old, and the earth standing out of the water and in the water: {standing: Gr. consisting}', 'for this they willingly are ignorant of that by the word of god the heavens were of old and the earth standing out of the water and in the water standing gr consisting');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 6, 'Whereby the world that then was, being overflowed with water, perished:', 'whereby the world that then was being overflowed with water perished');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 7, 'But the heavens and the earth, which are now, by the same word are kept in store, reserved unto fire against the day of judgment and perdition of ungodly men.', 'but the heavens and the earth which are now by the same word are kept in store reserved unto fire against the day of judgment and perdition of ungodly men');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 8, 'But, beloved, be not ignorant of this one thing, that one day {is} with the Lord as a thousand years, and a thousand years as one day.', 'but beloved be not ignorant of this one thing that one day is with the lord as a thousand years and a thousand years as one day');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 9, 'The Lord is not slack concerning his promise, as some men count slackness; but is longsuffering to us-ward, not willing that any should perish, but that all should come to repentance.', 'the lord is not slack concerning his promise as some men count slackness but is longsuffering to us ward not willing that any should perish but that all should come to repentance');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 10, 'But the day of the Lord will come as a thief in the night; in the which the heavens shall pass away with a great noise, and the elements shall melt with fervent heat, the earth also and the works that are therein shall be burned up.', 'but the day of the lord will come as a thief in the night in the which the heavens shall pass away with a great noise and the elements shall melt with fervent heat the earth also and the works that are therein shall be burned up');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 11, '{Seeing} then {that} all these things shall be dissolved, what manner {of persons} ought ye to be in {all} holy conversation and godliness,', 'seeing then that all these things shall be dissolved what manner of persons ought ye to be in all holy conversation and godliness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 12, 'Looking for and hasting unto the coming of the day of God, wherein the heavens being on fire shall be dissolved, and the elements shall melt with fervent heat? {hasting...: or, hasting the coming}', 'looking for and hasting unto the coming of the day of god wherein the heavens being on fire shall be dissolved and the elements shall melt with fervent heat hasting or hasting the coming');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 13, 'Nevertheless we, according to his promise, look for new heavens and a new earth, wherein dwelleth righteousness.', 'nevertheless we according to his promise look for new heavens and a new earth wherein dwelleth righteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 14, 'Wherefore, beloved, seeing that ye look for such things, be diligent that ye may be found of him in peace, without spot, and blameless.', 'wherefore beloved seeing that ye look for such things be diligent that ye may be found of him in peace without spot and blameless');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 15, 'And account {that} the longsuffering of our Lord {is} salvation; even as our beloved brother Paul also according to the wisdom given unto him hath written unto you;', 'and account that the longsuffering of our lord is salvation even as our beloved brother paul also according to the wisdom given unto him hath written unto you');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 16, 'As also in all {his} epistles, speaking in them of these things; in which are some things hard to be understood, which they that are unlearned and unstable wrest, as {they do} also the other scriptures, unto their own destruction.', 'as also in all his epistles speaking in them of these things in which are some things hard to be understood which they that are unlearned and unstable wrest as they do also the other scriptures unto their own destruction');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 17, 'Ye therefore, beloved, seeing ye know {these things} before, beware lest ye also, being led away with the error of the wicked, fall from your own stedfastness.', 'ye therefore beloved seeing ye know these things before beware lest ye also being led away with the error of the wicked fall from your own stedfastness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 61, 'Unknown', 3, 18, 'But grow in grace, and {in} the knowledge of our Lord and Saviour Jesus Christ. To him {be} glory both now and for ever. Amen.', 'but grow in grace and in the knowledge of our lord and saviour jesus christ to him be glory both now and for ever amen');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 1, 'That which was from the beginning, which we have heard, which we have seen with our eyes, which we have looked upon, and our hands have handled, of the Word of life;', 'that which was from the beginning which we have heard which we have seen with our eyes which we have looked upon and our hands have handled of the word of life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 2, '(For the life was manifested, and we have seen {it}, and bear witness, and shew unto you that eternal life, which was with the Father, and was manifested unto us;)', 'for the life was manifested and we have seen it and bear witness and shew unto you that eternal life which was with the father and was manifested unto us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 3, 'That which we have seen and heard declare we unto you, that ye also may have fellowship with us: and truly our fellowship {is} with the Father, and with his Son Jesus Christ.', 'that which we have seen and heard declare we unto you that ye also may have fellowship with us and truly our fellowship is with the father and with his son jesus christ');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 4, 'And these things write we unto you, that your joy may be full.', 'and these things write we unto you that your joy may be full');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 5, 'This then is the message which we have heard of him, and declare unto you, that God is light, and in him is no darkness at all.', 'this then is the message which we have heard of him and declare unto you that god is light and in him is no darkness at all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 6, 'If we say that we have fellowship with him, and walk in darkness, we lie, and do not the truth:', 'if we say that we have fellowship with him and walk in darkness we lie and do not the truth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 7, 'But if we walk in the light, as he is in the light, we have fellowship one with another, and the blood of Jesus Christ his Son cleanseth us from all sin.', 'but if we walk in the light as he is in the light we have fellowship one with another and the blood of jesus christ his son cleanseth us from all sin');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 8, 'If we say that we have no sin, we deceive ourselves, and the truth is not in us.', 'if we say that we have no sin we deceive ourselves and the truth is not in us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 9, 'If we confess our sins, he is faithful and just to forgive us {our} sins, and to cleanse us from all unrighteousness.', 'if we confess our sins he is faithful and just to forgive us our sins and to cleanse us from all unrighteousness');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 1, 10, 'If we say that we have not sinned, we make him a liar, and his word is not in us.', 'if we say that we have not sinned we make him a liar and his word is not in us');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 1, 'My little children, these things write I unto you, that ye sin not. And if any man sin, we have an advocate with the Father, Jesus Christ the righteous:', 'my little children these things write i unto you that ye sin not and if any man sin we have an advocate with the father jesus christ the righteous');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 2, 'And he is the propitiation for our sins: and not for ours only, but also for {the sins of} the whole world.', 'and he is the propitiation for our sins and not for ours only but also for the sins of the whole world');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 3, 'And hereby we do know that we know him, if we keep his commandments.', 'and hereby we do know that we know him if we keep his commandments');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 4, 'He that saith, I know him, and keepeth not his commandments, is a liar, and the truth is not in him.', 'he that saith i know him and keepeth not his commandments is a liar and the truth is not in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 5, 'But whoso keepeth his word, in him verily is the love of God perfected: hereby know we that we are in him.', 'but whoso keepeth his word in him verily is the love of god perfected hereby know we that we are in him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 6, 'He that saith he abideth in him ought himself also so to walk, even as he walked.', 'he that saith he abideth in him ought himself also so to walk even as he walked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 7, 'Brethren, I write no new commandment unto you, but an old commandment which ye had from the beginning. The old commandment is the word which ye have heard from the beginning.', 'brethren i write no new commandment unto you but an old commandment which ye had from the beginning the old commandment is the word which ye have heard from the beginning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 8, 'Again, a new commandment I write unto you, which thing is true in him and in you: because the darkness is past, and the true light now shineth.', 'again a new commandment i write unto you which thing is true in him and in you because the darkness is past and the true light now shineth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 9, 'He that saith he is in the light, and hateth his brother, is in darkness even until now.', 'he that saith he is in the light and hateth his brother is in darkness even until now');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 10, 'He that loveth his brother abideth in the light, and there is none occasion of stumbling in him. {occasion...: Gr. scandal}', 'he that loveth his brother abideth in the light and there is none occasion of stumbling in him occasion gr scandal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 11, 'But he that hateth his brother is in darkness, and walketh in darkness, and knoweth not whither he goeth, because that darkness hath blinded his eyes.', 'but he that hateth his brother is in darkness and walketh in darkness and knoweth not whither he goeth because that darkness hath blinded his eyes');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 12, 'I write unto you, little children, because your sins are forgiven you for his name''s sake.', 'i write unto you little children because your sins are forgiven you for his name s sake');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 13, 'I write unto you, fathers, because ye have known him {that is} from the beginning. I write unto you, young men, because ye have overcome the wicked one. I write unto you, little children, because ye have known the Father.', 'i write unto you fathers because ye have known him that is from the beginning i write unto you young men because ye have overcome the wicked one i write unto you little children because ye have known the father');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 14, 'I have written unto you, fathers, because ye have known him {that is} from the beginning. I have written unto you, young men, because ye are strong, and the word of God abideth in you, and ye have overcome the wicked one.', 'i have written unto you fathers because ye have known him that is from the beginning i have written unto you young men because ye are strong and the word of god abideth in you and ye have overcome the wicked one');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 2, 15, 'Love not the world, neither the things {that are} in the world. If any man love the world, the love of the Father is not in him.', 'love not the world neither the things that are in the world if any man love the world the love of the father is not in him');
