INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 3, 1, 'Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.', 'behold what manner of love the father hath bestowed upon us that we should be called the sons of god therefore the world knoweth us not because it knew him not');
