INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 3, 4, 'Whosoever committeth sin transgresseth also the law: for sin is the transgression of the law.', 'whosoever committeth sin transgresseth also the law for sin is the transgression of the law');
