INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 3, 7, 'Little children, let no man deceive you: he that doeth righteousness is righteous, even as he is righteous.', 'little children let no man deceive you he that doeth righteousness is righteous even as he is righteous');
