INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 3, 10, 'In this the children of God are manifest, and the children of the devil: whosoever doeth not righteousness is not of God, neither he that loveth not his brother.', 'in this the children of god are manifest and the children of the devil whosoever doeth not righteousness is not of god neither he that loveth not his brother');
