INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 3, 20, 'For if our heart condemn us, God is greater than our heart, and knoweth all things.', 'for if our heart condemn us god is greater than our heart and knoweth all things');
