INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 4, 1, 'Beloved, believe not every spirit, but try the spirits whether they are of God: because many false prophets are gone out into the world.', 'beloved believe not every spirit but try the spirits whether they are of god because many false prophets are gone out into the world');
