INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 4, 4, 'Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.', 'ye are of god little children and have overcome them because greater is he that is in you than he that is in the world');
