INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 4, 6, 'We are of God: he that knoweth God heareth us; he that is not of God heareth not us. Hereby know we the spirit of truth, and the spirit of error.', 'we are of god he that knoweth god heareth us he that is not of god heareth not us hereby know we the spirit of truth and the spirit of error');
