INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 4, 8, 'He that loveth not knoweth not God; for God is love.', 'he that loveth not knoweth not god for god is love');
