INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 62, 'Unknown', 5, 1, 'Whosoever believeth that Jesus is the Christ is born of God: and every one that loveth him that begat loveth him also that is begotten of him. {is born: Gr. has been born}', 'whosoever believeth that jesus is the christ is born of god and every one that loveth him that begat loveth him also that is begotten of him is born gr has been born');
