INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 5, 'He that overcometh, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.', 'he that overcometh the same shall be clothed in white raiment and i will not blot out his name out of the book of life but i will confess his name before my father and before his angels');
