INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 7, 'And to the angel of the church in Philadelphia write; These things saith he that is holy, he that is true, he that hath the key of David, he that openeth, and no man shutteth; and shutteth, and no man openeth;', 'and to the angel of the church in philadelphia write these things saith he that is holy he that is true he that hath the key of david he that openeth and no man shutteth and shutteth and no man openeth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 8, 'I know thy works: behold, I have set before thee an open door, and no man can shut it: for thou hast a little strength, and hast kept my word, and hast not denied my name.', 'i know thy works behold i have set before thee an open door and no man can shut it for thou hast a little strength and hast kept my word and hast not denied my name');
