INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 10, 'Because thou hast kept the word of my patience, I also will keep thee from the hour of temptation, which shall come upon all the world, to try them that dwell upon the earth.', 'because thou hast kept the word of my patience i also will keep thee from the hour of temptation which shall come upon all the world to try them that dwell upon the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 11, 'Behold, I come quickly: hold that fast which thou hast, that no man take thy crown.', 'behold i come quickly hold that fast which thou hast that no man take thy crown');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 12, 'Him that overcometh will I make a pillar in the temple of my God, and he shall go no more out: and I will write upon him the name of my God, and the name of the city of my God, {which is} new Jerusalem, which cometh down out of heaven from my God: and {I will write upon him} my new name.', 'him that overcometh will i make a pillar in the temple of my god and he shall go no more out and i will write upon him the name of my god and the name of the city of my god which is new jerusalem which cometh down out of heaven from my god and i will write upon him my new name');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 13, 'He that hath an ear, let him hear what the Spirit saith unto the churches.', 'he that hath an ear let him hear what the spirit saith unto the churches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 14, 'And unto the angel of the church of the Laodiceans write; These things saith the Amen, the faithful and true witness, the beginning of the creation of God; {of the Laodiceans: or, in Laodicea}', 'and unto the angel of the church of the laodiceans write these things saith the amen the faithful and true witness the beginning of the creation of god of the laodiceans or in laodicea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 15, 'I know thy works, that thou art neither cold nor hot: I would thou wert cold or hot.', 'i know thy works that thou art neither cold nor hot i would thou wert cold or hot');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 16, 'So then because thou art lukewarm, and neither cold nor hot, I will spue thee out of my mouth.', 'so then because thou art lukewarm and neither cold nor hot i will spue thee out of my mouth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 17, 'Because thou sayest, I am rich, and increased with goods, and have need of nothing; and knowest not that thou art wretched, and miserable, and poor, and blind, and naked:', 'because thou sayest i am rich and increased with goods and have need of nothing and knowest not that thou art wretched and miserable and poor and blind and naked');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 18, 'I counsel thee to buy of me gold tried in the fire, that thou mayest be rich; and white raiment, that thou mayest be clothed, and {that} the shame of thy nakedness do not appear; and anoint thine eyes with eyesalve, that thou mayest see.', 'i counsel thee to buy of me gold tried in the fire that thou mayest be rich and white raiment that thou mayest be clothed and that the shame of thy nakedness do not appear and anoint thine eyes with eyesalve that thou mayest see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 19, 'As many as I love, I rebuke and chasten: be zealous therefore, and repent.', 'as many as i love i rebuke and chasten be zealous therefore and repent');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 20, 'Behold, I stand at the door, and knock: if any man hear my voice, and open the door, I will come in to him, and will sup with him, and he with me.', 'behold i stand at the door and knock if any man hear my voice and open the door i will come in to him and will sup with him and he with me');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 21, 'To him that overcometh will I grant to sit with me in my throne, even as I also overcame, and am set down with my Father in his throne.', 'to him that overcometh will i grant to sit with me in my throne even as i also overcame and am set down with my father in his throne');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 3, 22, 'He that hath an ear, let him hear what the Spirit saith unto the churches.', 'he that hath an ear let him hear what the spirit saith unto the churches');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 1, 'After this I looked, and, behold, a door {was} opened in heaven: and the first voice which I heard {was} as it were of a trumpet talking with me; which said, Come up hither, and I will shew thee things which must be hereafter.', 'after this i looked and behold a door was opened in heaven and the first voice which i heard was as it were of a trumpet talking with me which said come up hither and i will shew thee things which must be hereafter');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 2, 'And immediately I was in the spirit: and, behold, a throne was set in heaven, and {one} sat on the throne.', 'and immediately i was in the spirit and behold a throne was set in heaven and one sat on the throne');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 3, 'And he that sat was to look upon like a jasper and a sardine stone: and {there was} a rainbow round about the throne, in sight like unto an emerald.', 'and he that sat was to look upon like a jasper and a sardine stone and there was a rainbow round about the throne in sight like unto an emerald');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 4, 'And round about the throne {were} four and twenty seats: and upon the seats I saw four and twenty elders sitting, clothed in white raiment; and they had on their heads crowns of gold.', 'and round about the throne were four and twenty seats and upon the seats i saw four and twenty elders sitting clothed in white raiment and they had on their heads crowns of gold');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 5, 'And out of the throne proceeded lightnings and thunderings and voices: and {there were} seven lamps of fire burning before the throne, which are the seven Spirits of God.', 'and out of the throne proceeded lightnings and thunderings and voices and there were seven lamps of fire burning before the throne which are the seven spirits of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 6, 'And before the throne {there was} a sea of glass like unto crystal: and in the midst of the throne, and round about the throne, {were} four beasts full of eyes before and behind.', 'and before the throne there was a sea of glass like unto crystal and in the midst of the throne and round about the throne were four beasts full of eyes before and behind');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 7, 'And the first beast {was} like a lion, and the second beast like a calf, and the third beast had a face as a man, and the fourth beast {was} like a flying eagle.', 'and the first beast was like a lion and the second beast like a calf and the third beast had a face as a man and the fourth beast was like a flying eagle');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 8, 'And the four beasts had each of them six wings about {him}; and {they were} full of eyes within: and they rest not day and night, saying, Holy, holy, holy, Lord God Almighty, which was, and is, and is to come. {rest...: Gr. have no rest}', 'and the four beasts had each of them six wings about him and they were full of eyes within and they rest not day and night saying holy holy holy lord god almighty which was and is and is to come rest gr have no rest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 9, 'And when those beasts give glory and honour and thanks to him that sat on the throne, who liveth for ever and ever,', 'and when those beasts give glory and honour and thanks to him that sat on the throne who liveth for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 10, 'The four and twenty elders fall down before him that sat on the throne, and worship him that liveth for ever and ever, and cast their crowns before the throne, saying,', 'the four and twenty elders fall down before him that sat on the throne and worship him that liveth for ever and ever and cast their crowns before the throne saying');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 4, 11, 'Thou art worthy, O Lord, to receive glory and honour and power: for thou hast created all things, and for thy pleasure they are and were created.', 'thou art worthy o lord to receive glory and honour and power for thou hast created all things and for thy pleasure they are and were created');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 1, 'And I saw in the right hand of him that sat on the throne a book written within and on the backside, sealed with seven seals.', 'and i saw in the right hand of him that sat on the throne a book written within and on the backside sealed with seven seals');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 2, 'And I saw a strong angel proclaiming with a loud voice, Who is worthy to open the book, and to loose the seals thereof?', 'and i saw a strong angel proclaiming with a loud voice who is worthy to open the book and to loose the seals thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 3, 'And no man in heaven, nor in earth, neither under the earth, was able to open the book, neither to look thereon.', 'and no man in heaven nor in earth neither under the earth was able to open the book neither to look thereon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 4, 'And I wept much, because no man was found worthy to open and to read the book, neither to look thereon.', 'and i wept much because no man was found worthy to open and to read the book neither to look thereon');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 5, 'And one of the elders saith unto me, Weep not: behold, the Lion of the tribe of Juda, the Root of David, hath prevailed to open the book, and to loose the seven seals thereof.', 'and one of the elders saith unto me weep not behold the lion of the tribe of juda the root of david hath prevailed to open the book and to loose the seven seals thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 6, 'And I beheld, and, lo, in the midst of the throne and of the four beasts, and in the midst of the elders, stood a Lamb as it had been slain, having seven horns and seven eyes, which are the seven Spirits of God sent forth into all the earth.', 'and i beheld and lo in the midst of the throne and of the four beasts and in the midst of the elders stood a lamb as it had been slain having seven horns and seven eyes which are the seven spirits of god sent forth into all the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 7, 'And he came and took the book out of the right hand of him that sat upon the throne.', 'and he came and took the book out of the right hand of him that sat upon the throne');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 8, 'And when he had taken the book, the four beasts and four {and} twenty elders fell down before the Lamb, having every one of them harps, and golden vials full of odours, which are the prayers of saints. {odours: or, incense}', 'and when he had taken the book the four beasts and four and twenty elders fell down before the lamb having every one of them harps and golden vials full of odours which are the prayers of saints odours or incense');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 9, 'And they sung a new song, saying, Thou art worthy to take the book, and to open the seals thereof: for thou wast slain, and hast redeemed us to God by thy blood out of every kindred, and tongue, and people, and nation;', 'and they sung a new song saying thou art worthy to take the book and to open the seals thereof for thou wast slain and hast redeemed us to god by thy blood out of every kindred and tongue and people and nation');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 10, 'And hast made us unto our God kings and priests: and we shall reign on the earth.', 'and hast made us unto our god kings and priests and we shall reign on the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 11, 'And I beheld, and I heard the voice of many angels round about the throne and the beasts and the elders: and the number of them was ten thousand times ten thousand, and thousands of thousands;', 'and i beheld and i heard the voice of many angels round about the throne and the beasts and the elders and the number of them was ten thousand times ten thousand and thousands of thousands');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 12, 'Saying with a loud voice, Worthy is the Lamb that was slain to receive power, and riches, and wisdom, and strength, and honour, and glory, and blessing.', 'saying with a loud voice worthy is the lamb that was slain to receive power and riches and wisdom and strength and honour and glory and blessing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 13, 'And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, {be} unto him that sitteth upon the throne, and unto the Lamb for ever and ever.', 'and every creature which is in heaven and on the earth and under the earth and such as are in the sea and all that are in them heard i saying blessing and honour and glory and power be unto him that sitteth upon the throne and unto the lamb for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 5, 14, 'And the four beasts said, Amen. And the four {and} twenty elders fell down and worshipped him that liveth for ever and ever.', 'and the four beasts said amen and the four and twenty elders fell down and worshipped him that liveth for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 1, 'And I saw when the Lamb opened one of the seals, and I heard, as it were the noise of thunder, one of the four beasts saying, Come and see.', 'and i saw when the lamb opened one of the seals and i heard as it were the noise of thunder one of the four beasts saying come and see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 2, 'And I saw, and behold a white horse: and he that sat on him had a bow; and a crown was given unto him: and he went forth conquering, and to conquer.', 'and i saw and behold a white horse and he that sat on him had a bow and a crown was given unto him and he went forth conquering and to conquer');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 3, 'And when he had opened the second seal, I heard the second beast say, Come and see.', 'and when he had opened the second seal i heard the second beast say come and see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 4, 'And there went out another horse {that was} red: and {power} was given to him that sat thereon to take peace from the earth, and that they should kill one another: and there was given unto him a great sword.', 'and there went out another horse that was red and power was given to him that sat thereon to take peace from the earth and that they should kill one another and there was given unto him a great sword');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 5, 'And when he had opened the third seal, I heard the third beast say, Come and see. And I beheld, and lo a black horse; and he that sat on him had a pair of balances in his hand.', 'and when he had opened the third seal i heard the third beast say come and see and i beheld and lo a black horse and he that sat on him had a pair of balances in his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 6, 'And I heard a voice in the midst of the four beasts say, A measure of wheat for a penny, and three measures of barley for a penny; and {see} thou hurt not the oil and the wine. {A measure: the word choenix signifieth a measure containing one wine quart, and the twelfth part of a quart}', 'and i heard a voice in the midst of the four beasts say a measure of wheat for a penny and three measures of barley for a penny and see thou hurt not the oil and the wine a measure the word choenix signifieth a measure containing one wine quart and the twelfth part of a quart');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 7, 'And when he had opened the fourth seal, I heard the voice of the fourth beast say, Come and see.', 'and when he had opened the fourth seal i heard the voice of the fourth beast say come and see');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 8, 'And I looked, and behold a pale horse: and his name that sat on him was Death, and Hell followed with him. And power was given unto them over the fourth part of the earth, to kill with sword, and with hunger, and with death, and with the beasts of the earth. {unto them: or, to him}', 'and i looked and behold a pale horse and his name that sat on him was death and hell followed with him and power was given unto them over the fourth part of the earth to kill with sword and with hunger and with death and with the beasts of the earth unto them or to him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 9, 'And when he had opened the fifth seal, I saw under the altar the souls of them that were slain for the word of God, and for the testimony which they held:', 'and when he had opened the fifth seal i saw under the altar the souls of them that were slain for the word of god and for the testimony which they held');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 10, 'And they cried with a loud voice, saying, How long, O Lord, holy and true, dost thou not judge and avenge our blood on them that dwell on the earth?', 'and they cried with a loud voice saying how long o lord holy and true dost thou not judge and avenge our blood on them that dwell on the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 11, 'And white robes were given unto every one of them; and it was said unto them, that they should rest yet for a little season, until their fellowservants also and their brethren, that should be killed as they {were}, should be fulfilled.', 'and white robes were given unto every one of them and it was said unto them that they should rest yet for a little season until their fellowservants also and their brethren that should be killed as they were should be fulfilled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 12, 'And I beheld when he had opened the sixth seal, and, lo, there was a great earthquake; and the sun became black as sackcloth of hair, and the moon became as blood;', 'and i beheld when he had opened the sixth seal and lo there was a great earthquake and the sun became black as sackcloth of hair and the moon became as blood');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 13, 'And the stars of heaven fell unto the earth, even as a fig tree casteth her untimely figs, when she is shaken of a mighty wind. {untimely figs: or, green figs}', 'and the stars of heaven fell unto the earth even as a fig tree casteth her untimely figs when she is shaken of a mighty wind untimely figs or green figs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 14, 'And the heaven departed as a scroll when it is rolled together; and every mountain and island were moved out of their places.', 'and the heaven departed as a scroll when it is rolled together and every mountain and island were moved out of their places');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 15, 'And the kings of the earth, and the great men, and the rich men, and the chief captains, and the mighty men, and every bondman, and every free man, hid themselves in the dens and in the rocks of the mountains;', 'and the kings of the earth and the great men and the rich men and the chief captains and the mighty men and every bondman and every free man hid themselves in the dens and in the rocks of the mountains');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 16, 'And said to the mountains and rocks, Fall on us, and hide us from the face of him that sitteth on the throne, and from the wrath of the Lamb:', 'and said to the mountains and rocks fall on us and hide us from the face of him that sitteth on the throne and from the wrath of the lamb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 6, 17, 'For the great day of his wrath is come; and who shall be able to stand?', 'for the great day of his wrath is come and who shall be able to stand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 7, 1, 'And after these things I saw four angels standing on the four corners of the earth, holding the four winds of the earth, that the wind should not blow on the earth, nor on the sea, nor on any tree.', 'and after these things i saw four angels standing on the four corners of the earth holding the four winds of the earth that the wind should not blow on the earth nor on the sea nor on any tree');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 7, 2, 'And I saw another angel ascending from the east, having the seal of the living God: and he cried with a loud voice to the four angels, to whom it was given to hurt the earth and the sea,', 'and i saw another angel ascending from the east having the seal of the living god and he cried with a loud voice to the four angels to whom it was given to hurt the earth and the sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 7, 3, 'Saying, Hurt not the earth, neither the sea, nor the trees, till we have sealed the servants of our God in their foreheads.', 'saying hurt not the earth neither the sea nor the trees till we have sealed the servants of our god in their foreheads');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 7, 4, 'And I heard the number of them which were sealed: {and there were} sealed an hundred {and} forty {and} four thousand of all the tribes of the children of Israel.', 'and i heard the number of them which were sealed and there were sealed an hundred and forty and four thousand of all the tribes of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 7, 5, 'Of the tribe of Juda {were} sealed twelve thousand. Of the tribe of Reuben {were} sealed twelve thousand. Of the tribe of Gad {were} sealed twelve thousand.', 'of the tribe of juda were sealed twelve thousand of the tribe of reuben were sealed twelve thousand of the tribe of gad were sealed twelve thousand');
