INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 8, 9, 'And the third part of the creatures which were in the sea, and had life, died; and the third part of the ships were destroyed.', 'and the third part of the creatures which were in the sea and had life died and the third part of the ships were destroyed');
