INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 9, 2, 'And he opened the bottomless pit; and there arose a smoke out of the pit, as the smoke of a great furnace; and the sun and the air were darkened by reason of the smoke of the pit.', 'and he opened the bottomless pit and there arose a smoke out of the pit as the smoke of a great furnace and the sun and the air were darkened by reason of the smoke of the pit');
