INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 9, 4, 'And it was commanded them that they should not hurt the grass of the earth, neither any green thing, neither any tree; but only those men which have not the seal of God in their foreheads.', 'and it was commanded them that they should not hurt the grass of the earth neither any green thing neither any tree but only those men which have not the seal of god in their foreheads');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 9, 5, 'And to them it was given that they should not kill them, but that they should be tormented five months: and their torment {was} as the torment of a scorpion, when he striketh a man.', 'and to them it was given that they should not kill them but that they should be tormented five months and their torment was as the torment of a scorpion when he striketh a man');
