INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 14, 14, 'And I looked, and behold a white cloud, and upon the cloud {one} sat like unto the Son of man, having on his head a golden crown, and in his hand a sharp sickle.', 'and i looked and behold a white cloud and upon the cloud one sat like unto the son of man having on his head a golden crown and in his hand a sharp sickle');
