INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 14, 19, 'And the angel thrust in his sickle into the earth, and gathered the vine of the earth, and cast {it} into the great winepress of the wrath of God.', 'and the angel thrust in his sickle into the earth and gathered the vine of the earth and cast it into the great winepress of the wrath of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 14, 20, 'And the winepress was trodden without the city, and blood came out of the winepress, even unto the horse bridles, by the space of a thousand {and} six hundred furlongs.', 'and the winepress was trodden without the city and blood came out of the winepress even unto the horse bridles by the space of a thousand and six hundred furlongs');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 15, 1, 'And I saw another sign in heaven, great and marvellous, seven angels having the seven last plagues; for in them is filled up the wrath of God.', 'and i saw another sign in heaven great and marvellous seven angels having the seven last plagues for in them is filled up the wrath of god');
