INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 15, 4, 'Who shall not fear thee, O Lord, and glorify thy name? for {thou} only {art} holy: for all nations shall come and worship before thee; for thy judgments are made manifest.', 'who shall not fear thee o lord and glorify thy name for thou only art holy for all nations shall come and worship before thee for thy judgments are made manifest');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 15, 5, 'And after that I looked, and, behold, the temple of the tabernacle of the testimony in heaven was opened:', 'and after that i looked and behold the temple of the tabernacle of the testimony in heaven was opened');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 15, 6, 'And the seven angels came out of the temple, having the seven plagues, clothed in pure and white linen, and having their breasts girded with golden girdles.', 'and the seven angels came out of the temple having the seven plagues clothed in pure and white linen and having their breasts girded with golden girdles');
