INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 15, 8, 'And the temple was filled with smoke from the glory of God, and from his power; and no man was able to enter into the temple, till the seven plagues of the seven angels were fulfilled.', 'and the temple was filled with smoke from the glory of god and from his power and no man was able to enter into the temple till the seven plagues of the seven angels were fulfilled');
