INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 16, 18, 'And there were voices, and thunders, and lightnings; and there was a great earthquake, such as was not since men were upon the earth, so mighty an earthquake, {and} so great.', 'and there were voices and thunders and lightnings and there was a great earthquake such as was not since men were upon the earth so mighty an earthquake and so great');
