INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 5, 'And upon her forehead {was} a name written, MYSTERY, BABYLON THE GREAT, THE MOTHER OF HARLOTS AND ABOMINATIONS OF THE EARTH. {harlots: or, fornications}', 'and upon her forehead was a name written mystery babylon the great the mother of harlots and abominations of the earth harlots or fornications');
