INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 7, 'And the angel said unto me, Wherefore didst thou marvel? I will tell thee the mystery of the woman, and of the beast that carrieth her, which hath the seven heads and ten horns.', 'and the angel said unto me wherefore didst thou marvel i will tell thee the mystery of the woman and of the beast that carrieth her which hath the seven heads and ten horns');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 8, 'The beast that thou sawest was, and is not; and shall ascend out of the bottomless pit, and go into perdition: and they that dwell on the earth shall wonder, whose names were not written in the book of life from the foundation of the world, when they behold the beast that was, and is not, and yet is.', 'the beast that thou sawest was and is not and shall ascend out of the bottomless pit and go into perdition and they that dwell on the earth shall wonder whose names were not written in the book of life from the foundation of the world when they behold the beast that was and is not and yet is');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 9, 'And here {is} the mind which hath wisdom. The seven heads are seven mountains, on which the woman sitteth.', 'and here is the mind which hath wisdom the seven heads are seven mountains on which the woman sitteth');
