INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 11, 'And the beast that was, and is not, even he is the eighth, and is of the seven, and goeth into perdition.', 'and the beast that was and is not even he is the eighth and is of the seven and goeth into perdition');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 12, 'And the ten horns which thou sawest are ten kings, which have received no kingdom as yet; but receive power as kings one hour with the beast.', 'and the ten horns which thou sawest are ten kings which have received no kingdom as yet but receive power as kings one hour with the beast');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 13, 'These have one mind, and shall give their power and strength unto the beast.', 'these have one mind and shall give their power and strength unto the beast');
