INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 16, 'And the ten horns which thou sawest upon the beast, these shall hate the whore, and shall make her desolate and naked, and shall eat her flesh, and burn her with fire.', 'and the ten horns which thou sawest upon the beast these shall hate the whore and shall make her desolate and naked and shall eat her flesh and burn her with fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 17, 'For God hath put in their hearts to fulfil his will, and to agree, and give their kingdom unto the beast, until the words of God shall be fulfilled.', 'for god hath put in their hearts to fulfil his will and to agree and give their kingdom unto the beast until the words of god shall be fulfilled');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 17, 18, 'And the woman which thou sawest is that great city, which reigneth over the kings of the earth.', 'and the woman which thou sawest is that great city which reigneth over the kings of the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 1, 'And after these things I saw another angel come down from heaven, having great power; and the earth was lightened with his glory.', 'and after these things i saw another angel come down from heaven having great power and the earth was lightened with his glory');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 2, 'And he cried mightily with a strong voice, saying, Babylon the great is fallen, is fallen, and is become the habitation of devils, and the hold of every foul spirit, and a cage of every unclean and hateful bird.', 'and he cried mightily with a strong voice saying babylon the great is fallen is fallen and is become the habitation of devils and the hold of every foul spirit and a cage of every unclean and hateful bird');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 3, 'For all nations have drunk of the wine of the wrath of her fornication, and the kings of the earth have committed fornication with her, and the merchants of the earth are waxed rich through the abundance of her delicacies. {abundance: or, power}', 'for all nations have drunk of the wine of the wrath of her fornication and the kings of the earth have committed fornication with her and the merchants of the earth are waxed rich through the abundance of her delicacies abundance or power');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 4, 'And I heard another voice from heaven, saying, Come out of her, my people, that ye be not partakers of her sins, and that ye receive not of her plagues.', 'and i heard another voice from heaven saying come out of her my people that ye be not partakers of her sins and that ye receive not of her plagues');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 5, 'For her sins have reached unto heaven, and God hath remembered her iniquities.', 'for her sins have reached unto heaven and god hath remembered her iniquities');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 6, 'Reward her even as she rewarded you, and double unto her double according to her works: in the cup which she hath filled fill to her double.', 'reward her even as she rewarded you and double unto her double according to her works in the cup which she hath filled fill to her double');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 7, 'How much she hath glorified herself, and lived deliciously, so much torment and sorrow give her: for she saith in her heart, I sit a queen, and am no widow, and shall see no sorrow.', 'how much she hath glorified herself and lived deliciously so much torment and sorrow give her for she saith in her heart i sit a queen and am no widow and shall see no sorrow');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 8, 'Therefore shall her plagues come in one day, death, and mourning, and famine; and she shall be utterly burned with fire: for strong {is} the Lord God who judgeth her.', 'therefore shall her plagues come in one day death and mourning and famine and she shall be utterly burned with fire for strong is the lord god who judgeth her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 9, 'And the kings of the earth, who have committed fornication and lived deliciously with her, shall bewail her, and lament for her, when they shall see the smoke of her burning,', 'and the kings of the earth who have committed fornication and lived deliciously with her shall bewail her and lament for her when they shall see the smoke of her burning');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 10, 'Standing afar off for the fear of her torment, saying, Alas, alas, that great city Babylon, that mighty city! for in one hour is thy judgment come.', 'standing afar off for the fear of her torment saying alas alas that great city babylon that mighty city for in one hour is thy judgment come');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 11, 'And the merchants of the earth shall weep and mourn over her; for no man buyeth their merchandise any more:', 'and the merchants of the earth shall weep and mourn over her for no man buyeth their merchandise any more');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 12, 'The merchandise of gold, and silver, and precious stones, and of pearls, and fine linen, and purple, and silk, and scarlet, and all thyine wood, and all manner vessels of ivory, and all manner vessels of most precious wood, and of brass, and iron, and marble, {thyine: or, sweet}', 'the merchandise of gold and silver and precious stones and of pearls and fine linen and purple and silk and scarlet and all thyine wood and all manner vessels of ivory and all manner vessels of most precious wood and of brass and iron and marble thyine or sweet');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 13, 'And cinnamon, and odours, and ointments, and frankincense, and wine, and oil, and fine flour, and wheat, and beasts, and sheep, and horses, and chariots, and slaves, and souls of men. {slaves: or, bodies}', 'and cinnamon and odours and ointments and frankincense and wine and oil and fine flour and wheat and beasts and sheep and horses and chariots and slaves and souls of men slaves or bodies');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 14, 'And the fruits that thy soul lusted after are departed from thee, and all things which were dainty and goodly are departed from thee, and thou shalt find them no more at all.', 'and the fruits that thy soul lusted after are departed from thee and all things which were dainty and goodly are departed from thee and thou shalt find them no more at all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 15, 'The merchants of these things, which were made rich by her, shall stand afar off for the fear of her torment, weeping and wailing,', 'the merchants of these things which were made rich by her shall stand afar off for the fear of her torment weeping and wailing');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 16, 'And saying, Alas, alas, that great city, that was clothed in fine linen, and purple, and scarlet, and decked with gold, and precious stones, and pearls!', 'and saying alas alas that great city that was clothed in fine linen and purple and scarlet and decked with gold and precious stones and pearls');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 17, 'For in one hour so great riches is come to nought. And every shipmaster, and all the company in ships, and sailors, and as many as trade by sea, stood afar off,', 'for in one hour so great riches is come to nought and every shipmaster and all the company in ships and sailors and as many as trade by sea stood afar off');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 18, 'And cried when they saw the smoke of her burning, saying, What {city is} like unto this great city!', 'and cried when they saw the smoke of her burning saying what city is like unto this great city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 19, 'And they cast dust on their heads, and cried, weeping and wailing, saying, Alas, alas, that great city, wherein were made rich all that had ships in the sea by reason of her costliness! for in one hour is she made desolate.', 'and they cast dust on their heads and cried weeping and wailing saying alas alas that great city wherein were made rich all that had ships in the sea by reason of her costliness for in one hour is she made desolate');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 20, 'Rejoice over her, {thou} heaven, and {ye} holy apostles and prophets; for God hath avenged you on her.', 'rejoice over her thou heaven and ye holy apostles and prophets for god hath avenged you on her');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 21, 'And a mighty angel took up a stone like a great millstone, and cast {it} into the sea, saying, Thus with violence shall that great city Babylon be thrown down, and shall be found no more at all.', 'and a mighty angel took up a stone like a great millstone and cast it into the sea saying thus with violence shall that great city babylon be thrown down and shall be found no more at all');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 22, 'And the voice of harpers, and musicians, and of pipers, and trumpeters, shall be heard no more at all in thee; and no craftsman, of whatsoever craft {he be}, shall be found any more in thee; and the sound of a millstone shall be heard no more at all in thee;', 'and the voice of harpers and musicians and of pipers and trumpeters shall be heard no more at all in thee and no craftsman of whatsoever craft he be shall be found any more in thee and the sound of a millstone shall be heard no more at all in thee');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 23, 'And the light of a candle shall shine no more at all in thee; and the voice of the bridegroom and of the bride shall be heard no more at all in thee: for thy merchants were the great men of the earth; for by thy sorceries were all nations deceived.', 'and the light of a candle shall shine no more at all in thee and the voice of the bridegroom and of the bride shall be heard no more at all in thee for thy merchants were the great men of the earth for by thy sorceries were all nations deceived');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 18, 24, 'And in her was found the blood of prophets, and of saints, and of all that were slain upon the earth.', 'and in her was found the blood of prophets and of saints and of all that were slain upon the earth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 1, 'And after these things I heard a great voice of much people in heaven, saying, Alleluia; Salvation, and glory, and honour, and power, unto the Lord our God:', 'and after these things i heard a great voice of much people in heaven saying alleluia salvation and glory and honour and power unto the lord our god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 2, 'For true and righteous {are} his judgments: for he hath judged the great whore, which did corrupt the earth with her fornication, and hath avenged the blood of his servants at her hand.', 'for true and righteous are his judgments for he hath judged the great whore which did corrupt the earth with her fornication and hath avenged the blood of his servants at her hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 3, 'And again they said, Alleluia. And her smoke rose up for ever and ever.', 'and again they said alleluia and her smoke rose up for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 4, 'And the four and twenty elders and the four beasts fell down and worshipped God that sat on the throne, saying, Amen; Alleluia.', 'and the four and twenty elders and the four beasts fell down and worshipped god that sat on the throne saying amen alleluia');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 5, 'And a voice came out of the throne, saying, Praise our God, all ye his servants, and ye that fear him, both small and great.', 'and a voice came out of the throne saying praise our god all ye his servants and ye that fear him both small and great');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 6, 'And I heard as it were the voice of a great multitude, and as the voice of many waters, and as the voice of mighty thunderings, saying, Alleluia: for the Lord God omnipotent reigneth.', 'and i heard as it were the voice of a great multitude and as the voice of many waters and as the voice of mighty thunderings saying alleluia for the lord god omnipotent reigneth');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 7, 'Let us be glad and rejoice, and give honour to him: for the marriage of the Lamb is come, and his wife hath made herself ready.', 'let us be glad and rejoice and give honour to him for the marriage of the lamb is come and his wife hath made herself ready');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 8, 'And to her was granted that she should be arrayed in fine linen, clean and white: for the fine linen is the righteousness of saints. {white: or, bright}', 'and to her was granted that she should be arrayed in fine linen clean and white for the fine linen is the righteousness of saints white or bright');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 9, 'And he saith unto me, Write, Blessed {are} they which are called unto the marriage supper of the Lamb. And he saith unto me, These are the true sayings of God.', 'and he saith unto me write blessed are they which are called unto the marriage supper of the lamb and he saith unto me these are the true sayings of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 10, 'And I fell at his feet to worship him. And he said unto me, See {thou do it} not: I am thy fellowservant, and of thy brethren that have the testimony of Jesus: worship God: for the testimony of Jesus is the spirit of prophecy.', 'and i fell at his feet to worship him and he said unto me see thou do it not i am thy fellowservant and of thy brethren that have the testimony of jesus worship god for the testimony of jesus is the spirit of prophecy');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 11, 'And I saw heaven opened, and behold a white horse; and he that sat upon him {was} called Faithful and True, and in righteousness he doth judge and make war.', 'and i saw heaven opened and behold a white horse and he that sat upon him was called faithful and true and in righteousness he doth judge and make war');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 12, 'His eyes {were} as a flame of fire, and on his head {were} many crowns; and he had a name written, that no man knew, but he himself.', 'his eyes were as a flame of fire and on his head were many crowns and he had a name written that no man knew but he himself');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 13, 'And he {was} clothed with a vesture dipped in blood: and his name is called The Word of God.', 'and he was clothed with a vesture dipped in blood and his name is called the word of god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 14, 'And the armies {which were} in heaven followed him upon white horses, clothed in fine linen, white and clean.', 'and the armies which were in heaven followed him upon white horses clothed in fine linen white and clean');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 15, 'And out of his mouth goeth a sharp sword, that with it he should smite the nations: and he shall rule them with a rod of iron: and he treadeth the winepress of the fierceness and wrath of Almighty God.', 'and out of his mouth goeth a sharp sword that with it he should smite the nations and he shall rule them with a rod of iron and he treadeth the winepress of the fierceness and wrath of almighty god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 16, 'And he hath on {his} vesture and on his thigh a name written, KING OF KINGS, AND LORD OF LORDS.', 'and he hath on his vesture and on his thigh a name written king of kings and lord of lords');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 17, 'And I saw an angel standing in the sun; and he cried with a loud voice, saying to all the fowls that fly in the midst of heaven, Come and gather yourselves together unto the supper of the great God;', 'and i saw an angel standing in the sun and he cried with a loud voice saying to all the fowls that fly in the midst of heaven come and gather yourselves together unto the supper of the great god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 18, 'That ye may eat the flesh of kings, and the flesh of captains, and the flesh of mighty men, and the flesh of horses, and of them that sit on them, and the flesh of all {men, both} free and bond, both small and great.', 'that ye may eat the flesh of kings and the flesh of captains and the flesh of mighty men and the flesh of horses and of them that sit on them and the flesh of all men both free and bond both small and great');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 19, 'And I saw the beast, and the kings of the earth, and their armies, gathered together to make war against him that sat on the horse, and against his army.', 'and i saw the beast and the kings of the earth and their armies gathered together to make war against him that sat on the horse and against his army');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 20, 'And the beast was taken, and with him the false prophet that wrought miracles before him, with which he deceived them that had received the mark of the beast, and them that worshipped his image. These both were cast alive into a lake of fire burning with brimstone.', 'and the beast was taken and with him the false prophet that wrought miracles before him with which he deceived them that had received the mark of the beast and them that worshipped his image these both were cast alive into a lake of fire burning with brimstone');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 19, 21, 'And the remnant were slain with the sword of him that sat upon the horse, which {sword} proceeded out of his mouth: and all the fowls were filled with their flesh.', 'and the remnant were slain with the sword of him that sat upon the horse which sword proceeded out of his mouth and all the fowls were filled with their flesh');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 1, 'And I saw an angel come down from heaven, having the key of the bottomless pit and a great chain in his hand.', 'and i saw an angel come down from heaven having the key of the bottomless pit and a great chain in his hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 2, 'And he laid hold on the dragon, that old serpent, which is the Devil, and Satan, and bound him a thousand years,', 'and he laid hold on the dragon that old serpent which is the devil and satan and bound him a thousand years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 3, 'And cast him into the bottomless pit, and shut him up, and set a seal upon him, that he should deceive the nations no more, till the thousand years should be fulfilled: and after that he must be loosed a little season.', 'and cast him into the bottomless pit and shut him up and set a seal upon him that he should deceive the nations no more till the thousand years should be fulfilled and after that he must be loosed a little season');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 4, 'And I saw thrones, and they sat upon them, and judgment was given unto them: and {I saw} the souls of them that were beheaded for the witness of Jesus, and for the word of God, and which had not worshipped the beast, neither his image, neither had received {his} mark upon their foreheads, or in their hands; and they lived and reigned with Christ a thousand years.', 'and i saw thrones and they sat upon them and judgment was given unto them and i saw the souls of them that were beheaded for the witness of jesus and for the word of god and which had not worshipped the beast neither his image neither had received his mark upon their foreheads or in their hands and they lived and reigned with christ a thousand years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 5, 'But the rest of the dead lived not again until the thousand years were finished. This {is} the first resurrection.', 'but the rest of the dead lived not again until the thousand years were finished this is the first resurrection');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 6, 'Blessed and holy {is} he that hath part in the first resurrection: on such the second death hath no power, but they shall be priests of God and of Christ, and shall reign with him a thousand years.', 'blessed and holy is he that hath part in the first resurrection on such the second death hath no power but they shall be priests of god and of christ and shall reign with him a thousand years');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 7, 'And when the thousand years are expired, Satan shall be loosed out of his prison,', 'and when the thousand years are expired satan shall be loosed out of his prison');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 8, 'And shall go out to deceive the nations which are in the four quarters of the earth, Gog and Magog, to gather them together to battle: the number of whom {is} as the sand of the sea.', 'and shall go out to deceive the nations which are in the four quarters of the earth gog and magog to gather them together to battle the number of whom is as the sand of the sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 9, 'And they went up on the breadth of the earth, and compassed the camp of the saints about, and the beloved city: and fire came down from God out of heaven, and devoured them.', 'and they went up on the breadth of the earth and compassed the camp of the saints about and the beloved city and fire came down from god out of heaven and devoured them');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 10, 'And the devil that deceived them was cast into the lake of fire and brimstone, where the beast and the false prophet {are}, and shall be tormented day and night for ever and ever.', 'and the devil that deceived them was cast into the lake of fire and brimstone where the beast and the false prophet are and shall be tormented day and night for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 11, 'And I saw a great white throne, and him that sat on it, from whose face the earth and the heaven fled away; and there was found no place for them.', 'and i saw a great white throne and him that sat on it from whose face the earth and the heaven fled away and there was found no place for them');
