INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 13, 'And the sea gave up the dead which were in it; and death and hell delivered up the dead which were in them: and they were judged every man according to their works. {hell: or, the grave}', 'and the sea gave up the dead which were in it and death and hell delivered up the dead which were in them and they were judged every man according to their works hell or the grave');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 14, 'And death and hell were cast into the lake of fire. This is the second death.', 'and death and hell were cast into the lake of fire this is the second death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 20, 15, 'And whosoever was not found written in the book of life was cast into the lake of fire.', 'and whosoever was not found written in the book of life was cast into the lake of fire');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 1, 'And I saw a new heaven and a new earth: for the first heaven and the first earth were passed away; and there was no more sea.', 'and i saw a new heaven and a new earth for the first heaven and the first earth were passed away and there was no more sea');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 2, 'And I John saw the holy city, new Jerusalem, coming down from God out of heaven, prepared as a bride adorned for her husband.', 'and i john saw the holy city new jerusalem coming down from god out of heaven prepared as a bride adorned for her husband');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 3, 'And I heard a great voice out of heaven saying, Behold, the tabernacle of God {is} with men, and he will dwell with them, and they shall be his people, and God himself shall be with them, {and be} their God.', 'and i heard a great voice out of heaven saying behold the tabernacle of god is with men and he will dwell with them and they shall be his people and god himself shall be with them and be their god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 4, 'And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.', 'and god shall wipe away all tears from their eyes and there shall be no more death neither sorrow nor crying neither shall there be any more pain for the former things are passed away');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 5, 'And he that sat upon the throne said, Behold, I make all things new. And he said unto me, Write: for these words are true and faithful.', 'and he that sat upon the throne said behold i make all things new and he said unto me write for these words are true and faithful');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 6, 'And he said unto me, It is done. I am Alpha and Omega, the beginning and the end. I will give unto him that is athirst of the fountain of the water of life freely.', 'and he said unto me it is done i am alpha and omega the beginning and the end i will give unto him that is athirst of the fountain of the water of life freely');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 7, 'He that overcometh shall inherit all things; and I will be his God, and he shall be my son. {all things: or, these things}', 'he that overcometh shall inherit all things and i will be his god and he shall be my son all things or these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 8, 'But the fearful, and unbelieving, and the abominable, and murderers, and whoremongers, and sorcerers, and idolaters, and all liars, shall have their part in the lake which burneth with fire and brimstone: which is the second death.', 'but the fearful and unbelieving and the abominable and murderers and whoremongers and sorcerers and idolaters and all liars shall have their part in the lake which burneth with fire and brimstone which is the second death');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 9, 'And there came unto me one of the seven angels which had the seven vials full of the seven last plagues, and talked with me, saying, Come hither, I will shew thee the bride, the Lamb''s wife.', 'and there came unto me one of the seven angels which had the seven vials full of the seven last plagues and talked with me saying come hither i will shew thee the bride the lamb s wife');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 10, 'And he carried me away in the spirit to a great and high mountain, and shewed me that great city, the holy Jerusalem, descending out of heaven from God,', 'and he carried me away in the spirit to a great and high mountain and shewed me that great city the holy jerusalem descending out of heaven from god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 11, 'Having the glory of God: and her light {was} like unto a stone most precious, even like a jasper stone, clear as crystal;', 'having the glory of god and her light was like unto a stone most precious even like a jasper stone clear as crystal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 12, 'And had a wall great and high, {and} had twelve gates, and at the gates twelve angels, and names written thereon, which are {the names} of the twelve tribes of the children of Israel:', 'and had a wall great and high and had twelve gates and at the gates twelve angels and names written thereon which are the names of the twelve tribes of the children of israel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 13, 'On the east three gates; on the north three gates; on the south three gates; and on the west three gates.', 'on the east three gates on the north three gates on the south three gates and on the west three gates');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 14, 'And the wall of the city had twelve foundations, and in them the names of the twelve apostles of the Lamb.', 'and the wall of the city had twelve foundations and in them the names of the twelve apostles of the lamb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 15, 'And he that talked with me had a golden reed to measure the city, and the gates thereof, and the wall thereof.', 'and he that talked with me had a golden reed to measure the city and the gates thereof and the wall thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 16, 'And the city lieth foursquare, and the length is as large as the breadth: and he measured the city with the reed, twelve thousand furlongs. The length and the breadth and the height of it are equal.', 'and the city lieth foursquare and the length is as large as the breadth and he measured the city with the reed twelve thousand furlongs the length and the breadth and the height of it are equal');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 17, 'And he measured the wall thereof, an hundred {and} forty {and} four cubits, {according to} the measure of a man, that is, of the angel.', 'and he measured the wall thereof an hundred and forty and four cubits according to the measure of a man that is of the angel');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 18, 'And the building of the wall of it was {of} jasper: and the city {was} pure gold, like unto clear glass.', 'and the building of the wall of it was of jasper and the city was pure gold like unto clear glass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 19, 'And the foundations of the wall of the city {were} garnished with all manner of precious stones. The first foundation {was} jasper; the second, sapphire; the third, a chalcedony; the fourth, an emerald;', 'and the foundations of the wall of the city were garnished with all manner of precious stones the first foundation was jasper the second sapphire the third a chalcedony the fourth an emerald');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 20, 'The fifth, sardonyx; the sixth, sardius; the seventh, chrysolite; the eighth, beryl; the ninth, a topaz; the tenth, a chrysoprasus; the eleventh, a jacinth; the twelfth, an amethyst.', 'the fifth sardonyx the sixth sardius the seventh chrysolite the eighth beryl the ninth a topaz the tenth a chrysoprasus the eleventh a jacinth the twelfth an amethyst');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 21, 'And the twelve gates {were} twelve pearls; every several gate was of one pearl: and the street of the city {was} pure gold, as it were transparent glass.', 'and the twelve gates were twelve pearls every several gate was of one pearl and the street of the city was pure gold as it were transparent glass');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 22, 'And I saw no temple therein: for the Lord God Almighty and the Lamb are the temple of it.', 'and i saw no temple therein for the lord god almighty and the lamb are the temple of it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 23, 'And the city had no need of the sun, neither of the moon, to shine in it: for the glory of God did lighten it, and the Lamb {is} the light thereof.', 'and the city had no need of the sun neither of the moon to shine in it for the glory of god did lighten it and the lamb is the light thereof');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 24, 'And the nations of them which are saved shall walk in the light of it: and the kings of the earth do bring their glory and honour into it.', 'and the nations of them which are saved shall walk in the light of it and the kings of the earth do bring their glory and honour into it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 25, 'And the gates of it shall not be shut at all by day: for there shall be no night there.', 'and the gates of it shall not be shut at all by day for there shall be no night there');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 26, 'And they shall bring the glory and honour of the nations into it.', 'and they shall bring the glory and honour of the nations into it');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 21, 27, 'And there shall in no wise enter into it any thing that defileth, neither {whatsoever} worketh abomination, or {maketh} a lie: but they which are written in the Lamb''s book of life.', 'and there shall in no wise enter into it any thing that defileth neither whatsoever worketh abomination or maketh a lie but they which are written in the lamb s book of life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 1, 'And he shewed me a pure river of water of life, clear as crystal, proceeding out of the throne of God and of the Lamb.', 'and he shewed me a pure river of water of life clear as crystal proceeding out of the throne of god and of the lamb');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 2, 'In the midst of the street of it, and on either side of the river, {was there} the tree of life, which bare twelve {manner of} fruits, {and} yielded her fruit every month: and the leaves of the tree {were} for the healing of the nations.', 'in the midst of the street of it and on either side of the river was there the tree of life which bare twelve manner of fruits and yielded her fruit every month and the leaves of the tree were for the healing of the nations');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 3, 'And there shall be no more curse: but the throne of God and of the Lamb shall be in it; and his servants shall serve him:', 'and there shall be no more curse but the throne of god and of the lamb shall be in it and his servants shall serve him');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 4, 'And they shall see his face; and his name {shall be} in their foreheads.', 'and they shall see his face and his name shall be in their foreheads');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 5, 'And there shall be no night there; and they need no candle, neither light of the sun; for the Lord God giveth them light: and they shall reign for ever and ever.', 'and there shall be no night there and they need no candle neither light of the sun for the lord god giveth them light and they shall reign for ever and ever');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 6, 'And he said unto me, These sayings {are} faithful and true: and the Lord God of the holy prophets sent his angel to shew unto his servants the things which must shortly be done.', 'and he said unto me these sayings are faithful and true and the lord god of the holy prophets sent his angel to shew unto his servants the things which must shortly be done');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 7, 'Behold, I come quickly: blessed {is} he that keepeth the sayings of the prophecy of this book.', 'behold i come quickly blessed is he that keepeth the sayings of the prophecy of this book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 8, 'And I John saw these things, and heard {them}. And when I had heard and seen, I fell down to worship before the feet of the angel which shewed me these things.', 'and i john saw these things and heard them and when i had heard and seen i fell down to worship before the feet of the angel which shewed me these things');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 9, 'Then saith he unto me, See {thou do it} not: for I am thy fellowservant, and of thy brethren the prophets, and of them which keep the sayings of this book: worship God.', 'then saith he unto me see thou do it not for i am thy fellowservant and of thy brethren the prophets and of them which keep the sayings of this book worship god');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 10, 'And he saith unto me, Seal not the sayings of the prophecy of this book: for the time is at hand.', 'and he saith unto me seal not the sayings of the prophecy of this book for the time is at hand');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 11, 'He that is unjust, let him be unjust still: and he which is filthy, let him be filthy still: and he that is righteous, let him be righteous still: and he that is holy, let him be holy still.', 'he that is unjust let him be unjust still and he which is filthy let him be filthy still and he that is righteous let him be righteous still and he that is holy let him be holy still');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 12, 'And, behold, I come quickly; and my reward {is} with me, to give every man according as his work shall be.', 'and behold i come quickly and my reward is with me to give every man according as his work shall be');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 13, 'I am Alpha and Omega, the beginning and the end, the first and the last.', 'i am alpha and omega the beginning and the end the first and the last');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 14, 'Blessed {are} they that do his commandments, that they may have right to the tree of life, and may enter in through the gates into the city.', 'blessed are they that do his commandments that they may have right to the tree of life and may enter in through the gates into the city');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 15, 'For without {are} dogs, and sorcerers, and whoremongers, and murderers, and idolaters, and whosoever loveth and maketh a lie.', 'for without are dogs and sorcerers and whoremongers and murderers and idolaters and whosoever loveth and maketh a lie');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 16, 'I Jesus have sent mine angel to testify unto you these things in the churches. I am the root and the offspring of David, {and} the bright and morning star.', 'i jesus have sent mine angel to testify unto you these things in the churches i am the root and the offspring of david and the bright and morning star');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 17, 'And the Spirit and the bride say, Come. And let him that heareth say, Come. And let him that is athirst come. And whosoever will, let him take the water of life freely.', 'and the spirit and the bride say come and let him that heareth say come and let him that is athirst come and whosoever will let him take the water of life freely');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 18, 'For I testify unto every man that heareth the words of the prophecy of this book, If any man shall add unto these things, God shall add unto him the plagues that are written in this book:', 'for i testify unto every man that heareth the words of the prophecy of this book if any man shall add unto these things god shall add unto him the plagues that are written in this book');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 19, 'And if any man shall take away from the words of the book of this prophecy, God shall take away his part out of the book of life, and out of the holy city, and {from} the things which are written in this book. {out of the book...: or, from the tree of life}', 'and if any man shall take away from the words of the book of this prophecy god shall take away his part out of the book of life and out of the holy city and from the things which are written in this book out of the book or from the tree of life');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 20, 'He which testifieth these things saith, Surely I come quickly. Amen. Even so, come, Lord Jesus.', 'he which testifieth these things saith surely i come quickly amen even so come lord jesus');
INSERT INTO local_bible_repository (translation_code, book_index, book_name, chapter_number, verse_number, verse_text, clean_search_tokens) VALUES ('KJV', 66, 'Unknown', 22, 21, 'The grace of our Lord Jesus Christ {be} with you all. Amen.', 'the grace of our lord jesus christ be with you all amen');
